# Human-like solver:
# 1) Each region is converted into all possible "waterline" options.
# 2) Repeated deduction:
#    - cell saturation on rows/cols (if a line already has all required water, all other candidates are dry;
#      if a line needs every possible candidate, they all become water)
#    - exact row/column sum pruning via reachable contribution totals
# 3) Only if logic stalls, branch on the most constrained region.

def solve(observation):
    region_grid = observation.get("region")
    row_targets = observation.get("row_water_counts")
    col_targets = observation.get("col_water_counts")

    if not isinstance(region_grid, list) or not region_grid:
        return "No Solution"
    if not isinstance(row_targets, list) or not isinstance(col_targets, list):
        return "No Solution"

    R = len(region_grid)
    C = len(region_grid[0]) if R else 0
    if R == 0 or C == 0:
        return "No Solution"
    if any(not isinstance(row, list) or len(row) != C for row in region_grid):
        return "No Solution"
    if len(row_targets) != R or len(col_targets) != C:
        return "No Solution"
    if any((not isinstance(x, int)) or x < 0 or x > C for x in row_targets):
        return "No Solution"
    if any((not isinstance(x, int)) or x < 0 or x > R for x in col_targets):
        return "No Solution"
    if sum(row_targets) != sum(col_targets):
        return "No Solution"

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    # Normalize region ids to dense 0..n-1.
    id_map = {}
    dense = []
    for row in region_grid:
        new_row = []
        for v in row:
            if v not in id_map:
                id_map[v] = len(id_map)
            new_row.append(id_map[v])
        dense.append(new_row)
    G = len(id_map)

    N = R * C
    idx_to_rc = [(i // C, i % C) for i in range(N)]
    row_cells = [[r * C + c for c in range(C)] for r in range(R)]
    col_cells = [[r * C + c for r in range(R)] for c in range(C)]

    cell_region = [0] * N
    region_cell_indices = [[] for _ in range(G)]
    region_rows = [set() for _ in range(G)]
    region_cols = [set() for _ in range(G)]
    region_cell_mask = [0] * G

    for r in range(R):
        for c in range(C):
            g = dense[r][c]
            idx = r * C + c
            cell_region[idx] = g
            region_cell_indices[g].append(idx)
            region_rows[g].add(r)
            region_cols[g].add(c)
            region_cell_mask[g] |= 1 << idx

    # Build all possible waterline options per region.
    option_masks = []
    option_water_counts = []
    option_row_counts = []
    option_col_counts = []
    cell_water_optionmask = []
    row_value_masks = []
    col_value_masks = []

    for g in range(G):
        rows_sorted = sorted(region_rows[g])
        masks = []
        seen = set()

        # Full down to each occupied row.
        for start_row in rows_sorted:
            m = 0
            for idx in region_cell_indices[g]:
                rr, _ = idx_to_rc[idx]
                if rr >= start_row:
                    m |= 1 << idx
            if m not in seen:
                seen.add(m)
                masks.append(m)

        # Empty option.
        if 0 not in seen:
            masks.append(0)

        option_masks.append(tuple(masks))
        option_water_counts.append(tuple(m.bit_count() for m in masks))

        row_counts_for_region = []
        col_counts_for_region = []

        row_maps = [dict() for _ in range(R)]
        col_maps = [dict() for _ in range(C)]

        for oi, m in enumerate(masks):
            rcounts = [0] * R
            ccounts = [0] * C
            mm = m
            while mm:
                lsb = mm & -mm
                idx = lsb.bit_length() - 1
                rr, cc = idx_to_rc[idx]
                rcounts[rr] += 1
                ccounts[cc] += 1
                mm ^= lsb
            rcounts = tuple(rcounts)
            ccounts = tuple(ccounts)
            row_counts_for_region.append(rcounts)
            col_counts_for_region.append(ccounts)

            for rr, v in enumerate(rcounts):
                row_maps[rr][v] = row_maps[rr].get(v, 0) | (1 << oi)
            for cc, v in enumerate(ccounts):
                col_maps[cc][v] = col_maps[cc].get(v, 0) | (1 << oi)

        option_row_counts.append(tuple(row_counts_for_region))
        option_col_counts.append(tuple(col_counts_for_region))
        row_value_masks.append(tuple(row_maps))
        col_value_masks.append(tuple(col_maps))

        water_mask_by_cell = {}
        for idx in region_cell_indices[g]:
            m = 0
            for oi, om in enumerate(masks):
                if (om >> idx) & 1:
                    m |= 1 << oi
            water_mask_by_cell[idx] = m
        cell_water_optionmask.append(water_mask_by_cell)

    all_option_masks = tuple((1 << len(option_masks[g])) - 1 for g in range(G))
    row_regions = [tuple(g for g in range(G) if r in region_rows[g]) for r in range(R)]
    col_regions = [tuple(g for g in range(G) if c in region_cols[g]) for c in range(C)]

    def prune_line(domains, regs, target, getter, line_len):
        # Exact line-sum reasoning using reachable totals.
        k = len(regs)
        limit_mask = (1 << (line_len + 1)) - 1
        prefix = [0] * (k + 1)
        prefix[0] = 1
        available = []

        for i, g in enumerate(regs):
            dom = domains[g]
            items = []
            for value, optmask in getter(g).items():
                if dom & optmask:
                    items.append((value, optmask))
            if not items:
                return None
            available.append(items)

            bits = 0
            for value, _ in items:
                bits |= prefix[i] << value
            prefix[i + 1] = bits & limit_mask

        if ((prefix[k] >> target) & 1) == 0:
            return None

        suffix = [0] * (k + 1)
        suffix[k] = 1
        for i in range(k - 1, -1, -1):
            bits = 0
            for value, _ in available[i]:
                bits |= suffix[i + 1] << value
            suffix[i] = bits & limit_mask

        changed = False
        for i, g in enumerate(regs):
            before = prefix[i]
            after = suffix[i + 1]
            allowed = 0

            for value, optmask in available[i]:
                rem = target - value
                if rem < 0:
                    continue
                bb = before
                ok = False
                while bb:
                    lsb = bb & -bb
                    s = lsb.bit_length() - 1
                    if s <= rem and ((after >> (rem - s)) & 1):
                        ok = True
                        break
                    bb ^= lsb
                if ok:
                    allowed |= optmask

            new_dom = domains[g] & allowed
            if new_dom == 0:
                return None
            if new_dom != domains[g]:
                domains[g] = new_dom
                changed = True

        return changed

    def propagate(domains):
        domains = list(domains)

        while True:
            changed = False

            for g in range(G):
                if domains[g] == 0:
                    return None

            # Determine guaranteed-water / possible-water cells from current region domains.
            status = [0] * N  # 0=dry in all options, 1=possible, 2=guaranteed water
            guaranteed_row = [0] * R
            possible_row = [0] * R
            guaranteed_col = [0] * C
            possible_col = [0] * C

            for g in range(G):
                dom = domains[g]
                union_mask = 0
                inter_mask = None

                for oi in iter_bits(dom):
                    om = option_masks[g][oi]
                    union_mask |= om
                    inter_mask = om if inter_mask is None else (inter_mask & om)

                for idx in region_cell_indices[g]:
                    bit = 1 << idx
                    rr, cc = idx_to_rc[idx]
                    if inter_mask is not None and (inter_mask & bit):
                        status[idx] = 2
                        guaranteed_row[rr] += 1
                        possible_row[rr] += 1
                        guaranteed_col[cc] += 1
                        possible_col[cc] += 1
                    elif union_mask & bit:
                        status[idx] = 1
                        possible_row[rr] += 1
                        possible_col[cc] += 1

            # Human-style saturation:
            # if target == guaranteed -> every other candidate on that line is dry
            # if target == possible   -> every possible candidate on that line is water
            forced = [0] * N  # -1 force dry, +1 force water

            def set_forced(idx, val):
                cur = forced[idx]
                if cur and cur != val:
                    return False
                forced[idx] = val
                return True

            for r in range(R):
                tgt = row_targets[r]
                if tgt < guaranteed_row[r] or tgt > possible_row[r]:
                    return None
                if tgt == guaranteed_row[r]:
                    for idx in row_cells[r]:
                        if status[idx] == 1 and not set_forced(idx, -1):
                            return None
                elif tgt == possible_row[r]:
                    for idx in row_cells[r]:
                        if status[idx] != 0 and not set_forced(idx, 1):
                            return None

            for c in range(C):
                tgt = col_targets[c]
                if tgt < guaranteed_col[c] or tgt > possible_col[c]:
                    return None
                if tgt == guaranteed_col[c]:
                    for idx in col_cells[c]:
                        if status[idx] == 1 and not set_forced(idx, -1):
                            return None
                elif tgt == possible_col[c]:
                    for idx in col_cells[c]:
                        if status[idx] != 0 and not set_forced(idx, 1):
                            return None

            for idx, val in enumerate(forced):
                if val == 0:
                    continue
                g = cell_region[idx]
                water_opts = cell_water_optionmask[g][idx]
                if val == 1:
                    if status[idx] == 0:
                        return None
                    new_dom = domains[g] & water_opts
                else:
                    if status[idx] == 2:
                        return None
                    new_dom = domains[g] & (all_option_masks[g] ^ water_opts)

                if new_dom == 0:
                    return None
                if new_dom != domains[g]:
                    domains[g] = new_dom
                    changed = True

            # Exact row reasoning.
            for r in range(R):
                res = prune_line(
                    domains,
                    row_regions[r],
                    row_targets[r],
                    lambda g, rr=r: row_value_masks[g][rr],
                    C,
                )
                if res is None:
                    return None
                if res:
                    changed = True

            # Exact column reasoning.
            for c in range(C):
                res = prune_line(
                    domains,
                    col_regions[c],
                    col_targets[c],
                    lambda g, cc=c: col_value_masks[g][cc],
                    R,
                )
                if res is None:
                    return None
                if res:
                    changed = True

            if not changed:
                return tuple(domains)

    def is_singleton(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def build_answer(domains):
        water = 0
        for g in range(G):
            if not is_singleton(domains[g]):
                return None
            oi = domains[g].bit_length() - 1
            water |= option_masks[g][oi]

        grid = []
        for r in range(R):
            row = []
            for c in range(C):
                idx = r * C + c
                row.append('W' if ((water >> idx) & 1) else None)
            grid.append(row)

        if [sum(1 for cell in row if cell == 'W') for row in grid] != row_targets:
            return None
        if [sum(1 for r in range(R) if grid[r][c] == 'W') for c in range(C)] != col_targets:
            return None

        return repr(grid)

    region_impact = [
        (len(region_cell_indices[g]), len(region_rows[g]) + len(region_cols[g]))
        for g in range(G)
    ]

    def choose_region(domains):
        best_g = None
        best_key = None
        for g in range(G):
            bc = domains[g].bit_count()
            if bc <= 1:
                continue
            size_score, line_score = region_impact[g]
            key = (bc, -size_score, -line_score, g)
            if best_key is None or key < best_key:
                best_key = key
                best_g = g
        return best_g

    dead = set()

    def search(domains, already_propagated=False):
        if not already_propagated:
            domains = propagate(domains)
            if domains is None:
                return None

        if all(is_singleton(dom) for dom in domains):
            return build_answer(domains)

        if domains in dead:
            return None

        g = choose_region(domains)
        if g is None:
            dead.add(domains)
            return None

        candidates = []
        for oi in iter_bits(domains[g]):
            trial = list(domains)
            trial[g] = 1 << oi
            pr = propagate(tuple(trial))
            if pr is not None:
                score = sum(dom.bit_count() for dom in pr)
                candidates.append((score, -option_water_counts[g][oi], pr))

        if not candidates:
            dead.add(domains)
            return None

        seen_states = set()
        candidates.sort()
        for _, _, pr in candidates:
            if pr in seen_states:
                continue
            seen_states.add(pr)
            ans = search(pr, already_propagated=True)
            if ans is not None:
                return ans

        dead.add(domains)
        return None

    initial_domains = tuple(all_option_masks)
    answer = search(initial_domains)
    return answer if answer is not None else "No Solution"


