            row_vals.append(rv)
            col_vals.append(cv)
            totals.append(tot)

        option_water_bits.append(tuple(water_bits))
        option_row_vals.append(tuple(row_vals))
        option_col_vals.append(tuple(col_vals))
        option_totals.append(tuple(totals))

    row_line_data = []
    for r in range(rows):
        line = []
        for g in sorted(row_to_regions[r]):
            vals = tuple(option_row_vals[g][o][r] for o in range(len(option_row_vals[g])))
            line.append((g, vals))
        row_line_data.append(tuple(line))

    col_line_data = []
    for c in range(cols):
        line = []
        for g in sorted(col_to_regions[c]):
            vals = tuple(option_col_vals[g][o][c] for o in range(len(option_col_vals[g])))
            line.append((g, vals))
        col_line_data.append(tuple(line))

    full_domain = [(1 << len(option_water_bits[g])) - 1 for g in range(region_count)]

    def bit_indices(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def line_prune(line_data, target, limit, domains):
        # Exact reachable-sum pruning for one row/column.
        m = len(line_data)
        limit_mask = (1 << (limit + 1)) - 1

        pref = [0] * (m + 1)
        pref[0] = 1

        for i, (g, vals) in enumerate(line_data):
            bits = 0
            seen = set()
            mask = domains[g]
            for o in bit_indices(mask):
                v = vals[o]
                if v not in seen:
                    bits |= pref[i] << v
                    seen.add(v)
            bits &= limit_mask
            if bits == 0:
                return False, ()
            pref[i + 1] = bits

        if target > limit or ((pref[m] >> target) & 1) == 0:
            return False, ()

        suff = [0] * (m + 1)
        suff[m] = 1
        for i in range(m - 1, -1, -1):
            g, vals = line_data[i]
            bits = 0
            seen = set()
            mask = domains[g]
            for o in bit_indices(mask):
                v = vals[o]
                if v not in seen:
                    bits |= suff[i + 1] << v
                    seen.add(v)
            bits &= limit_mask
            if bits == 0:
                return False, ()
            suff[i] = bits

        changed = []
        for i, (g, vals) in enumerate(line_data):
            old_mask = domains[g]
            new_mask = 0
            pb = pref[i]
            sb = suff[i + 1]

            for o in bit_indices(old_mask):
                need = target - vals[o]
                if need < 0 or need > limit:
                    continue

                ok = False
                candidate_prefix = pb & ((1 << (need + 1)) - 1)
                while candidate_prefix:
                    a_lsb = candidate_prefix & -candidate_prefix
                    a = a_lsb.bit_length() - 1
                    if ((sb >> (need - a)) & 1) != 0:
                        ok = True
                        break
                    candidate_prefix ^= a_lsb

                if ok:
                    new_mask |= 1 << o

            if new_mask == 0:
                return False, ()
            if new_mask != old_mask:
                domains[g] = new_mask
                changed.append(g)

        return True, tuple(changed)

    def propagate(domains):
        q = deque()
        in_q = set()

        for r in range(rows):
            key = ("r", r)
            q.append(key)
            in_q.add(key)
        for c in range(cols):
            key = ("c", c)
            q.append(key)
            in_q.add(key)

        while q:
            kind, idx = q.popleft()
            in_q.discard((kind, idx))

            if kind == "r":
                ok, changed_regions = line_prune(row_line_data[idx], row_targets[idx], cols, domains)
            else:
                ok, changed_regions = line_prune(col_line_data[idx], col_targets[idx], rows, domains)

            if not ok:
                return False

            for g in changed_regions:
                for rr in region_rows[g]:
                    key = ("r", rr)
                    if key not in in_q:
                        q.append(key)
                        in_q.add(key)
                for cc in region_cols[g]:
                    key = ("c", cc)
                    if key not in in_q:
                        q.append(key)
                        in_q.add(key)

        return True

    def is_solved(domains):
        return all(mask and (mask & (mask - 1)) == 0 for mask in domains)

    def choose_region(domains):
        best = None
        best_key = None
        for g, mask in enumerate(domains):
            count = mask.bit_count()
            if count <= 1:
                continue
            # Fail-first: smallest domain. Tie-break by larger, more influential region.
            influence = len(region_cells[g]) + len(region_rows[g]) + len(region_cols[g])
            key = (count, -influence, -len(region_cells[g]), g)
            if best_key is None or key < best_key:
                best_key = key
                best = g
        return best

    def ordered_options(g, mask):
        expected = global_density * len(region_cells[g])
        opts = list(bit_indices(mask))
        # Branch near the expected amount first.
        opts.sort(key=lambda o: (abs(option_totals[g][o] - expected), option_totals[g][o]))
        return opts

    def search(domains):
        if not propagate(domains):
            return None
        if is_solved(domains):
            return domains

        g = choose_region(domains)
        if g is None:
            return domains

        for o in ordered_options(g, domains[g]):
            new_domains = domains[:]
            new_domains[g] = 1 << o
            result = search(new_domains)
            if result is not None:
                return result
        return None

    solved = search(full_domain[:])
    if solved is None:
        return "No Solution"

    answer = [[None] * cols for _ in range(rows)]
    for g, mask in enumerate(solved):
        o = (mask & -mask).bit_length() - 1
        bits = option_water_bits[g][o]
        while bits:
            lsb = bits & -bits
            idx = lsb.bit_length() - 1
            answer[idx // cols][idx % cols] = 'W'
            bits ^= lsb

    return repr(answer)


