# General Aquarium solver.
# It models each region as choosing one waterline state:
# empty, or filled from some region-row downward.
# Then it performs aggressive propagation using:
# - row/column min-max bounds
# - exact-min / exact-max line deductions
# - per-state feasibility filtering
# - forced-cell deductions from row/column completion
# Search is only used after propagation stalls.

import sys

sys.setrecursionlimit(10000)


def solve(observation):
    region_grid = observation["region"]
    row_clues = observation["row_water_counts"]
    col_clues = observation["col_water_counts"]

    if not region_grid or not region_grid[0]:
        return "No Solution"

    R = len(region_grid)
    C = len(region_grid[0])

    if len(row_clues) != R or len(col_clues) != C:
        return "No Solution"

    total_row = sum(row_clues)
    total_col = sum(col_clues)
    if total_row != total_col:
        return "No Solution"

    # Build regions.
    id_to_cells = {}
    for r in range(R):
        if len(region_grid[r]) != C:
            return "No Solution"
        for c in range(C):
            rid = region_grid[r][c]
            idx = r * C + c
            id_to_cells.setdefault(rid, []).append((idx, r, c))

    region_ids = sorted(id_to_cells)
    rid_to_g = {rid: g for g, rid in enumerate(region_ids)}
    G = len(region_ids)

    row_cells = [[] for _ in range(R)]
    col_cells = [[] for _ in range(C)]
    cell_region = [None] * (R * C)

    regions = []
    row_regions = [[] for _ in range(R)]
    col_regions = [[] for _ in range(C)]

    for g, rid in enumerate(region_ids):
        cells = id_to_cells[rid]
        rows = sorted({r for _, r, _ in cells})
        cols = sorted({c for _, _, c in cells})

        row_pos = {r: i for i, r in enumerate(rows)}
        col_pos = {c: i for i, c in enumerate(cols)}

        all_cells_mask = 0
        for idx, r, c in cells:
            all_cells_mask |= 1 << idx
            row_cells[r].append(idx)
            col_cells[c].append(idx)
            cell_region[idx] = g

        # States ordered by increasing water amount:
        # 0 = empty, then bottommost row level, then next higher level, ..., full.
        state_masks = []
        state_row = []
        state_col = []
        state_total = []

        # Empty
        state_masks.append(0)
        state_row.append(tuple(0 for _ in rows))
        state_col.append(tuple(0 for _ in cols))
        state_total.append(0)

        for k in range(1, len(rows) + 1):
            cutoff = rows[-k]
            mask = 0
            rcnt = [0] * len(rows)
            ccnt = [0] * len(cols)
            total = 0
            for idx, r, c in cells:
                if r >= cutoff:
                    mask |= 1 << idx
                    rcnt[row_pos[r]] += 1
                    ccnt[col_pos[c]] += 1
                    total += 1
            state_masks.append(mask)
            state_row.append(tuple(rcnt))
            state_col.append(tuple(ccnt))
            state_total.append(total)

        all_state_mask = (1 << len(state_masks)) - 1

        cell_to_state_mask = {}
        for idx, _, _ in cells:
            sm = 0
            bit = 1 << idx
            for s, mask in enumerate(state_masks):
                if mask & bit:
                    sm |= 1 << s
            cell_to_state_mask[idx] = sm

        reg = {
            "rid": rid,
            "cells": cells,
            "rows": rows,
            "cols": cols,
            "row_pos": row_pos,
            "col_pos": col_pos,
            "state_masks": tuple(state_masks),
            "state_row": tuple(state_row),
            "state_col": tuple(state_col),
            "state_total": tuple(state_total),
            "all_cells_mask": all_cells_mask,
            "all_state_mask": all_state_mask,
            "cell_to_state_mask": cell_to_state_mask,
            "impact": len(cells) * (len(rows) + len(cols)),
            "cache": {},
        }
        regions.append(reg)

        for r in rows:
            row_regions[r].append(g)
        for c in cols:
            col_regions[c].append(g)

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def single_bit_index(mask):
        return (mask & -mask).bit_length() - 1

    def get_stats(g, domain_mask):
        reg = regions[g]
        cache = reg["cache"]
        if domain_mask in cache:
            return cache[domain_mask]

        if domain_mask == 0:
            return None

        rows = reg["rows"]
        cols = reg["cols"]
        row_min = [10**9] * len(rows)
        row_max = [-1] * len(rows)
        col_min = [10**9] * len(cols)
        col_max = [-1] * len(cols)

        certain = reg["all_cells_mask"]
        possible = 0

        for s in bit_iter(domain_mask):
            sm = reg["state_masks"][s]
            certain &= sm
            possible |= sm

            sr = reg["state_row"][s]
            sc = reg["state_col"][s]
            for i, v in enumerate(sr):
                if v < row_min[i]:
                    row_min[i] = v
                if v > row_max[i]:
                    row_max[i] = v
            for i, v in enumerate(sc):
                if v < col_min[i]:
                    col_min[i] = v
                if v > col_max[i]:
                    col_max[i] = v

        res = (
            tuple(row_min),
            tuple(row_max),
            tuple(col_min),
            tuple(col_max),
            certain,
            possible,
        )
        cache[domain_mask] = res
        return res

    def compute_global_info(domains):
        stats = [get_stats(g, domains[g]) for g in range(G)]

        row_min = [0] * R
        row_max = [0] * R
        col_min = [0] * C
        col_max = [0] * C

        fixed_row = [0] * R
        maybe_row = [0] * R
        fixed_col = [0] * C
        maybe_col = [0] * C

        fixed_total = 0
        possible_total = 0

        for g, reg in enumerate(regions):
            st = stats[g]
            if st is None:
                return None
            rmin, rmax, cmin, cmax, certain, possible = st

            for i, r in enumerate(reg["rows"]):
                row_min[r] += rmin[i]
                row_max[r] += rmax[i]
            for i, c in enumerate(reg["cols"]):
                col_min[c] += cmin[i]
                col_max[c] += cmax[i]

            for idx, r, c in reg["cells"]:
                bit = 1 << idx
                if certain & bit:
                    fixed_row[r] += 1
                    fixed_col[c] += 1
                    fixed_total += 1
                elif possible & bit:
                    maybe_row[r] += 1
                    maybe_col[c] += 1
                    possible_total += 1

        return {
            "stats": stats,
            "row_min": row_min,
            "row_max": row_max,
            "col_min": col_min,
            "col_max": col_max,
            "fixed_row": fixed_row,
            "maybe_row": maybe_row,
            "fixed_col": fixed_col,
            "maybe_col": maybe_col,
            "fixed_total": fixed_total,
            "possible_total": possible_total,
        }

    def prune_by_line_extremes(domains, info):
        # If a line is already at its minimum or maximum possible water count,
        # every touching region must realize its local minimum/maximum on that line.
        new_domains = list(domains)
        changed = False

        stats = info["stats"]
        row_min = info["row_min"]
        row_max = info["row_max"]
        col_min = info["col_min"]
        col_max = info["col_max"]

        # Rows
        for r in range(R):
            clue = row_clues[r]
            if clue == row_min[r]:
                for g in row_regions[r]:
                    reg = regions[g]
                    local = reg["row_pos"][r]
                    target = stats[g][0][local]
                    keep = 0
                    dm = new_domains[g]
                    for s in bit_iter(dm):
                        if reg["state_row"][s][local] == target:
                            keep |= 1 << s
                    if keep == 0:
                        return None
                    if keep != new_domains[g]:
                        new_domains[g] = keep
                        changed = True
            elif clue == row_max[r]:
                for g in row_regions[r]:
                    reg = regions[g]
                    local = reg["row_pos"][r]
                    target = stats[g][1][local]
                    keep = 0
                    dm = new_domains[g]
                    for s in bit_iter(dm):
                        if reg["state_row"][s][local] == target:
                            keep |= 1 << s
                    if keep == 0:
                        return None
                    if keep != new_domains[g]:
                        new_domains[g] = keep
                        changed = True

        # Cols
        for c in range(C):
            clue = col_clues[c]
            if clue == col_min[c]:
                for g in col_regions[c]:
                    reg = regions[g]
                    local = reg["col_pos"][c]
                    target = stats[g][2][local]
                    keep = 0
                    dm = new_domains[g]
                    for s in bit_iter(dm):
                        if reg["state_col"][s][local] == target:
                            keep |= 1 << s
                    if keep == 0:
                        return None
                    if keep != new_domains[g]:
                        new_domains[g] = keep
                        changed = True
            elif clue == col_max[c]:
                for g in col_regions[c]:
                    reg = regions[g]
                    local = reg["col_pos"][c]
                    target = stats[g][3][local]
                    keep = 0
                    dm = new_domains[g]
                    for s in bit_iter(dm):
                        if reg["state_col"][s][local] == target:
                            keep |= 1 << s
                    if keep == 0:
                        return None
                    if keep != new_domains[g]:
                        new_domains[g] = keep
                        changed = True

        if changed:
            return tuple(new_domains)
        return domains

    def prune_infeasible_states(domains, info):
        # For each region-state, require that all touched rows/cols
        # can still hit their clues with the other regions.
        new_domains = list(domains)
        changed = False

        row_min = info["row_min"]
        row_max = info["row_max"]
        col_min = info["col_min"]
        col_max = info["col_max"]
        stats = info["stats"]

        for g, reg in enumerate(regions):
            dm = domains[g]
            if dm == 0:
                return None
            if dm & (dm - 1) == 0:
                continue

            rmin, rmax, cmin, cmax, _, _ = stats[g]
            keep = 0

            for s in bit_iter(dm):
                ok = True

                sr = reg["state_row"][s]
                for i, r in enumerate(reg["rows"]):
                    need_other = row_clues[r] - sr[i]
                    if need_other < row_min[r] - rmin[i] or need_other > row_max[r] - rmax[i]:
                        ok = False
                        break
                if not ok:
                    continue

                sc = reg["state_col"][s]
                for i, c in enumerate(reg["cols"]):
                    need_other = col_clues[c] - sc[i]
                    if need_other < col_min[c] - cmin[i] or need_other > col_max[c] - cmax[i]:
                        ok = False
                        break

                if ok:
                    keep |= 1 << s

            if keep == 0:
                return None
            if keep != dm:
                new_domains[g] = keep
                changed = True

        if changed:
            return tuple(new_domains)
        return domains

    def force_cells(domains, info):
        # If a row/col is already complete or every undecided cell there must be water,
        # convert that into region-state pruning.
        forced_water = set()
        forced_dry = set()

        stats = info["stats"]
        fixed_row = info["fixed_row"]
        maybe_row = info["maybe_row"]
        fixed_col = info["fixed_col"]
        maybe_col = info["maybe_col"]

        # Row-based forces.
        for r in range(R):
            clue = row_clues[r]
            if clue < fixed_row[r] or clue > fixed_row[r] + maybe_row[r]:
                return None
            if clue == fixed_row[r]:
                for idx in row_cells[r]:
                    g = cell_region[idx]
                    bit = 1 << idx
                    certain = stats[g][4]
                    possible = stats[g][5]
                    if not (certain & bit) and (possible & bit):
                        forced_dry.add(idx)
            elif clue == fixed_row[r] + maybe_row[r]:
                for idx in row_cells[r]:
                    g = cell_region[idx]
                    bit = 1 << idx
                    certain = stats[g][4]
                    possible = stats[g][5]
                    if not (certain & bit) and (possible & bit):
                        forced_water.add(idx)

        # Col-based forces.
        for c in range(C):
            clue = col_clues[c]
            if clue < fixed_col[c] or clue > fixed_col[c] + maybe_col[c]:
                return None
            if clue == fixed_col[c]:
                for idx in col_cells[c]:
                    g = cell_region[idx]
                    bit = 1 << idx
                    certain = stats[g][4]
                    possible = stats[g][5]
                    if not (certain & bit) and (possible & bit):
                        forced_dry.add(idx)
            elif clue == fixed_col[c] + maybe_col[c]:
