    def propagate(domains):
        domains = tuple(domains)
        while True:
            info = compute_global_info(domains)
            if info is None:
                return None

            row_min = info["row_min"]
            row_max = info["row_max"]
            col_min = info["col_min"]
            col_max = info["col_max"]
            fixed_row = info["fixed_row"]
            maybe_row = info["maybe_row"]
            fixed_col = info["fixed_col"]
            maybe_col = info["maybe_col"]

            # Global consistency checks.
            if info["fixed_total"] > total_row or info["fixed_total"] + info["possible_total"] < total_row:
                return None

            for r in range(R):
                if row_clues[r] < row_min[r] or row_clues[r] > row_max[r]:
                    return None
                if row_clues[r] < fixed_row[r] or row_clues[r] > fixed_row[r] + maybe_row[r]:
                    return None

            for c in range(C):
                if col_clues[c] < col_min[c] or col_clues[c] > col_max[c]:
                    return None
                if col_clues[c] < fixed_col[c] or col_clues[c] > fixed_col[c] + maybe_col[c]:
                    return None

            nd = prune_by_line_extremes(domains, info)
            if nd is None:
                return None
            if nd != domains:
                domains = nd
                continue

            nd = prune_infeasible_states(domains, info)
            if nd is None:
                return None
            if nd != domains:
                domains = nd
                continue

            nd = force_cells(domains, info)
            if nd is None:
                return None
            if nd != domains:
                domains = nd
                continue

            return domains

    def build_grid(domains):
        grid = [[None for _ in range(C)] for _ in range(R)]
        for g, reg in enumerate(regions):
            dm = domains[g]
            if dm == 0 or (dm & (dm - 1)) != 0:
                return None
            s = single_bit_index(dm)
            mask = reg["state_masks"][s]
            for idx, r, c in reg["cells"]:
                if mask & (1 << idx):
                    grid[r][c] = "W"
        return grid

    def valid_complete(grid):
        if grid is None:
            return False
        for r in range(R):
            if sum(1 for c in range(C) if grid[r][c] == "W") != row_clues[r]:
                return False
        for c in range(C):
            if sum(1 for r in range(R) if grid[r][c] == "W") != col_clues[c]:
                return False
        return True

    density_target = total_row * 1.0 / (R * C)
    dead = set()

    def choose_region(domains):
        best_g = None
        best_key = None
        for g, dm in enumerate(domains):
            cnt = dm.bit_count()
            if cnt <= 1:
                continue
            reg = regions[g]
            key = (cnt, -reg["impact"], -len(reg["cells"]))
            if best_key is None or key < best_key:
                best_key = key
                best_g = g
        return best_g

    def ordered_states(g, domains):
        reg = regions[g]
        dm = domains[g]
        target = density_target * len(reg["cells"])
        states = list(bit_iter(dm))
        states.sort(key=lambda s: (abs(reg["state_total"][s] - target), reg["state_total"][s]))
        return states

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if domains in dead:
            return None

        solved = True
        for dm in domains:
            if dm & (dm - 1):
