            if nd is None:
                return None
            if nd != domains:
                domains = nd
                continue

            nd = prune_infeasible_states(domains, info)
            if nd is None:
                return None
            if nd != domains:
                domains = nd
                continue

            nd = force_cells(domains, info)
            if nd is None:
                return None
            if nd != domains:
                domains = nd
                continue

            return domains

    def build_grid(domains):
        grid = [[None for _ in range(C)] for _ in range(R)]
