            dm = domains[g]
            if dm == 0 or (dm & (dm - 1)) != 0:
                return None
            s = single_bit_index(dm)
            mask = reg["state_masks"][s]
            for idx, r, c in reg["cells"]:
                if mask & (1 << idx):
                    grid[r][c] = "W"
        return grid

    def valid_complete(grid):
        if grid is None:
            return False
        for r in range(R):
            if sum(1 for c in range(C) if grid[r][c] == "W") != row_clues[r]:
                return False
        for c in range(C):
            if sum(1 for r in range(R) if grid[r][c] == "W") != col_clues[c]:
                return False
        return True

    density_target = total_row * 1.0 / (R * C)
    dead = set()

    def choose_region(domains):
        best_g = None
        best_key = None
        for g, dm in enumerate(domains):
            cnt = dm.bit_count()
            if cnt <= 1:
                continue
            reg = regions[g]
            key = (cnt, -reg["impact"], -len(reg["cells"]))
            if best_key is None or key < best_key:
                best_key = key
                best_g = g
        return best_g

    def ordered_states(g, domains):
        reg = regions[g]
        dm = domains[g]
        target = density_target * len(reg["cells"])
        states = list(bit_iter(dm))
        states.sort(key=lambda s: (abs(reg["state_total"][s] - target), reg["state_total"][s]))
        return states

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if domains in dead:
            return None

        solved = True
        for dm in domains:
            if dm & (dm - 1):
                solved = False
                break

        if solved:
            grid = build_grid(domains)
            if valid_complete(grid):
                return grid
            dead.add(domains)
            return None

        g = choose_region(domains)
        if g is None:
            dead.add(domains)
            return None

        for s in ordered_states(g, domains):
            new_domains = list(domains)
            new_domains[g] = 1 << s
            ans = dfs(tuple(new_domains))
            if ans is not None:
                return ans

        dead.add(domains)
        return None

    initial_domains = tuple(reg["all_state_mask"] for reg in regions)
    answer = dfs(initial_domains)
    if answer is None:
        return "No Solution"
    return str(answer)


