B = 1
W = 0
U = -1


def popcount(x):
    try:
        return x.bit_count()
    except AttributeError:
        return bin(x).count("1")


def generate_valid_patterns(n):
    half = n // 2
    patterns = []

    def rec(pos, ones, zeros, last2, last1, pattern):
        remaining = n - pos
        if ones > half or zeros > half:
            return
        if ones + remaining < half or zeros + remaining < half:
            return
        if pos == n:
            if ones == half and zeros == half:
                patterns.append(pattern)
            return
        for val in (W, B):
            if val == B and ones >= half:
                continue
            if val == W and zeros >= half:
                continue
            if last2 != U and last1 != U and last2 == last1 == val:
                continue
            rec(
                pos + 1,
                ones + (1 if val == B else 0),
                zeros + (1 if val == W else 0),
                last1,
                val,
                pattern | (val << pos),
            )

    rec(0, 0, 0, U, U, 0)
    return patterns


class TakuzuSolver:
    def __init__(self, grid):
        self.n = len(grid)
        self.half = self.n // 2
        self.patterns = generate_valid_patterns(self.n)
        self.m = len(self.patterns)
        self.fullmask = (1 << self.m) - 1 if self.m else 0

        self.Bmask = [0] * self.n
        self.Wmask = [0] * self.n
        for i, pattern in enumerate(self.patterns):
            bit = 1 << i
            for pos in range(self.n):
                if (pattern >> pos) & 1:
                    self.Bmask[pos] |= bit
                else:
                    self.Wmask[pos] |= bit

        self.row_coords = [[(r, c) for c in range(self.n)] for r in range(self.n)]
        self.col_coords = [[(r, c) for r in range(self.n)] for c in range(self.n)]
        self.mask_cache = {}
        self.memo = set()

        self.initial_grid = [row[:] for row in grid]
        self.initial_row_masks = []
        self.initial_col_masks = []
        self.valid_init = True

        for r in range(self.n):
            mask = self.line_mask_from_assignment(tuple(self.initial_grid[r]))
            if mask == 0:
                self.valid_init = False
            self.initial_row_masks.append(mask)

        for c in range(self.n):
            col = tuple(self.initial_grid[r][c] for r in range(self.n))
            mask = self.line_mask_from_assignment(col)
            if mask == 0:
