    def line_mask_from_assignment(self, vals):
        key = vals if isinstance(vals, tuple) else tuple(vals)
        cached = self.mask_cache.get(key)
        if cached is not None:
            return cached
        mask = self.fullmask
        for pos, val in enumerate(key):
