                res = self.set_cell(grid, rr, cc, val)
                if res < 0:
                    return -1
                if res:
                    vals[i] = val
                    changed = True

            if a != U and a == c and b == U:
                val = 1 - a
                rr, cc = coords[i + 1]
                res = self.set_cell(grid, rr, cc, val)
                if res < 0:
                    return -1
                if res:
                    vals[i + 1] = val
                    changed = True

        bcnt = vals.count(B)
        wcnt = vals.count(W)
        if bcnt > self.half or wcnt > self.half:
            return -1

        if bcnt == self.half:
            for i, v in enumerate(vals):
                if v == U:
                    rr, cc = coords[i]
                    res = self.set_cell(grid, rr, cc, W)
                    if res < 0:
                        return -1
                    if res:
                        vals[i] = W
                        changed = True
        elif wcnt == self.half:
            for i, v in enumerate(vals):
                if v == U:
                    rr, cc = coords[i]
                    res = self.set_cell(grid, rr, cc, B)
                    if res < 0:
                        return -1
                    if res:
                        vals[i] = B
                        changed = True

        return 1 if changed else 0

    def filter_masks_from_grid(self, grid, row_masks, col_masks):
        changed = False

        for r in range(self.n):
            newmask = row_masks[r] & self.line_mask_from_assignment(tuple(grid[r]))
            if newmask == 0:
                return -1
            if newmask != row_masks[r]:
                row_masks[r] = newmask
                changed = True

        for c in range(self.n):
            col = tuple(grid[r][c] for r in range(self.n))
            newmask = col_masks[c] & self.line_mask_from_assignment(col)
            if newmask == 0:
                return -1
            if newmask != col_masks[c]:
                col_masks[c] = newmask
                changed = True

        return 1 if changed else 0

    def cross_filter_rows(self, grid, row_masks, col_masks):
        changed = False
        for r in range(self.n):
            cur = row_masks[r]
            newmask = cur
            for c in range(self.n):
                if grid[r][c] != U:
                    continue
                allowed = 0
                if col_masks[c] & self.Wmask[r]:
                    allowed |= self.Wmask[c]
                if col_masks[c] & self.Bmask[r]:
                    allowed |= self.Bmask[c]
                newmask &= allowed
                if newmask == 0:
                    return -1
            if newmask != cur:
                row_masks[r] = newmask
                changed = True
        return 1 if changed else 0

    def cross_filter_cols(self, grid, row_masks, col_masks):
        changed = False
        for c in range(self.n):
            cur = col_masks[c]
            newmask = cur
            for r in range(self.n):
                if grid[r][c] != U:
                    continue
                allowed = 0
                if row_masks[r] & self.Wmask[c]:
                    allowed |= self.Wmask[r]
                if row_masks[r] & self.Bmask[c]:
                    allowed |= self.Bmask[r]
                newmask &= allowed
                if newmask == 0:
                    return -1
            if newmask != cur:
                col_masks[c] = newmask
                changed = True
        return 1 if changed else 0

    def apply_singleton_exclusion(self, masks):
        singles = 0
        for m in masks:
            if m != 0 and (m & (m - 1)) == 0:
                if singles & m:
                    return False, False
                singles |= m

        if singles == 0:
            return True, False

        for i, m in enumerate(masks):
            if m != 0 and (m & (m - 1)) != 0:
                newmask = m & ~singles
                if newmask == 0:
                    return False, False
                if newmask != m:
                    masks[i] = newmask
                    return True, True

        return True, False

    def apply_naked_subsets(self, masks, max_k=4):
        unresolved = [i for i, m in enumerate(masks) if popcount(m) > 1]
        limit = min(max_k, len(unresolved))
        for k in range(2, limit + 1):
            for combo in combinations(unresolved, k):
                union = 0
                for idx in combo:
                    union |= masks[idx]
                if popcount(union) != k:
                    continue
                subset_idxs = [i for i in unresolved if (masks[i] & ~union) == 0]
                if len(subset_idxs) > k:
                    return False, False
                if len(subset_idxs) == k:
                    subset_set = set(subset_idxs)
                    for j, m in enumerate(masks):
                        if j not in subset_set and (m & union):
                            newmask = m & ~union
                            if newmask == 0:
                                return False, False
                            if newmask != m:
                                masks[j] = newmask
                                return True, True
        return True, False

    def apply_all_different_reductions(self, masks):
        ok, changed = self.apply_singleton_exclusion(masks)
        if not ok or changed:
            return ok, changed
        ok, changed = self.apply_naked_subsets(masks)
        return ok, changed

    def apply_mask_forces(self, grid, row_masks, col_masks):
        changed = False

        for r, mask in enumerate(row_masks):
            if mask != 0 and (mask & (mask - 1)) == 0:
                pattern = self.patterns[mask.bit_length() - 1]
                res = self.assign_row_pattern(grid, r, pattern)
                if res < 0:
                    return -1
                if res:
                    changed = True

        for c, mask in enumerate(col_masks):
            if mask != 0 and (mask & (mask - 1)) == 0:
                pattern = self.patterns[mask.bit_length() - 1]
                res = self.assign_col_pattern(grid, c, pattern)
                if res < 0:
                    return -1
                if res:
                    changed = True

        for r in range(self.n):
            for c in range(self.n):
                if grid[r][c] != U:
                    continue

                row_b = bool(row_masks[r] & self.Bmask[c])
                row_w = bool(row_masks[r] & self.Wmask[c])
                col_b = bool(col_masks[c] & self.Bmask[r])
                col_w = bool(col_masks[c] & self.Wmask[r])

                allow_b = row_b and col_b
                allow_w = row_w and col_w

                if not allow_b and not allow_w:
                    return -1
                if allow_b and not allow_w:
                    res = self.set_cell(grid, r, c, B)
                    if res < 0:
                        return -1
                    if res:
                        changed = True
                elif allow_w and not allow_b:
                    res = self.set_cell(grid, r, c, W)
                    if res < 0:
                        return -1
                    if res:
                        changed = True

        return 1 if changed else 0

    def propagate(self, grid, row_masks, col_masks):
        while True:
            changed = False

            for coords in self.row_coords:
                res = self.apply_basic_rules_to_coords(grid, coords)
                if res < 0:
                    return None
                if res:
                    changed = True

            for coords in self.col_coords:
                res = self.apply_basic_rules_to_coords(grid, coords)
                if res < 0:
                    return None
                if res:
                    changed = True

            res = self.filter_masks_from_grid(grid, row_masks, col_masks)
            if res < 0:
                return None
            if res:
                changed = True

            res = self.cross_filter_rows(grid, row_masks, col_masks)
            if res < 0:
                return None
            if res:
                changed = True

            res = self.cross_filter_cols(grid, row_masks, col_masks)
            if res < 0:
                return None
            if res:
                changed = True

            ok, res = self.apply_all_different_reductions(row_masks)
            if not ok:
                return None
            if res:
                changed = True

            ok, res = self.apply_all_different_reductions(col_masks)
            if not ok:
                return None
            if res:
                changed = True

            res = self.apply_mask_forces(grid, row_masks, col_masks)
            if res < 0:
                return None
            if res:
                changed = True

            if not changed:
                break

        return grid, row_masks, col_masks

    def is_solved(self, grid):
        for row in grid:
            if U in row:
                return False

        if len({tuple(row) for row in grid}) != self.n:
            return False

        cols = {tuple(grid[r][c] for r in range(self.n)) for c in range(self.n)}
        if len(cols) != self.n:
            return False

        return True

    def iter_bits(self, mask):
        while mask:
            bit = mask & -mask
            yield bit
            mask ^= bit

    def order_line_candidates(self, kind, idx, mask, row_masks, col_masks):
        bits = list(self.iter_bits(mask))

        def score(bit):
            pattern = self.patterns[bit.bit_length() - 1]
            total = 0
            if kind == "row":
                r = idx
                for c in range(self.n):
                    if (pattern >> c) & 1:
                        total += popcount(col_masks[c] & self.Bmask[r])
                    else:
                        total += popcount(col_masks[c] & self.Wmask[r])
            else:
                c = idx
                for r in range(self.n):
                    if (pattern >> r) & 1:
                        total += popcount(row_masks[r] & self.Bmask[c])
                    else:
                        total += popcount(row_masks[r] & self.Wmask[c])
            return total

        bits.sort(key=score)
        return bits

    def choose_branch(self, grid, row_masks, col_masks):
        best_line = None
        best_line_key = None

        for r, mask in enumerate(row_masks):
            cnt = popcount(mask)
            if cnt > 1:
                unknowns = sum(1 for c in range(self.n) if grid[r][c] == U)
                key = (cnt, unknowns)
                if best_line_key is None or key < best_line_key:
                    best_line_key = key
                    best_line = ("row", r, self.order_line_candidates("row", r, mask, row_masks, col_masks), cnt)

        for c, mask in enumerate(col_masks):
            cnt = popcount(mask)
            if cnt > 1:
                unknowns = sum(1 for r in range(self.n) if grid[r][c] == U)
                key = (cnt, unknowns)
                if best_line_key is None or key < best_line_key:
                    best_line_key = key
                    best_line = ("col", c, self.order_line_candidates("col", c, mask, row_masks, col_masks), cnt)

        best_cell = None
        best_cell_key = None

        for r in range(self.n):
            for c in range(self.n):
                if grid[r][c] != U:
                    continue
                b_support = popcount(row_masks[r] & self.Bmask[c]) * popcount(col_masks[c] & self.Bmask[r])
                w_support = popcount(row_masks[r] & self.Wmask[c]) * popcount(col_masks[c] & self.Wmask[r])

                if b_support == 0 and w_support == 0:
                    return None

                total = b_support + w_support
                imbalance = abs(b_support - w_support)
                line_product = popcount(row_masks[r]) * popcount(col_masks[c])
                key = (total, -imbalance, line_product)

                if best_cell_key is None or key < best_cell_key:
                    best_cell_key = key
                    if b_support < w_support:
                        order = [B, W]
                    else:
                        order = [W, B]
                    best_cell = ("cell", (r, c), order)

        if best_cell is not None and (best_line is None or best_line[3] > 2):
            return best_cell
        if best_line is not None:
            return best_line[:3]
        return None

    def search(self, grid, row_masks, col_masks):
        state = self.propagate(grid, row_masks, col_masks)
        if state is None:
            return None

        grid, row_masks, col_masks = state

        if self.is_solved(grid):
            return grid

        key = (tuple(tuple(row) for row in grid), tuple(row_masks), tuple(col_masks))
        if key in self.memo:
            return None
        self.memo.add(key)

        branch = self.choose_branch(grid, row_masks, col_masks)
        if branch is None:
            return None

        kind = branch[0]

        if kind == "cell":
            (_, (r, c), values) = branch
            for val in values:
                new_grid = [row[:] for row in grid]
                new_row_masks = row_masks[:]
                new_col_masks = col_masks[:]
                res = self.set_cell(new_grid, r, c, val)
                if res < 0:
                    continue
                ans = self.search(new_grid, new_row_masks, new_col_masks)
                if ans is not None:
                    return ans
            return None

        _, idx, bits = branch
        for bit in bits:
            pattern = self.patterns[bit.bit_length() - 1]
            new_grid = [row[:] for row in grid]
            new_row_masks = row_masks[:]
            new_col_masks = col_masks[:]

            if kind == "row":
                new_row_masks[idx] = bit
                res = self.assign_row_pattern(new_grid, idx, pattern)
            else:
                new_col_masks[idx] = bit
                res = self.assign_col_pattern(new_grid, idx, pattern)

            if res < 0:
                continue

            ans = self.search(new_grid, new_row_masks, new_col_masks)
            if ans is not None:
                return ans

        return None

    def run(self):
        if not self.valid_init:
            return None
        grid = [row[:] for row in self.initial_grid]
        row_masks = self.initial_row_masks[:]
        col_masks = self.initial_col_masks[:]
        return self.search(grid, row_masks, col_masks)


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data:
        return "No Solution"

    n = len(data)
    if n % 2 != 0:
        return "No Solution"

    grid = []
    for row in data:
        if not isinstance(row, list) or len(row) != n:
            return "No Solution"
        parsed = []
        for cell in row:
            if cell is None:
                parsed.append(U)
            elif cell == "B":
                parsed.append(B)
            elif cell == "W":
                parsed.append(W)
            else:
                return "No Solution"
        grid.append(parsed)

    solver = TakuzuSolver(grid)
    solved = solver.run()
    if solved is None:
        return "No Solution"

    return [[("B" if v == B else "W") for v in row] for row in solved]


