        for i in range(self.n - 2):
            a, b, c = vals[i], vals[i + 1], vals[i + 2]
            if a != U and a == b == c:
                return -1

            if a != U and a == b and c == U:
                val = 1 - a
                rr, cc = coords[i + 2]
