                newmask &= allowed
                if newmask == 0:
                    return -1
            if newmask != cur:
                col_masks[c] = newmask
                changed = True
        return 1 if changed else 0

    def apply_singleton_exclusion(self, masks):
        singles = 0
        for m in masks:
