def generate_patterns(length):
    half = length // 2
    patterns = []
    bits_map = {}
    prefix = [0] * length

    def rec(pos, ones):
        zeros = pos - ones
        if ones > half or zeros > half:
            return
        if pos == length:
            if ones == half:
                mask = 0
                for i, bit in enumerate(prefix):
                    if bit:
                        mask |= 1 << i
                patterns.append(mask)
                bits_map[mask] = tuple(prefix)
            return

        remaining = length - pos
        if ones + remaining < half or zeros + remaining < half:
            return

        for bit in (0, 1):
            if pos >= 2 and prefix[pos - 1] == prefix[pos - 2] == bit:
                continue
            prefix[pos] = bit
            rec(pos + 1, ones + bit)

    rec(0, 0)
    return patterns, bits_map


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data:
