                if board[r][c] == -1:
                    res = set_cell(board, r, c, 0)
                    if res < 0:
                        return None
                    changed |= bool(res)

        if zeros == half:
            for r, c in coords:
                if board[r][c] == -1:
                    res = set_cell(board, r, c, 1)
                    if res < 0:
                        return None
                    changed |= bool(res)

        vals = [board[r][c] for r, c in coords]
        ones = vals.count(1)
        zeros = vals.count(0)
        if ones > half or zeros > half:
            return None

