    def set_cell(board, r, c, value):
        cur = board[r][c]
        if cur == -1:
            board[r][c] = value
            return 1
        if cur != value:
            return -1
        return 0

    def line_signature(values):
        known_mask = 0
        value_mask = 0
        for i, v in enumerate(values):
            if v != -1:
                known_mask |= 1 << i
                if v == 1:
                    value_mask |= 1 << i
        return known_mask, value_mask

    def build_candidates(values, patterns, cache):
        key = line_signature(values)
        cached = cache.get(key)
        if cached is None:
            known_mask, value_mask = key
            cached = tuple(
                p for p in patterns
                if ((p ^ value_mask) & known_mask) == 0
            )
            cache[key] = cached
        return list(cached)

    def process_line(board, coords, half):
        changed = False
        vals = [board[r][c] for r, c in coords]
        ones = vals.count(1)
        zeros = vals.count(0)
        if ones > half or zeros > half:
            return None

        length = len(coords)

        # Human-like local deductions:
        # XX_ -> _ must be opposite
        # _XX -> _ must be opposite
        # X_X -> middle must be opposite
        for i in range(length - 2):
            a, b, c = vals[i], vals[i + 1], vals[i + 2]

            if a != -1 and a == b and c == -1:
                rr, cc = coords[i + 2]
                res = set_cell(board, rr, cc, 1 - a)
                if res < 0:
                    return None
                changed |= bool(res)

            if b != -1 and b == c and a == -1:
                rr, cc = coords[i]
                res = set_cell(board, rr, cc, 1 - b)
                if res < 0:
                    return None
                changed |= bool(res)

            if a != -1 and a == c and b == -1:
                rr, cc = coords[i + 1]
                res = set_cell(board, rr, cc, 1 - a)
                if res < 0:
                    return None
                changed |= bool(res)

        vals = [board[r][c] for r, c in coords]
        ones = vals.count(1)
        zeros = vals.count(0)
        if ones > half or zeros > half:
            return None

        # Balance rule: once half of one color is reached, the rest are forced.
        if ones == half:
            for r, c in coords:
                if board[r][c] == -1:
                    res = set_cell(board, r, c, 0)
                    if res < 0:
                        return None
                    changed |= bool(res)

        if zeros == half:
            for r, c in coords:
                if board[r][c] == -1:
                    res = set_cell(board, r, c, 1)
                    if res < 0:
                        return None
                    changed |= bool(res)

        vals = [board[r][c] for r, c in coords]
        ones = vals.count(1)
        zeros = vals.count(0)
        if ones > half or zeros > half:
            return None

        return changed

    def apply_basic_rules(board):
        any_changed = False
        while True:
            changed = False

            for coords in row_coords:
                res = process_line(board, coords, row_half)
                if res is None:
                    return None
                changed |= res

            for coords in col_coords:
                res = process_line(board, coords, col_half)
                if res is None:
                    return None
                changed |= res

            if not changed:
                return any_changed
            any_changed = True

    def allowed_from_candidates(cands, bits_map, length):
        allow = [0] * length  # 1 => W allowed, 2 => B allowed, 3 => both
        for mask in cands:
            bits = bits_map[mask]
            for i, bit in enumerate(bits):
                allow[i] |= 2 if bit else 1
        return allow

    def unique_filter(cands_list):
        # If a line is already forced to one full pattern, no other peer line may use it.
        forced_owner = {}
        for idx, cands in enumerate(cands_list):
            if len(cands) == 1:
                mask = cands[0]
                if mask in forced_owner:
                    return None
                forced_owner[mask] = idx

        forced_masks = set(forced_owner)
        if not forced_masks:
            return False

        changed = False
        for idx, cands in enumerate(cands_list):
            if len(cands) == 1:
                continue
            new_cands = [m for m in cands if m not in forced_masks]
            if not new_cands:
                return None
            if len(new_cands) != len(cands):
                cands_list[idx] = new_cands
                changed = True
        return changed

    def propagate(board):
        while True:
            basic = apply_basic_rules(board)
            if basic is None:
                return None

            row_cands = []
            for r in range(rows):
                cands = build_candidates(board[r], row_patterns, row_match_cache)
                if not cands:
                    return None
                row_cands.append(cands)

            col_cands = []
            for c in range(cols):
                col_vals = [board[r][c] for r in range(rows)]
                cands = build_candidates(col_vals, col_patterns, col_match_cache)
                if not cands:
                    return None
                col_cands.append(cands)

            while True:
                changed = unique_filter(row_cands)
                if changed is None:
                    return None
                if changed:
                    continue

                changed = unique_filter(col_cands)
                if changed is None:
                    return None
                if changed:
                    continue

                row_allow = [
                    allowed_from_candidates(row_cands[r], row_bits, cols)
                    for r in range(rows)
                ]
                col_allow = [
                    allowed_from_candidates(col_cands[c], col_bits, rows)
                    for c in range(cols)
                ]

                pruned = False

                for r in range(rows):
                    new_cands = []
                    for mask in row_cands[r]:
                        bits = row_bits[mask]
                        ok = True
                        for c, bit in enumerate(bits):
                            needed = 2 if bit else 1
                            if not (col_allow[c][r] & needed):
                                ok = False
                                break
                        if ok:
                            new_cands.append(mask)
                    if not new_cands:
                        return None
                    if len(new_cands) != len(row_cands[r]):
                        row_cands[r] = new_cands
                        pruned = True
                if pruned:
                    continue

                for c in range(cols):
                    new_cands = []
                    for mask in col_cands[c]:
                        bits = col_bits[mask]
                        ok = True
                        for r, bit in enumerate(bits):
                            needed = 2 if bit else 1
                            if not (row_allow[r][c] & needed):
                                ok = False
                                break
                        if ok:
                            new_cands.append(mask)
                    if not new_cands:
                        return None
                    if len(new_cands) != len(col_cands[c]):
                        col_cands[c] = new_cands
                        pruned = True
                if pruned:
                    continue

                assigned = False
                for r in range(rows):
                    for c in range(cols):
                        intersection = row_allow[r][c] & col_allow[c][r]
                        if intersection == 0:
                            return None
                        if board[r][c] == -1 and intersection in (1, 2):
                            value = 0 if intersection == 1 else 1
                            res = set_cell(board, r, c, value)
                            if res < 0:
                                return None
                            assigned |= bool(res)

                if assigned:
                    break

                return board, row_cands, col_cands

    def is_complete_valid(board):
        for row in board:
            if -1 in row:
                return False
            if row.count(1) != row_half or row.count(0) != row_half:
                return False
            for i in range(cols - 2):
                if row[i] == row[i + 1] == row[i + 2]:
                    return False

        seen_rows = set()
        for row in board:
            tup = tuple(row)
            if tup in seen_rows:
                return False
            seen_rows.add(tup)

        seen_cols = set()
        for c in range(cols):
            col = [board[r][c] for r in range(rows)]
            if col.count(1) != col_half or col.count(0) != col_half:
                return False
            for i in range(rows - 2):
                if col[i] == col[i + 1] == col[i + 2]:
                    return False
            tup = tuple(col)
            if tup in seen_cols:
                return False
            seen_cols.add(tup)

        return True

    def choose_branch(board, row_cands, col_cands):
        best = None

        for r in range(rows):
            count = len(row_cands[r])
            if count > 1:
                unknowns = sum(1 for v in board[r] if v == -1)
                score = (count, -unknowns, 0, r)
                if best is None or score < best[0]:
                    best = (score, "row", r, row_cands[r])

        for c in range(cols):
            count = len(col_cands[c])
            if count > 1:
                unknowns = sum(1 for r in range(rows) if board[r][c] == -1)
                score = (count, -unknowns, 1, c)
                if best is None or score < best[0]:
                    best = (score, "col", c, col_cands[c])

        return None if best is None else (best[1], best[2], best[3])

    def dfs(state):
        board = [list(row) for row in state]
        propagated = propagate(board)
        if propagated is None:
            return None

        board, row_cands, col_cands = propagated
        stable_state = tuple(tuple(row) for row in board)
        if stable_state in memo:
            return memo[stable_state]

        if all(v != -1 for row in board for v in row):
            if is_complete_valid(board):
                memo[stable_state] = stable_state
                return stable_state
            memo[stable_state] = None
            return None

        branch = choose_branch(board, row_cands, col_cands)
        if branch is None:
            memo[stable_state] = None
            return None

        axis, idx, cands = branch

        for mask in cands:
            child = [row[:] for row in board]
            ok = True

            if axis == "row":
                bits = row_bits[mask]
                for c, bit in enumerate(bits):
                    res = set_cell(child, idx, c, bit)
                    if res < 0:
                        ok = False
                        break
            else:
                bits = col_bits[mask]
                for r, bit in enumerate(bits):
                    res = set_cell(child, r, idx, bit)
                    if res < 0:
                        ok = False
                        break

            if not ok:
                continue

            result = dfs(tuple(tuple(row) for row in child))
            if result is not None:
                memo[stable_state] = result
                return result

        memo[stable_state] = None
        return None

    initial_state = tuple(tuple(row) for row in grid)
    solution = dfs(initial_state)
    if solution is None:
        return "No Solution"

    answer = [[int_to_char[v] for v in row] for row in solution]
    return repr(answer)


