OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, None, None, 'W', 'W', None, None, 'B'], ['W', None, 'B', None, None, 'W', 'W', None], ['W', None, None, None, None, 'W', None, None], [None, None, None, 'B', None, None, None, None], [None, None, 'W', None, None, None, 'B', None], [None, None, None, None, None, None, None, 'B'], [None, None, 'W', None, 'W', 'W', None, None]]}

import sys

MASK_W = 1
MASK_B = 2
BOTH = MASK_W | MASK_B
MASK_TO_CHAR = {MASK_W: "W", MASK_B: "B"}
CHAR_TO_MASK = {"W": MASK_W, "B": MASK_B}

sys.setrecursionlimit(10000)


def generate_patterns(length):
    half = length // 2
    patterns = []
    seq = [0] * length  # 0 -> W, 1 -> B

    def rec(pos, count_b):
        count_w = pos - count_b
        if count_b > half or count_w > half:
            return
        if pos == length:
            if count_b == half:
                patterns.append(tuple(seq))
            return

        remaining_after = length - pos - 1

        for v in (0, 1):
            if pos >= 2 and seq[pos - 1] == seq[pos - 2] == v:
                continue

            new_b = count_b + (1 if v == 1 else 0)
            new_w = (pos + 1) - new_b

            if new_b > half or new_w > half:
                continue
            if new_b + remaining_after < half:
                continue
            if new_w + remaining_after < half:
                continue

            seq[pos] = v
            rec(pos + 1, new_b)

    rec(0, 0)
    return patterns


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data or not isinstance(data[0], list):
        return "No Solution"

    R = len(data)
    C = len(data[0])

    if any(not isinstance(row, list) or len(row) != C for row in data):
        return "No Solution"
    if R % 2 != 0 or C % 2 != 0:
        return "No Solution"

    row_half = C // 2
    col_half = R // 2

    row_patterns = generate_patterns(C)
    col_patterns = generate_patterns(R)

    if not row_patterns or not col_patterns:
        return "No Solution"

    domains = []
    for row in data:
        drow = []
        for cell in row:
            if cell is None:
                drow.append(BOTH)
            elif cell in CHAR_TO_MASK:
                drow.append(CHAR_TO_MASK[cell])
            else:
                return "No Solution"
        domains.append(drow)

    row_coords = [[(i, j) for j in range(C)] for i in range(R)]
    col_coords = [[(i, j) for i in range(R)] for j in range(C)]

    def copy_domains(dom):
        return [row[:] for row in dom]

    def dom_sig(dom):
        return tuple(tuple(row) for row in dom)

    def build_row_candidates(dom):
        out = []
        for i in range(R):
            row = dom[i]
            s = set()
            for idx, pat in enumerate(row_patterns):
                ok = True
                for j, v in enumerate(pat):
                    need = MASK_B if v else MASK_W
                    if not (row[j] & need):
                        ok = False
                        break
                if ok:
                    s.add(idx)
            if not s:
                return None
            out.append(s)
        return out

    def build_col_candidates(dom):
        out = []
        for j in range(C):
            s = set()
            for idx, pat in enumerate(col_patterns):
                ok = True
                for i, v in enumerate(pat):
                    need = MASK_B if v else MASK_W
                    if not (dom[i][j] & need):
                        ok = False
                        break
                if ok:
                    s.add(idx)
            if not s:
                return None
            out.append(s)
        return out

    matching_cache = {}

    # All-different feasibility on line patterns.
    def matching_possible(candidate_sets):
        sig = tuple(tuple(sorted(s)) for s in candidate_sets)
        cached = matching_cache.get(sig)
        if cached is not None:
            return cached

        union = set()
        for s in candidate_sets:
            union.update(s)
        if len(union) < len(candidate_sets):
            matching_cache[sig] = False
            return False

        counts = {}
        for s in candidate_sets:
            for p in s:
                counts[p] = counts.get(p, 0) + 1

        order = sorted(
            range(len(candidate_sets)),
            key=lambda i: (len(candidate_sets[i]), sum(counts[p] for p in candidate_sets[i])),
        )
        match = {}

        def dfs(line_idx, seen):
            for p in sorted(candidate_sets[line_idx], key=lambda x: counts[x]):
                if p in seen:
                    continue
                seen.add(p)
                owner = match.get(p)
                if owner is None or dfs(owner, seen):
                    match[p] = line_idx
                    return True
            return False

        ok = True
        for i in order:
            if not dfs(i, set()):
                ok = False
                break

        matching_cache[sig] = ok
        return ok

    def prune_all_different(candidate_sets):
        candidate_sets = [set(s) for s in candidate_sets]
        if any(not s for s in candidate_sets):
            return None
        if not matching_possible(candidate_sets):
            return None

        while True:
            changed = False

            # Human-like uniqueness rule: once a line pattern is forced for one line,
            # no other peer line may use that same full pattern.
            fixed_patterns = {next(iter(s)) for s in candidate_sets if len(s) == 1}
            for i, s in enumerate(candidate_sets):
                if len(s) > 1:
                    new_s = s - fixed_patterns
                    if not new_s:
                        return None
                    if new_s != s:
                        candidate_sets[i] = new_s
                        changed = True

            if not matching_possible(candidate_sets):
                return None

            # Stronger all-different support pruning:
            # remove any candidate pattern that cannot participate in any perfect matching.
            for i in sorted(range(len(candidate_sets)), key=lambda k: len(candidate_sets[k])):
                s = candidate_sets[i]
                if len(s) <= 1:
                    continue
                for p in list(s):
                    temp = [set(x) if k != i else {p} for k, x in enumerate(candidate_sets)]
                    if not matching_possible(temp):
                        s.remove(p)
                        changed = True
                        if not s:
                            return None

            if not matching_possible(candidate_sets):
                return None

            if not changed:
                return candidate_sets

    def apply_local_rules_to_line(dom, coords, half):
        changed_any = False

        while True:
            changed = False

            def restrict_idx(idx, allowed):
                nonlocal changed, changed_any
                r, c = coords[idx]
                new_mask = dom[r][c] & allowed
                if new_mask == 0:
                    return False
                if new_mask != dom[r][c]:
                    dom[r][c] = new_mask
                    changed = True
                    changed_any = True
                return True

            masks = [dom[r][c] for r, c in coords]

            fixed_b = sum(1 for m in masks if m == MASK_B)
            fixed_w = sum(1 for m in masks if m == MASK_W)
            if fixed_b > half or fixed_w > half:
                return None

            can_b = sum(1 for m in masks if m & MASK_B)
            can_w = sum(1 for m in masks if m & MASK_W)
            if can_b < half or can_w < half:
                return None

            # Balance rule: if required quota is filled, the rest are forced.
            if fixed_b == half:
                for idx, m in enumerate(masks):
                    if m != MASK_B:
                        if not restrict_idx(idx, MASK_W):
                            return None

            masks = [dom[r][c] for r, c in coords]
            if fixed_w == half:
                for idx, m in enumerate(masks):
                    if m != MASK_W:
                        if not restrict_idx(idx, MASK_B):
                            return None

            # Saturation rule: if exactly half positions can still be B (or W),
            # then they all must be B (or W).
            masks = [dom[r][c] for r, c in coords]
            if sum(1 for m in masks if m & MASK_B) == half:
                for idx, m in enumerate(masks):
                    if m & MASK_B:
                        if not restrict_idx(idx, MASK_B):
                            return None

            masks = [dom[r][c] for r, c in coords]
            if sum(1 for m in masks if m & MASK_W) == half:
