                    if m & MASK_W:
                        if not restrict_idx(idx, MASK_W):
                            return None

            # Triplet rules: XX? / ?XX / X?X
            masks = [dom[r][c] for r, c in coords]
            vals = []
            for m in masks:
                if m == MASK_W:
                    vals.append(0)
                elif m == MASK_B:
