                        return None
                if b is not None and b == c:
                    if not restrict_idx(i, MASK_B if b == 0 else MASK_W):
                        return None
                if a is not None and a == c:
                    if not restrict_idx(i + 1, MASK_B if a == 0 else MASK_W):
                        return None

            if not changed:
