    def restrict_from_row_candidates(dom, row_cands):
        changed = False
        for i, cands in enumerate(row_cands):
            if len(cands) == 1:
                pat = row_patterns[next(iter(cands))]
                for j, v in enumerate(pat):
                    allowed = MASK_B if v else MASK_W
                    new_mask = dom[i][j] & allowed
                    if new_mask == 0:
                        return None
                    if new_mask != dom[i][j]:
                        dom[i][j] = new_mask
                        changed = True
                continue

            for j in range(C):
                allow = 0
                for p in cands:
                    allow |= MASK_B if row_patterns[p][j] else MASK_W
                    if allow == BOTH:
                        break
                new_mask = dom[i][j] & allow
                if new_mask == 0:
                    return None
                if new_mask != dom[i][j]:
                    dom[i][j] = new_mask
                    changed = True
        return changed

    def restrict_from_col_candidates(dom, col_cands):
        changed = False
        for j, cands in enumerate(col_cands):
            if len(cands) == 1:
                pat = col_patterns[next(iter(cands))]
                for i, v in enumerate(pat):
                    allowed = MASK_B if v else MASK_W
                    new_mask = dom[i][j] & allowed
                    if new_mask == 0:
                        return None
                    if new_mask != dom[i][j]:
                        dom[i][j] = new_mask
                        changed = True
                continue

            for i in range(R):
                allow = 0
                for p in cands:
                    allow |= MASK_B if col_patterns[p][i] else MASK_W
                    if allow == BOTH:
                        break
                new_mask = dom[i][j] & allow
                if new_mask == 0:
                    return None
                if new_mask != dom[i][j]:
                    dom[i][j] = new_mask
                    changed = True
        return changed

    def propagate(dom):
        dom = copy_domains(dom)

        while True:
            changed = False

            # Human-like local deductions on rows and columns.
            for coords in row_coords:
                res = apply_local_rules_to_line(dom, coords, row_half)
                if res is None:
                    return None
                changed |= res

            for coords in col_coords:
                res = apply_local_rules_to_line(dom, coords, col_half)
                if res is None:
                    return None
                changed |= res

            row_cands = build_row_candidates(dom)
            if row_cands is None:
                return None
            row_cands = prune_all_different(row_cands)
            if row_cands is None:
                return None

            row_changed = restrict_from_row_candidates(dom, row_cands)
            if row_changed is None:
                return None
            changed |= row_changed

            col_cands = build_col_candidates(dom)
            if col_cands is None:
                return None
            col_cands = prune_all_different(col_cands)
            if col_cands is None:
                return None

            col_changed = restrict_from_col_candidates(dom, col_cands)
            if col_changed is None:
                return None
            changed |= col_changed

            if not changed:
                return dom, row_cands, col_cands

    def validate_grid(grid):
        # Balance and triplets.
        for row in grid:
            if row.count("B") != row_half or row.count("W") != row_half:
                return False
            for i in range(C - 2):
                if row[i] == row[i + 1] == row[i + 2]:
                    return False

        cols = []
        for j in range(C):
            col = [grid[i][j] for i in range(R)]
            if col.count("B") != col_half or col.count("W") != col_half:
                return False
            for i in range(R - 2):
                if col[i] == col[i + 1] == col[i + 2]:
                    return False
            cols.append(tuple(col))

        if len({tuple(row) for row in grid}) != R:
            return False
        if len(set(cols)) != C:
            return False

        # Given cells fixed.
        for i in range(R):
            for j in range(C):
                if data[i][j] is not None and data[i][j] != grid[i][j]:
                    return False

        return True

    def row_pattern_support(i, pidx, col_cands):
        pat = row_patterns[pidx]
        total = 0
        for j, v in enumerate(pat):
            total += sum(1 for q in col_cands[j] if col_patterns[q][i] == v)
        return total

    def col_pattern_support(j, pidx, row_cands):
        pat = col_patterns[pidx]
        total = 0
        for i, v in enumerate(pat):
            total += sum(1 for q in row_cands[i] if row_patterns[q][j] == v)
        return total

    failed = set()

    def search(dom):
        start_sig = dom_sig(dom)
        if start_sig in failed:
            return None

