from functools import lru_cache

B = 1
W = 0
U = -1


@lru_cache(None)
def valid_patterns(n):
    if n % 2 != 0:
        return tuple()
    target = n // 2
    out = []

    def rec(pos, blacks, last1, last2, mask):
        whites = pos - blacks
        remaining = n - pos
        if blacks > target or whites > target:
            return
        if blacks + remaining < target or whites + remaining < target:
            return
        if pos == n:
            if blacks == target:
                out.append(mask)
            return
        for bit in (0, 1):
            if pos >= 2 and last1 == last2 == bit:
                continue
            rec(pos + 1, blacks + bit, bit, last1, mask | (bit << pos))

    rec(0, 0, -1, -1, 0)
    return tuple(out)


@lru_cache(None)
def allowed_masks_from_domain(domain, length):
    any1 = 0
    all1 = (1 << length) - 1
    for p in domain:
        any1 |= p
        all1 &= p
    masks = [0] * length
    for i in range(length):
        bit = 1 << i
        masks[i] = (1 if not (all1 & bit) else 0) | (2 if (any1 & bit) else 0)
    return tuple(masks)


@lru_cache(None)
def distinct_assignment_possible(domains):
    m = len(domains)
    pattern_to_idx = {}
    adj = []
    for dom in domains:
        row_adj = []
        for p in dom:
            if p not in pattern_to_idx:
                pattern_to_idx[p] = len(pattern_to_idx)
            row_adj.append(pattern_to_idx[p])
        adj.append(row_adj)

    if len(pattern_to_idx) < m:
        return False

    match = [-1] * len(pattern_to_idx)

    def dfs(r, seen):
        for pid in adj[r]:
            if seen[pid]:
                continue
            seen[pid] = True
            if match[pid] == -1 or dfs(match[pid], seen):
                match[pid] = r
                return True
        return False

    for r in sorted(range(m), key=lambda i: len(adj[i])):
        seen = [False] * len(pattern_to_idx)
        if not dfs(r, seen):
            return False
    return True


def row_masks(grid, r):
    known = 0
    black = 0
    for c, v in enumerate(grid[r]):
        if v != U:
            known |= 1 << c
            if v == B:
                black |= 1 << c
    return known, black


def col_masks(grid, c):
    known = 0
    black = 0
    for r in range(len(grid)):
        v = grid[r][c]
        if v != U:
            known |= 1 << r
            if v == B:
                black |= 1 << r
    return known, black


def partial_line_consistent(line):
    n = len(line)
    half = n // 2
    if line.count(B) > half or line.count(W) > half:
        return False
    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a != U and a == b == c:
            return False
    return True


def grid_consistent(grid):
    r_count = len(grid)
    c_count = len(grid[0])

    for r in range(r_count):
        if not partial_line_consistent(grid[r]):
            return False

    for c in range(c_count):
        col = [grid[r][c] for r in range(r_count)]
        if not partial_line_consistent(col):
            return False

    seen_rows = set()
    for row in grid:
        if U not in row:
            t = tuple(row)
            if t in seen_rows:
                return False
            seen_rows.add(t)

    seen_cols = set()
    for c in range(c_count):
        col = tuple(grid[r][c] for r in range(r_count))
        if U not in col:
            if col in seen_cols:
                return False
            seen_cols.add(col)

    return True


def forced_from_line(line):
    n = len(line)
    out = []

    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a == b != U and c == U:
            out.append((i + 2, 1 - a))
        if b == c != U and a == U:
            out.append((i, 1 - b))
        if a == c != U and b == U:
            out.append((i + 1, 1 - a))

    half = n // 2
    bcnt = line.count(B)
    wcnt = line.count(W)

    if bcnt == half:
        for i, v in enumerate(line):
            if v == U:
                out.append((i, W))
    if wcnt == half:
        for i, v in enumerate(line):
            if v == U:
                out.append((i, B))

    return out


def set_cell(grid, r, c, val):
    cur = grid[r][c]
    if cur == U:
        grid[r][c] = val
        return 1
    if cur != val:
        return -1
    return 0


