    m = len(data[0]) if isinstance(data[0], list) else 0
    if m == 0:
        return None

    domains = []
    for row in data:
        if not isinstance(row, list) or len(row) != m:
            return None
        drow = []
        for cell in row:
            if cell is None:
                drow.append(ALL)
            elif cell in ('W', 'w'):
                drow.append(W)
            elif cell in ('B', 'b'):
                drow.append(B)
            else:
                return None
        domains.append(drow)

    h_edges = {}
    for key, op in observation.get('horizontal', {}).items():
        if op not in ('=', 'x'):
            return None
        parsed = parse_edge_key(key)
        if parsed is None:
            return None
        r, c = parsed
        rr = int(round(r))
        cc = int(round(c - 0.5))
        if not (0 <= rr < n and 0 <= cc < m - 1):
            return None
        h_edges[(rr, cc)] = op

    v_edges = {}
    for key, op in observation.get('vertical', {}).items():
        if op not in ('=', 'x'):
            return None
        parsed = parse_edge_key(key)
        if parsed is None:
            return None
        r, c = parsed
        rr = int(round(r - 0.5))
        cc = int(round(c))
        if not (0 <= rr < n - 1 and 0 <= cc < m):
            return None
        v_edges[(rr, cc)] = op

    return n, m, domains, h_edges, v_edges


def parse_edge_key(key):
    try:
        if isinstance(key, str):
            a, b = ast.literal_eval(key)
        else:
            a, b = key
        return float(a), float(b)
    except Exception:
        return None


def state_key(domains):
    return tuple(cell for row in domains for cell in row)


def is_solved(domains):
    return all(cell in (W, B) for row in domains for cell in row)


def choose_cell(domains, row_cands, col_cands):
    best = None
    best_metric = None
    n = len(domains)
    m = len(domains[0])
    for r in range(n):
        for c in range(m):
            if domains[r][c] == ALL:
                metric = (len(row_cands[r]) * len(col_cands[c]), len(row_cands[r]) + len(col_cands[c]))
                if best_metric is None or metric < best_metric:
                    best_metric = metric
                    best = (r, c)
    return best


def propagate(domains, n, m, h_edges, v_edges):
    row_cands = [None] * n
    col_cands = [None] * m

    while True:
        changed = False

        # 1) Binary edge propagation (= / x).
        for (r, c), op in h_edges.items():
            a = domains[r][c]
            b = domains[r][c + 1]
            na, nb = prune_pair(a, b, op)
            if na == 0 or nb == 0:
                return None
            if na != a:
                domains[r][c] = na
                changed = True
            if nb != b:
                domains[r][c + 1] = nb
                changed = True

        for (r, c), op in v_edges.items():
            a = domains[r][c]
            b = domains[r + 1][c]
            na, nb = prune_pair(a, b, op)
            if na == 0 or nb == 0:
                return None
            if na != a:
                domains[r][c] = na
                changed = True
            if nb != b:
                domains[r + 1][c] = nb
                changed = True

        # 2) Local no-three-consecutive propagation on every length-3 window.
        for r in range(n):
            for c in range(m - 2):
                rel01 = h_edges.get((r, c))
                rel12 = h_edges.get((r, c + 1))
                supported = triple_support(domains[r][c], domains[r][c + 1], domains[r][c + 2], rel01, rel12)
                if supported is None:
                    return None
                s0, s1, s2 = supported
                if s0 != domains[r][c]:
                    domains[r][c] = s0
                    changed = True
                if s1 != domains[r][c + 1]:
                    domains[r][c + 1] = s1
                    changed = True
                if s2 != domains[r][c + 2]:
                    domains[r][c + 2] = s2
                    changed = True

        for c in range(m):
            for r in range(n - 2):
                rel01 = v_edges.get((r, c))
                rel12 = v_edges.get((r + 1, c))
                supported = triple_support(domains[r][c], domains[r + 1][c], domains[r + 2][c], rel01, rel12)
                if supported is None:
                    return None
                s0, s1, s2 = supported
                if s0 != domains[r][c]:
                    domains[r][c] = s0
                    changed = True
                if s1 != domains[r + 1][c]:
                    domains[r + 1][c] = s1
                    changed = True
                if s2 != domains[r + 2][c]:
                    domains[r + 2][c] = s2
                    changed = True

        # 3) Balance rules on rows and columns.
        for r in range(n):
            new_line = prune_balance_masks(tuple(domains[r]))
            if new_line is None:
                return None
            masks, line_changed = new_line
            if line_changed:
                domains[r] = list(masks)
                changed = True

        for c in range(m):
            col = tuple(domains[r][c] for r in range(n))
            new_line = prune_balance_masks(col)
            if new_line is None:
                return None
            masks, line_changed = new_line
            if line_changed:
                for r in range(n):
                    domains[r][c] = masks[r]
                changed = True

        # 4) Full line candidate filtering (human-style line completion/intersection).
        for r in range(n):
            out = prune_line_row(domains, r, m, h_edges)
            if out is None:
                return None
            line_changed, cands = out
            row_cands[r] = cands
            if line_changed:
                changed = True

        for c in range(m):
            out = prune_line_col(domains, c, n, v_edges)
            if out is None:
                return None
            line_changed, cands = out
            col_cands[c] = cands
            if line_changed:
                changed = True

        if not changed:
            return domains, row_cands, col_cands


def prune_pair(a, b, op):
    if op == '=':
        common = a & b
        return common, common
    # op == 'x'
    na = 0
    nb = 0
    if (a & W) and (b & B):
        na |= W
        nb |= B
    if (a & B) and (b & W):
        na |= B
        nb |= W
    return na, nb


def triple_support(d0, d1, d2, op01, op12):
    s0 = s1 = s2 = 0
    for c0, m0 in ((0, W), (1, B)):
        if not (d0 & m0):
            continue
        for c1, m1 in ((0, W), (1, B)):
            if not (d1 & m1):
                continue
            if op01 == '=' and c0 != c1:
                continue
            if op01 == 'x' and c0 == c1:
                continue
            for c2, m2 in ((0, W), (1, B)):
                if not (d2 & m2):
                    continue
                if op12 == '=' and c1 != c2:
                    continue
                if op12 == 'x' and c1 == c2:
                    continue
                if c0 == c1 == c2:
                    continue
                s0 |= m0
                s1 |= m1
                s2 |= m2
    if s0 == 0 or s1 == 0 or s2 == 0:
        return None
    return s0, s1, s2


def prune_balance_masks(masks):
    masks = list(masks)
    length = len(masks)
    target = length // 2
    changed = False

    fixed_b = sum(1 for d in masks if d == B)
    fixed_w = sum(1 for d in masks if d == W)
    unknown = length - fixed_b - fixed_w

    if fixed_b > target or fixed_w > target:
        return None
    if fixed_b + unknown < target or fixed_w + unknown < target:
        return None

    if fixed_b == target:
        for i, d in enumerate(masks):
            if d & B and d != W:
                nd = d & W
                if nd == 0:
                    return None
                if nd != d:
                    masks[i] = nd
                    changed = True

    if fixed_w == target:
        for i, d in enumerate(masks):
            if d & W and d != B:
                nd = d & B
                if nd == 0:
                    return None
                if nd != d:
                    masks[i] = nd
                    changed = True

    possible_b = sum(1 for d in masks if d & B)
    possible_w = sum(1 for d in masks if d & W)

    if possible_b < target or possible_w < target:
        return None

    if possible_b == target:
        for i, d in enumerate(masks):
            if d & B and d != B:
                masks[i] = B
                changed = True

    if possible_w == target:
        for i, d in enumerate(masks):
            if d & W and d != W:
                masks[i] = W
                changed = True

    fixed_b = sum(1 for d in masks if d == B)
    fixed_w = sum(1 for d in masks if d == W)
    if fixed_b > target or fixed_w > target:
        return None

    return tuple(masks), changed


def prune_line_row(domains, r, m, h_edges):
    dom_tuple = tuple(domains[r][c] for c in range(m))
    rel_tuple = tuple(h_edges.get((r, c)) for c in range(m - 1))
    cands = line_candidates(dom_tuple, rel_tuple)
    if not cands:
        return None

    support = [0] * m
    for pat in cands:
        for c in range(m):
            support[c] |= B if ((pat >> c) & 1) else W

    changed = False
    for c in range(m):
        nd = domains[r][c] & support[c]
        if nd == 0:
            return None
        if nd != domains[r][c]:
            domains[r][c] = nd
            changed = True

    return changed, cands


def prune_line_col(domains, c, n, v_edges):
    dom_tuple = tuple(domains[r][c] for r in range(n))
    rel_tuple = tuple(v_edges.get((r, c)) for r in range(n - 1))
    cands = line_candidates(dom_tuple, rel_tuple)
    if not cands:
        return None

    support = [0] * n
    for pat in cands:
        for r in range(n):
            support[r] |= B if ((pat >> r) & 1) else W

    changed = False
    for r in range(n):
        nd = domains[r][c] & support[r]
        if nd == 0:
            return None
        if nd != domains[r][c]:
            domains[r][c] = nd
            changed = True

    return changed, cands


@lru_cache(maxsize=None)
def line_candidates(dom_tuple, rel_tuple):
    length = len(dom_tuple)
    target_b = length // 2
    out = []

    def dfs(i, prev1, prev2, count_b, pattern):
        count_w = i - count_b
        rem = length - i

        if count_b > target_b or count_w > target_b:
            return
        if count_b + rem < target_b or count_w + rem < target_b:
            return

        if i == length:
            if count_b == target_b:
                out.append(pattern)
            return

        dom = dom_tuple[i]
        for color in (0, 1):  # 0 = W, 1 = B
            mask = W if color == 0 else B
            if not (dom & mask):
                continue
            if i > 0:
                op = rel_tuple[i - 1]
                if op == '=' and color != prev1:
                    continue
                if op == 'x' and color == prev1:
                    continue
            if i > 1 and color == prev1 == prev2:
                continue
            dfs(i + 1, color, prev1, count_b + color, pattern | (color << i))

    dfs(0, -1, -1, 0, 0)
    return tuple(out)


def validate_solution(domains, n, m, h_edges, v_edges):
    for r in range(n):
        for c in range(m):
            if domains[r][c] not in (W, B):
                return False

    for r in range(n):
        if sum(1 for c in range(m) if domains[r][c] == B) != m // 2:
            return False
        for c in range(m - 2):
            if domains[r][c] == domains[r][c + 1] == domains[r][c + 2]:
                return False

    for c in range(m):
        if sum(1 for r in range(n) if domains[r][c] == B) != n // 2:
            return False
        for r in range(n - 2):
            if domains[r][c] == domains[r + 1][c] == domains[r + 2][c]:
                return False

    for (r, c), op in h_edges.items():
        same = domains[r][c] == domains[r][c + 1]
        if op == '=' and not same:
            return False
        if op == 'x' and same:
            return False

    for (r, c), op in v_edges.items():
        same = domains[r][c] == domains[r + 1][c]
        if op == '=' and not same:
            return False
        if op == 'x' and same:
            return False

    return True


