import ast

B_MASK = 1
W_MASK = 2
BOTH = B_MASK | W_MASK

CHAR_TO_MASK = {'B': B_MASK, 'W': W_MASK}
MASK_TO_CHAR = {B_MASK: 'B', W_MASK: 'W'}

PATTERN_CACHE = {}


def swap_mask(mask):
    return ((mask & B_MASK) << 1) | ((mask & W_MASK) >> 1)


def parse_key(key):
    if isinstance(key, str):
        return ast.literal_eval(key)
    return key


def norm_symbol(sym):
    s = str(sym).strip().lower()
    return 'x' if s in {'x', '×'} else '='


def prune(domains, idx, allowed):
    new_mask = domains[idx] & allowed
    if new_mask == 0:
        return -1
    if new_mask != domains[idx]:
        domains[idx] = new_mask
        return 1
    return 0


def generate_patterns(n):
    if n in PATTERN_CACHE:
        return PATTERN_CACHE[n]
    if n % 2:
        PATTERN_CACHE[n] = []
        return []
    half = n // 2
    out = []
    line = [0] * n

    def rec(pos, blacks):
        whites = pos - blacks
        rem = n - pos
        if blacks > half or whites > half:
            return
        if blacks + rem < half or whites + rem < half:
            return
        if pos == n:
            if blacks == half:
                out.append(tuple(line))
            return
        for val in (B_MASK, W_MASK):
            if pos >= 2 and line[pos - 1] == line[pos - 2] == val:
                continue
            line[pos] = val
            rec(pos + 1, blacks + (1 if val == B_MASK else 0))

    rec(0, 0)
    PATTERN_CACHE[n] = out
    return out


def pattern_fits_constraints(pattern, constraints):
    for i, sym in enumerate(constraints):
        if sym is None:
            continue
        same = pattern[i] == pattern[i + 1]
        if sym == '=':
            if not same:
                return False
        else:
            if same:
                return False
    return True


def build_context(observation):
    data = observation.get('data')
    if not data or not data[0]:
        return None
    r_count = len(data)
    c_count = len(data[0])
    if any(len(row) != c_count for row in data):
        return None
    if r_count % 2 or c_count % 2:
        return None

    domains = [BOTH] * (r_count * c_count)

    def idx(r, c):
        return r * c_count + c

    for r in range(r_count):
        for c in range(c_count):
            cell = data[r][c]
            if cell is None:
                continue
            cell = str(cell).strip().upper()
            if cell not in CHAR_TO_MASK:
                return None
            domains[idx(r, c)] = CHAR_TO_MASK[cell]

    h_cons = [[None] * (c_count - 1) for _ in range(r_count)]
    v_cons = [[None] * c_count for _ in range(r_count - 1)]
    edges = []

    for key, sym in observation.get('horizontal', {}).items():
        rr, cc = parse_key(key)
        r = int(round(rr))
        c = int(round(cc - 0.5))
        if not (0 <= r < r_count and 0 <= c < c_count - 1):
            return None
        sym = norm_symbol(sym)
        h_cons[r][c] = sym
        edges.append((idx(r, c), idx(r, c + 1), sym == '='))

    for key, sym in observation.get('vertical', {}).items():
        rr, cc = parse_key(key)
        r = int(round(rr - 0.5))
        c = int(round(cc))
        if not (0 <= r < r_count - 1 and 0 <= c < c_count):
