        edges.append((idx(r, c), idx(r + 1, c), sym == '='))

    row_patterns = generate_patterns(c_count)
    col_patterns = generate_patterns(r_count)
    if not row_patterns or not col_patterns:
        return None

    row_cells = [[idx(r, c) for c in range(c_count)] for r in range(r_count)]
    col_cells = [[idx(r, c) for r in range(r_count)] for c in range(c_count)]

    col_adj_constraints = [[v_cons[r][c] for r in range(r_count - 1)] for c in range(c_count)]

    row_base = []
    for r in range(r_count):
        base = [p for p in row_patterns if pattern_fits_constraints(p, h_cons[r])]
        if not base:
            return None
