    return {
        'R': r_count,
        'C': c_count,
        'initial_domains': domains,
        'edges': edges,
        'row_cells': row_cells,
        'col_cells': col_cells,
        'row_base': row_base,
        'col_base': col_base,
        'row_half': c_count // 2,
        'col_half': r_count // 2,
    }


def apply_relation_rules(domains, edges):
    changed = False
    for a, b, same in edges:
        da = domains[a]
        db = domains[b]
        if same:
            na = da & db
            nb = db & da
        else:
            na = da & swap_mask(db)
            nb = db & swap_mask(da)
        if na == 0 or nb == 0:
            return None
        if na != da:
            domains[a] = na
            changed = True
        if nb != db:
            domains[b] = nb
            changed = True
    return changed


def apply_line_local_rules(indices, domains, half):
    changed = False
