    n = ctx['n']
    m = ctx['m']
    row_value_masks = ctx['row_info']['value_masks']
    col_value_masks = ctx['col_info']['value_masks']

    best = None

    for r in range(n):
        rdom = row_domains[r]
        for c in range(m):
            supports = []
            for v in (0, 1):
                rs = (rdom & row_value_masks[c][v]).bit_count()
                cs = (col_domains[c] & col_value_masks[r][v]).bit_count()
