    if all_singletons(row_domains) and all_singletons(col_domains):
        return row_domains, col_domains

    choice = choose_branch_cell(row_domains, col_domains, ctx)
    if choice is None:
        dead_states.add(key)
        return None

    r, c, values = choice
    row_value_masks = ctx['row_info']['value_masks']
    col_value_masks = ctx['col_info']['value_masks']

    for v in values:
        new_rows = row_domains.copy()
        new_cols = col_domains.copy()
        new_rows[r] &= row_value_masks[c][v]
        new_cols[c] &= col_value_masks[r][v]
        if new_rows[r] and new_cols[c]:
