    dead_states.add(key)
    return None


def domains_to_grid(row_domains, ctx):
    patterns = ctx['row_info']['patterns']
    m = ctx['m']
    grid = []

    for dom in row_domains:
        if not is_singleton(dom):
            return None
        idx = dom.bit_length() - 1
        pat = patterns[idx]
        row = []
        for c in range(m):
            row.append('B' if ((pat >> c) & 1) else 'W')
        grid.append(row)

    return grid


def solve(observation):
    try:
        ctx = build_problem(observation)
    except Exception:
        return "No Solution"

    row_domains, col_domains = initial_domains(ctx)
    if any(d == 0 for d in row_domains) or any(d == 0 for d in col_domains):
        return "No Solution"

    result = search(row_domains, col_domains, ctx, set())
    if result is None:
        return "No Solution"

    solved_rows, _ = result
    grid = domains_to_grid(solved_rows, ctx)
    if grid is None:
        return "No Solution"
    return repr(grid)


