            else:
                c = best_index
                for p in col_valid[c]:
                    score = 0
                    for r, v in enumerate(p):
                        cnt = 0
                        for rp in row_valid[r]:
                            if rp[c] == v:
                                cnt += 1
                        score += cnt
                    scored.append((score, p))

            scored.sort(key=lambda x: x[0])

            for _, p in scored:
                new_domains = cur[:]
                ok = True
                if best_kind == 'row':
                    off = best_index * n
                    for c, v in enumerate(p):
                        m = 1 << v
                        if (new_domains[off + c] & m) == 0:
                            ok = False
                            break
                        new_domains[off + c] = m
                else:
