                if ans is not None:
                    return ans

        dead.add(state)
        return None

    return dfs(domains0)


def solve(observation):
    vertical = observation.get('vertical', {})
    tried = []

    # Common convention first:
    # '^' means top < bottom, 'v' means top > bottom.
    for convention in (True, False) if vertical else (True,):
        grid = _solve_one(observation, convention)
        if grid is not None:
            t = tuple(tuple(row) for row in grid)
            if t not in tried:
                tried.append(t)

    if not tried:
        return "No Solution"
    return str([list(row) for row in tried[0]])


