            rel = '>' if sym == '^' else '<'
        v_pattern[r][c] = rel
        a, b = idx(r, c), idx(r + 1, c)
        if rel == '<':
            add_less(a, b)
        else:
            add_less(b, a)

    # Detect impossible inequality cycles and compute topological order.
    indeg_work = indeg[:]
    q = deque(i for i in range(cells) if indeg_work[i] == 0)
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in less_adj[u]:
            indeg_work[v] -= 1
            if indeg_work[v] == 0:
                q.append(v)
    if len(topo) != cells:
        return None

    # Static chain bounds: if x has k predecessors in the longest chain, x >= 1+k.
    pred_depth = [0] * cells
    for u in topo:
        base = pred_depth[u] + 1
        for v in less_adj[u]:
            if pred_depth[v] < base:
                pred_depth[v] = base

    succ_depth = [0] * cells
    for u in reversed(topo):
        best = 0
        for v in less_adj[u]:
            cand = succ_depth[v] + 1
            if cand > best:
                best = cand
        succ_depth[u] = best

