    row_units = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_units = [[idx(r, c) for r in range(n)] for c in range(n)]
    all_units = row_units + col_units

    # Strong line-based candidate filtering for practical puzzle sizes.
    use_perms = n <= 8
    perm_cache = {}

    def perms_for_pattern(pattern):
        key = tuple(pattern)
        if key in perm_cache:
            return perm_cache[key]

        result = []
        used = [False] * (n + 1)
        cur = [0] * n

        def rec(pos):
            if pos == n:
                result.append(tuple(cur))
                return
            for v in values:
                if used[v]:
                    continue
                if pos > 0:
                    s = key[pos - 1]
                    if s == '<' and cur[pos - 1] >= v:
                        continue
                    if s == '>' and cur[pos - 1] <= v:
                        continue
                if pos < n - 1:
                    s2 = key[pos]
                    if s2 == '<':
