            if not valid:
                return None, None
            row_valid.append(valid)

        col_valid = []
        for c in range(n):
            valid = []
            for p in col_base[c]:
                ok = True
                for r, v in enumerate(p):
                    if ((domains[r * n + c] >> v) & 1) == 0:
                        ok = False
                        break
                if ok:
                    valid.append(p)
            if not valid:
                return None, None
            col_valid.append(valid)

        return row_valid, col_valid

    def propagate(domains):
        domains = domains[:]

        while True:
            before = tuple(domains)

            # 1) Static inequality-chain bounds.
            for i in range(cells):
                lo = 1 + pred_depth[i]
                hi = n - succ_depth[i]
                nd = domains[i] & mask_range(lo, hi)
                if nd == 0:
                    return None
                domains[i] = nd

            # 2) Arc consistency over all transitive inequality relations.
            for a, b in closure_pairs:
                da = domains[a]
                db = domains[b]

                nda = da & mask_lt(max_value(db))
                if nda == 0:
                    return None
                domains[a] = nda

                ndb = db & mask_gt(min_value(domains[a]))
                if ndb == 0:
                    return None
                domains[b] = ndb

            # 3) Basic human-style Latin constraints in each row/column:
            #    singles, hidden singles, exact naked subsets.
            for unit in all_units:
                taken = 0
                for i in unit:
                    d = domains[i]
                    if d == 0:
                        return None
                    if is_single(d):
                        if taken & d:
