                    sz = d.bit_count()
                    if 2 <= sz <= upper_subset_size:
                        same_masks.setdefault(d, []).append(i)

                for mask, pos_list in same_masks.items():
                    sz = mask.bit_count()
                    if len(pos_list) == sz:
