                        domains[off + c] = nd

                for c in range(n):
                    valid = []
                    for p in col_base[c]:
                        ok = True
                        for r, v in enumerate(p):
                            if ((domains[r * n + c] >> v) & 1) == 0:
                                ok = False
                                break
                        if ok:
                            valid.append(p)
                    if not valid:
                        return None
                    for r in range(n):
                        allow = 0
                        for p in valid:
                            allow |= 1 << p[r]
