                        nd = domains[i] & allow
                        if nd == 0:
                            return None
                        domains[i] = nd

            if any(d == 0 for d in domains):
                return None

            if tuple(domains) == before:
                break

        row_valid, col_valid = final_line_valids(domains)
        if use_perms and (row_valid is None or col_valid is None):
            return None
        return domains, row_valid, col_valid

    def validate(grid):
        target = set(range(1, n + 1))

        for row in grid:
            if set(row) != target:
                return False
        for c in range(n):
            if {grid[r][c] for r in range(n)} != target:
                return False

        for key, sym in horizontal_raw.items():
            r, c_half = _coord_pair(key)
            r = int(round(r))
            c = int(round(c_half - 0.5))
            a = grid[r][c]
            b = grid[r][c + 1]
            if sym == '<' and not (a < b):
                return False
            if sym == '>' and not (a > b):
                return False

        for key, sym in vertical_raw.items():
            r_half, c = _coord_pair(key)
            r = int(round(r_half - 0.5))
            c = int(round(c))
            top = grid[r][c]
            bottom = grid[r + 1][c]
            if up_symbol_means_top_less:
                if sym == '^' and not (top < bottom):
                    return False
                if sym == 'v' and not (top > bottom):
                    return False
            else:
                if sym == '^' and not (top > bottom):
                    return False
                if sym == 'v' and not (top < bottom):
                    return False
        return True

    dead = set()

    def dfs(domains):
        prop = propagate(domains)
        if prop is None:
            return None

        cur, row_valid, col_valid = prop
        state = tuple(cur)
        if state in dead:
            return None

        if all(is_single(d) for d in cur):
            grid = [[single_value(cur[idx(r, c)]) for c in range(n)] for r in range(n)]
            if validate(grid):
                return grid
            dead.add(state)
            return None

        # Choose the most constrained cell.
        best_cell = None
        best_size = n + 1
        best_deg = -1
        for i, d in enumerate(cur):
            sz = d.bit_count()
            if 1 < sz < best_size or (sz == best_size and ineq_degree[i] > best_deg):
                best_size = sz
                best_deg = ineq_degree[i]
                best_cell = i

        # If line candidate counts are tiny, branch on an entire row/column pattern.
        use_unit_branch = False
        best_kind = None
        best_index = None
        best_count = 10 ** 9

        if use_perms:
            for r, valid in enumerate(row_valid):
                k = len(valid)
                if 1 < k < best_count:
                    best_count = k
                    best_kind = 'row'
                    best_index = r
            for c, valid in enumerate(col_valid):
                k = len(valid)
                if 1 < k < best_count:
                    best_count = k
                    best_kind = 'col'
                    best_index = c

            if best_count <= best_size + 1:
                use_unit_branch = True

        if use_unit_branch:
            scored = []
            if best_kind == 'row':
                r = best_index
                for p in row_valid[r]:
                    score = 0
                    for c, v in enumerate(p):
                        cnt = 0
                        for cp in col_valid[c]:
                            if cp[r] == v:
                                cnt += 1
                        score += cnt
                    scored.append((score, p))
            else:
                c = best_index
                for p in col_valid[c]:
                    score = 0
                    for r, v in enumerate(p):
                        cnt = 0
                        for rp in row_valid[r]:
                            if rp[c] == v:
                                cnt += 1
                        score += cnt
                    scored.append((score, p))

            scored.sort(key=lambda x: x[0])

            for _, p in scored:
                new_domains = cur[:]
                ok = True
                if best_kind == 'row':
                    off = best_index * n
                    for c, v in enumerate(p):
                        m = 1 << v
                        if (new_domains[off + c] & m) == 0:
                            ok = False
                            break
                        new_domains[off + c] = m
                else:
                    c = best_index
                    for r, v in enumerate(p):
                        i = r * n + c
                        m = 1 << v
                        if (new_domains[i] & m) == 0:
                            ok = False
                            break
                        new_domains[i] = m
                if ok:
                    ans = dfs(new_domains)
                    if ans is not None:
                        return ans
        else:
            i = best_cell
            r, c = divmod(i, n)
            vals = values_of(cur[i])

            if use_perms:
                freq = {}
                for v in vals:
                    fr = 0
                    for rp in row_valid[r]:
                        if rp[c] == v:
                            fr += 1
                    fc = 0
                    for cp in col_valid[c]:
                        if cp[r] == v:
                            fc += 1
                    freq[v] = fr * fc
                vals.sort(key=lambda v: (freq[v], v))

            for v in vals:
                new_domains = cur[:]
                new_domains[i] = 1 << v
                ans = dfs(new_domains)
                if ans is not None:
                    return ans

        dead.add(state)
        return None

    return dfs(domains0)


def solve(observation):
    vertical = observation.get('vertical', {})
    tried = []

    # Common convention first:
    # '^' means top < bottom, 'v' means top > bottom.
    for convention in (True, False) if vertical else (True,):
        grid = _solve_one(observation, convention)
        if grid is not None:
            t = tuple(tuple(row) for row in grid)
            if t not in tried:
                tried.append(t)

    if not tried:
        return "No Solution"
    return str([list(row) for row in tried[0]])


