import ast
from itertools import combinations, permutations


class FutoshikiSolver:
    def __init__(self, observation, up_is_less=True):
        self.data = observation["data"]
        self.n = len(self.data)
        self.size = self.n * self.n
        self.up_is_less = up_is_less

        self.row_of = [i // self.n for i in range(self.size)]
        self.col_of = [i % self.n for i in range(self.size)]
        self.rows = [tuple(r * self.n + c for c in range(self.n)) for r in range(self.n)]
        self.cols = [tuple(r * self.n + c for r in range(self.n)) for c in range(self.n)]
        self.units = self.rows + self.cols

        self.val_masks = [0] + [1 << (v - 1) for v in range(1, self.n + 1)]
        self.full_mask = (1 << self.n) - 1

        # Masks for values < v and > v.
        self.lt_masks = [0] * (self.n + 1)
        running = 0
        for v in range(1, self.n + 1):
            self.lt_masks[v] = running
            running |= self.val_masks[v]

        self.gt_masks = [0] * (self.n + 1)
        running = 0
        for v in range(self.n, 0, -1):
            self.gt_masks[v] = running
            running |= self.val_masks[v]

        self.row_signs = [[] for _ in range(self.n)]
        self.col_signs = [[] for _ in range(self.n)]
        self.inequalities = []
        self._build_inequalities(observation)

        self.peers = []
        for idx in range(self.size):
            r = self.row_of[idx]
            c = self.col_of[idx]
            ps = set(self.rows[r]) | set(self.cols[c])
            ps.remove(idx)
            self.peers.append(tuple(ps))

        self.ineq_adj = [[] for _ in range(self.size)]
        self.less_graph = [[] for _ in range(self.size)]
        self.more_graph = [[] for _ in range(self.size)]
        for a, b, rel in self.inequalities:
            self.ineq_adj[a].append((b, rel))
            self.ineq_adj[b].append((a, -rel))
            if rel < 0:
                self.less_graph[a].append(b)
                self.more_graph[b].append(a)
            else:
                self.less_graph[b].append(a)
                self.more_graph[a].append(b)

        self.invalid = False
        self.initial_masks = self._compute_chain_masks()
        self.use_patterns = self._should_use_patterns()
        self.row_patterns = []
        self.col_patterns = []
        if self.use_patterns:
            self._build_patterns()

    def _should_use_patterns(self):
        fact = 1
        for x in range(2, self.n + 1):
            fact *= x
        return fact <= 5040

    def _parse_key(self, key):
        if isinstance(key, str):
            return ast.literal_eval(key)
        return key

    def _idx(self, r, c):
        return r * self.n + c

    def _build_inequalities(self, observation):
        for key, sym in observation.get("horizontal", {}).items():
            r, ch = self._parse_key(key)
            r = int(round(r))
            c = int(round(ch - 0.5))
            a = self._idx(r, c)
            b = self._idx(r, c + 1)
            rel = -1 if sym == "<" else 1
            self.inequalities.append((a, b, rel))
            self.row_signs[r].append((c, rel))

        for key, sym in observation.get("vertical", {}).items():
            rh, c = self._parse_key(key)
            r = int(round(rh - 0.5))
            c = int(round(c))
            a = self._idx(r, c)
            b = self._idx(r + 1, c)
            if sym == "^":
                rel = -1 if self.up_is_less else 1
            else:
                rel = 1 if self.up_is_less else -1
            self.inequalities.append((a, b, rel))
            self.col_signs[c].append((r, rel))

    def _longest_paths(self, graph):
        memo = [-1] * self.size
        state = [0] * self.size

        def dfs(u):
            if state[u] == 1:
                raise ValueError("cycle")
            if state[u] == 2:
                return memo[u]
            state[u] = 1
            best = 0
            for v in graph[u]:
                best = max(best, 1 + dfs(v))
            state[u] = 2
            memo[u] = best
            return best

        for u in range(self.size):
            if state[u] == 0:
                dfs(u)
        return memo

    def _range_mask(self, lo, hi):
        mask = 0
        for v in range(lo, hi + 1):
            mask |= self.val_masks[v]
        return mask

