        try:
            larger_depth = self._longest_paths(self.less_graph)
            smaller_depth = self._longest_paths(self.more_graph)
        except ValueError:
            self.invalid = True
            return [0] * self.size

        masks = [self.full_mask] * self.size
        for i in range(self.size):
            lo = 1 + smaller_depth[i]
            hi = self.n - larger_depth[i]
            if lo > hi:
                self.invalid = True
                return [0] * self.size
            masks[i] = self._range_mask(lo, hi)
        return masks

    def _build_patterns(self):
        all_perms = list(permutations(range(1, self.n + 1)))

        self.row_patterns = [[] for _ in range(self.n)]
        for r in range(self.n):
            rules = self.row_signs[r]
            kept = []
            for perm in all_perms:
                ok = True
                for c, rel in rules:
                    if rel < 0:
                        if not (perm[c] < perm[c + 1]):
                            ok = False
                            break
                    else:
                        if not (perm[c] > perm[c + 1]):
                            ok = False
                            break
                if ok:
                    kept.append(perm)
            self.row_patterns[r] = kept

        self.col_patterns = [[] for _ in range(self.n)]
        for c in range(self.n):
            rules = self.col_signs[c]
            kept = []
            for perm in all_perms:
                ok = True
                for r, rel in rules:
                    if rel < 0:
                        if not (perm[r] < perm[r + 1]):
                            ok = False
                            break
                    else:
                        if not (perm[r] > perm[r + 1]):
                            ok = False
                            break
                if ok:
                    kept.append(perm)
            self.col_patterns[c] = kept

    def _filter_patterns(self, domains, unit, patterns):
        pos_masks = [0] * self.n
        any_pattern = False

        for perm in patterns:
            ok = True
            for p, idx in enumerate(unit):
                if not (domains[idx] & self.val_masks[perm[p]]):
                    ok = False
                    break
            if not ok:
                continue
            any_pattern = True
            for p, v in enumerate(perm):
                pos_masks[p] |= self.val_masks[v]

        if not any_pattern:
            return None

        changed = False
        for p, idx in enumerate(unit):
            new_mask = domains[idx] & pos_masks[p]
            if new_mask == 0:
                return None
            if new_mask != domains[idx]:
                domains[idx] = new_mask
                changed = True
        return changed

    def _propagate_unit(self, domains, unit):
        # Rule 1: fixed values exclude the same value from peers in the unit.
        fixed = 0
        changed = False
        for idx in unit:
            m = domains[idx]
            if m == 0:
                return None
            if m & (m - 1) == 0:
                if fixed & m:
                    return None
                fixed |= m

        for idx in unit:
            m = domains[idx]
            if m & (m - 1):
