        candidates = [idx for idx in unit if 2 <= domains[idx].bit_count() <= 4]
        for k in range(2, min(4, len(candidates)) + 1):
            for combo in combinations(candidates, k):
                union = 0
                for idx in combo:
                    union |= domains[idx]
                if union.bit_count() == k:
                    combo_set = set(combo)
                    local_change = False
                    for idx in unit:
