                            if new_mask == 0:
                                return None
                            if new_mask != domains[idx]:
                                domains[idx] = new_mask
                                local_change = True
                    if local_change:
                        return True

        # Rule 4: hidden pairs/triples.
        limited_vals = [v for v in range(1, self.n + 1) if 2 <= counts[v] <= 3]
        for k in range(2, min(3, len(limited_vals)) + 1):
            for vals in combinations(limited_vals, k):
                cell_set = set()
                for v in vals:
                    cell_set.update(positions[v])
