                rel = rels[pos - 1]
                if rel == "<":
                    cand &= self.gt_mask[last]
                elif rel == ">":
                    cand &= self.lt_mask[last]

            good = 0
            m = cand
            while m:
                bit = m & -m
                v = bit.bit_length()
                if choices(pos + 1, used | bit, v):
                    good |= bit
                m ^= bit

            memo[key] = good
            return good

        if not choices(0, 0, 0):
            self.line_cache[cache_key] = ()
            return None

        supports = [0] * n
        seen = set()

        def collect(pos, used, last):
            if pos == n:
                return
            key = (pos, used, last)
            if key in seen:
                return
            seen.add(key)

            good = choices(pos, used, last)
            supports[pos] |= good

            m = good
            while m:
                bit = m & -m
                v = bit.bit_length()
                collect(pos + 1, used | bit, v)
                m ^= bit

        collect(0, 0, 0)
        self.line_cache[cache_key] = tuple(supports)
        return supports

    def _apply_line_filters(self, domains):
        changed = False

        for r, unit in enumerate(self.rows):
            doms = [domains[cell] for cell in unit]
            supports = self._line_supports(doms, self.row_rels[r])
            if supports is None:
                return False, changed
            for i, cell in enumerate(unit):
                nm = domains[cell] & supports[i]
                if nm == 0:
                    return False, changed
                if nm != domains[cell]:
                    domains[cell] = nm
                    changed = True

        for c, unit in enumerate(self.cols):
            doms = [domains[cell] for cell in unit]
            supports = self._line_supports(doms, self.col_rels[c])
            if supports is None:
                return False, changed
            for i, cell in enumerate(unit):
                nm = domains[cell] & supports[i]
                if nm == 0:
                    return False, changed
                if nm != domains[cell]:
                    domains[cell] = nm
                    changed = True

        return True, changed

    def propagate(self, domains):
        while True:
            for m in domains:
                if m == 0:
                    return None

            any_change = False

            ok, changed = self._apply_unit_basics(domains)
            if not ok:
                return None
            any_change |= changed

            ok, changed = self._apply_inequalities(domains)
            if not ok:
                return None
            any_change |= changed

            ok, changed = self._apply_line_filters(domains)
            if not ok:
                return None
            any_change |= changed

            if not any_change:
                return domains

    def _ordered_values(self, cell, domains):
        mask = domains[cell]
        values = []

        m = mask
        while m:
            bit = m & -m
            v = bit.bit_length()

            score = 0

            # Row/column uniqueness pressure.
            for peer in self.peers[cell]:
                if domains[peer] & bit:
                    score += 1

            # Inequality pressure.
            not_gt_v = self.full_mask ^ self.gt_mask[v]
            for nb in self.adj[cell]:
                score += (domains[nb] & not_gt_v).bit_count()

            not_lt_v = self.full_mask ^ self.lt_mask[v]
            for nb in self.rev[cell]:
                score += (domains[nb] & not_lt_v).bit_count()

            values.append((score, v, bit))
            m ^= bit

        values.sort(key=lambda x: (x[0], x[1]))
        return [bit for _, _, bit in values]

    def search(self, domains):
        domains = self.propagate(domains)
        if domains is None:
            return None

        state = tuple(domains)
        if state in self.fail_cache:
            return None

        unsolved = [i for i, m in enumerate(domains) if not self._is_single(m)]
        if not unsolved:
            return domains

        cell = min(
            unsolved,
            key=lambda i: (domains[i].bit_count(), -self.ineq_degree[i])
        )

        for bit in self._ordered_values(cell, domains):
            new_domains = domains[:]
            new_domains[cell] = bit
            result = self.search(new_domains)
            if result is not None:
                return result

        self.fail_cache.add(state)
        return None

    def domains_to_grid(self, domains):
        grid = []
        idx = 0
        for _ in range(self.N):
            row = []
            for _ in range(self.N):
                m = domains[idx]
                if not self._is_single(m):
                    return None
                row.append(m.bit_length())
                idx += 1
            grid.append(row)
        return grid

    def _check_solution(self, grid):
        for row in grid:
            if sorted(row) != self.target:
                return False

        for c in range(self.N):
            col = sorted(grid[r][c] for r in range(self.N))
            if col != self.target:
                return False

        for small, large in self.edges:
            sr, sc = divmod(small, self.N)
            lr, lc = divmod(large, self.N)
            if not (grid[sr][sc] < grid[lr][lc]):
                return False

        return True

    def solve_grid(self):
        if not self.valid:
            return None
        domains = self.initial_domains()
        if domains is None:
            return None
        result = self.search(domains)
        if result is None:
            return None
        grid = self.domains_to_grid(result)
        if grid is None or not self._check_solution(grid):
            return None
        return grid


def solve(observation):
    # Vertical symbols in image-based Futoshiki instances are sometimes ambiguous.
    # Try the most common convention first:
    # '^' => upper < lower, 'v' => upper > lower
    candidates = []

    for vertical_map in ({'^': '<', 'v': '>'}, {'^': '>', 'v': '<'}):
        solver = FutoshikiSolver(observation, vertical_map)
        grid = solver.solve_grid()
        if grid is not None and grid not in candidates:
            candidates.append(grid)

    if not candidates:
        return "No Solution"
    return str(candidates[0])


