import ast
import sys
from collections import deque

sys.setrecursionlimit(10000)


class Context:
    __slots__ = (
        'N', 'M', 'ALL', 'prefix',
        'rows', 'cols', 'units',
        'row_of', 'col_of', 'peers',
        'rank_masks', 'less_pairs',
        'in_less', 'out_less',
        'constraint_degree',
        'value_bits', 'subset_masks'
    )


def is_single(mask):
    return mask != 0 and (mask & (mask - 1)) == 0


def build_context(observation, vertical_mode=0):
    # vertical_mode 0:
    #   'v' means upper < lower
    #   '^' means upper > lower
    # vertical_mode 1 is the opposite fallback
    data = observation['data']
    N = len(data)
    M = N * N
    ALL = (1 << N) - 1

    prefix = [0] * (N + 1)
    for v in range(1, N + 1):
        prefix[v] = (1 << v) - 1

    rows = tuple(tuple(r * N + c for c in range(N)) for r in range(N))
    cols = tuple(tuple(r * N + c for r in range(N)) for c in range(N))
    units = rows + cols

    row_of = [i // N for i in range(M)]
    col_of = [i % N for i in range(M)]

    peers = []
    for i in range(M):
        s = set(rows[row_of[i]])
        s.update(cols[col_of[i]])
        s.discard(i)
        peers.append(tuple(sorted(s)))
    peers = tuple(peers)

    edge_set = set()

    def add_less(a, b):
        if a == b:
            return
        edge_set.add((a, b))

    for key, sym in observation.get('horizontal', {}).items():
        r, x = ast.literal_eval(key)
        r = int(r)
        left = int(round(float(x) - 0.5))
        right = left + 1
        a = r * N + left
        b = r * N + right
        if sym == '<':
            add_less(a, b)
        elif sym == '>':
            add_less(b, a)

    for key, sym in observation.get('vertical', {}).items():
        x, c = ast.literal_eval(key)
        top = int(round(float(x) - 0.5))
        c = int(c)
        a = top * N + c
        b = (top + 1) * N + c
        if vertical_mode == 0:
            if sym == 'v':
                add_less(a, b)
            elif sym == '^':
                add_less(b, a)
        else:
            if sym == 'v':
                add_less(b, a)
            elif sym == '^':
                add_less(a, b)

    direct_adj = [[] for _ in range(M)]
    indeg = [0] * M
    for a, b in edge_set:
        direct_adj[a].append(b)
        indeg[b] += 1
    direct_adj = [tuple(sorted(vs)) for vs in direct_adj]

    # Topological order for inequality DAG
    dq = deque(i for i in range(M) if indeg[i] == 0)
    topo = []
    indeg_work = indeg[:]
    while dq:
        u = dq.popleft()
        topo.append(u)
        for v in direct_adj[u]:
            indeg_work[v] -= 1
            if indeg_work[v] == 0:
                dq.append(v)

    if len(topo) != M:
        return None

    # Static chain bounds: longest path into/out of each cell
    pred_depth = [0] * M
    for u in topo:
        du = pred_depth[u]
        for v in direct_adj[u]:
            nv = du + 1
            if nv > pred_depth[v]:
                pred_depth[v] = nv

    succ_depth = [0] * M
    for u in reversed(topo):
        best = 0
        for v in direct_adj[u]:
            cand = succ_depth[v] + 1
            if cand > best:
                best = cand
        succ_depth[u] = best

    rank_masks = [0] * M
    for i in range(M):
        lo = pred_depth[i] + 1
        hi = N - succ_depth[i]
        if lo > hi:
            return None
        rank_masks[i] = prefix[hi] & ~prefix[lo - 1]

    # Transitive closure of inequalities, using reverse topological accumulation
    reach = [0] * M
    for u in reversed(topo):
        mask = 0
        for v in direct_adj[u]:
            mask |= (1 << v) | reach[v]
        reach[u] = mask

    less_pairs = []
    in_less = [0] * M
    out_less = [0] * M
    for u in range(M):
        mask = reach[u]
        count = 0
        while mask:
            vb = mask & -mask
            v = vb.bit_length() - 1
            less_pairs.append((u, v))
            in_less[v] += 1
            count += 1
            mask ^= vb
        out_less[u] = count
    less_pairs = tuple(less_pairs)

    value_bits = tuple(1 << i for i in range(N))
    subset_limit = min(4, N - 1)
    subset_masks = tuple(
        mask
        for mask in range(1, ALL + 1)
        if 2 <= mask.bit_count() <= subset_limit
    )

    constraint_degree = [
        len(peers[i]) + in_less[i] + out_less[i]
        for i in range(M)
    ]

    ctx = Context()
    ctx.N = N
    ctx.M = M
    ctx.ALL = ALL
    ctx.prefix = prefix
    ctx.rows = rows
    ctx.cols = cols
    ctx.units = units
    ctx.row_of = row_of
    ctx.col_of = col_of
    ctx.peers = peers
    ctx.rank_masks = tuple(rank_masks)
    ctx.less_pairs = less_pairs
    ctx.in_less = tuple(in_less)
    ctx.out_less = tuple(out_less)
    ctx.constraint_degree = tuple(constraint_degree)
    ctx.value_bits = value_bits
    ctx.subset_masks = subset_masks
    return ctx


def initialize_domains(observation, ctx):
    domains = list(ctx.rank_masks)
    for r, row in enumerate(observation['data']):
        for c, value in enumerate(row):
            if value is None:
                continue
            bit = 1 << (value - 1)
            idx = r * ctx.N + c
            if domains[idx] & bit == 0:
                return None
            domains[idx] = bit
    return domains


def human_unit_sweep(domains, unit, ctx):
    changed = False

    # Fixed values remove themselves from peers in the unit
    seen = 0
    for i in unit:
        d = domains[i]
        if d == 0:
            return False, False
        if is_single(d):
            if seen & d:
                return False, False
            seen |= d

    if seen:
        for i in unit:
            d = domains[i]
            if not is_single(d):
                nd = d & ~seen
                if nd == 0:
                    return False, False
                if nd != d:
                    domains[i] = nd
                    changed = True

    # Hidden singles
    for bit in ctx.value_bits:
        places = []
        for i in unit:
            if domains[i] & bit:
                places.append(i)
        if not places:
            return False, False
        if len(places) == 1:
            i = places[0]
            if domains[i] != bit:
                domains[i] = bit
                changed = True

    # Naked subsets (pairs/triples/quads)
    for mask in ctx.subset_masks:
        k = mask.bit_count()
        if k >= len(unit):
            continue
        subset_cells = []
        for i in unit:
            if domains[i] & ~mask == 0:
                subset_cells.append(i)
        if len(subset_cells) == k:
            subset_cells = set(subset_cells)
            for i in unit:
                if i not in subset_cells and (domains[i] & mask):
                    nd = domains[i] & ~mask
                    if nd == 0:
                        return False, False
                    if nd != domains[i]:
                        domains[i] = nd
                        changed = True

    # Hidden subsets (pairs/triples/quads)
    for mask in ctx.subset_masks:
        k = mask.bit_count()
        if k >= len(unit):
            continue
        cells = []
        union = 0
        for i in unit:
            if domains[i] & mask:
                cells.append(i)
                union |= domains[i] & mask
        if len(cells) == k and union == mask:
            for i in cells:
                nd = domains[i] & mask
                if nd == 0:
                    return False, False
                if nd != domains[i]:
                    domains[i] = nd
                    changed = True

    return changed, True


def enforce_alldiff_gac(domains, unit, ctx):
    # Exact row/column feasibility via DP over used digits.
    # This is strong pruning and still small because typical futoshiki sizes are small.
    changed = False
    m = len(unit)
    ALL = ctx.ALL

    forward = [0] * (m + 1)
    forward[0] = 1  # state-set containing only used-mask 0

    for pos in range(m):
        cell = unit[pos]
        states = forward[pos]
        nxt = 0
        while states:
            one = states & -states
            used = one.bit_length() - 1
            states ^= one
            bits = domains[cell] & ~used
            while bits:
                bit = bits & -bits
                bits ^= bit
                nxt |= 1 << (used | bit)
        if nxt == 0:
            return False, False
        forward[pos + 1] = nxt

    if ((forward[m] >> ALL) & 1) == 0:
        return False, False

    backward = [0] * (m + 1)
    backward[m] = 1  # suffix uses no digits

    for pos in range(m - 1, -1, -1):
        cell = unit[pos]
        states = backward[pos + 1]
        prev = 0
        while states:
            one = states & -states
            used = one.bit_length() - 1
            states ^= one
            bits = domains[cell] & ~used
            while bits:
                bit = bits & -bits
                bits ^= bit
                prev |= 1 << (used | bit)
        if prev == 0:
            return False, False
        backward[pos] = prev

    for pos in range(m):
        cell = unit[pos]
        supported = 0
        states = forward[pos]
        while states:
            one = states & -states
            prefix_used = one.bit_length() - 1
            states ^= one
            bits = domains[cell] & ~prefix_used
            while bits:
                bit = bits & -bits
                bits ^= bit
                rem = ALL ^ (prefix_used | bit)
                if (backward[pos + 1] >> rem) & 1:
                    supported |= bit

        nd = domains[cell] & supported
        if nd == 0:
            return False, False
        if nd != domains[cell]:
            domains[cell] = nd
            changed = True

    return changed, True


def propagate(domains, ctx):
    while True:
        changed = False

        for d in domains:
            if d == 0:
                return False

        # Inequality arc consistency on all direct+transitive less-than relations
        for a, b in ctx.less_pairs:
            da = domains[a]
            db = domains[b]

            max_b = db.bit_length()
            nda = da & ctx.prefix[max_b - 1]
            if nda == 0:
                return False
            if nda != da:
                domains[a] = nda
                da = nda
                changed = True

            min_a = (da & -da).bit_length()
            ndb = db & (ctx.ALL ^ ctx.prefix[min_a])
            if ndb == 0:
                return False
            if ndb != db:
                domains[b] = ndb
                changed = True

        # Human-style row/column deductions
        for unit in ctx.units:
            ch, ok = human_unit_sweep(domains, unit, ctx)
            if not ok:
                return False
            if ch:
                changed = True

        # Exact all-different consistency on every row/column
        for unit in ctx.units:
            ch, ok = enforce_alldiff_gac(domains, unit, ctx)
            if not ok:
                return False
            if ch:
                changed = True

        if not changed:
            return True


def solved(domains):
    return all(is_single(d) for d in domains)


def select_cell(domains, ctx):
    best_cell = -1
    best_key = None
    for i, d in enumerate(domains):
        bc = d.bit_count()
        if bc <= 1:
            continue
        key = (bc, -ctx.constraint_degree[i], ctx.row_of[i], ctx.col_of[i])
        if best_key is None or key < best_key:
            best_key = key
            best_cell = i
    return best_cell


def ordered_bits(domains, cell, ctx):
    row = ctx.rows[ctx.row_of[cell]]
    col = ctx.cols[ctx.col_of[cell]]
    bits = domains[cell]
    choices = []

    while bits:
        bit = bits & -bits
        bits ^= bit
        value = bit.bit_length()

        # Prefer values that are scarcer in the row/column,
        # and values that naturally fit inequality direction.
        peer_support = 0
        for j in row:
            if j != cell and (domains[j] & bit):
                peer_support += 1
        for j in col:
            if j != cell and (domains[j] & bit):
                peer_support += 1

        score = peer_support
        score += ctx.out_less[cell] * value
        score += ctx.in_less[cell] * (ctx.N + 1 - value)

        choices.append((score, value, bit))

    choices.sort()
    return [bit for _, _, bit in choices]


def search(domains, ctx, failed):
    if not propagate(domains, ctx):
        return None

    state = tuple(domains)
    if state in failed:
        return None

    if solved(domains):
        return domains

    cell = select_cell(domains, ctx)
    if cell < 0:
        return None

    for bit in ordered_bits(domains, cell, ctx):
        new_domains = domains.copy()
        new_domains[cell] = bit
        result = search(new_domains, ctx, failed)
        if result is not None:
            return result

    failed.add(state)
    return None


def domains_to_grid(domains, N):
    return [
        [domains[r * N + c].bit_length() for c in range(N)]
        for r in range(N)
    ]


def solve_with_convention(observation, vertical_mode):
    ctx = build_context(observation, vertical_mode)
    if ctx is None:
        return None

    domains = initialize_domains(observation, ctx)
    if domains is None:
        return None

    result = search(domains, ctx, set())
    if result is None:
        return None

    return domains_to_grid(result, ctx.N)


def solve(observation):
    # Preferred convention from the puzzle image:
    # 'v' => upper < lower, '^' => upper > lower
    ans = solve_with_convention(observation, 0)
    if ans is not None:
        return ans

    # Fallback in case a different vertical convention is used
    ans = solve_with_convention(observation, 1)
    if ans is not None:
        return ans

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

