def _parse_pair(key):
    if isinstance(key, str):
        s = key.strip()
        if s.startswith("(") and s.endswith(")"):
            s = s[1:-1]
        a, b = s.split(",")
        return float(a.strip()), float(b.strip())
    return float(key[0]), float(key[1])


def build_edges(observation, h_direct=True, v_caret_less=True):
    n = len(observation["data"])

    def idx(r, c):
        return r * n + c

    edges = []
    seen = set()

    for key, sym in observation.get("horizontal", {}).items():
        row_f, mid_f = _parse_pair(key)
        r = int(round(row_f))
        c = int(round(mid_f - 0.5))
        if not (0 <= r < n and 0 <= c < n - 1):
            return None
        if sym == "<":
            left_less = h_direct
        elif sym == ">":
            left_less = not h_direct
        else:
            continue
        pair = (idx(r, c), idx(r, c + 1)) if left_less else (idx(r, c + 1), idx(r, c))
        if pair not in seen:
            seen.add(pair)
            edges.append(pair)

    for key, sym in observation.get("vertical", {}).items():
        mid_f, col_f = _parse_pair(key)
        r = int(round(mid_f - 0.5))
        c = int(round(col_f))
        if not (0 <= r < n - 1 and 0 <= c < n):
            return None
        if sym == "^":
            top_less = v_caret_less
        elif sym == "v":
            top_less = not v_caret_less
        else:
            continue
        pair = (idx(r, c), idx(r + 1, c)) if top_less else (idx(r + 1, c), idx(r, c))
        if pair not in seen:
            seen.add(pair)
            edges.append(pair)

    return edges


def validate_solution(grid, observation, h_direct=True, v_caret_less=True):
    n = len(grid)
    target = set(range(1, n + 1))

    for r in range(n):
        if set(grid[r]) != target:
            return False
    for c in range(n):
        if {grid[r][c] for r in range(n)} != target:
            return False

    for r in range(n):
        for c in range(n):
            given = observation["data"][r][c]
            if given is not None and grid[r][c] != given:
                return False

    edges = build_edges(observation, h_direct=h_direct, v_caret_less=v_caret_less)
    if edges is None:
        return False

    for a, b in edges:
        ra, ca = divmod(a, n)
        rb, cb = divmod(b, n)
        if not (grid[ra][ca] < grid[rb][cb]):
            return False

    return True


