        vals = [SINGLETON_VALUE[m] for m in result_masks]
        items = sorted(
            ((self.edge_keys[e], vals[e]) for e in range(len(self.ends)) if vals[e] > 0),
            key=lambda kv: kv[0],
        )
        return {k: v for k, v in items}


