                continue
            cu = comp[u]
            cv = comp[v]
            if cu == cv:
                continue
            ext[cu].add(e)
            ext[cv].add(e)
            if cu > cv:
                cu, cv = cv, cu
            pair_to_edges[(cu, cv)].append(e)

        # If a currently separate component has no route out, impossible.
        # If it has exactly one route out, that route must be used.
        for cid in range(k):
            if not ext[cid]:
                return False, False
            if len(ext[cid]) == 1:
                e = next(iter(ext[cid]))
                if lb[e] < 1:
                    lb[e] = 1
                    if lb[e] > ub[e]:
                        return False, False
                    changed = True

        # Bridge rule on the supergraph of current positive components:
        # any sole superedge that is a graph bridge must carry at least one bridge.
        if pair_to_edges:
            adj = [[] for _ in range(k)]
            for pair, edges in pair_to_edges.items():
                a, b = pair
                mult = len(edges)
                adj[a].append((b, pair, mult))
                adj[b].append((a, pair, mult))

            disc = [-1] * k
            low = [0] * k
            time = 0
            bridges = []

            def dfs(u, parent_pair):
                nonlocal time
                disc[u] = low[u] = time
                time += 1
                for v, pair, mult in adj[u]:
                    if disc[v] == -1:
                        dfs(v, pair)
                        if low[v] < low[u]:
                            low[u] = low[v]
                        if low[v] > disc[u] and mult == 1:
                            bridges.append(pair)
                    elif pair != parent_pair and disc[v] < low[u]:
                        low[u] = disc[v]

            dfs(0, None)

            for pair in bridges:
                e = pair_to_edges[pair][0]
                if lb[e] < 1:
                    lb[e] = 1
                    if lb[e] > ub[e]:
                        return False, False
                    changed = True

        return True, changed

    def propagate(self, lb, ub):
        while True:
            changed = False

            # Per-island degree feasibility and bound tightening.
            for i in range(self.island_count):
                inc = self.incident[i]
                t = self.target[i]

                s_lb = 0
                s_ub = 0
                for e in inc:
                    s_lb += lb[e]
                    s_ub += ub[e]

                if t < s_lb or t > s_ub:
                    return None

                for e in inc:
                    new_lb = max(lb[e], t - (s_ub - ub[e]))
                    new_ub = min(ub[e], t - (s_lb - lb[e]))
                    if new_lb > new_ub:
                        return None
                    if new_lb != lb[e]:
                        lb[e] = new_lb
                        changed = True
                    if new_ub != ub[e]:
                        ub[e] = new_ub
                        changed = True

            # Crossing elimination.
            for e in range(self.edge_count):
                if lb[e] > ub[e]:
                    return None
                if lb[e] > 0:
                    for f in self.crosses[e]:
                        if lb[f] > 0:
                            return None
                        if ub[f] != 0:
                            ub[f] = 0
                            changed = True

            ok, comp_changed = self.component_rules(lb, ub)
            if not ok:
                return None
            if comp_changed:
                changed = True

            if not changed:
                break

        return lb, ub

    def is_complete(self, lb, ub):
        for e in range(self.edge_count):
            if lb[e] != ub[e]:
                return False
        for i in range(self.island_count):
            total = 0
            for e in self.incident[i]:
                total += lb[e]
            if total != self.target[i]:
                return False
        return self.exact_connected(lb)

    def choose_edge(self, lb, ub):
        comp, comps = self.positive_components(lb)
        comp_ext_count = [0] * len(comps)

        if len(comps) > 1:
            seen_per_comp = [set() for _ in range(len(comps))]
            for e, (u, v) in enumerate(self.edge_ends):
                if ub[e] <= 0:
                    continue
                cu = comp[u]
                cv = comp[v]
                if cu != cv:
                    seen_per_comp[cu].add(e)
                    seen_per_comp[cv].add(e)
            for cid in range(len(comps)):
                comp_ext_count[cid] = len(seen_per_comp[cid])

        s_lb, s_ub = self.island_sum_bounds(lb, ub)
        best_e = None
        best_key = None

        for e, (u, v) in enumerate(self.edge_ends):
            if lb[e] == ub[e]:
                continue

            size = ub[e] - lb[e] + 1
            inter_comp = 0 if comp[u] != comp[v] else 1
            slack = (s_ub[u] - s_lb[u]) + (s_ub[v] - s_lb[v])
            ext_score = (
                comp_ext_count[comp[u]] + comp_ext_count[comp[v]]
                if comp[u] != comp[v]
                else 999999
            )
            key = (
                size,
                inter_comp,
                slack,
                ext_score,
                -self.cross_count[e],
                -(self.target[u] + self.target[v]),
            )
            if best_key is None or key < best_key:
                best_key = key
                best_e = e

        return best_e, comp, s_lb, s_ub

    def branch_values(self, e, lb, ub, comp, s_lb, s_ub):
        vals = list(range(lb[e], ub[e] + 1))
        u, v = self.edge_ends[e]
        compdiff = comp[u] != comp[v]

        rem_u = self.target[u] - s_lb[u]
        rem_v = self.target[v] - s_lb[v]
        room_u = s_ub[u] - s_lb[u]
        room_v = s_ub[v] - s_lb[v]

        pressure_u = (rem_u / room_u) if room_u > 0 else 0.0
        pressure_v = (rem_v / room_v) if room_v > 0 else 0.0
        prefer_high = (pressure_u + pressure_v) >= 1.2

        if compdiff:
            pos = [x for x in vals if x > 0]
            zero = [x for x in vals if x == 0]
            if prefer_high:
                pos.sort(reverse=True)
            else:
                pos.sort(key=lambda x: (x != 1, -x))
            return pos + zero

        if prefer_high:
            return sorted(vals, reverse=True)
        return sorted(vals)

    def search(self, lb, ub):
        propagated = self.propagate(lb, ub)
        if propagated is None:
            return None

        lb, ub = propagated
        state = (tuple(lb), tuple(ub))
        if state in self.failed:
            return None

        if self.is_complete(lb, ub):
            return lb

        e, comp, s_lb, s_ub = self.choose_edge(lb, ub)
        if e is None:
            self.failed.add(state)
            return None

        for val in self.branch_values(e, lb, ub, comp, s_lb, s_ub):
            nlb = lb[:]
            nub = ub[:]
            nlb[e] = val
            nub[e] = val
            ans = self.search(nlb, nub)
            if ans is not None:
                return ans

        self.failed.add(state)
        return None

    def format_answer(self, values):
        ans = {}
        for e, cnt in enumerate(values):
            if cnt > 0:
                u, v = self.edge_ends[e]
                ans[(self.coords[u], self.coords[v])] = cnt
        return ans

    def solve(self):
        if self.island_count == 0:
            return {}

        # Fast global impossibility checks.
        if sum(self.target) % 2 != 0:
            return None

        for i in range(self.island_count):
            if self.target[i] > 2 * len(self.incident[i]):
                return None
            if self.target[i] > 0 and not self.incident[i]:
                return None

        lb, ub = self.initial_bounds()
        ans = self.search(lb, ub)
        if ans is None:
            return None
        return self.format_answer(ans)


def solve(observation):
    result = HashiSolver(observation).solve()
    if result is None:
        return "No Solution"
    return repr(result)


