        return True


class HashiSolver:
    # Human-like solver:
    # 1) build only visible orthogonal candidate bridges
    # 2) propagate exact island totals with exact small DP
    # 3) propagate crossing exclusions
    # 4) enforce global connectivity via mandatory component graph
    # 5) branch only when deductions stall

    def __init__(self, grid):
        self.grid = grid
        self.rows = len(grid)
        self.cols = len(grid[0]) if self.rows else 0

        self.positions = []
        self.targets = []
        self.index_of = {}

        for r in range(self.rows):
            for c in range(self.cols):
                v = grid[r][c]
                if v is not None:
                    idx = len(self.positions)
                    self.positions.append((r, c))
                    self.targets.append(v)
                    self.index_of[(r, c)] = idx

        self.island_count = len(self.positions)
        self.edge_ends = []
        self.incident = [[] for _ in range(self.island_count)]

        self._build_edges()
        self.edge_count = len(self.edge_ends)
        self.crossings = self._build_crossings()

        self.initial_domains = []
        for a, b in self.edge_ends:
            cap = min(2, self.targets[a], self.targets[b])
            self.initial_domains.append((1 << (cap + 1)) - 1)

        self.edge_impact = [0] * self.edge_count
        for e, (a, b) in enumerate(self.edge_ends):
            self.edge_impact[e] = (
                len(self.crossings[e]) * 4
                + len(self.incident[a])
                + len(self.incident[b])
                + self.targets[a]
                + self.targets[b]
            )

        self.dead = set()

    def _build_edges(self):
        for i, (r, c) in enumerate(self.positions):
            # Right neighbor
            cc = c + 1
            while cc < self.cols:
                if self.grid[r][cc] is not None:
                    j = self.index_of[(r, cc)]
                    self._add_edge(i, j)
                    break
                cc += 1

            # Down neighbor
            rr = r + 1
            while rr < self.rows:
                if self.grid[rr][c] is not None:
                    j = self.index_of[(rr, c)]
                    self._add_edge(i, j)
                    break
                rr += 1

    def _add_edge(self, a, b):
        e = len(self.edge_ends)
        self.edge_ends.append((a, b))
        self.incident[a].append(e)
        self.incident[b].append(e)

    def _build_crossings(self):
        crossings = [set() for _ in range(len(self.edge_ends))]
        horizontals = []
        verticals = []

        for e, (a, b) in enumerate(self.edge_ends):
            r1, c1 = self.positions[a]
            r2, c2 = self.positions[b]
            if r1 == r2:
                if c1 > c2:
                    c1, c2 = c2, c1
                horizontals.append((e, r1, c1, c2))
            else:
                if r1 > r2:
                    r1, r2 = r2, r1
                verticals.append((e, c1, r1, r2))

        for eh, hr, hc1, hc2 in horizontals:
            for ev, vc, vr1, vr2 in verticals:
                if hc1 < vc < hc2 and vr1 < hr < vr2:
                    crossings[eh].add(ev)
                    crossings[ev].add(eh)

