        out = 0
        if dom & 1:
            out |= reach
        if dom & 2:
            out |= reach << 1
        if dom & 4:
            out |= reach << 2
        return out

    def _prune_island(self, domains, i):
        edges = self.incident[i]
        target = self.targets[i]

        if not edges:
            return target == 0, False

        d = len(edges)
        prefix = [0] * (d + 1)
        suffix = [0] * (d + 1)
        prefix[0] = 1

        for j, e in enumerate(edges):
            dom = domains[e]
            if dom == 0:
                return False, False
            prefix[j + 1] = self._advance(prefix[j], dom)

        if ((prefix[d] >> target) & 1) == 0:
            return False, False

        suffix[d] = 1
        for j in range(d - 1, -1, -1):
            suffix[j] = self._advance(suffix[j + 1], domains[edges[j]])

        changed = False
        for j, e in enumerate(edges):
            dom = domains[e]
            keep = 0
            pref = prefix[j]
            suff = suffix[j + 1]

            for v in DOM_VALUES[dom]:
                rem = target - v
                if rem < 0:
                    continue
                supported = False
                for s in range(rem + 1):
                    if ((pref >> s) & 1) and ((suff >> (rem - s)) & 1):
                        supported = True
                        break
                if supported:
                    keep |= (1 << v)

            if keep == 0:
                return False, False
            if keep != dom:
                domains[e] = keep
                changed = True

