        low = [0] * comp_count
        timer = [0]
        bridges = set()

        def dfs(u, parent_edge):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            for v, eid in adj[u]:
                if eid == parent_edge:
                    continue
                if disc[v] == -1:
                    dfs(v, eid)
                    if low[v] < low[u]:
                        low[u] = low[v]
                    if low[v] > disc[u]:
                        bridges.add(eid)
                else:
                    if disc[v] < low[u]:
                        low[u] = disc[v]

        for u in range(comp_count):
            if disc[u] == -1:
                dfs(u, -1)

        return bridges

