            return True, False

        dsu = DSU(self.island_count)
        for e, (a, b) in enumerate(self.edge_ends):
            if domains[e] != 0 and (domains[e] & 1) == 0:
                dsu.union(a, b)

        root_to_comp = {}
        comp_of_island = [0] * self.island_count
        for i in range(self.island_count):
