            if r not in root_to_comp:
                root_to_comp[r] = len(root_to_comp)
            comp_of_island[i] = root_to_comp[r]

        comp_count = len(root_to_comp)
        if comp_count == 1:
            return True, False

        adj = [[] for _ in range(comp_count)]
        external = [[] for _ in range(comp_count)]
        any_inter = False

        for e, (a, b) in enumerate(self.edge_ends):
            if domains[e] & POS_MASK:
                ca = comp_of_island[a]
                cb = comp_of_island[b]
                if ca != cb:
                    any_inter = True
                    adj[ca].append((cb, e))
                    adj[cb].append((ca, e))
                    external[ca].append(e)
                    external[cb].append(e)

        if not any_inter:
            return False, False

        # Possible component graph must itself be connected.
        seen = [False] * comp_count
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for v, _ in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        if not all(seen):
            return False, False

        changed = False

        # If a mandatory component has only one possible way out, that bridge must exist.
        for comp in range(comp_count):
            if not external[comp]:
                return False, False
            if len(external[comp]) == 1:
                e = external[comp][0]
                nd = domains[e] & POS_MASK
                if nd == 0:
                    return False, False
                if nd != domains[e]:
                    domains[e] = nd
                    changed = True

        # In the component graph, any graph-bridge is required to be positive.
        bridges = self._component_bridges(comp_count, adj)
        for e in bridges:
            nd = domains[e] & POS_MASK
            if nd == 0:
                return False, False
            if nd != domains[e]:
                domains[e] = nd
                changed = True

        return True, changed

    def _propagate(self, domains):
        while True:
            changed = False

            # Crossing rule: if one bridge is forced positive, all crossers are forced to zero.
            for e in range(self.edge_count):
                dom = domains[e]
                if dom == 0:
                    return False

                forced_cross_positive = False
                for x in self.crossings[e]:
                    if domains[x] != 0 and (domains[x] & 1) == 0:
                        forced_cross_positive = True
                        break

                if forced_cross_positive:
                    nd = dom & 1
                    if nd == 0:
                        return False
                    if nd != dom:
                        domains[e] = nd
                        changed = True

            for e in range(self.edge_count):
                dom = domains[e]
                if dom == 0:
                    return False
                if (dom & 1) == 0:
                    for x in self.crossings[e]:
                        nd = domains[x] & 1
                        if nd == 0:
                            return False
                        if nd != domains[x]:
                            domains[x] = nd
                            changed = True

            # Exact island arithmetic.
            for i in range(self.island_count):
                ok, ch = self._prune_island(domains, i)
                if not ok:
                    return False
                if ch:
                    changed = True

            # Global connectivity.
            ok, ch = self._connectivity_prune(domains)
            if not ok:
                return False
            if ch:
                changed = True

            if not changed:
                return True

    def _is_complete(self, domains):
        for dom in domains:
            if DOM_SIZE[dom] != 1:
                return False

        if self.island_count <= 1:
            return True

        dsu = DSU(self.island_count)
        for e, (a, b) in enumerate(self.edge_ends):
            if DOM_MIN[domains[e]] > 0:
                dsu.union(a, b)

        root = dsu.find(0)
        for i in range(1, self.island_count):
            if dsu.find(i) != root:
                return False
        return True

    def _choose_edge(self, domains):
        best_e = None
        best_key = None
        for e, dom in enumerate(domains):
            size = DOM_SIZE[dom]
            if size > 1:
                key = (size, -self.edge_impact[e])
                if best_key is None or key < best_key:
                    best_key = key
                    best_e = e
        return best_e

    def _branch_values(self, e, domains):
        vals = list(DOM_VALUES[domains[e]])
        vals.sort(key=lambda v: (0 if v > 0 else 1, -v))
        return vals

    def _search(self, domains):
        if not self._propagate(domains):
            return None

        key = tuple(domains)
        if key in self.dead:
            return None

        if self._is_complete(domains):
            return domains

        e = self._choose_edge(domains)
        if e is None:
            self.dead.add(key)
            return None

        for v in self._branch_values(e, domains):
            new_domains = list(domains)
            new_domains[e] = 1 << v
            result = self._search(new_domains)
            if result is not None:
                return result

        self.dead.add(key)
        return None

    def _extract_answer(self, domains):
        items = []
        for e, (a, b) in enumerate(self.edge_ends):
            v = DOM_MIN[domains[e]]
            if v and v > 0:
                p1 = self.positions[a]
                p2 = self.positions[b]
                if p2 < p1:
                    p1, p2 = p2, p1
                items.append(((p1, p2), v))
        items.sort()
        answer = {}
        for k, v in items:
            answer[k] = v
        return answer

    def solve(self):
        result = self._search(list(self.initial_domains))
        if result is None:
            return None
        return self._extract_answer(result)


