                    idx = len(self.positions)
                    self.positions.append((r, c))
                    self.targets.append(v)
                    self.index_of[(r, c)] = idx

        self.island_count = len(self.positions)
        self.edge_ends = []
        self.incident = [[] for _ in range(self.island_count)]

        self._build_edges()
        self.edge_count = len(self.edge_ends)
        self.crossings = self._build_crossings()

        self.initial_domains = []
        for a, b in self.edge_ends:
            cap = min(2, self.targets[a], self.targets[b])
            self.initial_domains.append((1 << (cap + 1)) - 1)

        self.edge_impact = [0] * self.edge_count
        for e, (a, b) in enumerate(self.edge_ends):
            self.edge_impact[e] = (
                len(self.crossings[e]) * 4
                + len(self.incident[a])
                + len(self.incident[b])
                + self.targets[a]
                + self.targets[b]
            )

        self.dead = set()

    def _build_edges(self):
        for i, (r, c) in enumerate(self.positions):
            # Right neighbor
            cc = c + 1
            while cc < self.cols:
                if self.grid[r][cc] is not None:
                    j = self.index_of[(r, cc)]
                    self._add_edge(i, j)
                    break
                cc += 1

            # Down neighbor
            rr = r + 1
            while rr < self.rows:
                if self.grid[rr][c] is not None:
                    j = self.index_of[(rr, c)]
                    self._add_edge(i, j)
                    break
                rr += 1

    def _add_edge(self, a, b):
        e = len(self.edge_ends)
        self.edge_ends.append((a, b))
        self.incident[a].append(e)
        self.incident[b].append(e)

    def _build_crossings(self):
        crossings = [set() for _ in range(len(self.edge_ends))]
        horizontals = []
        verticals = []

        for e, (a, b) in enumerate(self.edge_ends):
            r1, c1 = self.positions[a]
            r2, c2 = self.positions[b]
            if r1 == r2:
                if c1 > c2:
                    c1, c2 = c2, c1
                horizontals.append((e, r1, c1, c2))
            else:
                if r1 > r2:
                    r1, r2 = r2, r1
                verticals.append((e, c1, r1, r2))

        for eh, hr, hc1, hc2 in horizontals:
            for ev, vc, vr1, vr2 in verticals:
                if hc1 < vc < hc2 and vr1 < hr < vr2:
                    crossings[eh].add(ev)
                    crossings[ev].add(eh)

        return [tuple(sorted(s)) for s in crossings]

    @staticmethod
    def _advance(reach, dom):
        out = 0
        if dom & 1:
            out |= reach
        if dom & 2:
            out |= reach << 1
        if dom & 4:
            out |= reach << 2
        return out

    def _prune_island(self, domains, i):
        edges = self.incident[i]
        target = self.targets[i]

        if not edges:
            return target == 0, False

        d = len(edges)
        prefix = [0] * (d + 1)
        suffix = [0] * (d + 1)
        prefix[0] = 1

        for j, e in enumerate(edges):
            dom = domains[e]
            if dom == 0:
                return False, False
            prefix[j + 1] = self._advance(prefix[j], dom)

        if ((prefix[d] >> target) & 1) == 0:
            return False, False

        suffix[d] = 1
        for j in range(d - 1, -1, -1):
            suffix[j] = self._advance(suffix[j + 1], domains[edges[j]])

        changed = False
        for j, e in enumerate(edges):
            dom = domains[e]
            keep = 0
            pref = prefix[j]
            suff = suffix[j + 1]

            for v in DOM_VALUES[dom]:
                rem = target - v
                if rem < 0:
                    continue
                supported = False
                for s in range(rem + 1):
                    if ((pref >> s) & 1) and ((suff >> (rem - s)) & 1):
                        supported = True
                        break
                if supported:
                    keep |= (1 << v)

            if keep == 0:
                return False, False
            if keep != dom:
                domains[e] = keep
                changed = True

        return True, changed

    def _component_bridges(self, comp_count, adj):
        disc = [-1] * comp_count
        low = [0] * comp_count
        timer = [0]
        bridges = set()

        def dfs(u, parent_edge):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            for v, eid in adj[u]:
                if eid == parent_edge:
                    continue
                if disc[v] == -1:
                    dfs(v, eid)
                    if low[v] < low[u]:
                        low[u] = low[v]
                    if low[v] > disc[u]:
                        bridges.add(eid)
                else:
                    if disc[v] < low[u]:
                        low[u] = disc[v]

        for u in range(comp_count):
            if disc[u] == -1:
                dfs(u, -1)

        return bridges

    def _connectivity_prune(self, domains):
        if self.island_count <= 1:
            return True, False

        dsu = DSU(self.island_count)
        for e, (a, b) in enumerate(self.edge_ends):
            if domains[e] != 0 and (domains[e] & 1) == 0:
                dsu.union(a, b)

        root_to_comp = {}
        comp_of_island = [0] * self.island_count
        for i in range(self.island_count):
            r = dsu.find(i)
            if r not in root_to_comp:
                root_to_comp[r] = len(root_to_comp)
            comp_of_island[i] = root_to_comp[r]

        comp_count = len(root_to_comp)
        if comp_count == 1:
            return True, False

        adj = [[] for _ in range(comp_count)]
        external = [[] for _ in range(comp_count)]
        any_inter = False

        for e, (a, b) in enumerate(self.edge_ends):
            if domains[e] & POS_MASK:
                ca = comp_of_island[a]
                cb = comp_of_island[b]
                if ca != cb:
                    any_inter = True
                    adj[ca].append((cb, e))
                    adj[cb].append((ca, e))
                    external[ca].append(e)
                    external[cb].append(e)

        if not any_inter:
            return False, False

        # Possible component graph must itself be connected.
        seen = [False] * comp_count
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for v, _ in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        if not all(seen):
            return False, False

        changed = False

        # If a mandatory component has only one possible way out, that bridge must exist.
        for comp in range(comp_count):
            if not external[comp]:
                return False, False
            if len(external[comp]) == 1:
                e = external[comp][0]
                nd = domains[e] & POS_MASK
                if nd == 0:
                    return False, False
                if nd != domains[e]:
                    domains[e] = nd
                    changed = True

        # In the component graph, any graph-bridge is required to be positive.
        bridges = self._component_bridges(comp_count, adj)
        for e in bridges:
            nd = domains[e] & POS_MASK
            if nd == 0:
                return False, False
            if nd != domains[e]:
                domains[e] = nd
                changed = True

        return True, changed

    def _propagate(self, domains):
        while True:
            changed = False

            # Crossing rule: if one bridge is forced positive, all crossers are forced to zero.
            for e in range(self.edge_count):
                dom = domains[e]
                if dom == 0:
                    return False

                forced_cross_positive = False
                for x in self.crossings[e]:
                    if domains[x] != 0 and (domains[x] & 1) == 0:
                        forced_cross_positive = True
                        break

                if forced_cross_positive:
                    nd = dom & 1
                    if nd == 0:
                        return False
                    if nd != dom:
                        domains[e] = nd
                        changed = True

            for e in range(self.edge_count):
                dom = domains[e]
                if dom == 0:
                    return False
                if (dom & 1) == 0:
                    for x in self.crossings[e]:
                        nd = domains[x] & 1
                        if nd == 0:
                            return False
                        if nd != domains[x]:
                            domains[x] = nd
                            changed = True

            # Exact island arithmetic.
            for i in range(self.island_count):
                ok, ch = self._prune_island(domains, i)
                if not ok:
                    return False
                if ch:
                    changed = True

            # Global connectivity.
            ok, ch = self._connectivity_prune(domains)
            if not ok:
                return False
            if ch:
                changed = True

            if not changed:
                return True

    def _is_complete(self, domains):
        for dom in domains:
            if DOM_SIZE[dom] != 1:
                return False

        if self.island_count <= 1:
            return True

        dsu = DSU(self.island_count)
        for e, (a, b) in enumerate(self.edge_ends):
            if DOM_MIN[domains[e]] > 0:
                dsu.union(a, b)

        root = dsu.find(0)
        for i in range(1, self.island_count):
            if dsu.find(i) != root:
                return False
        return True

    def _choose_edge(self, domains):
        best_e = None
        best_key = None
        for e, dom in enumerate(domains):
            size = DOM_SIZE[dom]
            if size > 1:
                key = (size, -self.edge_impact[e])
                if best_key is None or key < best_key:
                    best_key = key
                    best_e = e
        return best_e

    def _branch_values(self, e, domains):
        vals = list(DOM_VALUES[domains[e]])
        vals.sort(key=lambda v: (0 if v > 0 else 1, -v))
        return vals

    def _search(self, domains):
        if not self._propagate(domains):
            return None

        key = tuple(domains)
        if key in self.dead:
            return None

        if self._is_complete(domains):
            return domains

        e = self._choose_edge(domains)
        if e is None:
            self.dead.add(key)
            return None

        for v in self._branch_values(e, domains):
            new_domains = list(domains)
            new_domains[e] = 1 << v
            result = self._search(new_domains)
            if result is not None:
                return result

        self.dead.add(key)
        return None

    def _extract_answer(self, domains):
        items = []
        for e, (a, b) in enumerate(self.edge_ends):
            v = DOM_MIN[domains[e]]
            if v and v > 0:
                p1 = self.positions[a]
                p2 = self.positions[b]
                if p2 < p1:
                    p1, p2 = p2, p1
                items.append(((p1, p2), v))
        items.sort()
        answer = {}
        for k, v in items:
            answer[k] = v
        return answer

    def solve(self):
        result = self._search(list(self.initial_domains))
        if result is None:
            return None
        return self._extract_answer(result)


def solve(observation):
    sys.setrecursionlimit(10000)
    grid = observation["data"]
    solver = HashiSolver(grid)
    answer = solver.solve()
    if answer is None:
        return "No Solution"
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

