OBSERVATION = {'data': [[None, 3, None, 6, None, None, None, None, None, 4], [None, None, None, None, None, 2, None, None, None, None], [None, None, None, None, None, None, None, 3, None, 5], [None, 4, None, 6, None, 5, None, None, None, None], [None, None, None, None, None, None, None, None, None, 3], [1, None, None, 2, None, None, None, 1, None, None], [None, 5, None, None, None, 5, None, None, None, 4], [None, None, None, None, None, None, None, 2, None, None], [None, 3, None, 1, None, None, None, None, None, 1], [2, None, None, None, None, 4, None, 4, None, None]]}

import sys

sys.setrecursionlimit(100000)


def solve(observation):
    data = observation.get("data", [])
    if not data:
        return "{}"

    rows = len(data)
    cols = len(data[0]) if rows else 0

    # Parse islands.
    islands = []
    reqs = []
    idx = {}
    for r in range(rows):
        for c in range(cols):
            v = data[r][c]
            if v is not None:
                idx[(r, c)] = len(islands)
                islands.append((r, c))
                reqs.append(int(v))

    n = len(islands)
    if n == 0:
        return "{}"

    total_degree = sum(reqs)
    if total_degree % 2:
        return "No Solution"
    if n > 1 and total_degree < 2 * (n - 1):
        return "No Solution"

    # Build all visible neighbor edges.
    edges = []
    orient = []
    spans = []

    # Horizontal edges.
    for r in range(rows):
        prev_c = None
        for c in range(cols):
            if data[r][c] is not None:
                if prev_c is not None:
                    edges.append((idx[(r, prev_c)], idx[(r, c)]))
                    orient.append("h")
                    spans.append((r, prev_c, c))
                prev_c = c

    # Vertical edges.
    for c in range(cols):
        prev_r = None
        for r in range(rows):
            if data[r][c] is not None:
                if prev_r is not None:
                    edges.append((idx[(prev_r, c)], idx[(r, c)]))
                    orient.append("v")
                    spans.append((c, prev_r, r))
                prev_r = r

    m = len(edges)
    inc = [[] for _ in range(n)]
    for e, (a, b) in enumerate(edges):
        inc[a].append(e)
        inc[b].append(e)

    # Per-edge static max multiplicity.
    max_edge = [min(2, reqs[a], reqs[b]) for a, b in edges]

    # Crossing table.
    conflicts = [set() for _ in range(m)]
    for e in range(m):
        for f in range(e + 1, m):
            if orient[e] == orient[f]:
                continue
            if orient[e] == "h":
                hr, hc1, hc2 = spans[e]
                vc, vr1, vr2 = spans[f]
            else:
                hr, hc1, hc2 = spans[f]
                vc, vr1, vr2 = spans[e]
            if vr1 < hr < vr2 and hc1 < vc < hc2:
                conflicts[e].add(f)
                conflicts[f].add(e)
    conflicts = [tuple(sorted(s)) for s in conflicts]

    def island_sums(low, up):
        low_sum = [0] * n
        up_sum = [0] * n
        for e, (a, b) in enumerate(edges):
            lv = low[e]
            uv = up[e]
            low_sum[a] += lv
            low_sum[b] += lv
            up_sum[a] += uv
            up_sum[b] += uv
        return low_sum, up_sum

    # Connectivity reasoning on the graph of current definitely-connected components.
    # Returns:
    #   None  -> contradiction
    #   list of bridge-groups, each group = list[edge_id]
    def connectivity_info(low, up):
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # Definite positive bridges already create definite connectivity.
        for e, (a, b) in enumerate(edges):
            if low[e] > 0:
                union(a, b)

        comp_index = {}
        for i in range(n):
            r = find(i)
            if r not in comp_index:
                comp_index[r] = len(comp_index)

        comp_count = len(comp_index)
        if comp_count <= 1:
            return []

        pair_to_edges = {}
        for e, (a, b) in enumerate(edges):
            if up[e] == 0:
                continue
            ra = find(a)
            rb = find(b)
            if ra == rb:
                continue
            key = (ra, rb) if ra < rb else (rb, ra)
            pair_to_edges.setdefault(key, []).append(e)

        adj = [[] for _ in range(comp_count)]
        group_edges = []
        for (ra, rb), elist in pair_to_edges.items():
            u = comp_index[ra]
            v = comp_index[rb]
            gid = len(group_edges)
            group_edges.append(elist)
            adj[u].append((v, gid))
            adj[v].append((u, gid))

        # The still-possible component graph must stay connected.
        seen = [False] * comp_count
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for v, _gid in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        if not all(seen):
            return None

        # Bridge-groups in the component graph are mandatory in aggregate.
        disc = [-1] * comp_count
        lowlink = [0] * comp_count
        timer = 0
        bridge_gids = []

        def dfs(u, parent_gid):
            nonlocal timer
            disc[u] = lowlink[u] = timer
            timer += 1
            for v, gid in adj[u]:
                if gid == parent_gid:
                    continue
                if disc[v] == -1:
                    dfs(v, gid)
                    if lowlink[v] > disc[u]:
                        bridge_gids.append(gid)
                    if lowlink[v] < lowlink[u]:
                        lowlink[u] = lowlink[v]
                else:
                    if disc[v] < lowlink[u]:
                        lowlink[u] = disc[v]

        dfs(0, -1)
        return [group_edges[gid] for gid in bridge_gids]

    def propagate(low, up):
        while True:
            changed = False

            # Basic sanity and static caps.
            for e in range(m):
                if up[e] > max_edge[e]:
                    up[e] = max_edge[e]
                    changed = True
                if low[e] < 0:
                    low[e] = 0
                    changed = True
                if low[e] > up[e]:
                    return None

            # Positive edges kill every crossing candidate.
            for e in range(m):
                if low[e] > 0:
                    for f in conflicts[e]:
                        if up[f] != 0:
                            up[f] = 0
                            changed = True
                            if low[f] > 0:
                                return None

            # Island degree accounting:
            #   current lower sum <= target <= current upper sum
            # and each edge gets sharpened from the rest of the incident edges.
            low_sum, up_sum = island_sums(low, up)
            for i in range(n):
                need = reqs[i]
                lo = low_sum[i]
                hi = up_sum[i]
                if lo > need or hi < need:
                    return None

                for e in inc[i]:
                    others_lo = lo - low[e]
                    others_hi = hi - up[e]

                    new_low = max(low[e], need - others_hi)
                    if new_low < 0:
                        new_low = 0

                    new_up = min(up[e], need - others_lo, max_edge[e])

                    if new_low > new_up:
                        return None

                    if new_low != low[e]:
                        low[e] = new_low
                        changed = True
                    if new_up != up[e]:
                        up[e] = new_up
                        changed = True

            # Connectivity propagation:
            # a bridge-group in the current component graph must contain
            # at least one positive bridge. If only one edge remains in that
            # group, it becomes forced.
            bridge_groups = connectivity_info(low, up)
            if bridge_groups is None:
                return None

            for group in bridge_groups:
                # All edges in the group have up > 0 by construction.
                if len(group) == 1:
                    e = group[0]
                    if low[e] == 0:
                        low[e] = 1
                        changed = True

            if not changed:
                return low, up

    def solved(low, up):
        for e in range(m):
            if low[e] != up[e]:
                return False

        counts = low
        deg = [0] * n
        for e, (a, b) in enumerate(edges):
            cnt = counts[e]
            if cnt:
                deg[a] += cnt
                deg[b] += cnt

        if deg != reqs:
            return False

        for e in range(m):
            if counts[e] > 0:
                for f in conflicts[e]:
                    if f > e and counts[f] > 0:
                        return False

        # Final positive network must be connected.
        seen = [False] * n
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for e in inc[u]:
                if counts[e] <= 0:
                    continue
                a, b = edges[e]
                v = b if a == u else a
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        return all(seen)

    def choose_edge(low, up):
        low_sum, up_sum = island_sums(low, up)

        # If there is an unresolved mandatory bridge-group with multiple options,
        # branch there first.
        bridge_groups = connectivity_info(low, up)
        if bridge_groups is None:
            return None, low_sum, up_sum, False

        focus_pool = None
        multi_groups = [g for g in bridge_groups if len(g) > 1]
        if multi_groups:
            multi_groups.sort(key=len)
            best_len = len(multi_groups[0])
            pool = set()
            for g in multi_groups:
                if len(g) != best_len:
                    break
                for e in g:
                    if low[e] != up[e]:
                        pool.add(e)
            if pool:
                focus_pool = pool

        best_e = None
        best_score = None
        prefer_positive = False

        for e in range(m):
            if low[e] == up[e]:
                continue
            if focus_pool is not None and e not in focus_pool:
                continue

            a, b = edges[e]
            width = up[e] - low[e]

            rem_a = reqs[a] - low_sum[a]
            rem_b = reqs[b] - low_sum[b]
            cap_a = up_sum[a] - low_sum[a]
            cap_b = up_sum[b] - low_sum[b]

            tight_a = (rem_a / cap_a) if cap_a else 0.0
            tight_b = (rem_b / cap_b) if cap_b else 0.0
            impact = 3 * len(conflicts[e]) + tight_a + tight_b

            # Narrow domains first, then impactful edges.
            score = (width, -impact, -up[e], e)
            if best_score is None or score < best_score:
                best_score = score
                best_e = e
                prefer_positive = focus_pool is not None and e in focus_pool

        return best_e, low_sum, up_sum, prefer_positive

    def branch_states(e, low, up, low_sum, up_sum, prefer_positive):
        a, b = edges[e]
        l = low[e]
        u = up[e]
        out = []

        if l == 0:
            # Branch on absence vs presence first.
            if prefer_positive:
                order = ("present", "absent")
            else:
                cap_a = up_sum[a] - low_sum[a]
                cap_b = up_sum[b] - low_sum[b]
                rem_a = reqs[a] - low_sum[a]
                rem_b = reqs[b] - low_sum[b]
                pressure = 0.0
                if cap_a:
                    pressure += rem_a / cap_a
                if cap_b:
                    pressure += rem_b / cap_b
                order = ("present", "absent") if pressure > 1.15 else ("absent", "present")

            for kind in order:
                nl = low.copy()
                nu = up.copy()
                if kind == "absent":
                    nu[e] = 0
                else:
                    nl[e] = 1
                out.append((nl, nu))
        else:
            # Domain is [1, 2]; branch on single vs double.
            extra_a = reqs[a] - low_sum[a]
            extra_b = reqs[b] - low_sum[b]
            order = ("double", "single") if (u == 2 and extra_a > 0 and extra_b > 0) else ("single", "double")

            for kind in order:
                nl = low.copy()
                nu = up.copy()
                if kind == "single":
                    nu[e] = 1
                else:
                    nl[e] = 2
                out.append((nl, nu))

        return out

    fail_cache = set()

    def dfs(low, up):
        state = propagate(low, up)
        if state is None:
            return None
        low, up = state

        key = (tuple(low), tuple(up))
        if key in fail_cache:
            return None

        if solved(low, up):
            return low

        e, low_sum, up_sum, prefer_positive = choose_edge(low, up)
        if e is None:
            fail_cache.add(key)
            return None

        for nl, nu in branch_states(e, low, up, low_sum, up_sum, prefer_positive):
            res = dfs(nl, nu)
            if res is not None:
                return res

        fail_cache.add(key)
        return None

    init_low = [0] * m
