                        new_low = 0

                    new_up = min(up[e], need - others_lo, max_edge[e])

                    if new_low > new_up:
                        return None

                    if new_low != low[e]:
                        low[e] = new_low
                        changed = True
                    if new_up != up[e]:
                        up[e] = new_up
                        changed = True

