                if len(group) == 1:
                    e = group[0]
                    if low[e] == 0:
                        low[e] = 1
                        changed = True

            if not changed:
                return low, up

    def solved(low, up):
        for e in range(m):
            if low[e] != up[e]:
                return False

        counts = low
        deg = [0] * n
        for e, (a, b) in enumerate(edges):
            cnt = counts[e]
            if cnt:
                deg[a] += cnt
                deg[b] += cnt

        if deg != reqs:
            return False

        for e in range(m):
            if counts[e] > 0:
                for f in conflicts[e]:
                    if f > e and counts[f] > 0:
                        return False

        # Final positive network must be connected.
        seen = [False] * n
        stack = [0]
        seen[0] = True
        while stack:
            u = stack.pop()
            for e in inc[u]:
                if counts[e] <= 0:
