            return low

        e, low_sum, up_sum, prefer_positive = choose_edge(low, up)
        if e is None:
            fail_cache.add(key)
            return None

        for nl, nu in branch_states(e, low, up, low_sum, up_sum, prefer_positive):
            res = dfs(nl, nu)
            if res is not None:
                return res

        fail_cache.add(key)
        return None

    init_low = [0] * m
    init_up = max_edge[:]
    result = dfs(init_low, init_up)
    if result is None:
        return "No Solution"

    items = []
    for e, cnt in enumerate(result):
        if cnt > 0:
            a, b = edges[e]
            p = islands[a]
            q = islands[b]
            key = (p, q) if p < q else (q, p)
            items.append((key, cnt))
    items.sort()

    answer = {k: v for k, v in items}
    return repr(answer)


