from collections import deque

MASK_VALUES = {
    1: (0,),
    2: (1,),
    3: (0, 1),
    4: (2,),
    5: (0, 2),
    6: (1, 2),
    7: (0, 1, 2),
}
MASK_MIN = {m: vals[0] for m, vals in MASK_VALUES.items()}
MASK_MAX = {m: vals[-1] for m, vals in MASK_VALUES.items()}
VALUE_MASK = {0: 1, 1: 2, 2: 4}
POS_MASK = 6  # values 1 or 2


class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        parent = self.parent
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True


class HashiSolver:
    def __init__(self, observation):
        self.data = observation["data"]
        self.n = len(self.data)
        self.positions = []
        self.targets = []
        self.pos_to_idx = {}

        for r, row in enumerate(self.data):
            for c, v in enumerate(row):
                if v is not None:
                    idx = len(self.positions)
                    self.positions.append((r, c))
                    self.targets.append(v)
                    self.pos_to_idx[(r, c)] = idx

        self.island_count = len(self.positions)
        self.edges = []
        self.incident = [[] for _ in range(self.island_count)]
        self._build_edges()
        self.edge_count = len(self.edges)
        self.incident_index = [{e: i for i, e in enumerate(lst)} for lst in self.incident]
        self.crossings = [[] for _ in range(self.edge_count)]
        self._build_crossings()

        self.pattern_cache = {}
        self.fail_cache = set()

        self.initial_domains = self._initial_domains()

    def _build_edges(self):
        # Only nearest visible islands in each orthogonal direction may be connected.
        for i, (r, c) in enumerate(self.positions):
            cc = c + 1
            while cc < self.n and self.data[r][cc] is None:
                cc += 1
            if cc < self.n and self.data[r][cc] is not None:
                j = self.pos_to_idx[(r, cc)]
                self._add_edge(i, j)

            rr = r + 1
            while rr < self.n and self.data[rr][c] is None:
                rr += 1
            if rr < self.n and self.data[rr][c] is not None:
                j = self.pos_to_idx[(rr, c)]
                self._add_edge(i, j)

    def _add_edge(self, u, v):
        e = len(self.edges)
        self.edges.append((u, v))
        self.incident[u].append(e)
        self.incident[v].append(e)

    def _build_crossings(self):
        horiz = []
        vert = []
        for e, (u, v) in enumerate(self.edges):
            (r1, c1) = self.positions[u]
            (r2, c2) = self.positions[v]
            if r1 == r2:
                if c1 > c2:
                    c1, c2 = c2, c1
                horiz.append((e, r1, c1, c2))
            else:
                if r1 > r2:
                    r1, r2 = r2, r1
                vert.append((e, c1, r1, r2))

        for eh, r, c1, c2 in horiz:
            for ev, c, r1, r2 in vert:
                if r1 < r < r2 and c1 < c < c2:
                    self.crossings[eh].append(ev)
                    self.crossings[ev].append(eh)

    def _initial_domains(self):
        domains = [7] * len(self.edges)
        for e, (u, v) in enumerate(self.edges):
            cap = min(2, self.targets[u], self.targets[v])
            if cap == 0:
                domains[e] = 1
            elif cap == 1:
                domains[e] = 3
            else:
                domains[e] = 7
        return domains

    def _pattern_info(self, target, masks):
        key = (target, masks)
        if key in self.pattern_cache:
            return self.pattern_cache[key]

        k = len(masks)
        mins = [MASK_MIN[m] for m in masks]
        maxs = [MASK_MAX[m] for m in masks]

        suf_min = [0] * (k + 1)
        suf_max = [0] * (k + 1)
        for i in range(k - 1, -1, -1):
            suf_min[i] = suf_min[i + 1] + mins[i]
            suf_max[i] = suf_max[i + 1] + maxs[i]

        if target < suf_min[0] or target > suf_max[0]:
            self.pattern_cache[key] = None
            return None

        chosen = [0] * k
        counts = [[0, 0, 0] for _ in range(k)]
        feasible_count = 0

        def dfs(idx, s):
            nonlocal feasible_count
            if s + suf_min[idx] > target or s + suf_max[idx] < target:
                return
            if idx == k:
                if s == target:
                    feasible_count += 1
                    for j, val in enumerate(chosen):
                        counts[j][val] += 1
                return
            for val in MASK_VALUES[masks[idx]]:
                chosen[idx] = val
                dfs(idx + 1, s + val)

        dfs(0, 0)

        if feasible_count == 0:
            self.pattern_cache[key] = None
            return None

        allowed = []
        for i in range(k):
            m = 0
            if counts[i][0]:
                m |= 1
            if counts[i][1]:
                m |= 2
            if counts[i][2]:
                m |= 4
            allowed.append(m)

        info = (tuple(allowed), tuple(tuple(row) for row in counts), feasible_count)
        self.pattern_cache[key] = info
        return info

    def _possible_connected(self, domains):
        if self.island_count <= 1:
            return True
        seen = [False] * self.island_count
        stack = [0]
        seen[0] = True
