        comp_of = [0] * self.island_count
        comp_count = 0
        for i in range(self.island_count):
            r = dsu.find(i)
            if r not in roots:
                roots[r] = comp_count
                comp_count += 1
            comp_of[i] = roots[r]
        return comp_of, comp_count

    def _forced_component_bridges(self, domains):
        # Human-like connectivity rule:
        # after contracting all currently mandatory-positive edges,
        # any bridge in the remaining component-graph must itself be positive.
        comp_of, comp_count = self._mandatory_components(domains)
        if comp_count <= 1:
