class HeyawakeSolver:
    def __init__(self, observation):
        self.region_grid = observation["region"]
        self.data_grid = observation["data"]
        self.n = len(self.region_grid)
        self.m = self.n * self.n

        self.region_of = [0] * self.m
        self.cells = [(r, c) for r in range(self.n) for c in range(self.n)]

        for r in range(self.n):
            for c in range(self.n):
                self.region_of[self.idx(r, c)] = self.region_grid[r][c]

        self.neighbors = [[] for _ in range(self.m)]
        self.neighbor_masks = [0] * self.m
        for r in range(self.n):
            for c in range(self.n):
                i = self.idx(r, c)
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < self.n and 0 <= cc < self.n:
                        j = self.idx(rr, cc)
                        self.neighbors[i].append(j)
                        self.neighbor_masks[i] |= 1 << j

        self.regions = defaultdict(list)
        for i in range(self.m):
            self.regions[self.region_of[i]].append(i)
        self.regions = dict(self.regions)

        self.region_masks = {}
        for rid, cells in self.regions.items():
            mask = 0
            for i in cells:
                mask |= 1 << i
            self.region_masks[rid] = mask

        self.region_clue = {}
        for rid in self.regions:
            self.region_clue[rid] = None
        for r in range(self.n):
            for c in range(self.n):
                v = self.data_grid[r][c]
                if v is not None:
                    rid = self.region_grid[r][c]
                    if self.region_clue[rid] is None:
                        self.region_clue[rid] = v
                    elif self.region_clue[rid] != v:
                        raise ValueError("Conflicting clues in same region")

        self.numbered_regions = [rid for rid, clue in self.region_clue.items() if clue is not None]

        # Precompute room patterns for numbered rooms.
        self.region_candidates = {}
        for rid in self.numbered_regions:
            clue = self.region_clue[rid]
            cands = self.generate_region_candidates(rid, clue)
            if not cands:
                self.unsat = True
                return
            self.region_candidates[rid] = cands

        self.unsat = False

        # Precompute straight-line constraints:
        # For any 3 consecutive region-blocks in a row/column,
        # [last cell of block1] + [all cells of block2] + [first cell of block3]
