    def idx(self, r, c):
        return r * self.n + c

    def rc(self, i):
        return divmod(i, self.n)

    def iter_bits(self, mask):
        while mask:
            bit = mask & -mask
            yield bit.bit_length() - 1
            mask ^= bit

    def generate_region_candidates(self, rid, clue):
        cells = self.regions[rid]
        k = len(cells)
        if clue < 0 or clue > k:
            return []

        pos = {cell: i for i, cell in enumerate(cells)}
        local_adj = [0] * k
        for i, cell in enumerate(cells):
