        order = sorted(range(k), key=lambda i: bin(local_adj[i]).count("1"), reverse=True)
        local_results = []

        def dfs(p, chosen_count, forbidden_mask, chosen_mask):
            if chosen_count > clue:
                return
            if chosen_count + (k - p) < clue:
                return
            if p == k:
                if chosen_count == clue:
                    local_results.append(chosen_mask)
                return

            i = order[p]

            # Exclude.
            dfs(p + 1, chosen_count, forbidden_mask, chosen_mask)

            # Include.
            if ((forbidden_mask >> i) & 1) == 0 and chosen_count < clue:
                dfs(
                    p + 1,
                    chosen_count + 1,
                    forbidden_mask | local_adj[i] | (1 << i),
                    chosen_mask | (1 << i),
