                t ^= b
                i = b.bit_length() - 1
                if b & assigned:
                    continue
                r = cell_region[i]
                total = len(reg_cands[r])
                bp = 0
                for pi in reg_cands[r]:
                    if patterns[r][pi] & b:
                        bp += 1
                wp = total - bp
