        # 2) Most constrained room split.
        best = None
        for r in range(R):
            total = len(reg_cands[r])
            if total <= 1:
                continue
            for i in region_cells[r]:
                b = BIT[i]
                if b & assigned:
                    continue
                bp = 0
                for pi in reg_cands[r]:
                    if patterns[r][pi] & b:
                        bp += 1
                wp = total - bp
                if bp and wp:
                    score = (total, max(bp, wp), -cell_clause_degree[i], -len(neigh[i]))
                    black_first = bp <= wp
                    if best is None or score < best[0]:
                        best = (score, i, black_first)

        if best is not None:
            return best[1], best[2]

        # 3) Fallback.
        unknown = ALL & ~assigned
        b = unknown & -unknown
        return b.bit_length() - 1, True

    fail_cache = set()

    def dfs(black_mask, white_mask, reg_cands):
        state = propagate(black_mask, white_mask, reg_cands)
        if state is None:
            return None

        black_mask, white_mask, reg_cands = state
        key = (black_mask, white_mask)
        if key in fail_cache:
            return None

        if (black_mask | white_mask) == ALL:
            if final_valid(black_mask, white_mask):
                return black_mask
            fail_cache.add(key)
            return None

        cell, black_first = choose_branch(black_mask, white_mask, reg_cands)
        b = BIT[cell]

        orders = (("B",), ("W",)) if black_first else (("W",), ("B",))
        for (choice,) in orders:
            next_black = black_mask
            next_white = white_mask
            if choice == "B":
                next_black |= b
            else:
                next_white |= b
            next_cands = [lst[:] for lst in reg_cands]
            ans = dfs(next_black, next_white, next_cands)
            if ans is not None:
                return ans

        fail_cache.add(key)
        return None

    init_cands = [list(range(len(patterns[r]))) for r in range(R)]
    sol_black = dfs(0, 0, init_cands)
    if sol_black is None:
        return "No Solution"

    ans = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if sol_black & BIT[idx(r, c)]:
                ans[r][c] = 'B'
    return repr(ans)


