    def bfs(self, allowed_mask, start_idx):
        start_bit = 1 << start_idx
        if not (allowed_mask & start_bit):
            return 0
        seen = start_bit
        stack = [start_idx]
        while stack:
            i = stack.pop()
            nxt = self.adj_masks[i] & allowed_mask & ~seen
            while nxt:
                b = nxt & -nxt
                j = b.bit_length() - 1
