        if (black_mask | white_mask) == self.all_mask:
            if self.final_valid(black_mask, white_mask):
                return state
            self.fail_cache.add(key)
            return None

        kind, target = self.choose_branch(black_mask, white_mask, room_cache)

        if kind == "room":
            rid = target
            valid, _, _ = room_cache[rid]
            room_mask = self.region_masks[rid]
            children = []
            for p in valid:
                child = self.propagate(black_mask | p, white_mask | (room_mask & ~p))
                if child is not None:
                    assigned = (child[0] | child[1]).bit_count()
                    children.append((assigned, child))
            children.sort(reverse=True, key=lambda x: x[0])
            for _, child in children:
                res = self.search(child)
                if res is not None:
                    return res
            self.fail_cache.add(key)
            return None

        cell = target
        bit = 1 << cell

        child_black = self.propagate(black_mask | bit, white_mask)
        child_white = self.propagate(black_mask, white_mask | bit)

        if child_black is None and child_white is None:
            self.fail_cache.add(key)
            return None
        if child_black is None:
            return self.search(child_white)
        if child_white is None:
            return self.search(child_black)

        # Black first is usually more constraining in Heyawake.
        children = [
            ((child_black[0] | child_black[1]).bit_count(), child_black),
            ((child_white[0] | child_white[1]).bit_count(), child_white),
        ]
        children.sort(reverse=True, key=lambda x: x[0])
        for _, child in children:
            res = self.search(child)
            if res is not None:
                return res

        self.fail_cache.add(key)
        return None

    def run(self):
        initial = self.propagate(0, 0)
        result = self.search(initial)
        if result is None:
            return None
        black_mask, white_mask, _ = result
        return black_mask

def solve(observation):
    solver = HeyawakeSolver(observation)
    black_mask = solver.run()
    if black_mask is None:
        return "No Solution"
    board = []
    for r in range(solver.n):
        row = []
        for c in range(solver.m):
            i = r * solver.m + c
            row.append('B' if (black_mask >> i) & 1 else None)
        board.append(row)
    return repr(board)

if __name__ == "__main__":
    print(solve(OBSERVATION))

