        for i in iter_bits(mask):
            out |= self.adj_masks[i]
        return out

    def bfs(self, allowed_mask, start_idx):
        start_bit = 1 << start_idx
        if not (allowed_mask & start_bit):
            return 0
        seen = start_bit
        stack = [start_idx]
        while stack:
            i = stack.pop()
            nxt = self.adj_masks[i] & allowed_mask & ~seen
            while nxt:
                b = nxt & -nxt
                j = b.bit_length() - 1
                nxt ^= b
                seen |= b
                stack.append(j)
        return seen

    def build_line_clauses(self):
        clauses = set()

        # Row-wise: for segments A,B,C, at least one of:
        # rightmost(A), any cell in B, leftmost(C) must be black.
        for r in range(self.n):
            segs = []
            c = 0
            while c < self.m:
                s = c
                rid = self.region_grid[r][c]
                while c + 1 < self.m and self.region_grid[r][c + 1] == rid:
                    c += 1
                e = c
                segs.append((s, e))
                c += 1
            for k in range(len(segs) - 2):
                s1, e1 = segs[k]
                s2, e2 = segs[k + 1]
                s3, e3 = segs[k + 2]
                mask = 0
                mask |= 1 << self.idx(r, e1)
                for c in range(s2, e2 + 1):
                    mask |= 1 << self.idx(r, c)
                mask |= 1 << self.idx(r, s3)
                clauses.add(mask)

        # Column-wise analogue.
        for c in range(self.m):
            segs = []
            r = 0
            while r < self.n:
                s = r
                rid = self.region_grid[r][c]
                while r + 1 < self.n and self.region_grid[r + 1][c] == rid:
                    r += 1
                e = r
                segs.append((s, e))
                r += 1
            for k in range(len(segs) - 2):
                s1, e1 = segs[k]
                s2, e2 = segs[k + 1]
                s3, e3 = segs[k + 2]
                mask = 0
                mask |= 1 << self.idx(e1, c)
                for r in range(s2, e2 + 1):
                    mask |= 1 << self.idx(r, c)
                mask |= 1 << self.idx(s3, c)
                clauses.add(mask)

        return sorted(clauses, key=lambda x: (x.bit_count(), x))

    def enumerate_room_patterns(self, rid, clue):
        cells = self.region_cells[rid]
        size = len(cells)
        if clue < 0 or clue > size:
            return []

        local_index = {cell: k for k, cell in enumerate(cells)}
        local_adj = [0] * size
        for a, cell_a in enumerate(cells):
            mask = 0
            for b, cell_b in enumerate(cells):
                if self.adj_masks[cell_a] & (1 << cell_b):
                    mask |= 1 << b
            local_adj[a] = mask

        patterns = []

        def dfs(avail_mask, chosen_mask, chosen_count):
            if chosen_count == clue:
                global_mask = 0
                for b in iter_bits(chosen_mask):
                    global_mask |= 1 << cells[b]
                patterns.append(global_mask)
                return
            if chosen_count > clue:
                return
            if chosen_count + avail_mask.bit_count() < clue:
                return
            if not avail_mask:
                return

            v_bit = avail_mask & -avail_mask
            v = v_bit.bit_length() - 1

            # Include v
            dfs(avail_mask & ~v_bit & ~local_adj[v], chosen_mask | v_bit, chosen_count + 1)
            # Exclude v
            dfs(avail_mask & ~v_bit, chosen_mask, chosen_count)

        dfs((1 << size) - 1, 0, 0)
        return patterns

    def connectivity_step(self, black_mask, white_mask):
        if white_mask == 0:
            return black_mask, white_mask

        nonblack = self.all_mask ^ black_mask
        start = (white_mask & -white_mask).bit_length() - 1
        reach = self.bfs(nonblack, start)
        if white_mask & ~reach:
            return None

        if white_mask.bit_count() >= 2:
            new_white = 0
            candidates = (reach & ~white_mask)
            for i in iter_bits(candidates):
                # If the cell is not a potential bridge, skip.
                if (self.adj_masks[i] & reach).bit_count() < 2:
                    continue
                reach2 = self.bfs(nonblack & ~(1 << i), start)
                if white_mask & ~reach2:
                    new_white |= 1 << i
            if new_white:
                if new_white & black_mask:
                    return None
                white_mask |= new_white

        return black_mask, white_mask

    def propagate(self, black_mask, white_mask):
        room_cache = {}

        while True:
            if black_mask & white_mask:
                return None

            changed = False

            # Black adjacency.
            adj_black = self.expand_neighbors(black_mask)
            if adj_black & black_mask:
                return None
            new_white = adj_black & ~(black_mask | white_mask)
            if new_white:
                white_mask |= new_white
                changed = True

            # Clued region exact-pattern propagation.
            room_cache = {}
            for rid in self.clued_regions:
                patterns = self.room_patterns[rid]
                room_mask = self.region_masks[rid]
                need_black = black_mask & room_mask

                valid = []
                union_mask = 0
                inter_mask = None

                for p in patterns:
                    if need_black & ~p:
                        continue
                    if p & white_mask:
                        continue
                    valid.append(p)
                    union_mask |= p
                    inter_mask = p if inter_mask is None else (inter_mask & p)

                if not valid:
                    return None

                if inter_mask is None:
                    inter_mask = 0
                room_cache[rid] = (valid, union_mask, inter_mask)

                force_white = room_mask & ~union_mask & ~white_mask
                if force_white:
                    if force_white & black_mask:
                        return None
                    white_mask |= force_white
                    changed = True

                force_black = inter_mask & ~black_mask
                if force_black:
                    if force_black & white_mask:
                        return None
                    black_mask |= force_black
                    changed = True

            # No-three-rooms white line clauses.
            for mask in self.line_clauses:
                if mask & black_mask:
                    continue
                avail = mask & ~(black_mask | white_mask)
                if avail == 0:
                    return None
                if avail & (avail - 1) == 0:
                    if avail & white_mask:
                        return None
                    black_mask |= avail
                    changed = True

            # White connectivity.
            conn = self.connectivity_step(black_mask, white_mask)
            if conn is None:
                return None
            b2, w2 = conn
            if b2 != black_mask or w2 != white_mask:
                black_mask, white_mask = b2, w2
                changed = True

            if not changed:
                return black_mask, white_mask, room_cache

    def final_valid(self, black_mask, white_mask):
        if (black_mask | white_mask) != self.all_mask:
            return False
        if self.expand_neighbors(black_mask) & black_mask:
            return False

        for rid in self.clued_regions:
            clue = self.region_clue[rid]
            room_mask = self.region_masks[rid]
            if (black_mask & room_mask).bit_count() != clue:
                return False

        for mask in self.line_clauses:
            if not (mask & black_mask):
                return False

        if white_mask:
            start = (white_mask & -white_mask).bit_length() - 1
            if self.bfs(white_mask, start) != white_mask:
                return False

        return True

    def unresolved_clause_masks(self, black_mask, white_mask):
        unknown = self.all_mask ^ (black_mask | white_mask)
        out = []
        for mask in self.line_clauses:
            if mask & black_mask:
                continue
            avail = mask & unknown
            if avail:
                out.append(avail)
        return out

    def pick_cell_from_mask(self, mask, black_mask, white_mask, room_cache):
        best = None
        best_key = None
        unknown = self.all_mask ^ (black_mask | white_mask)

        for i in iter_bits(mask & unknown):
            rid = self.cell_region[i]
            split = 0
            if rid in room_cache:
                valid, _, _ = room_cache[rid]
                total = len(valid)
                bit = 1 << i
                support = 0
                for p in valid:
                    if p & bit:
                        support += 1
                split = min(support, total - support)

            unsat_clause_count = 0
            for ci in self.cell_clauses[i]:
                if not (self.line_clauses[ci] & black_mask):
                    unsat_clause_count += 1

            key = (unsat_clause_count, split, self.adj_masks[i].bit_count())
            if best_key is None or key > best_key:
                best_key = key
                best = i
        return best

    def pick_room_split_cell(self, rid, black_mask, white_mask, room_cache):
        valid, union_mask, inter_mask = room_cache[rid]
        unknown = self.all_mask ^ (black_mask | white_mask)
        candidates = (union_mask & ~inter_mask & self.region_masks[rid] & unknown)
        if not candidates:
            candidates = self.region_masks[rid] & unknown
        best = None
        best_key = None
        total = len(valid)
        for i in iter_bits(candidates):
            bit = 1 << i
            support = 0
            for p in valid:
                if p & bit:
                    support += 1
            split = min(support, total - support)
            unsat_clause_count = 0
            for ci in self.cell_clauses[i]:
                if not (self.line_clauses[ci] & black_mask):
                    unsat_clause_count += 1
            key = (split, unsat_clause_count, self.adj_masks[i].bit_count())
            if best_key is None or key > best_key:
                best_key = key
                best = i
        return best

    def choose_branch(self, black_mask, white_mask, room_cache):
        unknown = self.all_mask ^ (black_mask | white_mask)

        best_clause = None
        best_clause_size = None
        for mask in self.line_clauses:
            if mask & black_mask:
                continue
            avail = mask & unknown
            k = avail.bit_count()
            if k <= 1:
                continue
            if best_clause_size is None or k < best_clause_size:
                best_clause_size = k
                best_clause = avail
                if k == 2:
                    break

        best_room = None
        best_room_count = None
        for rid, (valid, _, _) in room_cache.items():
            cnt = len(valid)
            if cnt > 1 and (best_room_count is None or cnt < best_room_count):
                best_room_count = cnt
                best_room = rid

        if best_clause is not None and best_clause_size == 2:
            return ("cell", self.pick_cell_from_mask(best_clause, black_mask, white_mask, room_cache))

        if best_room is not None and best_room_count <= 4:
            return ("room", best_room)

        if best_clause is not None:
            return ("cell", self.pick_cell_from_mask(best_clause, black_mask, white_mask, room_cache))

        if best_room is not None:
            return ("cell", self.pick_room_split_cell(best_room, black_mask, white_mask, room_cache))

        # Fallback: choose the most constrained unknown cell.
        best = None
        best_key = None
        for i in iter_bits(unknown):
            rid = self.cell_region[i]
            split = 0
            if rid in room_cache:
                valid, _, _ = room_cache[rid]
                total = len(valid)
                bit = 1 << i
                support = 0
                for p in valid:
                    if p & bit:
                        support += 1
                split = min(support, total - support)
            unsat_clause_count = 0
            for ci in self.cell_clauses[i]:
                if not (self.line_clauses[ci] & black_mask):
                    unsat_clause_count += 1
            key = (unsat_clause_count, split, self.adj_masks[i].bit_count())
            if best_key is None or key > best_key:
                best_key = key
                best = i
        return ("cell", best)

    def search(self, state):
        if state is None:
            return None

        black_mask, white_mask, room_cache = state
        key = (black_mask, white_mask)
        if key in self.fail_cache:
            return None

        if (black_mask | white_mask) == self.all_mask:
            if self.final_valid(black_mask, white_mask):
                return state
            self.fail_cache.add(key)
            return None

        kind, target = self.choose_branch(black_mask, white_mask, room_cache)

        if kind == "room":
            rid = target
            valid, _, _ = room_cache[rid]
            room_mask = self.region_masks[rid]
            children = []
            for p in valid:
                child = self.propagate(black_mask | p, white_mask | (room_mask & ~p))
                if child is not None:
                    assigned = (child[0] | child[1]).bit_count()
                    children.append((assigned, child))
            children.sort(reverse=True, key=lambda x: x[0])
            for _, child in children:
                res = self.search(child)
                if res is not None:
                    return res
            self.fail_cache.add(key)
            return None

        cell = target
        bit = 1 << cell

        child_black = self.propagate(black_mask | bit, white_mask)
        child_white = self.propagate(black_mask, white_mask | bit)

        if child_black is None and child_white is None:
            self.fail_cache.add(key)
            return None
        if child_black is None:
            return self.search(child_white)
        if child_white is None:
            return self.search(child_black)

        # Black first is usually more constraining in Heyawake.
        children = [
            ((child_black[0] | child_black[1]).bit_count(), child_black),
            ((child_white[0] | child_white[1]).bit_count(), child_white),
        ]
        children.sort(reverse=True, key=lambda x: x[0])
        for _, child in children:
            res = self.search(child)
            if res is not None:
                return res

        self.fail_cache.add(key)
        return None

    def run(self):
        initial = self.propagate(0, 0)
        result = self.search(initial)
        if result is None:
            return None
        black_mask, white_mask, _ = result
        return black_mask

def solve(observation):
    solver = HeyawakeSolver(observation)
    black_mask = solver.run()
    if black_mask is None:
        return "No Solution"
    board = []
    for r in range(solver.n):
        row = []
        for c in range(solver.m):
            i = r * solver.m + c
            row.append('B' if (black_mask >> i) & 1 else None)
        board.append(row)
    return repr(board)

