                for nb in self.neighbors[cell]:
                    j = pos_of.get(nb)
                    if j is not None:
                        mask |= 1 << j
                adj_masks[i] = mask

            patterns = []
            if clue == 0:
                patterns.append(0)
            else:
                for comb in combinations(range(sz), clue):
                    mask = 0
                    ok = True
                    for p in comb:
                        if adj_masks[p] & mask:
                            ok = False
