class HeyawakeSolver:
    # Human-style solver:
    # 1) enumerate valid black-placement patterns per region
    # 2) enforce inter-region black non-touch by arc consistency
    # 3) encode the "no white line through >2 regions" rule as line clauses
    # 4) enforce white connectivity with component checks and cut-vertex deductions
    # 5) only then branch on the most constrained undecided cell

    def __init__(self, observation):
        raw_region = observation["region"]
        raw_data = observation["data"]
        self.h = len(raw_region)
        self.w = len(raw_region[0])
        self.n = self.h * self.w

        ids = sorted({x for row in raw_region for x in row})
        id_map = {old: i for i, old in enumerate(ids)}

        self.region_grid = [[id_map[x] for x in row] for row in raw_region]
        self.region_count = len(ids)

        self.region_cells = [[] for _ in range(self.region_count)]
        self.region_clue = [None] * self.region_count
        self.cell_region = [0] * self.n

        for r in range(self.h):
            for c in range(self.w):
                cell = self.rc_to_cell(r, c)
                rid = self.region_grid[r][c]
                self.cell_region[cell] = rid
                self.region_cells[rid].append(cell)
                v = raw_data[r][c]
                if v is not None:
                    if self.region_clue[rid] is None:
                        self.region_clue[rid] = v
                    elif self.region_clue[rid] != v:
                        raise ValueError("Conflicting clues in one region")

        self.cell_local = [0] * self.n
        for rid, cells in enumerate(self.region_cells):
            for pos, cell in enumerate(cells):
                self.cell_local[cell] = pos

        self.cell_neighbors = [[] for _ in range(self.n)]
        for r in range(self.h):
            for c in range(self.w):
                cell = self.rc_to_cell(r, c)
                if r > 0:
                    self.cell_neighbors[cell].append(self.rc_to_cell(r - 1, c))
                if r + 1 < self.h:
                    self.cell_neighbors[cell].append(self.rc_to_cell(r + 1, c))
                if c > 0:
                    self.cell_neighbors[cell].append(self.rc_to_cell(r, c - 1))
                if c + 1 < self.w:
                    self.cell_neighbors[cell].append(self.rc_to_cell(r, c + 1))

        self.region_patterns = []
        self.region_full = []
        self.region_black_bits = []
        self.region_white_bits = []
        self._build_region_patterns()

        self.constraints = []
        self._build_black_adjacency_constraints()

        self.clauses = []
        self.cell_clauses = [[] for _ in range(self.n)]
        self._build_line_clauses()

        self.cell_weight = [
            len(self.cell_neighbors[cell]) + 2 * len(self.cell_clauses[cell])
            for cell in range(self.n)
        ]

        self.failed = set()

    def rc_to_cell(self, r, c):
        return r * self.w + c

    def cell_to_rc(self, cell):
        return divmod(cell, self.w)

    def _generate_region_patterns(self, adj_masks, clue):
        size = len(adj_masks)
        order = sorted(range(size), key=lambda i: adj_masks[i].bit_count(), reverse=True)
        patterns = []

        def rec(k, chosen_mask, blocked_mask, black_count):
            if clue is not None:
                if black_count > clue:
                    return
                if black_count + (size - k) < clue:
                    return
            if k == size:
                if clue is None or black_count == clue:
                    patterns.append(chosen_mask)
                return

            pos = order[k]
            bit = 1 << pos

            rec(k + 1, chosen_mask, blocked_mask, black_count)

            if (blocked_mask & bit) == 0:
                rec(
                    k + 1,
                    chosen_mask | bit,
                    blocked_mask | bit | adj_masks[pos],
                    black_count + 1,
                )

        rec(0, 0, 0, 0)
        return patterns

    def _build_region_patterns(self):
        for rid, cells in enumerate(self.region_cells):
            local_index = {cell: i for i, cell in enumerate(cells)}
            size = len(cells)
            adj_masks = [0] * size
            for i, cell in enumerate(cells):
                mask = 0
                for nb in self.cell_neighbors[cell]:
                    j = local_index.get(nb)
                    if j is not None:
                        mask |= 1 << j
                adj_masks[i] = mask

            clue = self.region_clue[rid]
            patterns = self._generate_region_patterns(adj_masks, clue)
            if not patterns:
                raise ValueError("Region has no valid patterns")

            self.region_patterns.append(patterns)
            full = (1 << len(patterns)) - 1
            self.region_full.append(full)

            black_bits = [0] * size
            for pi, mask in enumerate(patterns):
                pbit = 1 << pi
                mm = mask
                while mm:
                    lsb = mm & -mm
                    pos = lsb.bit_length() - 1
                    black_bits[pos] |= pbit
                    mm ^= lsb

            white_bits = [full ^ b for b in black_bits]
            self.region_black_bits.append(black_bits)
            self.region_white_bits.append(white_bits)

    def _build_black_adjacency_constraints(self):
        pairs = defaultdict(list)

        for r in range(self.h):
            for c in range(self.w):
                a = self.rc_to_cell(r, c)

                if c + 1 < self.w:
                    b = self.rc_to_cell(r, c + 1)
                    ra = self.cell_region[a]
                    rb = self.cell_region[b]
                    if ra != rb:
                        if ra < rb:
                            pairs[(ra, rb)].append((a, b))
                        else:
                            pairs[(rb, ra)].append((b, a))

                if r + 1 < self.h:
                    b = self.rc_to_cell(r + 1, c)
                    ra = self.cell_region[a]
                    rb = self.cell_region[b]
                    if ra != rb:
                        if ra < rb:
                            pairs[(ra, rb)].append((a, b))
                        else:
                            pairs[(rb, ra)].append((b, a))

        for (ra, rb), cell_pairs in pairs.items():
            local_pairs = [(self.cell_local[a], self.cell_local[b]) for a, b in cell_pairs]

            pa = self.region_patterns[ra]
            pb = self.region_patterns[rb]
            comp_a = [0] * len(pa)
            comp_b = [0] * len(pb)

            for i, ma in enumerate(pa):
                allowed_b = 0
                for j, mb in enumerate(pb):
                    ok = True
                    for la, lb in local_pairs:
                        if ((ma >> la) & 1) and ((mb >> lb) & 1):
                            ok = False
                            break
                    if ok:
                        allowed_b |= 1 << j
                        comp_b[j] |= 1 << i
                comp_a[i] = allowed_b

            self.constraints.append((ra, rb, comp_a, comp_b))

    def _build_line_clauses(self):
        clause_set = set()

        for r in range(self.h):
            blocks = []
            c = 0
            while c < self.w:
                s = c
                rid = self.region_grid[r][c]
                while c + 1 < self.w and self.region_grid[r][c + 1] == rid:
                    c += 1
                e = c
                blocks.append((s, e))
                c += 1

            for i in range(len(blocks) - 2):
                s = blocks[i][0]
                e = blocks[i + 2][1]
                clause_set.add(tuple(self.rc_to_cell(r, c) for c in range(s, e + 1)))

        for c in range(self.w):
            blocks = []
            r = 0
            while r < self.h:
                s = r
                rid = self.region_grid[r][c]
                while r + 1 < self.h and self.region_grid[r + 1][c] == rid:
                    r += 1
                e = r
                blocks.append((s, e))
                r += 1

            for i in range(len(blocks) - 2):
                s = blocks[i][0]
                e = blocks[i + 2][1]
                clause_set.add(tuple(self.rc_to_cell(r, c) for r in range(s, e + 1)))

        self.clauses = [list(t) for t in sorted(clause_set, key=lambda x: (len(x), x))]
        for ci, clause in enumerate(self.clauses):
            for cell in clause:
                self.cell_clauses[cell].append(ci)

    def _filter_supported(self, dom_a, dom_b, compat_a):
        keep = 0
        x = dom_a
        while x:
            lsb = x & -x
            i = lsb.bit_length() - 1
            if compat_a[i] & dom_b:
                keep |= lsb
            x ^= lsb
        return keep

    def _restrict_cell(self, domains, cell, make_black):
        rid = self.cell_region[cell]
        pos = self.cell_local[cell]
        mask = self.region_black_bits[rid][pos] if make_black else self.region_white_bits[rid][pos]
        old = domains[rid]
        new = old & mask
        if new == 0:
            return -1
        if new == old:
            return 0
        domains[rid] = new
        return 1

    def _cell_possibilities(self, domains):
        can_black = [False] * self.n
        can_white = [False] * self.n
        forced_black = [False] * self.n
        forced_white = [False] * self.n

        for rid, cells in enumerate(self.region_cells):
            dom = domains[rid]
            black_bits = self.region_black_bits[rid]
            white_bits = self.region_white_bits[rid]
            for pos, cell in enumerate(cells):
                cb = (dom & black_bits[pos]) != 0
                cw = (dom & white_bits[pos]) != 0
                can_black[cell] = cb
                can_white[cell] = cw
                forced_black[cell] = cb and not cw
                forced_white[cell] = cw and not cb

        return can_black, can_white, forced_black, forced_white

    def _connectivity_forces(self, can_black, can_white, forced_white):
        comp_id = [-1] * self.n
        components = []
        terminal_components = []

        for start in range(self.n):
            if not can_white[start] or comp_id[start] != -1:
                continue
            cid = len(components)
            q = deque([start])
            comp_id[start] = cid
            cells = []
            term_count = 0

            while q:
                u = q.popleft()
                cells.append(u)
                if forced_white[u]:
                    term_count += 1
                for v in self.cell_neighbors[u]:
                    if can_white[v] and comp_id[v] == -1:
                        comp_id[v] = cid
                        q.append(v)

            components.append((cells, term_count))
            if term_count > 0:
                terminal_components.append(cid)

        if len(terminal_components) > 1:
            return False, [], []

        force_white = set()
        force_black = set()

        if terminal_components:
            main_cid = terminal_components[0]

            for cid, (cells, _) in enumerate(components):
                if cid == main_cid:
                    continue
                for cell in cells:
                    if not can_black[cell]:
                        return False, [], []
                    if can_white[cell]:
                        force_black.add(cell)

            main_cells, main_term_count = components[main_cid]
            if main_term_count >= 2:
                force_white |= self._terminal_cut_vertices(
                    main_cells, comp_id, main_cid, can_black, can_white, forced_white
                )

        return True, list(force_white), list(force_black)

    def _terminal_cut_vertices(self, comp_cells, comp_id, target_cid, can_black, can_white, forced_white):
        disc = {}
        low = {}
        parent = {}
        force = set()
        total_terms = sum(1 for u in comp_cells if forced_white[u])
        time = 0

        def dfs(u):
            nonlocal time
            time += 1
            disc[u] = low[u] = time

            subtotal_terms = 1 if forced_white[u] else 0
            separated_terms_sum = 0
            pieces_with_terms = 0

            for v in self.cell_neighbors[u]:
                if not can_white[v] or comp_id[v] != target_cid:
                    continue
                if v not in disc:
                    parent[v] = u
                    child_terms = dfs(v)
                    subtotal_terms += child_terms
                    if low[v] < low[u]:
                        low[u] = low[v]
                    if low[v] >= disc[u]:
                        if child_terms > 0:
                            pieces_with_terms += 1
                        separated_terms_sum += child_terms
                elif parent.get(u) != v:
                    if disc[v] < low[u]:
                        low[u] = disc[v]

            outside_terms = total_terms - (1 if forced_white[u] else 0) - separated_terms_sum
            if outside_terms > 0:
                pieces_with_terms += 1

            if pieces_with_terms > 1 and can_black[u] and can_white[u]:
                force.add(u)

            return subtotal_terms

        if comp_cells:
            dfs(comp_cells[0])

        return force

    def propagate(self, domains):
        while True:
            progress = False

            # Arc consistency on black non-touch across region boundaries
            changed = True
            while changed:
                changed = False
                for ra, rb, comp_a, comp_b in self.constraints:
                    da = domains[ra]
                    db = domains[rb]

                    nda = self._filter_supported(da, db, comp_a)
                    if nda == 0:
                        return None
                    if nda != da:
                        domains[ra] = nda
                        da = nda
                        changed = True
                        progress = True

                    ndb = self._filter_supported(db, da, comp_b)
                    if ndb == 0:
                        return None
                    if ndb != db:
                        domains[rb] = ndb
                        changed = True
                        progress = True

            can_black, can_white, forced_black, forced_white = self._cell_possibilities(domains)

            # Three-region line rule: every such span needs at least one black cell
            for clause in self.clauses:
                candidates = [cell for cell in clause if can_black[cell]]
                if not candidates:
                    return None
                if len(candidates) == 1:
                    res = self._restrict_cell(domains, candidates[0], True)
                    if res < 0:
                        return None
                    if res > 0:
                        progress = True

            if progress:
                continue

            # White connectivity: contradiction, forced blacks in disconnected components,
            # and forced whites on cut vertices joining already-forced white areas.
            ok, force_white, force_black = self._connectivity_forces(can_black, can_white, forced_white)
            if not ok:
                return None

            if force_white or force_black:
                for cell in force_white:
                    res = self._restrict_cell(domains, cell, False)
                    if res < 0:
                        return None
                    if res > 0:
                        progress = True

                for cell in force_black:
                    res = self._restrict_cell(domains, cell, True)
                    if res < 0:
                        return None
                    if res > 0:
                        progress = True

            if not progress:
                return domains

    def is_solved(self, domains):
        can_black, can_white, _, _ = self._cell_possibilities(domains)
        for cell in range(self.n):
            if can_black[cell] == can_white[cell]:
                return False
        return True

    def choose_branch_cell(self, domains):
        can_black, can_white, _, _ = self._cell_possibilities(domains)
        best_key = None
        best_cell = None
        best_order = None

        for cell in range(self.n):
            if not (can_black[cell] and can_white[cell]):
                continue

            rid = self.cell_region[cell]
            pos = self.cell_local[cell]
            dom = domains[rid]

            bcount = (dom & self.region_black_bits[rid][pos]).bit_count()
            wcount = (dom & self.region_white_bits[rid][pos]).bit_count()

            key = (min(bcount, wcount), bcount + wcount, -self.cell_weight[cell], cell)
            if best_key is None or key < best_key:
                best_key = key
                best_cell = cell
                best_order = [True, False] if bcount <= wcount else [False, True]

        return best_cell, best_order

    def extract_grid(self, domains):
        can_black, can_white, _, _ = self._cell_possibilities(domains)
        out = []
        for r in range(self.h):
            row = []
            for c in range(self.w):
                cell = self.rc_to_cell(r, c)
                if can_black[cell] and not can_white[cell]:
                    row.append('B')
                else:
                    row.append(None)
            out.append(row)
        return out

    def validate_grid(self, grid):
        # Region clues
        for rid, cells in enumerate(self.region_cells):
            clue = self.region_clue[rid]
            if clue is None:
                continue
            count = 0
            for cell in cells:
                r, c = self.cell_to_rc(cell)
                if grid[r][c] == 'B':
                    count += 1
            if count != clue:
                return False

        # No orthogonally adjacent black cells
        for cell in range(self.n):
            r, c = self.cell_to_rc(cell)
            if grid[r][c] != 'B':
                continue
            for nb in self.cell_neighbors[cell]:
                nr, nc = self.cell_to_rc(nb)
                if grid[nr][nc] == 'B':
                    return False

        # Any uninterrupted white segment may pass through at most 2 regions
        for r in range(self.h):
            c = 0
            while c < self.w:
                if grid[r][c] == 'B':
                    c += 1
                    continue
                prev_rid = self.region_grid[r][c]
                blocks = 1
                c += 1
                while c < self.w and grid[r][c] != 'B':
                    rid = self.region_grid[r][c]
                    if rid != prev_rid:
                        blocks += 1
                        prev_rid = rid
                    c += 1
                if blocks > 2:
                    return False

        for c in range(self.w):
            r = 0
            while r < self.h:
                if grid[r][c] == 'B':
                    r += 1
                    continue
                prev_rid = self.region_grid[r][c]
                blocks = 1
                r += 1
                while r < self.h and grid[r][c] != 'B':
                    rid = self.region_grid[r][c]
                    if rid != prev_rid:
                        blocks += 1
                        prev_rid = rid
                    r += 1
                if blocks > 2:
                    return False

        # White connectivity
        whites = [cell for cell in range(self.n) if grid[cell // self.w][cell % self.w] != 'B']
        if whites:
            start = whites[0]
            seen = {start}
            q = deque([start])
            while q:
                u = q.popleft()
                for v in self.cell_neighbors[u]:
                    vr, vc = self.cell_to_rc(v)
                    if grid[vr][vc] == 'B' or v in seen:
                        continue
                    seen.add(v)
                    q.append(v)
            if len(seen) != len(whites):
                return False

        return True

    def dfs(self, domains):
        domains = self.propagate(domains)
        if domains is None:
            return None

        state = tuple(domains)
        if state in self.failed:
            return None

        if self.is_solved(domains):
            grid = self.extract_grid(domains)
            if self.validate_grid(grid):
                return domains
            self.failed.add(state)
            return None

        cell, order = self.choose_branch_cell(domains)
        if cell is None:
            grid = self.extract_grid(domains)
            if self.validate_grid(grid):
                return domains
            self.failed.add(state)
            return None

        for make_black in order:
            new_domains = domains.copy()
            res = self._restrict_cell(new_domains, cell, make_black)
            if res < 0:
                continue
            ans = self.dfs(new_domains)
            if ans is not None:
                return ans

        self.failed.add(state)
        return None

    def run(self):
        start_domains = self.region_full[:]
        result = self.dfs(start_domains)
        if result is None:
            return None
        return self.extract_grid(result)


def solve(observation):
    try:
        solver = HeyawakeSolver(observation)
        ans = solver.run()
        if ans is None:
            return "No Solution"
        return repr(ans)
    except Exception:
        return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

