OBSERVATION = {'data': [[1, 5, 3, 4, 1], [5, 3, 5, 3, 1], [3, 5, 4, 1, 5], [5, 1, 2, 3, 4], [2, 1, 1, 1, 3]]}

from collections import deque
import sys

UNKNOWN = 0
WHITE = 1
BLACK = 2


def solve(observation):
    grid = observation.get("data")
    if not grid or not grid[0]:
        return "No Solution"

    rows = len(grid)
    cols = len(grid[0])
    for row in grid:
        if len(row) != cols:
