    n = rows * cols

    # Orthogonal neighbors
    adj = [[] for _ in range(n)]
    for r in range(rows):
        for c in range(cols):
            i = idx(r, c)
            if r > 0:
                adj[i].append(idx(r - 1, c))
            if r + 1 < rows:
                adj[i].append(idx(r + 1, c))
            if c > 0:
                adj[i].append(idx(r, c - 1))
            if c + 1 < cols:
                adj[i].append(idx(r, c + 1))
    adj = [tuple(v) for v in adj]

