            groups.setdefault(grid[r][c], []).append(i)
        for cells in groups.values():
            if len(cells) > 1:
                for a in cells:
                    for b in cells:
                        if a != b:
                            conf_sets[a].add(b)

    for c in range(cols):
        groups = {}
        for r in range(rows):
            i = idx(r, c)
            groups.setdefault(grid[r][c], []).append(i)
        for cells in groups.values():
            if len(cells) > 1:
                for a in cells:
                    for b in cells:
                        if a != b:
                            conf_sets[a].add(b)

    conf = [tuple(sorted(s)) for s in conf_sets]

    # Static "sandwich" rule: A ? A => middle must be white
    static_white = set()
    for r in range(rows):
        for c in range(1, cols - 1):
            if grid[r][c - 1] == grid[r][c + 1]:
                static_white.add(idx(r, c))
    for c in range(cols):
        for r in range(1, rows - 1):
            if grid[r - 1][c] == grid[r + 1][c]:
