    def set_cell(state, cell, value, queue):
        cur = state[cell]
        if cur == value:
            return True
        if cur != UNKNOWN:
            return False
        state[cell] = value
        queue.append(cell)
        return True

    def compute_components(state):
        comp_index = [-1] * n
        comps = []
        for start in range(n):
            if state[start] == BLACK or comp_index[start] != -1:
                continue
            ci = len(comps)
            comp = [start]
            comp_index[start] = ci
            stack = [start]
            while stack:
                x = stack.pop()
                for y in adj[x]:
                    if state[y] != BLACK and comp_index[y] == -1:
                        comp_index[y] = ci
                        comp.append(y)
                        stack.append(y)
            comps.append(comp)
        return comps, comp_index

    def can_all_black(cells, state, extra_black=None):
        # Can this entire disconnected region vanish by turning every cell black?
        if not cells:
            return True
        cellset = set(cells)
        for x in cells:
            if state[x] != UNKNOWN:
                return False
            for y in adj[x]:
                if state[y] == BLACK:
                    return False
                if extra_black is not None and y == extra_black:
                    return False
                if y in cellset and y > x:
                    return False
        return True

    def analyze_components(state):
        comps, comp_index = compute_components(state)
        if not comps:
            return None, None, None, "BAD"

        req = [not can_all_black(comp, state) for comp in comps]

        white_comps = set()
        for i, v in enumerate(state):
            if v == WHITE:
                ci = comp_index[i]
                if ci == -1:
                    return comps, comp_index, req, "BAD"
                white_comps.add(ci)

        if len(white_comps) > 1:
            return comps, comp_index, req, "BAD"

        if white_comps:
            main = next(iter(white_comps))
            for i, need_white in enumerate(req):
                if i != main and need_white:
                    return comps, comp_index, req, "BAD"
        else:
            need = [i for i, need_white in enumerate(req) if need_white]
            if len(need) > 1:
                return comps, comp_index, req, "BAD"
            main = need[0] if len(need) == 1 else None

        return comps, comp_index, req, main

    def connectivity_deduce(state, queue):
        comps, comp_index, req, main = analyze_components(state)
        if main == "BAD":
            return None

        # If the main white component is known, every other component must disappear,
        # so force them all black.
        if main is not None:
            for ci, comp in enumerate(comps):
                if ci == main:
                    continue
                for cell in comp:
                    if not set_cell(state, cell, BLACK, queue):
                        return None
            if queue:
                return True

            # Articulation-style deduction inside the main component:
            # if blacking a cell would split the main area into 2+ subregions that
            # each still require a white, that cell must be white.
            main_comp = comps[main]
            if len(main_comp) > 1:
                main_set = set(main_comp)
                for v in main_comp:
                    if state[v] != UNKNOWN:
                        continue

                    deg = 0
                    for y in adj[v]:
                        if y in main_set:
                            deg += 1
                    if deg < 2:
                        continue

                    seen = {v}
                    required_parts = 0

                    for start in main_comp:
                        if start in seen:
                            continue
                        sub = [start]
                        seen.add(start)
                        stack = [start]
                        while stack:
                            x = stack.pop()
                            for y in adj[x]:
                                if y != v and y in main_set and y not in seen:
                                    seen.add(y)
                                    sub.append(y)
                                    stack.append(y)

                        if not can_all_black(sub, state, extra_black=v):
                            required_parts += 1
                            if required_parts >= 2:
