        return False

    def propagate(state, initial_queue=None):
        queue = deque(initial_queue) if initial_queue is not None else deque()

        while True:
            while queue:
                cell = queue.popleft()
                val = state[cell]

                if val == BLACK:
                    for y in adj[cell]:
                        if state[y] == BLACK:
                            return None
                        if state[y] == UNKNOWN:
                            if not set_cell(state, y, WHITE, queue):
                                return None

                elif val == WHITE:
                    for y in conf[cell]:
                        if state[y] == WHITE:
                            return None
                        if state[y] == UNKNOWN:
                            if not set_cell(state, y, BLACK, queue):
