        return state

    def validate_complete(state):
        if any(v == UNKNOWN for v in state):
            return False

        white_cells = [i for i, v in enumerate(state) if v == WHITE]
        if not white_cells:
            return False

        for i, v in enumerate(state):
            if v == BLACK:
                for y in adj[i]:
                    if state[y] == BLACK:
                        return False
            else:
                for y in conf[i]:
                    if state[y] == WHITE:
                        return False

