    def complete_all_white_if_possible(state):
        trial = state[:]
        for i, v in enumerate(trial):
            if v == UNKNOWN:
                trial[i] = WHITE
        return trial if validate_complete(trial) else None

    def choose_candidate(state):
        comps, comp_index, req, main = analyze_components(state)
        if main == "BAD":
            return None

        candidates = [i for i, v in enumerate(state) if v == UNKNOWN]
        if not candidates:
            return None

        if main is not None:
            main_candidates = [i for i in comps[main] if state[i] == UNKNOWN]
            if main_candidates:
                candidates = main_candidates

        best = None
        best_key = None

        for cell in candidates:
            conf_unknown = 0
            for y in conf[cell]:
                if state[y] == UNKNOWN:
                    conf_unknown += 1

            adj_unknown = 0
            for y in adj[cell]:
                if state[y] == UNKNOWN:
                    adj_unknown += 1

            comp_size = len(comps[comp_index[cell]]) if comp_index[cell] != -1 else 0

            key = (
                1 if conf_unknown > 0 else 0,
                conf_unknown,
                adj_unknown,
                comp_size,
                -cell,
            )
            if best_key is None or key > best_key:
                best_key = key
                best = cell

        return best

    fail_memo = set()

    def search(state):
        state = propagate(state, ())
        if state is None:
            return None

        key = tuple(state)
        if key in fail_memo:
            return None

        done = complete_all_white_if_possible(state)
        if done is not None:
            return done

        if UNKNOWN not in state:
            if validate_complete(state):
                return state
            fail_memo.add(key)
            return None

        cell = choose_candidate(state)
        if cell is None:
            fail_memo.add(key)
            return None

        prefer_black = any(state[y] == UNKNOWN for y in conf[cell])

        branches = []
        for value in (BLACK, WHITE):
            trial = state[:]
            q = deque()
            if set_cell(trial, cell, value, q):
                trial = propagate(trial, q)
                if trial is not None:
                    branches.append((trial.count(UNKNOWN), value, trial))

        if not branches:
            fail_memo.add(key)
            return None

        pref_rank = {BLACK: 0, WHITE: 1} if prefer_black else {WHITE: 0, BLACK: 1}
        branches.sort(key=lambda item: (item[0], pref_rank[item[1]]))

        for _, _, trial in branches:
            ans = search(trial)
            if ans is not None:
                return ans

        fail_memo.add(key)
        return None

    initial = [UNKNOWN] * n
    q = deque()
    for cell in sorted(static_white):
        if not set_cell(initial, cell, WHITE, q):
