import sys

sys.setrecursionlimit(1000000)

U = 0
W = 1
B = 2


class HitoriSolver:
    # Human-like solver:
    # 1) Local implications:
    #    - black => orthogonal neighbors white
    #    - white => equal-number peers in row/col black
    # 2) Static pattern:
    #    - a x a in a row/col forces x white
    # 3) Connectivity pruning:
    #    - among currently non-black cells, there can be at most one
    #      "significant" component (size > 1 or containing a confirmed white)
    #    - isolated singleton components outside the main significant component
    #      must be black
    # 4) Contradiction-driven lookahead:
    #    - if assuming black fails, force white
    #    - if assuming white fails, force black
    # 5) Branch on the most constraining cell using trial states.

    def __init__(self, grid):
        self.grid = grid
        self.n = len(grid)
        self.m = self.n * self.n

        self.neighbors = [[] for _ in range(self.m)]
        for r in range(self.n):
            for c in range(self.n):
                i = self.idx(r, c)
                if r > 0:
                    self.neighbors[i].append(self.idx(r - 1, c))
                if r + 1 < self.n:
                    self.neighbors[i].append(self.idx(r + 1, c))
                if c > 0:
                    self.neighbors[i].append(self.idx(r, c - 1))
                if c + 1 < self.n:
                    self.neighbors[i].append(self.idx(r, c + 1))

        dup_sets = [set() for _ in range(self.m)]

        for r in range(self.n):
            groups = {}
            for c in range(self.n):
                groups.setdefault(grid[r][c], []).append(self.idx(r, c))
            for cells in groups.values():
                if len(cells) > 1:
                    for i in range(len(cells)):
                        a = cells[i]
                        for j in range(i + 1, len(cells)):
                            b = cells[j]
                            dup_sets[a].add(b)
                            dup_sets[b].add(a)

        for c in range(self.n):
            groups = {}
            for r in range(self.n):
                groups.setdefault(grid[r][c], []).append(self.idx(r, c))
            for cells in groups.values():
                if len(cells) > 1:
                    for i in range(len(cells)):
                        a = cells[i]
                        for j in range(i + 1, len(cells)):
                            b = cells[j]
                            dup_sets[a].add(b)
                            dup_sets[b].add(a)

        self.dup = [tuple(sorted(s)) for s in dup_sets]

        # Static "sandwich" whites: a x a => x must be white.
        self.initial_white = set()
        for r in range(self.n):
            for c in range(self.n - 2):
                if grid[r][c] == grid[r][c + 2]:
                    self.initial_white.add(self.idx(r, c + 1))
        for c in range(self.n):
            for r in range(self.n - 2):
                if grid[r][c] == grid[r + 2][c]:
                    self.initial_white.add(self.idx(r + 1, c))

        # Search heuristic: duplicates matter most, then adjacency.
        self.impact = [
            4 * len(self.dup[i]) + len(self.neighbors[i])
            for i in range(self.m)
        ]

        self.dead = set()

    def idx(self, r, c):
        return r * self.n + c

    def assign(self, status, queue, i, color):
        cur = status[i]
        if cur != U:
            return cur == color

        if color == B:
            for j in self.neighbors[i]:
                if status[j] == B:
                    return False
        else:
            for j in self.dup[i]:
                if status[j] == W:
                    return False

        status[i] = color
        queue.append(i)
        return True

    def component_deductions(self, status, queue):
        # Return:
        #   -1 -> contradiction
        #    0 -> no change
        #    1 -> assignments added to queue
        seen = [False] * self.m
        significant = 0
        isolated_unknowns = []

        for i in range(self.m):
            if seen[i] or status[i] == B:
                continue

            stack = [i]
            seen[i] = True
            comp = []
            has_white = False

            while stack:
                v = stack.pop()
                comp.append(v)
                if status[v] == W:
                    has_white = True
                for nb in self.neighbors[v]:
                    if not seen[nb] and status[nb] != B:
                        seen[nb] = True
                        stack.append(nb)

            if has_white or len(comp) > 1:
                significant += 1
                if significant > 1:
                    return -1
            else:
                # Exactly one unknown cell.
                isolated_unknowns.append(comp[0])

        if significant == 1 and isolated_unknowns:
            changed = 0
            for i in isolated_unknowns:
                if status[i] == U:
                    if not self.assign(status, queue, i, B):
                        return -1
                    changed = 1
            return changed

        return 0

    def propagate(self, status, queue):
        head = 0

        while True:
            while head < len(queue):
                i = queue[head]
                head += 1
                color = status[i]

                if color == B:
                    for j in self.neighbors[i]:
                        sj = status[j]
                        if sj == B:
                            return False
                        if sj == U:
                            status[j] = W
                            queue.append(j)
                elif color == W:
                    for j in self.dup[i]:
                        sj = status[j]
                        if sj == W:
                            return False
                        if sj == U:
                            status[j] = B
                            queue.append(j)

            comp_result = self.component_deductions(status, queue)
            if comp_result < 0:
                return False
            if comp_result == 0:
                break

        return True

