        for c in range(self.n):
            groups = {}
            for r in range(self.n):
                groups.setdefault(grid[r][c], []).append(self.idx(r, c))
            for cells in groups.values():
                if len(cells) > 1:
                    for i in range(len(cells)):
                        a = cells[i]
                        for j in range(i + 1, len(cells)):
                            b = cells[j]
                            dup_sets[a].add(b)
                            dup_sets[b].add(a)

        self.dup = [tuple(sorted(s)) for s in dup_sets]

        # Static "sandwich" whites: a x a => x must be white.
        self.initial_white = set()
        for r in range(self.n):
            for c in range(self.n - 2):
                if grid[r][c] == grid[r][c + 2]:
                    self.initial_white.add(self.idx(r, c + 1))
        for c in range(self.n):
            for r in range(self.n - 2):
                if grid[r][c] == grid[r + 2][c]:
                    self.initial_white.add(self.idx(r + 1, c))

        # Search heuristic: duplicates matter most, then adjacency.
        self.impact = [
            4 * len(self.dup[i]) + len(self.neighbors[i])
            for i in range(self.m)
        ]

        self.dead = set()

    def idx(self, r, c):
