        #   -1 -> contradiction
        #    0 -> no change
        #    1 -> assignments added to queue
        seen = [False] * self.m
        significant = 0
        isolated_unknowns = []

        for i in range(self.m):
            if seen[i] or status[i] == B:
                continue

            stack = [i]
            seen[i] = True
            comp = []
            has_white = False

            while stack:
                v = stack.pop()
                comp.append(v)
