        if white_count == 0:
            return False

        # No adjacent blacks.
        for i in range(self.m):
            if status[i] == B:
                for j in self.neighbors[i]:
                    if j > i and status[j] == B:
                        return False

        # White uniqueness in rows.
        for r in range(self.n):
            seen = set()
            for c in range(self.n):
                i = self.idx(r, c)
                if status[i] == W:
                    v = self.grid[r][c]
                    if v in seen:
                        return False
                    seen.add(v)

        # White uniqueness in cols.
        for c in range(self.n):
            seen = set()
            for r in range(self.n):
                i = self.idx(r, c)
                if status[i] == W:
                    v = self.grid[r][c]
                    if v in seen:
                        return False
                    seen.add(v)

