        queue = []
        if not self.assign(new_status, queue, i, color):
            return None
        if not self.propagate(new_status, queue):
            return None
        return new_status

    def analyze(self, status):
        while True:
            if not self.propagate(status, []):
                return "dead", None

            unknowns = [i for i in range(self.m) if status[i] == U]
            if not unknowns:
                if self.final_valid(status):
                    return "solved", status
                return "dead", None

            unknowns.sort(key=lambda i: self.impact[i], reverse=True)

            base_u = len(unknowns)
            best = None
            forced = False

            for i in unknowns:
                t_black = self.try_color(status, i, B)
                t_white = self.try_color(status, i, W)

                if t_black is None and t_white is None:
                    return "dead", None

                if t_black is None:
                    queue = []
                    if not self.assign(status, queue, i, W):
                        return "dead", None
                    if not self.propagate(status, queue):
                        return "dead", None
                    forced = True
                    break

                if t_white is None:
                    queue = []
                    if not self.assign(status, queue, i, B):
                        return "dead", None
                    if not self.propagate(status, queue):
                        return "dead", None
                    forced = True
                    break

                u_black = t_black.count(U)
                u_white = t_white.count(U)

                # Prefer variables where both branches reduce uncertainty a lot.
                score = (
                    base_u - max(u_black, u_white),
                    (2 * base_u) - u_black - u_white,
                    self.impact[i],
                    -abs(u_black - u_white),
                )

                if best is None or score > best[0]:
                    if u_black <= u_white:
                        best = (score, t_black, t_white)
                    else:
                        best = (score, t_white, t_black)

            if forced:
                continue

            return "branch", (best[1], best[2])

    def dfs(self, status):
        kind, data = self.analyze(status)
        key = bytes(status)

        if kind == "dead":
            self.dead.add(key)
            return None

        if kind == "solved":
            return data

        if key in self.dead:
            return None

        first, second = data

        key1 = bytes(first)
        if key1 not in self.dead:
            ans = self.dfs(first)
            if ans is not None:
                return ans

        key2 = bytes(second)
        if key2 not in self.dead:
            ans = self.dfs(second)
            if ans is not None:
                return ans

        self.dead.add(key)
        return None

    def solve_mask(self):
        start = self.make_initial_state()
        if start is None:
            return None

        result = self.dfs(start)
        if result is None:
            return None

        out = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                i = self.idx(r, c)
                row.append('B' if result[i] == B else None)
            out.append(row)
        return out


def solve(observation):
    grid = observation['data']
    solver = HitoriSolver(grid)
    ans = solver.solve_mask()
    return ans if ans is not None else "No Solution"


