from collections import deque

WHITE = 1
BLACK = 2


class HitoriSolver:
    # State encoding:
    # 0 = unknown
    # 1 = white
    # 2 = black

    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.m = self.n * self.n
        self.values = [data[r][c] for r in range(self.n) for c in range(self.n)]

        self.neighbors = [[] for _ in range(self.m)]
        self.dups = [set() for _ in range(self.m)]
        self.opp = [set() for _ in range(self.m)]  # adjacent equal cells => opposite colors

        self.static_white = set()
        self.static_black = set()
        self.unsat = False

        self._build_neighbors()
        self._build_constraints()

        self.dups = [tuple(sorted(s)) for s in self.dups]
        self.opp = [tuple(sorted(s)) for s in self.opp]
        self.static_white = tuple(sorted(self.static_white))
        self.static_black = tuple(sorted(self.static_black))

        self.base_score = [
            4 * len(self.dups[i]) + 3 * len(self.opp[i]) + len(self.neighbors[i])
            for i in range(self.m)
        ]
        self.fail_cache = set()

    def idx(self, r, c):
        return r * self.n + c

    def rc(self, i):
        return divmod(i, self.n)

    def _build_neighbors(self):
        n = self.n
        for r in range(n):
            for c in range(n):
                i = self.idx(r, c)
                if r > 0:
                    self.neighbors[i].append(self.idx(r - 1, c))
                if r + 1 < n:
                    self.neighbors[i].append(self.idx(r + 1, c))
                if c > 0:
                    self.neighbors[i].append(self.idx(r, c - 1))
                if c + 1 < n:
                    self.neighbors[i].append(self.idx(r, c + 1))
                self.neighbors[i] = tuple(self.neighbors[i])

    def _add_opp(self, a, b):
        if a == b:
            self.unsat = True
            return
        self.opp[a].add(b)
        self.opp[b].add(a)

    def _analyze_line(self, line):
        # Human-like line deductions:
        # - adjacent equal cells must be opposite colors
        # - equal cells with one cell between force the middle white
        # - a consecutive run of 3 equal cells is B-W-B
        # - a line/value with one adjacent run forces all other same-valued cells in that line black
        # - two separate adjacent runs of same value in one line are impossible
