        for pos, cell in enumerate(line):
            by_value.setdefault(self.values[cell], []).append(pos)

        for positions in by_value.values():
            if len(positions) <= 1:
                continue

            posset = set(positions)

            # Duplicate graph for row/column uniqueness among whites.
            actual_cells = [line[p] for p in positions]
            k = len(actual_cells)
            for i in range(k):
                a = actual_cells[i]
                for j in range(i + 1, k):
                    b = actual_cells[j]
                    self.dups[a].add(b)
                    self.dups[b].add(a)

