            if cur != 0 and cur != color:
                return False, False

            if color == BLACK:
                for nb in self.neighbors[i]:
                    if state[nb] == BLACK:
                        return False, False
            else:
                for d in self.dups[i]:
                    if state[d] == WHITE:
                        return False, False

            state[i] = color
            queue.append(i)
            return True, True

        # Existing assignments are valid seeds.
        for i, s in enumerate(state):
            if s:
                queue.append(i)

        # Static deductions.
        for i in self.static_white:
            ok, _ = assign(i, WHITE)
            if not ok:
                return None
        for i in self.static_black:
            ok, _ = assign(i, BLACK)
            if not ok:
                return None

        while True:
            while queue:
                i = queue.popleft()
                color = state[i]

                if color == WHITE:
                    for d in self.dups[i]:
                        ok, _ = assign(d, BLACK)
                        if not ok:
                            return None
                    for j in self.opp[i]:
                        ok, _ = assign(j, BLACK)
                        if not ok:
                            return None
                else:
                    for nb in self.neighbors[i]:
                        ok, _ = assign(nb, WHITE)
                        if not ok:
                            return None
                    for j in self.opp[i]:
                        ok, _ = assign(j, WHITE)
                        if not ok:
