        comps = []

        for start in not_black:
            if seen[start]:
                continue
            seen[start] = True
            comp = [start]
            q = deque([start])
            while q:
                u = q.popleft()
                for v in self.neighbors[u]:
                    if state[v] != BLACK and not seen[v]:
                        seen[v] = True
                        q.append(v)
                        comp.append(v)
            comps.append(comp)

