                sb[i] = BLACK
                sb = self.basic_propagate(sb)

                if sw is None and sb is None:
                    return None
                if sw is None:
                    state[i] = BLACK
                    state = self.basic_propagate(state)
                    if state is None:
                        return None
                    forced = True
                    break
                if sb is None:
                    state[i] = WHITE
                    state = self.basic_propagate(state)
                    if state is None:
                        return None
                    forced = True
                    break

            if not forced:
