        best_key = None
        for i, s in enumerate(state):
            if s != 0:
                continue
            dup_unknown = sum(1 for d in self.dups[i] if state[d] == 0)
            opp_unknown = sum(1 for j in self.opp[i] if state[j] == 0)
            nb_unknown = sum(1 for nb in self.neighbors[i] if state[nb] == 0)
            key = (dup_unknown * 4 + opp_unknown * 3 + nb_unknown, self.base_score[i], i)
            if best is None or key > best_key:
