            actual_cells = [line[p] for p in positions]
            k = len(actual_cells)
            for i in range(k):
                a = actual_cells[i]
                for j in range(i + 1, k):
                    b = actual_cells[j]
                    self.dups[a].add(b)
                    self.dups[b].add(a)

            # Adjacent equal cells => exactly one black / one white.
            for a, b in zip(positions, positions[1:]):
                if b == a + 1:
                    self._add_opp(line[a], line[b])

            # Equal cells at distance 2 => middle must be white.
            for p in positions:
                if p + 2 in posset:
                    self.static_white.add(line[p + 1])

            # Consecutive runs of equal values.
            runs = []
            start = 0
            while start < len(positions):
                end = start
                while end + 1 < len(positions) and positions[end + 1] == positions[end] + 1:
                    end += 1
                run = positions[start:end + 1]
                if len(run) >= 2:
                    runs.append(run)
                start = end + 1

            if len(runs) >= 2:
                self.unsat = True
                continue

            if runs:
                run = runs[0]
                runset = set(run)
                rlen = len(run)

                if rlen >= 4:
                    self.unsat = True
                    continue

                # If one adjacent run exists, it already guarantees at least one white in the run,
                # so all other same-valued cells in the line must be black.
                for p in positions:
                    if p not in runset:
                        self.static_black.add(line[p])

                if rlen == 3:
                    self.static_black.add(line[run[0]])
                    self.static_white.add(line[run[1]])
                    self.static_black.add(line[run[2]])

    def _build_constraints(self):
        n = self.n

        for r in range(n):
            self._analyze_line([self.idx(r, c) for c in range(n)])

        for c in range(n):
            self._analyze_line([self.idx(r, c) for r in range(n)])

        # A cell with no duplicates in row or column must be white.
        for i in range(self.m):
            if not self.dups[i]:
                self.static_white.add(i)

    def basic_propagate(self, state):
        queue = deque()

        def assign(i, color):
            cur = state[i]
            if cur == color:
                return True, False
            if cur != 0 and cur != color:
                return False, False

            if color == BLACK:
                for nb in self.neighbors[i]:
                    if state[nb] == BLACK:
                        return False, False
            else:
                for d in self.dups[i]:
                    if state[d] == WHITE:
                        return False, False

            state[i] = color
            queue.append(i)
            return True, True

        # Existing assignments are valid seeds.
        for i, s in enumerate(state):
            if s:
                queue.append(i)

        # Static deductions.
        for i in self.static_white:
            ok, _ = assign(i, WHITE)
            if not ok:
                return None
        for i in self.static_black:
            ok, _ = assign(i, BLACK)
            if not ok:
                return None

        while True:
            while queue:
                i = queue.popleft()
                color = state[i]

                if color == WHITE:
                    for d in self.dups[i]:
                        ok, _ = assign(d, BLACK)
                        if not ok:
                            return None
                    for j in self.opp[i]:
                        ok, _ = assign(j, BLACK)
                        if not ok:
                            return None
                else:
                    for nb in self.neighbors[i]:
                        ok, _ = assign(nb, WHITE)
                        if not ok:
                            return None
                    for j in self.opp[i]:
                        ok, _ = assign(j, WHITE)
                        if not ok:
