    def connectivity_propagate(self, state, assign):
        # Connectivity on the graph of not-black cells.
        # If it splits into multiple components, all but one component must disappear.
        # A disconnected component of size > 1 cannot disappear entirely because all-black
        # on that component would create adjacent black cells.
        not_black = [i for i, s in enumerate(state) if s != BLACK]
        if not not_black:
            return None

        seen = [False] * self.m
        comps = []

        for start in not_black:
            if seen[start]:
                continue
            seen[start] = True
            comp = [start]
            q = deque([start])
            while q:
                u = q.popleft()
                for v in self.neighbors[u]:
                    if state[v] != BLACK and not seen[v]:
                        seen[v] = True
                        q.append(v)
                        comp.append(v)
            comps.append(comp)

        if len(comps) == 1:
            comp = comps[0]
            if len(comp) == 1 and state[comp[0]] == 0:
                ok, changed = assign(comp[0], WHITE)
                if not ok:
                    return None
                return changed
            return False

        nontrivial = 0
        for comp in comps:
            if len(comp) == 1 and state[comp[0]] == WHITE:
                return None
            if len(comp) > 1:
                nontrivial += 1
                if nontrivial >= 2:
                    return None

        changed_any = False

        if nontrivial == 1:
            for comp in comps:
                if len(comp) == 1:
                    ok, changed = assign(comp[0], BLACK)
                    if not ok:
                        return None
                    changed_any = changed_any or changed
            return changed_any

        # All components are singletons here.
        white_singletons = [comp[0] for comp in comps if state[comp[0]] == WHITE]
        if len(white_singletons) >= 2:
            return None
        if len(white_singletons) == 1:
            keep = white_singletons[0]
            for comp in comps:
                c = comp[0]
                if c != keep:
                    ok, changed = assign(c, BLACK)
                    if not ok:
                        return None
                    changed_any = changed_any or changed
            return changed_any

        return False

    def reduce_state(self, state, probing=True):
        state = self.basic_propagate(state)
        if state is None or not probing:
            return state

        while True:
            forced = False
            unknowns = [i for i, s in enumerate(state) if s == 0]
            if not unknowns:
                break

            unknowns.sort(key=lambda i: self.base_score[i], reverse=True)

            for i in unknowns:
                sw = state[:]
                sw[i] = WHITE
                sw = self.basic_propagate(sw)

                sb = state[:]
                sb[i] = BLACK
                sb = self.basic_propagate(sb)

                if sw is None and sb is None:
                    return None
                if sw is None:
                    state[i] = BLACK
                    state = self.basic_propagate(state)
                    if state is None:
                        return None
                    forced = True
                    break
                if sb is None:
                    state[i] = WHITE
                    state = self.basic_propagate(state)
                    if state is None:
                        return None
                    forced = True
                    break

            if not forced:
                break

        return state

    def choose_cell(self, state):
        best = None
        best_key = None
        for i, s in enumerate(state):
            if s != 0:
                continue
            dup_unknown = sum(1 for d in self.dups[i] if state[d] == 0)
            opp_unknown = sum(1 for j in self.opp[i] if state[j] == 0)
            nb_unknown = sum(1 for nb in self.neighbors[i] if state[nb] == 0)
            key = (dup_unknown * 4 + opp_unknown * 3 + nb_unknown, self.base_score[i], i)
            if best is None or key > best_key:
                best = i
                best_key = key
        return best

    def is_solution(self, state):
        if any(s == 0 for s in state):
            return False

        whites = [i for i, s in enumerate(state) if s == WHITE]
        if not whites:
            return False

        for i, s in enumerate(state):
            if s == WHITE:
                for d in self.dups[i]:
                    if d > i and state[d] == WHITE:
                        return False
            else:
                for nb in self.neighbors[i]:
                    if nb > i and state[nb] == BLACK:
                        return False

        seen = {whites[0]}
        q = deque([whites[0]])
        while q:
            u = q.popleft()
            for v in self.neighbors[u]:
                if state[v] == WHITE and v not in seen:
                    seen.add(v)
                    q.append(v)
        return len(seen) == len(whites)

    def search(self, state):
        key = tuple(state)
        if key in self.fail_cache:
            return None

        if 0 not in state:
            if self.is_solution(state):
                return state
            self.fail_cache.add(key)
            return None

        i = self.choose_cell(state)
        if i is None:
            self.fail_cache.add(key)
            return None

        children = []
        for color in (WHITE, BLACK):
            child = state[:]
            child[i] = color
            child = self.reduce_state(child, probing=True)
            if child is not None:
                children.append(child)

        if not children:
            self.fail_cache.add(key)
            return None

        children.sort(key=lambda st: sum(1 for x in st if x != 0), reverse=True)

        for child in children:
            child_key = tuple(child)
            if child_key in self.fail_cache:
                continue
            ans = self.search(child)
            if ans is not None:
                return ans

        self.fail_cache.add(key)
        return None

    def state_to_mask(self, state):
        return [
            ['B' if state[self.idx(r, c)] == BLACK else None for c in range(self.n)]
            for r in range(self.n)
        ]

    def solve_board(self):
        if self.unsat:
            return None

        init = [0] * self.m
        init = self.reduce_state(init, probing=True)
        if init is None:
            return None
        return self.search(init)


def solve(observation):
    data = observation["data"]
    solver = HitoriSolver(data)
    result = solver.solve_board()
    if result is None:
        return "No Solution"
    return solver.state_to_mask(result)


