def connectivity_propagate(model, domains):
    neighbors = model["neighbors"]
    m = model["m"]

    can_white = [bool(d & WBIT) for d in domains]
    comp_id = [-1] * m
    components = []

    for start in range(m):
        if not can_white[start] or comp_id[start] != -1:
            continue
        cid = len(components)
        stack = [start]
        comp_id[start] = cid
        comp = []
        while stack:
            u = stack.pop()
            comp.append(u)
            for v in neighbors[u]:
                if can_white[v] and comp_id[v] == -1:
                    comp_id[v] = cid
                    stack.append(v)
        components.append(comp)

    if not components:
        return None

    changed = False

    # Any white-possible connected component of size > 1 must contain a white,
    # because a whole connected multi-cell component cannot be entirely black.
    # A singleton component is "live" only if already forced white.
    live = []
    for cid, comp in enumerate(components):
        if len(comp) > 1 or domains[comp[0]] == WBIT:
            live.append(cid)

    if len(live) > 1:
        return None

    # If one live component exists, every other white-possible component must be
    # discarded entirely, so it must be a singleton that can be black.
    if len(live) == 1:
        live_cid = live[0]
        for cid, comp in enumerate(components):
            if cid == live_cid:
                continue
            if len(comp) != 1:
                return None
            u = comp[0]
            nd = domains[u] & BBIT
            if nd == 0:
                return None
            if nd != domains[u]:
                domains[u] = nd
                changed = True

    # Connectivity bridge rule:
    # In the graph of cells that can still be white, an articulation point
    # cannot be black, because black would force all orthogonal neighbors white
    # and split the white area into multiple disconnected parts.
    for cid, comp in enumerate(components):
        if len(comp) <= 2:
            continue
        for c in comp:
            if domains[c] != BOTH:
                continue
            neighs = [v for v in neighbors[c] if can_white[v] and comp_id[v] == cid]
            if len(neighs) < 2:
                continue

            seen = {c}
            parts = 0
            for s in neighs:
                if s in seen:
                    continue
                parts += 1
                if parts >= 2:
                    domains[c] = WBIT
                    changed = True
                    break
                stack = [s]
                seen.add(s)
                while stack:
                    u = stack.pop()
                    for v in neighbors[u]:
                        if v != c and can_white[v] and comp_id[v] == cid and v not in seen:
                            seen.add(v)
                            stack.append(v)

