def propagate(model, domains):
    neighbors = model["neighbors"]
    groups = model["groups"]
    patterns = model["patterns"]

    while True:
        changed = False

        for d in domains:
            if d == 0:
                return None

        # Black cells force orthogonal neighbors white.
        for u, d in enumerate(domains):
            if d == BBIT:
                for v in neighbors[u]:
                    nd = domains[v] & WBIT
                    if nd == 0:
                        return None
                    if nd != domains[v]:
                        domains[v] = nd
                        changed = True

        # Duplicate-group arc consistency.
        for gid, cells in enumerate(groups):
            allowed = []
            pats = patterns[gid]

            for wpos in pats:
                ok = True
                for pos, u in enumerate(cells):
                    want = WBIT if pos == wpos else BBIT
                    if not (domains[u] & want):
                        ok = False
                        break
                if ok:
                    allowed.append(wpos)

            if not allowed:
                return None

            for pos, u in enumerate(cells):
                support = 0
                for wpos in allowed:
                    support |= (WBIT if pos == wpos else BBIT)
                    if support == BOTH:
                        break
                nd = domains[u] & support
                if nd == 0:
                    return None
                if nd != domains[u]:
                    domains[u] = nd
                    changed = True

