                if v > u and domains[v] == BBIT:
                    return False

    # White numbers unique in each row.
    for r in range(n):
        seen = set()
        base = r * n
        for c in range(n):
            u = base + c
            if domains[u] == WBIT:
                val = data[r][c]
                if val in seen:
                    return False
                seen.add(val)

    # White numbers unique in each column.
    for c in range(n):
        seen = set()
        for r in range(n):
            u = r * n + c
            if domains[u] == WBIT:
                val = data[r][c]
                if val in seen:
                    return False
                seen.add(val)

    # White cells connected.
    start = whites[0]
    seen = {start}
    stack = [start]
    while stack:
