    neighbors = model["neighbors"]
    peer_union = model["peer_union"]
    cell_groups = model["cell_groups"]

    best_idx = None
    best_key = None

    for u, d in enumerate(domains):
        if d != BOTH:
            continue

        peer_open = 0
        for v in peer_union[u]:
            if domains[v] != BBIT:
                peer_open += 1

        nbr_open = 0
        for v in neighbors[u]:
            if domains[v] != WBIT:
                nbr_open += 1

        key = (
            len(cell_groups[u]),
            peer_open + nbr_open,
            max(peer_open, nbr_open),
            len(peer_union[u]),
            nbr_open,
        )
        if best_key is None or key > best_key:
            best_key = key
            best_idx = u

    return best_idx


def order_values(model, domains, u):
    peer_union = model["peer_union"]
    neighbors = model["neighbors"]

    impact_w = 0
    for v in peer_union[u]:
        if domains[v] != BBIT:
            impact_w += 1

    impact_b = 0
    for v in neighbors[u]:
        if domains[v] != WBIT:
            impact_b += 1

    if impact_w > impact_b:
        return (WBIT, BBIT)
    if impact_b > impact_w:
        return (BBIT, WBIT)

    if peer_union[u]:
        return (BBIT, WBIT)
    return (WBIT, BBIT)


def dfs(model, domains, fail_cache, propagated=False):
    if not propagated:
        domains = propagate(model, domains.copy())
        if domains is None:
            return None

    key = tuple(domains)
    if key in fail_cache:
        return None

    if BOTH not in domains:
        if validate_solution(model, domains):
            return domains
        fail_cache.add(key)
        return None

    u = select_cell(model, domains)
    if u is None:
        fail_cache.add(key)
        return None

    next_states = []
    seen_states = set()

    for val in order_values(model, domains, u):
        new_domains = domains.copy()
        new_domains[u] = val
        res = propagate(model, new_domains)
        if res is None:
            continue
        t = tuple(res)
        if t not in seen_states:
            seen_states.add(t)
            next_states.append(res)

    if not next_states:
        fail_cache.add(key)
        return None

    next_states.sort(key=lambda st: st.count(BOTH))

    for st in next_states:
        ans = dfs(model, st, fail_cache, propagated=True)
        if ans is not None:
            return ans

    fail_cache.add(key)
    return None


def solve(observation):
    data = observation["data"]
    model = build_model(data)

    domains = [BOTH] * model["m"]

    # Safe human deduction: numbers unique in both row and column stay white.
    for u in model["always_white"]:
        domains[u] = WBIT

    ans = dfs(model, domains, set(), propagated=False)
    if ans is None:
        return "No Solution"

    n = model["n"]
    out = [[None for _ in range(n)] for _ in range(n)]
    for u, d in enumerate(ans):
        if d == BBIT:
            r, c = divmod(u, n)
            out[r][c] = "B"
    return out


