                for u in cells:
                    cell_groups[u].append(gid)

    # For each duplicate group, valid local patterns are:
    # - all black, if no two cells of the group are adjacent
    # - exactly one white, if that single white breaks every adjacent-black clash
    patterns = []
    for cells in groups:
        k = len(cells)
        adj_edges = []
        for i in range(k - 1):
            if cells[i + 1] in neighbors[cells[i]]:
                adj_edges.append((i, i + 1))

        pats = []
        if not adj_edges:
            pats.append(-1)  # all black

        for wpos in range(k):
            ok = True
            for a, b in adj_edges:
                if a != wpos and b != wpos:
                    ok = False
                    break
            if ok:
                pats.append(wpos)

        patterns.append(tuple(pats))

    # A cell unique in both row and column can always be safely white.
    always_white = tuple(i for i in range(m) if not cell_groups[i])

    peer_union = []
    for u in range(m):
        s = set()
        for gid in cell_groups[u]:
            for v in groups[gid]:
                if v != u:
                    s.add(v)
        peer_union.append(tuple(sorted(s)))

    return {
        "data": data,
        "n": n,
        "m": m,
        "neighbors": neighbors,
        "groups": tuple(groups),
        "patterns": tuple(patterns),
        "cell_groups": tuple(tuple(gs) for gs in cell_groups),
        "peer_union": tuple(peer_union),
        "always_white": always_white,
    }


def connectivity_propagate(model, domains):
    neighbors = model["neighbors"]
    m = model["m"]

    can_white = [bool(d & WBIT) for d in domains]
    comp_id = [-1] * m
    components = []

    for start in range(m):
        if not can_white[start] or comp_id[start] != -1:
            continue
        cid = len(components)
        stack = [start]
        comp_id[start] = cid
        comp = []
        while stack:
            u = stack.pop()
            comp.append(u)
            for v in neighbors[u]:
                if can_white[v] and comp_id[v] == -1:
                    comp_id[v] = cid
                    stack.append(v)
        components.append(comp)

    if not components:
        return None

    changed = False

    # Any white-possible connected component of size > 1 must contain a white,
    # because a whole connected multi-cell component cannot be entirely black.
    # A singleton component is "live" only if already forced white.
    live = []
    for cid, comp in enumerate(components):
        if len(comp) > 1 or domains[comp[0]] == WBIT:
            live.append(cid)

    if len(live) > 1:
        return None

    # If one live component exists, every other white-possible component must be
    # discarded entirely, so it must be a singleton that can be black.
    if len(live) == 1:
        live_cid = live[0]
        for cid, comp in enumerate(components):
            if cid == live_cid:
                continue
            if len(comp) != 1:
                return None
            u = comp[0]
            nd = domains[u] & BBIT
            if nd == 0:
                return None
            if nd != domains[u]:
                domains[u] = nd
                changed = True

    # Connectivity bridge rule:
    # In the graph of cells that can still be white, an articulation point
    # cannot be black, because black would force all orthogonal neighbors white
    # and split the white area into multiple disconnected parts.
    for cid, comp in enumerate(components):
        if len(comp) <= 2:
            continue
        for c in comp:
            if domains[c] != BOTH:
                continue
            neighs = [v for v in neighbors[c] if can_white[v] and comp_id[v] == cid]
            if len(neighs) < 2:
                continue

            seen = {c}
            parts = 0
            for s in neighs:
                if s in seen:
                    continue
                parts += 1
                if parts >= 2:
                    domains[c] = WBIT
                    changed = True
                    break
                stack = [s]
                seen.add(s)
                while stack:
                    u = stack.pop()
                    for v in neighbors[u]:
                        if v != c and can_white[v] and comp_id[v] == cid and v not in seen:
                            seen.add(v)
                            stack.append(v)

    return changed


def propagate(model, domains):
    neighbors = model["neighbors"]
    groups = model["groups"]
    patterns = model["patterns"]

    while True:
        changed = False

        for d in domains:
            if d == 0:
                return None

        # Black cells force orthogonal neighbors white.
        for u, d in enumerate(domains):
            if d == BBIT:
                for v in neighbors[u]:
                    nd = domains[v] & WBIT
                    if nd == 0:
                        return None
                    if nd != domains[v]:
                        domains[v] = nd
                        changed = True

        # Duplicate-group arc consistency.
        for gid, cells in enumerate(groups):
            allowed = []
            pats = patterns[gid]

            for wpos in pats:
                ok = True
                for pos, u in enumerate(cells):
                    want = WBIT if pos == wpos else BBIT
                    if not (domains[u] & want):
                        ok = False
                        break
                if ok:
                    allowed.append(wpos)

            if not allowed:
                return None

            for pos, u in enumerate(cells):
                support = 0
                for wpos in allowed:
                    support |= (WBIT if pos == wpos else BBIT)
                    if support == BOTH:
                        break
                nd = domains[u] & support
                if nd == 0:
                    return None
                if nd != domains[u]:
                    domains[u] = nd
                    changed = True

        conn = connectivity_propagate(model, domains)
        if conn is None:
            return None
        if conn:
            changed = True

        if not changed:
            return domains


def validate_solution(model, domains):
    n = model["n"]
    data = model["data"]
    neighbors = model["neighbors"]

    if any(d not in (WBIT, BBIT) for d in domains):
        return False

    whites = [i for i, d in enumerate(domains) if d == WBIT]
    if not whites:
        return False

    # No orthogonally adjacent blacks.
    for u, d in enumerate(domains):
        if d == BBIT:
            for v in neighbors[u]:
                if v > u and domains[v] == BBIT:
                    return False

    # White numbers unique in each row.
    for r in range(n):
        seen = set()
        base = r * n
        for c in range(n):
            u = base + c
            if domains[u] == WBIT:
                val = data[r][c]
                if val in seen:
                    return False
                seen.add(val)

    # White numbers unique in each column.
    for c in range(n):
        seen = set()
        for r in range(n):
            u = r * n + c
            if domains[u] == WBIT:
                val = data[r][c]
                if val in seen:
                    return False
                seen.add(val)

    # White cells connected.
    start = whites[0]
    seen = {start}
    stack = [start]
    while stack:
        u = stack.pop()
        for v in neighbors[u]:
            if domains[v] == WBIT and v not in seen:
                seen.add(v)
                stack.append(v)

    return len(seen) == len(whites)


def select_cell(model, domains):
    neighbors = model["neighbors"]
    peer_union = model["peer_union"]
    cell_groups = model["cell_groups"]

    best_idx = None
    best_key = None

    for u, d in enumerate(domains):
        if d != BOTH:
            continue

        peer_open = 0
        for v in peer_union[u]:
            if domains[v] != BBIT:
                peer_open += 1

        nbr_open = 0
        for v in neighbors[u]:
            if domains[v] != WBIT:
                nbr_open += 1

        key = (
            len(cell_groups[u]),
            peer_open + nbr_open,
            max(peer_open, nbr_open),
            len(peer_union[u]),
            nbr_open,
        )
        if best_key is None or key > best_key:
            best_key = key
            best_idx = u

    return best_idx


def order_values(model, domains, u):
    peer_union = model["peer_union"]
    neighbors = model["neighbors"]

    impact_w = 0
    for v in peer_union[u]:
        if domains[v] != BBIT:
            impact_w += 1

    impact_b = 0
    for v in neighbors[u]:
        if domains[v] != WBIT:
            impact_b += 1

    if impact_w > impact_b:
        return (WBIT, BBIT)
    if impact_b > impact_w:
        return (BBIT, WBIT)

    if peer_union[u]:
        return (BBIT, WBIT)
    return (WBIT, BBIT)


def dfs(model, domains, fail_cache, propagated=False):
    if not propagated:
        domains = propagate(model, domains.copy())
        if domains is None:
            return None

    key = tuple(domains)
    if key in fail_cache:
        return None

    if BOTH not in domains:
        if validate_solution(model, domains):
            return domains
        fail_cache.add(key)
        return None

    u = select_cell(model, domains)
    if u is None:
        fail_cache.add(key)
        return None

    next_states = []
    seen_states = set()

    for val in order_values(model, domains, u):
        new_domains = domains.copy()
        new_domains[u] = val
        res = propagate(model, new_domains)
        if res is None:
            continue
        t = tuple(res)
        if t not in seen_states:
            seen_states.add(t)
            next_states.append(res)

    if not next_states:
        fail_cache.add(key)
        return None

    next_states.sort(key=lambda st: st.count(BOTH))

    for st in next_states:
        ans = dfs(model, st, fail_cache, propagated=True)
        if ans is not None:
            return ans

    fail_cache.add(key)
    return None


def solve(observation):
    data = observation["data"]
    model = build_model(data)

    domains = [BOTH] * model["m"]

    # Safe human deduction: numbers unique in both row and column stay white.
    for u in model["always_white"]:
        domains[u] = WBIT

    ans = dfs(model, domains, set(), propagated=False)
    if ans is None:
        return "No Solution"

    n = model["n"]
    out = [[None for _ in range(n)] for _ in range(n)]
    for u, d in enumerate(ans):
        if d == BBIT:
            r, c = divmod(u, n)
            out[r][c] = "B"
    return out


