from functools import lru_cache
from collections import Counter
import sys

sys.setrecursionlimit(10000)

WBIT = 1
BBIT = 2


@lru_cache(None)
def generate_line_masks(values):
    values = tuple(values)
    n = len(values)
    value_id = {}
    ids = []
    for v in values:
        if v not in value_id:
            value_id[v] = len(value_id)
        ids.append(value_id[v])

    memo = {}

    def dfs(pos, prev_black, used_white_mask):
        key = (pos, prev_black, used_white_mask)
        if key in memo:
            return memo[key]
        if pos == n:
            return (0,)

        out = []

        vid = ids[pos]

        # White is allowed only if this value has not already been kept white in the line.
        if not ((used_white_mask >> vid) & 1):
            for tail in dfs(pos + 1, 0, used_white_mask | (1 << vid)):
                out.append(tail)

        # Black is allowed only if previous cell is not black.
        if not prev_black:
            bit = 1 << pos
            for tail in dfs(pos + 1, 1, used_white_mask):
                out.append(bit | tail)

        memo[key] = tuple(out)
        return memo[key]

    return dfs(0, 0, 0)


class HitoriSolver:
    def __init__(self, data):
        self.data = data
        self.H = len(data)
        self.W = len(data[0]) if self.H else 0
        self.cols = [[data[r][c] for r in range(self.H)] for c in range(self.W)]

        self.row_all = [list(generate_line_masks(tuple(row))) for row in data]
        self.col_all = [list(generate_line_masks(tuple(col))) for col in self.cols]

        self.neighbors = [[[] for _ in range(self.W)] for _ in range(self.H)]
        for r in range(self.H):
            for c in range(self.W):
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < self.H and 0 <= cc < self.W:
                        self.neighbors[r][c].append((rr, cc))

        row_counts = [Counter(row) for row in data]
        col_counts = [Counter(col) for col in self.cols]
        self.branch_weight = [[0] * self.W for _ in range(self.H)]
        for r in range(self.H):
            for c in range(self.W):
                v = data[r][c]
                conflicts = (row_counts[r][v] - 1) + (col_counts[c][v] - 1)
                self.branch_weight[r][c] = 2 * conflicts + len(self.neighbors[r][c])

        self.fail_memo = set()

    def _signature(self, row_domains, col_domains):
        return (tuple(tuple(d) for d in row_domains), tuple(tuple(d) for d in col_domains))

    def _compute_row_pos(self, row_domains):
        res = [[0] * self.W for _ in range(self.H)]
        for r, dom in enumerate(row_domains):
            cur = [0] * self.W
            for m in dom:
                for c in range(self.W):
                    cur[c] |= BBIT if ((m >> c) & 1) else WBIT
            res[r] = cur
        return res

    def _compute_col_pos(self, col_domains):
        res = [[0] * self.H for _ in range(self.W)]
        for c, dom in enumerate(col_domains):
            cur = [0] * self.H
            for m in dom:
                for r in range(self.H):
                    cur[r] |= BBIT if ((m >> r) & 1) else WBIT
            res[c] = cur
        return res

    def _apply_cell_requirement(self, row_domains, col_domains, r, c, state_bit):
        want_black = (state_bit == BBIT)

        new_row = [m for m in row_domains[r] if (((m >> c) & 1) == want_black)]
        if not new_row:
            return False
        row_domains[r] = new_row

        new_col = [m for m in col_domains[c] if (((m >> r) & 1) == want_black)]
        if not new_col:
            return False
        col_domains[c] = new_col

        return True

    def _white_components(self, white_possible):
        seen = [[False] * self.W for _ in range(self.H)]
        comps = []
        for r in range(self.H):
            for c in range(self.W):
                if white_possible[r][c] and not seen[r][c]:
                    stack = [(r, c)]
                    seen[r][c] = True
                    comp = []
                    while stack:
                        x, y = stack.pop()
                        comp.append((x, y))
                        for nx, ny in self.neighbors[x][y]:
                            if white_possible[nx][ny] and not seen[nx][ny]:
                                seen[nx][ny] = True
                                stack.append((nx, ny))
                    comps.append(comp)
        return comps

    def _propagate(self, row_domains, col_domains):
        while True:
            # Arc consistency between row domains and column domains.
            while True:
                changed = False

                col_pos = self._compute_col_pos(col_domains)
                new_rows = []
                for r, dom in enumerate(row_domains):
                    nd = []
                    for m in dom:
                        ok = True
                        for c in range(self.W):
                            state = BBIT if ((m >> c) & 1) else WBIT
                            if not (col_pos[c][r] & state):
                                ok = False
                                break
                        if ok:
                            nd.append(m)
                    if not nd:
                        return None
                    if len(nd) != len(dom):
                        changed = True
                    new_rows.append(nd)
                row_domains = new_rows

                row_pos = self._compute_row_pos(row_domains)
                new_cols = []
                for c, dom in enumerate(col_domains):
                    nd = []
                    for m in dom:
                        ok = True
                        for r in range(self.H):
                            state = BBIT if ((m >> r) & 1) else WBIT
                            if not (row_pos[r][c] & state):
                                ok = False
                                break
                        if ok:
                            nd.append(m)
                    if not nd:
                        return None
                    if len(nd) != len(dom):
                        changed = True
                    new_cols.append(nd)
                col_domains = new_cols

                if not changed:
                    break

            row_pos = self._compute_row_pos(row_domains)
            col_pos = self._compute_col_pos(col_domains)

            poss = [[0] * self.W for _ in range(self.H)]
            white_possible = [[False] * self.W for _ in range(self.H)]
            black_possible = [[False] * self.W for _ in range(self.H)]

            total_white_possible = 0
            only_white_cell = None

            for r in range(self.H):
                for c in range(self.W):
                    p = row_pos[r][c] & col_pos[c][r]
                    if p == 0:
                        return None
                    poss[r][c] = p
                    if p & WBIT:
                        white_possible[r][c] = True
                        total_white_possible += 1
                        only_white_cell = (r, c)
                    if p & BBIT:
                        black_possible[r][c] = True

            if total_white_possible == 0:
                return None

            deductions = {}

            def add_deduction(r, c, state_bit):
                p = poss[r][c]
                if not (p & state_bit):
                    return False
                if p == state_bit:
                    return True
                old = deductions.get((r, c))
                if old is None:
                    deductions[(r, c)] = state_bit
                    return True
                return old == state_bit

            # At least one white must exist.
            if total_white_possible == 1:
                if not add_deduction(only_white_cell[0], only_white_cell[1], WBIT):
                    return None

            comps = self._white_components(white_possible)

            obligatory_idx = []
            for i, comp in enumerate(comps):
                if len(comp) > 1:
                    obligatory_idx.append(i)
                else:
                    rr, cc = comp[0]
                    if not black_possible[rr][cc]:
                        obligatory_idx.append(i)

            if len(obligatory_idx) > 1:
                return None

            if len(obligatory_idx) == 1:
                main_i = obligatory_idx[0]
                for i, comp in enumerate(comps):
                    if i == main_i:
                        continue
                    if len(comp) != 1:
                        return None
                    rr, cc = comp[0]
                    if not black_possible[rr][cc]:
                        return None
                    if not add_deduction(rr, cc, BBIT):
                        return None

            # Cut-point style connectivity:
            # if removing a candidate-black cell splits the white-possible graph into
            # two or more components that each must contain a white, that cell must be white.
            candidate_cells = []
            for r in range(self.H):
                for c in range(self.W):
                    if poss[r][c] == (WBIT | BBIT):
                        deg = 0
                        for nr, nc in self.neighbors[r][c]:
                            if white_possible[nr][nc]:
                                deg += 1
                        if deg >= 2:
                            candidate_cells.append((r, c))

            if candidate_cells:
                white_cells = [(r, c) for r in range(self.H) for c in range(self.W) if white_possible[r][c]]
                for xr, xc in candidate_cells:
                    seen = [[False] * self.W for _ in range(self.H)]
                    obligatory_count = 0

                    for sr, sc in white_cells:
                        if (sr, sc) == (xr, xc) or seen[sr][sc]:
                            continue
                        stack = [(sr, sc)]
                        seen[sr][sc] = True
                        comp_size = 0
                        singleton = None
                        while stack:
                            x, y = stack.pop()
                            comp_size += 1
                            singleton = (x, y)
                            for nx, ny in self.neighbors[x][y]:
                                if (nx, ny) == (xr, xc):
                                    continue
                                if white_possible[nx][ny] and not seen[nx][ny]:
                                    seen[nx][ny] = True
                                    stack.append((nx, ny))

                        must_have_white = comp_size > 1
                        if comp_size == 1:
                            rr, cc = singleton
                            if not black_possible[rr][cc]:
                                must_have_white = True

                        if must_have_white:
                            obligatory_count += 1
                            if obligatory_count > 1:
                                if not add_deduction(xr, xc, WBIT):
                                    return None
                                break

            if not deductions:
                return row_domains, col_domains, poss

            for (r, c), state_bit in deductions.items():
                if not self._apply_cell_requirement(row_domains, col_domains, r, c, state_bit):
                    return None

    def _choose_branch(self, row_domains, col_domains, poss):
        best = None
        best_info = None

        for r in range(self.H):
            for c in range(self.W):
                if poss[r][c] != (WBIT | BBIT):
                    continue

                row_black = 0
                for m in row_domains[r]:
                    row_black += (m >> c) & 1
                row_white = len(row_domains[r]) - row_black

                col_black = 0
                for m in col_domains[c]:
                    col_black += (m >> r) & 1
                col_white = len(col_domains[c]) - col_black

                support_black = row_black * col_black
                support_white = row_white * col_white

                key = (
                    min(support_black, support_white),
                    support_black + support_white,
                    -self.branch_weight[r][c],
                )

                if best is None or key < best:
                    best = key
                    if support_white < support_black:
                        order = [WBIT, BBIT]
                    elif support_black < support_white:
                        order = [BBIT, WBIT]
                    else:
                        order = [WBIT, BBIT]
                    best_info = (r, c, order)

        return best_info

    def _validate_final(self, poss):
        whites = []

        for r in range(self.H):
            seen = set()
            for c in range(self.W):
                if poss[r][c] == WBIT:
                    v = self.data[r][c]
                    if v in seen:
                        return False
                    seen.add(v)
                    whites.append((r, c))
                elif poss[r][c] != BBIT:
                    return False

        for c in range(self.W):
            seen = set()
            for r in range(self.H):
                if poss[r][c] == WBIT:
                    v = self.data[r][c]
                    if v in seen:
                        return False
                    seen.add(v)

        for r in range(self.H):
            for c in range(self.W):
                if poss[r][c] == BBIT:
                    for nr, nc in self.neighbors[r][c]:
                        if (nr > r or (nr == r and nc > c)) and poss[nr][nc] == BBIT:
                            return False

        if not whites:
            return False

        seen = set([whites[0]])
        stack = [whites[0]]
        while stack:
            r, c = stack.pop()
            for nr, nc in self.neighbors[r][c]:
                if poss[nr][nc] == WBIT and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    stack.append((nr, nc))

        return len(seen) == len(whites)

    def _build_answer(self, poss):
        return [['B' if poss[r][c] == BBIT else None for c in range(self.W)] for r in range(self.H)]

    def _search(self, row_domains, col_domains):
        propagated = self._propagate(row_domains, col_domains)
        if propagated is None:
            return None

        row_domains, col_domains, poss = propagated
        sig = self._signature(row_domains, col_domains)
        if sig in self.fail_memo:
            return None

        complete = True
        for r in range(self.H):
            for c in range(self.W):
                if poss[r][c] == (WBIT | BBIT):
                    complete = False
                    break
            if not complete:
                break

        if complete:
            if self._validate_final(poss):
                return self._build_answer(poss)
            self.fail_memo.add(sig)
            return None

        branch = self._choose_branch(row_domains, col_domains, poss)
        if branch is None:
            self.fail_memo.add(sig)
            return None

        r, c, order = branch

        for state_bit in order:
            new_rows = [list(d) for d in row_domains]
            new_cols = [list(d) for d in col_domains]
            if not self._apply_cell_requirement(new_rows, new_cols, r, c, state_bit):
                continue
            ans = self._search(new_rows, new_cols)
            if ans is not None:
                return ans

