        dead.add(key)
        return None

    start = [UNKNOWN] * vcount
    if not propagate(start, initial_forces):
        return "No Solution"

    solved = dfs(start)
    if solved is None:
        return "No Solution"

    out = [[None for _ in range(m)] for _ in range(n)]
    for i, s in enumerate(solved):
        r, c = rc(i)
        if s == BLACK:
            out[r][c] = "B"
    return out

