from itertools import combinations


def _normalize_observation(observation):
    if not isinstance(observation, dict) or 'region' not in observation or 'data' not in observation:
        raise ValueError("Invalid observation")

    region = observation['region']
    data = observation['data']

    if not isinstance(region, list) or not isinstance(data, list) or not region or len(region) != len(data):
        raise ValueError("Invalid grid shape")

    n = len(region)
    if any(not isinstance(row, list) or len(row) != n for row in region):
        raise ValueError("Region grid must be NxN")
    if any(not isinstance(row, list) or len(row) != n for row in data):
        raise ValueError("Data grid must be NxN")

    # Remap arbitrary region ids to dense 0..N-1 ids in first-seen order.
    remap = {}
    next_id = 0
    dense_region = []
    for row in region:
        new_row = []
        for rid in row:
            if rid not in remap:
                remap[rid] = next_id
                next_id += 1
            new_row.append(remap[rid])
        dense_region.append(new_row)

    if next_id != n:
        raise ValueError("Expected exactly N regions")

    counts = [0] * n
    for row in dense_region:
        for rid in row:
            counts[rid] += 1
    if any(count != n for count in counts):
        raise ValueError("Each region must contain exactly N cells")

    dense_data = []
    for row in data:
        new_row = []
        for v in row:
            if v is None:
                new_row.append(None)
            elif isinstance(v, int) and 1 <= v <= n:
                new_row.append(v)
            else:
                raise ValueError("Invalid given")
        dense_data.append(new_row)

    return n, dense_region, dense_data


def _is_single(mask):
    return mask != 0 and (mask & (mask - 1)) == 0


def _iter_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit
        mask ^= bit


def solve(observation):
    try:
        n, region, data = _normalize_observation(observation)
    except ValueError:
        return "No Solution"

    full_mask = (1 << n) - 1
    num_cells = n * n

    row_of = [0] * num_cells
    col_of = [0] * num_cells
    reg_of = [0] * num_cells

    row_cells = [[] for _ in range(n)]
    col_cells = [[] for _ in range(n)]
    reg_cells = [[] for _ in range(n)]

    # Intersections for locked-candidate logic.
    reg_rows = [[[] for _ in range(n)] for _ in range(n)]
    reg_cols = [[[] for _ in range(n)] for _ in range(n)]
    row_regs = [[[] for _ in range(n)] for _ in range(n)]
    col_regs = [[[] for _ in range(n)] for _ in range(n)]

    for r in range(n):
        for c in range(n):
            i = r * n + c
            g = region[r][c]
            row_of[i] = r
            col_of[i] = c
            reg_of[i] = g
            row_cells[r].append(i)
            col_cells[c].append(i)
            reg_cells[g].append(i)
            reg_rows[g][r].append(i)
            reg_cols[g][c].append(i)
            row_regs[r][g].append(i)
            col_regs[c][g].append(i)

    candidates = [full_mask] * num_cells
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                candidates[r * n + c] = 1 << (v - 1)

    def compute_needs(cand):
        row_need = [0] * n
        col_need = [0] * n
        reg_need = [0] * n

        for r in range(n):
            used = 0
            for i in row_cells[r]:
                m = cand[i]
                if m == 0:
                    return None
                if _is_single(m):
                    if used & m:
                        return None
                    used |= m
            row_need[r] = full_mask & ~used

        for c in range(n):
            used = 0
            for i in col_cells[c]:
                m = cand[i]
                if m == 0:
                    return None
                if _is_single(m):
                    if used & m:
                        return None
                    used |= m
            col_need[c] = full_mask & ~used

        for g in range(n):
            used = 0
            for i in reg_cells[g]:
                m = cand[i]
                if m == 0:
                    return None
                if _is_single(m):
                    if used & m:
                        return None
                    used |= m
            reg_need[g] = full_mask & ~used

        return row_need, col_need, reg_need

    def basic_elimination(cand, row_need, col_need, reg_need):
        changed = False
        for i in range(num_cells):
            m = cand[i]
            if not _is_single(m):
                allowed = row_need[row_of[i]] & col_need[col_of[i]] & reg_need[reg_of[i]]
                new_m = m & allowed
                if new_m == 0:
                    return None
                if new_m != m:
                    cand[i] = new_m
                    changed = True
        return changed

    def hidden_singles(cand, row_need, col_need, reg_need):
        changed = False

        for r in range(n):
            for bit in _iter_bits(row_need[r]):
                spots = [i for i in row_cells[r] if cand[i] & bit]
                if not spots:
                    return None
                if len(spots) == 1 and cand[spots[0]] != bit:
                    cand[spots[0]] = bit
                    changed = True

        for c in range(n):
            for bit in _iter_bits(col_need[c]):
                spots = [i for i in col_cells[c] if cand[i] & bit]
                if not spots:
                    return None
                if len(spots) == 1 and cand[spots[0]] != bit:
                    cand[spots[0]] = bit
                    changed = True

        for g in range(n):
            for bit in _iter_bits(reg_need[g]):
                spots = [i for i in reg_cells[g] if cand[i] & bit]
                if not spots:
                    return None
                if len(spots) == 1 and cand[spots[0]] != bit:
                    cand[spots[0]] = bit
                    changed = True

        return changed

    def locked_candidates(cand, row_need, col_need, reg_need):
        changed = False

        # Pointing: region -> row/col
        for g in range(n):
            for bit in _iter_bits(reg_need[g]):
                poss = [i for i in reg_cells[g] if cand[i] & bit]
                if not poss:
                    return None

                rows = {row_of[i] for i in poss}
                if len(rows) == 1:
                    r = next(iter(rows))
                    for j in row_cells[r]:
                        if reg_of[j] != g and (cand[j] & bit):
                            new_m = cand[j] & ~bit
                            if new_m == 0:
                                return None
                            if new_m != cand[j]:
                                cand[j] = new_m
