    if any(not isinstance(row, list) or len(row) != n for row in data):
        raise ValueError("Data grid must be NxN")

    # Remap arbitrary region ids to dense 0..N-1 ids in first-seen order.
    remap = {}
    next_id = 0
    dense_region = []
    for row in region:
        new_row = []
        for rid in row:
            if rid not in remap:
                remap[rid] = next_id
                next_id += 1
            new_row.append(remap[rid])
        dense_region.append(new_row)

    if next_id != n:
