    if any(count != n for count in counts):
        raise ValueError("Each region must contain exactly N cells")

    dense_data = []
    for row in data:
        new_row = []
        for v in row:
            if v is None:
                new_row.append(None)
            elif isinstance(v, int) and 1 <= v <= n:
