        bit = branch[1]
        positions = branch[2][:]
        positions.sort(key=lambda idx: (st.cand[idx].bit_count(), -impact_score(st, idx, bit)))
        for idx in positions:
            nxt = st.copy()
            if assign_bit(nxt, idx, bit):
