class LatinJigsawSolver:
    def __init__(self, observation):
        self.region_grid = observation["region"]
        self.data_grid = observation["data"]
        self.n = len(self.region_grid)
        self.ncells = self.n * self.n
        self.allmask = (1 << self.n) - 1
        self.bit_to_val = {1 << i: i + 1 for i in range(self.n)}

        self.rows = [[] for _ in range(self.n)]
        self.cols = [[] for _ in range(self.n)]
        self.row_of = [0] * self.ncells
        self.col_of = [0] * self.ncells
        self.reg_of = [0] * self.ncells

        label_to_id = {}
        regions = []

        for r in range(self.n):
            if len(self.region_grid[r]) != self.n:
                raise ValueError("Region grid must be square")
            for c in range(self.n):
                label = self.region_grid[r][c]
                if label not in label_to_id:
                    label_to_id[label] = len(label_to_id)
                    regions.append([])
                g = label_to_id[label]
                idx = r * self.n + c
                self.rows[r].append(idx)
                self.cols[c].append(idx)
                regions[g].append(idx)
                self.row_of[idx] = r
                self.col_of[idx] = c
                self.reg_of[idx] = g

        self.regions = regions
        self.region_count = len(self.regions)
        self.units = [(0, self.rows), (1, self.cols), (2, self.regions)]

        self.peers = []
        for idx in range(self.ncells):
            s = set(self.rows[self.row_of[idx]])
            s.update(self.cols[self.col_of[idx]])
            s.update(self.regions[self.reg_of[idx]])
            s.discard(idx)
            self.peers.append(tuple(sorted(s)))

    def _is_singleton(self, mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def _mask_to_bits(self, mask):
        bits = []
        while mask:
            bit = mask & -mask
            bits.append(bit)
            mask -= bit
        return bits

    def _copy_state(self, state):
        return {
            "grid": state["grid"][:],
            "cand": state["cand"][:],
            "row_missing": state["row_missing"][:],
            "col_missing": state["col_missing"][:],
            "reg_missing": state["reg_missing"][:],
            "unsolved": state["unsolved"],
        }

    def _get_missing(self, state, kind, idx):
        if kind == 0:
            return state["row_missing"][idx]
        if kind == 1:
            return state["col_missing"][idx]
        return state["reg_missing"][idx]

    def _initial_state(self):
        if len(self.data_grid) != self.n:
            return None
        if self.region_count != self.n:
            return None
        for region in self.regions:
            if len(region) != self.n:
                return None

        row_missing = [self.allmask for _ in range(self.n)]
        col_missing = [self.allmask for _ in range(self.n)]
        reg_missing = [self.allmask for _ in range(self.n)]
        grid = [0] * self.ncells

        for r in range(self.n):
            if len(self.data_grid[r]) != self.n:
                return None
            for c in range(self.n):
                v = self.data_grid[r][c]
                if v is None:
                    continue
                if not isinstance(v, int) or not (1 <= v <= self.n):
                    return None
                idx = r * self.n + c
                g = self.reg_of[idx]
                bit = 1 << (v - 1)
                if not (row_missing[r] & bit and col_missing[c] & bit and reg_missing[g] & bit):
                    return None
                grid[idx] = v
                row_missing[r] &= ~bit
                col_missing[c] &= ~bit
                reg_missing[g] &= ~bit

        cand = [0] * self.ncells
        unsolved = 0
        for idx in range(self.ncells):
            if grid[idx]:
                cand[idx] = 1 << (grid[idx] - 1)
            else:
                unsolved += 1
                r = self.row_of[idx]
                c = self.col_of[idx]
                g = self.reg_of[idx]
                m = row_missing[r] & col_missing[c] & reg_missing[g]
