    def _enqueue(self, state, idx, queue, in_queue):
        if state["grid"][idx] == 0 and self._is_singleton(state["cand"][idx]) and not in_queue[idx]:
            queue.append(idx)
            in_queue[idx] = True

    def _eliminate(self, state, idx, remove_mask, queue, in_queue):
        cand = state["cand"]
        grid = state["grid"]

        if remove_mask == 0:
            return True

        if grid[idx]:
            return (cand[idx] & remove_mask) == 0

        newmask = cand[idx] & ~remove_mask
        if newmask == cand[idx]:
            return True
        if newmask == 0:
            return False

        cand[idx] = newmask
        if self._is_singleton(newmask):
            self._enqueue(state, idx, queue, in_queue)
        return True

