        grid = state["grid"]
        cand = state["cand"]

        if grid[idx]:
            return cand[idx] == bit
        if not (cand[idx] & bit):
            return False

        r = self.row_of[idx]
        c = self.col_of[idx]
        g = self.reg_of[idx]

