            return False
        if not (state["col_missing"][c] & bit):
            return False
        if not (state["reg_missing"][g] & bit):
            return False

        grid[idx] = self.bit_to_val[bit]
        cand[idx] = bit
        state["row_missing"][r] &= ~bit
        state["col_missing"][c] &= ~bit
        state["reg_missing"][g] &= ~bit
        state["unsolved"] -= 1

        for j in self.peers[idx]:
            if state["grid"][j] == 0 and (state["cand"][j] & bit):
