            newmask = state["cand"][idx] & allowed
            if newmask != state["cand"][idx]:
                remove = state["cand"][idx] & ~newmask
                if not self._eliminate(state, idx, remove, queue, in_queue):
                    return False, False
                changed = True
            if state["cand"][idx] == 0:
                return False, False
        return True, changed

    def _apply_unit_logic(self, state, kind, unit_index, cells, queue, in_queue):
        progress = False
        grid = state["grid"]
