        return score

    def _choose_branch(self, state):
        best_count = self.n + 1
        best_kind = None
        best_payload = None

        for kind, units in self.units:
            missing_arr = (
                state["row_missing"] if kind == 0 else
                state["col_missing"] if kind == 1 else
