        bit, positions = best_payload
        positions = [i for i in positions if state["grid"][i] == 0 and (state["cand"][i] & bit)]
        positions.sort(
            key=lambda i: (
                state["cand"][i].bit_count(),
                -sum(1 for j in self.peers[i] if state["grid"][j] == 0 and (state["cand"][j] & bit)),
            )
        )
        return ("unit", bit, positions)

    def _search(self, state):
        if not self._propagate(state, allow_forcing=True):
            return None
        if state["unsolved"] == 0:
            return state

        branch = self._choose_branch(state)
        if branch is None:
            return None

        if branch[0] == "cell":
            idx = branch[1]
            for bit in branch[2]:
                trial = self._copy_state(state)
                q = []
                iq = [False] * self.ncells
                if not self._assign(trial, idx, bit, q, iq):
