                q = []
                iq = [False] * self.ncells
                if not self._assign(trial, idx, bit, q, iq):
                    continue
                result = self._search(trial)
                if result is not None:
                    return result

        return None

    def solve(self):
        state = self._initial_state()
        if state is None:
            return None
        result = self._search(state)
        if result is None:
            return None
        return [
            [result["grid"][r * self.n + c] for c in range(self.n)]
            for r in range(self.n)
        ]


