                self.col_of[idx] = c
                self.reg_of[idx] = g

        self.regions = regions
        self.region_count = len(self.regions)
        self.units = [(0, self.rows), (1, self.cols), (2, self.regions)]

        self.peers = []
        for idx in range(self.ncells):
            s = set(self.rows[self.row_of[idx]])
            s.update(self.cols[self.col_of[idx]])
            s.update(self.regions[self.reg_of[idx]])
            s.discard(idx)
            self.peers.append(tuple(sorted(s)))

    def _is_singleton(self, mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def _mask_to_bits(self, mask):
        bits = []
        while mask:
            bit = mask & -mask
            bits.append(bit)
            mask -= bit
        return bits

    def _copy_state(self, state):
        return {
            "grid": state["grid"][:],
            "cand": state["cand"][:],
            "row_missing": state["row_missing"][:],
            "col_missing": state["col_missing"][:],
            "reg_missing": state["reg_missing"][:],
            "unsolved": state["unsolved"],
