            return None
        for region in self.regions:
            if len(region) != self.n:
                return None

        row_missing = [self.allmask for _ in range(self.n)]
        col_missing = [self.allmask for _ in range(self.n)]
        reg_missing = [self.allmask for _ in range(self.n)]
