            cell_houses[cell].append(hid)

    peers = []
    for cell in range(size):
        s = set()
        for hid in cell_houses[cell]:
            s.update(houses[hid])
        s.discard(cell)
        peers.append(tuple(s))

    # Intersection-based helper tables.
    region_by_row = [[[] for _ in range(n)] for _ in range(n)]
    region_by_col = [[[] for _ in range(n)] for _ in range(n)]
    for rid, cells in enumerate(region_cells):
        for cell in cells:
            region_by_row[rid][row_of[cell]].append(cell)
            region_by_col[rid][col_of[cell]].append(cell)

    # Initial candidate masks.
    initial = [full_mask] * size
    for r in range(n):
        for c in range(n):
            value = data_grid[r][c]
            if value in (None, 0):
                continue
            if not isinstance(value, int) or not (1 <= value <= n):
                return "No Solution"
            initial[r * n + c] = 1 << (value - 1)

    def propagate(cand):
        # Repeatedly apply human-style deductions:
        # - peer elimination from singles
        # - hidden singles
        # - locked candidates (pointing/claiming)
        # - naked subsets up to size 4
        # - hidden subsets up to size 4
        processed_single = [0] * size
        queue = [i for i, m in enumerate(cand) if is_single(m)]

        while True:
            changed = False

            # 1) Standard singleton propagation.
            while queue:
                cell = queue.pop()
                mask = cand[cell]
                if mask == 0:
                    return None
                if not is_single(mask):
                    continue
                if processed_single[cell] == mask:
                    continue
                if processed_single[cell] and processed_single[cell] != mask:
                    return None
                processed_single[cell] = mask

                for peer in peers[cell]:
                    if cand[peer] & mask:
                        chg = update_mask(cand, peer, cand[peer] & ~mask, queue)
                        if chg < 0:
                            return None
                        if chg:
                            changed = True

            # 2) House scans: contradictions, hidden singles, subsets.
            for house in houses:
                counts = [0] * n
                last_cell = [-1] * n
                unsolved = []

                for cell in house:
                    mask = cand[cell]
                    if mask == 0:
                        return None
                    if not is_single(mask):
                        unsolved.append(cell)
                    mm = mask
                    while mm:
                        bit = mm & -mm
                        d = bit.bit_length() - 1
                        counts[d] += 1
                        last_cell[d] = cell
                        mm ^= bit

                # Every digit must still be placeable somewhere in the house.
                for d, cnt in enumerate(counts):
                    if cnt == 0:
                        return None
                    if cnt == 1:
                        bit = 1 << d
                        cell = last_cell[d]
                        if cand[cell] != bit:
                            chg = update_mask(cand, cell, bit, queue)
                            if chg < 0:
                                return None
                            if chg:
                                changed = True

                if len(unsolved) < 2:
                    continue

                max_subset = min(4, len(unsolved) - 1)
                unsolved_masks = [cand[cell] for cell in unsolved]

                # 2a) Fast identical-mask naked subsets.
                freq = {}
                for i, mask in enumerate(unsolved_masks):
                    bc = mask.bit_count()
                    if 2 <= bc <= max_subset:
                        freq.setdefault(mask, []).append(i)

                for subset_mask, idxs in freq.items():
                    k = subset_mask.bit_count()
                    if len(idxs) != k:
                        continue
                    idxs = set(idxs)
                    for i, cell in enumerate(unsolved):
                        if i in idxs:
                            continue
                        if cand[cell] & subset_mask:
                            chg = update_mask(cand, cell, cand[cell] & ~subset_mask, queue)
                            if chg < 0:
                                return None
                            if chg:
                                changed = True

                # 2b) General naked subsets.
                unsolved_count = len(unsolved)
                for k in range(2, max_subset + 1):
                    for comb in combinations(range(unsolved_count), k):
                        union = 0
                        for i in comb:
                            union |= unsolved_masks[i]
                        if union.bit_count() != k:
                            continue
                        comb = set(comb)
                        for i, cell in enumerate(unsolved):
                            if i in comb:
                                continue
                            if cand[cell] & union:
                                chg = update_mask(cand, cell, cand[cell] & ~union, queue)
                                if chg < 0:
                                    return None
                                if chg:
                                    changed = True

                # 2c) Hidden subsets.
                digit_pool = [d for d, cnt in enumerate(counts) if 1 < cnt <= max_subset]
                for k in range(2, min(4, len(digit_pool)) + 1):
                    for ds in combinations(digit_pool, k):
                        subset_mask = 0
                        cellset = set()
                        for d in ds:
                            bit = 1 << d
                            subset_mask |= bit
                            for cell in house:
                                if cand[cell] & bit:
                                    cellset.add(cell)
                        if len(cellset) != k:
                            continue
                        for cell in cellset:
                            chg = update_mask(cand, cell, cand[cell] & subset_mask, queue)
                            if chg < 0:
                                return None
                            if chg:
                                changed = True

            # 3) Locked candidates: region -> row/col (pointing).
            for rid, cells in enumerate(region_cells):
                for bit in bits:
                    hit_rows = []
                    hit_cols = []
                    for cell in cells:
                        if cand[cell] & bit:
                            hit_rows.append(row_of[cell])
                            hit_cols.append(col_of[cell])
                    if not hit_rows:
                        return None

                    if len(set(hit_rows)) == 1:
                        r = hit_rows[0]
                        for cell in rows[r]:
                            if region_of[cell] != rid and (cand[cell] & bit):
                                chg = update_mask(cand, cell, cand[cell] & ~bit, queue)
                                if chg < 0:
                                    return None
                                if chg:
                                    changed = True

                    if len(set(hit_cols)) == 1:
                        c = hit_cols[0]
                        for cell in cols[c]:
                            if region_of[cell] != rid and (cand[cell] & bit):
                                chg = update_mask(cand, cell, cand[cell] & ~bit, queue)
                                if chg < 0:
                                    return None
                                if chg:
                                    changed = True

            # 4) Locked candidates: row/col -> region (claiming).
            for r in range(n):
                row_cells = rows[r]
                for bit in bits:
                    hit_regions = []
                    for cell in row_cells:
                        if cand[cell] & bit:
                            hit_regions.append(region_of[cell])
                    if not hit_regions:
                        return None
                    if len(set(hit_regions)) == 1:
                        rid = hit_regions[0]
                        for cell in region_by_row[rid][r]:
                            pass
                        for cell in region_cells[rid]:
                            if row_of[cell] != r and (cand[cell] & bit):
                                chg = update_mask(cand, cell, cand[cell] & ~bit, queue)
                                if chg < 0:
                                    return None
                                if chg:
                                    changed = True

            for c in range(n):
                col_cells = cols[c]
                for bit in bits:
                    hit_regions = []
                    for cell in col_cells:
                        if cand[cell] & bit:
                            hit_regions.append(region_of[cell])
                    if not hit_regions:
                        return None
                    if len(set(hit_regions)) == 1:
                        rid = hit_regions[0]
                        for cell in region_cells[rid]:
                            if col_of[cell] != c and (cand[cell] & bit):
                                chg = update_mask(cand, cell, cand[cell] & ~bit, queue)
                                if chg < 0:
                                    return None
                                if chg:
                                    changed = True

            if not changed:
                return cand

    def candidate_order(cell, mask, cand):
        # Prefer values that are already highly constrained in row/col/region.
        scored = []
        mm = mask
        while mm:
            bit = mm & -mm
            mm ^= bit
            score = 0
            for hid in cell_houses[cell]:
                cnt = 0
                for hcell in houses[hid]:
                    if cand[hcell] & bit:
                        cnt += 1
                score += cnt
            impact = 0
            for peer in peers[cell]:
                if cand[peer] & bit:
                    impact += 1
            scored.append((score, -impact, bit))
        scored.sort()
        return [bit for _, __, bit in scored]

    def choose_branches(cand):
        # Main branching heuristic:
        # 1) minimum remaining values cell
        # 2) if even stronger, a house-digit with very few positions
        best_cell = -1
        best_cell_count = n + 1
        best_peer_pressure = -1

        for cell, mask in enumerate(cand):
            bc = mask.bit_count()
            if bc <= 1:
                continue
            peer_pressure = 0
            for peer in peers[cell]:
                if not is_single(cand[peer]):
                    peer_pressure += 1
            if bc < best_cell_count or (bc == best_cell_count and peer_pressure > best_peer_pressure):
                best_cell = cell
                best_cell_count = bc
                best_peer_pressure = peer_pressure

        best_places = None
        best_places_bit = 0
        best_places_count = n + 1

        for house in houses:
            counts = [0] * n
            cells_for_digit = [[] for _ in range(n)]
            for cell in house:
                mm = cand[cell]
                while mm:
                    bit = mm & -mm
                    d = bit.bit_length() - 1
                    counts[d] += 1
                    cells_for_digit[d].append(cell)
                    mm ^= bit
            for d, cnt in enumerate(counts):
                if 1 < cnt < best_places_count:
                    best_places_count = cnt
                    best_places_bit = 1 << d
                    best_places = cells_for_digit[d]

        if best_places is not None and best_places_count < best_cell_count:
            ordered_cells = sorted(
                best_places,
                key=lambda cell: (cand[cell].bit_count(), -sum(1 for peer in peers[cell] if not is_single(cand[peer])))
            )
            return [(cell, best_places_bit) for cell in ordered_cells]

        ordered_bits = candidate_order(best_cell, cand[best_cell], cand)
        return [(best_cell, bit) for bit in ordered_bits]

    failed = set()

    def search(cand):
        cand = propagate(cand)
        if cand is None:
            return None

        key = tuple(cand)
        if key in failed:
            return None

        if all(is_single(mask) for mask in cand):
            return cand

        for cell, bit in choose_branches(cand):
            nxt = cand[:]
            nxt[cell] = bit
            solved = search(nxt)
            if solved is not None:
                return solved

        failed.add(key)
        return None

    solved = search(initial[:])
    if solved is None:
        return "No Solution"

    # Final exact validation.
    for house in houses:
        seen = 0
        for cell in house:
            mask = solved[cell]
            if not is_single(mask) or (seen & mask):
                return "No Solution"
            seen |= mask
        if seen != full_mask:
            return "No Solution"

    grid = [[solved[r * n + c].bit_length() for c in range(n)] for r in range(n)]
    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

