# General irregular Sudoku / Latin-region solver.
# Strategy:
# 1) Bitmask candidates.
# 2) Strong propagation:
#    - direct singles
#    - hidden singles
#    - locked candidates (region<->row/col)
#    - naked subsets
#    - hidden subsets
# 3) If needed, branch on the most constrained cell or unit-digit placement.

from itertools import combinations
import sys

sys.setrecursionlimit(10000)


class State:
    __slots__ = ("cand", "values", "row_used", "col_used", "reg_used", "unsolved")

    def __init__(self, cand, values, row_used, col_used, reg_used, unsolved):
        self.cand = cand
        self.values = values
        self.row_used = row_used
        self.col_used = col_used
        self.reg_used = reg_used
        self.unsolved = unsolved

    def clone(self):
        return State(
            self.cand[:],
            self.values[:],
            self.row_used[:],
            self.col_used[:],
            self.reg_used[:],
            self.unsolved,
        )


class JigsawLatinSolver:
    def __init__(self, observation):
        region = observation["region"]
        data = observation["data"]

        if not isinstance(region, list) or not isinstance(data, list) or not region or not data:
            raise ValueError("Invalid observation")

        n = len(data)
        if any(len(row) != n for row in data):
            raise ValueError("Data must be NxN")
        if len(region) != n or any(len(row) != n for row in region):
            raise ValueError("Region grid must be NxN")

        self.N = n
        self.ALL = (1 << n) - 1
        self.size = n * n

        # Normalize arbitrary region ids to 0..N-1
        remap = {}
        next_id = 0
        norm_region = [[0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                rid = region[r][c]
                if rid not in remap:
                    remap[rid] = next_id
                    next_id += 1
                norm_region[r][c] = remap[rid]

        if next_id != n:
            raise ValueError("Number of regions must equal N")

        self.region_grid = norm_region
        self.row_of = [i // n for i in range(self.size)]
        self.col_of = [i % n for i in range(self.size)]
        self.region_of = [norm_region[i // n][i % n] for i in range(self.size)]

        self.rows = [tuple(r * n + c for c in range(n)) for r in range(n)]
        self.cols = [tuple(r * n + c for r in range(n)) for c in range(n)]
        regs = [[] for _ in range(n)]
        for i, g in enumerate(self.region_of):
            regs[g].append(i)
        self.regs = [tuple(cells) for cells in regs]

        if any(len(cells) != n for cells in self.regs):
            raise ValueError("Each region must contain exactly N cells")

        # Peer sets
        peers = []
        for i in range(self.size):
            r = self.row_of[i]
            c = self.col_of[i]
            g = self.region_of[i]
            s = set(self.rows[r])
            s.update(self.cols[c])
            s.update(self.regs[g])
            s.discard(i)
            peers.append(tuple(s))
        self.peers = peers

        # Static intersections for faster locked-candidate eliminations
        self.row_outside_reg = [
            [tuple(i for i in self.rows[r] if self.region_of[i] != g) for g in range(n)]
            for r in range(n)
        ]
        self.col_outside_reg = [
            [tuple(i for i in self.cols[c] if self.region_of[i] != g) for g in range(n)]
            for c in range(n)
        ]
        self.reg_outside_row = [
            [tuple(i for i in self.regs[g] if self.row_of[i] != r) for r in range(n)]
            for g in range(n)
        ]
        self.reg_outside_col = [
            [tuple(i for i in self.regs[g] if self.col_of[i] != c) for c in range(n)]
            for g in range(n)
        ]

        # Flatten givens
        self.givens = [0] * self.size
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v in (None, 0):
                    continue
                if not isinstance(v, int) or not (1 <= v <= n):
                    raise ValueError("Invalid given value")
                self.givens[r * n + c] = v

        self.units = self.rows + self.cols + self.regs

    def make_state(self):
        st = State(
            cand=[self.ALL] * self.size,
            values=[0] * self.size,
            row_used=[0] * self.N,
            col_used=[0] * self.N,
            reg_used=[0] * self.N,
            unsolved=self.size,
        )
        for idx, v in enumerate(self.givens):
            if v:
                if not self.assign(st, idx, 1 << (v - 1)):
                    return None
        return st

    def assign(self, st, idx, bit):
        cur = st.cand[idx]
        if not (cur & bit):
            return False
        if st.values[idx]:
            return cur == bit

        r = self.row_of[idx]
        c = self.col_of[idx]
        g = self.region_of[idx]
        if (st.row_used[r] & bit) or (st.col_used[c] & bit) or (st.reg_used[g] & bit):
            return False

        st.values[idx] = bit.bit_length()
        st.cand[idx] = bit
        st.row_used[r] |= bit
        st.col_used[c] |= bit
        st.reg_used[g] |= bit
        st.unsolved -= 1

        for p in self.peers[idx]:
            ok, _ = self.eliminate(st, p, bit)
            if not ok:
                return False
        return True

    def eliminate(self, st, idx, mask):
        cur = st.cand[idx]
        rem = cur & mask
        if rem == 0:
            return True, False

        if st.values[idx]:
            return False, False

        new = cur & ~rem
        if new == 0:
            return False, False
        if new == cur:
            return True, False

        st.cand[idx] = new
        if new & (new - 1) == 0:
            if not self.assign(st, idx, new):
                return False, False
        return True, True

    def restrict_to(self, st, idx, mask):
        cur = st.cand[idx]
        new = cur & mask
        if new == 0:
            return False, False
        if new == cur:
            return True, False
        if st.values[idx]:
            return False, False

        st.cand[idx] = new
        if new & (new - 1) == 0:
            if not self.assign(st, idx, new):
                return False, False
        return True, True

    def hidden_singles(self, st):
        changed = False

        # Rows
        for r, unit in enumerate(self.rows):
            ok, ch = self._hidden_singles_unit(st, unit, st.row_used[r])
            if not ok:
                return False, False
            changed |= ch

        # Cols
        for c, unit in enumerate(self.cols):
            ok, ch = self._hidden_singles_unit(st, unit, st.col_used[c])
            if not ok:
                return False, False
            changed |= ch

        # Regions
        for g, unit in enumerate(self.regs):
            ok, ch = self._hidden_singles_unit(st, unit, st.reg_used[g])
            if not ok:
                return False, False
            changed |= ch

        return True, changed

    def _hidden_singles_unit(self, st, unit, used_mask):
        changed = False
        counts = [0] * self.N
        last = [-1] * self.N

        for idx in unit:
            if st.values[idx]:
                continue
            m = st.cand[idx]
            while m:
                b = m & -m
                d = b.bit_length() - 1
                counts[d] += 1
                last[d] = idx
                m ^= b

        missing = self.ALL & ~used_mask
        m = missing
        while m:
            b = m & -m
            d = b.bit_length() - 1
            if counts[d] == 0:
                return False, False
            if counts[d] == 1:
                idx = last[d]
                if idx < 0 or not self.assign(st, idx, b):
                    return False, False
                changed = True
            m ^= b
        return True, changed

    def locked_candidates(self, st):
        changed = False

        # Region -> row / col
        for g, unit in enumerate(self.regs):
            missing = self.ALL & ~st.reg_used[g]
            m = missing
            while m:
                b = m & -m
                cells = [idx for idx in unit if not st.values[idx] and (st.cand[idx] & b)]
                if not cells:
                    return False, False

                r0 = self.row_of[cells[0]]
                if all(self.row_of[idx] == r0 for idx in cells):
                    for j in self.row_outside_reg[r0][g]:
                        ok, ch = self.eliminate(st, j, b)
                        if not ok:
                            return False, False
                        changed |= ch

                c0 = self.col_of[cells[0]]
                if all(self.col_of[idx] == c0 for idx in cells):
                    for j in self.col_outside_reg[c0][g]:
                        ok, ch = self.eliminate(st, j, b)
                        if not ok:
                            return False, False
                        changed |= ch
                m ^= b

        # Row -> region
        for r, unit in enumerate(self.rows):
            missing = self.ALL & ~st.row_used[r]
            m = missing
            while m:
                b = m & -m
                cells = [idx for idx in unit if not st.values[idx] and (st.cand[idx] & b)]
                if not cells:
                    return False, False
                g0 = self.region_of[cells[0]]
                if all(self.region_of[idx] == g0 for idx in cells):
                    for j in self.reg_outside_row[g0][r]:
                        ok, ch = self.eliminate(st, j, b)
                        if not ok:
                            return False, False
                        changed |= ch
                m ^= b

        # Col -> region
        for c, unit in enumerate(self.cols):
            missing = self.ALL & ~st.col_used[c]
            m = missing
            while m:
                b = m & -m
                cells = [idx for idx in unit if not st.values[idx] and (st.cand[idx] & b)]
                if not cells:
                    return False, False
                g0 = self.region_of[cells[0]]
                if all(self.region_of[idx] == g0 for idx in cells):
                    for j in self.reg_outside_col[g0][c]:
                        ok, ch = self.eliminate(st, j, b)
                        if not ok:
                            return False, False
                        changed |= ch
                m ^= b

        return True, changed

    def naked_subsets(self, st, max_k=4):
        changed = False

        for unit in self.units:
            uns = [idx for idx in unit if not st.values[idx]]
            ulen = len(uns)
            if ulen < 2:
                continue

            limit = min(max_k, ulen - 1)
            if limit < 2:
                continue

            small = [idx for idx in uns if 2 <= st.cand[idx].bit_count() <= limit]
            if len(small) < 2:
                continue

            for k in range(2, limit + 1):
                pool = [idx for idx in small if st.cand[idx].bit_count() <= k]
                if len(pool) < k:
                    continue
                for combo in combinations(pool, k):
                    union = 0
                    for idx in combo:
                        union |= st.cand[idx]
                    if union.bit_count() != k:
                        continue
                    combo_set = set(combo)
                    for j in uns:
                        if j in combo_set:
                            continue
                        ok, ch = self.eliminate(st, j, union)
                        if not ok:
                            return False, False
                        changed |= ch

        return True, changed

    def hidden_subsets(self, st, max_k=4):
        changed = False

        for unit in self.units:
            uns = [idx for idx in unit if not st.values[idx]]
            if len(uns) < 2:
                continue

            used = 0
            for idx in unit:
                if st.values[idx]:
                    used |= st.cand[idx]
            missing = self.ALL & ~used

            posmask = {}
            digits = []
            m = missing
            while m:
                b = m & -m
                pm = 0
                for pos, idx in enumerate(uns):
                    if st.cand[idx] & b:
                        pm |= 1 << pos
                if pm == 0:
                    return False, False
                if 1 < pm.bit_count() <= max_k:
                    digits.append(b)
                    posmask[b] = pm
                m ^= b

            if len(digits) < 2:
                continue

            limit = min(max_k, len(digits))
            for k in range(2, limit + 1):
                for combo in combinations(digits, k):
                    cells_pm = 0
                    digits_mask = 0
                    for b in combo:
                        cells_pm |= posmask[b]
                        digits_mask |= b
                    if cells_pm.bit_count() != k:
                        continue
                    pm = cells_pm
                    while pm:
                        lb = pm & -pm
                        pos = lb.bit_length() - 1
                        idx = uns[pos]
                        ok, ch = self.restrict_to(st, idx, digits_mask)
                        if not ok:
                            return False, False
