from functools import lru_cache


@lru_cache(maxsize=None)
def masks_for_sum(weights, target):
    weights = tuple(weights)
    length = len(weights)

    @lru_cache(maxsize=None)
    def rec(i, rem):
        if rem == 0:
            return (0,)
        if rem < 0 or i == length:
            return ()
        out = list(rec(i + 1, rem))
        bit = 1 << i
        w = weights[i]
        if rem >= w:
            for sub in rec(i + 1, rem - w):
                out.append(sub | bit)
        return tuple(out)

    masks = rec(0, target)
    if not masks:
        return ()
    return tuple(sorted(masks, key=lambda x: (x.bit_count(), x)))


def normalize_fixed_value(value):
    if value is True or value == 1:
        return 1
