from functools import lru_cache
import sys

sys.setrecursionlimit(10000)


def solve(observation):
    row_sum = list(observation.get("row_sum", ()))
    col_sum = list(observation.get("col_sum", ()))
    if not row_sum or not col_sum:
        return "No Solution"

