    col_weight = list(observation.get("col_weight", observation.get("col_weights", list(range(1, n + 1)))))

    if len(row_weight) != m or len(col_weight) != n:
        return "No Solution"
    if any(x < 0 for x in row_sum) or any(x < 0 for x in col_sum):
        return "No Solution"
    if any(w < 0 for w in row_weight) or any(w < 0 for w in col_weight):
        return "No Solution"

