        @lru_cache(maxsize=None)
        def rec(i, remain):
            if remain < 0 or remain > suffix[i]:
                return ()
            if i == length:
                return (0,) if remain == 0 else ()

            out = list(rec(i + 1, remain))
            w = weights[i]
            if remain >= w:
                bit = 1 << i
                for tail in rec(i + 1, remain - w):
                    out.append(bit | tail)
            return tuple(out)

