                rdom = tuple(mask for mask in row_domains[r] if (mask >> c) & 1)
                cdom = tuple(mask for mask in col_domains[c] if (mask >> r) & 1)
            else:
                rdom = tuple(mask for mask in row_domains[r] if not ((mask >> c) & 1))
                cdom = tuple(mask for mask in col_domains[c] if not ((mask >> r) & 1))

            if not rdom or not cdom:
                return None
            row_domains[r] = rdom
            col_domains[c] = cdom

        return tuple(row_domains), tuple(col_domains)

    fixed_state = apply_fixed(row_domains, col_domains, fixed_black, True)
    if fixed_state is None:
        return "No Solution"
    row_domains, col_domains = fixed_state

    fixed_state = apply_fixed(row_domains, col_domains, fixed_white, False)
    if fixed_state is None:
        return "No Solution"
    row_domains, col_domains = fixed_state

    # Human-style deduction:
    # - each row/column keeps only legal patterns
    # - forced cells emerge when the opposite direction cannot support 0 or 1
    # - repeat until stable (arc consistency over cells)
    def propagate(row_domains, col_domains):
        row_domains = tuple(tuple(d) for d in row_domains)
        col_domains = tuple(tuple(d) for d in col_domains)

        while True:
            if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
                return None

            changed = False

            # What values can each column still place in each row?
            col_support1 = [0] * n
            col_support0 = [0] * n
            for c, dom in enumerate(col_domains):
                s1 = 0
                s0 = 0
                for mask in dom:
                    s1 |= mask
                    s0 |= all_rows_mask ^ mask
                col_support1[c] = s1
                col_support0[c] = s0

            # Remove row patterns containing unsupported cell values.
            new_rows = []
            for r, dom in enumerate(row_domains):
