                bad1 = 0
                bad0 = 0
                for c in range(n):
                    cbit = 1 << c
                    if not (col_support1[c] & rbit):
                        bad1 |= cbit
                    if not (col_support0[c] & rbit):
                        bad0 |= cbit

                nd = tuple(
                    mask
                    for mask in dom
                    if not (mask & bad1) and not ((all_cols_mask ^ mask) & bad0)
                )
                if not nd:
                    return None
                if len(nd) != len(dom):
                    changed = True
                new_rows.append(nd)
            row_domains = tuple(new_rows)

            # What values can each row still place in each column?
            row_support1 = [0] * m
            row_support0 = [0] * m
            for r, dom in enumerate(row_domains):
                s1 = 0
                s0 = 0
                for mask in dom:
                    s1 |= mask
                    s0 |= all_cols_mask ^ mask
                row_support1[r] = s1
                row_support0[r] = s0

            # Remove column patterns containing unsupported cell values.
            new_cols = []
            for c, dom in enumerate(col_domains):
                cbit = 1 << c
                bad1 = 0
                bad0 = 0
                for r in range(m):
                    rbit = 1 << r
                    if not (row_support1[r] & cbit):
                        bad1 |= rbit
                    if not (row_support0[r] & cbit):
                        bad0 |= rbit

                nd = tuple(
                    mask
                    for mask in dom
                    if not (mask & bad1) and not ((all_rows_mask ^ mask) & bad0)
                )
                if not nd:
                    return None
                if len(nd) != len(dom):
                    changed = True
                new_cols.append(nd)
            col_domains = tuple(new_cols)

            if not changed:
                return row_domains, col_domains

    def domain_uncertainty(dom, full_mask):
        union = 0
        inter = full_mask
        for mask in dom:
            union |= mask
            inter &= mask
        return (union ^ inter).bit_count()

    def choose_branch(row_domains, col_domains):
        best = None

        for r, dom in enumerate(row_domains):
            if len(dom) > 1:
                key = (len(dom), domain_uncertainty(dom, all_cols_mask), 0, r)
                if best is None or key < best:
                    best = key

        for c, dom in enumerate(col_domains):
            if len(dom) > 1:
                key = (len(dom), domain_uncertainty(dom, all_rows_mask), 1, c)
                if best is None or key < best:
                    best = key

        return best

    # Try the most restrictive pattern first.
    def ordered_row_choices(r, dom, col_domains):
        col_sizes = [len(d) for d in col_domains]
        ones = [0] * n
        for c, cdom in enumerate(col_domains):
            cnt = 0
            for mask in cdom:
                cnt += (mask >> r) & 1
            ones[c] = cnt

        scored = []
        for mask in dom:
            score = 0
            for c in range(n):
                score += ones[c] if ((mask >> c) & 1) else (col_sizes[c] - ones[c])
            scored.append((score, mask.bit_count(), mask))
        scored.sort()
        return [mask for _, _, mask in scored]

    def ordered_col_choices(c, dom, row_domains):
        row_sizes = [len(d) for d in row_domains]
        ones = [0] * m
        for r, rdom in enumerate(row_domains):
            cnt = 0
            for mask in rdom:
                cnt += (mask >> c) & 1
            ones[r] = cnt

        scored = []
        for mask in dom:
            score = 0
            for r in range(m):
                score += ones[r] if ((mask >> r) & 1) else (row_sizes[r] - ones[r])
            scored.append((score, mask.bit_count(), mask))
        scored.sort()
        return [mask for _, _, mask in scored]

    failed = set()

    def dfs(row_domains, col_domains):
        state = propagate(row_domains, col_domains)
        if state is None:
            return None

        row_domains, col_domains = state

        if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
            return row_domains, col_domains

        key = (row_domains, col_domains)
        if key in failed:
            return None

        branch = choose_branch(row_domains, col_domains)
        if branch is None:
            return row_domains, col_domains

        _, _, kind, idx = branch

        if kind == 0:
            for mask in ordered_row_choices(idx, row_domains[idx], col_domains):
                new_rows = list(row_domains)
                new_rows[idx] = (mask,)
                result = dfs(tuple(new_rows), col_domains)
                if result is not None:
                    return result
        else:
            for mask in ordered_col_choices(idx, col_domains[idx], row_domains):
                new_cols = list(col_domains)
                new_cols[idx] = (mask,)
                result = dfs(row_domains, tuple(new_cols))
                if result is not None:
                    return result

        failed.add(key)
        return None

    result = dfs(tuple(row_domains), tuple(col_domains))
    if result is None:
        return "No Solution"

    row_domains, _ = result
    row_masks = [dom[0] for dom in row_domains]

    # Final verification.
    for r, mask in enumerate(row_masks):
        total = 0
        for c, w in enumerate(col_weight):
            if (mask >> c) & 1:
                total += w
        if total != row_sum[r]:
            return "No Solution"

    for c, target in enumerate(col_sum):
        total = 0
        for r, w in enumerate(row_weight):
            if (row_masks[r] >> c) & 1:
                total += w
        if total != target:
            return "No Solution"

    grid = []
    for r in range(m):
        row = []
        mask = row_masks[r]
        for c in range(n):
            row.append("B" if ((mask >> c) & 1) else None)
        grid.append(row)

    return repr(grid)


