@lru_cache(None)
def patterns(weights, target):
    # All subset bitmasks whose selected weights sum to target.
    n = len(weights)
    if target < 0:
        return ()
    total = sum(weights)
    if target > total:
        return ()

    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]

    out = []

    def dfs(idx, rem, mask):
        if rem == 0:
            out.append(mask)
            return
        if idx == n or rem < 0 or rem > suffix[idx]:
            return

        # Human-style split: either this weight is not used, or it is used.
        dfs(idx + 1, rem, mask)
        w = weights[idx]
        if w <= rem:
            dfs(idx + 1, rem - w, mask | (1 << idx))

    dfs(0, target, 0)
    out.sort()
    return tuple(out)


