            count1[r] = ones
            count0[r] = len(r_domains[r]) - ones

        def score(mask):
            total = 0
            for r in range(R):
                total += count1[r] if ((mask >> r) & 1) else count0[r]
            return total

        return tuple(sorted(dom, key=score))

