    def build_mask_generator(weights):
        n = len(weights)
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + weights[i]

        @lru_cache(maxsize=None)
        def rec(i, target):
            if target < 0 or target > suffix[i]:
                return ()
            if i == n:
                return (0,) if target == 0 else ()

            without_i = rec(i + 1, target)
            w = weights[i]
            if target < w:
                return without_i

            with_i_base = rec(i + 1, target - w)
            if not with_i_base:
                return without_i

            bit = 1 << i
            return without_i + tuple(m | bit for m in with_i_base)

        @lru_cache(maxsize=None)
        def masks_for_target(target):
            return rec(0, target)

        return masks_for_target

