from functools import lru_cache


def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]

    n_rows = len(row_sum)
    n_cols = len(col_sum)

    row_weights = list(range(1, n_rows + 1))
    col_weights = list(range(1, n_cols + 1))

    full_row_mask = (1 << n_rows) - 1
    full_col_mask = (1 << n_cols) - 1

    def candidate_map(weights, targets):
        n = len(weights)
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + weights[i]

        @lru_cache(None)
        def build(i, remain):
            if remain == 0:
                return (0,)
            if i == n or remain < 0 or remain > suffix[i]:
                return ()
            res = list(build(i + 1, remain))
            w = weights[i]
            if w <= remain:
                bit = 1 << i
                res.extend(mask | bit for mask in build(i + 1, remain - w))
            return tuple(res)

        out = {}
        for t in set(targets):
            out[t] = list(build(0, t))
        return out

    row_cands_by_target = candidate_map(col_weights, row_sum)
    col_cands_by_target = candidate_map(row_weights, col_sum)

    row_domains = [row_cands_by_target.get(t, [])[:] for t in row_sum]
    col_domains = [col_cands_by_target.get(t, [])[:] for t in col_sum]

    if any(not d for d in row_domains) or any(not d for d in col_domains):
        return "No Solution"

    def summarize(domains, full_mask):
        ors = [0] * len(domains)
        ands = [full_mask] * len(domains)
        for idx, dom in enumerate(domains):
            if not dom:
                return None, None
            o = 0
            a = full_mask
            for m in dom:
                o |= m
                a &= m
            ors[idx] = o
            ands[idx] = a
        return ors, ands

    def propagate(r_domains, c_domains):
        while True:
            row_or, row_and = summarize(r_domains, full_col_mask)
            if row_or is None:
                return None
            col_or, col_and = summarize(c_domains, full_row_mask)
            if col_or is None:
                return None

            changed = False

            # Row filtering by current column possibilities.
            for i, dom in enumerate(r_domains):
                bit_i = 1 << i
                disallow_black = 0
                require_black = 0
                for j in range(n_cols):
                    bit_j = 1 << j
                    if not (col_or[j] & bit_i):
                        disallow_black |= bit_j
                    if col_and[j] & bit_i:
                        require_black |= bit_j
                if disallow_black or require_black:
                    new_dom = [
                        m
                        for m in dom
                        if (m & disallow_black) == 0 and (m & require_black) == require_black
                    ]
                    if not new_dom:
                        return None
                    if len(new_dom) != len(dom):
                        r_domains[i] = new_dom
                        changed = True

            row_or, row_and = summarize(r_domains, full_col_mask)
            if row_or is None:
                return None

            # Column filtering by current row possibilities.
            for j, dom in enumerate(c_domains):
                bit_j = 1 << j
                disallow_black = 0
                require_black = 0
                for i in range(n_rows):
                    bit_i = 1 << i
                    if not (row_or[i] & bit_j):
                        disallow_black |= bit_i
                    if row_and[i] & bit_j:
                        require_black |= bit_i
                if disallow_black or require_black:
                    new_dom = [
                        m
                        for m in dom
                        if (m & disallow_black) == 0 and (m & require_black) == require_black
                    ]
                    if not new_dom:
                        return None
                    if len(new_dom) != len(dom):
                        c_domains[j] = new_dom
                        changed = True

            if not changed:
                return r_domains, c_domains

    def validate(row_masks):
        for j, target in enumerate(col_sum):
            bit_j = 1 << j
            s = 0
            for i, mask in enumerate(row_masks):
                if mask & bit_j:
                    s += row_weights[i]
            if s != target:
                return False
        return True

    def choose_cell(r_domains, c_domains):
        best = None
        best_score = None

        for i in range(n_rows):
            rdom = r_domains[i]
            lr = len(rdom)
            if lr <= 1:
                continue
            for j in range(n_cols):
                bit_j = 1 << j
                rb = sum(1 for m in rdom if m & bit_j)
                if rb == 0 or rb == lr:
                    continue

                cdom = c_domains[j]
                lc = len(cdom)
                bit_i = 1 << i
                cb = sum(1 for m in cdom if m & bit_i)
                if cb == 0 or cb == lc:
                    continue

                black_support = rb * cb
                white_support = (lr - rb) * (lc - cb)

                score = (
                    max(black_support, white_support),
                    black_support + white_support,
                    abs(black_support - white_support),
                    lr + lc,
                )
                order = [1, 0] if black_support <= white_support else [0, 1]

                if best is None or score < best_score:
                    best = (i, j, order)
                    best_score = score

        if best is not None:
            return best

        # Fallback: choose a smallest undecided line and split on its best pivot cell.
        best_line = None
        for i, dom in enumerate(r_domains):
            if len(dom) > 1 and (best_line is None or len(dom) < best_line[2]):
                best_line = ("row", i, len(dom))
        for j, dom in enumerate(c_domains):
            if len(dom) > 1 and (best_line is None or len(dom) < best_line[2]):
                best_line = ("col", j, len(dom))

        if best_line is None:
            return None

        kind, idx, _ = best_line
        if kind == "row":
            i = idx
            dom = r_domains[i]
            best_j = None
            best_delta = None
            for j in range(n_cols):
                cnt = sum(1 for m in dom if (m >> j) & 1)
                if 0 < cnt < len(dom):
                    delta = abs(len(dom) - 2 * cnt)
                    if best_j is None or delta < best_delta:
                        best_j = j
                        best_delta = delta
            if best_j is None:
                return None
            j = best_j
        else:
            j = idx
            dom = c_domains[j]
            best_i = None
            best_delta = None
            for i in range(n_rows):
                cnt = sum(1 for m in dom if (m >> i) & 1)
                if 0 < cnt < len(dom):
                    delta = abs(len(dom) - 2 * cnt)
                    if best_i is None or delta < best_delta:
                        best_i = i
                        best_delta = delta
            if best_i is None:
                return None
            i = best_i

        rdom = r_domains[i]
        cdom = c_domains[j]
        bit_j = 1 << j
        bit_i = 1 << i
        rb = sum(1 for m in rdom if m & bit_j)
        cb = sum(1 for m in cdom if m & bit_i)
        black_support = rb * cb
        white_support = (len(rdom) - rb) * (len(cdom) - cb)
        order = [1, 0] if black_support <= white_support else [0, 1]
        return i, j, order

    failed = set()

    def search(r_domains, c_domains):
        r_domains = r_domains[:]
        c_domains = c_domains[:]

        propagated = propagate(r_domains, c_domains)
        if propagated is None:
            return None
        r_domains, c_domains = propagated

        key = (
            tuple(tuple(dom) for dom in r_domains),
            tuple(tuple(dom) for dom in c_domains),
        )
        if key in failed:
            return None

        if all(len(dom) == 1 for dom in r_domains):
            row_masks = [dom[0] for dom in r_domains]
            if validate(row_masks):
                return row_masks
            failed.add(key)
            return None

        choice = choose_cell(r_domains, c_domains)
        if choice is None:
            failed.add(key)
            return None

        i, j, order = choice
        bit_j = 1 << j
        bit_i = 1 << i

        for value in order:
            new_r = r_domains[:]
            new_c = c_domains[:]

            if value == 1:
                row_filtered = [m for m in new_r[i] if m & bit_j]
                col_filtered = [m for m in new_c[j] if m & bit_i]
            else:
                row_filtered = [m for m in new_r[i] if not (m & bit_j)]
                col_filtered = [m for m in new_c[j] if not (m & bit_i)]

            if not row_filtered or not col_filtered:
                continue

            new_r[i] = row_filtered
            new_c[j] = col_filtered

            ans = search(new_r, new_c)
            if ans is not None:
                return ans

        failed.add(key)
        return None

    solution = search(row_domains, col_domains)
    if solution is None:
        return "No Solution"

    grid = [
        ["B" if (solution[i] >> j) & 1 else None for j in range(n_cols)]
        for i in range(n_rows)
    ]
    return repr(grid)


