                black_support = rb * cb
                white_support = (lr - rb) * (lc - cb)

                score = (
                    max(black_support, white_support),
                    black_support + white_support,
                    abs(black_support - white_support),
                    lr + lc,
                )
                order = [1, 0] if black_support <= white_support else [0, 1]

