                if 0 < cnt < len(dom):
                    delta = abs(len(dom) - 2 * cnt)
                    if best_j is None or delta < best_delta:
                        best_j = j
                        best_delta = delta
            if best_j is None:
                return None
            j = best_j
        else:
            j = idx
            dom = c_domains[j]
            best_i = None
            best_delta = None
            for i in range(n_rows):
                cnt = sum(1 for m in dom if (m >> i) & 1)
                if 0 < cnt < len(dom):
                    delta = abs(len(dom) - 2 * cnt)
                    if best_i is None or delta < best_delta:
                        best_i = i
                        best_delta = delta
            if best_i is None:
                return None
            i = best_i

        rdom = r_domains[i]
        cdom = c_domains[j]
        bit_j = 1 << j
        bit_i = 1 << i
        rb = sum(1 for m in rdom if m & bit_j)
        cb = sum(1 for m in cdom if m & bit_i)
        black_support = rb * cb
        white_support = (len(rdom) - rb) * (len(cdom) - cb)
        order = [1, 0] if black_support <= white_support else [0, 1]
