from functools import lru_cache


# Generate all bitmasks over weights 1..length whose weighted sum equals target.
# Bit i corresponds to using weight (i + 1).
@lru_cache(None)
def masks_for_target(length, target):
    total = length * (length + 1) // 2
    if target < 0 or target > total:
        return ()

    @lru_cache(None)
    def can_make(next_weight, remain):
        if remain == 0:
            return True
        if next_weight > length or remain < 0:
            return False
        max_sum = (next_weight + length) * (length - next_weight + 1) // 2
        if remain > max_sum:
            return False
        return can_make(next_weight + 1, remain) or can_make(next_weight + 1, remain - next_weight)

    result = []

    def gen(next_weight, remain, mask):
        if remain == 0:
            result.append(mask)
            return
        if next_weight > length or remain < 0:
            return
        max_sum = (next_weight + length) * (length - next_weight + 1) // 2
        if remain > max_sum:
            return
        if can_make(next_weight + 1, remain):
            gen(next_weight + 1, remain, mask)
        if can_make(next_weight + 1, remain - next_weight):
            gen(next_weight + 1, remain - next_weight, mask | (1 << (next_weight - 1)))

    gen(1, target, 0)
    return tuple(result)


