        allow1_cols_for_row = [0] * m
        allow0_cols_for_row = [0] * m
        for c, domain in enumerate(col_domains):
            if not domain:
                return None
            any_one = 0
            all_one = full_row_mask
            for mask in domain:
                any_one |= mask
                all_one &= mask
            can1 = any_one
            can0 = full_row_mask ^ all_one
            cbit = 1 << c
            for r in range(m):
                rbit = 1 << r
                if can1 & rbit:
                    allow1_cols_for_row[r] |= cbit
                if can0 & rbit:
                    allow0_cols_for_row[r] |= cbit

        # Filter row candidates by current column supports.
        for r, domain in enumerate(row_domains):
            a1 = allow1_cols_for_row[r]
            a0 = allow0_cols_for_row[r]
