def ordered_row_candidates(r, domain, col_domains):
    support1 = []
    for c_domain in col_domains:
        count1 = 0
        for mask in c_domain:
            count1 += (mask >> r) & 1
        support1.append(count1)

    ordered = []
    for mask in domain:
        score = 0
        for c, c_domain in enumerate(col_domains):
            if (mask >> c) & 1:
                score += support1[c]
            else:
                score += len(c_domain) - support1[c]
        ordered.append((score, mask.bit_count(), mask))
