    total = 0
    while mask:
        lsb = mask & -mask
        total += lsb.bit_length()
        mask ^= lsb
    return total


def verify_solution(row_masks, row_sum, col_sum):
    m = len(row_sum)
    n = len(col_sum)

    for r in range(m):
        if weighted_mask_sum(row_masks[r]) != row_sum[r]:
            return False

    for c in range(n):
        total = 0
        for r in range(m):
            if (row_masks[r] >> c) & 1:
                total += r + 1
        if total != col_sum[c]:
            return False

    return True


def build_answer(row_masks, cols):
    return [[('B' if (row_masks[r] >> c) & 1 else None) for c in range(cols)] for r in range(len(row_masks))]


def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    m = len(row_sum)
    n = len(col_sum)

    max_row_target = n * (n + 1) // 2
    max_col_target = m * (m + 1) // 2

    if any(t < 0 or t > max_row_target for t in row_sum):
        return "No Solution"
    if any(t < 0 or t > max_col_target for t in col_sum):
        return "No Solution"

    # Necessary weighted consistency:
    # sum(row_weight * row_target) == sum(col_weight * col_target)
    left = sum((r + 1) * row_sum[r] for r in range(m))
    right = sum((c + 1) * col_sum[c] for c in range(n))
    if left != right:
        return "No Solution"

    row_domains = [list(masks_for_target(n, target)) for target in row_sum]
    col_domains = [list(masks_for_target(m, target)) for target in col_sum]

    if any(not d for d in row_domains) or any(not d for d in col_domains):
        return "No Solution"

    memo = {}

    def search(r_domains, c_domains):
        state = propagate([d[:] for d in r_domains], [d[:] for d in c_domains])
        if state is None:
            return None

        r_domains, c_domains = state
        key = freeze_domains(r_domains, c_domains)
        if key in memo:
            return memo[key]

        if all(len(d) == 1 for d in r_domains):
            solution = tuple(d[0] for d in r_domains)
            memo[key] = solution
            return solution

        choice = choose_branch(r_domains, c_domains)
        if choice is None:
            memo[key] = None
            return None

        kind, idx = choice

        if kind == "row":
            for mask in ordered_row_candidates(idx, r_domains[idx], c_domains):
                new_r = [d[:] for d in r_domains]
                new_c = [d[:] for d in c_domains]
                new_r[idx] = [mask]
                solution = search(new_r, new_c)
                if solution is not None:
                    memo[key] = solution
                    return solution
        else:
            for mask in ordered_col_candidates(idx, c_domains[idx], r_domains):
                new_r = [d[:] for d in r_domains]
                new_c = [d[:] for d in c_domains]
                new_c[idx] = [mask]
                solution = search(new_r, new_c)
                if solution is not None:
                    memo[key] = solution
                    return solution

        memo[key] = None
        return None

    solution = search(row_domains, col_domains)
    if solution is None:
        return "No Solution"
    if not verify_solution(solution, row_sum, col_sum):
        return "No Solution"

    return repr(build_answer(solution, n))


