    # selecting a set summing to target is equivalent to omitting a set
    # summing to total-target when that side is smaller.
    if target > total - target:
        comp = generate_patterns(weights, total - target)
        return tuple(full ^ m for m in comp)

    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]

