import sys

sys.setrecursionlimit(10000)


def generate_masks_by_sum(weights):
    # All subset masks grouped by weighted sum.
    res = {}
    n = len(weights)

    def dfs(i, total, mask):
        if i == n:
            res.setdefault(total, []).append(mask)
            return
        dfs(i + 1, total, mask)
        dfs(i + 1, total + weights[i], mask | (1 << i))

    dfs(0, 0, 0)
    return {k: tuple(v) for k, v in res.items()}


def solve(observation):
    row_sum = observation.get('row_sum')
    col_sum = observation.get('col_sum')
    if not isinstance(row_sum, list) or not isinstance(col_sum, list):
        return "No Solution"

    n = len(row_sum)
    m = len(col_sum)
    if n == 0 or m == 0:
        return "No Solution"

    # Default weights are the visible row/column indices: 1..n and 1..m.
    row_weights = observation.get('row_weights', list(range(1, n + 1)))
    col_weights = observation.get('col_weights', list(range(1, m + 1)))

    if len(row_weights) != n or len(col_weights) != m:
        return "No Solution"
    if any((not isinstance(x, int)) or x < 0 for x in row_sum + col_sum + row_weights + col_weights):
        return "No Solution"

    # Necessary global consistency:
    # sum_i row_weight[i] * row_target[i] == sum_j col_weight[j] * col_target[j]
    if sum(w * t for w, t in zip(row_weights, row_sum)) != sum(w * t for w, t in zip(col_weights, col_sum)):
        return "No Solution"

    row_patterns_by_sum = generate_masks_by_sum(col_weights)
    col_patterns_by_sum = generate_masks_by_sum(row_weights)

    row_domains = []
    for t in row_sum:
        dom = row_patterns_by_sum.get(t, ())
        if not dom:
