    col_domains = tuple(col_domains)

    full_row_mask = (1 << m) - 1
    full_col_mask = (1 << n) - 1

    def compute_must_may(domains, full_mask):
        must = []
        may = []
        for dom in domains:
            if not dom:
                return None, None
            a = full_mask
            o = 0
            for mask in dom:
                a &= mask
                o |= mask
            must.append(a)
            may.append(o)
        return must, may

    def propagate(r_domains, c_domains):
        # Human-style closure:
        # 1) Common bits in a line's candidates are forced black.
        # 2) Missing bits from all candidates are forced white.
        # 3) Those forced cell states remove opposite-line candidates.
        r_domains = list(r_domains)
