                    if not (row_may[i] & bit_j):
                        req0 |= 1 << i
                if req1 & req0:
                    return None
                if req1 or req0:
                    nd = tuple(mask for mask in dom if (mask & req1) == req1 and (mask & req0) == 0)
                    if not nd:
                        return None
                    if len(nd) != len(dom):
                        c_domains[j] = nd
                        changed = True

            if not changed:
                return tuple(r_domains), tuple(c_domains)

    def choose_branch(r_domains, c_domains):
