        col_must, col_may = compute_must_may(c_domains, full_col_mask)

        best = None
        best_key = None

        for i, dom in enumerate(r_domains):
            if len(dom) > 1:
                spread = (row_may[i] ^ row_must[i]).bit_count()
                key = (len(dom), -spread, 0, i)
                if best_key is None or key < best_key:
