            cdom = c_domains[j]
            cnt1 = 0
            for cmask in cdom:
                if cmask & bit_i:
                    cnt1 += 1
            support1[j] = cnt1
            support0[j] = len(cdom) - cnt1

        def score(mask):
            total = 0
            for j in range(m):
                total += support1[j] if (mask >> j) & 1 else support0[j]
            return -total

        return tuple(sorted(dom, key=score))

    def ordered_col_candidates(j, dom, r_domains):
        # Prefer masks best supported by current row domains.
        bit_j = 1 << j
        support1 = [0] * n
        support0 = [0] * n
        for i in range(n):
