            support1[i] = cnt1
            support0[i] = len(rdom) - cnt1

        def score(mask):
            total = 0
            for i in range(n):
                total += support1[i] if (mask >> i) & 1 else support0[i]
            return -total

        return tuple(sorted(dom, key=score))

    def validate(row_masks):
