from functools import lru_cache


@lru_cache(maxsize=None)
def masks_for_sum(weights, target):
    # Enumerate all subset masks whose weighted sum equals target.
    # Uses descending-weight recursion with suffix pruning.
    weights = tuple(weights)
    target = int(target)
    n = len(weights)
    if target < 0:
        return ()
    total = sum(weights)
    if target > total:
        return ()

    order = sorted(range(n), key=lambda i: weights[i], reverse=True)
    ordered_weights = [weights[i] for i in order]

    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + ordered_weights[i]

    out = []

    def dfs(i, remain, mask):
        if remain == 0:
            out.append(mask)
            return
        if i == n or remain < 0 or remain > suffix[i]:
            return

        idx = order[i]
        w = ordered_weights[i]

        if w <= remain:
            dfs(i + 1, remain - w, mask | (1 << idx))
        if remain <= suffix[i + 1]:
            dfs(i + 1, remain, mask)

    dfs(0, target, 0)
    out.sort()
    return tuple(out)


def summarize_domains(domains, full_mask):
    any1 = [0] * len(domains)
    all1 = [full_mask] * len(domains)
    for i, dom in enumerate(domains):
        if not dom:
            return None
        a = 0
        b = full_mask
        for m in dom:
            a |= m
            b &= m
        any1[i] = a
        all1[i] = b
    return any1, all1


def propagate(row_domains, col_domains):
    # Human-style logic:
    # 1) Generate all legal row/column patterns.
    # 2) Force cells by intersections/unions of those patterns.
    # 3) Remove any pattern unsupported by the opposite direction.
    # Repeat until stable.
    r_count = len(row_domains)
    c_count = len(col_domains)
    row_full = (1 << c_count) - 1
    col_full = (1 << r_count) - 1

    while True:
        if any(not d for d in row_domains) or any(not d for d in col_domains):
            return None

        row_summary = summarize_domains(row_domains, row_full)
        col_summary = summarize_domains(col_domains, col_full)
        if row_summary is None or col_summary is None:
            return None
        row_any1, row_all1 = row_summary
        col_any1, col_all1 = col_summary

        changed = False

        new_rows = []
        for r, dom in enumerate(row_domains):
            r_bit = 1 << r
            filtered = []
            for mask in dom:
                ok = True
                for c in range(c_count):
                    bit = (mask >> c) & 1
                    if bit:
                        if not (col_any1[c] & r_bit):
                            ok = False
                            break
                    else:
                        if col_all1[c] & r_bit:
                            ok = False
                            break
                if ok:
                    filtered.append(mask)
            if not filtered:
                return None
            if len(filtered) != len(dom):
                changed = True
            new_rows.append(tuple(filtered))
        row_domains = new_rows

        if changed:
            continue

        # Row summaries are still valid because rows did not change in this pass.
        new_cols = []
        for c, dom in enumerate(col_domains):
            c_bit = 1 << c
            filtered = []
            for mask in dom:
                ok = True
                for r in range(r_count):
                    bit = (mask >> r) & 1
                    if bit:
                        if not (row_any1[r] & c_bit):
                            ok = False
                            break
                    else:
                        if row_all1[r] & c_bit:
                            ok = False
                            break
                if ok:
                    filtered.append(mask)
            if not filtered:
                return None
            if len(filtered) != len(dom):
                changed = True
            new_cols.append(tuple(filtered))
        col_domains = new_cols

        if not changed:
            return row_domains, col_domains


def normalize_fixed_value(v):
    if v in (1, True, 'B', 'b', '#', 'X', 'x'):
        return 1
    if v in (0, False, 'W', 'w', '.', '-'):
        return 0
    return None


def parse_fixed_cells(observation, r_count, c_count):
    fixed = {}

    for key in ("fixed_black", "black"):
        for cell in observation.get(key, ()):
            if isinstance(cell, (tuple, list)) and len(cell) == 2:
                r, c = int(cell[0]), int(cell[1])
                if 0 <= r < r_count and 0 <= c < c_count:
                    fixed[(r, c)] = 1

    for key in ("fixed_white", "white"):
        for cell in observation.get(key, ()):
            if isinstance(cell, (tuple, list)) and len(cell) == 2:
                r, c = int(cell[0]), int(cell[1])
                if 0 <= r < r_count and 0 <= c < c_count:
                    fixed[(r, c)] = 0

    raw_fixed = observation.get("fixed")
    if raw_fixed:
        if isinstance(raw_fixed, dict):
            iterable = raw_fixed.items()
            for pos, val in iterable:
                if isinstance(pos, (tuple, list)) and len(pos) == 2:
                    r, c = int(pos[0]), int(pos[1])
                    bit = normalize_fixed_value(val)
                    if bit is not None and 0 <= r < r_count and 0 <= c < c_count:
                        fixed[(r, c)] = bit
        else:
            for item in raw_fixed:
                if isinstance(item, (tuple, list)) and len(item) == 3:
                    r, c, val = item
                    r, c = int(r), int(c)
                    bit = normalize_fixed_value(val)
                    if bit is not None and 0 <= r < r_count and 0 <= c < c_count:
                        fixed[(r, c)] = bit

    preset = observation.get("preset")
    if preset is not None:
        for r, row in enumerate(preset):
            if r >= r_count:
                break
            for c, val in enumerate(row):
                if c >= c_count:
                    break
                bit = normalize_fixed_value(val)
                if bit is not None:
                    fixed[(r, c)] = bit

    return fixed


def order_row_masks(r, row_domains, col_domains):
    c_count = len(col_domains)
    scored = []
    for mask in row_domains[r]:
        score = 0
        for c in range(c_count):
            bit = (mask >> c) & 1
            cnt = 0
            for col_mask in col_domains[c]:
                if ((col_mask >> r) & 1) == bit:
                    cnt += 1
            score += cnt
        scored.append((score, mask))
    scored.sort()
    return tuple(mask for _, mask in scored)


def order_col_masks(c, row_domains, col_domains):
    r_count = len(row_domains)
    scored = []
    for mask in col_domains[c]:
        score = 0
        for r in range(r_count):
            bit = (mask >> r) & 1
            cnt = 0
            for row_mask in row_domains[r]:
                if ((row_mask >> c) & 1) == bit:
                    cnt += 1
            score += cnt
        scored.append((score, mask))
    scored.sort()
    return tuple(mask for _, mask in scored)


def choose_branch(row_domains, col_domains):
    r_count = len(row_domains)
    c_count = len(col_domains)

    # If a row/column already has very few legal patterns, branch on the whole line.
    best_axis = None
    best_idx = -1
    best_size = 10 ** 9

    for r, dom in enumerate(row_domains):
        n = len(dom)
        if 1 < n < best_size:
            best_size = n
            best_axis = "row"
            best_idx = r

    for c, dom in enumerate(col_domains):
        n = len(dom)
        if 1 < n < best_size:
            best_size = n
            best_axis = "col"
            best_idx = c

    if best_axis is not None and best_size <= 4:
        if best_axis == "row":
            return ("line", "row", best_idx, order_row_masks(best_idx, row_domains, col_domains))
        return ("line", "col", best_idx, order_col_masks(best_idx, row_domains, col_domains))

    # Otherwise branch on the most constrained unresolved cell (binary split).
    row_one_counts = [[0] * c_count for _ in range(r_count)]
    for r, dom in enumerate(row_domains):
        counts = row_one_counts[r]
        for mask in dom:
            x = mask
            while x:
                lsb = x & -x
                counts[lsb.bit_length() - 1] += 1
                x ^= lsb

    col_one_counts = [[0] * r_count for _ in range(c_count)]
    for c, dom in enumerate(col_domains):
        counts = col_one_counts[c]
        for mask in dom:
            x = mask
            while x:
                lsb = x & -x
                counts[lsb.bit_length() - 1] += 1
                x ^= lsb

    best_cell = None
    for r in range(r_count):
        row_len = len(row_domains[r])
        for c in range(c_count):
            a1 = row_one_counts[r][c]
            a0 = row_len - a1
            if a0 == 0 or a1 == 0:
                continue

            col_len = len(col_domains[c])
            b1 = col_one_counts[c][r]
            b0 = col_len - b1
            if b0 == 0 or b1 == 0:
                continue

            support0 = a0 * b0
            support1 = a1 * b1

            # Prefer cells where one branch is tiny and the other is still constrained.
            score = (
                min(support0, support1),
                max(support0, support1),
                row_len + col_len,
                abs(a1 - a0) + abs(b1 - b0),
                r,
                c,
            )
            if best_cell is None or score < best_cell[0]:
                values = (0, 1) if support0 <= support1 else (1, 0)
                best_cell = (score, r, c, values)

    if best_cell is not None:
        return ("cell", best_cell[1], best_cell[2], best_cell[3])

    if best_axis is not None:
        if best_axis == "row":
            return ("line", "row", best_idx, order_row_masks(best_idx, row_domains, col_domains))
        return ("line", "col", best_idx, order_col_masks(best_idx, row_domains, col_domains))

    return None


def verify_solution(row_masks, row_weight, col_weight, row_sum, col_sum):
    r_count = len(row_masks)
    c_count = len(col_weight)

    for r in range(r_count):
        total = 0
        mask = row_masks[r]
        for c in range(c_count):
