    any1 = [0] * len(domains)
    all1 = [full_mask] * len(domains)
    for i, dom in enumerate(domains):
        if not dom:
            return None
        a = 0
        b = full_mask
        for m in dom:
            a |= m
            b &= m
        any1[i] = a
        all1[i] = b
    return any1, all1


