from collections import deque
import sys

sys.setrecursionlimit(1000000)


class KuromasuSolver:
    UNKNOWN = -1
    WHITE = 0
    BLACK = 1

    def __init__(self, data):
        self.data = data
        self.N = len(data)
        self.M = self.N * self.N
        self.clue_ids = []
        self.clue_values = {}
        self.valid = True

        for r, row in enumerate(data):
            if len(row) != self.N:
                self.valid = False
                return
            for c, v in enumerate(row):
                if v is not None:
                    idx = self.to_idx(r, c)
                    self.clue_ids.append(idx)
                    self.clue_values[idx] = v

        self.clue_set = set(self.clue_ids)
        self.num_clues = len(self.clue_ids)

        self.neighbors = [[] for _ in range(self.M)]
        for r in range(self.N):
            for c in range(self.N):
                idx = self.to_idx(r, c)
                if r > 0:
                    self.neighbors[idx].append(self.to_idx(r - 1, c))
                if r + 1 < self.N:
                    self.neighbors[idx].append(self.to_idx(r + 1, c))
                if c > 0:
                    self.neighbors[idx].append(self.to_idx(r, c - 1))
                if c + 1 < self.N:
                    self.neighbors[idx].append(self.to_idx(r, c + 1))

        self.clue_rays = []
        self.clue_targets = []
        for idx in self.clue_ids:
            r, c = self.to_rc(idx)
            rays = []

            up = []
            rr = r - 1
            while rr >= 0:
                up.append(self.to_idx(rr, c))
                rr -= 1
            rays.append(up)

            down = []
            rr = r + 1
            while rr < self.N:
                down.append(self.to_idx(rr, c))
                rr += 1
            rays.append(down)

            left = []
            cc = c - 1
            while cc >= 0:
                left.append(self.to_idx(r, cc))
                cc -= 1
            rays.append(left)

            right = []
            cc = c + 1
            while cc < self.N:
                right.append(self.to_idx(r, cc))
                cc += 1
            rays.append(right)

            self.clue_rays.append(rays)
            max_vis = 1 + sum(len(ray) for ray in rays)
            v = self.clue_values[idx]
            self.clue_targets.append(v - 1)
            if not isinstance(v, int) or v < 1 or v > max_vis:
                self.valid = False

        self.cell_impact = [0] * self.M
        for cid, rays in enumerate(self.clue_rays):
            for ray in rays:
                for idx in ray:
                    self.cell_impact[idx] += 2
        for idx in range(self.M):
            self.cell_impact[idx] += len(self.neighbors[idx])

        self.dead = set()

        # Small enough to use stronger reasoning late in the solve.
        self.hypothesis_threshold = 24
        self.connectivity_threshold = 40
        self.clue_branch_threshold = 8

    def to_idx(self, r, c):
        return r * self.N + c

    def to_rc(self, idx):
        return divmod(idx, self.N)

    def can_be_black_now(self, state, idx):
        if idx in self.clue_set:
            return False
        if state[idx] == self.WHITE:
            return False
        for nb in self.neighbors[idx]:
            if state[nb] == self.BLACK:
                return False
        return True

    def assign(self, state, idx, color, queue):
        cur = state[idx]
        if cur != self.UNKNOWN:
            return cur == color

        if color == self.BLACK:
            if idx in self.clue_set:
                return False
            for nb in self.neighbors[idx]:
