        if color == self.BLACK:
            for nb in self.neighbors[idx]:
                if state[nb] == self.UNKNOWN:
                    queue.append((nb, self.WHITE))
        return True

    def process_queue(self, state, queue):
        while queue:
            idx, color = queue.popleft()
            if not self.assign(state, idx, color, queue):
                return False
        return True

    def clue_tuples(self, state, cid):
        target = self.clue_targets[cid]
        rays = self.clue_rays[cid]

        allowed = []
        maxlens = []

        for ray in rays:
            maxlen = 0
            while maxlen < len(ray) and state[ray[maxlen]] != self.BLACK:
                maxlen += 1
            maxlens.append(maxlen)

            minlen = 0
            while minlen < maxlen and state[ray[minlen]] == self.WHITE:
                minlen += 1

            choices = []
            for x in range(minlen, maxlen + 1):
                if x < maxlen:
                    stopper = ray[x]
                    if not self.can_be_black_now(state, stopper):
                        continue
                choices.append(x)

            if not choices:
                return [], maxlens
            allowed.append(choices)

        A, B, C, D = allowed
        dset = set(D)

        tuples = []
        minB, maxB = B[0], B[-1]
        minC, maxC = C[0], C[-1]
        minD, maxD = D[0], D[-1]

        for a in A:
            rem1 = target - a
            if rem1 < minB + minC + minD or rem1 > maxB + maxC + maxD:
                continue
            for b in B:
                rem2 = rem1 - b
                if rem2 < minC + minD or rem2 > maxC + maxD:
                    continue
                for c in C:
                    d = rem2 - c
                    if d in dset:
                        tuples.append((a, b, c, d))

        return tuples, maxlens

    def reachable_white_component(self, state):
        allowed = [i for i, v in enumerate(state) if v != self.BLACK]
        if not allowed:
            return set()

        whites = [i for i, v in enumerate(state) if v == self.WHITE]
        root = whites[0] if whites else allowed[0]

        seen = {root}
        dq = deque([root])

        while dq:
            v = dq.popleft()
            for nb in self.neighbors[v]:
                if state[nb] != self.BLACK and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)

        for w in whites:
            if w not in seen:
                return None
        return seen

    def connectivity_forced_whites(self, state, main_component):
        whites = [i for i, v in enumerate(state) if v == self.WHITE]
        if len(whites) <= 1:
            return []

        unknowns = [i for i in main_component if state[i] == self.UNKNOWN]
        if len(unknowns) > self.connectivity_threshold:
            return []

        main_component = set(main_component)
        root = whites[0]
        forced = []

        for x in unknowns:
