                    deg += 1
            if deg < 2:
                continue

            seen = {root}
            dq = deque([root])

            while dq:
                v = dq.popleft()
                for nb in self.neighbors[v]:
                    if nb == x:
                        continue
                    if state[nb] == self.BLACK or nb in seen:
                        continue
                    seen.add(nb)
                    dq.append(nb)

            ok = True
            for w in whites[1:]:
                if w not in seen:
                    ok = False
                    break
            if not ok:
                forced.append(x)

        return forced

    def propagate(self, state, use_hypothesis=True):
