                continue
            white_n = sum(1 for nb in self.neighbors[idx] if state[nb] == self.WHITE)
            unknown_n = sum(1 for nb in self.neighbors[idx] if state[nb] == self.UNKNOWN)
            score = (self.cell_impact[idx], white_n, unknown_n)
            if best_score is None or score > best_score:
