            count = 1
            for ray in self.clue_rays[cid]:
                for cell in ray:
                    if state[cell] == self.BLACK:
                        break
                    count += 1
            if count != self.clue_values[clue_idx]:
                return False

        return True

    def search(self, state):
        state, clue_info = self.propagate(state, use_hypothesis=True)
        if state is None:
            return None

        key = tuple(state)
        if key in self.dead:
            return None

        if self.is_solved(state):
            return state

        best_branching = None
        best_score = None

        for cid, (tuples, maxlens) in clue_info.items():
            if len(tuples) <= 1:
                continue

            sig_to_tuple = {}
            for tup in tuples:
                sig = self.tuple_signature(state, cid, tup, maxlens)
                if sig not in sig_to_tuple:
                    sig_to_tuple[sig] = tup

            effective = list(sig_to_tuple.items())
            if len(effective) <= 1:
                continue

            max_effect = max(len(sig) for sig, _ in effective)
            score = (len(effective), len(tuples), -max_effect)
            if best_score is None or score < best_score:
                best_score = score
                best_branching = (cid, maxlens, effective)

        if best_branching is not None and len(best_branching[2]) <= self.clue_branch_threshold:
            cid, maxlens, effective = best_branching
            ordered = sorted(
                effective,
                key=lambda item: (-len(item[0]), -sum(item[1]), item[1]),
            )
            for _, tup in ordered:
                new_state = state.copy()
                q = deque()
                if not self.apply_tuple(new_state, cid, tup, q, maxlens):
                    continue
                if not self.process_queue(new_state, q):
                    continue
                res = self.search(new_state)
                if res is not None:
                    return res
            self.dead.add(key)
            return None

        idx = self.choose_cell(state)
        if idx is None:
            self.dead.add(key)
            return None

        for color in self.order_cell_branches(state, idx):
            new_state = state.copy()
            q = deque()
            if not self.assign(new_state, idx, color, q):
                continue
            if not self.process_queue(new_state, q):
                continue
            res = self.search(new_state)
            if res is not None:
                return res

        self.dead.add(key)
        return None

    def format_solution(self, state):
        out = []
        for r in range(self.N):
            row = []
            for c in range(self.N):
                idx = self.to_idx(r, c)
                if idx in self.clue_set:
                    row.append(self.clue_values[idx])
                elif state[idx] == self.BLACK:
                    row.append('B')
                else:
                    row.append(None)
            out.append(row)
        return out

    def run(self):
        if not self.valid:
            return None

        state = [self.UNKNOWN] * self.M
        q = deque()

        for idx in self.clue_ids:
            if not self.assign(state, idx, self.WHITE, q):
                return None
        if not self.process_queue(state, q):
            return None

        return self.search(state)


def solve(observation):
    solver = KuromasuSolver(observation['data'])
    result = solver.run()
    if result is None:
        return "No Solution"
    return str(solver.format_solution(result))


