                    b = opt[2]
                    if b != -1:
                        combo_status[b] = 4  # black
                for cell, st in combo_status.items():
                    masks[cell] |= st
                return

            rem = need - cur_sum
            for opt in dir_opts[d]:
                if opt[0] > rem:
                    continue
                chosen[d] = opt
                rec(d + 1, cur_sum + opt[0])

        rec(0, 0)
        return total, masks

    def prioritized_unknowns(self, state):
        center = (self.n - 1) / 2.0
        ranked = []
        for idx, v in enumerate(state):
            if v != self.UNKNOWN:
                continue
            influence = len(self.cell_to_clues[idx])
            decided_neighbors = sum(1 for nb in self.nei[idx] if state[nb] != self.UNKNOWN)
            clue_neighbors = sum(1 for nb in self.nei[idx] if self.is_clue[nb])
            r, c = self.rc(idx)
            dist = abs(r - center) + abs(c - center)
            score = (influence, decided_neighbors, clue_neighbors, -dist)
            ranked.append((score, idx))
        ranked.sort(reverse=True)
        return [idx for _, idx in ranked]

    def trial_order(self, state, idx):
        trials = []
        for color in (self.BLACK, self.WHITE):
            if color == self.BLACK and not self.can_be_black_now(state, idx):
                continue
            s2 = state[:]
            if not self.assign(s2, idx, color):
                continue
            if not self.propagate(s2, allow_probe=False):
                continue
            trials.append((s2.count(self.UNKNOWN), color, s2))
        trials.sort(key=lambda x: (x[0], 0 if x[1] == self.BLACK else 1))
        return trials

    def find_forced_by_probing(self, state):
        unknowns = self.prioritized_unknowns(state)
        if not unknowns:
            return []
        probe_limit = len(unknowns) if len(unknowns) <= 20 else 20

        for idx in unknowns[:probe_limit]:
            trials = self.trial_order(state, idx)
            if not trials:
                return False
            if len(trials) == 1:
                return [(idx, trials[0][1])]

            s_a = trials[0][2]
            s_b = trials[1][2]
            common = []
            for j, cur in enumerate(state):
                if cur != self.UNKNOWN:
                    continue
                if s_a[j] == s_b[j] and s_a[j] != self.UNKNOWN:
                    common.append((j, s_a[j]))
            if common:
                return common

        return []

    def propagate(self, state, allow_probe=True):
        while True:
            progress = False

            # Clues are always white.
            for idx, _ in self.clues:
                if state[idx] == self.BLACK:
                    return False
                if state[idx] == self.UNKNOWN:
                    state[idx] = self.WHITE
                    progress = True

            # No adjacent black cells; neighbors of a black are forced white.
            for idx, v in enumerate(state):
                if v != self.BLACK:
                    continue
                if self.is_clue[idx]:
                    return False
                for nb in self.nei[idx]:
                    if state[nb] == self.BLACK:
                        return False
                    if state[nb] == self.UNKNOWN:
                        state[nb] = self.WHITE
                        progress = True

            # Clue visibility deductions via feasible ray-length combinations.
            for clue_idx, target in self.clues:
                total, masks = self.clue_masks(state, clue_idx, target)
                if total == 0:
                    return False
                for cell, mask in masks.items():
                    if mask == 2 and state[cell] == self.UNKNOWN:
                        if not self.assign(state, cell, self.WHITE):
                            return False
                        progress = True
                    elif mask == 4 and state[cell] == self.UNKNOWN:
                        if not self.assign(state, cell, self.BLACK):
                            return False
                        progress = True
                    elif mask == 2 and state[cell] == self.BLACK:
                        return False
                    elif mask == 4 and state[cell] == self.WHITE:
                        return False

            # Current white cells must still be connectable through non-black cells.
            if not self.white_component_possible(state):
                return False

            if progress:
                continue

            if allow_probe:
                forced = self.find_forced_by_probing(state)
                if forced is False:
                    return False
                if forced:
                    for idx, color in forced:
                        if not self.assign(state, idx, color):
                            return False
                    continue

            return True

    def choose_branch(self, state):
        unknowns = self.prioritized_unknowns(state)
        if not unknowns:
            return None, []

        best_idx = None
        best_vals = None
        best_key = None

        for idx in unknowns[:6]:
            trials = self.trial_order(state, idx)
            if not trials:
                return idx, []
            key = (len(trials), sum(t[0] for t in trials))
            vals = [t[1] for t in trials]
            if best_key is None or key < best_key:
                best_key = key
                best_idx = idx
                best_vals = vals
                if len(trials) == 1:
                    break

        if best_idx is None:
            best_idx = unknowns[0]
            best_vals = [self.BLACK, self.WHITE]
        return best_idx, best_vals

    def verify(self, state):
        if any(v == self.UNKNOWN for v in state):
            return False

        for idx, v in enumerate(state):
            if self.is_clue[idx] and v != self.WHITE:
                return False
            if v == self.BLACK:
                for nb in self.nei[idx]:
                    if state[nb] == self.BLACK:
                        return False

        whites = [i for i, v in enumerate(state) if v == self.WHITE]
        if whites:
            seen = {whites[0]}
            q = deque([whites[0]])
            while q:
                cur = q.popleft()
                for nb in self.nei[cur]:
                    if state[nb] == self.WHITE and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
            if len(seen) != len(whites):
                return False

        for clue_idx, target in self.clues:
            count = 1
            for ray in self.clue_rays[clue_idx]:
                for cell in ray:
                    if state[cell] == self.BLACK:
                        break
                    count += 1
            if count != target:
                return False

        return True

    def search(self, state):
        if not self.propagate(state, allow_probe=True):
            return None

        key = tuple(state)
        if key in self.failed:
            return None

        if self.UNKNOWN not in state:
            if self.verify(state):
                return state
            self.failed.add(key)
            return None

        idx, values = self.choose_branch(state)
        if idx is None or not values:
            self.failed.add(key)
            return None

        for color in values:
            s2 = state[:]
            if not self.assign(s2, idx, color):
                continue
            ans = self.search(s2)
            if ans is not None:
                return ans

        self.failed.add(key)
        return None

    def render(self, state):
        out = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                idx = self.idx(r, c)
                if state[idx] == self.BLACK:
                    row.append('B')
                elif self.is_clue[idx]:
                    row.append(self.clue_value[idx])
                else:
                    row.append(None)
            out.append(row)
        return out


def solve(observation):
        try:
            data = observation['data']
            solver = KuromasuSolver(data)
            sys.setrecursionlimit(10000)
            result = solver.search(solver.initial_state())
            if result is None:
                return "No Solution"
            return repr(solver.render(result))
        except Exception:
            return "No Solution"


