# Kuromasu solver:
# - Numbered cells are white.
# - A clue equals the number of visible white cells orthogonally including itself.
# - Black cells do not touch orthogonally.
# - White cells form a single orthogonally connected group.
#
# The solver is generalized:
# - Each clue is compiled into all feasible "visibility patterns" (ray lengths + stopper blacks).
# - Propagation repeatedly:
#   * filters clue patterns against current white/black assignments
#   * applies forced white/black cells from clue-domain intersections
#   * enforces black non-touching
#   * enforces white-connectivity implications
#   * uses contradiction probing when stalled
# - Search branches on the most constrained clue / best discriminating cell.

import sys

sys.setrecursionlimit(10000)


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n
    all_mask = (1 << m) - 1

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    # Precompute adjacency masks.
    adj = [0] * m
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            mask = 0
            if r > 0:
                mask |= 1 << idx(r - 1, c)
            if r + 1 < n:
                mask |= 1 << idx(r + 1, c)
            if c > 0:
                mask |= 1 << idx(r, c - 1)
            if c + 1 < n:
                mask |= 1 << idx(r, c + 1)
            adj[i] = mask

    # Collect clues.
    is_clue = [False] * m
    clue_mask = 0
    clues = []
    clue_at = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                i = idx(r, c)
                is_clue[i] = True
                clue_mask |= 1 << i
                clue_at[i] = len(clues)
                clues.append({"cell": i, "value": v, "pos": (r, c)})

    # Rays for each clue.
    for clue in clues:
        r, c = clue["pos"]
        dirs = []

        ray = []
        rr = r - 1
        while rr >= 0:
            ray.append(idx(rr, c))
            rr -= 1
        dirs.append(ray)

        ray = []
        rr = r + 1
        while rr < n:
            ray.append(idx(rr, c))
            rr += 1
        dirs.append(ray)

        ray = []
        cc = c - 1
        while cc >= 0:
            ray.append(idx(r, cc))
            cc -= 1
        dirs.append(ray)

        ray = []
        cc = c + 1
        while cc < n:
            ray.append(idx(r, cc))
            cc += 1
        dirs.append(ray)

        clue["dirs"] = dirs

    # Cell influence score: how many clue-rays include the cell.
    cell_score = [0] * m
    for clue in clues:
        i = clue["cell"]
        cell_score[i] += 1000  # clues are fixed white and heavily relevant
        for ray in clue["dirs"]:
            for j in ray:
                cell_score[j] += 1

    # Generate all clue patterns.
    # Pattern: a pair (white_mask, black_mask)
    #   white_mask = visible cells forced white by this clue
    #   black_mask = stopper cells forced black by this clue
    patterns = []
    pattern_sizes = []

    for clue in clues:
        cell = clue["cell"]
        value = clue["value"]
        dirs = clue["dirs"]
        caps = [len(ray) for ray in dirs]
        target = value - 1
        clue_bit = 1 << cell
        out = []

        # Impossible clue early check.
        if target < 0 or target > sum(caps):
            return "No Solution"

        suffix_caps = [0] * 5
        for k in range(3, -1, -1):
            suffix_caps[k] = suffix_caps[k + 1] + caps[k]

        lens = [0, 0, 0, 0]

        def rec(k, rem):
            if k == 4:
                if rem != 0:
                    return
                wmask = clue_bit
                bmask = 0
                for ray, ln in zip(dirs, lens):
                    for t in range(ln):
                        wmask |= 1 << ray[t]
                    if ln < len(ray):
                        stopper = ray[ln]
                        if is_clue[stopper]:
                            return
                        bmask |= 1 << stopper
                out.append((wmask, bmask))
                return

            lo = max(0, rem - suffix_caps[k + 1])
            hi = min(caps[k], rem)
            for ln in range(lo, hi + 1):
                lens[k] = ln
                # Static invalid stop-before-clue pruning.
                if ln < caps[k]:
                    stopper = dirs[k][ln]
                    if is_clue[stopper]:
                        continue
                rec(k + 1, rem - ln)

        rec(0, target)

        if not out:
            return "No Solution"

        patterns.append(out)
        pattern_sizes.append([(w | b).bit_count() for (w, b) in out])

    pre = {
        "n": n,
        "m": m,
        "data": data,
        "all_mask": all_mask,
        "adj": adj,
        "is_clue": is_clue,
        "clue_mask": clue_mask,
        "clues": clues,
        "patterns": patterns,
        "pattern_sizes": pattern_sizes,
        "cell_score": cell_score,
    }

    def copy_state(state):
        return {
            "white": state["white"],
            "black": state["black"],
            "domains": [dom[:] for dom in state["domains"]],
        }

    def add_white(state, mask):
        if mask & state["black"]:
            return False
        state["white"] |= mask
        return True

    def add_black(state, mask):
        if mask & (state["white"] | pre["clue_mask"]):
            return False
        new = mask & ~state["black"]
        while new:
            bit = new & -new
            new ^= bit
            i = bit.bit_length() - 1
            if pre["adj"][i] & state["black"]:
                return False
            state["black"] |= bit
            if not add_white(state, pre["adj"][i]):
                return False
        return True

    def flood(start_bit, allowed_mask):
        seen = 0
        stack = [start_bit]
        while stack:
            bit = stack.pop()
            if seen & bit:
                continue
            seen |= bit
            i = bit.bit_length() - 1
            nbrs = pre["adj"][i] & allowed_mask & ~seen
            while nbrs:
                nb = nbrs & -nbrs
                nbrs ^= nb
                stack.append(nb)
        return seen

    def connectivity_forces(state):
        # Non-black cells are potential white cells.
        passable = pre["all_mask"] & ~state["black"]
        if passable == 0:
            # Only valid if there are no white cells at all.
            return None if state["white"] else False

        remaining = passable
        white_component = 0
        force_black_mask = 0

        while remaining:
            start = remaining & -remaining
            comp = flood(start, passable)
            remaining &= ~comp

            if comp & state["white"]:
                if white_component and comp != white_component:
                    return None
                white_component = comp
            else:
                # This component can never connect to the current white group.
                # Therefore every cell in it must be black.
                force_black_mask |= comp

        changed = False

        if force_black_mask:
            before_b = state["black"]
            if not add_black(state, force_black_mask):
                return None
            if state["black"] != before_b:
                changed = True

        # If there are white cells, all must stay connected through passable cells.
        if state["white"]:
            passable = pre["all_mask"] & ~state["black"]
            root = state["white"] & -state["white"]

            # Unknown articulation cells separating current white cells are forced white.
            candidates = (passable & ~state["white"])
            force_white_mask = 0
            while candidates:
                bit = candidates & -candidates
                candidates ^= bit
                reachable = flood(root, passable & ~bit)
                if (state["white"] & ~bit) & ~reachable:
                    force_white_mask |= bit

            if force_white_mask:
                before_w = state["white"]
                if not add_white(state, force_white_mask):
                    return None
                if state["white"] != before_w:
                    changed = True

        return changed

    def probe(state):
        # Contradiction probing on promising unknown cells.
        unknown = pre["all_mask"] & ~(state["white"] | state["black"])
        if not unknown:
            return False

        cells = []
        tmp = unknown
        while tmp:
            bit = tmp & -tmp
            tmp ^= bit
            i = bit.bit_length() - 1
            cells.append((pre["cell_score"][i], i))

        cells.sort(reverse=True)
        limit = len(cells) if len(cells) <= 18 else 18

        for _, i in cells[:limit]:
            bit = 1 << i

            # Try black.
            black_ok = True
            st = copy_state(state)
            if not add_black(st, bit) or not propagate(st, allow_probe=False):
                black_ok = False

            if not black_ok:
                before_w = state["white"]
                if not add_white(state, bit):
                    return None
                return state["white"] != before_w

            # Try white.
            white_ok = True
            st = copy_state(state)
            if not add_white(st, bit) or not propagate(st, allow_probe=False):
                white_ok = False

            if not white_ok:
                before_b = state["black"]
                if not add_black(state, bit):
                    return None
                return state["black"] != before_b

        return False

    def propagate(state, allow_probe=True):
        while True:
            changed = False

            if state["white"] & state["black"]:
                return False
            if state["black"] & pre["clue_mask"]:
                return False

            # Filter clue domains; collect intersection-forced cells.
            force_white_mask = 0
            force_black_mask = 0

            for ci, dom in enumerate(state["domains"]):
                pats = pre["patterns"][ci]
                new_dom = []
                inter_w = None
                inter_b = None

                for pi in dom:
                    wmask, bmask = pats[pi]
                    if (wmask & state["black"]) or (bmask & state["white"]):
                        continue
                    new_dom.append(pi)
                    if inter_w is None:
                        inter_w = wmask
                        inter_b = bmask
                    else:
                        inter_w &= wmask
                        inter_b &= bmask

                if not new_dom:
                    return False

                if new_dom != dom:
                    state["domains"][ci] = new_dom
                    changed = True

                force_white_mask |= inter_w
                force_black_mask |= inter_b

            # Apply clue-forced cells.
            new_w = force_white_mask & ~(state["white"] | state["black"])
            if new_w:
                before_w = state["white"]
                if not add_white(state, new_w):
                    return False
                if state["white"] != before_w:
                    changed = True

            new_b = force_black_mask & ~(state["white"] | state["black"])
            if new_b:
                before_b = state["black"]
                if not add_black(state, new_b):
                    return False
                if state["black"] != before_b:
                    changed = True

            # Connectivity implications.
            conn = connectivity_forces(state)
            if conn is None:
                return False
            if conn:
                changed = True

            if not changed:
                if allow_probe:
                    pr = probe(state)
                    if pr is None:
                        return False
                    if pr:
                        continue
                break

        return True

    def choose_discriminating_cell(state, clue_index):
        dom = state["domains"][clue_index]
        pats = pre["patterns"][clue_index]
        unknown = pre["all_mask"] & ~(state["white"] | state["black"])
        if not unknown:
            return None

        counts = {}
        dlen = len(dom)
        for pi in dom:
            wmask, bmask = pats[pi]

            tmp = wmask & unknown
            while tmp:
                bit = tmp & -tmp
                tmp ^= bit
                i = bit.bit_length() - 1
                pair = counts.get(i)
                if pair is None:
                    counts[i] = [1, 0]
                else:
                    pair[0] += 1

            tmp = bmask & unknown
            while tmp:
                bit = tmp & -tmp
                tmp ^= bit
                i = bit.bit_length() - 1
                pair = counts.get(i)
                if pair is None:
                    counts[i] = [0, 1]
                else:
                    pair[1] += 1

        best = None
        best_key = None
        for i, (cw, cb) in counts.items():
            surv_black = dlen - cw
            surv_white = dlen - cb
            both = 0 if (cw > 0 and cb > 0) else 1
            # Prefer cells that best split the constrained clue.
            key = (
                both,
                max(surv_black, surv_white),
                abs(surv_black - surv_white),
                -pre["cell_score"][i],
            )
            if best_key is None or key < best_key:
                best_key = key
                best = (i, surv_white, surv_black)

        if best is None:
            return None

        i, surv_white, surv_black = best
        if surv_black < surv_white:
            order = ("B", "W")
        else:
            order = ("W", "B")
        return i, order

    def choose_branch(state):
        unknown = pre["all_mask"] & ~(state["white"] | state["black"])

        # Most constrained clue first.
        best_ci = None
        best_len = 10**9
        for ci, dom in enumerate(state["domains"]):
            dl = len(dom)
            if 1 < dl < best_len:
                best_len = dl
                best_ci = ci

        if best_ci is not None:
            dom = state["domains"][best_ci]

            # Tiny domains: branch directly on the whole clue pattern.
            if len(dom) <= 3:
                order = dom[:]
                order.sort(
                    key=lambda pi: -(
                        ((pre["patterns"][best_ci][pi][0] | pre["patterns"][best_ci][pi][1]) & unknown).bit_count()
                    )
                )
                return ("pattern", best_ci, order)

            # Otherwise use a discriminating cell from that clue.
            choice = choose_discriminating_cell(state, best_ci)
            if choice is not None:
                i, order = choice
                return ("cell", i, order)

        # Fallback: best unknown cell by static relevance.
        best_i = None
        best_key = None
        tmp = unknown
        while tmp:
            bit = tmp & -tmp
            tmp ^= bit
            i = bit.bit_length() - 1
            key = (-pre["cell_score"][i], -((pre["adj"][i] & unknown).bit_count()))
            if best_key is None or key < best_key:
                best_key = key
                best_i = i

        if best_i is None:
            return None

        # Black is more constraining; try it first by default.
        return ("cell", best_i, ("B", "W"))

    def validate_solution(state):
        if (state["white"] | state["black"]) != pre["all_mask"]:
            return False
        if pre["clue_mask"] & ~state["white"]:
            return False

        # No orthogonally adjacent black cells.
        tmp = state["black"]
        while tmp:
            bit = tmp & -tmp
            tmp ^= bit
            i = bit.bit_length() - 1
            if pre["adj"][i] & state["black"]:
                return False

        # Clue values.
        for clue in pre["clues"]:
            total = 1
            for ray in clue["dirs"]:
                for j in ray:
                    if state["black"] & (1 << j):
                        break
                    total += 1
            if total != clue["value"]:
                return False

        # White connectivity.
        if state["white"]:
            root = state["white"] & -state["white"]
            reached = flood(root, state["white"])
            if reached != state["white"]:
                return False

        return True

    def render(state):
        out = []
        for r in range(n):
            row = []
            for c in range(n):
                i = idx(r, c)
                v = data[r][c]
                if v is not None:
                    row.append(v)
                elif state["black"] & (1 << i):
                    row.append("B")
                else:
                    row.append(None)
            out.append(row)
        return str(out)

    dead = set()

    def dfs(state):
        if not propagate(state, allow_probe=True):
            return None

        key = (state["white"], state["black"])
        if key in dead:
            return None

        if (state["white"] | state["black"]) == pre["all_mask"]:
            if validate_solution(state):
                return state
            dead.add(key)
            return None

        branch = choose_branch(state)
        if branch is None:
            dead.add(key)
            return None

        kind = branch[0]

        if kind == "pattern":
            _, ci, order = branch
            for pi in order:
                st = copy_state(state)
                st["domains"][ci] = [pi]
                wmask, bmask = pre["patterns"][ci][pi]
                if not add_white(st, wmask):
                    continue
                if not add_black(st, bmask):
                    continue
                res = dfs(st)
                if res is not None:
                    return res

        else:
            _, i, order = branch
            bit = 1 << i
            for value in order:
                st = copy_state(state)
                ok = add_black(st, bit) if value == "B" else add_white(st, bit)
                if not ok:
                    continue
                res = dfs(st)
                if res is not None:
