# Kuromasu solver:
# - Numbered cells are white.
# - A clue equals the number of visible white cells orthogonally including itself.
# - Black cells do not touch orthogonally.
# - White cells form a single orthogonally connected group.
#
# The solver is generalized:
# - Each clue is compiled into all feasible "visibility patterns" (ray lengths + stopper blacks).
# - Propagation repeatedly:
#   * filters clue patterns against current white/black assignments
#   * applies forced white/black cells from clue-domain intersections
#   * enforces black non-touching
#   * enforces white-connectivity implications
#   * uses contradiction probing when stalled
# - Search branches on the most constrained clue / best discriminating cell.

import sys

sys.setrecursionlimit(10000)


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = n * n
    all_mask = (1 << m) - 1

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    # Precompute adjacency masks.
    adj = [0] * m
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            mask = 0
            if r > 0:
                mask |= 1 << idx(r - 1, c)
            if r + 1 < n:
                mask |= 1 << idx(r + 1, c)
            if c > 0:
                mask |= 1 << idx(r, c - 1)
            if c + 1 < n:
                mask |= 1 << idx(r, c + 1)
            adj[i] = mask

    # Collect clues.
    is_clue = [False] * m
    clue_mask = 0
    clues = []
    clue_at = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                i = idx(r, c)
                is_clue[i] = True
                clue_mask |= 1 << i
                clue_at[i] = len(clues)
                clues.append({"cell": i, "value": v, "pos": (r, c)})

    # Rays for each clue.
    for clue in clues:
        r, c = clue["pos"]
        dirs = []

        ray = []
        rr = r - 1
        while rr >= 0:
            ray.append(idx(rr, c))
            rr -= 1
        dirs.append(ray)

        ray = []
        rr = r + 1
        while rr < n:
            ray.append(idx(rr, c))
            rr += 1
        dirs.append(ray)

        ray = []
        cc = c - 1
        while cc >= 0:
            ray.append(idx(r, cc))
            cc -= 1
        dirs.append(ray)

        ray = []
        cc = c + 1
        while cc < n:
            ray.append(idx(r, cc))
            cc += 1
        dirs.append(ray)

        clue["dirs"] = dirs

    # Cell influence score: how many clue-rays include the cell.
    cell_score = [0] * m
    for clue in clues:
        i = clue["cell"]
        cell_score[i] += 1000  # clues are fixed white and heavily relevant
        for ray in clue["dirs"]:
            for j in ray:
                cell_score[j] += 1

    # Generate all clue patterns.
    # Pattern: a pair (white_mask, black_mask)
    #   white_mask = visible cells forced white by this clue
    #   black_mask = stopper cells forced black by this clue
    patterns = []
    pattern_sizes = []

    for clue in clues:
        cell = clue["cell"]
        value = clue["value"]
        dirs = clue["dirs"]
        caps = [len(ray) for ray in dirs]
        target = value - 1
        clue_bit = 1 << cell
        out = []

        # Impossible clue early check.
        if target < 0 or target > sum(caps):
            return "No Solution"

        suffix_caps = [0] * 5
        for k in range(3, -1, -1):
            suffix_caps[k] = suffix_caps[k + 1] + caps[k]

        lens = [0, 0, 0, 0]

        def rec(k, rem):
            if k == 4:
                if rem != 0:
                    return
                wmask = clue_bit
                bmask = 0
                for ray, ln in zip(dirs, lens):
                    for t in range(ln):
                        wmask |= 1 << ray[t]
                    if ln < len(ray):
                        stopper = ray[ln]
                        if is_clue[stopper]:
                            return
                        bmask |= 1 << stopper
                out.append((wmask, bmask))
                return

            lo = max(0, rem - suffix_caps[k + 1])
            hi = min(caps[k], rem)
            for ln in range(lo, hi + 1):
                lens[k] = ln
                # Static invalid stop-before-clue pruning.
                if ln < caps[k]:
                    stopper = dirs[k][ln]
                    if is_clue[stopper]:
                        continue
                rec(k + 1, rem - ln)

        rec(0, target)

        if not out:
            return "No Solution"

        patterns.append(out)
        pattern_sizes.append([(w | b).bit_count() for (w, b) in out])

    pre = {
        "n": n,
        "m": m,
        "data": data,
        "all_mask": all_mask,
        "adj": adj,
        "is_clue": is_clue,
        "clue_mask": clue_mask,
        "clues": clues,
        "patterns": patterns,
        "pattern_sizes": pattern_sizes,
        "cell_score": cell_score,
    }

    def copy_state(state):
        return {
            "white": state["white"],
            "black": state["black"],
            "domains": [dom[:] for dom in state["domains"]],
        }

    def add_white(state, mask):
        if mask & state["black"]:
            return False
        state["white"] |= mask
        return True

    def add_black(state, mask):
