        new = mask & ~state["black"]
        while new:
            bit = new & -new
            new ^= bit
            i = bit.bit_length() - 1
            if pre["adj"][i] & state["black"]:
                return False
            state["black"] |= bit
            if not add_white(state, pre["adj"][i]):
                return False
        return True

    def flood(start_bit, allowed_mask):
        seen = 0
        stack = [start_bit]
        while stack:
            bit = stack.pop()
            if seen & bit:
                continue
            seen |= bit
            i = bit.bit_length() - 1
            nbrs = pre["adj"][i] & allowed_mask & ~seen
            while nbrs:
                nb = nbrs & -nbrs
                nbrs ^= nb
                stack.append(nb)
        return seen

