            return None if state["white"] else False

        remaining = passable
        white_component = 0
        force_black_mask = 0

        while remaining:
            start = remaining & -remaining
            comp = flood(start, passable)
            remaining &= ~comp

            if comp & state["white"]:
                if white_component and comp != white_component:
                    return None
                white_component = comp
            else:
                # This component can never connect to the current white group.
                # Therefore every cell in it must be black.
                force_black_mask |= comp

        changed = False

        if force_black_mask:
            before_b = state["black"]
            if not add_black(state, force_black_mask):
                return None
            if state["black"] != before_b:
                changed = True

        # If there are white cells, all must stay connected through passable cells.
        if state["white"]:
            passable = pre["all_mask"] & ~state["black"]
            root = state["white"] & -state["white"]

            # Unknown articulation cells separating current white cells are forced white.
            candidates = (passable & ~state["white"])
            force_white_mask = 0
            while candidates:
                bit = candidates & -candidates
                candidates ^= bit
                reachable = flood(root, passable & ~bit)
                if (state["white"] & ~bit) & ~reachable:
                    force_white_mask |= bit

            if force_white_mask:
                before_w = state["white"]
                if not add_white(state, force_white_mask):
                    return None
                if state["white"] != before_w:
                    changed = True

        return changed

    def probe(state):
        # Contradiction probing on promising unknown cells.
        unknown = pre["all_mask"] & ~(state["white"] | state["black"])
        if not unknown:
            return False

        cells = []
        tmp = unknown
        while tmp:
            bit = tmp & -tmp
            tmp ^= bit
            i = bit.bit_length() - 1
            cells.append((pre["cell_score"][i], i))

        cells.sort(reverse=True)
        limit = len(cells) if len(cells) <= 18 else 18

        for _, i in cells[:limit]:
            bit = 1 << i

            # Try black.
            black_ok = True
            st = copy_state(state)
            if not add_black(st, bit) or not propagate(st, allow_probe=False):
                black_ok = False

            if not black_ok:
                before_w = state["white"]
                if not add_white(state, bit):
                    return None
                return state["white"] != before_w

            # Try white.
            white_ok = True
            st = copy_state(state)
            if not add_white(st, bit) or not propagate(st, allow_probe=False):
                white_ok = False

            if not white_ok:
                before_b = state["black"]
                if not add_black(state, bit):
                    return None
                return state["black"] != before_b

        return False

    def propagate(state, allow_probe=True):
        while True:
            changed = False

            if state["white"] & state["black"]:
                return False
            if state["black"] & pre["clue_mask"]:
                return False

            # Filter clue domains; collect intersection-forced cells.
            force_white_mask = 0
            force_black_mask = 0

            for ci, dom in enumerate(state["domains"]):
                pats = pre["patterns"][ci]
                new_dom = []
                inter_w = None
                inter_b = None

                for pi in dom:
                    wmask, bmask = pats[pi]
                    if (wmask & state["black"]) or (bmask & state["white"]):
                        continue
                    new_dom.append(pi)
                    if inter_w is None:
                        inter_w = wmask
                        inter_b = bmask
                    else:
                        inter_w &= wmask
                        inter_b &= bmask

                if not new_dom:
                    return False

                if new_dom != dom:
                    state["domains"][ci] = new_dom
                    changed = True

                force_white_mask |= inter_w
                force_black_mask |= inter_b

            # Apply clue-forced cells.
            new_w = force_white_mask & ~(state["white"] | state["black"])
            if new_w:
                before_w = state["white"]
                if not add_white(state, new_w):
                    return False
                if state["white"] != before_w:
                    changed = True

            new_b = force_black_mask & ~(state["white"] | state["black"])
            if new_b:
                before_b = state["black"]
                if not add_black(state, new_b):
                    return False
                if state["black"] != before_b:
                    changed = True

            # Connectivity implications.
            conn = connectivity_forces(state)
            if conn is None:
                return False
            if conn:
                changed = True

            if not changed:
                if allow_probe:
                    pr = probe(state)
                    if pr is None:
                        return False
                    if pr:
                        continue
                break

        return True

    def choose_discriminating_cell(state, clue_index):
        dom = state["domains"][clue_index]
        pats = pre["patterns"][clue_index]
        unknown = pre["all_mask"] & ~(state["white"] | state["black"])
        if not unknown:
            return None

        counts = {}
        dlen = len(dom)
        for pi in dom:
            wmask, bmask = pats[pi]

            tmp = wmask & unknown
            while tmp:
                bit = tmp & -tmp
                tmp ^= bit
                i = bit.bit_length() - 1
                pair = counts.get(i)
                if pair is None:
                    counts[i] = [1, 0]
                else:
                    pair[0] += 1

