            surv_white = dlen - cb
            both = 0 if (cw > 0 and cb > 0) else 1
            # Prefer cells that best split the constrained clue.
            key = (
                both,
                max(surv_black, surv_white),
                abs(surv_black - surv_white),
                -pre["cell_score"][i],
            )
