                best_key = key
                best = (i, surv_white, surv_black)

        if best is None:
            return None

        i, surv_white, surv_black = best
        if surv_black < surv_white:
            order = ("B", "W")
        else:
            order = ("W", "B")
        return i, order

    def choose_branch(state):
