        best_ci = None
        best_len = 10**9
        for ci, dom in enumerate(state["domains"]):
            dl = len(dom)
            if 1 < dl < best_len:
                best_len = dl
                best_ci = ci

        if best_ci is not None:
            dom = state["domains"][best_ci]

            # Tiny domains: branch directly on the whole clue pattern.
            if len(dom) <= 3:
                order = dom[:]
                order.sort(
                    key=lambda pi: -(
                        ((pre["patterns"][best_ci][pi][0] | pre["patterns"][best_ci][pi][1]) & unknown).bit_count()
                    )
                )
                return ("pattern", best_ci, order)

            # Otherwise use a discriminating cell from that clue.
            choice = choose_discriminating_cell(state, best_ci)
            if choice is not None:
                i, order = choice
                return ("cell", i, order)

        # Fallback: best unknown cell by static relevance.
        best_i = None
        best_key = None
        tmp = unknown
        while tmp:
            bit = tmp & -tmp
            tmp ^= bit
            i = bit.bit_length() - 1
            key = (-pre["cell_score"][i], -((pre["adj"][i] & unknown).bit_count()))
