            for ray in clue["dirs"]:
                for j in ray:
                    if state["black"] & (1 << j):
                        break
                    total += 1
            if total != clue["value"]:
                return False

        # White connectivity.
        if state["white"]:
            root = state["white"] & -state["white"]
            reached = flood(root, state["white"])
            if reached != state["white"]:
                return False

        return True

    def render(state):
        out = []
        for r in range(n):
            row = []
            for c in range(n):
                i = idx(r, c)
                v = data[r][c]
                if v is not None:
                    row.append(v)
                elif state["black"] & (1 << i):
                    row.append("B")
                else:
                    row.append(None)
            out.append(row)
        return str(out)

    dead = set()

    def dfs(state):
        if not propagate(state, allow_probe=True):
            return None

        key = (state["white"], state["black"])
        if key in dead:
            return None

        if (state["white"] | state["black"]) == pre["all_mask"]:
            if validate_solution(state):
                return state
            dead.add(key)
            return None

        branch = choose_branch(state)
        if branch is None:
            dead.add(key)
            return None

        kind = branch[0]

        if kind == "pattern":
            _, ci, order = branch
            for pi in order:
