                if not add_black(st, bmask):
                    continue
                res = dfs(st)
                if res is not None:
                    return res

        else:
            _, i, order = branch
            bit = 1 << i
            for value in order:
                st = copy_state(state)
                ok = add_black(st, bit) if value == "B" else add_white(st, bit)
                if not ok:
                    continue
                res = dfs(st)
                if res is not None:
                    return res

        dead.add(key)
        return None

    init_state = {
        "white": clue_mask,
        "black": 0,
        "domains": [list(range(len(pats))) for pats in patterns],
    }

    result = dfs(init_state)
    if result is None:
        return "No Solution"
    return render(result)


