class AkariSolver:
    # Human-like solver:
    # 1) Exact local reasoning around numbered black cells by enumerating valid adjacent patterns.
    # 2) Immediate line-of-sight singleton deductions for dark cells.
    # 3) Branch first on the smallest ambiguous numbered pattern, otherwise on a cell from the
    #    most constrained dark-cell clause.

    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.cell_at = [[-1] * self.n for _ in range(self.n)]
        self.index_to_rc = []

        for r in range(self.n):
            for c in range(self.n):
                if data[r][c] is None:
                    idx = len(self.index_to_rc)
                    self.cell_at[r][c] = idx
                    self.index_to_rc.append((r, c))

        self.w = len(self.index_to_rc)
        self.all_white_mask = (1 << self.w) - 1 if self.w else 0

        self.rowseg_of = [0] * self.w
        self.colseg_of = [0] * self.w
        self.rowseg_masks = []
        self.colseg_masks = []

        self._build_segments()
        self.lighting_mask = [0] * self.w
        self.conflict_mask = [0] * self.w
        for idx in range(self.w):
            rm = self.rowseg_masks[self.rowseg_of[idx]]
            cm = self.colseg_masks[self.colseg_of[idx]]
            vis = rm | cm
            self.lighting_mask[idx] = vis
            self.conflict_mask[idx] = vis ^ (1 << idx)

        self.num_masks = []
        self.num_targets = []
        self.num_cells = []
        self.cell_to_nums = [[] for _ in range(self.w)]
        self._build_number_constraints()

        self.failed = set()

    def _build_segments(self):
        for r in range(self.n):
            c = 0
            while c < self.n:
                if self.data[r][c] is not None:
                    c += 1
                    continue
                mask = 0
                seg_id = len(self.rowseg_masks)
                while c < self.n and self.data[r][c] is None:
                    idx = self.cell_at[r][c]
                    self.rowseg_of[idx] = seg_id
                    mask |= 1 << idx
                    c += 1
                self.rowseg_masks.append(mask)

        for c in range(self.n):
            r = 0
            while r < self.n:
                if self.data[r][c] is not None:
                    r += 1
                    continue
                mask = 0
                seg_id = len(self.colseg_masks)
                while r < self.n and self.data[r][c] is None:
                    idx = self.cell_at[r][c]
                    self.colseg_of[idx] = seg_id
                    mask |= 1 << idx
                    r += 1
                self.colseg_masks.append(mask)

    def _build_number_constraints(self):
