                best = ("cover", t, None, opts)
                best_key = key

        # Fallback: choose a single influential undecided cell.
        if best is None:
            unknowns = [i for i in range(self.W) if s.status[i] == UNKNOWN]
            if not unknowns:
                return None
            unknowns.sort(key=lambda i: (-self.cell_score(s, i), i))
            i = unknowns[0]
            best = ("cell", i, None, None)

        return best

    def apply_number_combo(self, s, u, combo):
        chosen = set(combo)
        for i in u:
            if i in chosen:
                ok, _ = self.set_bulb(s, i)
            else:
                ok, _ = self.set_empty(s, i)
            if not ok:
                return False
        return True

    def search(self, s):
        s = self.propagate(s)
        if s is None:
            return None

        while True:
            if self.is_solved(s):
                return s
            out = self.contradiction_infer(s)
            if out is None:
                return None
            s, changed = out
            if not changed:
                break
            s = self.propagate(s)
            if s is None:
                return None

        if self.is_solved(s):
            return s

        key = tuple(s.status)
        if key in self.unsat:
            return None

        branch = self.choose_branch(s)
        if branch is None:
            return s if self.is_solved(s) else None

        kind, target, u, options = branch

        if kind == "number":
            for combo in options:
                child = s.copy()
                if self.apply_number_combo(child, u, combo):
                    res = self.search(child)
                    if res is not None:
                        return res

        elif kind == "cover":
            for i in options:
                child = s.copy()
                ok, _ = self.set_bulb(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

        else:
            i = target
            bulb_first = (
                any(s.lit[t] == 0 for t in self.illuminates[i]) or
                any(self.num_vals[cid] > s.bulbs_count[cid] for cid in self.adj_nums[i])
            )

            if bulb_first:
                child = s.copy()
                ok, _ = self.set_bulb(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

                child = s.copy()
                ok, _ = self.set_empty(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res
            else:
                child = s.copy()
                ok, _ = self.set_empty(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

                child = s.copy()
                ok, _ = self.set_bulb(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

        self.unsat.add(key)
        return None

    def answer_grid(self, s):
        grid = [[None for _ in range(self.C)] for _ in range(self.R)]
        for i, (r, c) in enumerate(self.white_coords):
            if s.status[i] == BULB:
                grid[r][c] = "B"
        return grid

    def run(self):
        res = self.search(self.initial_state())
        if res is None:
            return "No Solution"
        return repr(self.answer_grid(res))


def solve(observation):
    return AkariSolver(observation).run()


