        score = self.cell_static_score[i]
        for t in self.illuminates[i]:
            if s.lit[t] == 0:
                score += 1
        for cid in self.adj_nums[i]:
            score += 2 * (self.num_vals[cid] - s.bulbs_count[cid])
        return score

    def assumption_possible(self, s, i, bulb):
        tmp = s.copy()
        if bulb:
            ok, _ = self.set_bulb(tmp, i)
        else:
            ok, _ = self.set_empty(tmp, i)
        if not ok:
            return False
        return self.propagate(tmp) is not None

    def contradiction_infer(self, s):
        # Limited trial-based deduction on the most constrained frontier.
        pivots = set()

        min_cover = None
        for t in range(self.W):
            if s.lit[t] == 0 and s.cand_count[t] > 1:
                if min_cover is None or s.cand_count[t] < min_cover:
                    min_cover = s.cand_count[t]

        if min_cover is not None and min_cover <= 4:
            for t in range(self.W):
                if s.lit[t] == 0 and s.cand_count[t] == min_cover:
                    for i in self.illuminators[t]:
                        if s.status[i] == UNKNOWN:
                            pivots.add(i)

        min_num_branches = None
        for cid, req in enumerate(self.num_vals):
            rem = req - s.bulbs_count[cid]
            u = [i for i in self.num_adjs[cid] if s.status[i] == UNKNOWN]
            if 0 < rem < len(u):
                branches = comb(len(u), rem)
                if min_num_branches is None or branches < min_num_branches:
                    min_num_branches = branches

        if min_num_branches is not None and min_num_branches <= 4:
            for cid, req in enumerate(self.num_vals):
                rem = req - s.bulbs_count[cid]
                u = [i for i in self.num_adjs[cid] if s.status[i] == UNKNOWN]
                if 0 < rem < len(u) and comb(len(u), rem) == min_num_branches:
                    pivots.update(u)

        ordered = sorted(
            (i for i in pivots if s.status[i] == UNKNOWN),
            key=lambda i: (-self.cell_score(s, i), i),
        )

        changed = False
        for i in ordered[:8]:
            bulb_possible = self.assumption_possible(s, i, True)
            empty_possible = self.assumption_possible(s, i, False)

            if not bulb_possible and not empty_possible:
                return None
            if not bulb_possible:
                ok, ch = self.set_empty(s, i)
                if not ok:
                    return None
                changed = changed or ch
            elif not empty_possible:
                ok, ch = self.set_bulb(s, i)
                if not ok:
                    return None
                changed = changed or ch

        return s, changed

    def choose_branch(self, s):
        best = None
        best_key = None

        # Prefer branching on a numbered cell's exact remaining combinations.
        for cid, req in enumerate(self.num_vals):
            rem = req - s.bulbs_count[cid]
            if rem <= 0:
                continue
            u = [i for i in self.num_adjs[cid] if s.status[i] == UNKNOWN]
            if not u or rem >= len(u):
                continue

            count = comb(len(u), rem)
            key = (count, 0, -len(u))

            if best_key is None or key < best_key:
                scored = []
                for combo in combinations(u, rem):
                    score = sum(self.cell_score(s, i) for i in combo)
                    scored.append((-score, combo))
                scored.sort()
                options = [combo for _, combo in scored]
                best = ("number", cid, tuple(u), options)
                best_key = key

        # Otherwise branch on the darkest still-unlit cell with the fewest lighting options.
        for t in range(self.W):
            if s.lit[t] != 0:
                continue
            opts = [i for i in self.illuminators[t] if s.status[i] == UNKNOWN]
            if len(opts) <= 1:
                continue

            impact = sum(1 for i in opts if self.adj_nums[i])
            key = (len(opts), 1, -impact)

            if best_key is None or key < best_key:
                opts.sort(key=lambda i: (-self.cell_score(s, i), i))
                best = ("cover", t, None, opts)
                best_key = key

        # Fallback: choose a single influential undecided cell.
        if best is None:
            unknowns = [i for i in range(self.W) if s.status[i] == UNKNOWN]
            if not unknowns:
                return None
            unknowns.sort(key=lambda i: (-self.cell_score(s, i), i))
            i = unknowns[0]
            best = ("cell", i, None, None)

        return best

    def apply_number_combo(self, s, u, combo):
        chosen = set(combo)
        for i in u:
            if i in chosen:
                ok, _ = self.set_bulb(s, i)
            else:
                ok, _ = self.set_empty(s, i)
            if not ok:
                return False
        return True

    def search(self, s):
        s = self.propagate(s)
        if s is None:
            return None

        while True:
            if self.is_solved(s):
                return s
            out = self.contradiction_infer(s)
            if out is None:
                return None
            s, changed = out
            if not changed:
                break
            s = self.propagate(s)
            if s is None:
                return None

        if self.is_solved(s):
            return s

        key = tuple(s.status)
        if key in self.unsat:
            return None

        branch = self.choose_branch(s)
        if branch is None:
            return s if self.is_solved(s) else None

        kind, target, u, options = branch

        if kind == "number":
            for combo in options:
                child = s.copy()
                if self.apply_number_combo(child, u, combo):
                    res = self.search(child)
                    if res is not None:
                        return res

        elif kind == "cover":
            for i in options:
                child = s.copy()
                ok, _ = self.set_bulb(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

        else:
            i = target
            bulb_first = (
                any(s.lit[t] == 0 for t in self.illuminates[i]) or
                any(self.num_vals[cid] > s.bulbs_count[cid] for cid in self.adj_nums[i])
            )

            if bulb_first:
                child = s.copy()
                ok, _ = self.set_bulb(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

                child = s.copy()
                ok, _ = self.set_empty(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res
            else:
                child = s.copy()
                ok, _ = self.set_empty(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

                child = s.copy()
                ok, _ = self.set_bulb(child, i)
                if ok:
                    res = self.search(child)
                    if res is not None:
                        return res

        self.unsat.add(key)
        return None

    def answer_grid(self, s):
        grid = [[None for _ in range(self.C)] for _ in range(self.R)]
        for i, (r, c) in enumerate(self.white_coords):
            if s.status[i] == BULB:
                grid[r][c] = "B"
        return grid

    def run(self):
        res = self.search(self.initial_state())
        if res is None:
            return "No Solution"
        return repr(self.answer_grid(res))


def solve(observation):
    return AkariSolver(observation).run()


