        # Row segments: maximal white runs separated by black cells.
        self.row_seg_of = [-1] * self.white_count
        self.row_segments = []
        for r in range(self.rows):
            seg = []
            for c in range(self.cols + 1):
                if c < self.cols and data[r][c] is None:
                    seg.append(self.pos_to_idx[(r, c)])
                else:
                    if seg:
                        sid = len(self.row_segments)
                        self.row_segments.append(tuple(seg))
                        for idx in seg:
                            self.row_seg_of[idx] = sid
                        seg = []

        # Column segments.
        self.col_seg_of = [-1] * self.white_count
        self.col_segments = []
        for c in range(self.cols):
            seg = []
            for r in range(self.rows + 1):
                if r < self.rows and data[r][c] is None:
                    seg.append(self.pos_to_idx[(r, c)])
                else:
                    if seg:
                        sid = len(self.col_segments)
                        self.col_segments.append(tuple(seg))
                        for idx in seg:
                            self.col_seg_of[idx] = sid
                        seg = []

        # For each white cell:
        # - conflicts: cells a bulb would illuminate directly, so they cannot also be bulbs.
        # - cover_sets: cells whose bulb would illuminate this cell (including itself).
        self.conflicts = [None] * self.white_count
        self.cover_sets = [None] * self.white_count
        for i in range(self.white_count):
            rseg = self.row_segments[self.row_seg_of[i]]
            cseg = self.col_segments[self.col_seg_of[i]]

            cover = list(rseg)
            for j in cseg:
                if j != i:
                    cover.append(j)
            self.cover_sets[i] = tuple(cover)

            conflict = [j for j in rseg if j != i]
            conflict.extend(j for j in cseg if j != i)
            self.conflicts[i] = tuple(conflict)

        # Numbered black-cell constraints.
        self.num_targets = []
        self.num_adjs = []
        self.num_positions = []
        self.adj_num_of_cell = [[] for _ in range(self.white_count)]
        for r in range(self.rows):
            for c in range(self.cols):
                val = data[r][c]
                if val is not None and val >= 0:
                    adj = []
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        rr, cc = r + dr, c + dc
                        if (rr, cc) in self.pos_to_idx:
                            adj.append(self.pos_to_idx[(rr, cc)])
