    def is_lit(self, i, state):
        for j in self.cover_sets[i]:
            if state[j] == 1:
                return True
        return False

    def can_place_bulb(self, i, state):
        if state[i] == 0:
            return False

        # No other visible bulb.
        for j in self.conflicts[i]:
            if j != i and state[j] == 1:
                return False

        # Respect all adjacent numbered cells, both upper and lower feasibility.
        for cid in self.adj_num_of_cell[i]:
            target = self.num_targets[cid]
            bulbs = 0
            undec = 0
            for j in self.num_adjs[cid]:
                s = state[j]
                if s == 1:
                    bulbs += 1
                elif s == -1:
                    undec += 1

            if state[i] == -1:
                bulbs += 1
                undec -= 1

            if bulbs > target or bulbs + undec < target:
                return False

        return True

    def force_empty(self, state, i):
        cur = state[i]
        if cur == 0:
            return True, False
        if cur == 1:
            return False, False
        state[i] = 0
        return True, True

    def force_bulb(self, state, i):
        cur = state[i]
        if cur == 1:
            return True, False
        if cur == 0:
            return False, False
        if not self.can_place_bulb(i, state):
            return False, False
        state[i] = 1
        return True, True

    def apply_subset_reasoning(self, state):
        changed = False
        info = []
        for cid, target in enumerate(self.num_targets):
            bulbs, undec = self.number_info(cid, state)
            rem = target - bulbs
            if rem < 0 or rem > len(undec):
                return None
            info.append((rem, set(undec)))

        m = len(info)
        for a in range(m):
            rem_a, set_a = info[a]
            if not set_a:
                continue
            for b in range(a + 1, m):
                rem_b, set_b = info[b]
                if not set_b:
                    continue

                if set_a <= set_b:
                    extra = set_b - set_a
                    diff = rem_b - rem_a
                elif set_b <= set_a:
                    extra = set_a - set_b
                    diff = rem_a - rem_b
                else:
                    continue

                if diff < 0 or diff > len(extra):
                    return None

                if not extra:
                    continue

                if diff == 0:
                    for i in extra:
                        ok, ch = self.force_empty(state, i)
                        if not ok:
                            return None
                        changed = changed or ch
                elif diff == len(extra):
                    for i in extra:
                        ok, ch = self.force_bulb(state, i)
