                    continue
                if not self.can_place_bulb(i, state):
                    return False
                for j in self.conflicts[i]:
                    if state[j] == 1:
                        return False
                    if state[j] == -1:
                        state[j] = 0
                        changed = True

            # Rule 2: numbered black cells.
            for cid, target in enumerate(self.num_targets):
                bulbs, undec = self.number_info(cid, state)
                if bulbs > target or bulbs + len(undec) < target:
                    return False

                rem = target - bulbs
                if rem == 0:
                    for i in undec:
                        ok, ch = self.force_empty(state, i)
                        if not ok:
                            return False
                        changed = changed or ch
                elif rem == len(undec):
                    for i in undec:
                        ok, ch = self.force_bulb(state, i)
                        if not ok:
                            return False
                        changed = changed or ch

            # Rule 3: any cell that can never be a bulb becomes empty.
            for i, s in enumerate(state):
                if s == -1 and not self.can_place_bulb(i, state):
