            return ("cell", undec[0])

        return ("done",)

    def search(self, state):
        if not self.propagate(state, use_lookahead=True):
            return None

        if self.is_complete(state):
            final_state = state[:]
            for i, s in enumerate(final_state):
                if s == -1:
                    final_state[i] = 0
            return final_state

        branch = self.choose_branch(state)
        kind = branch[0]

        if kind == "contradiction":
            return None

        if kind == "done":
            if self.is_complete(state):
                final_state = state[:]
                for i, s in enumerate(final_state):
                    if s == -1:
                        final_state[i] = 0
                return final_state
            return None

        if kind == "num":
            _, cid, undec, rem = branch
            combs = list(combinations(undec, rem))
            combs.sort(key=lambda picked: -sum(self.branch_weight[i] for i in picked))

            undec_set = tuple(undec)
            for picked in combs:
                picked = set(picked)
                new_state = state[:]
                ok = True

                for i in undec_set:
                    if i in picked:
                        good, _ = self.force_bulb(new_state, i)
                    else:
                        good, _ = self.force_empty(new_state, i)
                    if not good:
                        ok = False
                        break

                if not ok:
                    continue

                result = self.search(new_state)
                if result is not None:
                    return result
            return None

        if kind == "cover":
            _, cell, cand = branch
            ordered = sorted(cand, key=lambda i: (-self.branch_weight[i], self.white_cells[i]))
            for i in ordered:
                new_state = state[:]
                ok, _ = self.force_bulb(new_state, i)
                if not ok:
                    continue
                result = self.search(new_state)
                if result is not None:
                    return result
            return None

        # Fallback binary branch on a single undecided cell.
        _, i = branch
        for val in (1, 0):
            new_state = state[:]
            if val == 1:
                ok, _ = self.force_bulb(new_state, i)
            else:
                ok, _ = self.force_empty(new_state, i)
            if not ok:
                continue
            result = self.search(new_state)
            if result is not None:
                return result
        return None

    def to_answer_grid(self, state):
        ans = [[None for _ in range(self.cols)] for _ in range(self.rows)]
        for i, s in enumerate(state):
            if s == 1:
                r, c = self.white_cells[i]
                ans[r][c] = 'B'
        return ans


def solve(observation):
    data = observation['data']
    solver = AkariSolver(data)
    initial_state = [-1] * solver.white_count
    result = solver.search(initial_state)
    if result is None:
        return "No Solution"
    return repr(solver.to_answer_grid(result))


