            return False
        for cid, target in enumerate(self.num_targets):
            if s.num_placed[cid] != target:
                return False
        return True

    def choose_branch(self, s):
        best_cover = None
        best_cover_size = 10**9

        for i in range(self.W):
            if self.is_lit(s, i):
                continue
            cands = [j for j in self.cover_lists[i] if self.can_be_bulb(s, j)]
            k = len(cands)
            if k == 0:
                return None
            if 1 < k < best_cover_size:
                best_cover_size = k
                best_cover = (i, cands)
                if k == 2:
                    break

        best_num = None
        best_num_width = 10**9

        for cid, target in enumerate(self.num_targets):
            rem = target - s.num_placed[cid]
            if rem <= 0:
                continue
            undec = [i for i in self.num_adj[cid] if self.is_unknown(s, i)]
            if not undec:
                continue
            if rem == len(undec):
                continue
            width = comb(len(undec), rem)
            if 1 < width < best_num_width:
                best_num_width = width
                best_num = (cid, undec, rem)

        if best_cover is not None and (best_num is None or best_cover_size <= best_num_width):
            return ("cover", best_cover)

        if best_num is not None:
            return ("number", best_num)

        return None

    def search(self, s):
        pre_key = (s.bulb_mask, s.empty_mask)
        if pre_key in self.dead:
            return None

        if not self.propagate(s):
            self.dead.add(pre_key)
            return None

        key = (s.bulb_mask, s.empty_mask)
        if key in self.dead:
            self.dead.add(pre_key)
            return None

        if self.is_solved(s):
            return s

        branch = self.choose_branch(s)
        if branch is None:
            self.dead.add(key)
            self.dead.add(pre_key)
            return None

        kind, data = branch

        if kind == "cover":
            _, cands = data
            cands = sorted(cands, key=lambda i: self.impact[i], reverse=True)
            for j in cands:
                t = self.copy_state(s)
                res = self.assign_bulb(t, j)
                if res is False:
                    continue
                ans = self.search(t)
                if ans is not None:
                    return ans

        elif kind == "number":
            _, undec, rem = data
            combos = list(combinations(undec, rem))
            combos.sort(key=lambda tup: -sum(self.impact[i] for i in tup))

            for chosen in combos:
                chosen = set(chosen)
                t = self.copy_state(s)
                ok = True
