                        res = self.assign_bulb(t, i)
                    else:
                        res = self.assign_empty(t, i)
                    if res is False:
                        ok = False
                        break
                if not ok:
                    continue
                ans = self.search(t)
                if ans is not None:
                    return ans

        self.dead.add(key)
        self.dead.add(pre_key)
        return None

    def build_answer(self, s):
        out = [[None for _ in range(self.m)] for _ in range(self.n)]
        for i, (r, c) in enumerate(self.white_positions):
            if s.bulb_mask & self.bits[i]:
                out[r][c] = "B"
        return out

    def solve_grid(self):
        s = self.new_state()
        ans = self.search(s)
        if ans is None:
            return None
        return self.build_answer(ans)


def solve(observation):
    grid = observation["data"]
    solver = AkariSolver(grid)
    ans = solver.solve_grid()
    if ans is None:
        return "No Solution"
    return repr(ans)


