                seg_idxs.append(i)
                seg_mask |= bits[i]
                c += 1
            for i in seg_idxs:
                row_seg_masks[i] = seg_mask

    for c in range(cols):
        r = 0
        while r < rows:
            if data[r][c] is not None:
                r += 1
                continue
            seg_mask = 0
            seg_idxs = []
            while r < rows and data[r][c] is None:
                i = index_of[(r, c)]
                seg_idxs.append(i)
                seg_mask |= bits[i]
                r += 1
            for i in seg_idxs:
                col_seg_masks[i] = seg_mask

    vis_masks = [row_seg_masks[i] | col_seg_masks[i] for i in range(wcount)]
    attack_masks = [vis_masks[i] & ~bits[i] for i in range(wcount)]

    # Numbered black cell constraints.
    num_adj_masks = []
    num_reqs = []
    cell_num_degree = [0] * wcount
    orth = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if isinstance(val, int) and val >= 0:
                mask = 0
                for dr, dc in orth:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < rows and 0 <= cc < cols and data[rr][cc] is None:
                        i = index_of[(rr, cc)]
                        mask |= bits[i]
                        cell_num_degree[i] += 1
                num_adj_masks.append(mask)
                num_reqs.append(val)

    mcount = len(num_reqs)

    def compute_lit(bmask):
        lit = 0
        m = bmask
        while m:
            lsb = m & -m
            i = lsb.bit_length() - 1
            lit |= vis_masks[i]
            m ^= lsb
        return lit

    def force_bulb(bmask, nmask, i):
        bit = bits[i]
        if nmask & bit:
            return None
        if bmask & bit:
            return bmask, nmask, False
        if attack_masks[i] & bmask:
            return None
        bmask |= bit
        nmask |= attack_masks[i]
        return bmask, nmask, True

    def force_bulbs_mask(bmask, nmask, mask):
        changed = False
        m = mask
        while m:
            lsb = m & -m
            i = lsb.bit_length() - 1
            res = force_bulb(bmask, nmask, i)
            if res is None:
                return None
            bmask, nmask, ch = res
            changed = changed or ch
            m ^= lsb
        return bmask, nmask, changed

    def force_nobulb_mask(bmask, nmask, mask):
        if mask & bmask:
            return None
        new_bits = mask & ~nmask
        if not new_bits:
            return bmask, nmask, False
        nmask |= new_bits
        return bmask, nmask, True

    def propagate(bmask, nmask):
        # Repeatedly apply deterministic human-like deductions:
        # 1) numbered black exactness
        # 2) subset reasoning between nearby numbered constraints
        # 3) every unlit cell must keep at least one possible bulb;
        #    if only one remains, force it
        while True:
            if bmask & nmask:
                return None

            progress = False
            residual_need = [0] * mcount
            residual_undec = [0] * mcount

            # Exact numbered-cell propagation.
            for k in range(mcount):
                adj = num_adj_masks[k]
                req = num_reqs[k]
                fixed = (bmask & adj).bit_count()
                if fixed > req:
                    return None
                undec = adj & ~(bmask | nmask)
                need = req - fixed
                ucount = undec.bit_count()
                if need < 0 or need > ucount:
                    return None

                residual_need[k] = need
                residual_undec[k] = undec

                if need == 0 and undec:
                    res = force_nobulb_mask(bmask, nmask, undec)
                    if res is None:
                        return None
                    bmask, nmask, ch = res
                    if ch:
                        progress = True
                elif need == ucount and undec:
                    res = force_bulbs_mask(bmask, nmask, undec)
                    if res is None:
                        return None
                    bmask, nmask, ch = res
                    if ch:
                        progress = True

            if progress:
                continue

            # Subset reasoning on residual numbered constraints.
            subset_progress = False
            for a in range(mcount):
                ua = residual_undec[a]
                if not ua:
                    continue
                na = residual_need[a]
                for b in range(mcount):
                    if a == b:
                        continue
                    ub = residual_undec[b]
                    if not ub or ua == ub:
                        continue
                    if ua & ~ub:
                        continue  # ua is not a subset of ub
                    diff = ub ^ ua
                    delta = residual_need[b] - na
                    dcount = diff.bit_count()
                    if delta < 0 or delta > dcount:
                        return None
                    if delta == 0 and diff:
                        res = force_nobulb_mask(bmask, nmask, diff)
                        if res is None:
                            return None
                        bmask, nmask, ch = res
                        if ch:
                            subset_progress = True
                            break
                    elif delta == dcount and diff:
                        res = force_bulbs_mask(bmask, nmask, diff)
                        if res is None:
                            return None
                        bmask, nmask, ch = res
                        if ch:
                            subset_progress = True
                            break
                if subset_progress:
                    break

            if subset_progress:
                continue

            # Illumination propagation.
            lit = compute_lit(bmask)
            for i in range(wcount):
                bit = bits[i]
                if lit & bit:
                    continue
                cand = vis_masks[i] & ~nmask
                if cand == 0:
                    return None
                if cand & (cand - 1) == 0:
                    j = cand.bit_length() - 1
                    res = force_bulb(bmask, nmask, j)
                    if res is None:
                        return None
                    bmask, nmask, ch = res
                    if ch:
                        progress = True
                        break

            if progress:
                continue

            return bmask, nmask

    def is_solved(bmask):
        if compute_lit(bmask) != all_mask:
            return False
        for k in range(mcount):
            if (bmask & num_adj_masks[k]).bit_count() != num_reqs[k]:
                return False
        return True

    def comb_small(n, k):
        if k < 0 or k > n:
            return 0
        if k == 0 or k == n:
            return 1
        if k == 1 or k == n - 1:
            return n
        return comb(n, k)

    def enumerate_k_submasks(mask, k):
        idxs = []
        m = mask
        while m:
            lsb = m & -m
            idxs.append(lsb.bit_length() - 1)
            m ^= lsb
        for combo in combinations(idxs, k):
            sm = 0
            for i in combo:
                sm |= bits[i]
            yield sm

    def choose_number_branch(bmask, nmask):
        # Pick the numbered cell with the fewest residual combinations.
        best = None
        best_score = None
        for k in range(mcount):
            adj = num_adj_masks[k]
            need = num_reqs[k] - (bmask & adj).bit_count()
            undec = adj & ~(bmask | nmask)
            ucount = undec.bit_count()
            if need <= 0 or need >= ucount:
                continue
            score = comb_small(ucount, need)
            if best is None or score < best_score or (score == best_score and ucount < best[2]):
                best = (k, undec, ucount, need)
                best_score = score
        return best

    def choose_unlit_exact_one_segment_branch(bmask, nmask):
        # If an unlit cell can only be lit from one axis, then exactly one bulb
        # must be chosen from that remaining segment.
        lit = compute_lit(bmask)
        best = None
        for i in range(wcount):
            if lit & bits[i]:
                continue
            row_c = row_seg_masks[i] & ~nmask
            col_c = col_seg_masks[i] & ~nmask
            if row_c and col_c:
                continue
            cand = row_c | col_c
            cnt = cand.bit_count()
            if cnt <= 1:
                continue
            if best is None or cnt < best[0]:
                best = (cnt, i, cand)
        return best

    def choose_binary_cell(bmask, nmask):
        # Prefer candidates from a minimally ambiguous unlit cell.
        lit = compute_lit(bmask)
        best_cell = None
        best_cand_count = None
        best_score = None

        for i in range(wcount):
            if lit & bits[i]:
                continue
            cand = vis_masks[i] & ~nmask
            cnt = cand.bit_count()
            if cnt <= 1:
                continue
            m = cand
            while m:
                lsb = m & -m
                j = lsb.bit_length() - 1
                score = ((vis_masks[j] & ~lit).bit_count() << 3) + (cell_num_degree[j] << 1) - attack_masks[j].bit_count()
                if (
                    best_cell is None
                    or cnt < best_cand_count
                    or (cnt == best_cand_count and score > best_score)
                ):
                    best_cell = j
                    best_cand_count = cnt
                    best_score = score
                m ^= lsb

        if best_cell is not None:
            return best_cell

        # Fallback: any undecided cell with high structural impact.
        undec = all_mask & ~(bmask | nmask)
        if not undec:
            return None
        best_cell = None
        best_score = None
        while undec:
            lsb = undec & -undec
            j = lsb.bit_length() - 1
            score = (cell_num_degree[j] << 4) + vis_masks[j].bit_count() - attack_masks[j].bit_count()
            if best_cell is None or score > best_score:
                best_cell = j
                best_score = score
            undec ^= lsb
        return best_cell

    fail = set()

    def dfs(bmask, nmask):
        prop = propagate(bmask, nmask)
        if prop is None:
            return None
        bmask, nmask = prop

        key = (bmask, nmask)
        if key in fail:
            return None

        if is_solved(bmask):
            return bmask

        # Strongest branch: exact choose-k around a numbered black cell.
        num_branch = choose_number_branch(bmask, nmask)
        if num_branch is not None:
            _, undec, _, need = num_branch
            lit = compute_lit(bmask)
            options = []
            for subset in enumerate_k_submasks(undec, need):
                score = 0
                m = subset
                while m:
                    lsb = m & -m
                    j = lsb.bit_length() - 1
                    score += (vis_masks[j] & ~lit).bit_count() + 3 * cell_num_degree[j]
                    m ^= lsb
                options.append((-score, subset))
            options.sort()

            for _, subset in options:
                others = undec ^ subset
                res = force_bulbs_mask(bmask, nmask, subset)
                if res is None:
                    continue
                nb, nn, _ = res
                res = force_nobulb_mask(nb, nn, others)
                if res is None:
                    continue
                nb, nn, _ = res
                out = dfs(nb, nn)
                if out is not None:
                    return out

            fail.add(key)
            return None

        # Next strongest: an unlit cell that can only be served from one segment.
        seg_branch = choose_unlit_exact_one_segment_branch(bmask, nmask)
        if seg_branch is not None:
            _, _, cand = seg_branch
            lit = compute_lit(bmask)
            options = []
            m = cand
            while m:
                lsb = m & -m
                j = lsb.bit_length() - 1
                score = (vis_masks[j] & ~lit).bit_count() + 3 * cell_num_degree[j]
                options.append((-score, j))
                m ^= lsb
            options.sort()

            for _, j in options:
                others = cand ^ bits[j]
                res = force_bulb(bmask, nmask, j)
                if res is None:
                    continue
                nb, nn, _ = res
                res = force_nobulb_mask(nb, nn, others)
                if res is None:
                    continue
                nb, nn, _ = res
                out = dfs(nb, nn)
                if out is not None:
                    return out

            fail.add(key)
            return None

        # General fallback: binary branch on a high-impact cell.
        j = choose_binary_cell(bmask, nmask)
        if j is None:
            fail.add(key)
            return None

        lit = compute_lit(bmask)
        bulb_first = cell_num_degree[j] > 0 or (vis_masks[j] & ~lit).bit_count() > 1

        if bulb_first:
            res = force_bulb(bmask, nmask, j)
            if res is not None:
                nb, nn, _ = res
                out = dfs(nb, nn)
                if out is not None:
                    return out
            res = force_nobulb_mask(bmask, nmask, bits[j])
            if res is not None:
                nb, nn, _ = res
                out = dfs(nb, nn)
                if out is not None:
                    return out
        else:
            res = force_nobulb_mask(bmask, nmask, bits[j])
            if res is not None:
                nb, nn, _ = res
                out = dfs(nb, nn)
                if out is not None:
                    return out
            res = force_bulb(bmask, nmask, j)
            if res is not None:
                nb, nn, _ = res
                out = dfs(nb, nn)
                if out is not None:
                    return out

        fail.add(key)
        return None

    solved_bmask = dfs(0, 0)
    if solved_bmask is None:
        return "No Solution"

    answer = [[None for _ in range(cols)] for _ in range(rows)]
