                best_key = key
                best_rr = rr

        rr = best_rr
        dom = domains[rr]

        # Prefer branching by tetromino type when that is coarser and more human-like.
        type_options = []
        for t in range(4):
            td = dom & by_type[rr][t]
            if td:
                type_options.append((td.bit_count(), t, td))

        if 1 < len(type_options) < dom.bit_count():
            type_options.sort()
            for _cnt, _t, td in type_options:
                new_domains = list(domains)
                new_domains[rr] = td
                ans = search(tuple(new_domains))
                if ans is not None:
                    return ans
        else:
            cand_options = []
            for i, bit in iter_bits(dom):
                tid = cand_types[rr][i]
                deg = 0
                support_total = 0
                for ss in region_neighbors[rr]:
                    sup = touch[rr][ss][i] & domains[ss] & other_type[ss][tid]
                    if sup:
                        deg += 1
                        support_total += sup.bit_count()
                cand_options.append((-deg, -support_total, cand_masks[rr][i], bit))
