            for _neg_deg, _neg_sup, _mask, bit in cand_options:
                new_domains = list(domains)
                new_domains[rr] = bit
                ans = search(tuple(new_domains))
                if ans is not None:
                    return ans

        fail_cache.add(domains)
        return None

    initial_domains = tuple(full_domains)
    solved = search(initial_domains)
    if solved is None:
        return "No Solution"
    return repr(solved)


