# Human-style CSP solver:
# - enumerate every tetromino placement inside each region
# - propagate region-type inequalities, 2x2 bans, and connectivity necessities
# - only then branch on the tightest remaining region/type choice

TYPE_ORDER = "ILTS"
TYPE_TO_ID = {ch: i for i, ch in enumerate(TYPE_ORDER)}

BASE_SHAPES = {
    "I": ((0, 0), (1, 0), (2, 0), (3, 0)),
    "L": ((0, 0), (1, 0), (2, 0), (2, 1)),
    "T": ((0, 0), (0, 1), (0, 2), (1, 1)),
    "S": ((0, 1), (0, 2), (1, 0), (1, 1)),
}


def _normalize(coords):
    min_r = min(r for r, _ in coords)
    min_c = min(c for _, c in coords)
    return tuple(sorted((r - min_r, c - min_c) for r, c in coords))


def _transform(coords, rot, reflect):
    pts = list(coords)
    if reflect:
        pts = [(r, -c) for r, c in pts]
    for _ in range(rot):
        pts = [(c, -r) for r, c in pts]
    return _normalize(pts)


def _build_orientations():
    out = {}
    for name, shape in BASE_SHAPES.items():
        seen = set()
        for reflect in (False, True):
            for rot in range(4):
                seen.add(_transform(shape, rot, reflect))
        out[name] = tuple(sorted(seen))
    return out


ORIENTATIONS = _build_orientations()


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data or not all(isinstance(row, list) for row in data):
