    # Cell adjacency masks
    cell_nbr_mask = [0] * n_cells
    for r in range(h):
        for c in range(w):
            idx = r * w + c
            m = 0
            if r > 0:
                m |= 1 << ((r - 1) * w + c)
            if r + 1 < h:
                m |= 1 << ((r + 1) * w + c)
