    neighbors = tuple(tuple(sorted(s)) for s in neighbors)

    # Orth-neighbor masks for cell-connectivity and inter-region touching.
    cell_neighbor_mask = [0] * (n * m)
    for r in range(n):
        for c in range(m):
            idx = cell_index(r, c)
            mask = 0
            if r > 0:
                mask |= 1 << cell_index(r - 1, c)
            if r + 1 < n:
                mask |= 1 << cell_index(r + 1, c)
            if c > 0:
                mask |= 1 << cell_index(r, c - 1)
            if c + 1 < m:
                mask |= 1 << cell_index(r, c + 1)
            cell_neighbor_mask[idx] = mask
    cell_neighbor_mask = tuple(cell_neighbor_mask)

    # 2x2 block masks.
    blocks = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks.append(
                (1 << cell_index(r, c))
                | (1 << cell_index(r + 1, c))
                | (1 << cell_index(r, c + 1))
                | (1 << cell_index(r + 1, c + 1))
            )
    blocks = tuple(blocks)

    # Enumerate all tetromino placements in each region.
    cand_bits = []
    cand_types = []
    cand_block_masks = []
    include_masks = []
    type_to_candmask = []

    for i in range(R):
        region_set = set(region_cells[i])
        local_bits = []
        local_types = []
        seen_placements = set()

        for t_idx, t_char in enumerate(TYPES):
            for shape in ORIENTATIONS[t_char]:
                max_dr = max(r for r, c in shape)
                max_dc = max(c for r, c in shape)
                for r0, c0 in region_cells[i]:
                    if r0 + max_dr >= n or c0 + max_dc >= m:
                        continue
                    mask = 0
                    ok = True
                    for dr, dc in shape:
                        rr = r0 + dr
                        cc = c0 + dc
                        if (rr, cc) not in region_set:
                            ok = False
                            break
                        mask |= 1 << cell_index(rr, cc)
                    if ok and mask not in seen_placements:
                        seen_placements.add(mask)
                        local_bits.append(mask)
                        local_types.append(t_idx)

        if not local_bits:
            return "No Solution"

        inc = [0] * (n * m)
        type_masks = [0] * len(TYPES)
        block_list = []
        for a, mask in enumerate(local_bits):
            type_masks[local_types[a]] |= 1 << a
            mm = mask
            while mm:
                b = mm & -mm
                idx = b.bit_length() - 1
                inc[idx] |= 1 << a
                mm ^= b
            block_list.append(tuple(bm for bm in blocks if bm & mask))

        cand_bits.append(tuple(local_bits))
        cand_types.append(tuple(local_types))
        cand_block_masks.append(tuple(block_list))
        include_masks.append(tuple(inc))
        type_to_candmask.append(tuple(type_masks))

    cand_bits = tuple(cand_bits)
    cand_types = tuple(cand_types)
    cand_block_masks = tuple(cand_block_masks)
    include_masks = tuple(include_masks)
    type_to_candmask = tuple(type_to_candmask)

    # Precompute candidate expansions and pairwise compatibility.
    cand_expand = []
    for i in range(R):
        ex = []
        for mask in cand_bits[i]:
            em = 0
            mm = mask
            while mm:
                b = mm & -mm
                idx = b.bit_length() - 1
                em |= cell_neighbor_mask[idx]
                mm ^= b
            ex.append(em)
        cand_expand.append(tuple(ex))
    cand_expand = tuple(cand_expand)

    not_same = [[None] * R for _ in range(R)]
    touch_compat = [[None] * R for _ in range(R)]

    for i in range(R):
        for j in neighbors[i]:
            if not_same[i][j] is not None:
                continue
            ni = len(cand_bits[i])
            nj = len(cand_bits[j])

            ns_ij = [0] * ni
            tc_ij = [0] * ni
            for a in range(ni):
                ta = cand_types[i][a]
                exa = cand_expand[i][a]
                mask_ns = 0
                mask_tc = 0
                for b in range(nj):
                    if cand_types[j][b] != ta:
                        bb = 1 << b
                        mask_ns |= bb
                        if exa & cand_bits[j][b]:
                            mask_tc |= bb
                ns_ij[a] = mask_ns
                tc_ij[a] = mask_tc

            ns_ji = [0] * nj
            tc_ji = [0] * nj
            for b in range(nj):
                tb = cand_types[j][b]
                exb = cand_expand[j][b]
                mask_ns = 0
                mask_tc = 0
                for a in range(ni):
                    if cand_types[i][a] != tb:
                        aa = 1 << a
                        mask_ns |= aa
                        if exb & cand_bits[i][a]:
                            mask_tc |= aa
                ns_ji[b] = mask_ns
                tc_ji[b] = mask_tc

            not_same[i][j] = tuple(ns_ij)
            touch_compat[i][j] = tuple(tc_ij)
            not_same[j][i] = tuple(ns_ji)
            touch_compat[j][i] = tuple(tc_ji)

    initial_domains = tuple((1 << len(cand_bits[i])) - 1 for i in range(R))

    @lru_cache(None)
    def summarize(domains):
        counts = []
        type_masks = []
        possible = []
        must = []
        global_must = 0

        for i, dom in enumerate(domains):
            counts.append(dom.bit_count())
            tmask = 0
            p = 0
            first = True
            inter = 0
            for a in _iter_bits(dom):
                p |= cand_bits[i][a]
                if first:
                    inter = cand_bits[i][a]
                    first = False
                else:
                    inter &= cand_bits[i][a]
                tmask |= 1 << cand_types[i][a]
            type_masks.append(tmask)
            possible.append(p)
            must.append(inter)
            global_must |= inter

        return tuple(counts), tuple(type_masks), tuple(possible), tuple(must), global_must

    @lru_cache(None)
    def edge_possible(i, j, dom_i, dom_j):
        for a in _iter_bits(dom_i):
            if touch_compat[i][j][a] & dom_j:
                return True
        return False

    @lru_cache(None)
    def graph_connected(domains):
        if R <= 1:
            return True
        seen = {0}
        stack = [0]
        while stack:
            i = stack.pop()
            di = domains[i]
            for j in neighbors[i]:
                if j not in seen and edge_possible(i, j, di, domains[j]):
                    seen.add(j)
                    stack.append(j)
        return len(seen) == R

    # Human-style propagation:
    # 1) remove candidates unsupported by adjacent region types
    # 2) apply forced 2x2 logic
    # 3) remove candidates that would complete a forced 2x2
    # 4) every chosen tetromino must be able to touch at least one neighbor
    # 5) potential region-touch graph must stay connected
    # 6) singleton connectivity lookahead on each candidate
    @lru_cache(None)
    def propagate(domains):
        doms = list(domains)

        while True:
            if any(d == 0 for d in doms):
                return None

            counts, type_masks, possible_bits, must_bits, global_must = summarize(tuple(doms))
            changed = False

            # Rule 1: adjacency type support.
            for i in range(R):
                di = doms[i]
                remove = 0
                for a in _iter_bits(di):
                    bad = False
                    for j in neighbors[i]:
                        if not (not_same[i][j][a] & doms[j]):
                            bad = True
                            break
                    if bad:
                        remove |= 1 << a
                if remove:
                    nd = di & ~remove
                    if nd == 0:
                        return None
                    if nd != di:
                        doms[i] = nd
                        changed = True
            if changed:
                continue

            # Rule 2: if 3 cells in a 2x2 are forced shaded, the 4th must be unshaded.
            remove = [0] * R
            for block in blocks:
                if (global_must & block) == block:
                    return None
                missing = block & ~global_must
                if missing and missing.bit_count() == 1:
                    cell_bit = missing & -missing
                    cell_idx = cell_bit.bit_length() - 1
                    i = cell_to_region[cell_idx]
                    remove[i] |= include_masks[i][cell_idx]
            for i in range(R):
                if remove[i]:
                    nd = doms[i] & ~remove[i]
                    if nd == 0:
                        return None
                    if nd != doms[i]:
                        doms[i] = nd
                        changed = True
            if changed:
                continue

            # Rule 3: candidate-level 2x2 completion against other forced cells.
            remove = [0] * R
            for i in range(R):
                di = doms[i]
                other_must = global_must & ~region_cellbits[i]
                for a in _iter_bits(di):
                    cb = cand_bits[i][a]
                    bad = False
                    for block in cand_block_masks[i][a]:
                        if ((block ^ (cb & block)) & ~other_must) == 0:
                            bad = True
                            break
                    if bad:
                        remove[i] |= 1 << a
            for i in range(R):
                if remove[i]:
                    nd = doms[i] & ~remove[i]
                    if nd == 0:
                        return None
                    if nd != doms[i]:
                        doms[i] = nd
                        changed = True
            if changed:
                continue

            # Rule 4: every region's tetromino must be able to touch something else.
            if R > 1:
                remove = [0] * R
                for i in range(R):
                    di = doms[i]
                    for a in _iter_bits(di):
                        ok = False
                        for j in neighbors[i]:
                            if touch_compat[i][j][a] & doms[j]:
                                ok = True
                                break
                        if not ok:
                            remove[i] |= 1 << a
                for i in range(R):
                    if remove[i]:
                        nd = doms[i] & ~remove[i]
                        if nd == 0:
                            return None
                        if nd != doms[i]:
                            doms[i] = nd
                            changed = True
                if changed:
                    continue

            # Rule 5: the possible region-touch graph must remain connected.
            dom_tuple = tuple(doms)
            if not graph_connected(dom_tuple):
                return None

            # Rule 6: singleton connectivity lookahead.
            remove = [0] * R
            for i in range(R):
                if doms[i].bit_count() <= 1:
                    continue
                di = doms[i]
                for a in _iter_bits(di):
                    trial = list(doms)
                    trial[i] = 1 << a
                    if not graph_connected(tuple(trial)):
                        remove[i] |= 1 << a
            for i in range(R):
                if remove[i]:
                    nd = doms[i] & ~remove[i]
                    if nd == 0:
                        return None
                    if nd != doms[i]:
                        doms[i] = nd
                        changed = True
            if changed:
                continue

            return tuple(doms)

    def final_check(domains):
        if any(d == 0 or (d & (d - 1)) != 0 for d in domains):
            return False

        picked_bits = []
        picked_types = []
        shaded = 0

        for i, d in enumerate(domains):
            a = d.bit_length() - 1
            picked_bits.append(cand_bits[i][a])
            picked_types.append(cand_types[i][a])
            shaded |= cand_bits[i][a]

        # Adjacent regions must differ in tetromino type.
        for i in range(R):
            for j in neighbors[i]:
                if j > i and picked_types[i] == picked_types[j]:
                    return False

        # No fully shaded 2x2.
        for block in blocks:
            if (shaded & block) == block:
                return False

        # Global orthogonal connectivity of shaded cells.
        if shaded == 0:
            return False
        start = shaded & -shaded
        seen = 0
        stack = [start]
        while stack:
            b = stack.pop()
            if seen & b:
                continue
            seen |= b
            idx = b.bit_length() - 1
            nxt = cell_neighbor_mask[idx] & shaded & ~seen
            while nxt:
                nb = nxt & -nxt
                stack.append(nb)
                nxt ^= nb
        return seen == shaded

    def choose_region(domains):
        counts, type_masks, possible_bits, must_bits, global_must = summarize(domains)
        best = None
        best_key = None
        for i in range(R):
            cnt = counts[i]
            if cnt <= 1:
                continue
            key = (
                cnt,
                type_masks[i].bit_count(),
                -len(neighbors[i]),
                -len(region_cells[i]),
            )
            if best is None or key < best_key:
                best = i
                best_key = key
        return best

    def candidate_order(i, a, domains):
        touch_support = 0
        for j in neighbors[i]:
            touch_support += (touch_compat[i][j][a] & domains[j]).bit_count()
        # Prefer candidates that preserve more touching options.
        return (-touch_support, cand_types[i][a], cand_bits[i][a])

    failed = set()

    def search(domains):
        domains = tuple(domains)
        if domains in failed:
            return None

        prop = propagate(domains)
        if prop is None:
            failed.add(domains)
            return None

        if prop in failed:
            return None

        if final_check(prop):
            return prop

        i = choose_region(prop)
        if i is None:
            failed.add(prop)
            failed.add(domains)
            return None

        vals = list(_iter_bits(prop[i]))
        vals.sort(key=lambda a: candidate_order(i, a, prop))

        for a in vals:
            trial = list(prop)
            trial[i] = 1 << a
            ans = search(tuple(trial))
            if ans is not None:
                return ans

        failed.add(prop)
        failed.add(domains)
        return None

    solution = search(initial_domains)
    if solution is None:
        return "No Solution"

    answer = [[None for _ in range(m)] for _ in range(n)]
    for i, d in enumerate(solution):
        a = d.bit_length() - 1
        t_char = TYPES[cand_types[i][a]]
        mask = cand_bits[i][a]
        while mask:
            b = mask & -mask
            idx = b.bit_length() - 1
            r, c = divmod(idx, m)
            answer[r][c] = t_char
            mask ^= b

    return repr(answer)


