# General Tetrominous solver:
# - one tetromino per region
# - allowed free tetromino types: L, I, T, S
# - adjacent regions cannot use same type
# - all shaded cells globally connected
# - no 2x2 fully shaded

import sys

TYPE_NAMES = ["L", "I", "T", "S"]
TYPE_INDEX = {name: i for i, name in enumerate(TYPE_NAMES)}

BASE_SHAPES = {
    "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
    "I": [(0, 0), (0, 1), (0, 2), (0, 3)],
    "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
    "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
}


def _generate_orientations(base):
    pts = list(base)
    out = set()

    def norm(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    for swap in (0, 1):
        for sr in (-1, 1):
            for sc in (-1, 1):
                cells = []
                for r, c in pts:
                    if swap:
                        r, c = c, r
                    cells.append((sr * r, sc * c))
                out.add(norm(cells))
    return sorted(out)


ORIENTATIONS = {name: _generate_orientations(shape) for name, shape in BASE_SHAPES.items()}


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation["data"]
    n = len(data)
    if n == 0:
        return "No Solution"
    m = len(data[0])
    cell_count = n * m

    def idx(r, c):
        return r * m + c

    def rc(p):
        return divmod(p, m)

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def is_singleton(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    # Compress arbitrary region ids.
    reg_map = {}
    reg_grid = []
    next_id = 0
    for row in data:
        new_row = []
        for x in row:
            if x not in reg_map:
                reg_map[x] = next_id
                next_id += 1
            new_row.append(reg_map[x])
        reg_grid.append(new_row)

    R = next_id

    region_cells = [[] for _ in range(R)]
    region_sets = [set() for _ in range(R)]
    region_of_cell = [None] * cell_count

    for r in range(n):
        for c in range(m):
            p = idx(r, c)
            rid = reg_grid[r][c]
            region_cells[rid].append(p)
            region_sets[rid].add((r, c))
            region_of_cell[p] = rid

    # Region adjacency.
    region_adj = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = reg_grid[r][c]
            if r + 1 < n:
                b = reg_grid[r + 1][c]
                if a != b:
                    region_adj[a].add(b)
                    region_adj[b].add(a)
            if c + 1 < m:
                b = reg_grid[r][c + 1]
                if a != b:
                    region_adj[a].add(b)
                    region_adj[b].add(a)

    # Cell adjacency masks.
    neighbor_mask = [0] * cell_count
    for r in range(n):
        for c in range(m):
            p = idx(r, c)
            mask = 0
            if r > 0:
                mask |= 1 << idx(r - 1, c)
            if r + 1 < n:
                mask |= 1 << idx(r + 1, c)
            if c > 0:
                mask |= 1 << idx(r, c - 1)
            if c + 1 < m:
                mask |= 1 << idx(r, c + 1)
            neighbor_mask[p] = mask

    # 2x2 blocks.
    blocks_2x2 = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks_2x2.append((idx(r, c), idx(r, c + 1), idx(r + 1, c), idx(r + 1, c + 1)))

    # Enumerate region candidates as placements of L/I/T/S tetrominoes.
    cand_types = []
    cand_cells = []
    cand_first_cell = []
    cand_neighbor_union = []
    by_type = []
    by_cell = []
    all_masks = []

    for rid in range(R):
        cells_set = region_sets[rid]
        seen = set()
        local_types = []
        local_cells = []
        local_first = []
        local_ngh = []

        for t_name in TYPE_NAMES:
            t_idx = TYPE_INDEX[t_name]
            for orient in ORIENTATIONS[t_name]:
                h = max(r for r, c in orient) + 1
                w = max(c for r, c in orient) + 1
                for r0 in range(n - h + 1):
                    for c0 in range(m - w + 1):
                        coords = tuple(sorted((r0 + dr, c0 + dc) for dr, dc in orient))
                        if coords in seen:
                            continue
                        ok = True
                        for rr, cc in coords:
                            if (rr, cc) not in cells_set:
                                ok = False
                                break
                        if not ok:
                            continue
                        seen.add(coords)
                        cmask = 0
                        nmask = 0
                        plist = []
                        for rr, cc in coords:
                            p = idx(rr, cc)
                            plist.append(p)
                            cmask |= 1 << p
                            nmask |= neighbor_mask[p]
                        local_types.append(t_idx)
                        local_cells.append(cmask)
                        local_first.append(plist[0])
                        local_ngh.append(nmask)

