            local_by_type[local_types[i]] |= bit
            for p in iter_bits(local_cells[i]):
                local_by_cell[p] = local_by_cell.get(p, 0) | bit

        cand_types.append(local_types)
        cand_cells.append(local_cells)
        cand_first_cell.append(local_first)
        cand_neighbor_union.append(local_ngh)
        by_type.append(local_by_type)
        by_cell.append(local_by_cell)
        all_masks.append((1 << k) - 1)

