    touch_masks = []
    for i in range(R):
        per_region = []
        for ci in range(len(cand_cells[i])):
            entry = {}
            ni = cand_neighbor_union[i][ci]
            for j in region_adj[i]:
                mask = 0
                for cj in range(len(cand_cells[j])):
                    if ni & cand_cells[j][cj]:
                        mask |= 1 << cj
                if mask:
                    entry[j] = mask
            per_region.append(entry)
        touch_masks.append(per_region)

    summary_cache = [dict() for _ in range(R)]
    fail_cache = set()

    def region_summary(rid, mask):
        cached = summary_cache[rid].get(mask)
        if cached is not None:
            return cached
        union = 0
        inter = 0
        tmask = 0
        first = True
        mm = mask
        while mm:
            b = mm & -mm
            ci = b.bit_length() - 1
            union |= cand_cells[rid][ci]
            tmask |= 1 << cand_types[rid][ci]
            if first:
