                first = False
            else:
                inter &= cand_cells[rid][ci]
            mm ^= b
        summary_cache[rid][mask] = (tmask, union, inter)
        return summary_cache[rid][mask]

    def connected_components(mask):
        comps = []
        comp_of = [-1] * cell_count
        rem = mask
        while rem:
            seed = rem & -rem
            comp = 0
            frontier = seed
            rem ^= seed
            while frontier:
                b = frontier & -frontier
                frontier ^= b
                p = b.bit_length() - 1
                comp |= b
                nxt = neighbor_mask[p] & rem
                frontier |= nxt
                rem ^= nxt
            cid = len(comps)
