        # No 2x2.
        for a, b, c, d in blocks_2x2:
            full = ((shaded >> a) & 1) and ((shaded >> b) & 1) and ((shaded >> c) & 1) and ((shaded >> d) & 1)
            if full:
                return False

        return True

    def propagate(masks):
        masks = list(masks)

        while True:
            changed = False

            # Basic emptiness check.
            for rid in range(R):
                if masks[rid] == 0:
                    return None

            # Type inequality propagation:
            # remove type t from region i if any adjacent region j can only be type t.
            for i in range(R):
                mi = masks[i]
                remove = 0
                for t in range(4):
                    tm = mi & by_type[i][t]
                    if not tm:
