                break

        if solved:
            ans = build_final_answer(domains)
            if ans is not None:
                return ans
            failed.add(domains)
            return None

        # Most constrained region first.
        target = min(
            (rid for rid in range(region_count) if domains[rid] & (domains[rid] - 1)),
            key=lambda rid: (
                domains[rid].bit_count(),
                domain_type_count(rid, domains[rid]),
