        for _, _, _, i in options:
            new_domains = list(domains)
            new_domains[target] = 1 << i
            res = search(tuple(new_domains))
            if res is not None:
                return res

        failed.add(domains)
        return None

    initial_domains = tuple(all_domain_masks)
    answer = search(initial_domains)
    if answer is None:
        return "No Solution"
    return repr(answer)


