def _normalize(cells):
    min_r = min(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))


def _build_tetromino_catalog():
    bases = {
        0: [(0, 0), (1, 0), (2, 0), (2, 1)],      # L / J
        1: [(0, 0), (0, 1), (0, 2), (0, 3)],      # I
        2: [(0, 0), (0, 1), (0, 2), (1, 1)],      # T
        3: [(0, 1), (0, 2), (1, 0), (1, 1)],      # S / Z
    }
    catalog = {}
    for typ, cells in bases.items():
        seen = set()
        for reflect in (1, -1):
            for rot in range(4):
                out = []
                for r, c in cells:
                    x, y = r, c
                    if reflect == -1:
                        y = -y
                    for _ in range(rot):
                        x, y = y, -x
                    out.append((x, y))
                key = _normalize(out)
                if key not in seen:
                    seen.add(key)
                    catalog[key] = typ
    return catalog


TETROMINO_CATALOG = _build_tetromino_catalog()


def _iter_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit.bit_length() - 1
        mask ^= bit


def _single_bit_index(mask):
    return mask.bit_length() - 1


