    if not mask:
        return False
    start = mask & -mask
    seen = 0
    stack = [start.bit_length() - 1]
    while stack:
        idx = stack.pop()
        b = 1 << idx
        if seen & b:
            continue
        seen |= b
        nbrs = adj_bits[idx] & mask & ~seen
        for j in _iter_bits(nbrs):
            stack.append(j)
    return seen == mask


