    def domain_info(rr, dom):
        cache = info_cache[rr]
        got = cache.get(dom)
        if got is not None:
            return got
        union = 0
        inter = None
        types = 0
        x = dom
        while x:
            b = x & -x
            i = b.bit_length() - 1
            mask, t = placements[rr][i]
            union |= mask
            inter = mask if inter is None else (inter & mask)
            types |= 1 << t
            x ^= b
        if inter is None:
            inter = 0
        got = (union, inter, types)
        cache[dom] = got
        return got

    def bit_component(start_bit, allowed_mask):
        seen = 0
        front = start_bit
        while front:
            seen |= front
            nbr = 0
            x = front
            while x:
                b = x & -x
                k = b.bit_length() - 1
                nbr |= adj_bits[k]
                x ^= b
            front = nbr & allowed_mask & ~seen
        return seen

    def edge_possible(a, b, da, db):
        x = da
        while x:
            lb = x & -x
            i = lb.bit_length() - 1
            if contact_support[a][i].get(b, 0) & db:
                return True
            x ^= lb
        return False

    def propagate(domains):
        domains = list(domains)

        while True:
            changed = False

            # Empty-domain check.
            for rr in range(R):
                if domains[rr] == 0:
                    return None

            # Same-type pruning on adjacent regions.
            type_sets = [domain_info(rr, domains[rr])[2] for rr in range(R)]
            for a in range(R):
                ts = type_sets[a]
                if ts and (ts & (ts - 1)) == 0:
                    forced_t = _single_index(ts)
                    for b in neighbors[a]:
                        nd = domains[b] & ~type_bits[b][forced_t]
                        if nd != domains[b]:
                            domains[b] = nd
