            # Each candidate must still be able to touch at least one neighbor.
            if R > 1:
                for rr in range(R):
                    d = domains[rr]
                    nd = d
                    x = d
                    while x:
                        lb = x & -x
                        i = lb.bit_length() - 1
                        ok = False
                        for nb in neighbors[rr]:
