                            poss_graph[b].add(a)

                if any(len(poss_graph[rr]) == 0 for rr in range(R)):
                    return None

                seen = {0}
                stack = [0]
                while stack:
                    x = stack.pop()
                    for y in poss_graph[x]:
                        if y not in seen:
                            seen.add(y)
                            stack.append(y)
                if len(seen) != R:
                    return None

                # If already-fixed islands cannot ever connect outward, fail.
                singles = [rr for rr in range(R) if domains[rr] and (domains[rr] & (domains[rr] - 1)) == 0]
                if singles and len(singles) < R:
                    fixed_graph = {rr: set() for rr in singles}
                    single_idx = {rr: _single_index(domains[rr]) for rr in singles}
                    single_set = set(singles)
                    for a in singles:
                        ia = single_idx[a]
                        for b in neighbors[a]:
                            if b in single_set and b > a:
                                ib = single_idx[b]
                                if contact_support[a][ia].get(b, 0) & (1 << ib):
                                    fixed_graph[a].add(b)
                                    fixed_graph[b].add(a)

                    seen_fixed = set()
                    for s in singles:
                        if s in seen_fixed:
                            continue
                        comp = []
                        stack = [s]
                        seen_fixed.add(s)
                        while stack:
                            x = stack.pop()
                            comp.append(x)
                            for y in fixed_graph[x]:
                                if y not in seen_fixed:
                                    seen_fixed.add(y)
                                    stack.append(y)

                        comp_set = set(comp)
                        has_out = False
                        for a in comp:
                            ia = single_idx[a]
                            for b in neighbors[a]:
                                if b not in comp_set and (contact_support[a][ia].get(b, 0) & domains[b]):
                                    has_out = True
                                    break
                            if has_out:
                                break
                        if not has_out:
                            return None

            if not changed:
                return tuple(domains)

    # Exact final verification.
    def verify_and_format(domains):
        chosen_masks = [0] * R
        chosen_types = [0] * R
        black = 0

        for rr in range(R):
            d = domains[rr]
            if d == 0 or (d & (d - 1)) != 0:
                return None
            i = _single_index(d)
            mask, t = placements[rr][i]
            chosen_masks[rr] = mask
            chosen_types[rr] = t
            black |= mask

        # Adjacent regions cannot share tetromino type.
        for a in range(R):
            ta = chosen_types[a]
            for b in neighbors[a]:
                if b > a and ta == chosen_types[b]:
                    return None

        # No 2x2 fully shaded.
        for bm in block_masks:
            if (black & bm) == bm:
                return None

        # All shaded cells connected.
        if black == 0:
            return None
        start = black & -black
        comp = bit_component(start, black)
        if comp != black:
            return None

        ans = [[None for _ in range(m)] for _ in range(n)]
        for rr in range(R):
            letter = TYPE_LETTERS[chosen_types[rr]]
            mm = chosen_masks[rr]
            while mm:
                b = mm & -mm
                k = b.bit_length() - 1
                ans[k // m][k % m] = letter
                mm ^= b
        return repr(ans)

    # Search.
    all_domains = tuple((1 << len(placements[rr])) - 1 for rr in range(R))
    failed = set()

    def candidate_score(rr, i, domains):
        # Prefer choices that keep many touch options (helps connectivity)
        # and don't immediately starve neighbors.
        touch_regions = 0
        touch_count = 0
        for nb in neighbors[rr]:
            sup = contact_support[rr][i].get(nb, 0) & domains[nb]
            if sup:
                touch_regions += 1
                touch_count += sup.bit_count()
        _, t = placements[rr][i]
        return (touch_regions, touch_count, -t)

    def choose_region(domains):
        best = None
        best_key = None
        for rr in range(R):
            d = domains[rr]
            cnt = d.bit_count()
            if cnt <= 1:
                continue
            _, _, ts = domain_info(rr, d)
            key = (cnt, ts.bit_count(), -len(neighbors[rr]), -len(region_cells[rr]))
            if best_key is None or key < best_key:
                best_key = key
                best = rr
        return best

    def dfs(domains):
        pd = propagate(domains)
        if pd is None:
            return None
        if pd in failed:
            return None

        done = True
        for d in pd:
            if d & (d - 1):
                done = False
                break
        if done:
            out = verify_and_format(pd)
            if out is not None:
                return out
            failed.add(pd)
            return None

        rr = choose_region(pd)
        if rr is None:
            failed.add(pd)
            return None

        options = list(_iter_bits(pd[rr]))
        options.sort(key=lambda i: candidate_score(rr, i, pd), reverse=True)

        for i in options:
            new_domains = list(pd)
            new_domains[rr] = 1 << i
            res = dfs(tuple(new_domains))
            if res is not None:
                return res

        failed.add(pd)
        return None

    result = dfs(all_domains)
    return result if result is not None else "No Solution"


