OBSERVATION = {'data': [[None, None, None, 'W', None, None], [None, 'B', None, None, 'W', None], [None, 'W', None, None, None, None], [None, None, None, None, 'W', 'B'], ['W', 'B', 'W', None, None, 'W'], [None, None, None, None, None, None]]}

# General Masyu-on-dots solver:
# - vertices are grid dots
# - edges are unit segments between orthogonally adjacent dots
# - every used vertex has degree 2; unused non-clue vertices have degree 0
# - white clues are straight and must have a turn immediately before or after
# - black clues are turns and both neighboring vertices on the loop must be straight

U, R, D, L = 0, 1, 2, 3
OPP = (D, L, U, R)
DIRBIT = (1 << U, 1 << R, 1 << D, 1 << L)

PID_EMPTY, PID_UD, PID_LR, PID_UR, PID_RD, PID_DL, PID_LU = range(7)

PAT_DIR_MASKS = (
    0,
    DIRBIT[U] | DIRBIT[D],  # UD
    DIRBIT[L] | DIRBIT[R],  # LR
    DIRBIT[U] | DIRBIT[R],  # UR
    DIRBIT[R] | DIRBIT[D],  # RD
    DIRBIT[D] | DIRBIT[L],  # DL
    DIRBIT[L] | DIRBIT[U],  # LU
)

TURN_PIDS = (PID_UR, PID_RD, PID_DL, PID_LU)
STRAIGHT_PIDS = (PID_UD, PID_LR)

BIT_PID = tuple(1 << i for i in range(7))
ALL_DOM = (1 << 7) - 1
BIT_EMPTY = BIT_PID[PID_EMPTY]
NONEMPTY_DOM = ALL_DOM ^ BIT_EMPTY

DIR_INCLUDE_DOM = tuple(
    sum(BIT_PID[pid] for pid in range(7) if PAT_DIR_MASKS[pid] & DIRBIT[d])
    for d in range(4)
)
DIR_EXCLUDE_DOM = tuple(ALL_DOM ^ m for m in DIR_INCLUDE_DOM)

TURN_WITH_EDGE = tuple(
    sum(BIT_PID[pid] for pid in TURN_PIDS if PAT_DIR_MASKS[pid] & DIRBIT[d])
    for d in range(4)
)

BLACK_REQ = {
    PID_UR: ((U, PID_UD), (R, PID_LR)),
    PID_RD: ((R, PID_LR), (D, PID_UD)),
    PID_DL: ((D, PID_UD), (L, PID_LR)),
    PID_LU: ((L, PID_LR), (U, PID_UD)),
}


def iter_pids(dom):
    while dom:
        b = dom & -dom
        yield b.bit_length() - 1
        dom ^= b


def is_singleton(dom):
    return dom != 0 and (dom & (dom - 1)) == 0


def singleton_pid(dom):
    return dom.bit_length() - 1


def restrict_domain(domains, v, mask):
    nd = domains[v] & mask
    if nd == 0:
        return -1
    if nd != domains[v]:
        domains[v] = nd
        return 1
    return 0


def revise_vertex(v, domains, model):
    clues = model["clues"]
    neighbors = model["neighbors"]

    clue = clues[v]
    neigh = neighbors[v]
    dom = domains[v]
    new_dom = 0

    for pid in iter_pids(dom):
        pm = PAT_DIR_MASKS[pid]
        ok = True

        # Arc consistency on every incident edge.
        for d in (U, R, D, L):
            n = neigh[d]
            if pm & DIRBIT[d]:
                if n == -1 or not (domains[n] & DIR_INCLUDE_DOM[OPP[d]]):
                    ok = False
                    break
            else:
                if n != -1 and not (domains[n] & DIR_EXCLUDE_DOM[OPP[d]]):
                    ok = False
                    break
        if not ok:
            continue

        # Higher-order clue rules.
        if clue == "W":
            if pid == PID_LR:
                nL, nR = neigh[L], neigh[R]
                if nL == -1 or nR == -1:
                    continue
                if not ((domains[nL] & TURN_WITH_EDGE[R]) or (domains[nR] & TURN_WITH_EDGE[L])):
                    continue
            elif pid == PID_UD:
                nU, nD = neigh[U], neigh[D]
                if nU == -1 or nD == -1:
                    continue
                if not ((domains[nU] & TURN_WITH_EDGE[D]) or (domains[nD] & TURN_WITH_EDGE[U])):
                    continue
            else:
                continue

        elif clue == "B":
            if pid not in BLACK_REQ:
                continue
            for d, req_pid in BLACK_REQ[pid]:
                n = neigh[d]
                if n == -1 or not (domains[n] & BIT_PID[req_pid]):
                    ok = False
                    break
            if not ok:
                continue

        new_dom |= BIT_PID[pid]

    return new_dom


def required_connected(domains, model):
    V = model["V"]
    clues = model["clues"]
    neighbors = model["neighbors"]

    required = [v for v in range(V) if clues[v] is not None or (domains[v] & BIT_EMPTY) == 0]
    if not required:
        return True

    can_be_used = [(domains[v] & NONEMPTY_DOM) != 0 for v in range(V)]
    start = required[0]
    if not can_be_used[start]:
        return False

    seen = [False] * V
    stack = [start]
    seen[start] = True

    while stack:
        v = stack.pop()
        for d in (U, R, D, L):
            n = neighbors[v][d]
            if n == -1 or seen[n] or not can_be_used[n]:
                continue
            if (domains[v] & DIR_INCLUDE_DOM[d]) and (domains[n] & DIR_INCLUDE_DOM[OPP[d]]):
                seen[n] = True
                stack.append(n)

    return all(seen[v] for v in required)


def sealed_cycle_component(domains, model):
    V = model["V"]
    clues = model["clues"]
    neighbors = model["neighbors"]

    forced_adj = [[] for _ in range(V)]

    # Forced edge = every remaining pattern at both ends contains that edge.
    for v in range(V):
        for d in (R, D):
            n = neighbors[v][d]
            if n == -1:
                continue
            if (domains[v] & DIR_EXCLUDE_DOM[d]) == 0 and (domains[n] & DIR_EXCLUDE_DOM[OPP[d]]) == 0:
                forced_adj[v].append(n)
                forced_adj[n].append(v)

    forced_deg = [len(forced_adj[v]) for v in range(V)]
    seen = [False] * V
    sealed = None

    for v in range(V):
        if forced_deg[v] == 0 or seen[v]:
            continue
        stack = [v]
        seen[v] = True
        comp = []
        while stack:
            x = stack.pop()
            comp.append(x)
            for y in forced_adj[x]:
                if not seen[y]:
                    seen[y] = True
                    stack.append(y)
        if all(forced_deg[x] == 2 for x in comp):
            comp_set = set(comp)
            if sealed is not None:
                return False
            sealed = comp_set

    if sealed is not None:
        for v in range(V):
            required = clues[v] is not None or (domains[v] & BIT_EMPTY) == 0
            if required and v not in sealed:
                return False

    return sealed


def global_propagate(domains, model):
    if not required_connected(domains, model):
        return None

    sealed = sealed_cycle_component(domains, model)
    if sealed is False:
        return None

    changed = False

    # If a full cycle is already sealed, everything else must be empty.
    if sealed is not None:
        for v in range(model["V"]):
            if v not in sealed:
                res = restrict_domain(domains, v, BIT_EMPTY)
                if res < 0:
                    return None
                if res > 0:
                    changed = True

    return changed


def propagate(domains, model):
    clues = model["clues"]
    neighbors = model["neighbors"]
    clue_vertices = model["clue_vertices"]
    scan_order = model["scan_order"]

    while True:
        changed = False

        # Main local consistency loop.
        for v in scan_order:
            nd = revise_vertex(v, domains, model)
            if nd == 0:
                return None
            if nd != domains[v]:
                domains[v] = nd
                changed = True

        # Explicit human-style clue deductions.
        for v in clue_vertices:
            clue = clues[v]
            dom = domains[v]

            if clue == "W":
                if dom == BIT_PID[PID_LR]:
                    nL, nR = neighbors[v][L], neighbors[v][R]
                    if nL == -1 or nR == -1:
                        return None

                    left_turn = domains[nL] & TURN_WITH_EDGE[R]
                    right_turn = domains[nR] & TURN_WITH_EDGE[L]

                    if not left_turn and not right_turn:
                        return None
                    if not left_turn:
                        res = restrict_domain(domains, nR, TURN_WITH_EDGE[L])
                        if res < 0:
                            return None
                        if res > 0:
                            changed = True
                    if not right_turn:
                        res = restrict_domain(domains, nL, TURN_WITH_EDGE[R])
                        if res < 0:
                            return None
                        if res > 0:
                            changed = True

                elif dom == BIT_PID[PID_UD]:
                    nU, nD = neighbors[v][U], neighbors[v][D]
                    if nU == -1 or nD == -1:
                        return None

                    up_turn = domains[nU] & TURN_WITH_EDGE[D]
                    down_turn = domains[nD] & TURN_WITH_EDGE[U]

                    if not up_turn and not down_turn:
                        return None
                    if not up_turn:
                        res = restrict_domain(domains, nD, TURN_WITH_EDGE[U])
                        if res < 0:
                            return None
                        if res > 0:
                            changed = True
                    if not down_turn:
                        res = restrict_domain(domains, nU, TURN_WITH_EDGE[D])
                        if res < 0:
                            return None
                        if res > 0:
                            changed = True

            elif clue == "B":
                # If every remaining black-corner option shares one arm,
                # the adjacent vertex on that arm must be the corresponding straight.
                for d in (U, R, D, L):
                    if (dom & DIR_EXCLUDE_DOM[d]) == 0:
                        n = neighbors[v][d]
                        if n == -1:
                            return None
                        req = PID_UD if d in (U, D) else PID_LR
                        res = restrict_domain(domains, n, BIT_PID[req])
                        if res < 0:
                            return None
                        if res > 0:
                            changed = True

        g = global_propagate(domains, model)
        if g is None:
            return None
        if g:
            changed = True

        if not changed:
            return domains


def pattern_support_score(v, pid, domains, model):
    neighbors = model["neighbors"]
    clues = model["clues"]

    pm = PAT_DIR_MASKS[pid]
    neigh = neighbors[v]
    score = 0

    for d in (U, R, D, L):
        n = neigh[d]
        if n == -1:
            continue
        if pm & DIRBIT[d]:
            score += (domains[n] & DIR_INCLUDE_DOM[OPP[d]]).bit_count()
        else:
            score += (domains[n] & DIR_EXCLUDE_DOM[OPP[d]]).bit_count()

    clue = clues[v]
    if clue == "W":
        if pid == PID_LR:
            nL, nR = neigh[L], neigh[R]
            if nL != -1:
                score += (domains[nL] & TURN_WITH_EDGE[R]).bit_count()
            if nR != -1:
                score += (domains[nR] & TURN_WITH_EDGE[L]).bit_count()
        elif pid == PID_UD:
            nU, nD = neigh[U], neigh[D]
            if nU != -1:
                score += (domains[nU] & TURN_WITH_EDGE[D]).bit_count()
            if nD != -1:
                score += (domains[nD] & TURN_WITH_EDGE[U]).bit_count()

    elif clue == "B":
        for d, req in BLACK_REQ.get(pid, ()):
            n = neigh[d]
            if n != -1:
                score += (domains[n] & BIT_PID[req]).bit_count()

    return score


def choose_var(domains, model):
    clues = model["clues"]
    impact = model["impact"]

    best_v = None
    best_key = None

    for v, dom in enumerate(domains):
        if is_singleton(dom):
            continue

        if clues[v] is not None:
            pri = 0
        elif (dom & BIT_EMPTY) == 0:
            pri = 1
        else:
            pri = 2

        key = (pri, dom.bit_count(), -impact[v])

        if best_key is None or key < best_key:
            best_key = key
            best_v = v

    return best_v


def ordered_pids(v, dom, domains, model):
    clue = model["clues"][v]
    pids = list(iter_pids(dom))

    if clue is None:
        pids.sort(key=lambda pid: (0 if pid == PID_EMPTY else 1, pattern_support_score(v, pid, domains, model)))
    else:
        pids.sort(key=lambda pid: pattern_support_score(v, pid, domains, model))

    return pids


def build_path(domains, model):
    V = model["V"]
    coords = model["coords"]
    clues = model["clues"]
    neighbors = model["neighbors"]

    pids = []
    for dom in domains:
        if not is_singleton(dom):
            return None
        pids.append(singleton_pid(dom))

    adj = [[] for _ in range(V)]
    used = []

    # Build selected edge graph.
    for v, pid in enumerate(pids):
        if pid == PID_EMPTY:
            if clues[v] is not None:
                return None
            continue

        used.append(v)
        pm = PAT_DIR_MASKS[pid]

        for d in (R, D):
            if pm & DIRBIT[d]:
                n = neighbors[v][d]
                if n == -1:
                    return None
                npid = pids[n]
                if not (PAT_DIR_MASKS[npid] & DIRBIT[OPP[d]]):
                    return None
                adj[v].append(n)
                adj[n].append(v)

    if not used:
        return None

    # Degree check.
    for v, pid in enumerate(pids):
        deg = len(adj[v])
        if pid == PID_EMPTY:
            if deg != 0:
                return None
        else:
            if deg != 2:
                return None

    # Final exact clue verification.
    for v, clue in enumerate(clues):
        if clue == "W":
            pid = pids[v]
            if pid not in STRAIGHT_PIDS:
                return None
            if pid == PID_LR:
                nL, nR = neighbors[v][L], neighbors[v][R]
                if nL == -1 or nR == -1:
                    return None
                left_turn = pids[nL] in TURN_PIDS and (PAT_DIR_MASKS[pids[nL]] & DIRBIT[R])
                right_turn = pids[nR] in TURN_PIDS and (PAT_DIR_MASKS[pids[nR]] & DIRBIT[L])
                if not (left_turn or right_turn):
                    return None
            else:
                nU, nD = neighbors[v][U], neighbors[v][D]
                if nU == -1 or nD == -1:
                    return None
                up_turn = pids[nU] in TURN_PIDS and (PAT_DIR_MASKS[pids[nU]] & DIRBIT[D])
                down_turn = pids[nD] in TURN_PIDS and (PAT_DIR_MASKS[pids[nD]] & DIRBIT[U])
                if not (up_turn or down_turn):
                    return None

        elif clue == "B":
            pid = pids[v]
            if pid not in TURN_PIDS:
                return None
            for d, req in BLACK_REQ[pid]:
