    # Single connected cycle.
    start = used[0]
    seen = {start}
    stack = [start]
    while stack:
        v = stack.pop()
        for n in adj[v]:
            if n not in seen:
                seen.add(n)
                stack.append(n)
    if len(seen) != len(used):
        return None

    # Output ordered closed loop.
    start = min(used, key=lambda x: coords[x])
