            if r > 0:
                neighbors[v][U] = idx(r - 1, c)
            if c < N - 1:
                neighbors[v][R] = idx(r, c + 1)
            if r < N - 1:
                neighbors[v][D] = idx(r + 1, c)
            if c > 0:
                neighbors[v][L] = idx(r, c - 1)

    init_domains = []
    for v in range(V):
