        range(V),
        key=lambda v: (0 if clues[v] == "B" else 1 if clues[v] == "W" else 2, -impact[v]),
    )

    model = {
        "N": N,
        "V": V,
        "coords": coords,
        "clues": clues,
        "neighbors": neighbors,
        "clue_vertices": clue_vertices,
        "impact": impact,
        "scan_order": scan_order,
    }

    domains = propagate(init_domains[:], model)
    if domains is None:
        return "No Solution"

    fail_cache = set()

    def search(curr_domains):
        key = tuple(curr_domains)
        if key in fail_cache:
            return None

        v = choose_var(curr_domains, model)
        if v is None:
            return curr_domains if build_path(curr_domains, model) is not None else None

        dom = curr_domains[v]
