# General Masyu-on-dots solver:
# - vertices are grid dots
# - edges are unit segments between orthogonally adjacent dots
# - every used vertex has degree 2; unused non-clue vertices have degree 0
# - white clues are straight and must have a turn immediately before or after
# - black clues are turns and both neighboring vertices on the loop must be straight

U, R, D, L = 0, 1, 2, 3
OPP = (D, L, U, R)
DIRBIT = (1 << U, 1 << R, 1 << D, 1 << L)

PID_EMPTY, PID_UD, PID_LR, PID_UR, PID_RD, PID_DL, PID_LU = range(7)

PAT_DIR_MASKS = (
    0,
    DIRBIT[U] | DIRBIT[D],  # UD
    DIRBIT[L] | DIRBIT[R],  # LR
    DIRBIT[U] | DIRBIT[R],  # UR
    DIRBIT[R] | DIRBIT[D],  # RD
    DIRBIT[D] | DIRBIT[L],  # DL
    DIRBIT[L] | DIRBIT[U],  # LU
)

TURN_PIDS = (PID_UR, PID_RD, PID_DL, PID_LU)
STRAIGHT_PIDS = (PID_UD, PID_LR)

BIT_PID = tuple(1 << i for i in range(7))
ALL_DOM = (1 << 7) - 1
BIT_EMPTY = BIT_PID[PID_EMPTY]
NONEMPTY_DOM = ALL_DOM ^ BIT_EMPTY

DIR_INCLUDE_DOM = tuple(
    sum(BIT_PID[pid] for pid in range(7) if PAT_DIR_MASKS[pid] & DIRBIT[d])
    for d in range(4)
)
DIR_EXCLUDE_DOM = tuple(ALL_DOM ^ m for m in DIR_INCLUDE_DOM)

TURN_WITH_EDGE = tuple(
    sum(BIT_PID[pid] for pid in TURN_PIDS if PAT_DIR_MASKS[pid] & DIRBIT[d])
    for d in range(4)
)

BLACK_REQ = {
    PID_UR: ((U, PID_UD), (R, PID_LR)),
    PID_RD: ((R, PID_LR), (D, PID_UD)),
    PID_DL: ((D, PID_UD), (L, PID_LR)),
    PID_LU: ((L, PID_LR), (U, PID_UD)),
}


def iter_pids(dom):
    while dom:
        b = dom & -dom
        yield b.bit_length() - 1
        dom ^= b


def is_singleton(dom):
    return dom != 0 and (dom & (dom - 1)) == 0


