class MasyuSolver:
    def __init__(self, observation):
        self.valid = True
        data = observation.get("data")
        if not isinstance(data, list) or not data:
            self.valid = False
            return

        self.N = len(data)
        if any(not isinstance(row, list) or len(row) != self.N for row in data):
            self.valid = False
            return

        self.V = self.N * self.N
        self.coords = []
        self.clues = []
        self.neighbors = []
        self.deg = []
        self.adj_clue_count = []

        for r in range(self.N):
            for c in range(self.N):
                clue = data[r][c]
                if clue not in (None, "W", "B"):
                    self.valid = False
                    return
                self.coords.append((r, c))
                self.clues.append(clue)

        for r in range(self.N):
            for c in range(self.N):
                neigh = []
                for dr, dc in [(-1, 0), (0, 1), (1, 0), (0, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < self.N and 0 <= nc < self.N:
                        neigh.append(nr * self.N + nc)
                    else:
                        neigh.append(-1)
                self.neighbors.append(tuple(neigh))
                self.deg.append(sum(1 for x in neigh if x != -1))

        for idx in range(self.V):
            count = 0
            for nb in self.neighbors[idx]:
                if nb != -1 and self.clues[nb] is not None:
                    count += 1
            self.adj_clue_count.append(count)

        self.affected = []
        for idx in range(self.V):
            s = {idx}
            for nb in self.neighbors[idx]:
                if nb != -1:
                    s.add(nb)
                    for nb2 in self.neighbors[nb]:
                        if nb2 != -1:
                            s.add(nb2)
            self.affected.append(tuple(s))

        self.initial_domains = []
        for idx, (r, c) in enumerate(self.coords):
            fits = 0
            for p in range(7):
                m = MASKS[p]
                if (m & SIDE_BIT[U]) and r == 0:
                    continue
                if (m & SIDE_BIT[D]) and r == self.N - 1:
                    continue
                if (m & SIDE_BIT[L]) and c == 0:
                    continue
                if (m & SIDE_BIT[R]) and c == self.N - 1:
                    continue
                fits |= BIT[p]

            clue = self.clues[idx]
            if clue is None:
                dom = fits
            elif clue == "W":
                dom = fits & (BIT[HOR] | BIT[VER])
            else:
                dom = fits & (BIT[UR] | BIT[RD] | BIT[DL] | BIT[LU])

            if dom == 0:
                self.valid = False
                return
            self.initial_domains.append(dom)

        self.fail_memo = set()

    def center_supported(self, idx, pid, domains, overrides=None):
        neigh = self.neighbors[idx]

        for s in range(4):
            nb = neigh[s]
            if nb == -1:
                if USES[pid][s]:
                    return False
                continue

            nb_dom = overrides[s] if overrides and s in overrides else domains[nb]
            if USES[pid][s]:
                if (nb_dom & USING_DOM[OPP[s]]) == 0:
                    return False
            else:
                if (nb_dom & NOT_USING_DOM[OPP[s]]) == 0:
                    return False

        clue = self.clues[idx]
        if clue == "W":
            if pid == HOR:
                left_dom = overrides[L] if overrides and L in overrides else domains[neigh[L]]
                right_dom = overrides[R] if overrides and R in overrides else domains[neigh[R]]
                if (left_dom & TURN_USING_DOM[R]) == 0 and (right_dom & TURN_USING_DOM[L]) == 0:
                    return False
            elif pid == VER:
                up_dom = overrides[U] if overrides and U in overrides else domains[neigh[U]]
                down_dom = overrides[D] if overrides and D in overrides else domains[neigh[D]]
                if (up_dom & TURN_USING_DOM[D]) == 0 and (down_dom & TURN_USING_DOM[U]) == 0:
                    return False
            else:
                return False

        elif clue == "B":
