                        return False
                    nb_dom = overrides[s] if overrides and s in overrides else domains[nb]
                    if (nb_dom & BIT[REQ_STRAIGHT[s]]) == 0:
                        return False

        return True

    def pattern_supported(self, idx, pid, domains):
