                    break
            if not ok:
                return False

        return True

    def edge_may(self, v, s, may_masks):
        w = self.neighbors[v][s]
        if w == -1:
            return False
        return bool((may_masks[v] & SIDE_BIT[s]) and (may_masks[w] & SIDE_BIT[OPP[s]]))

    def edge_forced(self, v, s, must_masks):
        w = self.neighbors[v][s]
        if w == -1:
            return False
        return bool((must_masks[v] & SIDE_BIT[s]) and (must_masks[w] & SIDE_BIT[OPP[s]]))

    def global_possible(self, domains):
        may_masks = [DOM_MAY_MASK[d] for d in domains]
        must_masks = [DOM_MUST_MASK[d] for d in domains]
        forced_used = [not (domains[i] & BIT[NONE]) for i in range(self.V)]

        comp = [-1] * self.V
        forced_components = 0
        cid = 0
        for i in range(self.V):
            if comp[i] != -1 or may_masks[i] == 0:
                continue
            dq = [i]
            comp[i] = cid
            has_forced = forced_used[i]
            while dq:
                v = dq.pop()
                for s in range(4):
                    if not self.edge_may(v, s, may_masks):
                        continue
                    w = self.neighbors[v][s]
                    if comp[w] == -1:
                        comp[w] = cid
                        if forced_used[w]:
