        forced_adj = [[] for _ in range(self.V)]
        for v in range(self.V):
            for s in (R, D):
                w = self.neighbors[v][s]
                if w != -1 and self.edge_forced(v, s, must_masks):
                    forced_deg[v] += 1
                    forced_deg[w] += 1
                    forced_adj[v].append(w)
                    forced_adj[w].append(v)

