        for i in range(self.V):
            if seen[i] or forced_deg[i] == 0:
                continue
            stack = [i]
            comp_vertices = []
            seen[i] = True
            while stack:
                v = stack.pop()
                comp_vertices.append(v)
                for w in forced_adj[v]:
                    if not seen[w]:
                        seen[w] = True
                        stack.append(w)

            if all(forced_deg[v] == 2 for v in comp_vertices):
                comp_set = set(comp_vertices)
                closed = True
                for v in comp_vertices:
                    for s in range(4):
                        if self.edge_may(v, s, may_masks):
                            w = self.neighbors[v][s]
                            if w not in comp_set:
                                closed = False
                                break
                    if not closed:
                        break
                if closed:
                    for v in range(self.V):
                        if v not in comp_set and forced_used[v]:
                            return False

        return True

    def propagate(self, domains):
        q = deque(range(self.V))
        in_q = [True] * self.V

        while q:
            idx = q.popleft()
            in_q[idx] = False

            old_dom = domains[idx]
            new_dom = 0
            for p in bit_iter(old_dom):
                if self.pattern_supported(idx, p, domains):
                    new_dom |= BIT[p]

            if new_dom == 0:
                return None

            if new_dom != old_dom:
                domains[idx] = new_dom
                if not self.global_possible(domains):
                    return None
                for a in self.affected[idx]:
                    if not in_q[a]:
                        q.append(a)
                        in_q[a] = True

        if not self.global_possible(domains):
            return None
        return domains

    def choose_var(self, domains):
        best = None
        best_key = None
        for idx, dom in enumerate(domains):
            sz = DOM_SIZE[dom]
            if sz <= 1:
                continue
            forced = 0 if not (dom & BIT[NONE]) else 1
            clue = 0 if self.clues[idx] is not None else 1
            key = (forced, sz, clue, -self.adj_clue_count[idx], -self.deg[idx])
            if best_key is None or key < best_key:
                best_key = key
                best = idx
        return best

    def order_values(self, idx, domains):
        opts = list(bit_iter(domains[idx]))

        def score(pid):
            total = 0
            if not self.center_supported(idx, pid, domains):
                return 10**9
            for s in range(4):
                nb = self.neighbors[idx][s]
                if nb == -1:
                    continue
                cnt = 0
                for q in bit_iter(domains[nb]):
                    if USES[q][OPP[s]] != USES[pid][s]:
                        continue
                    if self.center_supported(nb, q, domains, overrides={OPP[s]: BIT[pid]}):
                        cnt += 1
                total += cnt
            return total

        opts.sort(key=lambda p: (score(p), 0 if p != NONE else 1))
        return opts

    def final_path(self, domains):
        pids = [singleton_pid(d) for d in domains]

        for idx, pid in enumerate(pids):
            if not self.center_supported(idx, pid, domains):
                return None
            for s in range(4):
                nb = self.neighbors[idx][s]
                if nb == -1:
                    if USES[pid][s]:
                        return None
                else:
                    if USES[pid][s] != USES[pids[nb]][OPP[s]]:
                        return None

        adj = [[] for _ in range(self.V)]
        used_vertices = []

        for idx, pid in enumerate(pids):
            if pid == NONE:
                continue
            for s in range(4):
                if USES[pid][s]:
                    nb = self.neighbors[idx][s]
                    if nb == -1:
                        return None
                    adj[idx].append(nb)
            if len(adj[idx]) != 2:
                return None
            used_vertices.append(idx)

        if not used_vertices:
            return None

        start = min(used_vertices)
        seen = set([start])
        stack = [start]
        while stack:
            v = stack.pop()
            for w in adj[v]:
                if w not in seen:
                    seen.add(w)
                    stack.append(w)

        if len(seen) != len(used_vertices):
            return None

        n0, n1 = sorted(adj[start])
        path = [self.coords[start], self.coords[n0]]
        prev, cur = start, n0

        while cur != start:
            a, b = adj[cur]
            nxt = a if b == prev else b
            prev, cur = cur, nxt
            path.append(self.coords[cur])
            if len(path) > len(used_vertices) + 1:
                return None

        if len(path) != len(used_vertices) + 1:
            return None

        return path

    def search(self, domains):
        domains = self.propagate(domains)
        if domains is None:
            return None

        key = tuple(domains)
        if key in self.fail_memo:
            return None

        if all(DOM_SIZE[d] == 1 for d in domains):
            path = self.final_path(domains)
            if path is None:
                self.fail_memo.add(key)
                return None
            return repr(path)

        idx = self.choose_var(domains)
        if idx is None:
            self.fail_memo.add(key)
            return None

        for pid in self.order_values(idx, domains):
            new_domains = domains.copy()
            new_domains[idx] = BIT[pid]
            ans = self.search(new_domains)
            if ans is not None:
                return ans

        self.fail_memo.add(key)
        return None

    def run(self):
        return self.search(self.initial_domains.copy())


def solve(observation):
    solver = MasyuSolver(observation)
    if not solver.valid:
        return "No Solution"
    ans = solver.run()
    return ans if ans is not None else "No Solution"


