        for i in range(self.V):
            if seen[i] or forced_deg[i] == 0:
                continue
            stack = [i]
            comp_vertices = []
            seen[i] = True
            while stack:
                v = stack.pop()
                comp_vertices.append(v)
                for w in forced_adj[v]:
                    if not seen[w]:
                        seen[w] = True
                        stack.append(w)

