    OPP = (D, L, U, R)
    DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    DIR_BIT = [1 << d for d in range(4)]

    # Pattern indices.
    P_EMPTY = 0
    P_H = 1
    P_V = 2
    P_UR = 3
    P_UL = 4
    P_DR = 5
    P_DL = 6

    PATTERN_EDGEBITS = [
