    TURN_MASK_BY_NEIGHBOR_DIR = [
        (1 << P_DR) | (1 << P_DL),  # neighbor above, must use D and turn
        (1 << P_UL) | (1 << P_DL),  # neighbor right, must use L and turn
        (1 << P_UR) | (1 << P_UL),  # neighbor below, must use U and turn
        (1 << P_UR) | (1 << P_DR),  # neighbor left, must use R and turn
    ]

    MASK_PATTERNS = [[] for _ in range(1 << 7)]
    POPCOUNT = [0] * (1 << 7)
    SINGLETON_PATTERN = [-1] * (1 << 7)
    for m in range(1 << 7):
        lst = []
        for p in range(7):
            if (m >> p) & 1:
                lst.append(p)
        MASK_PATTERNS[m] = lst
        POPCOUNT[m] = len(lst)
        if len(lst) == 1:
