                neighbors4[v][d] = u
                vertex_neighbors[v].append((d, u))

    edges = []
    for r in range(N):
        for c in range(N):
            v = vid(r, c)
            if c + 1 < N:
                edges.append((v, vid(r, c + 1), R))
            if r + 1 < N:
                edges.append((v, vid(r + 1, c), D))

    # Initial pattern domains from clue type and boundary legality.
    initial_domains = [0] * V
    for v, (r, c) in enumerate(rc):
        t = clue[v]
