                possible_adj[u].append(v)

            if on_possible and not off_possible:
                forced_adj[v].append(u)
                forced_adj[u].append(v)
                forced_deg[v] += 1
                forced_deg[u] += 1
                forced_edge.add((v, u))
                forced_edge.add((u, v))

        return possible_adj, forced_adj, forced_deg, forced_edge

    def global_checks(dom):
