        if comp is None:
            return False
        possible_adj, forced_adj, forced_deg, forced_edge = comp

        usable = [bool(dom[v] & NONEMPTY_MASK) for v in range(V)]
        mandatory = [v for v in range(V) if clue[v] is not None or not (dom[v] & EMPTY_BIT)]

