            if forced_deg[v] > 2:
                return False
            if dom[v] == EMPTY_BIT and forced_deg[v] != 0:
                return False

        # All mandatory vertices must still be connectable through possible loop edges.
        if mandatory:
            start = mandatory[0]
            if not usable[start]:
                return False
            seen = {start}
            dq = deque([start])
            while dq:
                x = dq.popleft()
                for y in possible_adj[x]:
                    if not usable[y] or y in seen:
                        continue
                    seen.add(y)
                    dq.append(y)
            if any(m not in seen for m in mandatory):
                return False

        # No premature closed cycle unless it already contains every forced/must-use part.
        seen = set()
        cycle_component = None
        for v in range(V):
            if forced_deg[v] == 0 or v in seen:
                continue
