                lp = singles[l]
                rp = singles[r]
                if not (((1 << lp) & TURN_MASK_BY_NEIGHBOR_DIR[L]) or ((1 << rp) & TURN_MASK_BY_NEIGHBOR_DIR[R])):
                    return None
            elif p == P_V:
                u = neighbors4[w][U]
                d = neighbors4[w][D]
                if u is None or d is None:
                    return None
                up = singles[u]
                dp = singles[d]
