                    if singles[u] != AXIS_STRAIGHT[d]:
                        return None

        used = [v for v in range(V) if adj[v]]
        if not used:
            return None

        start = min(used)
        if len(adj[start]) != 2:
            return None

        def build_with_first(first):
            path = [rc[start], rc[first]]
            visited = {start}
            prev = start
            cur = first
            while cur != start:
                if cur in visited:
                    return None
                visited.add(cur)
                if len(adj[cur]) != 2:
                    return None
                a, b = adj[cur]
                nxt = a if a != prev else b
                prev, cur = cur, nxt
                path.append(rc[cur])
            if len(visited) != len(used):
                return None
            return path

        n0, n1 = sorted(adj[start])
        p0 = build_with_first(n0)
        p1 = build_with_first(n1)
        if p0 is None and p1 is None:
            return None
        if p0 is None:
            return p1
        if p1 is None:
            return p0
        return p0 if p0 < p1 else p1

    def select_var(dom):
        best_v = None
        best_key = None
        for v in range(V):
            cnt = POPCOUNT[dom[v]]
            if cnt <= 1:
                continue
            clue_priority = 0 if clue[v] is not None else (1 if not (dom[v] & EMPTY_BIT) else 2)
            support_score = 0
            for p in MASK_PATTERNS[dom[v]]:
                for d, u in vertex_neighbors[v]:
                    support_score += POPCOUNT[support[v][d][p] & dom[u]]
            key = (cnt, clue_priority, support_score, -len(vertex_neighbors[v]))
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
        return best_v

    def order_patterns(v, dom):
        opts = []
        for p in MASK_PATTERNS[dom[v]]:
            score = 0
            for d, u in vertex_neighbors[v]:
                score += POPCOUNT[support[v][d][p] & dom[u]]
            # Try tighter patterns first.
            opts.append((score, p))
        opts.sort()
        return [p for _, p in opts]

    failed = set()

    def dfs(dom):
        dom = propagate(dom)
        if dom is None:
            return None

        key = tuple(dom)
        if key in failed:
            return None

        if all(POPCOUNT[m] == 1 for m in dom):
            path = build_final_path(dom)
            if path is not None:
                return path
            failed.add(key)
            return None

        v = select_var(dom)
        if v is None:
            failed.add(key)
            return None

        for p in order_patterns(v, dom):
            nxt = list(dom)
            nxt[v] = 1 << p
            res = dfs(nxt)
            if res is not None:
                return res

        failed.add(key)
        return None

    result = dfs(initial_domains)
    return repr(result) if result is not None else "No Solution"


