import sys
from collections import deque

def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation["data"]
    N = len(data)
    if N == 0 or any(len(row) != N for row in data):
        return "No Solution"

    # Directions.
    U, R, D, L = 0, 1, 2, 3
    OPP = (D, L, U, R)
    DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    DIR_BIT = [1 << d for d in range(4)]

    # Pattern indices.
    P_EMPTY = 0
    P_H = 1
    P_V = 2
    P_UR = 3
    P_UL = 4
    P_DR = 5
    P_DL = 6

    PATTERN_EDGEBITS = [
        0,
        DIR_BIT[L] | DIR_BIT[R],  # H
        DIR_BIT[U] | DIR_BIT[D],  # V
        DIR_BIT[U] | DIR_BIT[R],  # UR
        DIR_BIT[U] | DIR_BIT[L],  # UL
        DIR_BIT[D] | DIR_BIT[R],  # DR
        DIR_BIT[D] | DIR_BIT[L],  # DL
    ]
    USES = [[bool(PATTERN_EDGEBITS[p] & DIR_BIT[d]) for d in range(4)] for p in range(7)]

    EMPTY_BIT = 1 << P_EMPTY
    NONEMPTY_MASK = 0
    for p in range(1, 7):
        NONEMPTY_MASK |= 1 << p
    TURN_MASK_ALL = (1 << P_UR) | (1 << P_UL) | (1 << P_DR) | (1 << P_DL)

    AXIS_STRAIGHT = [P_V, P_H, P_V, P_H]

    # If white uses the edge toward direction d, these are the turning patterns
    # for the neighbor at that side.
    TURN_MASK_BY_NEIGHBOR_DIR = [
        (1 << P_DR) | (1 << P_DL),  # neighbor above, must use D and turn
        (1 << P_UL) | (1 << P_DL),  # neighbor right, must use L and turn
        (1 << P_UR) | (1 << P_UL),  # neighbor below, must use U and turn
        (1 << P_UR) | (1 << P_DR),  # neighbor left, must use R and turn
    ]

    MASK_PATTERNS = [[] for _ in range(1 << 7)]
    POPCOUNT = [0] * (1 << 7)
    SINGLETON_PATTERN = [-1] * (1 << 7)
    for m in range(1 << 7):
        lst = []
        for p in range(7):
            if (m >> p) & 1:
                lst.append(p)
        MASK_PATTERNS[m] = lst
        POPCOUNT[m] = len(lst)
        if len(lst) == 1:
            SINGLETON_PATTERN[m] = lst[0]

    V = N * N

    def vid(r, c):
        return r * N + c

    rc = [(i // N, i % N) for i in range(V)]
    clue = [data[r][c] for r in range(N) for c in range(N)]

    neighbors4 = [[None] * 4 for _ in range(V)]
    vertex_neighbors = [[] for _ in range(V)]
    for v, (r, c) in enumerate(rc):
        for d, (dr, dc) in enumerate(DIRS):
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                u = vid(nr, nc)
                neighbors4[v][d] = u
                vertex_neighbors[v].append((d, u))

    edges = []
    for r in range(N):
        for c in range(N):
            v = vid(r, c)
            if c + 1 < N:
                edges.append((v, vid(r, c + 1), R))
            if r + 1 < N:
                edges.append((v, vid(r + 1, c), D))

    # Initial pattern domains from clue type and boundary legality.
    initial_domains = [0] * V
    for v, (r, c) in enumerate(rc):
        t = clue[v]
        if t == "W":
            base = (1 << P_H) | (1 << P_V)
        elif t == "B":
            base = TURN_MASK_ALL
        else:
            base = EMPTY_BIT | NONEMPTY_MASK

        mask = 0
        for p in MASK_PATTERNS[base]:
            bits = PATTERN_EDGEBITS[p]
            if r == 0 and (bits & DIR_BIT[U]):
                continue
            if c == N - 1 and (bits & DIR_BIT[R]):
                continue
            if r == N - 1 and (bits & DIR_BIT[D]):
                continue
            if c == 0 and (bits & DIR_BIT[L]):
                continue
            mask |= 1 << p

        if mask == 0:
            return "No Solution"
        initial_domains[v] = mask

    # Pairwise supports across each adjacency.
    # This enforces edge agreement and the black-circle "neighbor must be straight" rule.
    support = [[[0] * 7 for _ in range(4)] for _ in range(V)]
    for v in range(V):
        tv = clue[v]
        for d, u in vertex_neighbors[v]:
            tu = clue[u]
            axis_pat = AXIS_STRAIGHT[d]
            arr = [0] * 7
            for p in range(7):
                use_edge = USES[p][d]
                m = 0
                for q in range(7):
                    if USES[q][OPP[d]] != use_edge:
                        continue
                    if tv == "B" and use_edge and q != axis_pat:
                        continue
                    if tu == "B" and use_edge and p != axis_pat:
                        continue
                    m |= 1 << q
                arr[p] = m
            support[v][d] = arr

    white_vertices = [v for v in range(V) if clue[v] == "W"]
    black_vertices = [v for v in range(V) if clue[v] == "B"]

    def revise_basic(v, dom):
        old = dom[v]
        new = 0
        for p in MASK_PATTERNS[old]:
            ok = True
            for d, u in vertex_neighbors[v]:
                if support[v][d][p] & dom[u] == 0:
                    ok = False
                    break
            if ok:
                new |= 1 << p
        return new

    def white_center_supported(w, p, dom):
        if p == P_H:
            a = neighbors4[w][L]
            b = neighbors4[w][R]
            if a is None or b is None:
                return False
            left_cand = support[w][L][p] & dom[a]
            if left_cand == 0:
                return False
            right_cand = support[w][R][p] & dom[b]
            if right_cand == 0:
                return False
            return bool((left_cand & TURN_MASK_BY_NEIGHBOR_DIR[L]) or (right_cand & TURN_MASK_BY_NEIGHBOR_DIR[R]))

        if p == P_V:
            a = neighbors4[w][U]
            b = neighbors4[w][D]
            if a is None or b is None:
                return False
            up_cand = support[w][U][p] & dom[a]
            if up_cand == 0:
                return False
            down_cand = support[w][D][p] & dom[b]
            if down_cand == 0:
                return False
            return bool((up_cand & TURN_MASK_BY_NEIGHBOR_DIR[U]) or (down_cand & TURN_MASK_BY_NEIGHBOR_DIR[D]))

        return False

    def white_neighbor_supported(w, d, q, dom):
        qbit = 1 << q
        od = OPP[d]
        opp = neighbors4[w][od]
        for p in MASK_PATTERNS[dom[w]]:
            if support[w][d][p] & qbit == 0:
                continue
            # If white does not use this side, pairwise compatibility is enough.
            if not USES[p][d]:
                return True
            # White uses this side: opposite side must exist and at least one of the
            # two side-neighbors must be turning.
            if opp is None:
                continue
            opp_cand = support[w][od][p] & dom[opp]
            if opp_cand == 0:
                continue
            if qbit & TURN_MASK_BY_NEIGHBOR_DIR[d]:
                return True
            if opp_cand & TURN_MASK_BY_NEIGHBOR_DIR[od]:
                return True
        return False

    def revise_white(w, dom):
        changed = False

        old_center = dom[w]
        new_center = 0
        for p in MASK_PATTERNS[old_center]:
            if white_center_supported(w, p, dom):
                new_center |= 1 << p
        if new_center == 0:
            return None
        if new_center != old_center:
            dom[w] = new_center
            changed = True

        for d in range(4):
            u = neighbors4[w][d]
            if u is None:
                continue
            old_u = dom[u]
            new_u = 0
            for q in MASK_PATTERNS[old_u]:
                if white_neighbor_supported(w, d, q, dom):
                    new_u |= 1 << q
            if new_u == 0:
                return None
            if new_u != old_u:
                dom[u] = new_u
                changed = True

        return changed

    def compute_edge_possibilities(dom):
        possible_adj = [[] for _ in range(V)]
        forced_adj = [[] for _ in range(V)]
        forced_deg = [0] * V
        forced_edge = set()

        for v, u, d in edges:
            on_possible = False
            off_possible = False
            du = dom[u]
            for p in MASK_PATTERNS[dom[v]]:
                sup = support[v][d][p] & du
                if sup == 0:
                    continue
                if USES[p][d]:
                    on_possible = True
                else:
                    off_possible = True
                if on_possible and off_possible:
                    break

            if not on_possible and not off_possible:
                return None

            if on_possible:
                possible_adj[v].append(u)
                possible_adj[u].append(v)

            if on_possible and not off_possible:
                forced_adj[v].append(u)
                forced_adj[u].append(v)
                forced_deg[v] += 1
                forced_deg[u] += 1
                forced_edge.add((v, u))
                forced_edge.add((u, v))

        return possible_adj, forced_adj, forced_deg, forced_edge

    def global_checks(dom):
        comp = compute_edge_possibilities(dom)
        if comp is None:
            return False
        possible_adj, forced_adj, forced_deg, forced_edge = comp

        usable = [bool(dom[v] & NONEMPTY_MASK) for v in range(V)]
        mandatory = [v for v in range(V) if clue[v] is not None or not (dom[v] & EMPTY_BIT)]

        # Anything forced on cannot coexist with a vertex fixed empty.
        for v in range(V):
            if forced_deg[v] > 2:
                return False
            if dom[v] == EMPTY_BIT and forced_deg[v] != 0:
                return False

        # All mandatory vertices must still be connectable through possible loop edges.
        if mandatory:
            start = mandatory[0]
            if not usable[start]:
                return False
            seen = {start}
            dq = deque([start])
            while dq:
                x = dq.popleft()
                for y in possible_adj[x]:
                    if not usable[y] or y in seen:
                        continue
                    seen.add(y)
                    dq.append(y)
            if any(m not in seen for m in mandatory):
                return False

        # No premature closed cycle unless it already contains every forced/must-use part.
        seen = set()
        cycle_component = None
        for v in range(V):
            if forced_deg[v] == 0 or v in seen:
                continue
            stack = [v]
            seen.add(v)
            comp_vertices = []
            while stack:
                x = stack.pop()
                comp_vertices.append(x)
                for y in forced_adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)

            if all(forced_deg[x] == 2 for x in comp_vertices):
                if cycle_component is not None:
                    return False
                cycle_component = set(comp_vertices)
            else:
                # Forced path endpoints must still have some way to continue.
                endpoints = [x for x in comp_vertices if forced_deg[x] == 1]
                if len(endpoints) != 2:
                    return False
                for x in endpoints:
                    if not any((x, y) not in forced_edge for y in possible_adj[x]):
                        return False

        if cycle_component is not None:
            for v in range(V):
                if forced_deg[v] and v not in cycle_component:
                    return False
            if any(m not in cycle_component for m in mandatory):
                return False

        return True

    def propagate(dom):
        dom = list(dom)
        while True:
            changed = False

            for v in range(V):
                new = revise_basic(v, dom)
                if new == 0:
                    return None
                if new != dom[v]:
                    dom[v] = new
                    changed = True

            for w in white_vertices:
                res = revise_white(w, dom)
                if res is None:
                    return None
                if res:
                    changed = True

            if not global_checks(dom):
                return None

            if not changed:
                return dom

    def build_final_path(dom):
        singles = [SINGLETON_PATTERN[m] for m in dom]
        if any(p < 0 for p in singles):
            return None

        adj = [[] for _ in range(V)]

        for v, u, d in edges:
            a = USES[singles[v]][d]
            b = USES[singles[u]][OPP[d]]
            if a != b:
                return None
            if a:
                adj[v].append(u)
                adj[u].append(v)

        for v in range(V):
            p = singles[v]
            deg = len(adj[v])
            if p == P_EMPTY:
                if deg != 0:
                    return None
            else:
                if deg != 2:
                    return None
            if clue[v] is not None and p == P_EMPTY:
                return None

        # Final clue validation.
        for w in white_vertices:
            p = singles[w]
            if p == P_H:
                l = neighbors4[w][L]
                r = neighbors4[w][R]
                if l is None or r is None:
                    return None
                lp = singles[l]
                rp = singles[r]
                if not (((1 << lp) & TURN_MASK_BY_NEIGHBOR_DIR[L]) or ((1 << rp) & TURN_MASK_BY_NEIGHBOR_DIR[R])):
                    return None
            elif p == P_V:
                u = neighbors4[w][U]
                d = neighbors4[w][D]
                if u is None or d is None:
                    return None
                up = singles[u]
                dp = singles[d]
                if not (((1 << up) & TURN_MASK_BY_NEIGHBOR_DIR[U]) or ((1 << dp) & TURN_MASK_BY_NEIGHBOR_DIR[D])):
                    return None
            else:
                return None

        for b in black_vertices:
            p = singles[b]
            if p not in (P_UR, P_UL, P_DR, P_DL):
                return None
            for d in range(4):
                if USES[p][d]:
                    u = neighbors4[b][d]
                    if u is None:
                        return None
                    if singles[u] != AXIS_STRAIGHT[d]:
                        return None

        used = [v for v in range(V) if adj[v]]
        if not used:
            return None

        start = min(used)
        if len(adj[start]) != 2:
            return None

        def build_with_first(first):
            path = [rc[start], rc[first]]
            visited = {start}
            prev = start
            cur = first
            while cur != start:
                if cur in visited:
                    return None
                visited.add(cur)
                if len(adj[cur]) != 2:
                    return None
                a, b = adj[cur]
                nxt = a if a != prev else b
                prev, cur = cur, nxt
                path.append(rc[cur])
            if len(visited) != len(used):
                return None
            return path

        n0, n1 = sorted(adj[start])
        p0 = build_with_first(n0)
        p1 = build_with_first(n1)
        if p0 is None and p1 is None:
            return None
        if p0 is None:
            return p1
        if p1 is None:
            return p0
        return p0 if p0 < p1 else p1

    def select_var(dom):
        best_v = None
        best_key = None
        for v in range(V):
            cnt = POPCOUNT[dom[v]]
            if cnt <= 1:
                continue
            clue_priority = 0 if clue[v] is not None else (1 if not (dom[v] & EMPTY_BIT) else 2)
            support_score = 0
            for p in MASK_PATTERNS[dom[v]]:
                for d, u in vertex_neighbors[v]:
                    support_score += POPCOUNT[support[v][d][p] & dom[u]]
            key = (cnt, clue_priority, support_score, -len(vertex_neighbors[v]))
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
        return best_v

    def order_patterns(v, dom):
        opts = []
        for p in MASK_PATTERNS[dom[v]]:
            score = 0
            for d, u in vertex_neighbors[v]:
                score += POPCOUNT[support[v][d][p] & dom[u]]
            # Try tighter patterns first.
            opts.append((score, p))
        opts.sort()
        return [p for _, p in opts]

    failed = set()

    def dfs(dom):
        dom = propagate(dom)
        if dom is None:
            return None

        key = tuple(dom)
        if key in failed:
            return None

        if all(POPCOUNT[m] == 1 for m in dom):
            path = build_final_path(dom)
            if path is not None:
                return path
            failed.add(key)
            return None

        v = select_var(dom)
        if v is None:
            failed.add(key)
            return None

        for p in order_patterns(v, dom):
            nxt = list(dom)
            nxt[v] = 1 << p
            res = dfs(nxt)
            if res is not None:
                return res

        failed.add(key)
        return None

    result = dfs(initial_domains)
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

