                inq[v] = False
                if not process_vertex(domains, q, inq, v):
                    return False
            ok, changed = global_propagate(domains, q, inq)
            if not ok:
                return False
            if not changed:
                break
        return True

    def validate_and_extract(domains):
        # All domains must be singleton.
        for dom in domains:
            if dom == 0 or (dom & (dom - 1)) != 0:
                return None

        mask_of = [MASK_FROM_DOMBIT[dom] for dom in domains]
        used_neighbors = [[] for _ in range(vcount)]
        used_vertices = []

        for v in range(vcount):
            mask = mask_of[v]
            if mask:
                used_vertices.append(v)
            for d in range(4):
                if mask & DIR_BIT[d]:
                    u = adj[v][d]
                    if u == -1:
                        return None
                    if not (mask_of[u] & DIR_BIT[OPP[d]]):
                        return None
                    used_neighbors[v].append(u)

        for v in range(vcount):
            if mask_of[v]:
                if len(used_neighbors[v]) != 2:
                    return None
            else:
                if used_neighbors[v]:
                    return None

        if not used_vertices:
            return None

        # Clue validation
        for v in range(vcount):
            cv = clue[v]
            if cv is None:
                continue
            mask = mask_of[v]
            if cv == 'W':
                if mask not in (MASK_LR, MASK_UD):
                    return None
                if mask == MASK_LR:
                    left = adj[v][L]
                    right = adj[v][R]
                    ok = (
                        (left != -1 and IS_TURN_MASK[mask_of[left]])
                        or (right != -1 and IS_TURN_MASK[mask_of[right]])
                    )
                    if not ok:
                        return None
                else:
                    up = adj[v][U]
                    down = adj[v][D]
                    ok = (
                        (up != -1 and IS_TURN_MASK[mask_of[up]])
                        or (down != -1 and IS_TURN_MASK[mask_of[down]])
                    )
                    if not ok:
                        return None
            elif cv == 'B':
                if not IS_TURN_MASK[mask]:
                    return None
                for d in DIRS_OF_MASK[mask]:
                    u = adj[v][d]
                    if u == -1 or mask_of[u] != REQ_STRAIGHT_MASK[d]:
                        return None

        # Single cycle extraction
        start = min(used_vertices)
        visited = {start}
        path = [rc(start)]
        prev = -1
        cur = start

        while True:
            nbrs = used_neighbors[cur]
            if len(nbrs) != 2:
                return None
            if prev == -1:
                nxt = min(nbrs)
            else:
                if nbrs[0] == prev:
                    nxt = nbrs[1]
                elif nbrs[1] == prev:
                    nxt = nbrs[0]
                else:
                    return None
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break
            if cur in visited:
                return None
            visited.add(cur)

        if len(visited) != len(used_vertices):
            return None

        return path

    def choose_var(domains):
        best_v = None
        best_key = None
        for v in range(vcount):
            dom = domains[v]
            if dom == 0 or (dom & (dom - 1)) == 0:
                continue

            cv = clue[v]
            clue_rank = 0 if cv == 'B' else 1 if cv == 'W' else 2
            must_rank = 0 if (dom & ZERO_BIT) == 0 else 1
            near_rank = 0 if neighbor_clue_count[v] > 0 else 1

            nonzero = dom & ~ZERO_BIT
            eff_size = nonzero.bit_count() if nonzero else dom.bit_count()
            total_size = dom.bit_count()

            key = (clue_rank, must_rank, near_rank, eff_size, total_size, -neighbor_clue_count[v], v)
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
        return best_v

    def split_domain(v, dom):
        cv = clue[v]

        if cv == 'W':
            parts = [dom & BIT_LR, dom & BIT_UD]
            return [p for p in parts if p]

        if cv == 'B':
            # Balanced clue-oriented splits before exact orientation.
            parts = []
            a = dom & (BIT_UR | BIT_LU)
            b = dom & (BIT_RD | BIT_DL)
            if a and b:
                parts = [a, b]
            else:
                a = dom & (BIT_UR | BIT_RD)
                b = dom & (BIT_DL | BIT_LU)
                if a and b:
                    parts = [a, b]
            if parts:
                return parts

        if (dom & ZERO_BIT) and dom != ZERO_BIT:
            return [ZERO_BIT, dom & ~ZERO_BIT]

        straight = dom & STRAIGHT_BITS
        turn = dom & TURN_BITS
        if straight and turn:
            return [straight, turn]

        bits = list(iter_domain_bits(dom))
        if len(bits) <= 1:
            return bits
        mid = len(bits) // 2
        left = 0
        right = 0
        for b in bits[:mid]:
            left |= b
        for b in bits[mid:]:
            right |= b
        return [left, right]

    failed = set()

    def dfs(domains):
        if not propagate(domains):
            return None

        key = tuple(domains)
        if key in failed:
            return None

        path = validate_and_extract(domains)
        if path is not None:
            return path

        v = choose_var(domains)
        if v is None:
            failed.add(key)
            return None

        for part in split_domain(v, domains[v]):
            if part == 0 or part == domains[v]:
                continue
            nd = domains.copy()
            nd[v] &= part
            result = dfs(nd)
            if result is not None:
                return result

        failed.add(key)
        return None

    initial = base.copy()
    ans = dfs(initial)
    return ans if ans is not None else "No Solution"


