import sys

sys.setrecursionlimit(10000)

# Direction bits
U, D, L, R = 1, 2, 4, 8
OPP = {U: D, D: U, L: R, R: L}

# Pattern ids
P_NONE = 0
P_UD = 1
P_LR = 2
P_UR = 3
P_UL = 4
P_DR = 5
P_DL = 6

# Incident-edge masks for patterns
PAT_MASK = [
    0,        # NONE
    U | D,    # UD
    L | R,    # LR
    U | R,    # UR
    U | L,    # UL
    D | R,    # DR
    D | L,    # DL
]

ALL_PATTERN_BITS = (1 << len(PAT_MASK)) - 1
NONE_BIT = 1 << P_NONE
USED_PATTERN_BITS = ALL_PATTERN_BITS ^ NONE_BIT
WHITE_BITS = (1 << P_UD) | (1 << P_LR)
TURN_BITS = (1 << P_UR) | (1 << P_UL) | (1 << P_DR) | (1 << P_DL)

USE_BITS = {
    d: sum(1 << pid for pid, mask in enumerate(PAT_MASK) if mask & d)
    for d in (U, D, L, R)
}
NOT_USE_BITS = {d: ALL_PATTERN_BITS ^ USE_BITS[d] for d in (U, D, L, R)}
TURN_USE_BITS = {d: USE_BITS[d] & TURN_BITS for d in (U, D, L, R)}
REQ_STRAIGHT_PAT = {U: P_UD, D: P_UD, L: P_LR, R: P_LR}

DIR_DELTAS = {
    U: (-1, 0),
    D: (1, 0),
    L: (0, -1),
    R: (0, 1),
}


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data:
        return "No Solution"
    n = len(data)
    if any(not isinstance(row, list) or len(row) != n for row in data):
        return "No Solution"

    total = n * n

    def idx(r, c):
        return r * n + c

    coords = [(r, c) for r in range(n) for c in range(n)]
    neighbors = [dict() for _ in range(total)]
    incident = [0] * total
    edges = []

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i][U] = idx(r - 1, c)
                incident[i] |= U
            if r + 1 < n:
                neighbors[i][D] = idx(r + 1, c)
                incident[i] |= D
            if c > 0:
                neighbors[i][L] = idx(r, c - 1)
                incident[i] |= L
            if c + 1 < n:
                neighbors[i][R] = idx(r, c + 1)
                incident[i] |= R
            if r + 1 < n:
                j = idx(r + 1, c)
                edges.append((i, D, j, U))
            if c + 1 < n:
                j = idx(r, c + 1)
                edges.append((i, R, j, L))

    clue = [None] * total
    clue_vertices = []
    white_vertices = []
    black_vertices = []
    init = [0] * total

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            typ = data[r][c]
            clue[i] = typ
            feasible = 0
            for pid, mask in enumerate(PAT_MASK):
                if (mask & ~incident[i]) == 0:
                    feasible |= 1 << pid

            if typ is None:
                dom = feasible
            elif typ == 'W':
                dom = feasible & WHITE_BITS
                clue_vertices.append(i)
                white_vertices.append(i)
            elif typ == 'B':
                dom = feasible & TURN_BITS
                clue_vertices.append(i)
                black_vertices.append(i)
            else:
                return "No Solution"

            if dom == 0:
                return "No Solution"
            init[i] = dom

    def is_singleton(bits):
        return bits != 0 and (bits & (bits - 1)) == 0

    def singleton_pid(bits):
        return bits.bit_length() - 1

    def possible_edge(dom, u, du, v, dv):
        return (dom[u] & USE_BITS[du]) != 0 and (dom[v] & USE_BITS[dv]) != 0

    def confirmed_edge(dom, u, du, v, dv):
        return (dom[u] & NOT_USE_BITS[du]) == 0 and (dom[v] & NOT_USE_BITS[dv]) == 0

    def filter_black(dom, b):
        changed = False
        db = dom[b]

        allowed_b = 0
        for pid in (P_UR, P_UL, P_DR, P_DL):
            bit = 1 << pid
            if not (db & bit):
                continue
            mask = PAT_MASK[pid]
            ok = True
            for d, nb in neighbors[b].items():
                if mask & d:
                    req_bit = 1 << REQ_STRAIGHT_PAT[d]
                    if not (dom[nb] & req_bit):
                        ok = False
                        break
                else:
                    if not (dom[nb] & NOT_USE_BITS[OPP[d]]):
                        ok = False
                        break
            if ok:
                allowed_b |= bit

        if allowed_b == 0:
            return False, changed
        if allowed_b != db:
            dom[b] = allowed_b
            db = allowed_b
            changed = True

        for d, nb in neighbors[b].items():
            dn = dom[nb]
            req_pid = REQ_STRAIGHT_PAT[d]
            can_on = (db & USE_BITS[d]) != 0
            can_off = (db & NOT_USE_BITS[d]) != 0
            opp = OPP[d]

            new_dn = 0
            for q in range(len(PAT_MASK)):
                bit = 1 << q
                if not (dn & bit):
                    continue
                uses = (PAT_MASK[q] & opp) != 0
                if uses:
                    if q == req_pid and can_on:
                        new_dn |= bit
                else:
                    if can_off:
                        new_dn |= bit

            if new_dn == 0:
                return False, changed
            if new_dn != dn:
                dom[nb] = new_dn
                changed = True

        return True, changed

    def filter_white(dom, w):
        changed = False
        dw = dom[w]

        left = neighbors[w].get(L)
        right = neighbors[w].get(R)
        up = neighbors[w].get(U)
        down = neighbors[w].get(D)

        allowed_w = 0

        if (dw & (1 << P_LR)) and left is not None and right is not None:
            left_any = dom[left] & USE_BITS[R]
            right_any = dom[right] & USE_BITS[L]
            left_turn = dom[left] & TURN_USE_BITS[R]
            right_turn = dom[right] & TURN_USE_BITS[L]
            if left_any and right_any and (left_turn or right_turn):
                allowed_w |= 1 << P_LR

        if (dw & (1 << P_UD)) and up is not None and down is not None:
            up_any = dom[up] & USE_BITS[D]
            down_any = dom[down] & USE_BITS[U]
            up_turn = dom[up] & TURN_USE_BITS[D]
            down_turn = dom[down] & TURN_USE_BITS[U]
            if up_any and down_any and (up_turn or down_turn):
                allowed_w |= 1 << P_UD

        if allowed_w == 0:
            return False, changed
        if allowed_w != dw:
            dom[w] = allowed_w
            dw = allowed_w
            changed = True

        lr_possible = (dw & (1 << P_LR)) != 0
        ud_possible = (dw & (1 << P_UD)) != 0

        if left is not None:
            dl = dom[left]
            right_use = (dom[right] & USE_BITS[L]) if right is not None else 0
            right_turn = (dom[right] & TURN_USE_BITS[L]) if right is not None else 0
            new_dl = 0
            for q in range(len(PAT_MASK)):
                bit = 1 << q
                if not (dl & bit):
                    continue
                if PAT_MASK[q] & R:
                    if lr_possible:
                        if q == P_LR:
                            if right_turn:
                                new_dl |= bit
                        else:
                            if right_use:
                                new_dl |= bit
                else:
                    if ud_possible:
                        new_dl |= bit
            if new_dl == 0:
                return False, changed
            if new_dl != dl:
                dom[left] = new_dl
                changed = True

        if right is not None:
            dr = dom[right]
            left_use = (dom[left] & USE_BITS[R]) if left is not None else 0
            left_turn = (dom[left] & TURN_USE_BITS[R]) if left is not None else 0
            new_dr = 0
            for q in range(len(PAT_MASK)):
                bit = 1 << q
                if not (dr & bit):
                    continue
                if PAT_MASK[q] & L:
                    if lr_possible:
                        if q == P_LR:
                            if left_turn:
                                new_dr |= bit
                        else:
                            if left_use:
                                new_dr |= bit
                else:
                    if ud_possible:
                        new_dr |= bit
            if new_dr == 0:
                return False, changed
            if new_dr != dr:
                dom[right] = new_dr
                changed = True

        if up is not None:
            du = dom[up]
            down_use = (dom[down] & USE_BITS[U]) if down is not None else 0
            down_turn = (dom[down] & TURN_USE_BITS[U]) if down is not None else 0
            new_du = 0
            for q in range(len(PAT_MASK)):
                bit = 1 << q
                if not (du & bit):
                    continue
                if PAT_MASK[q] & D:
                    if ud_possible:
                        if q == P_UD:
                            if down_turn:
                                new_du |= bit
                        else:
                            if down_use:
                                new_du |= bit
                else:
                    if lr_possible:
                        new_du |= bit
            if new_du == 0:
                return False, changed
            if new_du != du:
                dom[up] = new_du
                changed = True

        if down is not None:
            dd = dom[down]
            up_use = (dom[up] & USE_BITS[D]) if up is not None else 0
            up_turn = (dom[up] & TURN_USE_BITS[D]) if up is not None else 0
            new_dd = 0
            for q in range(len(PAT_MASK)):
                bit = 1 << q
                if not (dd & bit):
                    continue
                if PAT_MASK[q] & U:
                    if ud_possible:
                        if q == P_UD:
                            if up_turn:
                                new_dd |= bit
                        else:
                            if up_use:
                                new_dd |= bit
                else:
                    if lr_possible:
                        new_dd |= bit
            if new_dd == 0:
                return False, changed
            if new_dd != dd:
                dom[down] = new_dd
                changed = True

        return True, changed

    def global_checks(dom):
        required = [i for i in range(total) if clue[i] is not None or (dom[i] & NONE_BIT) == 0]
        if required:
            start = required[0]
            seen = {start}
            stack = [start]
            while stack:
                u = stack.pop()
                for d, v in neighbors[u].items():
                    if v not in seen and possible_edge(dom, u, d, v, OPP[d]):
                        seen.add(v)
                        stack.append(v)
            for i in required:
                if i not in seen:
                    return False

        conf_adj = [[] for _ in range(total)]
        conf_deg = [0] * total
        any_confirmed = False
        for u, du, v, dv in edges:
            if confirmed_edge(dom, u, du, v, dv):
                conf_adj[u].append(v)
                conf_adj[v].append(u)
                conf_deg[u] += 1
                conf_deg[v] += 1
                any_confirmed = True

        if any_confirmed:
            seen_comp = set()
            required_set = set(required)
            for s in range(total):
                if conf_deg[s] == 0 or s in seen_comp:
                    continue
                comp = []
                stack = [s]
                seen_comp.add(s)
                while stack:
                    u = stack.pop()
                    comp.append(u)
                    for v in conf_adj[u]:
                        if v not in seen_comp:
                            seen_comp.add(v)
                            stack.append(v)

                if all(conf_deg[v] == 2 for v in comp):
                    comp_set = set(comp)
                    closed = True
                    for u in comp:
                        for d, v in neighbors[u].items():
                            if v not in comp_set and possible_edge(dom, u, d, v, OPP[d]):
                                closed = False
                                break
                        if not closed:
                            break

                    if closed:
                        for i in required_set:
                            if i not in comp_set:
                                return False
                        for i in range(total):
                            if conf_deg[i] > 0 and i not in comp_set:
                                return False

        return True

    def propagate(dom):
        while True:
            changed = False

            for u, du, v, dv in edges:
                bu = dom[u]
                bv = dom[v]

                u_on = bu & USE_BITS[du]
                v_on = bv & USE_BITS[dv]
                can_on = bool(u_on and v_on)

                u_off = bu & NOT_USE_BITS[du]
                v_off = bv & NOT_USE_BITS[dv]
                can_off = bool(u_off and v_off)

                if not can_on and not can_off:
                    return False

                nbu = bu
                nbv = bv
                if not can_on:
                    nbu &= NOT_USE_BITS[du]
                    nbv &= NOT_USE_BITS[dv]
                if not can_off:
                    nbu &= USE_BITS[du]
                    nbv &= USE_BITS[dv]

                if nbu == 0 or nbv == 0:
                    return False
                if nbu != bu:
                    dom[u] = nbu
                    changed = True
                if nbv != bv:
                    dom[v] = nbv
                    changed = True

            for b in black_vertices:
                ok, ch = filter_black(dom, b)
                if not ok:
                    return False
                changed |= ch

            for w in white_vertices:
                ok, ch = filter_white(dom, w)
                if not ok:
                    return False
                changed |= ch

            if not global_checks(dom):
                return False

            if not changed:
                return True

    def extract_path(dom):
        if not all(is_singleton(bits) for bits in dom):
            return None

        pids = [singleton_pid(bits) for bits in dom]
        used_adj = [[] for _ in range(total)]
        used_vertices = []

        for i, pid in enumerate(pids):
            mask = PAT_MASK[pid]
            if mask == 0:
                continue
            used_vertices.append(i)
            for d, v in neighbors[i].items():
                if mask & d:
                    used_adj[i].append(v)

        if not used_vertices:
            return None

        for i in range(total):
            if PAT_MASK[pids[i]] == 0:
                if used_adj[i]:
                    return None
            else:
                if len(used_adj[i]) != 2:
                    return None

        edge_count = 0
        for i in used_vertices:
            for v in used_adj[i]:
                if i not in used_adj[v]:
                    return None
                if i < v:
                    edge_count += 1

        if edge_count != len(used_vertices):
            return None

        seen = {used_vertices[0]}
        stack = [used_vertices[0]]
        while stack:
            u = stack.pop()
            for v in used_adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        if len(seen) != len(used_vertices):
            return None

        for i in clue_vertices:
            pid = pids[i]
            typ = clue[i]
            if typ == 'W':
                if pid not in (P_UD, P_LR):
                    return None
                if pid == P_LR:
                    left = neighbors[i].get(L)
                    right = neighbors[i].get(R)
                    if left is None or right is None:
                        return None
                    lp = pids[left]
                    rp = pids[right]
                    if not (PAT_MASK[lp] & R and PAT_MASK[rp] & L):
                        return None
                    left_turn = lp in (P_UR, P_DR)
                    right_turn = rp in (P_UL, P_DL)
                    if not (left_turn or right_turn):
                        return None
                else:
                    up = neighbors[i].get(U)
                    down = neighbors[i].get(D)
                    if up is None or down is None:
                        return None
                    up_p = pids[up]
                    down_p = pids[down]
                    if not (PAT_MASK[up_p] & D and PAT_MASK[down_p] & U):
                        return None
                    up_turn = up_p in (P_DR, P_DL)
                    down_turn = down_p in (P_UR, P_UL)
                    if not (up_turn or down_turn):
                        return None
            elif typ == 'B':
                if pid not in (P_UR, P_UL, P_DR, P_DL):
                    return None
                mask = PAT_MASK[pid]
                for d, nb in neighbors[i].items():
                    np = pids[nb]
                    if mask & d:
                        req = P_UD if d in (U, D) else P_LR
                        if np != req:
                            return None
                    else:
                        if PAT_MASK[np] & OPP[d]:
                            return None

        start = min(used_vertices)
        path = [coords[start]]
        prev = None
        curr = start

        while True:
            nxts = used_adj[curr]
            if len(nxts) != 2:
                return None
            if prev is None:
                nxt = min(nxts)
            else:
                if nxts[0] == prev:
                    nxt = nxts[1]
                elif nxts[1] == prev:
                    nxt = nxts[0]
                else:
                    return None
            path.append(coords[nxt])
            prev, curr = curr, nxt
            if curr == start:
                break
            if len(path) > len(used_vertices) + 1:
                return None

        if len(path) != len(used_vertices) + 1:
            return None
        return path

    def choose_branch(dom):
        best = None
        best_key = None

        for i, bits in enumerate(dom):
            cnt = bits.bit_count()
            if cnt <= 1:
                continue
            has_none = (bits & NONE_BIT) != 0
            typ = clue[i]
            if typ == 'B':
                pri = 0
            elif typ == 'W':
                pri = 1
            elif not has_none:
                pri = 2
            else:
                pri = 3

            clue_nei = 0
            for _, nb in neighbors[i].items():
                if clue[nb] is not None:
                    clue_nei += 1

            key = (pri, cnt, -clue_nei, -len(neighbors[i]), i)
            if best_key is None or key < best_key:
                best_key = key
                best = i

