                        break
                    continue

                nd = domains[nb]
                od = OPP[d]

                if use_edge:
                    if not CAN_USE[nd][od]:
                        ok = False
                        break

                    nclue = clues[nb]

                    # Adjacent to black: if black uses the shared edge, this vertex must be straight.
                    if nclue == CL_B:
                        if idx != AXIS_PATTERN[d]:
                            ok = False
                            break
                        if not (nd & TURN_USE_DIR_MASK[od]):
                            ok = False
                            break

                    # Adjacent to white: white must be straight along the shared axis.
                    # If this side is not a turn, the opposite side of the white must be able to turn.
                    elif nclue == CL_W:
                        need_axis_mask = VERT_MASK if d in (U, D) else HORIZ_MASK
                        if not (nd & need_axis_mask):
                            ok = False
                            break
                        if not IS_TURN[idx]:
                            other = neighbors[nb][d]
                            if other == -1 or not CAN_TURN_WITH[domains[other]][od]:
                                ok = False
                                break
                else:
                    if MUST_USE[nd][od]:
                        ok = False
                        break

            if not ok:
                continue

            if clue == CL_B:
                # Black turns; both adjacent vertices on the loop must be straight.
                for d in range(4):
                    if p & DIRBITS[d]:
                        nb = neighbors[v][d]
                        nd = domains[nb]
                        need_axis_mask = VERT_MASK if d in (U, D) else HORIZ_MASK
                        if not (nd & need_axis_mask):
                            ok = False
                            break

            elif clue == CL_W:
                # White goes straight and at least one neighboring step must turn.
