                    a = neighbors[v][U]
                    b = neighbors[v][D]
                    if a == -1 or b == -1:
                        ok = False
                    elif not CAN_USE[domains[a]][D] or not CAN_USE[domains[b]][U]:
                        ok = False
                    elif not (CAN_TURN_WITH[domains[a]][D] or CAN_TURN_WITH[domains[b]][U]):
