                        ok = False
                    elif not CAN_USE[domains[a]][R] or not CAN_USE[domains[b]][L]:
                        ok = False
                    elif not (CAN_TURN_WITH[domains[a]][R] or CAN_TURN_WITH[domains[b]][L]):
