            stack = [s]
            seen[s] = True
            comp = []
            closed = True
            while stack:
                v = stack.pop()
                comp.append(v)
                if len(madj[v]) != 2:
                    closed = False
                for nb in madj[v]:
                    if not seen[nb]:
