            deg = len(adj[v])
            if deg not in (0, 2):
                return None
            for nb in adj[v]:
                if v not in adj[nb]:
                    return None

        used = [v for v in range(h * w) if adj[v]]
        if not used:
            return None

        # Single connected cycle
        seen = {used[0]}
        stack = [used[0]]
        while stack:
            v = stack.pop()
            for nb in adj[v]:
                if nb not in seen:
                    seen.add(nb)
                    stack.append(nb)

        if len(seen) != len(used):
            return None

        edge_count = sum(len(adj[v]) for v in used) // 2
        if edge_count != len(used):
            return None

        # Final clue verification
        for v in range(h * w):
            clue = clues[v]
            if clue == CL_NONE:
                continue
            idx = SINGLETON_INDEX[domains[v]]
            p = PATTERN_EDGES[idx]

            if clue == CL_W:
                if idx == VERT:
                    a = neighbors[v][U]
                    b = neighbors[v][D]
                    if a == -1 or b == -1:
                        return None
                    ia = SINGLETON_INDEX[domains[a]]
                    ib = SINGLETON_INDEX[domains[b]]
                    if not (IS_TURN[ia] and (PATTERN_EDGES[ia] & DIRBITS[D]) or IS_TURN[ib] and (PATTERN_EDGES[ib] & DIRBITS[U])):
                        return None
                elif idx == HORIZ:
                    a = neighbors[v][L]
                    b = neighbors[v][R]
                    if a == -1 or b == -1:
                        return None
                    ia = SINGLETON_INDEX[domains[a]]
                    ib = SINGLETON_INDEX[domains[b]]
                    if not (IS_TURN[ia] and (PATTERN_EDGES[ia] & DIRBITS[R]) or IS_TURN[ib] and (PATTERN_EDGES[ib] & DIRBITS[L])):
                        return None
                else:
                    return None

            elif clue == CL_B:
