                    return None
                for d in range(4):
                    if p & DIRBITS[d]:
                        nb = neighbors[v][d]
                        nidx = SINGLETON_INDEX[domains[nb]]
                        if nidx != AXIS_PATTERN[d]:
                            return None

        # Extract ordered closed loop
        start = min(used, key=lambda v: coord(v))
        nbs = sorted(adj[start], key=lambda v: coord(v))
        if len(nbs) != 2:
            return None

        path = [coord(start)]
        prev = start
        curr = nbs[0]

        while True:
            path.append(coord(curr))
            if curr == start:
                break
            nbrs = adj[curr]
            if len(nbrs) != 2:
                return None
            nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
            prev, curr = curr, nxt
            if len(path) > len(used) + 1:
                return None

        if len(path) != len(used) + 1:
            return None
        if len(set(path[:-1])) != len(used):
            return None

        return path

    dead = set()

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        key = tuple(domains)
        if key in dead:
            return None

        if all(POPCOUNT[dom] == 1 for dom in domains):
            sol = build_solution(domains)
            if sol is not None:
                return sol
            dead.add(key)
            return None

        v = choose_var(domains)
        if v is None:
            dead.add(key)
            return None

        options = list(DOM_MEMBERS[domains[v]])
        options.sort(key=lambda idx: (pattern_score(v, idx, domains), idx != OFF), reverse=True)

        for idx in options:
            new_domains = domains.copy()
            new_domains[v] = 1 << idx
            sol = search(new_domains)
            if sol is not None:
                return sol

        dead.add(key)
        return None

