# Human-style logic is encoded as:
# - each dot is either unused or has degree 2,
# - white clues are straight and must have a turn immediately before/after,
# - black clues are turns and force straight continuation on both adjacent dots,
# - border impossibilities are removed immediately,
# - aggressive propagation repeatedly deletes unsupported local shapes,
# - global checks prevent disconnected mandatory regions and premature closed subloops.

U, R, D, L = 0, 1, 2, 3
DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [D, L, U, R]
DIR_BIT = [1 << U, 1 << R, 1 << D, 1 << L]

# Pattern ids
OFF = 0
H = 1
V = 2
UR = 3
RD = 4
DL = 5
LU = 6
P = 7

PAT_EDGE_BITS = [
    0,
    DIR_BIT[R] | DIR_BIT[L],  # H
    DIR_BIT[U] | DIR_BIT[D],  # V
    DIR_BIT[U] | DIR_BIT[R],  # UR
    DIR_BIT[R] | DIR_BIT[D],  # RD
    DIR_BIT[D] | DIR_BIT[L],  # DL
    DIR_BIT[L] | DIR_BIT[U],  # LU
