PAT_USE = [[bool(PAT_EDGE_BITS[p] & DIR_BIT[d]) for d in range(4)] for p in range(P)]
IS_TURN = [False, False, False, True, True, True, True]
IS_STRAIGHT = [False, True, True, False, False, False, False]

MASK_OFF = 1 << OFF
MASK_H = 1 << H
MASK_V = 1 << V
MASK_STRAIGHT = MASK_H | MASK_V
MASK_TURN = (1 << UR) | (1 << RD) | (1 << DL) | (1 << LU)
MASK_NONOFF = ((1 << P) - 1) ^ MASK_OFF


