    # 1) direct clue saturation (0 => all white, full => all black)
    # 2) pairwise overlap bounds between exact-count regions
    # 3) whenever a subregion count becomes exact, treat it as a new derived clue
    def propagate(black, white):
        if black & white:
            return None

        while True:
            constraints = reduce_constraints(black, white)
            if constraints is None:
                return None

            restarted = False

            while True:
                forced_black = 0
                forced_white = 0

                # Basic exact-sum propagation
                for mask, target in constraints.items():
                    k = mask.bit_count()
                    if target < 0 or target > k:
                        return None
                    if k == 0:
                        if target != 0:
