                if verify(final):
                    return final
                unsat.add(key)
                return None

            values = (1, 0) if pref[v] >= 0.5 else (0, 1)
            for val in values:
                new_assign = assign[:]
                new_assign[v] = val
                sol = search(new_assign)
                if sol is not None:
                    return sol

