    data = observation.get('data')
    if not isinstance(data, list):
        return "No Solution"
    if not data:
        return str([])

    original = [row[:] for row in data]
    if any(not isinstance(row, list) for row in original):
        return "No Solution"
    if not original:
        return str([])

    h = len(original)
    w = len(original[0]) if h else 0
    if any(len(row) != w for row in original):
