def cell_search_solve(data, constraints, adj, assignment):
    # Fallback targeted search with heavy propagation.
    h = len(data)
    w = len(data[0]) if h else 0
    n = h * w
    failed = set()

    def state_key(assign):
        known = 0
        black = 0
        for i, a in enumerate(assign):
            if a != -1:
                known |= 1 << i
                if a == 1:
                    black |= 1 << i
        return known, black

    def choose_var(assign):
        stats = {}
        for ci, (vars_, target) in enumerate(constraints):
            black = 0
            unknown = []
            for v in vars_:
                a = assign[v]
                if a == 1:
                    black += 1
                elif a == -1:
                    unknown.append(v)
            if not unknown:
                continue
            need = target - black
            ucount = len(unknown)
            frac = need / ucount
            for v in unknown:
                item = stats.get(v)
                if item is None:
                    stats[v] = [ucount, 1, frac]
                else:
                    if ucount < item[0]:
                        item[0] = ucount
                    item[1] += 1
                    item[2] += frac

        best_v = None
        best_key = None
        best_avg = 0.5

        for v, (min_ucount, degree, frac_sum) in stats.items():
            avg = frac_sum / degree
            key = (min_ucount, -degree, -abs(avg - 0.5))
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
                best_avg = avg

        if best_v is None:
            for v, a in enumerate(assign):
                if a == -1:
                    return v, 0.0
            return None, 0.0
        return best_v, best_avg

    def rec(assign):
        assign = propagate_exact_sum(n, constraints, adj, assign)
        if assign is None:
            return None

        key = state_key(assign)
        if key in failed:
            return None

        if all(a != -1 for a in assign):
            return assign

        v, avg = choose_var(assign)
        if v is None:
            return assign

        order = (1, 0) if avg > 0.5 else (0, 1)
        for val in order:
            nxt = assign[:]
            nxt[v] = val
            sol = rec(nxt)
            if sol is not None:
                return sol

        failed.add(key)
        return None

    return rec(assignment)


def solve_core(data):
    built = build_system(data)
    if built is None:
        return None
    h, w, n, constraints, adj = built

    if not constraints:
        return [[None for _ in range(w)] for _ in range(h)]

    base_assignment = [-1] * n
    for v in range(n):
        if not adj[v]:
            base_assignment[v] = 0

    assignment = propagate_exact_sum(n, constraints, adj, base_assignment)
    if assignment is None:
        return None

    if all(a != -1 for a in assignment):
        grid = assignment_to_grid(assignment, h, w)
        return grid if verify_solution(data, grid) else None

    grid = row_dp_solve(data, assignment)
    if grid is not None:
        return grid

    final_assign = cell_search_solve(data, constraints, adj, assignment)
    if final_assign is None:
        return None

    grid = assignment_to_grid(final_assign, h, w)
    return grid if verify_solution(data, grid) else None


def solve(observation):
    data = observation.get('data')
    if not isinstance(data, list):
        return "No Solution"
    if not data:
        return str([])

    original = [row[:] for row in data]
    if any(not isinstance(row, list) for row in original):
        return "No Solution"
    if not original:
        return str([])

    h = len(original)
    w = len(original[0]) if h else 0
    if any(len(row) != w for row in original):
        return "No Solution"

    transposed = False
    work = original
    if w > h:
        work = transpose_grid(original)
        transposed = True

    grid = solve_core(work)
    if grid is None:
        return "No Solution"

    if transposed:
        grid = transpose_grid(grid)

    if not verify_solution(original, grid):
        return "No Solution"

    return str(grid)


