        if key in unsat:
            return None

        if (black_mask | white_mask) == full_mask:
            if verify(black_mask):
                return black_mask
            unsat.add(key)
            return None

        cell, order = choose_cell(cons, black_mask, white_mask)
        if cell is None:
            if verify(black_mask):
                return black_mask
            unsat.add(key)
            return None

        bit = 1 << cell
        current_unknown = full_mask ^ (black_mask | white_mask)
        trials = []

        # Failed-literal probing on the most constrained cell.
        for value in order:
            try:
                if value:
                    b2, w2, _ = propagate(black_mask | bit, white_mask)
                else:
                    b2, w2, _ = propagate(black_mask, white_mask | bit)
                trials.append((value, b2, w2))
            except Contradiction:
