            return None

        if len(ok) == 1:
            return dfs(ok[0][1], ok[0][2])

        # If both branches force the same other cells, commit them immediately.
        _, b0, w0 = ok[0]
        _, b1, w1 = ok[1]
        forced_black = (b0 & b1) & current_unknown
        forced_white = (w0 & w1) & current_unknown
        if forced_black or forced_white:
            return dfs(black_mask | forced_black, white_mask | forced_white)

