def solve(observation):
    data = observation.get("data")
    if not data or not data[0]:
        return "No Solution"

    rows = len(data)
    cols = len(data[0])
    if any(len(row) != cols for row in data):
        return "No Solution"

    cell_count = rows * cols

    # Normalize region ids to 0..R-1 while keeping the shape.
    region_index = {}
    region_cells = []
    region_of = [0] * cell_count
    for r in range(rows):
        for c in range(cols):
            rid = data[r][c]
            if rid not in region_index:
                region_index[rid] = len(region_cells)
                region_cells.append([])
            rr = region_index[rid]
            idx = r * cols + c
            region_of[idx] = rr
            region_cells[rr].append(idx)
    region_count = len(region_cells)

    # Cell neighbors.
    neighbors = [[] for _ in range(cell_count)]
    adj_mask = [0] * cell_count
    for r in range(rows):
        for c in range(cols):
            idx = r * cols + c
            if r > 0:
                neighbors[idx].append((r - 1) * cols + c)
            if r + 1 < rows:
                neighbors[idx].append((r + 1) * cols + c)
            if c > 0:
                neighbors[idx].append(r * cols + (c - 1))
            if c + 1 < cols:
                neighbors[idx].append(r * cols + (c + 1))
            m = 0
            for nb in neighbors[idx]:
                m |= 1 << nb
            adj_mask[idx] = m

    # Enumerate all domino placements.
    placements = []
    placement_cells_mask = []
    for r in range(rows):
        for c in range(cols):
            a = r * cols + c
            if c + 1 < cols:
                b = r * cols + (c + 1)
                placements.append((a, b))
                placement_cells_mask.append((1 << a) | (1 << b))
            if r + 1 < rows:
                b = (r + 1) * cols + c
                placements.append((a, b))
                placement_cells_mask.append((1 << a) | (1 << b))

    placement_count = len(placements)

    # A domino forbids any other domino that shares a cell or touches it orthogonally.
    touch_zone = [0] * placement_count
    for p, (a, b) in enumerate(placements):
        touch_zone[p] = placement_cells_mask[p] | adj_mask[a] | adj_mask[b]

    conflict_mask = [0] * placement_count
    for p in range(placement_count):
        tz = touch_zone[p]
        for q in range(p + 1, placement_count):
            if placement_cells_mask[q] & tz:
                conflict_mask[p] |= 1 << q
                conflict_mask[q] |= 1 << p

    # Classify placements per region.
    region_internal = [[] for _ in range(region_count)]
    region_crossing = [[] for _ in range(region_count)]
    crossing_cell = {}
    shared_mask = [[0] * region_count for _ in range(region_count)]

    for p, (a, b) in enumerate(placements):
        ra = region_of[a]
        rb = region_of[b]
        if ra == rb:
            region_internal[ra].append(p)
        else:
            region_crossing[ra].append(p)
            region_crossing[rb].append(p)
            crossing_cell[(ra, p)] = a
            crossing_cell[(rb, p)] = b
            shared_mask[ra][rb] |= 1 << p
            shared_mask[rb][ra] |= 1 << p

    # Human-style local enumeration:
