                p = idx(r, c)
                clue_id_of[p] = len(clues)
                clues.append(p)
                sizes.append(v)

    k = len(clues)
    island_masks = [1 << i for i in range(k)]
    island_all = (1 << k) - 1
    black = 1 << k
    white_total = sum(sizes)
    black_needed = n - white_total
    if black_needed < 0:
        return "No Solution"

    clue_rc = [rc[p] for p in clues]

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def is_single_island(mask):
        return (mask & black) == 0 and is_single(mask)

    def bit_to_index(bit):
        return bit.bit_length() - 1

    domains = [0] * n
    for p, (r, c) in enumerate(rc):
