    for p, (r, c) in enumerate(rc):
        if p in clue_id_of:
            domains[p] = island_masks[clue_id_of[p]]
        else:
            mask = black
            for i, (rr, cc) in enumerate(clue_rc):
                if abs(r - rr) + abs(c - cc) <= sizes[i] - 1:
                    mask |= island_masks[i]
            domains[p] = mask

    def bfs_bit_dist(start, bit, doms, exclude=-1):
        if start == exclude or not (doms[start] & bit):
            return {}
        dist = {start: 0}
        dq = deque([start])
        while dq:
            p = dq.popleft()
            nd = dist[p] + 1
            for q in adj[p]:
                if q != exclude and q not in dist and (doms[q] & bit):
                    dist[q] = nd
                    dq.append(q)
        return dist

    def bfs_black_possible(start, doms, exclude=-1):
        if start == exclude or not (doms[start] & black):
