                if island_part == 0:
                    if m & black:
                        if m != black:
                            doms[p] = black
                            changed = True
                    else:
                        return fail()
                elif not (m & black) and (island_part & (island_part - 1)) == 0:
                    if m != island_part:
                        doms[p] = island_part
                        changed = True

