            black_possible = [p for p, m in enumerate(doms) if m & black]
            bac = len(black_assigned)
            bpc = len(black_possible)

            if bac > black_needed or bpc < black_needed:
                return fail()

            if bac == black_needed:
                if black_needed:
                    if len(bfs_exact_mask(black_assigned[0], black, doms)) != black_needed:
                        return fail()
                for p in black_possible:
                    if doms[p] != black:
