                dist = bfs_bit_dist(clues[i], bit, doms)
                if not dist:
                    return fail()

                for p, m in enumerate(doms):
                    if m & bit:
                        d = dist.get(p)
                        if d is None or d >= target:
                            new = m & ~bit
                            if new == 0:
                                return fail()
                            doms[p] = new
                            changed = True

                region = {p for p, d in dist.items() if d < target}
                if len(region) < target:
                    return fail()
                if any(p not in region for p in assigned):
                    return fail()

                if ac == target:
                    if len(bfs_exact_mask(clues[i], bit, doms)) != target:
                        return fail()
                    for p in region:
                        if doms[p] != bit and (doms[p] & bit):
                            new = doms[p] & ~bit
                            if new == 0:
                                return fail()
                            doms[p] = new
                            changed = True
                    assigned_set = set(assigned)
                    for p in assigned:
                        for q in adj[p]:
                            if q not in assigned_set:
                                new = doms[q] & black
                                if new != doms[q]:
                                    if new == 0:
                                        return fail()
                                    doms[q] = new
                                    changed = True
                    continue

                if len(region) == target:
                    for p in region:
                        if doms[p] != bit:
                            doms[p] = bit
                            changed = True
                    continue

                for p in region:
                    if doms[p] == bit or not (doms[p] & bit):
                        continue
                    rr = bfs_bit_dist(clues[i], bit, doms, exclude=p)
                    if len(rr) < target or any(a not in rr for a in assigned):
                        doms[p] = bit
                        changed = True

            black_assigned = [p for p, m in enumerate(doms) if m == black]
            if black_assigned:
                region = bfs_black_possible(black_assigned[0], doms)
                if any(p not in region for p in black_assigned):
                    return fail()
                for p, m in enumerate(doms):
                    if (m & black) and p not in region:
                        new = m & ~black
                        if new == 0:
                            return fail()
                        doms[p] = new
                        changed = True

                if len(black_assigned) < black_needed:
                    for p, m in enumerate(doms):
                        if m == black or not (m & black):
                            continue
                        rr = bfs_black_possible(black_assigned[0], doms, exclude=p)
                        if len(rr) < black_needed or any(a not in rr for a in black_assigned):
                            doms[p] = black
                            changed = True

            if not changed:
                break

        prop_cache[key] = tuple(doms)
        return doms

    dead = set()

    def select_cell(doms):
        best_p = None
        best_key = None
        for p, m in enumerate(doms):
            bits = m.bit_count()
            if bits <= 1:
                continue
            assigned_neighbors = sum(1 for q in adj[p] if is_single(doms[q]))
            island_cnt = (m & island_all).bit_count()
            special = 0 if ((m & black) and island_cnt == 1) else 1
            key = (bits, special, -assigned_neighbors)
            if best_key is None or key < best_key:
                best_key = key
                best_p = p
        return best_p

    def order_values(p, m, doms):
        island_opts = []
        x = m & island_all
        while x:
            b = x & -x
            x -= b
            adjacent_same = any(doms[q] == b for q in adj[p])
            island_opts.append((0 if adjacent_same else 1, bit_to_index(b), b))
        island_opts.sort()
        island_vals = [b for _, _, b in island_opts]

        if m & black:
            if island_vals and island_opts[0][0] == 0:
                return island_vals + [black]
            return [black] + island_vals
        return island_vals

    def dfs(start_doms):
        doms = propagate(start_doms)
        if doms is None:
            return None

        key = tuple(doms)
        if key in dead:
            return None

        if all(is_single(m) for m in doms):
            if validate(doms):
                return doms
            dead.add(key)
            return None

        p = select_cell(doms)
        if p is None:
            dead.add(key)
            return None

        for val in order_values(p, doms[p], doms):
            new_doms = doms.copy()
            new_doms[p] = val
            res = dfs(new_doms)
            if res is not None:
                return res

        dead.add(key)
        return None

    sol = dfs(domains)
    if sol is None:
        return "No Solution"

    answer = []
    for r in range(h):
        row = []
        for c in range(w):
            p = idx(r, c)
            row.append('B' if sol[p] == black else None)
        answer.append(row)
    return str(answer)

