    if any(v <= 0 for v in targets):
        return "No Solution"

    total_white = sum(targets)
    black_target = N - total_white
    if black_target < 0:
        return "No Solution"

    BLACK = 1
    island_bits = [1 << (i + 1) for i in range(K)]

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def assign_single(dom, cell, bit):
        if dom[cell] == bit:
            return True, False
        if not (dom[cell] & bit):
            return False, False
        dom[cell] = bit
        return True, True

    def remove_value(dom, cell, bit):
        if not (dom[cell] & bit):
            return True, False
        new_mask = dom[cell] & ~bit
        if new_mask == 0:
            return False, False
        dom[cell] = new_mask
        return True, True

    # Static reachability: a cell can belong to island i only if it can be reached
    # from the clue cell within target-1 steps without crossing another clue.
    root_set = set(roots)
    static_mask = [0] * N
    for i, root in enumerate(roots):
        bit = island_bits[i]
        limit = targets[i] - 1
        q = deque([(root, 0)])
        seen = {root}
        while q:
            u, d = q.popleft()
            static_mask[u] |= bit
            if d == limit:
                continue
