from collections import deque
import sys

sys.setrecursionlimit(10000)


class NurikabeSolver:
    BLACK = 1

    def __init__(self, data):
        self.data = data
        self.R = len(data)
        self.C = len(data[0]) if self.R else 0
        self.N = self.R * self.C

        self.cell_bits = [1 << i for i in range(self.N)]
        self.neighbors = [[] for _ in range(self.N)]
        self.nei_mask = [0] * self.N
        self.blocks_2x2 = []

        for r in range(self.R):
            for c in range(self.C):
                idx = self.idx(r, c)
                mask = 0
                if r > 0:
                    n = self.idx(r - 1, c)
                    self.neighbors[idx].append(n)
                    mask |= self.cell_bits[n]
                if r + 1 < self.R:
                    n = self.idx(r + 1, c)
                    self.neighbors[idx].append(n)
                    mask |= self.cell_bits[n]
                if c > 0:
                    n = self.idx(r, c - 1)
                    self.neighbors[idx].append(n)
                    mask |= self.cell_bits[n]
                if c + 1 < self.C:
                    n = self.idx(r, c + 1)
                    self.neighbors[idx].append(n)
                    mask |= self.cell_bits[n]
                self.nei_mask[idx] = mask

        for r in range(self.R - 1):
            for c in range(self.C - 1):
                self.blocks_2x2.append(
                    (self.idx(r, c), self.idx(r + 1, c), self.idx(r, c + 1), self.idx(r + 1, c + 1))
                )

        self.clues = []
        self.clue_id_at = [-1] * self.N
        for r in range(self.R):
            for c in range(self.C):
                v = data[r][c]
                if v is not None:
                    idx = self.idx(r, c)
                    self.clue_id_at[idx] = len(self.clues)
                    self.clues.append((idx, v))

        self.K = len(self.clues)
        self.clue_cells = [p for p, _ in self.clues]
        self.sizes = [v for _, v in self.clues]
        self.target_black = self.N - sum(self.sizes)

        self.ISLAND_BITS = [1 << (i + 1) for i in range(self.K)]
        self.singleton_to_island = {self.ISLAND_BITS[i]: i for i in range(self.K)}
        self.island_bit_to_id = dict(self.singleton_to_island)

        self.shape_cache = [dict() for _ in range(self.K)]
        self.dead_states = set()

        self.dist_from_clue = []
        self.initial_domains = self._build_initial_domains()

    def idx(self, r, c):
        return r * self.C + c

    def rc(self, idx):
        return divmod(idx, self.C)

    def iter_indices(self, mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def neighbor_union(self, mask):
        out = 0
        m = mask
        while m:
            lsb = m & -m
            out |= self.nei_mask[lsb.bit_length() - 1]
            m ^= lsb
        return out

    def flood_from_sources(self, src_mask, allowed_mask):
        seen = 0
        stack = src_mask & allowed_mask
        while stack:
            lsb = stack & -stack
            stack ^= lsb
            if seen & lsb:
                continue
            seen |= lsb
            idx = lsb.bit_length() - 1
            stack |= self.nei_mask[idx] & allowed_mask & ~seen
        return seen

    def flood_from_cell(self, start_idx, allowed_mask):
        bit = self.cell_bits[start_idx]
        if not (allowed_mask & bit):
            return 0
        return self.flood_from_sources(bit, allowed_mask)

    def _static_bfs_dist(self, start_idx, blocked):
        dist = [-1] * self.N
        q = deque([start_idx])
        dist[start_idx] = 0
        while q:
            v = q.popleft()
            for n in self.neighbors[v]:
                if blocked[n] or dist[n] != -1:
                    continue
                dist[n] = dist[v] + 1
                q.append(n)
        return dist

    def _build_initial_domains(self):
        if self.R == 0 or self.C == 0 or self.target_black < 0:
            return []

        clue_blocked_template = [False] * self.N
        for idx, _ in self.clues:
            clue_blocked_template[idx] = True

        adjacent_to_clue = 0
        for clue_idx in self.clue_cells:
            adjacent_to_clue |= self.nei_mask[clue_idx]

        island_possible_masks = [0] * self.K

        for i, clue_idx in enumerate(self.clue_cells):
            blocked = clue_blocked_template[:]
            blocked[clue_idx] = False
            dist = self._static_bfs_dist(clue_idx, blocked)
            self.dist_from_clue.append(dist)

            mask = self.cell_bits[clue_idx]
            maxd = self.sizes[i] - 1
            for idx in range(self.N):
                if idx == clue_idx:
                    continue
                if self.clue_id_at[idx] != -1:
                    continue
                if dist[idx] == -1 or dist[idx] > maxd:
                    continue
                # A white cell cannot be orthogonally adjacent to another clue.
                bad = False
                for n in self.neighbors[idx]:
                    cid = self.clue_id_at[n]
                    if cid != -1 and cid != i:
                        bad = True
                        break
                if not bad:
                    mask |= self.cell_bits[idx]
            island_possible_masks[i] = mask

        domains = [self.BLACK] * self.N
        for idx in range(self.N):
            clue_id = self.clue_id_at[idx]
            if clue_id != -1:
                domains[idx] = self.ISLAND_BITS[clue_id]
            else:
                d = self.BLACK
                bit = self.cell_bits[idx]
                for i in range(self.K):
                    if island_possible_masks[i] & bit:
                        d |= self.ISLAND_BITS[i]
                domains[idx] = d
        return domains

    def analyze(self, domains):
        fixed_black_mask = 0
        possible_black_mask = 0

        fixed_masks = [0] * self.K
        possible_masks = [0] * self.K
        fixed_counts = [0] * self.K
        possible_counts = [0] * self.K
        singleton_islands = []

        for idx, d in enumerate(domains):
            bit = self.cell_bits[idx]
            if d & self.BLACK:
                possible_black_mask |= bit
            if d == self.BLACK:
                fixed_black_mask |= bit

            if d == self.BLACK:
                continue

            if d in self.singleton_to_island:
                i = self.singleton_to_island[d]
                fixed_masks[i] |= bit
                possible_masks[i] |= bit
                fixed_counts[i] += 1
                possible_counts[i] += 1
                singleton_islands.append((idx, i))
            else:
                x = d & ~self.BLACK
                while x:
                    lsb = x & -x
                    i = self.island_bit_to_id[lsb]
                    possible_masks[i] |= bit
                    possible_counts[i] += 1
                    x ^= lsb

        return {
            "fixed_black_mask": fixed_black_mask,
            "possible_black_mask": possible_black_mask,
            "fixed_counts": fixed_counts,
            "possible_counts": possible_counts,
            "fixed_masks": fixed_masks,
            "possible_masks": possible_masks,
            "singleton_islands": singleton_islands,
        }

    def _restrict(self, domains, idx, keep_mask):
        old = domains[idx]
        new = old & keep_mask
        if new == 0:
            return False, True
        if new != old:
            domains[idx] = new
            return True, False
        return False, False

    def _remove(self, domains, idx, remove_mask):
        old = domains[idx]
        new = old & ~remove_mask
        if new == 0:
            return False, True
        if new != old:
            domains[idx] = new
            return True, False
        return False, False

    def get_shapes(self, island_id, allowed_mask, required_mask):
        root = self.clue_cells[island_id]
        size = self.sizes[island_id]

        allowed_mask = self.flood_from_cell(root, allowed_mask)
        if (required_mask & ~allowed_mask) != 0:
            return []

        if allowed_mask.bit_count() < size:
            return []

        if size == 1:
            root_mask = self.cell_bits[root]
            return [root_mask] if required_mask == root_mask else []

        if required_mask.bit_count() > size:
            return []

        if required_mask.bit_count() == size:
            if self.flood_from_cell(root, required_mask) == required_mask:
                return [required_mask]
            return []

        if allowed_mask.bit_count() == size:
            if self.flood_from_cell(root, allowed_mask) == allowed_mask and (required_mask & ~allowed_mask) == 0:
                return [allowed_mask]
            return []

        key = (allowed_mask, required_mask)
        cached = self.shape_cache[island_id].get(key)
        if cached is not None:
            return cached

        root_mask = self.cell_bits[root]
        req = required_mask
        dist = self.dist_from_clue[island_id]
        results = []
        seen = {root_mask}

        def dfs(cur_mask):
            cur_size = cur_mask.bit_count()
            missing_req = req & ~cur_mask
            if missing_req.bit_count() > size - cur_size:
                return

            if cur_size == size:
                if missing_req == 0:
                    results.append(cur_mask)
                return

            frontier = self.neighbor_union(cur_mask) & allowed_mask & ~cur_mask
            if frontier == 0:
                return

            cand = list(self.iter_indices(frontier))
            if missing_req:
                cand.sort(key=lambda idx: (0 if (req & self.cell_bits[idx]) else 1, dist[idx], idx))
            else:
                cand.sort(key=lambda idx: (dist[idx], idx))

            for idx in cand:
                bit = self.cell_bits[idx]
                new_mask = cur_mask | bit
                if new_mask in seen:
                    continue
                seen.add(new_mask)
                dfs(new_mask)

        dfs(root_mask)
        self.shape_cache[island_id][key] = results
        return results

    def propagate(self, domains):
        while True:
            for d in domains:
                if d == 0:
                    return None

            info = self.analyze(domains)
            fixed_black_mask = info["fixed_black_mask"]
            possible_black_mask = info["possible_black_mask"]
            fixed_counts = info["fixed_counts"]
            possible_counts = info["possible_counts"]
            fixed_masks = info["fixed_masks"]
            possible_masks = info["possible_masks"]
            singleton_islands = info["singleton_islands"]

            fixed_black_count = fixed_black_mask.bit_count()
            possible_black_count = possible_black_mask.bit_count()

            if fixed_black_count > self.target_black or possible_black_count < self.target_black:
                return None

            for i in range(self.K):
                if fixed_counts[i] > self.sizes[i]:
                    return None
                if possible_counts[i] < self.sizes[i]:
                    return None

            # Exact black count reached.
            changed = False
            if fixed_black_count == self.target_black:
                for idx, d in enumerate(domains):
                    if d != self.BLACK and (d & self.BLACK):
                        ch, fail = self._remove(domains, idx, self.BLACK)
                        if fail:
                            return None
                        changed |= ch
                if changed:
                    continue

            if possible_black_count == self.target_black:
                for idx, d in enumerate(domains):
                    if d != self.BLACK and (d & self.BLACK):
                        ch, fail = self._restrict(domains, idx, self.BLACK)
                        if fail:
                            return None
                        changed |= ch
                if changed:
                    continue

            # White cells adjacent to a confirmed island cell may only be that island.
            changed = False
            for idx, island_id in singleton_islands:
                keep = self.BLACK | self.ISLAND_BITS[island_id]
                for n in self.neighbors[idx]:
                    ch, fail = self._restrict(domains, n, keep)
                    if fail:
                        return None
                    changed |= ch
            if changed:
                continue

            # Completed islands force their border to black.
            changed = False
            for i in range(self.K):
                if fixed_counts[i] == self.sizes[i]:
                    if self.flood_from_cell(self.clue_cells[i], fixed_masks[i]) != fixed_masks[i]:
                        return None
                    border = self.neighbor_union(fixed_masks[i]) & ~fixed_masks[i]
                    for idx in self.iter_indices(border):
                        ch, fail = self._restrict(domains, idx, self.BLACK)
                        if fail:
                            return None
                        changed |= ch
            if changed:
                continue

            # Only clue-connected cells can belong to an island.
            changed = False
            for i in range(self.K):
                bit_i = self.ISLAND_BITS[i]
                comp = self.flood_from_cell(self.clue_cells[i], possible_masks[i])
                if (fixed_masks[i] & ~comp) != 0:
                    return None
                if comp.bit_count() < self.sizes[i]:
                    return None

                unreachable = possible_masks[i] & ~comp
                if unreachable:
                    for idx in self.iter_indices(unreachable):
                        ch, fail = self._remove(domains, idx, bit_i)
                        if fail:
                            return None
                        changed |= ch
                    break

                if comp.bit_count() == self.sizes[i]:
                    for idx in self.iter_indices(comp):
                        ch, fail = self._restrict(domains, idx, bit_i)
                        if fail:
                            return None
                        changed |= ch
                    break

                # Single expansion point: must grow there.
                if fixed_counts[i] < self.sizes[i]:
                    frontier = self.neighbor_union(fixed_masks[i]) & comp & ~fixed_masks[i]
                    if frontier == 0:
                        return None
                    if frontier.bit_count() == 1:
                        only_idx = (frontier & -frontier).bit_length() - 1
                        ch, fail = self._restrict(domains, only_idx, bit_i)
                        if fail:
                            return None
                        changed |= ch
                        break
            if changed:
                continue

            # If an island has exactly size many remaining possible cells, they are all white in that island.
            changed = False
            for i in range(self.K):
                if possible_counts[i] == self.sizes[i]:
                    bit_i = self.ISLAND_BITS[i]
                    for idx in self.iter_indices(possible_masks[i]):
                        ch, fail = self._restrict(domains, idx, bit_i)
                        if fail:
                            return None
                        changed |= ch
                    break
            if changed:
                continue

            # 2x2 black rule.
            changed = False
            for a, b, c, d in self.blocks_2x2:
                cells = (a, b, c, d)
                black_fixed = 0
                last = None
                for idx in cells:
                    if domains[idx] == self.BLACK:
                        black_fixed += 1
                    else:
                        last = idx
                if black_fixed == 4:
                    return None
                if black_fixed == 3 and last is not None and (domains[last] & self.BLACK):
                    ch, fail = self._remove(domains, last, self.BLACK)
                    if fail:
                        return None
                    changed |= ch
            if changed:
                continue

            # All black cells must stay connectable.
            changed = False
            if fixed_black_mask:
                start = fixed_black_mask & -fixed_black_mask
                comp = self.flood_from_sources(start, possible_black_mask)
                if (fixed_black_mask & ~comp) != 0:
                    return None
                unreachable_black = possible_black_mask & ~comp
                if unreachable_black:
                    for idx in self.iter_indices(unreachable_black):
                        ch, fail = self._remove(domains, idx, self.BLACK)
                        if fail:
                            return None
                        changed |= ch
                    if changed:
                        continue

            # Exact island-shape filtering.
            shapes = {}
            shape_changed = False
            for i in range(self.K):
                bit_i = self.ISLAND_BITS[i]
                shp = self.get_shapes(i, possible_masks[i], fixed_masks[i])
                if not shp:
                    return None
                shapes[i] = shp

                union = 0
                inter = shp[0]
                for s in shp:
                    union |= s
                    inter &= s

                removable = possible_masks[i] & ~union
                if removable:
                    for idx in self.iter_indices(removable):
                        ch, fail = self._remove(domains, idx, bit_i)
                        if fail:
                            return None
                        shape_changed |= ch
                    break

                forced = inter & ~fixed_masks[i]
                if forced:
                    for idx in self.iter_indices(forced):
                        ch, fail = self._restrict(domains, idx, bit_i)
                        if fail:
                            return None
                        shape_changed |= ch
                    break

            if shape_changed:
                continue

            return domains, shapes

    def order_cell_values(self, idx, mask, domains):
        island_vals = []
        x = mask & ~self.BLACK
        while x:
            lsb = x & -x
            island_vals.append(lsb)
            x ^= lsb

        def score(bit):
            s = 0
            for n in self.neighbors[idx]:
                if domains[n] == bit:
                    s -= 3
                elif domains[n] & bit:
                    s -= 1
            return s

        island_vals.sort(key=score)
        out = island_vals[:]
        if mask & self.BLACK:
            out.append(self.BLACK)
        return out

    def all_singleton(self, domains):
        for d in domains:
            if d & (d - 1):
                return False
        return True

    def final_validate(self, domains):
        if not self.all_singleton(domains):
            return False

        black_mask = 0
        island_masks = [0] * self.K

        for idx, d in enumerate(domains):
            bit = self.cell_bits[idx]
            if d == self.BLACK:
                black_mask |= bit
            elif d in self.singleton_to_island:
                island_masks[self.singleton_to_island[d]] |= bit
            else:
                return False

        if black_mask.bit_count() != self.target_black:
            return False

        for a, b, c, d in self.blocks_2x2:
            if domains[a] == domains[b] == domains[c] == domains[d] == self.BLACK:
                return False

        if black_mask:
            start = black_mask & -black_mask
            if self.flood_from_sources(start, black_mask) != black_mask:
                return False

        for i in range(self.K):
            mask = island_masks[i]
            if mask.bit_count() != self.sizes[i]:
                return False
            if not (mask & self.cell_bits[self.clue_cells[i]]):
                return False
            if self.flood_from_cell(self.clue_cells[i], mask) != mask:
                return False

        return True

    def search(self, domains):
        propagated = self.propagate(domains[:])
        if propagated is None:
            return None

        domains, shapes = propagated
        state_key = tuple(domains)
        if state_key in self.dead_states:
            return None

        if self.all_singleton(domains):
            if self.final_validate(domains):
                return domains
            self.dead_states.add(state_key)
            return None

        best_cell = None
        best_cell_size = 10**9
        for idx, d in enumerate(domains):
            bc = d.bit_count()
            if 1 < bc < best_cell_size:
                best_cell = idx
                best_cell_size = bc
                if bc == 2:
                    break

        best_island = None
        best_shape_count = 10**9
        for i, shp in shapes.items():
            cnt = len(shp)
            if 1 < cnt < best_shape_count:
                best_shape_count = cnt
                best_island = i

        use_cell = False
