            row = []
            for c in range(self.C):
                idx = self.idx(r, c)
                row.append('B' if domains[idx] == self.BLACK else None)
            out.append(row)
        return out


def solve(observation):
    data = observation.get('data')
    if not isinstance(data, list) or not data or not isinstance(data[0], list):
        return "No Solution"
    width = len(data[0])
    if width == 0 or any(len(row) != width for row in data):
        return "No Solution"

    solver = NurikabeSolver(data)
    result = solver.solve()
    if result is None:
        return "No Solution"
    return repr(solver.format_answer(result))


