                    self.neighbors[idx].append(n)
                    mask |= self.cell_bits[n]
                if c > 0:
                    n = self.idx(r, c - 1)
                    self.neighbors[idx].append(n)
                    mask |= self.cell_bits[n]
                if c + 1 < self.C:
