            x ^= lsb

        def score(bit):
            s = 0
            for n in self.neighbors[idx]:
                if domains[n] == bit:
                    s -= 3
                elif domains[n] & bit:
                    s -= 1
            return s

        island_vals.sort(key=score)
        out = island_vals[:]
        if mask & self.BLACK:
            out.append(self.BLACK)
        return out

    def all_singleton(self, domains):
        for d in domains:
            if d & (d - 1):
                return False
        return True

    def final_validate(self, domains):
        if not self.all_singleton(domains):
            return False

        black_mask = 0
        island_masks = [0] * self.K

        for idx, d in enumerate(domains):
            bit = self.cell_bits[idx]
            if d == self.BLACK:
                black_mask |= bit
            elif d in self.singleton_to_island:
                island_masks[self.singleton_to_island[d]] |= bit
            else:
                return False

        if black_mask.bit_count() != self.target_black:
            return False

        for a, b, c, d in self.blocks_2x2:
            if domains[a] == domains[b] == domains[c] == domains[d] == self.BLACK:
                return False

        if black_mask:
            start = black_mask & -black_mask
            if self.flood_from_sources(start, black_mask) != black_mask:
                return False

        for i in range(self.K):
            mask = island_masks[i]
            if mask.bit_count() != self.sizes[i]:
                return False
            if not (mask & self.cell_bits[self.clue_cells[i]]):
                return False
            if self.flood_from_cell(self.clue_cells[i], mask) != mask:
                return False

        return True

    def search(self, domains):
        propagated = self.propagate(domains[:])
        if propagated is None:
            return None

        domains, shapes = propagated
        state_key = tuple(domains)
        if state_key in self.dead_states:
            return None

        if self.all_singleton(domains):
            if self.final_validate(domains):
                return domains
            self.dead_states.add(state_key)
            return None

        best_cell = None
        best_cell_size = 10**9
        for idx, d in enumerate(domains):
            bc = d.bit_count()
            if 1 < bc < best_cell_size:
                best_cell = idx
                best_cell_size = bc
                if bc == 2:
                    break

        best_island = None
        best_shape_count = 10**9
        for i, shp in shapes.items():
            cnt = len(shp)
            if 1 < cnt < best_shape_count:
                best_shape_count = cnt
                best_island = i

        use_cell = False
        if best_cell is not None:
            if best_island is None:
                use_cell = True
            elif best_cell_size <= 2:
                use_cell = True
            elif best_shape_count > 20 and best_cell_size <= 3:
                use_cell = True

        if use_cell:
            idx = best_cell
            for val in self.order_cell_values(idx, domains[idx], domains):
                new_domains = domains[:]
                new_domains[idx] = val
                res = self.search(new_domains)
                if res is not None:
                    return res
        else:
            i = best_island
            bit_i = self.ISLAND_BITS[i]
            for shape in shapes[i]:
                new_domains = domains[:]
                ok = True
                for idx in range(self.N):
                    in_shape = bool(shape & self.cell_bits[idx])
                    if in_shape:
                        new = new_domains[idx] & bit_i
                    else:
                        new = new_domains[idx] & ~bit_i
                    if new == 0:
                        ok = False
                        break
                    new_domains[idx] = new
                if not ok:
                    continue
                res = self.search(new_domains)
                if res is not None:
                    return res

        self.dead_states.add(state_key)
        return None

    def solve(self):
        if self.R == 0 or self.C == 0:
            return None
        if self.target_black < 0:
            return None
        if self.K == 0:
            return None
        return self.search(self.initial_domains)

    def format_answer(self, domains):
        out = []
        for r in range(self.R):
            row = []
            for c in range(self.C):
                idx = self.idx(r, c)
                row.append('B' if domains[idx] == self.BLACK else None)
            out.append(row)
        return out


def solve(observation):
    data = observation.get('data')
    if not isinstance(data, list) or not data or not isinstance(data[0], list):
        return "No Solution"
    width = len(data[0])
    if width == 0 or any(len(row) != width for row in data):
        return "No Solution"

    solver = NurikabeSolver(data)
    result = solver.solve()
    if result is None:
        return "No Solution"
    return repr(solver.format_answer(result))


if __name__ == "__main__":
