            for idx in cells:
                new_state = list(state)
                new_state[idx] = bit
                res = dfs(tuple(new_state))
                if res is not None:
                    return res

        failed.add(state)
        return None

    def verify(solution_state):
        if solution_state is None or not all(single(d) for d in solution_state):
            return False
        grid = [[bit_to_value(solution_state[r * N + c]) for c in range(N)] for r in range(N)]
