    cell_subsets = []
    for mask in range(1, 1 << n):
        size = mask.bit_count()
        if 1 < size < n:
            positions = []
            tmp = mask
            while tmp:
                lsb = tmp & -tmp
                positions.append(lsb.bit_length() - 1)
                tmp -= lsb
