                    support = allow_cons[domains[b]] if cons else allow_non[domains[b]]
                    nd = domains[a] & support
                    if nd == 0:
                        return None
                    if nd != domains[a]:
                        domains[a] = nd
                        changed = True
                        arc_changed = True

            if not changed:
