        col = cols[col_of[i]]
        vals = []
        tmp = domains[i]
        while tmp:
            bit = tmp & -tmp
            tmp -= bit
            v = bit.bit_length()

            # Fail-fast branching: prefer the value that squeezes peers/neighbors most.
            peer_hits = 0
            for j in row:
                if j != i and (domains[j] & bit):
                    peer_hits += 1
            for j in col:
                if j != i and (domains[j] & bit):
                    peer_hits += 1

            rel_support = 0
