                support = (cons_masks[v] if cons else non_masks[v]) & domains[nb]
                rel_support += support.bit_count()

            vals.append((rel_support, -peer_hits, v))

        vals.sort()
        return [1 << (v - 1) for _, _, v in vals]

    def search(domains):
        domains = propagate(domains, use_failed_literal=True)
        if domains is None:
            return None

        state = tuple(domains)
        if state in dead:
            return None

        if all(d & (d - 1) == 0 for d in domains):
            return domains

        i = select_cell(domains)
        for bit in ordered_values(domains, i):
            trial = list(domains)
            trial[i] = bit
            solved = search(trial)
            if solved is not None:
                return solved

        dead.add(state)
        return None

    def validate(grid):
        target = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != target:
                return False
        for c in range(n):
            if {grid[r][c] for r in range(n)} != target:
                return False
        for r in range(n):
            for c in range(n):
                if c + 1 < n:
                    want = (2 * r, 2 * c + 1) in dot_set
                    have = abs(grid[r][c] - grid[r][c + 1]) == 1
                    if want != have:
                        return False
                if r + 1 < n:
                    want = (2 * r + 1, 2 * c) in dot_set
                    have = abs(grid[r][c] - grid[r + 1][c]) == 1
                    if want != have:
                        return False
        return True

    solved = search(domains)
    if solved is None:
        return "No Solution"

    grid = [[solved[idx(r, c)].bit_length() for c in range(n)] for r in range(n)]
    if not validate(grid):
        return "No Solution"
    return str(grid)


