                b = idx(r + 1, c)
                cons = (2 * r + 1, 2 * c) in dot_set
                neighbors[a].append((b, cons))
                neighbors[b].append((a, cons))
                arcs.append((a, b, cons))
                arcs.append((b, a, cons))

    # Value-based support masks.
    cons_masks = [0] * (n + 1)
    non_masks = [0] * (n + 1)
    for v in range(1, n + 1):
        bit = 1 << (v - 1)
        cons = 0
        if v > 1:
            cons |= 1 << (v - 2)
        if v < n:
            cons |= 1 << v
        cons_masks[v] = cons
        # Adjacent cells are in the same row/column, so equality is also disallowed.
        non_masks[v] = full & ~cons & ~bit

    # Fast arc-support lookup: given neighbor domain, which values remain possible here?
    allow_cons = [0] * (full + 1)
    allow_non = [0] * (full + 1)
    for other in range(full + 1):
        keep_c = 0
        keep_n = 0
        for v in range(1, n + 1):
            bit = 1 << (v - 1)
            if cons_masks[v] & other:
                keep_c |= bit
            if non_masks[v] & other:
                keep_n |= bit
        allow_cons[other] = keep_c
        allow_non[other] = keep_n

    # Exhaustive Hall-style subset reasoning per unit.
    cell_subsets = []
    for mask in range(1, 1 << n):
        size = mask.bit_count()
        if 1 < size < n:
            positions = []
            tmp = mask
            while tmp:
                lsb = tmp & -tmp
                positions.append(lsb.bit_length() - 1)
                tmp -= lsb
            cell_subsets.append((mask, positions, size))

    value_subsets = [(mask, mask.bit_count()) for mask in range(1, 1 << n) if 1 < mask.bit_count() < n]

    row_of = [i // n for i in range(n * n)]
    col_of = [i % n for i in range(n * n)]
    dot_degree = [sum(1 for _, cons in nbrs if cons) for nbrs in neighbors]

    domains = [full] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
