        # Basic all-different pruning from already fixed values.
        fixed = 0
        for i in unit:
            d = domains[i]
            if d == 0:
                return None
            if d & (d - 1) == 0:
                if fixed & d:
                    return None
                fixed |= d

        if fixed:
            for i in unit:
                d = domains[i]
                if d & (d - 1):
                    nd = d & ~fixed
                    if nd == 0:
                        return None
                    if nd != d:
                        domains[i] = nd
                        changed = True

        # Hidden singles.
        for shift in range(n):
            vbit = 1 << shift
            pos = -1
            count = 0
            for i in unit:
                if domains[i] & vbit:
                    count += 1
                    pos = i
            if count == 0:
                return None
            if count == 1 and domains[pos] != vbit:
                domains[pos] = vbit
                changed = True

        # Naked subsets / Hall sets on cells.
        for subset_mask, positions, size in cell_subsets:
            union = 0
            for p in positions:
                union |= domains[unit[p]]
            count = union.bit_count()
            if count < size:
                return None
            if count == size:
                for p, i in enumerate(unit):
                    if not ((subset_mask >> p) & 1):
                        nd = domains[i] & ~union
                        if nd == 0:
