                        if nd != domains[i]:
                            domains[i] = nd
                            changed = True

        # Hidden subsets / dual Hall sets on values.
        for vals, size in value_subsets:
            positions = 0
            for p, i in enumerate(unit):
                if domains[i] & vals:
                    positions |= 1 << p
            count = positions.bit_count()
            if count < size:
                return None
            if count == size:
                tmp = positions
                while tmp:
                    lsb = tmp & -tmp
                    p = lsb.bit_length() - 1
                    i = unit[p]
                    nd = domains[i] & vals
                    if nd == 0:
                        return None
                    if nd != domains[i]:
                        domains[i] = nd
                        changed = True
                    tmp -= lsb

        return changed

    def failed_literal(domains):
