                if nd != domains[i]:
                    domains[i] = nd
                    return True
        return False

    def propagate(domains, use_failed_literal=True):
        while True:
            changed = False

            # Latin-square reasoning.
            for unit in units:
                res = propagate_unit(domains, unit)
                if res is None:
