    def ordered_values(domains, i):
        row = rows[row_of[i]]
        col = cols[col_of[i]]
        vals = []
        tmp = domains[i]
        while tmp:
            bit = tmp & -tmp
            tmp -= bit
            v = bit.bit_length()

