from collections import deque


class ConsecutiveLatinSolver:
    # General solver for:
    # - Latin square rows/cols 1..N exactly once
    # - orthogonally adjacent cells with a dot are consecutive
    # - orthogonally adjacent cells without a dot are NOT consecutive

    def __init__(self, observation):
        self.data = observation["data"]
        self.N = len(self.data)
        self.CELLS = self.N * self.N
        self.FULL = (1 << self.N) - 1

        self.rows = [[r * self.N + c for c in range(self.N)] for r in range(self.N)]
        self.cols = [[r * self.N + c for r in range(self.N)] for c in range(self.N)]
        self.units = self.rows + self.cols

        self.row_of = [i // self.N for i in range(self.CELLS)]
        self.col_of = [i % self.N for i in range(self.CELLS)]
        self.cell_units = [(self.row_of[i], self.N + self.col_of[i]) for i in range(self.CELLS)]

        self.peers = []
        for i in range(self.CELLS):
            r = self.row_of[i]
            c = self.col_of[i]
            s = set(self.rows[r] + self.cols[c])
            s.remove(i)
            self.peers.append(tuple(sorted(s)))

        # Precompute relation masks by value.
        self.consec_by_value = [0] * (self.N + 1)
        self.nonconsec_by_value = [0] * (self.N + 1)
        for v in range(1, self.N + 1):
            m = 0
            if v > 1:
                m |= 1 << (v - 2)
            if v < self.N:
                m |= 1 << v
            self.consec_by_value[v] = m
            self.nonconsec_by_value[v] = self.FULL ^ m

        # For a neighbor domain mask B, which values in A are supported?
        size = 1 << self.N
        self.consec_supported_by = [0] * size
        self.nonconsec_supported_by = [0] * size
        for mask in range(size):
            cm = 0
            nm = 0
            for v in range(1, self.N + 1):
                b = 1 << (v - 1)
                if self.consec_by_value[v] & mask:
                    cm |= b
                if self.nonconsec_by_value[v] & mask:
                    nm |= b
            self.consec_supported_by[mask] = cm
            self.nonconsec_supported_by[mask] = nm

        # Build all orthogonal edges; missing dot means non-consecutive.
        adj_set = {tuple(map(float, p)) for p in observation["adjacent"]}
        self.neighbors = [[] for _ in range(self.CELLS)]
        self.edge_list = []

        for r in range(self.N):
            for c in range(self.N):
                i = r * self.N + c
                if c + 1 < self.N:
                    j = r * self.N + (c + 1)
                    mid = (float(r), c + 0.5)
                    consec = mid in adj_set
                    self.neighbors[i].append((j, consec))
                    self.neighbors[j].append((i, consec))
                    self.edge_list.append((i, j, consec))
                if r + 1 < self.N:
                    j = (r + 1) * self.N + c
                    mid = (r + 0.5, float(c))
                    consec = mid in adj_set
                    self.neighbors[i].append((j, consec))
                    self.neighbors[j].append((i, consec))
                    self.edge_list.append((i, j, consec))

        self.unit_cache = {}
        self.fail_cache = set()

    def initial_domains(self):
        domains = [self.FULL] * self.CELLS
        for r in range(self.N):
            if len(self.data[r]) != self.N:
                return None
            for c in range(self.N):
                v = self.data[r][c]
                if v is not None:
                    if not (1 <= v <= self.N):
                        return None
                    domains[r * self.N + c] = 1 << (v - 1)
        return domains

    def unit_prune(self, dom_tuple):
        # Exact support propagation for an all-different unit using DP over used-value masks.
        # This is much stronger than simple singles and mimics human hidden/naked subset logic.
        cached = self.unit_cache.get(dom_tuple)
        if cached is not None or dom_tuple in self.unit_cache:
            return cached

        n = self.N
        full = self.FULL

        prefix = [0] * (n + 1)
        prefix[0] = 1  # bit 0 set => used-mask 0 reachable

        for i in range(n):
            dom = dom_tuple[i]
            reachable = prefix[i]
            nxt = 0
            while reachable:
                low = reachable & -reachable
                used = low.bit_length() - 1
                reachable -= low
                avail = dom & ~used
                a = avail
                while a:
                    bv = a & -a
                    a -= bv
                    nxt |= 1 << (used | bv)
            if nxt == 0:
                self.unit_cache[dom_tuple] = None
                return None
            prefix[i + 1] = nxt

        if ((prefix[n] >> full) & 1) == 0:
            self.unit_cache[dom_tuple] = None
            return None

        suffix = [0] * (n + 1)
        suffix[n] = 1  # used-mask 0 reachable for empty suffix

        for i in range(n - 1, -1, -1):
            dom = dom_tuple[i]
            reachable = suffix[i + 1]
            cur = 0
            while reachable:
                low = reachable & -reachable
                used = low.bit_length() - 1
                reachable -= low
                avail = dom & ~used
                a = avail
                while a:
                    bv = a & -a
                    a -= bv
                    cur |= 1 << (used | bv)
            if cur == 0:
                self.unit_cache[dom_tuple] = None
                return None
            suffix[i] = cur

        pruned = [0] * n
        for i in range(n):
            dom = dom_tuple[i]
            new_dom = 0
            d = dom
            while d:
                bv = d & -d
                d -= bv
                reachable = prefix[i]
                supported = False
                while reachable:
                    low = reachable & -reachable
                    used_pre = low.bit_length() - 1
                    reachable -= low
                    if used_pre & bv:
                        continue
                    target = full ^ (used_pre | bv)
                    if (suffix[i + 1] >> target) & 1:
                        supported = True
                        break
                if supported:
                    new_dom |= bv
            if new_dom == 0:
                self.unit_cache[dom_tuple] = None
                return None
            pruned[i] = new_dom

        result = tuple(pruned)
        self.unit_cache[dom_tuple] = result
        return result

    def propagate(self, domains, changed_cells=None):
        # Hybrid propagation:
        # 1) singleton elimination in row/col
        # 2) binary arc consistency on consecutive / non-consecutive edges
        # 3) exact all-different support pruning on each row/col
        cell_q = deque()
        unit_q = deque()
        cell_in = [False] * self.CELLS
        unit_in = [False] * (2 * self.N)

        def push_cell(i):
            if not cell_in[i]:
                cell_in[i] = True
                cell_q.append(i)

        def push_unit(u):
            if not unit_in[u]:
                unit_in[u] = True
                unit_q.append(u)

        if changed_cells is None:
            for i in range(self.CELLS):
                push_cell(i)
            for u in range(2 * self.N):
                push_unit(u)
        else:
            for i in changed_cells:
                push_cell(i)
                ru, cu = self.cell_units[i]
                push_unit(ru)
                push_unit(cu)

        while cell_q or unit_q:
            while cell_q:
                i = cell_q.popleft()
                cell_in[i] = False
                dom = domains[i]
                if dom == 0:
                    return False

                ru, cu = self.cell_units[i]
                push_unit(ru)
                push_unit(cu)

                # If fixed, eliminate from row/col peers.
                if (dom & (dom - 1)) == 0:
                    fixed = dom
                    for j in self.peers[i]:
                        nd = domains[j] & ~fixed
                        if nd != domains[j]:
                            if nd == 0:
                                return False
                            domains[j] = nd
                            push_cell(j)

                # Binary relation propagation to neighbors.
                support_mask_cache = {
                    True: self.consec_supported_by[dom],
                    False: self.nonconsec_supported_by[dom],
                }
                for j, consec in self.neighbors[i]:
                    nd = domains[j] & support_mask_cache[consec]
                    if nd != domains[j]:
                        if nd == 0:
                            return False
                        domains[j] = nd
                        push_cell(j)

            while (not cell_q) and unit_q:
                u = unit_q.popleft()
                unit_in[u] = False
                cells = self.units[u]
                dom_tuple = tuple(domains[i] for i in cells)
                pruned = self.unit_prune(dom_tuple)
                if pruned is None:
                    return False
                for i, nd in zip(cells, pruned):
                    if nd != domains[i]:
                        if nd == 0:
                            return False
                        domains[i] = nd
                        push_cell(i)

        return True

    def select_branch_cell(self, domains):
        best_i = None
        best_key = None
        for i, dom in enumerate(domains):
            cnt = dom.bit_count()
            if cnt <= 1:
                continue
            peer_sum = sum(domains[j].bit_count() for j in self.peers[i])
            consec_deg = sum(1 for _, k in self.neighbors[i] if k)
            unsolved_peers = sum(1 for j in self.peers[i] if domains[j].bit_count() > 1)
            key = (cnt, peer_sum, -consec_deg, -unsolved_peers, i)
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
        return best_i

    def order_values(self, domains, i):
        row = self.rows[self.row_of[i]]
        col = self.cols[self.col_of[i]]
        dom = domains[i]
        options = []
        d = dom
        while d:
            bv = d & -d
            d -= bv
            v = bv.bit_length()

            freq = sum(1 for j in row if domains[j] & bv) + sum(1 for j in col if domains[j] & bv)

            compat = 0
            forced = 0
            for j, consec in self.neighbors[i]:
                allowed = (self.consec_by_value[v] if consec else self.nonconsec_by_value[v]) & domains[j]
                c = allowed.bit_count()
                compat += c
                if c == 1:
                    forced += 1

            # Smaller is tried first: rarer in row/col, fewer neighbor supports, more forcing.
            options.append(((freq, compat, -forced, v), bv))

        options.sort()
        return [bv for _, bv in options]

    def search(self, domains):
        key = tuple(domains)
        if key in self.fail_cache:
            return None

        i = self.select_branch_cell(domains)
        if i is None:
            return domains

        for bv in self.order_values(domains, i):
            new_domains = domains.copy()
            new_domains[i] = bv
            if self.propagate(new_domains, [i]):
                result = self.search(new_domains)
                if result is not None:
                    return result

        self.fail_cache.add(key)
        return None

    def domains_to_grid(self, domains):
        return [[domains[r * self.N + c].bit_length() for c in range(self.N)] for r in range(self.N)]

    def validate(self, domains):
        if domains is None:
            return False
        if any((d == 0 or (d & (d - 1)) != 0) for d in domains):
            return False

        target = set(range(1, self.N + 1))
        grid = self.domains_to_grid(domains)

        for r in range(self.N):
            if set(grid[r]) != target:
                return False
        for c in range(self.N):
            if {grid[r][c] for r in range(self.N)} != target:
                return False

        for i, j, consec in self.edge_list:
            a = domains[i].bit_length()
            b = domains[j].bit_length()
            if consec:
                if abs(a - b) != 1:
                    return False
            else:
                if abs(a - b) == 1:
                    return False
        return True

    def solve(self):
        domains = self.initial_domains()
        if domains is None:
            return None
        if not self.propagate(domains):
            return None
        result = self.search(domains)
        if not self.validate(result):
            return None
        return self.domains_to_grid(result)


def solve(observation):
    solver = ConsecutiveLatinSolver(observation)
    answer = solver.solve()
    if answer is None:
        return "No Solution"
    return str(answer)


