from functools import lru_cache
import sys


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation.get("data")
    if not isinstance(data, list) or not data:
        return "No Solution"
    n = len(data)
    if any(not isinstance(row, list) or len(row) != n for row in data):
        return "No Solution"

    adjacent_raw = observation.get("adjacent", [])
    adjacent = set()
    for item in adjacent_raw:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            return "No Solution"
        adjacent.add((float(item[0]), float(item[1])))

    # Relation tables:
    # row_rels[r][c]  -> relation between (r,c) and (r,c+1)
    # col_rels[c][r]  -> relation between (r,c) and (r+1,c)
    row_rels = []
    for r in range(n):
        rels = []
        for c in range(n - 1):
            rels.append((float(r), c + 0.5) in adjacent)
        row_rels.append(tuple(rels))

    col_rels = []
    for c in range(n):
        rels = []
        for r in range(n - 1):
            rels.append((r + 0.5, float(c)) in adjacent)
        col_rels.append(tuple(rels))

    allmask = (1 << n) - 1
    size = 1 << n

    # popcount cache for domain masks and subset masks
    pc = [0] * size
    for m in range(1, size):
        pc[m] = pc[m >> 1] + (m & 1)

    # trans[1][v] = values consecutive to v
    # trans[0][v] = values non-consecutive and not equal to v
    trans = [[0] * n for _ in range(2)]
    for v in range(n):
        consec = 0
        if v > 0:
            consec |= 1 << (v - 1)
        if v + 1 < n:
            consec |= 1 << (v + 1)
        trans[1][v] = consec
        trans[0][v] = allmask ^ consec ^ (1 << v)

    domains = [[allmask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is None:
                continue
            if not isinstance(val, int) or not (1 <= val <= n):
                return "No Solution"
            domains[r][c] = 1 << (val - 1)

    # Strong line propagator:
    # A row/column must be a permutation of 1..N and satisfy every adjacent
    # consecutive / non-consecutive relation. We filter each line by dynamic
    # programming over subsets, which is much stronger than simple singles.
    @lru_cache(maxsize=None)
    def filter_line_cached(dom_tuple, rel_tuple):
        reach = [0] * size

        # Position 0
        mm = dom_tuple[0]
        while mm:
            b = mm & -mm
            mm ^= b
            reach[b] = b

        full = allmask

        # Forward DP: reach[mask] stores possible last values for that prefix.
        for mask in range(1, size):
            lasts = reach[mask]
            if not lasts:
                continue
            used = pc[mask]
            if used == n:
                continue
            pos = used - 1
            rel_idx = 1 if rel_tuple[pos] else 0
            next_domain = dom_tuple[pos + 1]

            lm = lasts
            while lm:
                lb = lm & -lm
                lm ^= lb
                v = lb.bit_length() - 1
                cand = next_domain & ~mask & trans[rel_idx][v]
                cm = cand
                while cm:
                    nb = cm & -cm
                    cm ^= nb
                    reach[mask | nb] |= nb

        if not reach[full]:
            return None

        # Backward DP: good[mask] stores last values that can complete to a full line.
        good = [0] * size
        good[full] = reach[full]

        for mask in range(full - 1, 0, -1):
            lasts = reach[mask]
            if not lasts:
                continue
            used = pc[mask]
            pos = used - 1
            rel_idx = 1 if rel_tuple[pos] else 0
            next_domain = dom_tuple[pos + 1]

            gm = 0
            lm = lasts
            while lm:
                lb = lm & -lm
                lm ^= lb
                v = lb.bit_length() - 1
                cand = next_domain & ~mask & trans[rel_idx][v]
                cm = cand
                while cm:
                    nb = cm & -cm
                    cm ^= nb
                    child = mask | nb
                    if good[child] & nb:
                        gm |= lb
                        break
            good[mask] = gm

        # Supported values per position across all complete line realizations.
        support = [0] * n
        for mask in range(1, size):
            gm = good[mask]
            if gm:
                support[pc[mask] - 1] |= gm

        out = []
        for i in range(n):
            nd = dom_tuple[i] & support[i]
            if not nd:
                return None
            out.append(nd)
        return tuple(out)

    def clone(dom):
        return [row[:] for row in dom]

    def propagate(dom):
        dirty_rows = set(range(n))
        dirty_cols = set(range(n))

        while dirty_rows or dirty_cols:
            while dirty_rows:
                r = dirty_rows.pop()
                filtered = filter_line_cached(tuple(dom[r]), row_rels[r])
                if filtered is None:
                    return None
                row = dom[r]
                for c, nd in enumerate(filtered):
                    if nd != row[c]:
                        row[c] = nd
                        dirty_cols.add(c)

            while dirty_cols:
                c = dirty_cols.pop()
                col = tuple(dom[r][c] for r in range(n))
                filtered = filter_line_cached(col, col_rels[c])
                if filtered is None:
                    return None
                for r, nd in enumerate(filtered):
                    if nd != dom[r][c]:
                        dom[r][c] = nd
                        dirty_rows.add(r)

        return dom

    def total_entropy(dom):
        s = 0
        for row in dom:
            for m in row:
                s += pc[m]
        return s

    def choice_key(r, c, m):
        # MRV first, then prefer cells involved in more dot-constraints.
        dotdeg = 0
        if c > 0 and row_rels[r][c - 1]:
            dotdeg += 1
        if c < n - 1 and row_rels[r][c]:
            dotdeg += 1
        if r > 0 and col_rels[c][r - 1]:
            dotdeg += 1
        if r < n - 1 and col_rels[c][r]:
            dotdeg += 1
        deg = (r > 0) + (r < n - 1) + (c > 0) + (c < n - 1)
        return (pc[m], -dotdeg, -deg)

    def extract_grid(dom):
        return [[cell.bit_length() for cell in row] for row in dom]

    def valid_complete(grid):
        target = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != target:
                return False
        for c in range(n):
            if {grid[r][c] for r in range(n)} != target:
                return False
        for r in range(n):
            for c in range(n - 1):
                if (abs(grid[r][c] - grid[r][c + 1]) == 1) != row_rels[r][c]:
                    return False
        for c in range(n):
            for r in range(n - 1):
                if (abs(grid[r][c] - grid[r + 1][c]) == 1) != col_rels[c][r]:
                    return False
        return True

    search_cache = {}

    def search(dom, already_propagated=False):
        if not already_propagated:
            dom = propagate(dom)
            if dom is None:
                return None

        key = tuple(cell for row in dom for cell in row)
        if key in search_cache:
            return search_cache[key]

        best = None
        best_key = None
        solved = True

        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                if m & (m - 1):
                    solved = False
                    ck = choice_key(r, c, m)
                    if best_key is None or ck < best_key:
                        best_key = ck
                        best = (r, c)

        if solved:
            grid = extract_grid(dom)
            result = grid if valid_complete(grid) else None
            search_cache[key] = result
            return result

        r, c = best
        mask = dom[r][c]

        # Look-ahead ordering: try branches that leave the smallest total entropy first.
        branches = []
        mm = mask
        while mm:
            b = mm & -mm
            mm ^= b
            nd = clone(dom)
            nd[r][c] = b
            nd = propagate(nd)
            if nd is not None:
                branches.append((total_entropy(nd), nd))

        branches.sort(key=lambda item: item[0])

        for _, nd in branches:
            result = search(nd, already_propagated=True)
            if result is not None:
                search_cache[key] = result
                return result

        search_cache[key] = None
        return None

    result = search(domains)
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

