            next_domain = dom_tuple[pos + 1]

            gm = 0
            lm = lasts
            while lm:
                lb = lm & -lm
                lm ^= lb
                v = lb.bit_length() - 1
                cand = next_domain & ~mask & trans[rel_idx][v]
