                        if new != domains[idx]:
                            domains[idx] = new
                            changed = True

        # Value-side locked subsets from exact line supports
        val_groups = {}
        for v, pb in enumerate(val_pos):
            val_groups.setdefault(pb, []).append(v)

        for pb, values in val_groups.items():
