        for r in range(self.n):
            ch = self._apply_line_supports(domains, self.rows[r], self.row_rels[r])
            if ch is None:
                return None
            changed |= ch

        for c in range(self.n):
            ch = self._apply_line_supports(domains, self.cols[c], self.col_rels[c])
            if ch is None:
                return None
            changed |= ch

        return changed

    def _propagate(self, domains):
        while True:
            changed = False

            ch = self._unit_basic_pass(domains)
            if ch is None:
                return None
            changed |= ch

            ch = self._edge_pass(domains)
            if ch is None:
                return None
            changed |= ch

            ch = self._line_pass(domains)
            if ch is None:
                return None
            changed |= ch

            if not changed:
                return domains

    def _choose_branch_cell(self, domains):
        best_idx = -1
        best_key = None

        for idx, m in enumerate(domains):
            k = m.bit_count()
            if k <= 1:
                continue

            peer_unsolved = 0
            for p in self.peers[idx]:
                if domains[p].bit_count() > 1:
                    peer_unsolved += 1

            adj_unsolved = 0
            for nb, _ in self.cell_adj[idx]:
                if domains[nb].bit_count() > 1:
                    adj_unsolved += 1

            key = (k, -(peer_unsolved + adj_unsolved))
            if best_key is None or key < best_key:
                best_key = key
                best_idx = idx

        return best_idx

    def _ordered_values(self, idx, domains):
        m = domains[idx]
        out = []

        while m:
            bit = m & -m
            m -= bit
            score = 0

            for nb, rel in self.cell_adj[idx]:
                support = self.cons_support[bit] if rel else self.noncons_support[bit]
                score += (domains[nb] & support).bit_count()

            for p in self.peers[idx]:
                if domains[p] & bit:
                    score += 1

            out.append((score, bit))

        out.sort()
        return [bit for _, bit in out]

    def _search(self, domains):
        domains = self._propagate(domains)
        if domains is None:
            return None

        state = tuple(domains)
        if state in self.dead_states:
            return None

        solved = True
        for m in domains:
            if not self._is_single(m):
                solved = False
                break

        if solved:
            grid = self._domains_to_grid(domains)
            if self._validate(grid):
                return domains
            self.dead_states.add(state)
            return None

        idx = self._choose_branch_cell(domains)
        if idx < 0:
            self.dead_states.add(state)
            return None

        for bit in self._ordered_values(idx, domains):
            new_domains = list(domains)
            new_domains[idx] = bit
            res = self._search(new_domains)
            if res is not None:
                return res

        self.dead_states.add(state)
        return None

    def run(self):
        result = self._search(list(self.initial_domains))
        if result is None:
            return None
        return self._domains_to_grid(result)


def solve(observation):
    try:
        solver = KropkiLatinSolver(observation)
        answer = solver.run()
        return "No Solution" if answer is None else str(answer)
    except Exception:
        return "No Solution"


