import sys


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation.get("data")
    adjacent = observation.get("adjacent", [])

    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    n = len(data)
    full = (1 << n) - 1

    bit_to_val = [0] * (1 << n)
