        t = int(round(x * 2))
        return t if abs(x * 2 - t) < 1e-9 else None

    for rc in adjacent:
        if not isinstance(rc, (list, tuple)) or len(rc) != 2:
            return "No Solution"
        a2 = half_int(rc[0])
        b2 = half_int(rc[1])
        if a2 is None or b2 is None:
            return "No Solution"

        if a2 % 2 == 0 and b2 % 2 == 1:
            r = a2 // 2
            c = b2 // 2
            if not (0 <= r < n and 0 <= c < n - 1):
                return "No Solution"
            row_sig[r] |= 1 << c
        elif a2 % 2 == 1 and b2 % 2 == 0:
            r = a2 // 2
            c = b2 // 2
            if not (0 <= r < n - 1 and 0 <= c < n):
                return "No Solution"
            col_sig[c] |= 1 << r
        else:
            return "No Solution"

