            score = 0
            for r, b in enumerate(cand):
                cnt = 0
                for rr in row_info[r][1]:
                    if rr[c] == b:
                        cnt += 1
                score += cnt
            scored.append((score, cand))
        scored.sort(key=lambda x: x[0])
        return [cand for _, cand in scored]

    def search(domains):
        prop = propagate(clone_domains(domains))
        if prop is None:
            return None

        domains, row_info, col_info = prop
        key = flat_key(domains)
        if key in dead:
            return None

        solved = True
        for r in range(n):
