            for c in range(n):
                k = domains[r][c].bit_count()
                if k > 1:
                    meta = (k, 1)
                    if best_meta is None or meta < best_meta:
                        best_meta = meta
                        best_action = ("cell", r, c)

        if best_action is None:
            dead.add(key)
            return None

        kind = best_action[0]

        if kind == "cell":
            _, r, c = best_action
            for b in order_cell_values(domains[r][c], r, c, row_info, col_info):
                child = clone_domains(domains)
                child[r][c] = b
                result = search(child)
                if result is not None:
                    return result

        elif kind == "row":
            _, r, candidates = best_action
            for cand in order_row_candidates(r, candidates, col_info):
                child = clone_domains(domains)
                ok = True
                for c, b in enumerate(cand):
                    if child[r][c] & b == 0:
                        ok = False
                        break
                    child[r][c] = b
                if not ok:
                    continue
                result = search(child)
                if result is not None:
                    return result

        else:
            _, c, candidates = best_action
            for cand in order_col_candidates(c, candidates, row_info):
                child = clone_domains(domains)
                ok = True
                for r, b in enumerate(cand):
                    if child[r][c] & b == 0:
                        ok = False
                        break
                    child[r][c] = b
                if not ok:
                    continue
                result = search(child)
                if result is not None:
                    return result

        dead.add(key)
        return None

    solved_domains = search(domains0)
    if solved_domains is None:
        return "No Solution"

