    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    n = len(data)
    full = (1 << n) - 1

    bit_to_val = [0] * (1 << n)
    consec_from_bit = [0] * (1 << n)
    nonconsec_from_bit = [0] * (1 << n)
    for i in range(n):
        bit = 1 << i
        bit_to_val[bit] = i + 1
        mask = 0
        if i > 0:
            mask |= 1 << (i - 1)
        if i + 1 < n:
            mask |= 1 << (i + 1)
        consec_from_bit[bit] = mask
        nonconsec_from_bit[bit] = full ^ mask

    row_sig = [0] * n
    col_sig = [0] * n

    def half_int(x):
        t = int(round(x * 2))
        return t if abs(x * 2 - t) < 1e-9 else None

    for rc in adjacent:
        if not isinstance(rc, (list, tuple)) or len(rc) != 2:
            return "No Solution"
        a2 = half_int(rc[0])
        b2 = half_int(rc[1])
        if a2 is None or b2 is None:
            return "No Solution"

        if a2 % 2 == 0 and b2 % 2 == 1:
            r = a2 // 2
            c = b2 // 2
            if not (0 <= r < n and 0 <= c < n - 1):
                return "No Solution"
            row_sig[r] |= 1 << c
        elif a2 % 2 == 1 and b2 % 2 == 0:
            r = a2 // 2
            c = b2 // 2
            if not (0 <= r < n - 1 and 0 <= c < n):
                return "No Solution"
            col_sig[c] |= 1 << r
        else:
            return "No Solution"

