    # Human-like line reasoning:
    # each row/column is a permutation of 1..N and must match the exact
    # consecutive/non-consecutive pattern implied by the dots.
    def line_info(dom_tuple, sig):
        key = (sig, dom_tuple)
        cached = line_cache.get(key)
        if cached is not None:
            return cached

        supports = [0] * n
        candidates = []

        def dfs(pos, used, prev_bit, path):
            if pos == n:
                cand = tuple(path)
                candidates.append(cand)
                for i, b in enumerate(cand):
                    supports[i] |= b
                return

            unused = full ^ used

            # Hall-style quick check on remaining digits.
            union = 0
            for j in range(pos, n):
                union |= dom_tuple[j] & unused
            if union.bit_count() < (n - pos):
                return

            mask = dom_tuple[pos] & unused
            if pos > 0:
                if (sig >> (pos - 1)) & 1:
                    mask &= consec_from_bit[prev_bit]
                else:
                    mask &= nonconsec_from_bit[prev_bit]

            while mask:
                b = mask & -mask
                mask -= b
                new_used = used | b

