                if pos + 1 < n:
                    next_mask = dom_tuple[pos + 1] & (full ^ new_used)
                    if (sig >> pos) & 1:
                        next_mask &= consec_from_bit[b]
                    else:
                        next_mask &= nonconsec_from_bit[b]
                    if next_mask == 0:
                        continue

                path.append(b)
                dfs(pos + 1, new_used, b, path)
                path.pop()

