        return result

    def clone_domains(domains):
        return [row[:] for row in domains]

    def flat_key(domains):
        return tuple(v for row in domains for v in row)

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    # Alternate row and column filtering until no more deductions remain.
    def propagate(domains):
        row_info = [None] * n
        col_info = [None] * n
        dirty_rows = set(range(n))
        dirty_cols = set(range(n))

        while dirty_rows or dirty_cols:
            while dirty_rows:
                r = dirty_rows.pop()
                dom_tuple = tuple(domains[r])
                count, supports, cands = line_info(dom_tuple, row_sig[r])
                if count == 0:
                    return None
                row_info[r] = (count, cands)
                for c in range(n):
                    new_mask = domains[r][c] & supports[c]
                    if new_mask == 0:
                        return None
                    if new_mask != domains[r][c]:
                        domains[r][c] = new_mask
                        dirty_cols.add(c)

            while dirty_cols:
                c = dirty_cols.pop()
                dom_tuple = tuple(domains[r][c] for r in range(n))
                count, supports, cands = line_info(dom_tuple, col_sig[c])
                if count == 0:
                    return None
                col_info[c] = (count, cands)
                for r in range(n):
                    new_mask = domains[r][c] & supports[r]
                    if new_mask == 0:
                        return None
                    if new_mask != domains[r][c]:
                        domains[r][c] = new_mask
                        dirty_rows.add(r)

        return domains, row_info, col_info

