    def order_cell_values(mask, r, c, row_info, col_info):
        vals = []
        row_cands = row_info[r][1]
        col_cands = col_info[c][1]
        m = mask
        while m:
            b = m & -m
            m -= b
            score = 0
            for cand in row_cands:
                if cand[c] == b:
                    score += 1
            for cand in col_cands:
                if cand[r] == b:
                    score += 1
            vals.append((score, b))
        vals.sort()
        return [b for _, b in vals]

    def order_row_candidates(r, candidates, col_info):
        scored = []
        for cand in candidates:
            score = 0
            for c, b in enumerate(cand):
                cnt = 0
                for cc in col_info[c][1]:
                    if cc[r] == b:
                        cnt += 1
                score += cnt
            scored.append((score, cand))
        scored.sort(key=lambda x: x[0])
        return [cand for _, cand in scored]

