    def search(domains):
        prop = propagate(clone_domains(domains))
        if prop is None:
            return None

        domains, row_info, col_info = prop
        key = flat_key(domains)
        if key in dead:
            return None

        solved = True
        for r in range(n):
            for c in range(n):
                if not is_single(domains[r][c]):
