        if solved:
            return domains

        best_meta = None
        best_action = None

        # Prefer smallest branching factor; break ties in favor of line choices.
        for r in range(n):
            count = row_info[r][0]
            if count > 1:
                meta = (count, 0)
                if best_meta is None or meta < best_meta:
                    best_meta = meta
                    best_action = ("row", r, row_info[r][1])

        for c in range(n):
