                    child[r][c] = b
                if not ok:
                    continue
                result = search(child)
                if result is not None:
                    return result

        else:
            _, c, candidates = best_action
            for cand in order_col_candidates(c, candidates, row_info):
                child = clone_domains(domains)
                ok = True
                for r, b in enumerate(cand):
                    if child[r][c] & b == 0:
                        ok = False
                        break
                    child[r][c] = b
                if not ok:
                    continue
                result = search(child)
                if result is not None:
                    return result

        dead.add(key)
        return None

    solved_domains = search(domains0)
    if solved_domains is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(bit_to_val[solved_domains[r][c]])
        grid.append(row)
    return str(grid)


