from collections import deque
from functools import lru_cache
import sys


def solve(observation):
    data = observation.get("data")
    adjacent = observation.get("adjacent", [])

    if not isinstance(data, list) or not data:
        return "No Solution"
    n = len(data)
    if any(not isinstance(row, list) or len(row) != n for row in data):
        return "No Solution"

    sys.setrecursionlimit(max(10000, n * n * 20))

    fullmask = (1 << n) - 1
    state_count = 1 << n
    cell_count = n * n

    # Precompute bit expansions for all masks.
    mask_bits = [None] * state_count
    for m in range(state_count):
        bits = []
        x = m
        while x:
            b = x & -x
            bits.append(b)
            x -= b
        mask_bits[m] = tuple(bits)

    # Midpoints are stored on a doubled grid to avoid float issues.
    adjset2 = set()
    for rc in adjacent:
        if not isinstance(rc, (list, tuple)) or len(rc) != 2:
            return "No Solution"
        rr = int(round(float(rc[0]) * 2))
        cc = int(round(float(rc[1]) * 2))
        adjset2.add((rr, cc))

    # Pairwise support tables for adjacency constraints.
    cons_allowed = [0] * state_count
    noncons_allowed = [0] * state_count

    forbid_same_or_consec = [0] * n
    for v in range(n):
        bit = 1 << v
        forbid = bit
        if v > 0:
            forbid |= 1 << (v - 1)
        if v + 1 < n:
            forbid |= 1 << (v + 1)
        forbid_same_or_consec[v] = forbid

    for m in range(state_count):
        cons_allowed[m] = ((m << 1) | (m >> 1)) & fullmask

        allowed = 0
        for v in range(n):
            if m & (fullmask ^ forbid_same_or_consec[v]):
                allowed |= 1 << v
        noncons_allowed[m] = allowed

    # Build units and peer structures.
    row_units = [[r * n + c for c in range(n)] for r in range(n)]
    col_units = [[r * n + c for r in range(n)] for c in range(n)]
    units = row_units + col_units

    cell_units = [[] for _ in range(cell_count)]
    for ui, cells in enumerate(units):
        for cell in cells:
            cell_units[cell].append(ui)

    peer_cells = [None] * cell_count
    for r in range(n):
        for c in range(n):
            cell = r * n + c
            peers = [r * n + cc for cc in range(n) if cc != c]
            peers.extend(rr * n + c for rr in range(n) if rr != r)
            peer_cells[cell] = tuple(peers)

    # Build orthogonal adjacency constraints.
    edges = []
    cell_edges = [[] for _ in range(cell_count)]

    def add_edge(a, b, is_dot):
        ei = len(edges)
        edges.append((a, b, is_dot))
        cell_edges[a].append(ei)
        cell_edges[b].append(ei)

    for r in range(n):
        for c in range(n):
            a = r * n + c
            if c + 1 < n:
                b = r * n + (c + 1)
                is_dot = (2 * r, 2 * c + 1) in adjset2
                add_edge(a, b, is_dot)
            if r + 1 < n:
                b = (r + 1) * n + c
                is_dot = (2 * r + 1, 2 * c) in adjset2
                add_edge(a, b, is_dot)

    cell_degree = [len(cell_edges[i]) for i in range(cell_count)]

    # Initial domains from clues.
    initial = [fullmask] * cell_count
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= n):
                return "No Solution"
            initial[r * n + c] = 1 << (v - 1)

    @lru_cache(maxsize=None)
    def unit_filter(masks):
        # Exact all-different GAC via subset DP on values.
        # Feasible because Kropki Latin puzzles are typically <= 9x9.
        if any(m == 0 for m in masks):
            return None

        size = len(masks)

        fwd = [[False] * state_count for _ in range(size + 1)]
        fwd[0][0] = True
        for i, dom in enumerate(masks):
            prev = fwd[i]
            nxt = fwd[i + 1]
            for used in range(state_count):
                if not prev[used]:
                    continue
                for bit in mask_bits[dom & (fullmask ^ used)]:
                    nxt[used | bit] = True

        if not fwd[size][fullmask]:
            return None

        suf = [[False] * state_count for _ in range(size + 1)]
        suf[size][0] = True
        for i in range(size - 1, -1, -1):
            dom = masks[i]
            curr = suf[i]
            nxt = suf[i + 1]
            for subset in range(state_count):
                for bit in mask_bits[dom & subset]:
                    if nxt[subset ^ bit]:
                        curr[subset] = True
                        break

        supported = [0] * size
        for i, dom in enumerate(masks):
            prev = fwd[i]
            nxt = suf[i + 1]
            sup = 0
            for used in range(state_count):
                if not prev[used]:
                    continue
                remaining = fullmask ^ used
                for bit in mask_bits[dom & remaining]:
                    if nxt[remaining ^ bit]:
                        sup |= bit
            if sup == 0:
                return None
            supported[i] = sup

        return tuple(supported)

    @lru_cache(maxsize=None)
    def propagate_state(state):
        domains = list(state)
        if any(d == 0 for d in domains):
            return None

        pending = deque()
        queued_edge = [False] * len(edges)
        queued_unit = [False] * len(units)

        def enqueue_edge(ei):
            if not queued_edge[ei]:
                queued_edge[ei] = True
                pending.append((0, ei))

        def enqueue_unit(ui):
            if not queued_unit[ui]:
                queued_unit[ui] = True
                pending.append((1, ui))

        def note_change(cell):
            for ei in cell_edges[cell]:
                enqueue_edge(ei)
            for ui in cell_units[cell]:
                enqueue_unit(ui)

        for ei in range(len(edges)):
            enqueue_edge(ei)
        for ui in range(len(units)):
            enqueue_unit(ui)

        while pending:
            typ, idx = pending.popleft()

            if typ == 0:
                queued_edge[idx] = False
                a, b, is_dot = edges[idx]
                table = cons_allowed if is_dot else noncons_allowed

                da = domains[a]
                db = domains[b]

                nda = da & table[db]
                if nda == 0:
                    return None
                if nda != da:
                    domains[a] = nda
                    note_change(a)

                da = domains[a]
                ndb = db & table[da]
                if ndb == 0:
                    return None
                if ndb != db:
                    domains[b] = ndb
                    note_change(b)

            else:
                queued_unit[idx] = False
                cells = units[idx]
                masks = tuple(domains[cell] for cell in cells)
                filtered = unit_filter(masks)
                if filtered is None:
                    return None

                for cell, new_mask in zip(cells, filtered):
                    if new_mask == 0:
                        return None
                    if new_mask != domains[cell]:
                        domains[cell] = new_mask
                        note_change(cell)

        return tuple(domains)

    def choose_branch_cell(state):
        best_cell = -1
        best_key = None
        for cell, dom in enumerate(state):
            size = dom.bit_count()
            if size <= 1:
                continue
            peer_slack = 0
            for p in peer_cells[cell]:
                peer_slack += state[p].bit_count()
            key = (size, -cell_degree[cell], peer_slack, cell)
            if best_key is None or key < best_key:
                best_key = key
                best_cell = cell
        return best_cell

    def order_values(cell, state):
        dom = state[cell]
        ordered = []

        for bit in mask_bits[dom]:
            # Quick local contradictions.
            bad = False
            for p in peer_cells[cell]:
                if state[p] == bit:
                    bad = True
                    break
            if bad:
                continue

            adj_slack = 0
            peer_hits = 0

            for p in peer_cells[cell]:
                if state[p] & bit:
                    peer_hits += 1

            for ei in cell_edges[cell]:
                a, b, is_dot = edges[ei]
                other = b if a == cell else a
                other_dom = state[other]
                allowed = cons_allowed[bit] if is_dot else noncons_allowed[bit]
                remain = (other_dom & allowed).bit_count()
                if remain == 0:
                    bad = True
                    break
                adj_slack += remain

            if not bad:
                ordered.append((adj_slack, -peer_hits, bit.bit_length(), bit))

        ordered.sort()
        return [bit for _, __, ___, bit in ordered]

    @lru_cache(maxsize=None)
    def search(state):
        reduced = propagate_state(state)
        if reduced is None:
            return None
        if reduced != state:
            return search(reduced)

        solved = True
        for d in reduced:
            if d & (d - 1):
                solved = False
                break
        if solved:
            return reduced

        cell = choose_branch_cell(reduced)
        if cell < 0:
            return None

        for bit in order_values(cell, reduced):
            child = list(reduced)
            child[cell] = bit
            result = search(tuple(child))
            if result is not None:
                return result

        return None

    def decode(state):
        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                bit = state[r * n + c]
                if bit == 0 or (bit & (bit - 1)):
                    return None
                row.append(bit.bit_length())
            grid.append(row)
        return grid

    def verify(grid):
        target = set(range(1, n + 1))

        if grid is None or len(grid) != n or any(len(row) != n for row in grid):
            return False

        for r in range(n):
            if set(grid[r]) != target:
                return False

        for c in range(n):
            if set(grid[r][c] for r in range(n)) != target:
                return False

        for r in range(n):
            for c in range(n - 1):
                want_dot = (2 * r, 2 * c + 1) in adjset2
                got_dot = abs(grid[r][c] - grid[r][c + 1]) == 1
                if want_dot != got_dot:
                    return False

        for r in range(n - 1):
            for c in range(n):
                want_dot = (2 * r + 1, 2 * c) in adjset2
                got_dot = abs(grid[r][c] - grid[r + 1][c]) == 1
                if want_dot != got_dot:
                    return False

        return True

    solution_state = search(tuple(initial))
    if solution_state is None:
        return "No Solution"

    grid = decode(solution_state)
    if not verify(grid):
        return "No Solution"

    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

