    adjset2 = set()
    for rc in adjacent:
        if not isinstance(rc, (list, tuple)) or len(rc) != 2:
            return "No Solution"
        rr = int(round(float(rc[0]) * 2))
        cc = int(round(float(rc[1]) * 2))
        adjset2.add((rr, cc))

    # Pairwise support tables for adjacency constraints.
    cons_allowed = [0] * state_count
    noncons_allowed = [0] * state_count

    forbid_same_or_consec = [0] * n
    for v in range(n):
        bit = 1 << v
        forbid = bit
        if v > 0:
            forbid |= 1 << (v - 1)
        if v + 1 < n:
            forbid |= 1 << (v + 1)
        forbid_same_or_consec[v] = forbid

    for m in range(state_count):
        cons_allowed[m] = ((m << 1) | (m >> 1)) & fullmask

        allowed = 0
        for v in range(n):
            if m & (fullmask ^ forbid_same_or_consec[v]):
                allowed |= 1 << v
        noncons_allowed[m] = allowed

