    for r in range(n):
        for c in range(n):
            cell = r * n + c
            peers = [r * n + cc for cc in range(n) if cc != c]
            peers.extend(rr * n + c for rr in range(n) if rr != r)
            peer_cells[cell] = tuple(peers)

