        # Feasible because Kropki Latin puzzles are typically <= 9x9.
        if any(m == 0 for m in masks):
            return None

        size = len(masks)

        fwd = [[False] * state_count for _ in range(size + 1)]
        fwd[0][0] = True
        for i, dom in enumerate(masks):
            prev = fwd[i]
            nxt = fwd[i + 1]
            for used in range(state_count):
                if not prev[used]:
                    continue
                for bit in mask_bits[dom & (fullmask ^ used)]:
                    nxt[used | bit] = True

