                pending.append((0, ei))

        def enqueue_unit(ui):
            if not queued_unit[ui]:
                queued_unit[ui] = True
                pending.append((1, ui))

        def note_change(cell):
            for ei in cell_edges[cell]:
                enqueue_edge(ei)
            for ui in cell_units[cell]:
                enqueue_unit(ui)

        for ei in range(len(edges)):
            enqueue_edge(ei)
        for ui in range(len(units)):
            enqueue_unit(ui)

        while pending:
            typ, idx = pending.popleft()

            if typ == 0:
                queued_edge[idx] = False
                a, b, is_dot = edges[idx]
                table = cons_allowed if is_dot else noncons_allowed

                da = domains[a]
                db = domains[b]

                nda = da & table[db]
                if nda == 0:
