    def choose_branch_cell(state):
        best_cell = -1
        best_key = None
        for cell, dom in enumerate(state):
            size = dom.bit_count()
            if size <= 1:
                continue
            peer_slack = 0
            for p in peer_cells[cell]:
                peer_slack += state[p].bit_count()
            key = (size, -cell_degree[cell], peer_slack, cell)
            if best_key is None or key < best_key:
                best_key = key
                best_cell = cell
        return best_cell

    def order_values(cell, state):
        dom = state[cell]
        ordered = []

        for bit in mask_bits[dom]:
            # Quick local contradictions.
            bad = False
            for p in peer_cells[cell]:
                if state[p] == bit:
                    bad = True
                    break
            if bad:
                continue

            adj_slack = 0
            peer_hits = 0

            for p in peer_cells[cell]:
                if state[p] & bit:
                    peer_hits += 1

            for ei in cell_edges[cell]:
                a, b, is_dot = edges[ei]
                other = b if a == cell else a
                other_dom = state[other]
                allowed = cons_allowed[bit] if is_dot else noncons_allowed[bit]
                remain = (other_dom & allowed).bit_count()
                if remain == 0:
                    bad = True
                    break
                adj_slack += remain

            if not bad:
                ordered.append((adj_slack, -peer_hits, bit.bit_length(), bit))

        ordered.sort()
        return [bit for _, __, ___, bit in ordered]

    @lru_cache(maxsize=None)
    def search(state):
        reduced = propagate_state(state)
        if reduced is None:
            return None
        if reduced != state:
            return search(reduced)

        solved = True
        for d in reduced:
            if d & (d - 1):
                solved = False
                break
        if solved:
            return reduced

        cell = choose_branch_cell(reduced)
        if cell < 0:
            return None

        for bit in order_values(cell, reduced):
            child = list(reduced)
            child[cell] = bit
            result = search(tuple(child))
            if result is not None:
                return result

        return None

    def decode(state):
        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                bit = state[r * n + c]
                if bit == 0 or (bit & (bit - 1)):
                    return None
                row.append(bit.bit_length())
            grid.append(row)
        return grid

    def verify(grid):
        target = set(range(1, n + 1))

        if grid is None or len(grid) != n or any(len(row) != n for row in grid):
            return False

        for r in range(n):
            if set(grid[r]) != target:
                return False

        for c in range(n):
            if set(grid[r][c] for r in range(n)) != target:
                return False

        for r in range(n):
            for c in range(n - 1):
                want_dot = (2 * r, 2 * c + 1) in adjset2
                got_dot = abs(grid[r][c] - grid[r][c + 1]) == 1
                if want_dot != got_dot:
                    return False

        for r in range(n - 1):
            for c in range(n):
                want_dot = (2 * r + 1, 2 * c) in adjset2
                got_dot = abs(grid[r][c] - grid[r + 1][c]) == 1
                if want_dot != got_dot:
                    return False

        return True

    solution_state = search(tuple(initial))
    if solution_state is None:
        return "No Solution"

    grid = decode(solution_state)
    if not verify(grid):
        return "No Solution"

    return repr(grid)


