from collections import deque


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data:
        return "No Solution"

    n = len(data)
    if any(not isinstance(row, list) or len(row) != n for row in data):
        return "No Solution"

    nn = n * n
    full_mask = (1 << n) - 1

    # Parse midpoint clues.
    adj_set = set()
    for item in observation.get("adjacent", []):
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            return "No Solution"
        rr = int(round(item[0] * 2))
        cc = int(round(item[1] * 2))
        adj_set.add((rr, cc))

    row_cells = [[r * n + c for c in range(n)] for r in range(n)]
    col_cells = [[r * n + c for r in range(n)] for c in range(n)]

    # 1 = consecutive dot exists, 0 = explicitly not consecutive.
    row_rels = [tuple(1 if (2 * r, 2 * c + 1) in adj_set else 0 for c in range(n - 1)) for r in range(n)]
    col_rels = [tuple(1 if (2 * r + 1, 2 * c) in adj_set else 0 for r in range(n - 1)) for c in range(n)]

    neighbors = [[] for _ in range(nn)]
    edges = []
    for r in range(n):
        for c in range(n):
            i = r * n + c
            if c + 1 < n:
                j = i + 1
                rel = row_rels[r][c]
                edges.append((i, j, rel))
                neighbors[i].append((j, rel))
                neighbors[j].append((i, rel))
            if r + 1 < n:
                j = i + n
                rel = col_rels[c][r]
                edges.append((i, j, rel))
                neighbors[i].append((j, rel))
                neighbors[j].append((i, rel))

