    next_allowed = [[0] * (n + 1) for _ in range(2)]
    for v in range(1, n + 1):
        b = 1 << (v - 1)
        cons = 0
        if v > 1:
            cons |= 1 << (v - 2)
        if v < n:
            cons |= 1 << v
        next_allowed[1][v] = cons
        next_allowed[0][v] = full_mask & ~cons & ~b

    # For fast arc-consistency: given neighbor domain, which values here still have support?
    support_from = [[0] * (1 << n) for _ in range(2)]
    for rel in (0, 1):
        table = support_from[rel]
        allowed = next_allowed[rel]
        for m in range(1 << n):
            res = 0
            bit = 1
            for v in range(1, n + 1):
                if allowed[v] & m:
                    res |= bit
                bit <<= 1
            table[m] = res

    domains = [full_mask] * nn
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is not None:
                if not isinstance(val, int) or not (1 <= val <= n):
                    return "No Solution"
                domains[r * n + c] = 1 << (val - 1)

    # Strong human-like line reasoning:
    # For a row/column, compute all values supported by some full permutation
    # respecting the line's dot / no-dot pattern and Latin uniqueness.
    def line_support(cells, rels, dom):
        pd = [dom[i] for i in cells]
        memo = {}

        def feasible(pos, used, prev):
            key = (pos, used, prev)
            if key in memo:
                return memo[key]
            if pos == n:
                res = (used == full_mask)
            else:
                avail = pd[pos] & (full_mask ^ used)
                if pos:
                    avail &= next_allowed[rels[pos - 1]][prev]
                res = False
                a = avail
                while a:
                    b = a & -a
                    a -= b
                    if feasible(pos + 1, used | b, b.bit_length()):
                        res = True
                        break
            memo[key] = res
            return res

        if not feasible(0, 0, 0):
            return None

        supported = [0] * n
        value_pos = [0] * (n + 1)
        seen = set()

        def collect(pos, used, prev):
            key = (pos, used, prev)
            if key in seen:
                return
            seen.add(key)
            if pos == n:
                return
            avail = pd[pos] & (full_mask ^ used)
            if pos:
                avail &= next_allowed[rels[pos - 1]][prev]
            a = avail
            while a:
                b = a & -a
                a -= b
                v = b.bit_length()
                if feasible(pos + 1, used | b, v):
                    supported[pos] |= b
                    value_pos[v] |= 1 << pos
                    collect(pos + 1, used | b, v)

        collect(0, 0, 0)
        return supported, value_pos

