                supported, value_pos = res
                cells = row_cells[r]

                for p, cell in enumerate(cells):
                    nd = dom[cell] & supported[p]
                    if nd != dom[cell] and not apply(cell, nd):
                        return None

                for v in range(1, n + 1):
                    pm = value_pos[v]
                    if pm == 0:
                        return None
                    if pm & (pm - 1) == 0:
                        cell = cells[pm.bit_length() - 1]
                        bit = 1 << (v - 1)
                        if dom[cell] != bit and not apply(cell, bit):
