        return dom

    def solved(dom):
        for d in dom:
            if d == 0 or (d & (d - 1)):
                return False
        return True

    def verify(dom):
        vals = [d.bit_length() for d in dom]
        target = set(range(1, n + 1))

        for r in range(n):
            if set(vals[r * n:(r + 1) * n]) != target:
                return False

        for c in range(n):
            if set(vals[r * n + c] for r in range(n)) != target:
                return False

        for a, b, rel in edges:
            cons = abs(vals[a] - vals[b]) == 1
            if rel:
                if not cons:
                    return False
            else:
                if cons:
                    return False

        return True

    def choose_cell(dom):
        row_uns = [0] * n
        col_uns = [0] * n
        for i, d in enumerate(dom):
            if d & (d - 1):
                r, c = divmod(i, n)
                row_uns[r] += 1
                col_uns[c] += 1

        best = None
        best_key = None
        for i, d in enumerate(dom):
            bc = d.bit_count()
            if bc > 1:
                r, c = divmod(i, n)
                unresolved_neighbors = 0
                for j, _ in neighbors[i]:
                    if dom[j] & (dom[j] - 1):
                        unresolved_neighbors += 1
                key = (bc, -unresolved_neighbors, row_uns[r] + col_uns[c])
                if best_key is None or key < best_key:
                    best_key = key
                    best = i
        return best

    def order_values(i, dom):
        r, c = divmod(i, n)
        out = []
        m = dom[i]
        while m:
            b = m & -m
            m -= b
            v = b.bit_length()

            line_score = 0
            for cell in row_cells[r]:
                if dom[cell] & b:
                    line_score += 1
            for cell in col_cells[c]:
                if dom[cell] & b:
                    line_score += 1

            neighbor_score = 0
            for j, rel in neighbors[i]:
                neighbor_score += (dom[j] & next_allowed[rel][v]).bit_count()

            out.append((line_score, neighbor_score, v, b))

        out.sort()
        return [b for _, _, _, b in out]

    def search(dom):
        dom = propagate(dom[:])
        if dom is None:
            return None

        if solved(dom):
            return dom if verify(dom) else None

        i = choose_cell(dom)
        if i is None:
            return dom if verify(dom) else None

        for b in order_values(i, dom):
            new_dom = dom[:]
            new_dom[i] = b
            res = search(new_dom)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = [[result[r * n + c].bit_length() for c in range(n)] for r in range(n)]
    return repr(grid)


