from itertools import combinations
from functools import lru_cache
import sys


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation.get("data")
    adjacent = observation.get("adjacent")

    if not isinstance(data, list) or not data:
        return "No Solution"
    N = len(data)
    if any(not isinstance(row, list) or len(row) != N for row in data):
        return "No Solution"

    ALL = (1 << N) - 1
    BITS = [1 << i for i in range(N)]
    POPCOUNT = [i.bit_count() for i in range(ALL + 1)]

    def idx(r, c):
        return r * N + c

    # Parse dotted adjacencies from midpoint coordinates.
    dot_h = set()  # (r, c) means dot between (r,c) and (r,c+1)
    dot_v = set()  # (r, c) means dot between (r,c) and (r+1,c)

    for item in adjacent:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            return "No Solution"
        a, b = float(item[0]), float(item[1])
        if abs(a - round(a)) < 1e-9:
            r = int(round(a))
            c = int(b)
            if not (0 <= r < N and 0 <= c < N - 1):
                return "No Solution"
            dot_h.add((r, c))
        else:
            r = int(a)
            c = int(round(b))
            if not (0 <= r < N - 1 and 0 <= c < N):
                return "No Solution"
            dot_v.add((r, c))

    # Consecutive/non-consecutive support masks for a fixed value.
    support_dot = []
    support_no = []
    for v in range(1, N + 1):
        m = 0
        if v > 1:
            m |= 1 << (v - 2)
        if v < N:
            m |= 1 << v
        support_dot.append(m)
        support_no.append(ALL & ~m & ~(1 << (v - 1)))

    # Fast edge-revision tables: for a neighbor-domain mask, which values remain possible here?
    allowed_dot = [0] * (ALL + 1)
    allowed_no = [0] * (ALL + 1)
    for nb in range(ALL + 1):
        md = 0
        mn = 0
        for i, bit in enumerate(BITS):
            if support_dot[i] & nb:
                md |= bit
            if support_no[i] & nb:
                mn |= bit
        allowed_dot[nb] = md
        allowed_no[nb] = mn

    # Units and neighbors.
    rows = [[idx(r, c) for c in range(N)] for r in range(N)]
    cols = [[idx(r, c) for r in range(N)] for c in range(N)]
    units = rows + cols

    row_of = [i // N for i in range(N * N)]
    col_of = [i % N for i in range(N * N)]

    neighbors = [[] for _ in range(N * N)]
    dotted_degree = [0] * (N * N)
    edges = []

    for r in range(N):
        for c in range(N - 1):
            a = idx(r, c)
            b = idx(r, c + 1)
            dotted = (r, c) in dot_h
            edges.append((a, b, dotted))
            neighbors[a].append((b, dotted))
            neighbors[b].append((a, dotted))
            if dotted:
                dotted_degree[a] += 1
                dotted_degree[b] += 1

    for r in range(N - 1):
        for c in range(N):
            a = idx(r, c)
            b = idx(r + 1, c)
            dotted = (r, c) in dot_v
            edges.append((a, b, dotted))
            neighbors[a].append((b, dotted))
            neighbors[b].append((a, dotted))
            if dotted:
                dotted_degree[a] += 1
                dotted_degree[b] += 1

