    def line_candidates(pattern):
        # Generate all permutations 1..N matching the row/column's local dot pattern.
        out = []
        cur = [0] * N

        def dfs(pos, prev_value, unused_mask):
            if pos == N:
                out.append(tuple(cur))
                return
