                cand_mask = unused_mask
            else:
                cand_mask = unused_mask & (support_dot[prev_value - 1] if pattern[pos - 1] else support_no[prev_value - 1])

            x = cand_mask
            while x:
                bit = x & -x
                x -= bit
                cur[pos] = bit
                dfs(pos + 1, bit.bit_length(), unused_mask ^ bit)

