    def line_union(pattern, unit_masks):
        # Intersect current cell domains with all feasible line permutations.
        unions = [0] * N
        found = False
        for cand in line_candidates(pattern):
            ok = True
            for m, b in zip(unit_masks, cand):
                if not (m & b):
                    ok = False
                    break
