                counts = [0] * N
                last_pos = [-1] * N
                for i in unit:
                    x = dom[i]
                    while x:
                        bit = x & -x
                        x -= bit
                        k = bit.bit_length() - 1
                        counts[k] += 1
                        last_pos[k] = i

                for k, cnt in enumerate(counts):
                    if cnt == 0:
