                # Naked subsets up to size 4.
                unsolved = [i for i in unit if POPCOUNT[dom[i]] > 1]
                if len(unsolved) >= 2:
                    max_k = min(4, len(unsolved) - 1)
                    for k in range(2, max_k + 1):
                        pool = [i for i in unsolved if 1 < POPCOUNT[dom[i]] <= k]
                        if len(pool) < k:
                            continue
                        for combo in combinations(pool, k):
                            union = 0
                            for i in combo:
                                union |= dom[i]
                            pc = POPCOUNT[union]
                            if pc < k:
                                return False
                            if pc == k:
