                                        if nm != dom[j]:
                                            if nm == 0:
                                                return False
                                            dom[j] = nm
                                            changed = True

            # 3) Whole-line permutation filtering.
            for unit, pattern in line_units:
                sig = tuple(dom[i] for i in unit)
                unions = line_union(pattern, sig)
                if unions is None:
                    return False
                for i, allowed in zip(unit, unions):
                    nm = dom[i] & allowed
                    if nm != dom[i]:
                        if nm == 0:
                            return False
                        dom[i] = nm
                        changed = True

            if not changed:
                return True

