    def choose_cell(dom):
        best_i = -1
        best_key = None
        for i, m in enumerate(dom):
            pc = POPCOUNT[m]
            if pc <= 1:
                continue
            r = row_of[i]
            c = col_of[i]
            peer_unsolved = sum(POPCOUNT[dom[j]] > 1 for j in rows[r]) + sum(POPCOUNT[dom[j]] > 1 for j in cols[c]) - 2
            key = (pc, -dotted_degree[i], -peer_unsolved)
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
