    def ordered_bits(mask, i, dom):
        r = row_of[i]
        c = col_of[i]
        row_unit = rows[r]
        col_unit = cols[c]

        scored = []
        x = mask
        while x:
            bit = x & -x
            x -= bit
            scarcity = sum(1 for j in row_unit if dom[j] & bit) + sum(1 for j in col_unit if j != i and (dom[j] & bit))
            bit_index = bit.bit_length() - 1
            support_total = 0
            for nb, dotted in neighbors[i]:
                support_total += POPCOUNT[dom[nb] & (support_dot[bit_index] if dotted else support_no[bit_index])]
            scored.append((scarcity, support_total, bit.bit_length(), bit))
        scored.sort()
        return [bit for _, _, _, bit in scored]

    def dfs(dom):
        if not propagate(dom):
            return None

        key = tuple(dom)
        if key in failed:
            return None

        if all(POPCOUNT[m] == 1 for m in dom):
            return dom

        i = choose_cell(dom)
        if i < 0:
            return None

        for bit in ordered_bits(dom[i], i, dom):
            nd = dom[:]
            nd[i] = bit
            ans = dfs(nd)
            if ans is not None:
                return ans

        failed.add(key)
        return None

    solved = dfs(domains)
    if solved is None:
        return "No Solution"

    grid = [[solved[idx(r, c)].bit_length() for c in range(N)] for r in range(N)]

    # Final verification.
    target = set(range(1, N + 1))
    for r in range(N):
        if set(grid[r]) != target:
            return "No Solution"
    for c in range(N):
        if {grid[r][c] for r in range(N)} != target:
            return "No Solution"
    for r in range(N):
        for c in range(N - 1):
            if (abs(grid[r][c] - grid[r][c + 1]) == 1) != ((r, c) in dot_h):
