        return None

    solved = dfs(domains)
    if solved is None:
        return "No Solution"

    grid = [[solved[idx(r, c)].bit_length() for c in range(N)] for r in range(N)]

    # Final verification.
    target = set(range(1, N + 1))
    for r in range(N):
        if set(grid[r]) != target:
