from collections import deque
import sys

sys.setrecursionlimit(10000)

NORTH, EAST, SOUTH, WEST = 0, 1, 2, 3
DIRS = (NORTH, EAST, SOUTH, WEST)
DR = (-1, 0, 1, 0)
DC = (0, 1, 0, -1)
OPP = (SOUTH, WEST, NORTH, EAST)

EDGEBIT = (1, 2, 4, 8)

MASK_0 = 0
MASK_NS = EDGEBIT[NORTH] | EDGEBIT[SOUTH]
MASK_EW = EDGEBIT[EAST] | EDGEBIT[WEST]
MASK_NE = EDGEBIT[NORTH] | EDGEBIT[EAST]
MASK_ES = EDGEBIT[EAST] | EDGEBIT[SOUTH]
MASK_SW = EDGEBIT[SOUTH] | EDGEBIT[WEST]
MASK_WN = EDGEBIT[WEST] | EDGEBIT[NORTH]

ALLOWED_MASKS = (MASK_0, MASK_NS, MASK_EW, MASK_NE, MASK_ES, MASK_SW, MASK_WN)
BIT = {m: 1 << m for m in ALLOWED_MASKS}
ALL_BITS = sum(BIT[m] for m in ALLOWED_MASKS)
NONZERO_BITS = ALL_BITS ^ BIT[MASK_0]

INCIDENT = {
    MASK_0: (),
    MASK_NS: (NORTH, SOUTH),
    MASK_EW: (WEST, EAST),
    MASK_NE: (NORTH, EAST),
    MASK_ES: (EAST, SOUTH),
    MASK_SW: (SOUTH, WEST),
    MASK_WN: (WEST, NORTH),
}

AXIS = {
    NORTH: 0,
    SOUTH: 0,
    EAST: 1,
    WEST: 1,
}

STRAIGHT_BITS = (
    BIT[MASK_NS],  # vertical
    BIT[MASK_EW],  # horizontal
)

TURN_MASKS = (MASK_NE, MASK_ES, MASK_SW, MASK_WN)
TURN_IN_BITS = tuple(
    sum(BIT[m] for m in TURN_MASKS if m & EDGEBIT[d])
    for d in DIRS
)

USE_DIR_BITS = tuple(
    sum(BIT[m] for m in ALLOWED_MASKS if m & EDGEBIT[d])
    for d in DIRS
)

NO_USE_BITS = tuple(ALL_BITS ^ USE_DIR_BITS[d] for d in DIRS)

SINGLETON_TO_MASK = {BIT[m]: m for m in ALLOWED_MASKS}

SUPPORT = {
    d: {
        m: sum(
            BIT[n]
            for n in ALLOWED_MASKS
            if bool(m & EDGEBIT[d]) == bool(n & EDGEBIT[OPP[d]])
        )
        for m in ALLOWED_MASKS
    }
    for d in DIRS
}


def perimeter_loop(rows, cols):
    if rows < 2 or cols < 2:
        return None
    path = []
    for c in range(cols):
        path.append((0, c))
    for r in range(1, rows):
        path.append((r, cols - 1))
    for c in range(cols - 2, -1, -1):
        path.append((rows - 1, c))
    for r in range(rows - 2, 0, -1):
        path.append((r, 0))
    path.append((0, 0))
    return path


def solve(observation):
    data = observation.get("data", [])
    rows = len(data)
    cols = len(data[0]) if rows else 0
    if rows == 0 or cols == 0:
        return "No Solution"

    def vid(r, c):
        return r * cols + c

    def rc(v):
        return (v // cols, v % cols)

    V = rows * cols

    neighbors = []
    for r in range(rows):
        for c in range(cols):
            nbrs = []
            for d in DIRS:
                nr, nc = r + DR[d], c + DC[d]
                nbrs.append(vid(nr, nc) if 0 <= nr < rows and 0 <= nc < cols else -1)
            neighbors.append(tuple(nbrs))

    rays = {}
    for v in range(V):
        r, c = rc(v)
        for d in DIRS:
            rr, cc = r + DR[d], c + DC[d]
            ray = []
            while 0 <= rr < rows and 0 <= cc < cols:
                ray.append(vid(rr, cc))
                rr += DR[d]
                cc += DC[d]
