        for c in range(cols):
            v = vid(r, c)
            dom = ALL_BITS

            for d in DIRS:
                if neighbors[v][d] == -1:
                    dom &= NO_USE_BITS[d]

            token = data[r][c]
            if token is not None:
                t = token[0]
                k = int(token[1:])
                clue_info[v] = (t, k)
                dom &= NONZERO_BITS
                if t == "W":
                    dom &= white_bits
                elif t == "B":
                    dom &= black_bits
                else:
                    return "No Solution"

