    MASK_0: (),
    MASK_NS: (NORTH, SOUTH),
    MASK_EW: (WEST, EAST),
    MASK_NE: (NORTH, EAST),
    MASK_ES: (EAST, SOUTH),
    MASK_SW: (SOUTH, WEST),
    MASK_WN: (WEST, NORTH),
}

AXIS = {
    NORTH: 0,
    SOUTH: 0,
    EAST: 1,
    WEST: 1,
}

