def iter_bits(mask):
    while mask:
        lb = mask & -mask
        yield lb.bit_length() - 1
        mask ^= lb


def single_value(mask):
    return (mask & -mask).bit_length() - 1


def coord(v, size):
    return (v // size, v % size)


def in_bounds(r, c, size):
    return 0 <= r < size and 0 <= c < size


def build_puzzle(observation):
    data = observation["data"]
    size = len(data)
    if size == 0 or any(len(row) != size for row in data):
        return None

    vertex_count = size * size
    raw_clues = []
    clue_map = {}
    is_clue = [False] * vertex_count

    for r in range(size):
        for c in range(size):
            tok = data[r][c]
            if tok is not None:
                typ = tok[0]
                k = int(tok[1:])
                vid = r * size + c
                raw_clues.append({"r": r, "c": c, "vid": vid, "type": typ, "k": k})
                clue_map[vid] = (typ, k)
                is_clue[vid] = True

    neighbors = [[] for _ in range(vertex_count)]
    edges = []
    for r in range(size):
        for c in range(size):
            u = r * size + c
            if c + 1 < size:
                v = r * size + (c + 1)
                edges.append((u, v, R))
                neighbors[u].append((R, v))
                neighbors[v].append((L, u))
            if r + 1 < size:
                v = (r + 1) * size + c
                edges.append((u, v, D))
                neighbors[u].append((D, v))
                neighbors[v].append((U, u))

    initial_domains = [0] * vertex_count
    for r in range(size):
        for c in range(size):
            vid = r * size + c
            avail = 0
            for d, (dr, dc) in enumerate(DIRS):
                nr, nc = r + dr, c + dc
                if in_bounds(nr, nc, size):
                    avail |= DBIT[d]

            allowed = FULL_DOMAIN
            if vid in clue_map:
                allowed = CLUE_ALLOWED[clue_map[vid][0]]

            dom = 0
            for p in range(7):
                if allowed & PATBIT[p]:
                    if (PATTERN_BITS[p] & ~avail) == 0:
                        dom |= PATBIT[p]
            if dom == 0:
                return None
            initial_domains[vid] = dom

    clues = []
    for item in raw_clues:
        cands = generate_candidates(
            size=size,
            r=item["r"],
            c=item["c"],
            typ=item["type"],
            k=item["k"],
            clue_domain=initial_domains[item["vid"]],
            initial_domains=initial_domains,
        )
        if not cands:
            return None
        clues.append(
            {
                "vid": item["vid"],
                "r": item["r"],
                "c": item["c"],
                "type": item["type"],
                "k": item["k"],
                "candidates": cands,
            }
        )

    return {
        "size": size,
        "vertex_count": vertex_count,
        "edges": edges,
        "neighbors": neighbors,
        "initial_domains": initial_domains,
        "clues": clues,
        "is_clue": is_clue,
    }


def generate_candidates(size, r, c, typ, k, clue_domain, initial_domains):
    candidates = []
    if k < 2:
        return candidates

    for p in range(7):
        if not (clue_domain & PATBIT[p]):
            continue
        dirs = PATTERN_DIRS[p]
        if len(dirs) != 2:
            continue

        d1, d2 = dirs
        for l1 in range(1, k):
            l2 = k - l1

            e1r = r + DIRS[d1][0] * l1
            e1c = c + DIRS[d1][1] * l1
            e2r = r + DIRS[d2][0] * l2
            e2c = c + DIRS[d2][1] * l2
            if not in_bounds(e1r, e1c, size) or not in_bounds(e2r, e2c, size):
                continue

            req = {}
            ok = True

            for d, length in ((d1, l1), (d2, l2)):
                dr, dc = DIRS[d]
                straight_mask = PATBIT[STRAIGHT_FOR_DIR[d]]

                for step in range(1, length):
                    vr = r + dr * step
                    vc = c + dc * step
                    vid = vr * size + vc
                    new_mask = req.get(vid, FULL_DOMAIN) & straight_mask
                    if new_mask == 0:
                        ok = False
                        break
                    req[vid] = new_mask
                if not ok:
                    break

                vr = r + dr * length
                vc = c + dc * length
                vid = vr * size + vc
                new_mask = req.get(vid, FULL_DOMAIN) & TURN_END_MASK[d]
                if new_mask == 0:
                    ok = False
                    break
                req[vid] = new_mask

            if not ok:
                continue

            for vid, mask in req.items():
                if (initial_domains[vid] & mask) == 0:
                    ok = False
                    break
            if ok:
                candidates.append(Candidate(p, req))

    return candidates


def has_premature_cycle(puzzle, domains):
    n = puzzle["vertex_count"]
    forced_adj = [[] for _ in range(n)]
    forced_deg = [0] * n

    for u, v, d in puzzle["edges"]:
        ud = domains[u]
        vd = domains[v]
        od = OPP[d]

        u_can_on = bool(ud & USE_MASK[d])
        v_can_on = bool(vd & USE_MASK[od])
        u_can_off = bool(ud & NOT_USE_MASK[d])
        v_can_off = bool(vd & NOT_USE_MASK[od])

        if u_can_on != v_can_on or u_can_off != v_can_off:
            return True

        if u_can_on and not u_can_off:
            forced_adj[u].append(v)
            forced_adj[v].append(u)
            forced_deg[u] += 1
            forced_deg[v] += 1
            if forced_deg[u] > 2 or forced_deg[v] > 2:
                return True

    seen = [False] * n
    cycle_components = []

    for s in range(n):
        if forced_deg[s] and not seen[s]:
            comp = []
            stack = [s]
            seen[s] = True
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in forced_adj[x]:
                    if not seen[y]:
                        seen[y] = True
                        stack.append(y)
            if all(forced_deg[x] == 2 for x in comp):
                cycle_components.append(comp)

    if not cycle_components:
        return False
    if len(cycle_components) > 1:
        return True

    cycle_set = set(cycle_components[0])
    for v, dom in enumerate(domains):
        if v not in cycle_set and not (dom & PATBIT[P_UNUSED]):
            return True
    return False


def propagate(puzzle, domains, cand_masks):
    clues = puzzle["clues"]

    while True:
        changed = False

        # Local edge-consistency between neighboring vertices.
        for u, v, d in puzzle["edges"]:
            du = domains[u]
            dv = domains[v]
            od = OPP[d]

            u_use = du & USE_MASK[d]
            u_not = du & NOT_USE_MASK[d]
            v_use = dv & USE_MASK[od]
            v_not = dv & NOT_USE_MASK[od]

            ndu = (u_use if v_use else 0) | (u_not if v_not else 0)
            ndv = (v_use if u_use else 0) | (v_not if u_not else 0)

            if ndu == 0 or ndv == 0:
                return None
            if ndu != du:
                domains[u] = ndu
                changed = True
            if ndv != dv:
                domains[v] = ndv
                changed = True

        # Clue support propagation via candidate rays.
        for i, clue in enumerate(clues):
            old_mask = cand_masks[i]
            new_mask = 0
            survivors = []
            pat_union = 0
            clue_vid = clue["vid"]

            for j in iter_bits(old_mask):
                cand = clue["candidates"][j]
                if (domains[clue_vid] & PATBIT[cand.pattern]) == 0:
                    continue
                ok = True
                for v, req_mask in cand.req.items():
                    if (domains[v] & req_mask) == 0:
                        ok = False
                        break
                if ok:
                    new_mask |= (1 << j)
                    survivors.append(cand)
                    pat_union |= PATBIT[cand.pattern]

            if new_mask == 0:
                return None
            if new_mask != old_mask:
                cand_masks[i] = new_mask
                changed = True

            nd = domains[clue_vid] & pat_union
            if nd == 0:
                return None
            if nd != domains[clue_vid]:
                domains[clue_vid] = nd
                changed = True

            if len(survivors) == 1:
                cand = survivors[0]
                for v, req_mask in cand.req.items():
                    nd = domains[v] & req_mask
                    if nd == 0:
                        return None
                    if nd != domains[v]:
                        domains[v] = nd
                        changed = True
            elif len(survivors) > 1:
                common = set(survivors[0].keys)
                for cand in survivors[1:]:
                    common.intersection_update(cand.keys)
                    if not common:
                        break
                for v in common:
                    union_mask = 0
                    for cand in survivors:
                        union_mask |= cand.req[v]
                    nd = domains[v] & union_mask
                    if nd == 0:
                        return None
                    if nd != domains[v]:
                        domains[v] = nd
                        changed = True

        if has_premature_cycle(puzzle, domains):
            return None

        if not changed:
            return domains, cand_masks


def segment_length(start_vid, d, assign, size):
    cur = start_vid
    steps = 0
    limit = size * size + 5

    for _ in range(limit):
        if (PATTERN_BITS[assign[cur]] & DBIT[d]) == 0:
            return None

        r, c = divmod(cur, size)
        nr, nc = r + DIRS[d][0], c + DIRS[d][1]
        if not in_bounds(nr, nc, size):
            return None
        nxt = nr * size + nc

        if (PATTERN_BITS[assign[nxt]] & DBIT[OPP[d]]) == 0:
            return None

        steps += 1
        if assign[nxt] == STRAIGHT_FOR_DIR[d]:
            cur = nxt
            continue

        if assign[nxt] == P_UNUSED:
            return None
        if PATTERN_BITS[assign[nxt]] & DBIT[d]:
            return None
        return steps

    return None


def verify_and_extract(puzzle, domains):
    if any(d == 0 for d in domains):
        return None
    if any(d & (d - 1) for d in domains):
        return None

    size = puzzle["size"]
    n = puzzle["vertex_count"]
    assign = [single_value(d) for d in domains]

    adj = [[] for _ in range(n)]
    for u, v, d in puzzle["edges"]:
        use_u = bool(PATTERN_BITS[assign[u]] & DBIT[d])
        use_v = bool(PATTERN_BITS[assign[v]] & DBIT[OPP[d]])
        if use_u != use_v:
            return None
        if use_u:
            adj[u].append(v)
            adj[v].append(u)

    used = [v for v in range(n) if assign[v] != P_UNUSED]
    if not used:
        return None

    for v in range(n):
        deg = len(adj[v])
        if assign[v] == P_UNUSED:
            if deg != 0:
                return None
        else:
            if deg != 2:
                return None

    start = min(used)
    seen = {start}
    stack = [start]
    while stack:
        x = stack.pop()
        for y in adj[x]:
            if y not in seen:
                seen.add(y)
                stack.append(y)
    if len(seen) != len(used):
        return None

    for clue in puzzle["clues"]:
        p = assign[clue["vid"]]
        if clue["type"] == "W":
            if p not in (P_H, P_V):
                return None
        else:
            if p not in (P_NE, P_NW, P_SE, P_SW):
                return None

        total = 0
        for d in PATTERN_DIRS[p]:
            seg = segment_length(clue["vid"], d, assign, size)
            if seg is None:
                return None
            total += seg
        if total != clue["k"]:
            return None

    path = [coord(start, size)]
    prev = -1
    cur = start
    max_steps = len(used) + 1

    for _ in range(max_steps):
        nbrs = adj[cur]
        if prev == -1:
            nxt = min(nbrs)
        else:
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(coord(nxt, size))
        prev, cur = cur, nxt
        if cur == start:
            break

    if cur != start:
        return None
    if len(path) != len(used) + 1:
        return None

    return path


def choose_branch(puzzle, domains, cand_masks):
    best = None

    for i, mask in enumerate(cand_masks):
        cnt = mask.bit_count()
        if cnt > 1:
            max_impact = 0
            for j in iter_bits(mask):
                imp = puzzle["clues"][i]["candidates"][j].impact
                if imp > max_impact:
                    max_impact = imp
            key = (cnt, -max_impact, i)
            if best is None or key < best[0]:
                best = (key, ("clue", i))
    if best is not None:
        return best[1]

    best = None
    for v, dom in enumerate(domains):
        cnt = dom.bit_count()
        if cnt > 1:
            requires_use = 0 if not (dom & PATBIT[P_UNUSED]) else 1
            is_clue = 0 if puzzle["is_clue"][v] else 1
            key = (cnt, requires_use, is_clue, v)
            if best is None or key < best[0]:
                best = (key, ("vertex", v))
    return None if best is None else best[1]


def search(puzzle, domains, cand_masks, fail_cache):
    state = propagate(puzzle, domains, cand_masks)
    if state is None:
        return None

    key = (tuple(domains), tuple(cand_masks))
    if key in fail_cache:
        return None

    solved = True
    for d in domains:
        if d & (d - 1):
            solved = False
            break
    if solved:
        ans = verify_and_extract(puzzle, domains)
        if ans is not None:
            return ans
        fail_cache.add(key)
        return None

    branch = choose_branch(puzzle, domains, cand_masks)
    if branch is None:
        ans = verify_and_extract(puzzle, domains)
        if ans is not None:
            return ans
        fail_cache.add(key)
        return None

    kind, idx = branch

    if kind == "clue":
        clue = puzzle["clues"][idx]
        options = list(iter_bits(cand_masks[idx]))
        options.sort(key=lambda j: (-clue["candidates"][j].impact, j))

        for j in options:
            cand = clue["candidates"][j]
            ndomains = domains[:]
            ncands = cand_masks[:]
            ncands[idx] = 1 << j

            cv = clue["vid"]
            nd = ndomains[cv] & PATBIT[cand.pattern]
            if nd == 0:
                continue
            ndomains[cv] = nd

            ok = True
            for v, req_mask in cand.req.items():
                nd = ndomains[v] & req_mask
                if nd == 0:
                    ok = False
                    break
                ndomains[v] = nd
            if not ok:
                continue

            ans = search(puzzle, ndomains, ncands, fail_cache)
            if ans is not None:
                return ans
    else:
        v = idx
        dom = domains[v]
        values = [p for p in range(7) if dom & PATBIT[p]]
        values.sort(key=lambda p: (p == P_UNUSED, p))

        for p in values:
            ndomains = domains[:]
            ncands = cand_masks[:]
            ndomains[v] = PATBIT[p]
            ans = search(puzzle, ndomains, ncands, fail_cache)
            if ans is not None:
                return ans

    fail_cache.add(key)
    return None


def solve(observation):
    puzzle = build_puzzle(observation)
    if puzzle is None:
        return "No Solution"

    domains = puzzle["initial_domains"][:]
    cand_masks = [(1 << len(clue["candidates"])) - 1 for clue in puzzle["clues"]]
    fail_cache = set()

    ans = search(puzzle, domains, cand_masks, fail_cache)
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

