# Local vertex patterns
P_UNUSED, P_H, P_V, P_NE, P_NW, P_SE, P_SW = range(7)
PATBIT = [1 << i for i in range(7)]
FULL_DOMAIN = (1 << 7) - 1

PATTERN_BITS = [
    0,                      # unused
    DBIT[R] | DBIT[L],      # horizontal
    DBIT[U] | DBIT[D],      # vertical
    DBIT[U] | DBIT[R],      # turn NE
    DBIT[U] | DBIT[L],      # turn NW
    DBIT[D] | DBIT[R],      # turn SE
    DBIT[D] | DBIT[L],      # turn SW
]

PATTERN_DIRS = [
