# 0: empty
# 1: horizontal (L,R)
# 2: vertical   (U,D)
# 3: turn U,R
# 4: turn U,L
# 5: turn D,R
# 6: turn D,L

EMPTY, H, V, UR, UL, DR, DL = range(7)
STATE_BITS = [1 << i for i in range(7)]
ALL_STATE_BITS = (1 << 7) - 1

U, D, L, R = range(4)
DRS = (-1, 1, 0, 0)
