TURN_STATES = (UR, UL, DR, DL)

USE_MASK = [0, 0, 0, 0]
for s in range(7):
    for d in range(4):
        if STATE_DIRBITS[s] & (1 << d):
            USE_MASK[d] |= STATE_BITS[s]
NOT_USE_MASK = [ALL_STATE_BITS ^ USE_MASK[d] for d in range(4)]

INCOMING_TURN_MASK = [0, 0, 0, 0]
for incoming in range(4):
    m = 0
    for s in TURN_STATES:
