def check_partial_loop(state, puzzle):
    edges = state["edges"]
    domains = state["domains"]
    edge_ends = puzzle["edge_ends"]

    present_adj = {}
    degree_present = {}

    for eid, val in enumerate(edges):
        if val != 1:
            continue
        a, b = edge_ends[eid]
        present_adj.setdefault(a, []).append(b)
        present_adj.setdefault(b, []).append(a)
        degree_present[a] = degree_present.get(a, 0) + 1
        degree_present[b] = degree_present.get(b, 0) + 1
        if degree_present[a] > 2 or degree_present[b] > 2:
            return False

    if not present_adj:
        return True

    used_vertices = set(present_adj)
    seen = set()
    closed_comp = None

    for start in used_vertices:
