def verify_and_extract(state, puzzle):
    edges = state["edges"]
    domains = state["domains"]
    M = puzzle["M"]
    inc_edges = puzzle["inc_edges"]
    neigh = puzzle["neigh"]
    edge_ends = puzzle["edge_ends"]

    if any(v == -1 for v in edges):
        return None
    if any(dom.bit_count() != 1 for dom in domains):
        return None

    used_dirs = [[] for _ in range(puzzle["V"])]
    for v in range(puzzle["V"]):
        for d in range(4):
            e = inc_edges[v][d]
            if e != -1 and edges[e] == 1:
                used_dirs[v].append(d)

