    start = min(used_vertices, key=puzzle["rc"])
    seen = set([start])
    stack = [start]
    while stack:
        v = stack.pop()
        for d in used_dirs[v]:
            nb = neigh[v][d]
            if nb not in seen:
                seen.add(nb)
                stack.append(nb)
    if len(seen) != len(used_vertices):
        return None

