            total += dist
        if total != k:
            return None

    path = build_cycle_path(start, used_dirs, neigh, puzzle["rc"])
    if path is None:
        return None
    return path


def distance_to_next_turn(start_v, d, used_dirs, neigh):
    cur = neigh[start_v][d]
    if cur == -1:
        return None
    dist = 1
    travel = d

    while True:
        dirs = used_dirs[cur]
        if len(dirs) != 2:
            return None
        incoming = OPP[travel]
        if incoming not in dirs:
            return None
        other = dirs[0] if dirs[1] == incoming else dirs[1] if dirs[0] == incoming else None
        if other is None:
            return None
        if other == travel:
            nxt = neigh[cur][travel]
            if nxt == -1:
                return None
            cur = nxt
            dist += 1
        else:
            return dist


def build_cycle_path(start, used_dirs, neigh, rc):
    dirs = used_dirs[start]
    if len(dirs) != 2:
        return None

    first_dir = min(dirs)
    nxt = neigh[start][first_dir]
    if nxt == -1:
        return None

    path = [rc(start), rc(nxt)]
    prev, cur = start, nxt

    while cur != start:
        dirs = used_dirs[cur]
        if len(dirs) != 2:
            return None
        next_vertices = []
        for d in dirs:
            nb = neigh[cur][d]
            if nb != prev:
                next_vertices.append(nb)
        if len(next_vertices) != 1:
            return None
        nxt = next_vertices[0]
        path.append(rc(nxt))
        prev, cur = cur, nxt

    return path


