from collections import deque
import sys

# State encoding for each dot:
# 0: empty
# 1: horizontal (L,R)
# 2: vertical   (U,D)
# 3: turn U,R
# 4: turn U,L
# 5: turn D,R
# 6: turn D,L

EMPTY, H, V, UR, UL, DR, DL = range(7)
STATE_BITS = [1 << i for i in range(7)]
ALL_STATE_BITS = (1 << 7) - 1

U, D, L, R = range(4)
DRS = (-1, 1, 0, 0)
DCS = (0, 0, -1, 1)
OPP = (D, U, R, L)

STATE_DIRBITS = [
    0,                          # EMPTY
    (1 << L) | (1 << R),        # H
    (1 << U) | (1 << D),        # V
    (1 << U) | (1 << R),        # UR
    (1 << U) | (1 << L),        # UL
    (1 << D) | (1 << R),        # DR
    (1 << D) | (1 << L),        # DL
]

WHITE_MASK = STATE_BITS[H] | STATE_BITS[V]
BLACK_MASK = STATE_BITS[UR] | STATE_BITS[UL] | STATE_BITS[DR] | STATE_BITS[DL]
TURN_STATES = (UR, UL, DR, DL)

USE_MASK = [0, 0, 0, 0]
for s in range(7):
    for d in range(4):
        if STATE_DIRBITS[s] & (1 << d):
            USE_MASK[d] |= STATE_BITS[s]
NOT_USE_MASK = [ALL_STATE_BITS ^ USE_MASK[d] for d in range(4)]

INCOMING_TURN_MASK = [0, 0, 0, 0]
for incoming in range(4):
    m = 0
    for s in TURN_STATES:
        if STATE_DIRBITS[s] & (1 << incoming):
            m |= STATE_BITS[s]
    INCOMING_TURN_MASK[incoming] = m


def solve(observation):
    sys.setrecursionlimit(10000)
    puzzle = build_puzzle(observation)
    if puzzle is None:
        return "No Solution"

    state = {
        "domains": puzzle["initial_domains"][:],
        "edges": [-1] * puzzle["E"],
        "active": [list(range(len(cands))) for cands in puzzle["candidates"]],
    }

    if not propagate(state, puzzle):
        return "No Solution"

    result = dfs(state, puzzle)
    return result if result is not None else "No Solution"


def build_puzzle(observation):
    data = observation["data"]
    if not data or any(len(row) != len(data) for row in data):
        return None

    M = len(data)
    Vn = M * M

    def vid(r, c):
        return r * M + c

    def rc(v):
        return divmod(v, M)

    inc_edges = [[-1] * 4 for _ in range(Vn)]
    neigh = [[-1] * 4 for _ in range(Vn)]
    edge_ends = []

    def add_edge(v1, d1, v2, d2):
        eid = len(edge_ends)
        edge_ends.append((v1, v2))
        inc_edges[v1][d1] = eid
        inc_edges[v2][d2] = eid
        neigh[v1][d1] = v2
        neigh[v2][d2] = v1

    for r in range(M):
        for c in range(M - 1):
            add_edge(vid(r, c), R, vid(r, c + 1), L)
    for r in range(M - 1):
        for c in range(M):
            add_edge(vid(r, c), D, vid(r + 1, c), U)

    clues = []
    clues_by_v = {}
    for r in range(M):
        for c in range(M):
            token = data[r][c]
            if token is not None:
                color = token[0]
                k = int(token[1:])
                v = vid(r, c)
                clues.append((v, color, k))
                clues_by_v[v] = (color, k)

    valid_state_mask = [0] * Vn
    for v in range(Vn):
        mask = 0
        for s in range(7):
            ok = True
            sb = STATE_DIRBITS[s]
            for d in range(4):
                if (sb & (1 << d)) and inc_edges[v][d] == -1:
                    ok = False
                    break
            if ok:
                mask |= STATE_BITS[s]
        valid_state_mask[v] = mask

    initial_domains = [0] * Vn
    for v in range(Vn):
        if v in clues_by_v:
            color, _ = clues_by_v[v]
            base = WHITE_MASK if color == "W" else BLACK_MASK
        else:
            base = ALL_STATE_BITS
        dom = base & valid_state_mask[v]
        if dom == 0:
            return None
        initial_domains[v] = dom

    candidates = []
    influenced = [False] * Vn

    for v, color, k in clues:
        state_options = (H, V) if color == "W" else (UR, UL, DR, DL)
        clue_cands = []
        seen = set()
        for s in state_options:
            dirs = [d for d in range(4) if STATE_DIRBITS[s] & (1 << d)]
            if len(dirs) != 2:
                continue
            for a in range(1, k):
                lens = (a, k - a)
                vreq = {v: STATE_BITS[s]}
                edges = []
                ok = True

                for d, seg_len in zip(dirs, lens):
                    cur = v
                    for step in range(1, seg_len + 1):
                        eid = inc_edges[cur][d]
                        if eid == -1:
                            ok = False
                            break
                        nxt = neigh[cur][d]
                        edges.append(eid)

                        if step < seg_len:
                            req = STATE_BITS[H] if d in (L, R) else STATE_BITS[V]
                        else:
                            req = INCOMING_TURN_MASK[OPP[d]]

                        prev = vreq.get(nxt, ALL_STATE_BITS)
                        prev &= req
                        if prev == 0:
                            ok = False
                            break
                        vreq[nxt] = prev
                        cur = nxt

                    if not ok:
                        break

                if not ok:
                    continue

                for vv, mask in vreq.items():
                    if (mask & initial_domains[vv]) == 0:
                        ok = False
                        break
                if not ok:
                    continue

                e_tuple = tuple(sorted(set(edges)))
                v_tuple = tuple(sorted(vreq.items()))
                sig = (v_tuple, e_tuple)
                if sig in seen:
                    continue
                seen.add(sig)

                cand = {
                    "vreq": v_tuple,
                    "vmap": dict(vreq),
                    "vkeys": frozenset(vreq.keys()),
                    "edges": e_tuple,
                    "eset": frozenset(e_tuple),
                    "strength": (len(e_tuple), len(v_tuple)),
                }
                clue_cands.append(cand)

        if not clue_cands:
            return None

        clue_cands.sort(key=lambda c: (-c["strength"][0], -c["strength"][1]))
        for cand in clue_cands:
            for vv in cand["vmap"]:
                influenced[vv] = True
        candidates.append(clue_cands)

    return {
        "M": M,
        "V": Vn,
        "E": len(edge_ends),
        "vid": vid,
        "rc": rc,
        "inc_edges": inc_edges,
        "neigh": neigh,
        "edge_ends": edge_ends,
        "clues": clues,
        "clues_by_v": clues_by_v,
        "clue_vertices": [v for v, _, _ in clues],
        "initial_domains": initial_domains,
        "candidates": candidates,
        "influenced": influenced,
    }


def propagate(state, puzzle):
    domains = state["domains"]
    edges = state["edges"]
    active = state["active"]
    inc_edges = puzzle["inc_edges"]
    candidates = puzzle["candidates"]
    clue_vertices = puzzle["clue_vertices"]

    while True:
        progress = False

        # Local vertex/edge consistency.
        for v in range(puzzle["V"]):
            dom = domains[v]
            nd = dom
            inc = inc_edges[v]

            for d in range(4):
                e = inc[d]
                if e == -1:
                    nd &= NOT_USE_MASK[d]
                else:
                    ev = edges[e]
                    if ev == 1:
                        nd &= USE_MASK[d]
                    elif ev == 0:
                        nd &= NOT_USE_MASK[d]

            if nd == 0:
                return False
            if nd != dom:
                domains[v] = nd
                dom = nd
                progress = True

            for d in range(4):
                e = inc[d]
                if e == -1:
                    continue
                if (dom & USE_MASK[d]) == 0:
                    if edges[e] == 1:
                        return False
                    if edges[e] == -1:
                        edges[e] = 0
                        progress = True
                elif (dom & NOT_USE_MASK[d]) == 0:
                    if edges[e] == 0:
                        return False
                    if edges[e] == -1:
                        edges[e] = 1
                        progress = True

        # Clue candidate filtering and clue-driven deductions.
        for ci, clue_cands in enumerate(candidates):
            rem = []
            for idx in active[ci]:
                cand = clue_cands[idx]
                ok = True
                for vv, mask in cand["vreq"]:
                    if (domains[vv] & mask) == 0:
                        ok = False
                        break
                if ok:
                    for e in cand["edges"]:
                        if edges[e] == 0:
                            ok = False
                            break
                if ok:
                    rem.append(idx)

            if not rem:
                return False

            if len(rem) != len(active[ci]):
                active[ci] = rem
                progress = True

            if len(rem) == 1:
                cand = clue_cands[rem[0]]
                for vv, mask in cand["vreq"]:
                    nd = domains[vv] & mask
                    if nd == 0:
                        return False
                    if nd != domains[vv]:
                        domains[vv] = nd
                        progress = True
                for e in cand["edges"]:
                    if edges[e] == 0:
                        return False
                    if edges[e] == -1:
                        edges[e] = 1
                        progress = True
            else:
                common = dict(clue_cands[rem[0]]["vmap"])
                common_edges = set(clue_cands[rem[0]]["eset"])
                for idx in rem[1:]:
                    cand = clue_cands[idx]
                    for vv in list(common.keys()):
                        m = cand["vmap"].get(vv)
                        if m is None:
                            del common[vv]
                        else:
                            common[vv] |= m
                    common_edges.intersection_update(cand["eset"])

                for vv, mask in common.items():
                    nd = domains[vv] & mask
                    if nd == 0:
                        return False
                    if nd != domains[vv]:
                        domains[vv] = nd
                        progress = True

                for e in common_edges:
                    if edges[e] == 0:
                        return False
                    if edges[e] == -1:
                        edges[e] = 1
                        progress = True

        # Partial-loop pruning: forbid sealed subloops and impossible outside usage.
        if not check_partial_loop(state, puzzle):
            return False

        # Every clue vertex must remain non-empty.
        for v in clue_vertices:
            if domains[v] & ~STATE_BITS[EMPTY] == 0:
                return False

        if not progress:
            return True


def check_partial_loop(state, puzzle):
    edges = state["edges"]
    domains = state["domains"]
    edge_ends = puzzle["edge_ends"]

    present_adj = {}
    degree_present = {}

    for eid, val in enumerate(edges):
        if val != 1:
            continue
        a, b = edge_ends[eid]
        present_adj.setdefault(a, []).append(b)
        present_adj.setdefault(b, []).append(a)
        degree_present[a] = degree_present.get(a, 0) + 1
        degree_present[b] = degree_present.get(b, 0) + 1
        if degree_present[a] > 2 or degree_present[b] > 2:
            return False

    if not present_adj:
        return True

    used_vertices = set(present_adj)
    seen = set()
    closed_comp = None

    for start in used_vertices:
        if start in seen:
            continue
        stack = [start]
        comp = set()
        seen.add(start)
        while stack:
            v = stack.pop()
            comp.add(v)
            for nb in present_adj.get(v, ()):
                if nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
        closed = all(degree_present.get(v, 0) == 2 for v in comp)
        if closed:
            if closed_comp is not None:
                return False
            closed_comp = comp

    if closed_comp is not None:
        if len(closed_comp) != len(used_vertices):
            return False
        for v in puzzle["clue_vertices"]:
            if v not in closed_comp:
                return False
        for v in range(puzzle["V"]):
            if v not in closed_comp and (domains[v] & STATE_BITS[EMPTY]) == 0:
                return False

    return True


def dfs(state, puzzle):
    if not propagate(state, puzzle):
        return None

    done = True
    for dom in state["domains"]:
        if dom.bit_count() != 1:
            done = False
            break
    if done and all(v != -1 for v in state["edges"]):
        return verify_and_extract(state, puzzle)

    choice = pick_branch(state, puzzle)
    if choice is None:
        return verify_and_extract(state, puzzle)

    kind = choice[0]

    if kind == "clue":
        ci = choice[1]
        for idx in choice[2]:
            new_state = copy_state(state)
            new_state["active"][ci] = [idx]
            cand = puzzle["candidates"][ci][idx]
            ok = True
            for vv, mask in cand["vreq"]:
                nd = new_state["domains"][vv] & mask
                if nd == 0:
                    ok = False
                    break
                new_state["domains"][vv] = nd
            if not ok:
                continue
            for e in cand["edges"]:
                ev = new_state["edges"][e]
                if ev == 0:
                    ok = False
                    break
                new_state["edges"][e] = 1
            if not ok:
                continue
            ans = dfs(new_state, puzzle)
            if ans is not None:
                return ans
        return None

    if kind == "vertex":
        v = choice[1]
        for s in choice[2]:
            new_state = copy_state(state)
            new_state["domains"][v] = STATE_BITS[s]
            ans = dfs(new_state, puzzle)
            if ans is not None:
                return ans
        return None

    if kind == "edge":
        e = choice[1]
        for val in choice[2]:
            new_state = copy_state(state)
            new_state["edges"][e] = val
            ans = dfs(new_state, puzzle)
            if ans is not None:
                return ans
        return None

    return None


def pick_branch(state, puzzle):
    # Prefer branching on a clue candidate: this most closely mirrors human deduction.
    best_ci = None
    best_key = None
    for ci, act in enumerate(state["active"]):
        m = len(act)
        if m <= 1:
            continue
        strongest = max(puzzle["candidates"][ci][idx]["strength"][0] for idx in act)
        key = (m, -strongest)
        if best_key is None or key < best_key:
            best_key = key
            best_ci = ci

    if best_ci is not None:
        order = list(state["active"][best_ci])
        order.sort(
            key=lambda idx: (
                -puzzle["candidates"][best_ci][idx]["strength"][0],
                -puzzle["candidates"][best_ci][idx]["strength"][1],
            )
        )
        return ("clue", best_ci, order)

    # Then branch on the most constrained vertex.
    best_v = None
    best_count = None
    for v, dom in enumerate(state["domains"]):
        cnt = dom.bit_count()
        if cnt <= 1:
            continue
        if best_count is None or cnt < best_count:
            best_count = cnt
            best_v = v

    if best_v is not None:
        dom = state["domains"][best_v]
        states = [s for s in range(7) if dom & STATE_BITS[s]]
        if puzzle["influenced"][best_v]:
            states.sort(key=lambda s: (s == EMPTY, s))
        else:
            states.sort(key=lambda s: (s != EMPTY, s))
        return ("vertex", best_v, states)

    # Finally, branch on an undecided edge.
    inc_edges = puzzle["inc_edges"]
    clue_vertices = set(puzzle["clue_vertices"])
    for e, val in enumerate(state["edges"]):
        if val != -1:
            continue
        a, b = puzzle["edge_ends"][e]
        prefer_present = (
            a in clue_vertices
            or b in clue_vertices
            or puzzle["influenced"][a]
            or puzzle["influenced"][b]
        )
        return ("edge", e, [1, 0] if prefer_present else [0, 1])

    return None


def copy_state(state):
    return {
        "domains": state["domains"][:],
        "edges": state["edges"][:],
        "active": [lst[:] for lst in state["active"]],
    }


def verify_and_extract(state, puzzle):
    edges = state["edges"]
    domains = state["domains"]
    M = puzzle["M"]
    inc_edges = puzzle["inc_edges"]
    neigh = puzzle["neigh"]
    edge_ends = puzzle["edge_ends"]

    if any(v == -1 for v in edges):
        return None
    if any(dom.bit_count() != 1 for dom in domains):
        return None

    used_dirs = [[] for _ in range(puzzle["V"])]
    for v in range(puzzle["V"]):
        for d in range(4):
            e = inc_edges[v][d]
            if e != -1 and edges[e] == 1:
                used_dirs[v].append(d)

    used_vertices = [v for v in range(puzzle["V"]) if used_dirs[v]]
    if not used_vertices:
        return None

    for v in range(puzzle["V"]):
        deg = len(used_dirs[v])
        if deg not in (0, 2):
            return None

    for v in puzzle["clue_vertices"]:
        if len(used_dirs[v]) != 2:
            return None

    # Connectedness of the used loop.
    start = min(used_vertices, key=puzzle["rc"])
    seen = set([start])
    stack = [start]
    while stack:
        v = stack.pop()
        for d in used_dirs[v]:
            nb = neigh[v][d]
            if nb not in seen:
                seen.add(nb)
                stack.append(nb)
    if len(seen) != len(used_vertices):
        return None

    # Since connected and every used vertex has degree 2, it is a single cycle.
    for v, (color, k) in puzzle["clues_by_v"].items():
        dirs = used_dirs[v]
        straight = (
            (U in dirs and D in dirs) or
            (L in dirs and R in dirs)
        )
        if color == "W" and not straight:
            return None
        if color == "B" and straight:
            return None

        total = 0
        for d in dirs:
            dist = distance_to_next_turn(v, d, used_dirs, neigh)
            if dist is None:
                return None
            total += dist
        if total != k:
            return None

    path = build_cycle_path(start, used_dirs, neigh, puzzle["rc"])
    if path is None:
        return None
    return path


def distance_to_next_turn(start_v, d, used_dirs, neigh):
    cur = neigh[start_v][d]
    if cur == -1:
        return None
    dist = 1
    travel = d

    while True:
        dirs = used_dirs[cur]
        if len(dirs) != 2:
            return None
        incoming = OPP[travel]
        if incoming not in dirs:
            return None
        other = dirs[0] if dirs[1] == incoming else dirs[1] if dirs[0] == incoming else None
        if other is None:
            return None
        if other == travel:
            nxt = neigh[cur][travel]
            if nxt == -1:
                return None
            cur = nxt
            dist += 1
        else:
            return dist


def build_cycle_path(start, used_dirs, neigh, rc):
    dirs = used_dirs[start]
    if len(dirs) != 2:
        return None

    first_dir = min(dirs)
    nxt = neigh[start][first_dir]
    if nxt == -1:
        return None

    path = [rc(start), rc(nxt)]
    prev, cur = start, nxt

    while cur != start:
        dirs = used_dirs[cur]
        if len(dirs) != 2:
            return None
        next_vertices = []
        for d in dirs:
            nb = neigh[cur][d]
            if nb != prev:
                next_vertices.append(nb)
        if len(next_vertices) != 1:
            return None
        nxt = next_vertices[0]
        path.append(rc(nxt))
        prev, cur = cur, nxt

    return path


