import sys

sys.setrecursionlimit(10000)

# Vertex local states:
# 0 EMPTY
# 1 H  (L-R)
# 2 V  (U-D)
# 3 UR
# 4 RD
# 5 DL
# 6 LU

EMPTY, H, V, UR, RD, DL, LU = range(7)

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # U, R, D, L
OPP = [2, 3, 0, 1]
DIRBIT = [1, 2, 4, 8]

STATE_EDGE_MASKS = [
    0,                  # EMPTY
    DIRBIT[1] | DIRBIT[3],  # H
    DIRBIT[0] | DIRBIT[2],  # V
    DIRBIT[0] | DIRBIT[1],  # UR
    DIRBIT[1] | DIRBIT[2],  # RD
    DIRBIT[2] | DIRBIT[3],  # DL
    DIRBIT[3] | DIRBIT[0],  # LU
]

STATE_DIRS = [
    (),
    (1, 3),
    (0, 2),
    (0, 1),
    (1, 2),
    (2, 3),
    (3, 0),
]

ALL_STATE_BITS = (1 << 7) - 1
EMPTY_BIT = 1 << EMPTY
H_BIT = 1 << H
V_BIT = 1 << V
TURN_BITS = (1 << UR) | (1 << RD) | (1 << DL) | (1 << LU)
NONEMPTY_BITS = ALL_STATE_BITS ^ EMPTY_BIT

USE_STATES = [0, 0, 0, 0]
for s in range(7):
    for d in range(4):
        if STATE_EDGE_MASKS[s] & DIRBIT[d]:
            USE_STATES[d] |= 1 << s
OFF_STATES = [ALL_STATE_BITS ^ USE_STATES[d] for d in range(4)]

# If a segment travels from the clue in direction d, then its endpoint must turn
# with the back-edge OPP(d).
TURN_BACK_MASK = [
    (1 << RD) | (1 << DL),  # branch goes U, endpoint must contain D
    (1 << DL) | (1 << LU),  # branch goes R, endpoint must contain L
    (1 << UR) | (1 << LU),  # branch goes D, endpoint must contain U
    (1 << UR) | (1 << RD),  # branch goes L, endpoint must contain R
]


def iter_bits(mask):
    while mask:
        b = mask & -mask
        yield b.bit_length() - 1
        mask ^= b


def singleton_index(mask):
    return mask.bit_length() - 1 if mask and (mask & (mask - 1)) == 0 else None


def solve(observation):
    data = observation['data']
    m = len(data)
    nverts = m * m

    def vid(r, c):
        return r * m + c

    coords = [(r, c) for r in range(m) for c in range(m)]

    neighbors = [[-1] * 4 for _ in range(nverts)]
    for r in range(m):
        for c in range(m):
            v = vid(r, c)
            for d, (dr, dc) in enumerate(DIRS):
                rr, cc = r + dr, c + dc
                if 0 <= rr < m and 0 <= cc < m:
                    neighbors[v][d] = vid(rr, cc)

    edges = []
    for r in range(m):
        for c in range(m):
            v = vid(r, c)
            if c + 1 < m:
                w = vid(r, c + 1)
                edges.append((v, 1, w, 3))
            if r + 1 < m:
                w = vid(r + 1, c)
                edges.append((v, 2, w, 0))

    def boundary_compatible(r, c, s):
        em = STATE_EDGE_MASKS[s]
        if (em & DIRBIT[0]) and r == 0:
            return False
        if (em & DIRBIT[1]) and c == m - 1:
            return False
        if (em & DIRBIT[2]) and r == m - 1:
            return False
        if (em & DIRBIT[3]) and c == 0:
            return False
        return True

    full_domains = [0] * nverts
    clue_positions = []
    clue_tokens = {}
    clue_pos_set = set()

    for r in range(m):
        for c in range(m):
            token = data[r][c]
            v = vid(r, c)
            dom = 0
            for s in range(7):
                if token is None:
                    pass
                else:
                    if s == EMPTY:
                        continue
                    if token[0] == 'W' and s not in (H, V):
