            if ans is not None:
                return ans
            failed.add(key)
            return None

        best_ci = None
        best_count = 10**9
        best_span = -1
        for ci, dom in enumerate(clue_doms):
            c = dom.bit_count()
            if 1 < c < best_count:
                best_count = c
                best_ci = ci
                best_span = 0
            elif c == best_count and c > 1:
                span = 0
                bm = dom
                seenv = set()
                while bm:
