            # Filter clue options against current domains.
            for ci, opts in enumerate(clue_options):
                dom = clue_doms[ci]
                new_dom = 0
                bm = dom
                while bm:
                    lsb = bm & -bm
                    oi = lsb.bit_length() - 1
                    bm ^= lsb
