            return None
        if any(len(adj[v]) != 2 for v in used):
            return None

        start = min(used, key=lambda x: coords[x])
        nbrs = sorted(adj[start], key=lambda x: coords[x])
        if len(nbrs) != 2:
            return None

        visited = {start}
        prev = start
        curr = nbrs[0]
        path = [coords[start], coords[curr]]

        steps = 0
        while curr != start:
            if curr in visited:
                return None
            visited.add(curr)
            if len(adj[curr]) != 2:
                return None
            a, b = adj[curr]
            nxt = b if a == prev else a
            prev, curr = curr, nxt
            path.append(coords[curr])
            steps += 1
            if steps > len(used) + 2:
                return None

        if len(visited) != len(used):
            return None

        def length_from(v, d):
            cur = v
            length = 0
            limit = nverts + 1
            while limit > 0:
                limit -= 1
                nxt = neighbors[cur][d]
                if nxt == -1:
                    return None
                if nxt not in adj[cur]:
                    return None
                length += 1
                cur = nxt
                s = states[cur]
