                    return None
                dirs2 = STATE_DIRS[s]

            total = 0
            for d in dirs2:
                val = length_from(v, d)
                if val is None:
                    return None
                total += val
            if total != k:
                return None

        return path

    failed = set()

    def dfs(domains, clue_doms):
        if not propagate(domains, clue_doms):
            return None

        key = (tuple(domains), tuple(clue_doms))
        if key in failed:
            return None

        if all((dom & (dom - 1)) == 0 for dom in domains):
            ans = validate_and_extract(domains)
            if ans is not None:
                return ans
            failed.add(key)
            return None

        best_ci = None
        best_count = 10**9
        best_span = -1
        for ci, dom in enumerate(clue_doms):
            c = dom.bit_count()
            if 1 < c < best_count:
                best_count = c
                best_ci = ci
                best_span = 0
            elif c == best_count and c > 1:
                span = 0
                bm = dom
                seenv = set()
                while bm:
                    lsb = bm & -bm
                    oi = lsb.bit_length() - 1
                    bm ^= lsb
                    for v, _ in clue_options[ci][oi]:
                        seenv.add(v)
                span = len(seenv)
                if span > best_span:
                    best_ci = ci
                    best_span = span

        if best_ci is not None:
            opts_order = [oi for oi in iter_bits(clue_doms[best_ci])]
            opts_order.sort(key=lambda oi: -len(clue_options[best_ci][oi]))
            for oi in opts_order:
                nd = domains[:]
                cd = clue_doms[:]
                cd[best_ci] = 1 << oi
                ans = dfs(nd, cd)
                if ans is not None:
                    return ans
            failed.add(key)
            return None

        best_v = None
        best_size = 10**9
        best_required = -1
        for v in range(nverts):
            c = domains[v].bit_count()
            if c <= 1:
                continue
            req = 1 if (domains[v] & EMPTY_BIT) == 0 else 0
            if c < best_size or (c == best_size and req > best_required):
                best_size = c
                best_required = req
                best_v = v

        if best_v is None:
            failed.add(key)
            return None

        state_choices = [1 << s for s in iter_bits(domains[best_v])]
        state_choices.sort(key=lambda b: (b == EMPTY_BIT, 0))
        for sb in state_choices:
            nd = domains[:]
            cd = clue_doms[:]
            nd[best_v] = sb
            ans = dfs(nd, cd)
            if ans is not None:
                return ans

        failed.add(key)
        return None

    result = dfs(initial_domains[:], initial_clue_domains[:])
    return result if result is not None else "No Solution"


