import sys
from collections import deque

sys.setrecursionlimit(10000)

# Directions
U, R, D, L = 0, 1, 2, 3
DRC = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [D, L, U, R]

# Local degree-2 states on a vertex, encoded as used direction bits.
EMP = 0
VER = (1 << U) | (1 << D)
HOR = (1 << L) | (1 << R)
UR = (1 << U) | (1 << R)
UL = (1 << U) | (1 << L)
DR = (1 << D) | (1 << R)
DL = (1 << D) | (1 << L)

STATE_MASKS = [EMP, VER, HOR, UR, UL, DR, DL]
BIT = {m: 1 << i for i, m in enumerate(STATE_MASKS)}
ALL_DOMAIN = (1 << len(STATE_MASKS)) - 1
EMPTY_BIT = BIT[EMP]
WHITE_ALLOWED = BIT[VER] | BIT[HOR]
BLACK_ALLOWED = BIT[UR] | BIT[UL] | BIT[DR] | BIT[DL]
TURN_LOCALS = {UR, UL, DR, DL}
AXIS_LOCAL = {U: VER, D: VER, L: HOR, R: HOR}
SINGLETON_TO_LOCAL = {1 << i: m for i, m in enumerate(STATE_MASKS)}

USES = [0, 0, 0, 0]
for i, m in enumerate(STATE_MASKS):
    b = 1 << i
    for d in range(4):
        if m & (1 << d):
            USES[d] |= b
NOTUSES = [ALL_DOMAIN ^ USES[d] for d in range(4)]

# Endpoint-turn masks: turn states that contain a specific edge.
TURN_WITH_EDGE = [0, 0, 0, 0]
for turn in (UR, UL, DR, DL):
    tb = BIT[turn]
    for d in range(4):
        if turn & (1 << d):
            TURN_WITH_EDGE[d] |= tb


def solve(observation):
    data = observation.get('data')
    if not data or not data[0]:
        return "No Solution"

    H = len(data)
    W = len(data[0])
    V = H * W

    def vid(r, c):
        return r * W + c

    def rc(v):
        return (v // W, v % W)

    def in_bounds(r, c):
        return 0 <= r < H and 0 <= c < W

    def step(r, c, d, k=1):
        dr, dc = DRC[d]
        return r + dr * k, c + dc * k

    def add_req(req, v, mask):
        cur = req.get(v, ALL_DOMAIN)
        new_mask = cur & mask
        if new_mask == 0:
            return False
        req[v] = new_mask
        return True

    # Build edge list and per-vertex incidence.
    edges = []
    incident = [[] for _ in range(V)]
    for r in range(H):
        for c in range(W):
            v = vid(r, c)
            if r + 1 < H:
                w = vid(r + 1, c)
                edges.append((v, D, w, U))
                incident[v].append((w, D, U))
                incident[w].append((v, U, D))
            if c + 1 < W:
                w = vid(r, c + 1)
                edges.append((v, R, w, L))
                incident[v].append((w, R, L))
                incident[w].append((v, L, R))

    # Initial domains: boundary legality + clue shape.
    init_domains = [0] * V
    clues = []
    is_clue_vertex = [False] * V
    for r in range(H):
        for c in range(W):
            v = vid(r, c)
            dom = ALL_DOMAIN
            if r == 0:
                dom &= NOTUSES[U]
            if r == H - 1:
                dom &= NOTUSES[D]
            if c == 0:
                dom &= NOTUSES[L]
            if c == W - 1:
                dom &= NOTUSES[R]

            tok = data[r][c]
            if tok is not None:
                if not isinstance(tok, str) or len(tok) < 2:
                    return "No Solution"
                t = tok[0]
                try:
                    k = int(tok[1:])
                except ValueError:
                    return "No Solution"
                if t == 'W':
                    dom &= WHITE_ALLOWED
                elif t == 'B':
                    dom &= BLACK_ALLOWED
                else:
                    return "No Solution"
                is_clue_vertex[v] = True
                clues.append({'r': r, 'c': c, 'vid': v, 'type': t, 'k': k})

            if dom == 0:
                return "No Solution"
            init_domains[v] = dom

    if not clues:
        return "No Solution"

    # Enumerate all clue candidates.
    # Each candidate is a concrete "human deduction pattern":
    # choose orientation + split k into two arm lengths,
    # force every internal point of those arms to be straight,
    # and force the arm endpoints to be turns.
    for clue in clues:
        r, c, v0, t, k = clue['r'], clue['c'], clue['vid'], clue['type'], clue['k']
        cand_list = []
        seen = set()

        def push_candidate(req):
            items = tuple(sorted(req.items()))
            if items in seen:
                return
            for vv, mask in items:
                if init_domains[vv] & mask == 0:
                    return
            seen.add(items)
            impact = sum(8 - mask.bit_count() for _, mask in items)
            cand_list.append({
                'items': items,
                'map': dict(items),
                'impact': impact,
            })

        if k >= 2:
            if t == 'W':
                # Horizontal
                for a in range(1, k):
                    b = k - a
                    lc = c - a
                    rc2 = c + b
                    if not (0 <= lc < W and 0 <= rc2 < W):
                        continue
                    req = {}
                    ok = add_req(req, v0, BIT[HOR])
                    for i in range(1, a):
                        if ok:
                            vv = vid(r, c - i)
                            ok = add_req(req, vv, BIT[HOR])
                    if ok:
                        ok = add_req(req, vid(r, lc), TURN_WITH_EDGE[R])
                    for i in range(1, b):
                        if ok:
                            vv = vid(r, c + i)
                            ok = add_req(req, vv, BIT[HOR])
                    if ok:
                        ok = add_req(req, vid(r, rc2), TURN_WITH_EDGE[L])
                    if ok:
                        push_candidate(req)

                # Vertical
                for a in range(1, k):
                    b = k - a
                    ur = r - a
                    dr2 = r + b
                    if not (0 <= ur < H and 0 <= dr2 < H):
                        continue
                    req = {}
                    ok = add_req(req, v0, BIT[VER])
                    for i in range(1, a):
                        if ok:
                            vv = vid(r - i, c)
                            ok = add_req(req, vv, BIT[VER])
                    if ok:
                        ok = add_req(req, vid(ur, c), TURN_WITH_EDGE[D])
                    for i in range(1, b):
                        if ok:
                            vv = vid(r + i, c)
                            ok = add_req(req, vv, BIT[VER])
                    if ok:
                        ok = add_req(req, vid(dr2, c), TURN_WITH_EDGE[U])
                    if ok:
                        push_candidate(req)

            else:
                # Black clue: choose a turning orientation and split k across the two incident runs.
                for d1, d2 in ((U, R), (U, L), (D, R), (D, L)):
                    turn_local = (1 << d1) | (1 << d2)
                    turn_bit = BIT[turn_local]
                    for a in range(1, k):
                        b = k - a
                        er1, ec1 = step(r, c, d1, a)
                        er2, ec2 = step(r, c, d2, b)
                        if not (in_bounds(er1, ec1) and in_bounds(er2, ec2)):
                            continue
                        req = {}
                        ok = add_req(req, v0, turn_bit)

                        for i in range(1, a):
                            if ok:
                                rr, cc = step(r, c, d1, i)
                                ok = add_req(req, vid(rr, cc), BIT[AXIS_LOCAL[d1]])
                        if ok:
                            ok = add_req(req, vid(er1, ec1), TURN_WITH_EDGE[OPP[d1]])

                        for i in range(1, b):
                            if ok:
                                rr, cc = step(r, c, d2, i)
                                ok = add_req(req, vid(rr, cc), BIT[AXIS_LOCAL[d2]])
                        if ok:
                            ok = add_req(req, vid(er2, ec2), TURN_WITH_EDGE[OPP[d2]])

                        if ok:
                            push_candidate(req)

        clue['cands'] = cand_list
        clue['touched'] = tuple(sorted({vv for cand in cand_list for vv, _ in cand['items']}))
        clue['score'] = max((cand['impact'] for cand in cand_list), default=0)

        if not clue['cands']:
            return "No Solution"

    clue_vids = [clue['vid'] for clue in clues]

    vertex_touch_score = [0] * V
    for clue in clues:
        for vv in clue['touched']:
            vertex_touch_score[vv] += 1

    def apply_closed_forced_cycle(domains):
        # If a complete closed cycle is already forced, every outside vertex must be empty.
        fadj = [[] for _ in range(V)]
        fdeg = [0] * V
        for v, d, w, od in edges:
            if (domains[v] & NOTUSES[d]) == 0 and (domains[w] & NOTUSES[od]) == 0:
                fadj[v].append(w)
                fadj[w].append(v)
                fdeg[v] += 1
                fdeg[w] += 1

        changed = False
        seen = [False] * V
        for s in range(V):
            if fdeg[s] == 0 or seen[s]:
                continue
            stack = [s]
            seen[s] = True
            comp = []
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in fadj[x]:
                    if not seen[y]:
                        seen[y] = True
                        stack.append(y)
            if all(fdeg[x] == 2 for x in comp):
                comp_set = set(comp)
                for x in range(V):
                    if x not in comp_set:
                        nd = domains[x] & EMPTY_BIT
                        if nd == 0:
                            return False, changed
                        if nd != domains[x]:
                            domains[x] = nd
                            changed = True
        return True, changed

    def propagate(domains, clue_domains):
        while True:
            changed = False

            # Edge arc-consistency: both ends of an edge must agree on on/off.
            for v, d, w, od in edges:
                dv = domains[v]
                dw = domains[w]

                allow_v = 0
                if dw & USES[od]:
                    allow_v |= USES[d]
                if dw & NOTUSES[od]:
                    allow_v |= NOTUSES[d]
                ndv = dv & allow_v
                if ndv == 0:
                    return False
                if ndv != dv:
                    domains[v] = ndv
                    dv = ndv
                    changed = True

                allow_w = 0
                if dv & USES[d]:
                    allow_w |= USES[od]
                if dv & NOTUSES[d]:
                    allow_w |= NOTUSES[od]
                ndw = dw & allow_w
                if ndw == 0:
                    return False
                if ndw != dw:
                    domains[w] = ndw
                    changed = True

            # Clue candidate filtering and candidate-to-vertex propagation.
            for i, clue in enumerate(clues):
                mask = clue_domains[i]
                if mask == 0:
                    return False

                active = []
                bits = mask
                while bits:
                    lb = bits & -bits
                    idx = lb.bit_length() - 1
                    bits ^= lb
                    cand = clue['cands'][idx]
                    ok = True
                    for vv, cm in cand['items']:
                        if domains[vv] & cm == 0:
                            ok = False
                            break
                    if ok:
                        active.append(idx)

                if not active:
                    return False

                newmask = 0
                for idx in active:
                    newmask |= 1 << idx
                if newmask != mask:
                    clue_domains[i] = newmask
                    changed = True

                # If every remaining candidate constrains a touched vertex, union those possibilities.
                for vv in clue['touched']:
                    allowed = 0
                    constrained_by_all = True
                    for idx in active:
                        m = clue['cands'][idx]['map'].get(vv)
                        if m is None:
                            constrained_by_all = False
                            break
                        allowed |= m
                    if not constrained_by_all:
                        continue
                    nd = domains[vv] & allowed
                    if nd == 0:
                        return False
                    if nd != domains[vv]:
                        domains[vv] = nd
                        changed = True

            # Connectivity-style deduction:
            # any vertex not even possibly connected to the clue component must be empty.
            reachable = [False] * V
            dq = deque([clue_vids[0]])
            reachable[clue_vids[0]] = True
            while dq:
                v = dq.popleft()
                for w, d, od in incident[v]:
                    if not reachable[w] and (domains[v] & USES[d]) and (domains[w] & USES[od]):
                        reachable[w] = True
                        dq.append(w)

            for cv in clue_vids:
                if not reachable[cv]:
                    return False

            for v in range(V):
                if not reachable[v]:
                    nd = domains[v] & EMPTY_BIT
                    if nd == 0:
                        return False
                    if nd != domains[v]:
                        domains[v] = nd
                        changed = True

            ok, cyc_changed = apply_closed_forced_cycle(domains)
            if not ok:
                return False
            if cyc_changed:
                changed = True

            if not changed:
                return True

    def measure_arm(locals_, r, c, d):
        rr, cc = r, c
        axis_local = AXIS_LOCAL[d]
        incoming = OPP[d]
        limit = H * W + 5
        length = 0
        for _ in range(limit):
            cur = locals_[vid(rr, cc)]
            if not (cur & (1 << d)):
                return None
            rr, cc = step(rr, cc, d, 1)
            if not in_bounds(rr, cc):
                return None
            length += 1
            nxt = locals_[vid(rr, cc)]
            if nxt == axis_local:
                continue
            if nxt in TURN_LOCALS and (nxt & (1 << incoming)):
                return length
            return None
        return None

    def validate_and_extract(domains):
        locals_ = []
        for d in domains:
            local = SINGLETON_TO_LOCAL.get(d)
            if local is None:
                return None
            locals_.append(local)

        adj = [[] for _ in range(V)]
        used_vertices = []

        for v, d, w, od in edges:
            uv = bool(locals_[v] & (1 << d))
            uw = bool(locals_[w] & (1 << od))
            if uv != uw:
                return None
            if uv:
                adj[v].append(w)
                adj[w].append(v)

        for v in range(V):
            local = locals_[v]
            if local == EMP:
                if adj[v]:
                    return None
            else:
                if len(adj[v]) != 2:
                    return None
                used_vertices.append(v)

        if not used_vertices:
            return None

        # Single connected loop.
        seen = {used_vertices[0]}
        stack = [used_vertices[0]]
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        if len(seen) != len(used_vertices):
            return None

        # Check all clues exactly.
        for clue in clues:
            r, c, v0, t, k = clue['r'], clue['c'], clue['vid'], clue['type'], clue['k']
            local = locals_[v0]
            if t == 'W':
                if local not in (VER, HOR):
                    return None
            else:
                if local not in TURN_LOCALS:
                    return None

            dirs = [d for d in range(4) if local & (1 << d)]
            if len(dirs) != 2:
                return None
            total = 0
            for d in dirs:
                arm = measure_arm(locals_, r, c, d)
                if arm is None:
                    return None
                total += arm
            if total != k:
                return None

        # Extract ordered loop path.
        start = min(used_vertices, key=lambda x: rc(x))
        nbrs = sorted(adj[start], key=lambda x: rc(x))
        path = [rc(start)]
        prev = None
        cur = start
        nxt = nbrs[0]

        while True:
            path.append(rc(nxt))
            prev, cur = cur, nxt
            if cur == start:
                break
            a, b = adj[cur]
            nxt = a if a != prev else b

        return path

    def choose_branch(domains, clue_domains):
        best_kind = None
        best_idx = None
        best_size = 10**9
        best_tie = (-1, -1)

        for i, mask in enumerate(clue_domains):
            cnt = mask.bit_count()
            if cnt > 1:
                tie = (1, clues[i]['score'])
                if cnt < best_size or (cnt == best_size and tie > best_tie):
