AXIS_LOCAL = {U: VER, D: VER, L: HOR, R: HOR}
SINGLETON_TO_LOCAL = {1 << i: m for i, m in enumerate(STATE_MASKS)}

USES = [0, 0, 0, 0]
for i, m in enumerate(STATE_MASKS):
