    while mask:
        lb = mask & -mask
        yield lb.bit_length() - 1
        mask ^= lb


def mask_single(p):
    return 1 << p


def solve(observation):
    sys.setrecursionlimit(10000)

    data = observation['data']
    rows = len(data)
    cols = len(data[0])
    vcount = rows * cols

    def vid(r, c):
        return r * cols + c

    def pos(v):
        return divmod(v, cols)

    def inside(r, c):
        return 0 <= r < rows and 0 <= c < cols

