    valid_domain = [0] * vcount
    for r in range(rows):
        for c in range(cols):
            v = vid(r, c)
            mask = 0
            for p in ALL_PATTERN_IDS:
                ok = True
                for d in PATTERN_DIRS[p]:
                    nr, nc = r + DR[d], c + DC[d]
                    if not inside(nr, nc):
                        ok = False
                        break
                if ok:
                    mask |= 1 << p
            valid_domain[v] = mask

    clues = []
    clue_at = {}
    base_domain = [0] * vcount
    for r in range(rows):
        for c in range(cols):
            v = vid(r, c)
            token = data[r][c]
            if token is None:
                base_domain[v] = valid_domain[v]
            else:
                t = token[0]
                k = int(token[1:])
                if t == 'W':
                    base_domain[v] = valid_domain[v] & MASK_WHITE
                else:
                    base_domain[v] = valid_domain[v] & MASK_BLACK
                clues.append((v, t, k, r, c))
                clue_at[v] = len(clues) - 1
            if base_domain[v] == 0:
                return "No Solution"

    clue_vertices = [v for (v, _, _, _, _) in clues]

    def apply_restr(restr, v, m):
        if v in restr:
            nm = restr[v] & m
            if nm == 0:
                return False
            restr[v] = nm
        else:
            restr[v] = m
        return True

    def build_candidate(v, clue_pattern, branches):
        r, c = pos(v)
        restr = {}
        if not apply_restr(restr, v, mask_single(clue_pattern)):
            return None

        for d, length in branches:
            for s in range(1, length + 1):
                rr = r + DR[d] * s
                cc = c + DC[d] * s
                if not inside(rr, cc):
                    return None
                vv = vid(rr, cc)
                if s < length:
                    m = MASK_H if d in (L, R) else MASK_V
                else:
                    m = TURN_WITH_EDGE[OPP[d]]
                if not apply_restr(restr, vv, m):
                    return None

        # Must also respect base domains
