                return None

        return tuple(sorted(restr.items()))

    candidates = []
    candidate_sizes = []
    for v, t, k, r, c in clues:
        cands = {}
        if t == 'W':
            for a in range(1, k):
                b = k - a
                cand = build_candidate(v, H, [(L, a), (R, b)])
                if cand is not None:
                    cands[cand] = None
                cand = build_candidate(v, V, [(U, a), (D, b)])
                if cand is not None:
                    cands[cand] = None
        else:
            for a in range(1, k):
                b = k - a
                for pat, branches in (
                    (UR, [(U, a), (R, b)]),
                    (RD, [(R, a), (D, b)]),
                    (DL, [(D, a), (L, b)]),
                    (LU, [(L, a), (U, b)]),
                ):
                    cand = build_candidate(v, pat, branches)
                    if cand is not None:
                        cands[cand] = None
        cands = list(cands.keys())
