    clue_count = len(clues)

    def candidate_pair_compatible(map_a, map_b):
        merged = dict(map_a)
        for v, m in map_b.items():
            if v in merged:
                nm = merged[v] & m
                if nm == 0:
                    return False
                merged[v] = nm
            else:
                merged[v] = m

        # Local adjacency consistency on all jointly restricted edges
        for v, ma in merged.items():
            for nv, d in neighbors[v]:
                if v < nv and nv in merged:
                    if not EDGE_MASK_COMP[d][ma][merged[nv]]:
                        return False
        return True

    compat = [[None] * clue_count for _ in range(clue_count)]
    for i in range(clue_count):
        for j in range(clue_count):
            if i == j:
                continue
            arr = []
            for mi in cand_maps[i]:
                m = 0
                for k, mj in enumerate(cand_maps[j]):
                    if candidate_pair_compatible(mi, mj):
                        m |= 1 << k
                arr.append(m)
            compat[i][j] = arr

