    def ac3(dom):
        queue = deque(arcs)
        changed_any = False
        while queue:
            v, nv, d = queue.popleft()
            old = dom[v]
            new = 0
            m = old
            while m:
                lb = m & -m
                p = lb.bit_length() - 1
                if dom[nv] & COMP[d][p]:
                    new |= lb
                m ^= lb
            if new == 0:
                return False, changed_any
            if new != old:
                dom[v] = new
                changed_any = True
                for pv, pd in neighbors[v]:
                    if pv != nv:
                        queue.append((pv, v, OPP[pd]))
        return True, changed_any

    def present_possible(dom, v, nv, d):
        return bool((dom[v] & HAS_MASK[d]) and (dom[nv] & HAS_MASK[OPP[d]]))

    def forced_present(dom, v, nv, d):
        return bool((dom[v] & NOT_HAS_MASK[d]) == 0 and (dom[nv] & NOT_HAS_MASK[OPP[d]]) == 0)

    def forced_used_vertex(dom, v):
        return (dom[v] & mask_single(OFF)) == 0

    def connectivity_ok(dom):
        required = set(clue_vertices)
        for v in range(vcount):
            if forced_used_vertex(dom, v):
                required.add(v)

        if required:
            start = next(iter(required))
            seen = {start}
            q = deque([start])
            while q:
                v = q.popleft()
                for nv, d in neighbors[v]:
                    if nv not in seen and present_possible(dom, v, nv, d):
                        seen.add(nv)
                        q.append(nv)
            if not required.issubset(seen):
                return False

        # Detect forced closed subloops that cannot connect to the rest
        f_adj = [[] for _ in range(vcount)]
        f_deg = [0] * vcount
        any_forced = False
        for v, nv, d in undirected_edges:
            if forced_present(dom, v, nv, d):
                any_forced = True
                f_adj[v].append(nv)
                f_adj[nv].append(v)
                f_deg[v] += 1
                f_deg[nv] += 1

        if any_forced:
            seen = [False] * vcount
            for s in range(vcount):
                if seen[s] or not f_adj[s]:
                    continue
                comp = []
                stack = [s]
                seen[s] = True
                while stack:
                    v = stack.pop()
                    comp.append(v)
                    for nv in f_adj[v]:
                        if not seen[nv]:
                            seen[nv] = True
                            stack.append(nv)

                if all(f_deg[v] == 2 for v in comp):
                    comp_set = set(comp)
                    outside_required = False
                    for rv in required:
                        if rv not in comp_set:
                            outside_required = True
                            break
                    if outside_required:
                        return False

        return True

    def propagate(dom, cand_dom):
        while True:
            changed = False

            # Candidate -> vertex consistency
            for ci in range(clue_count):
                old = cand_dom[ci]
                new = 0
                m = old
                cands = candidates[ci]
                while m:
                    lb = m & -m
                    idx = lb.bit_length() - 1
                    ok = True
                    for v, mask in cands[idx]:
                        if dom[v] & mask == 0:
                            ok = False
                            break
                    if ok:
                        new |= lb
                    m ^= lb
                if new == 0:
                    return False
                if new != old:
                    cand_dom[ci] = new
                    changed = True

            # Pairwise AC on clue candidates
            q = deque((i, j) for i in range(clue_count) for j in range(clue_count) if i != j)
            while q:
                i, j = q.popleft()
                old = cand_dom[i]
                new = 0
                mj = cand_dom[j]
                comp_ij = compat[i][j]
                m = old
                while m:
                    lb = m & -m
                    idx = lb.bit_length() - 1
                    if comp_ij[idx] & mj:
                        new |= lb
                    m ^= lb
                if new == 0:
                    return False
                if new != old:
                    cand_dom[i] = new
                    changed = True
                    for h in range(clue_count):
                        if h != i and h != j:
                            q.append((h, i))

            # Vertex reductions implied by all remaining candidates of a clue
            for ci in range(clue_count):
                cm = cand_dom[ci]
                total = cm.bit_count()
                counts = {}
                unions = {}
                m = cm
                cands = candidates[ci]
                while m:
                    lb = m & -m
                    idx = lb.bit_length() - 1
                    for v, mask in cands[idx]:
                        counts[v] = counts.get(v, 0) + 1
                        unions[v] = unions.get(v, 0, 0) | mask
                    m ^= lb
                for v, cnt in counts.items():
                    if cnt == total:
                        new = dom[v] & unions[v]
                        if new == 0:
                            return False
                        if new != dom[v]:
                            dom[v] = new
                            changed = True

            ok, ac_changed = ac3(dom)
            if not ok:
                return False
            if ac_changed:
                changed = True

            if not connectivity_ok(dom):
                return False

            if not changed:
                return True

    def complete(dom):
        return all((m & (m - 1)) == 0 for m in dom)

    def build_solution(dom):
        pats = [m.bit_length() - 1 for m in dom]
        adj = [[] for _ in range(vcount)]
        used = set()

        for v in range(vcount):
            p = pats[v]
            if p != OFF:
                used.add(v)

        for v in range(vcount):
            p = pats[v]
            for d in PATTERN_DIRS[p]:
                nr, nc = pos(v)[0] + DR[d], pos(v)[1] + DC[d]
                if not inside(nr, nc):
                    return None
                nv = vid(nr, nc)
                np = pats[nv]
                if OPP[d] not in PATTERN_DIRS[np]:
                    return None
                if v < nv:
                    adj[v].append(nv)
                    adj[nv].append(v)

        for v in used:
            if len(adj[v]) != 2:
                return None

        if not clue_vertices:
            return None
        for v in clue_vertices:
            if v not in used:
                return None

        start = clue_vertices[0]
        seen = {start}
        q = deque([start])
        while q:
            v = q.popleft()
            for nv in adj[v]:
                if nv not in seen:
                    seen.add(nv)
                    q.append(nv)

        if seen != used:
            return None

        start = min(used)
        path = [pos(start)]
        prev = None
        curr = start
        limit = len(used) + 1
        for _ in range(limit):
            nxts = adj[curr]
            if prev is None:
                nxt = min(nxts)
            else:
                if nxts[0] == prev:
                    nxt = nxts[1]
                else:
                    nxt = nxts[0]
            path.append(pos(nxt))
            if nxt == start:
                break
            prev, curr = curr, nxt
        else:
            return None

        if len(path) != len(used) + 1:
            return None
        return path

    bad = set()

    def state_sig(dom, cand_dom):
        return (tuple(dom), tuple(cand_dom))

    def choose_branch(dom, cand_dom):
        best_clue = None
        best_key = None
        for ci in range(clue_count):
            cnt = cand_dom[ci].bit_count()
            if cnt > 1:
                weight = max(candidate_sizes[ci][idx] for idx in bit_iter(cand_dom[ci]))
                key = (cnt, -weight, ci)
                if best_key is None or key < best_key:
                    best_key = key
                    best_clue = ci
        if best_clue is not None:
            order = sorted(bit_iter(cand_dom[best_clue]), key=lambda i: (-candidate_sizes[best_clue][i], i))
            return ('clue', best_clue, order)

        best_v = None
        best_v_key = None
        for v in range(vcount):
            cnt = dom[v].bit_count()
            if cnt > 1:
                key = (cnt, v)
                if best_v_key is None or key < best_v_key:
                    best_v_key = key
                    best_v = v
        if best_v is not None:
            ids = list(bit_iter(dom[best_v]))
            ids.sort(key=lambda p: (p != OFF, p))
            return ('vertex', best_v, ids)

        return None

    def search(dom, cand_dom):
        if not propagate(dom, cand_dom):
            return None

        sig = state_sig(dom, cand_dom)
        if sig in bad:
            return None

        if complete(dom):
            sol = build_solution(dom)
            if sol is not None:
                return sol
            bad.add(sig)
            return None

        choice = choose_branch(dom, cand_dom)
        if choice is None:
            bad.add(sig)
            return None

        kind, idx, options = choice
        if kind == 'clue':
            for opt in options:
                ndom = dom[:]
                ncand = cand_dom[:]
                ncand[idx] = 1 << opt
                res = search(ndom, ncand)
                if res is not None:
                    return res
        else:
            for p in options:
                ndom = dom[:]
                ncand = cand_dom[:]
                ndom[idx] = 1 << p
                res = search(ndom, ncand)
                if res is not None:
                    return res

        bad.add(sig)
        return None

    dom0 = base_domain[:]
    cand0 = full_cand_domain[:]
    ans = search(dom0, cand0)
    return ans if ans is not None else "No Solution"


