    bad = set()

    def state_sig(dom, cand_dom):
        return (tuple(dom), tuple(cand_dom))

    def choose_branch(dom, cand_dom):
        best_clue = None
        best_key = None
        for ci in range(clue_count):
            cnt = cand_dom[ci].bit_count()
            if cnt > 1:
                weight = max(candidate_sizes[ci][idx] for idx in bit_iter(cand_dom[ci]))
                key = (cnt, -weight, ci)
                if best_key is None or key < best_key:
                    best_key = key
                    best_clue = ci
        if best_clue is not None:
            order = sorted(bit_iter(cand_dom[best_clue]), key=lambda i: (-candidate_sizes[best_clue][i], i))
            return ('clue', best_clue, order)

        best_v = None
        best_v_key = None
        for v in range(vcount):
            cnt = dom[v].bit_count()
            if cnt > 1:
                key = (cnt, v)
                if best_v_key is None or key < best_v_key:
                    best_v_key = key
                    best_v = v
        if best_v is not None:
            ids = list(bit_iter(dom[best_v]))
            ids.sort(key=lambda p: (p != OFF, p))
            return ('vertex', best_v, ids)

        return None

    def search(dom, cand_dom):
        if not propagate(dom, cand_dom):
            return None

        sig = state_sig(dom, cand_dom)
        if sig in bad:
            return None

        if complete(dom):
            sol = build_solution(dom)
            if sol is not None:
                return sol
            bad.add(sig)
            return None

        choice = choose_branch(dom, cand_dom)
        if choice is None:
            bad.add(sig)
            return None

        kind, idx, options = choice
        if kind == 'clue':
            for opt in options:
                ndom = dom[:]
                ncand = cand_dom[:]
                ncand[idx] = 1 << opt
                res = search(ndom, ncand)
                if res is not None:
                    return res
        else:
            for p in options:
                ndom = dom[:]
                ncand = cand_dom[:]
                ndom[idx] = 1 << p
                res = search(ndom, ncand)
                if res is not None:
                    return res

        bad.add(sig)
        return None

    dom0 = base_domain[:]
    cand0 = full_cand_domain[:]
    ans = search(dom0, cand0)
    return ans if ans is not None else "No Solution"


