# Pattern encoding on a dot:
# 0: unused
# 1: NS
# 2: EW
# 3: NE
# 4: NW
# 5: SE
# 6: SW

P_U = 0
P_NS = 1
P_EW = 2
P_NE = 3
P_NW = 4
P_SE = 5
P_SW = 6

N, E, S, W = 0, 1, 2, 3
DR = (-1, 0, 1, 0)
DC = (0, 1, 0, -1)
OPP = (S, W, N, E)

PATTERN_EDGES = (
    (0, 0, 0, 0),  # U
    (1, 0, 1, 0),  # NS
    (0, 1, 0, 1),  # EW
    (1, 1, 0, 0),  # NE
    (1, 0, 0, 1),  # NW
    (0, 1, 1, 0),  # SE
    (0, 0, 1, 1),  # SW
)

PATTERN_DIRS = tuple(tuple(d for d in range(4) if PATTERN_EDGES[p][d]) for p in range(7))

MASKS = [1 << p for p in range(7)]
MASK_U = MASKS[P_U]
MASK_NS = MASKS[P_NS]
MASK_EW = MASKS[P_EW]
MASK_NE = MASKS[P_NE]
MASK_NW = MASKS[P_NW]
MASK_SE = MASKS[P_SE]
MASK_SW = MASKS[P_SW]
MASK_STRAIGHT = MASK_NS | MASK_EW
MASK_TURN = MASK_NE | MASK_NW | MASK_SE | MASK_SW
FULL_MASK = (1 << 7) - 1

EDGE_PAT_MASK = [[0, 0] for _ in range(4)]
for d in range(4):
    for p in range(7):
        EDGE_PAT_MASK[d][PATTERN_EDGES[p][d]] |= 1 << p

# If a clue's arm extends in direction d, then the endpoint turn must include the opposite edge.
ENDPOINT_MASK = {
    N: MASK_SE | MASK_SW,  # endpoint receives the segment from the south
    E: MASK_NW | MASK_SW,  # endpoint receives the segment from the west
    S: MASK_NE | MASK_NW,  # endpoint receives the segment from the north
    W: MASK_NE | MASK_SE,  # endpoint receives the segment from the east
