OPP = (S, W, N, E)

PATTERN_EDGES = (
    (0, 0, 0, 0),  # U
    (1, 0, 1, 0),  # NS
    (0, 1, 0, 1),  # EW
    (1, 1, 0, 0),  # NE
    (1, 0, 0, 1),  # NW
    (0, 1, 1, 0),  # SE
    (0, 0, 1, 1),  # SW
)

