MASK_NS = MASKS[P_NS]
MASK_EW = MASKS[P_EW]
MASK_NE = MASKS[P_NE]
MASK_NW = MASKS[P_NW]
MASK_SE = MASKS[P_SE]
MASK_SW = MASKS[P_SW]
