def initial_line_domain(front_clue, back_clue, all_perms, by_pair, by_left, by_right):
    front = 0 if front_clue in (None, 0) else front_clue
    back = 0 if back_clue in (None, 0) else back_clue

    if front and back:
        return list(by_pair.get((front, back), ()))
    if front:
        return list(by_left.get(front, ()))
    if back:
        return list(by_right.get(back, ()))
