    cell_masks = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            mask = row_masks[r][c] & col_masks[c][r]
            if mask == 0:
                return None
            cell_masks[r][c] = mask
    return row_masks, col_masks, cell_masks


