    branch = choose_branch(row_domains, col_domains, cell_masks, n)

    if branch[0] == "line":
        _, kind, idx = branch
        if kind == "row":
            candidates = list(row_domains[idx])
        else:
            candidates = list(col_domains[idx])

        candidates.sort(
            key=lambda perm: line_candidate_score(kind, idx, perm, row_domains, col_domains),
            reverse=True,
        )

        for perm in candidates:
            new_rows = clone_domains(row_domains)
            new_cols = clone_domains(col_domains)
            if kind == "row":
                new_rows[idx] = [perm]
            else:
