    _, r, c = branch
    values = mask_values(cell_masks[r][c], n)

    # Prefer values with lower support first for fail-fast pruning.
    values.sort(
        key=lambda v: (
            sum(1 for rp in row_domains[r] if rp[c] == v)
            * sum(1 for cp in col_domains[c] if cp[r] == v),
            v,
        )
    )

