            return False

    for r, clue in enumerate(obs["L"]):
        if clue and visible_count(grid[r]) != clue:
            return False

    for r, clue in enumerate(obs["R"]):
        if clue and visible_count(reversed(grid[r])) != clue:
            return False

    return True


def solve(observation):
    observation = normalize_observation(observation)
    n = len(observation["U"])

    if not (len(observation["D"]) == len(observation["L"]) == len(observation["R"]) == n):
        return "No Solution"

    all_perms, by_pair, by_left, by_right = build_catalog(n)

    row_domains = []
    for r in range(n):
        dom = initial_line_domain(
            observation["L"][r],
            observation["R"][r],
            all_perms,
            by_pair,
            by_left,
            by_right,
        )
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        dom = initial_line_domain(
            observation["U"][c],
            observation["D"][c],
            all_perms,
            by_pair,
            by_left,
            by_right,
        )
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    grid = search(row_domains, col_domains, n)
    if grid is None:
        return "No Solution"

    if not validate_grid(grid, observation):
        return "No Solution"

    return repr(grid)


