    domain_cache = {(a, b): [] for a in range(n + 1) for b in range(n + 1)}
    for p in permutations(range(1, n + 1)):
        l = visible_count(p)
        r = visible_count(reversed(p))
        domain_cache[(0, 0)].append(p)
        domain_cache[(l, 0)].append(p)
        domain_cache[(0, r)].append(p)
        domain_cache[(l, r)].append(p)

    hall_subsets = []
    for s in range(1, 1 << n):
        k = s.bit_count()
        if 1 < k < n:
            inside = [i for i in range(n) if (s >> i) & 1]
            outside = [i for i in range(n) if not ((s >> i) & 1)]
            hall_subsets.append((inside, outside, k))
    return domain_cache, hall_subsets


