def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data or not all(isinstance(row, list) for row in data):
        return "No Solution"

    n1 = len(data)
    if any(len(row) != n1 for row in data):
        return "No Solution"
    n = n1 - 1
    if n <= 0:
        return "No Solution"

    # Domain mask per cell:
    # 1 -> '\'
    # 2 -> '/'
    # 3 -> both possible
    def cell_id(r, c):
        return r * n + c

    def vid(r, c):
        return r * n1 + c

    cells = n * n
    verts = n1 * n1

    cell_ends = [None] * cells
    for r in range(n):
        for c in range(n):
            cid = cell_id(r, c)
            cell_ends[cid] = (
                (vid(r, c), vid(r + 1, c + 1)),      # '\'
                (vid(r, c + 1), vid(r + 1, c)),      # '/'
            )

    clues = []
    cell_to_clues = [[] for _ in range(cells)]

    for r in range(n1):
        for c in range(n1):
            k = data[r][c]
            if k is None:
                continue

            items = []
            # Around dot (r, c):
            # NW cell -> bottom-right -> '\'
            if r > 0 and c > 0:
                items.append((cell_id(r - 1, c - 1), 0))
            # NE cell -> bottom-left -> '/'
            if r > 0 and c < n:
                items.append((cell_id(r - 1, c), 1))
            # SW cell -> top-right -> '/'
            if r < n and c > 0:
                items.append((cell_id(r, c - 1), 1))
            # SE cell -> top-left -> '\'
            if r < n and c < n:
                items.append((cell_id(r, c), 0))

            if not isinstance(k, int) or k < 0 or k > len(items):
                return "No Solution"

            patterns = []
            d = len(items)
            for pat in range(1 << d):
                cnt = 0
                for i, (_, contrib_val) in enumerate(items):
                    if ((pat >> i) & 1) == contrib_val:
                        cnt += 1
                if cnt == k:
                    patterns.append(pat)

            clue = {
                "k": k,
                "items": tuple(items),
                "patterns": tuple(patterns),
            }
            clue_index = len(clues)
            clues.append(clue)
