# General Slant solver:
# - exactly one diagonal per cell ('/' or '\')
# - numbered dots count incident chosen diagonals
# - chosen diagonals must form no closed loop
#
# The solver uses:
# 1) strong local clue propagation (exact-count arc consistency),
# 2) cycle-avoidance propagation via DSU on fixed edges,
# 3) failed-literal probing and common-consequence deduction,
# 4) small, well-ordered recursive search only when logic stalls.

def solve(observation):
    data = observation["data"]
    n1 = len(data)
    if n1 == 0 or any(len(row) != n1 for row in data):
        return "No Solution"
    n = n1 - 1
    if n < 0:
        return "No Solution"

    num_cells = n * n
    num_dots = n1 * n1

    SLASH = 0      # '/'
    BACKSLASH = 1  # '\'
    MASK_SLASH = 1
    MASK_BACK = 2
    MASK_BOTH = 3

    def dot_id(r, c):
        return r * n1 + c

    # Flatten clues.
    clues = [None] * num_dots
    for r in range(n1):
        for c in range(n1):
            clues[dot_id(r, c)] = data[r][c]

    # Precompute cell endpoints and dot incidences.
    # For a cell:
    #   '/'  connects TR-BL
    #   '\' connects TL-BR
    cell_endpoints = [None] * num_cells         # [(slash_a, slash_b), (back_a, back_b)]
    cell_adj_dots = [None] * num_cells          # [tl, tr, bl, br]
    incidents = [[] for _ in range(num_dots)]   # dot -> list of (cell, orientation_that_incidents_dot)

    for r in range(n):
        for c in range(n):
            cell = r * n + c
            tl = dot_id(r, c)
            tr = dot_id(r, c + 1)
            bl = dot_id(r + 1, c)
            br = dot_id(r + 1, c + 1)

            cell_endpoints[cell] = ((tr, bl), (tl, br))
            cell_adj_dots[cell] = (tl, tr, bl, br)

            incidents[tl].append((cell, BACKSLASH))
            incidents[tr].append((cell, SLASH))
            incidents[bl].append((cell, SLASH))
            incidents[br].append((cell, BACKSLASH))

    # Quick validity check on clues.
    for d in range(num_dots):
        k = clues[d]
        if k is not None and (k < 0 or k > len(incidents[d])):
            return "No Solution"

    dot_degree = [len(incidents[d]) for d in range(num_dots)]

    # Static cell heuristic: nearby extreme clues are more constraining.
    static_cell_score = [0] * num_cells
    for cell in range(num_cells):
        score = 0
        for d in cell_adj_dots[cell]:
            k = clues[d]
            if k is not None:
                deg = dot_degree[d]
                score += 2 + abs(2 * k - deg)
        static_cell_score[cell] = score

    def mask_to_value(mask):
        if mask == MASK_SLASH:
            return SLASH
        if mask == MASK_BACK:
            return BACKSLASH
        return None

    def value_to_mask(v):
        return MASK_SLASH if v == SLASH else MASK_BACK

    def singleton(mask):
        return mask == MASK_SLASH or mask == MASK_BACK

    def count_singletons(domains):
        s = 0
        for d in domains:
            if d == MASK_SLASH or d == MASK_BACK:
                s += 1
        return s

