import sys

SLASH = 1   # '/'
BACK = 2    # '\'
BOTH = 3

sys.setrecursionlimit(1_000_000)


def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data or not isinstance(data[0], list) or not data[0]:
        return "No Solution"

    point_rows = len(data)
    point_cols = len(data[0])
    if point_rows < 2 or point_cols < 2:
        return "No Solution"
    if any(len(row) != point_cols for row in data):
        return "No Solution"

    h = point_rows - 1
    w = point_cols - 1
    cell_count = h * w
    dot_count = point_rows * point_cols

    def dot_id(r, c):
        return r * point_cols + c

    clues = [data[r][c] for r in range(point_rows) for c in range(point_cols)]
    slash_edges = [None] * cell_count
    back_edges = [None] * cell_count
    cell_corners = [None] * cell_count
    dot_inc = [[] for _ in range(dot_count)]

    for r in range(h):
        for c in range(w):
            cid = r * w + c
            nw = dot_id(r, c)
            ne = dot_id(r, c + 1)
            sw = dot_id(r + 1, c)
            se = dot_id(r + 1, c + 1)

            slash_edges[cid] = (ne, sw)
            back_edges[cid] = (nw, se)
            cell_corners[cid] = (nw, ne, sw, se)

            dot_inc[nw].append((cid, BACK))
            dot_inc[ne].append((cid, SLASH))
            dot_inc[sw].append((cid, SLASH))
            dot_inc[se].append((cid, BACK))

    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def build_dsu(domains):
        parent = list(range(dot_count))
        size = [1] * dot_count
        for cid, dom in enumerate(domains):
            if dom == SLASH:
                u, v = slash_edges[cid]
            elif dom == BACK:
                u, v = back_edges[cid]
            else:
                continue
            ru = find(parent, u)
            rv = find(parent, v)
            if ru == rv:
                return None
            if size[ru] < size[rv]:
                ru, rv = rv, ru
            parent[rv] = ru
            size[ru] += size[rv]
        return parent

    def dot_bounds(dot, domains):
        low = 0
        high = 0
        for cid, tbit in dot_inc[dot]:
            dom = domains[cid]
            if dom == tbit:
                low += 1
                high += 1
            elif dom & tbit:
                high += 1
        return low, high

    def candidate_possible(cid, bit, domains, parent):
        if not (domains[cid] & bit):
            return False

        if bit == SLASH:
            u, v = slash_edges[cid]
        else:
            u, v = back_edges[cid]

        # No-loop rule: a chosen edge cannot connect two vertices already connected
        # by previously fixed edges.
        if find(parent, u) == find(parent, v):
            return False

        # Human-style local trial: pretend this orientation is chosen and verify
        # that each affected clue can still be satisfied.
        for dot in cell_corners[cid]:
            clue = clues[dot]
            if clue is None:
                continue
            low = 0
            high = 0
            for ocid, tbit in dot_inc[dot]:
                dom = bit if ocid == cid else domains[ocid]
                if dom == tbit:
                    low += 1
                    high += 1
                elif dom & tbit:
                    high += 1
            if clue < low or clue > high:
                return False

        return True

    def propagate(domains):
        domains = domains[:]
        while True:
            parent = build_dsu(domains)
            if parent is None:
                return None

            changed = False

            # Rule 1: remove orientations that immediately break a clue or form a loop.
            for cid, dom in enumerate(domains):
                if dom == BOTH:
                    newdom = 0
                    if candidate_possible(cid, SLASH, domains, parent):
                        newdom |= SLASH
                    if candidate_possible(cid, BACK, domains, parent):
                        newdom |= BACK
                    if newdom == 0:
                        return None
                    if newdom != dom:
                        domains[cid] = newdom
                        changed = True

            # Rule 2: dot saturation.
            # low = guaranteed incident segments, high = still possible incident segments.
            # If clue == low, every optional touching segment is forbidden.
            # If clue == high, every optional touching segment is forced.
            for dot, clue in enumerate(clues):
                if clue is None:
                    continue

                low = 0
                high = 0
                ambiguous = []

                for cid, tbit in dot_inc[dot]:
                    dom = domains[cid]
                    if dom == tbit:
                        low += 1
                        high += 1
                    elif dom & tbit:
                        high += 1
                        if dom == BOTH:
                            ambiguous.append((cid, tbit))

                if clue < low or clue > high:
                    return None

                if clue == low:
                    for cid, tbit in ambiguous:
                        newdom = domains[cid] & (BOTH ^ tbit)
                        if newdom == 0:
                            return None
                        if newdom != domains[cid]:
                            domains[cid] = newdom
                            changed = True

                elif clue == high:
                    for cid, tbit in ambiguous:
                        newdom = domains[cid] & tbit
                        if newdom == 0:
                            return None
                        if newdom != domains[cid]:
                            domains[cid] = newdom
                            changed = True

            if not changed:
                return domains

    def solved(domains):
        if any(dom == BOTH for dom in domains):
            return False
        if build_dsu(domains) is None:
            return False
        for dot, clue in enumerate(clues):
            if clue is None:
                continue
            low, high = dot_bounds(dot, domains)
            if low != clue or high != clue:
                return False
        return True

    def choose_cell(domains):
        # Fail-first heuristic: branch on a cell touching many clues, especially tight ones.
        best_cid = None
        best_key = None
        for cid, dom in enumerate(domains):
            if dom != BOTH:
                continue
            clue_count = 0
            total_slack = 0
            tight_dots = 0
            for dot in cell_corners[cid]:
                clue = clues[dot]
                if clue is None:
                    continue
                clue_count += 1
                low, high = dot_bounds(dot, domains)
                slack = high - low
                total_slack += slack
                if slack <= 1:
                    tight_dots += 1
            key = (-clue_count, total_slack, -tight_dots, cid)
            if best_key is None or key < best_key:
                best_key = key
                best_cid = cid
        if best_cid is not None:
            return best_cid
        for cid, dom in enumerate(domains):
            if dom == BOTH:
                return cid
        return None

    def orientation_priority(cid, bit, domains):
        # Try the orientation that most tightens nearby clue ranges.
        score = 0
        for dot in cell_corners[cid]:
            clue = clues[dot]
            if clue is None:
                continue

            low = 0
            high = 0
            low2 = 0
            high2 = 0

            for ocid, tbit in dot_inc[dot]:
                dom = domains[ocid]
                if dom == tbit:
                    low += 1
                    high += 1
                elif dom & tbit:
                    high += 1

                dom2 = bit if ocid == cid else dom
                if dom2 == tbit:
                    low2 += 1
                    high2 += 1
                elif dom2 & tbit:
                    high2 += 1

            score += (high - low) - (high2 - low2)
            if low2 == clue == high2:
                score += 3
            elif clue == low2 or clue == high2:
                score += 1

        return score

    dead = set()

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        key = tuple(domains)
        if key in dead:
            return None

        if solved(domains):
            return domains

        cid = choose_cell(domains)
        if cid is None:
            dead.add(key)
            return None

        options = [bit for bit in (SLASH, BACK) if domains[cid] & bit]
        options.sort(key=lambda bit: orientation_priority(cid, bit, domains), reverse=True)

        for bit in options:
            nxt = domains[:]
            nxt[cid] = bit
            res = dfs(nxt)
            if res is not None:
                return res

        dead.add(key)
        return None

    result = dfs([BOTH] * cell_count)
    if result is None:
        return "No Solution"

    answer = []
    for r in range(h):
        row = []
        for c in range(w):
            dom = result[r * w + c]
            row.append('/' if dom == SLASH else '\\')
        answer.append(row)
    return repr(answer)


