            clue_cnt = 0
            total_u = 0
            smallest_u = 10**9
            for d, _ in cell_clue_corners[cid]:
                clue_cnt += 1
                uu = undec[d]
                total_u += uu
                if uu < smallest_u:
                    smallest_u = uu
            if clue_cnt == 0:
                key = (10**9, 10**9, cid)
            else:
                key = (smallest_u, total_u, cid)
            if best_key is None or key < best_key:
                best_key = key
                best_cell = cid
        return best_cell

    dead = set()

    def search(domains, already_propagated=False):
        if not already_propagated:
            domains = propagate(domains)
            if domains is None:
                return None

        state_key = tuple(domains)
        if state_key in dead:
            return None

        if BOTH not in domains:
            return domains

        analysis = build_analysis(domains)
        if analysis is None:
            dead.add(state_key)
            return None

        _, ones, undec = analysis
        cid = choose_cell(domains, ones, undec)
        if cid is None:
            dead.add(state_key)
            return None

        # Two-way lookahead: try both orientations, propagate immediately,
        # and search the branch that collapses the most cells first.
        branches = []
        for orient in (SLASH, BACK):
            trial = domains[:]
            trial[cid] = orient
            reduced = propagate(trial)
            if reduced is not None:
                branches.append((reduced.count(BOTH), tuple(reduced), reduced))

        if not branches:
            dead.add(state_key)
            return None

        branches.sort(key=lambda x: (x[0], x[1]))

        seen = set()
        for _, reduced_key, reduced in branches:
            if reduced_key in seen:
                continue
            seen.add(reduced_key)
            sol = search(reduced, True)
            if sol is not None:
                return sol

        dead.add(state_key)
        return None

    initial = [BOTH] * num_cells
    solution = search(initial)
    if solution is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(CH[solution[r * n + c]])
        grid.append(row)
    return str(grid)


