        self.edge_cells = [[] for _ in range(self.ECOUNT)]
        self.vertex_edges = [[] for _ in range(self.VCOUNT)]
        self.cell_edges = [None] * self.CCOUNT
        self.cell_corners = [None] * self.CCOUNT

        # Edges and vertex incidence
        for r in range(N + 1):
