                a = vid(r, c)
                b = vid(r, c + 1)
                self.edge_ends[e] = (a, b)
                self.vertex_edges[a].append(e)
                self.vertex_edges[b].append(e)

        for r in range(N):
            for c in range(N + 1):
                e = vidx(r, c)
                a = vid(r, c)
                b = vid(r + 1, c)
                self.edge_ends[e] = (a, b)
                self.vertex_edges[a].append(e)
                self.vertex_edges[b].append(e)

        # Cells and edge-cell incidence
        for r in range(N):
            for c in range(N):
                cid = r * N + c
                top = hidx(r, c)
                right = vidx(r, c + 1)
                bottom = hidx(r + 1, c)
                left = vidx(r, c)
                edges = [top, right, bottom, left]  # T, R, B, L
                self.cell_edges[cid] = edges
                for e in edges:
