        # that are not yet forced off.
        on_vertices = [v for v in range(self.VCOUNT) if self.vert_on[v] > 0]
        if on_vertices:
            start = on_vertices[0]
            seen = {start}
            dq = deque([start])
            while dq:
                v = dq.popleft()
                for e in self.vertex_edges[v]:
                    if self.val[e] == 0:
                        continue
                    a, b = self.edge_ends[e]
                    w = b if a == v else a
                    if w not in seen:
                        seen.add(w)
                        dq.append(w)
            for v in on_vertices:
                if v not in seen:
                    return False

