                        a, b = self.edge_ends[e]
                        w = b if a == u else a
                        if w not in visited_vertices:
                            visited_vertices.add(w)
                            stack.append(w)

                if edges == verts:
                    cycle_components += 1
                    if edges != self.on_edge_count:
                        return False

            if cycle_components > 1:
                return False

        return True

    def edge_score(self, e):
        score = 0

        # Clue pressure
        for cid in self.edge_cells[e]:
            clue = self.clues[cid]
            if clue is None:
                continue
            on = self.cell_on[cid]
            unk = self.cell_unk[cid]
            need = clue - on

            score += 8
            if 0 <= need <= unk:
                score += 4 - min(need, unk - need)
                if need == 0 or need == unk:
                    score += 10
            else:
                score += 20

        # Vertex pressure
        a, b = self.edge_ends[e]
        for v in (a, b):
            on = self.vert_on[v]
            unk = self.vert_unk[v]
            if on == 1:
                score += 12
            elif on == 2:
                score += 9
            if unk <= 2:
                score += 8
            elif unk == 3:
                score += 3

        return score

