                (bits >> 1) & 1,  # R
                (bits >> 2) & 1,  # B
                (bits >> 3) & 1,  # L
            )
            self.patterns[sum(p)].append(p)

    def clone(self):
        other = self.__class__.__new__(self.__class__)

        other.data = self.data
        other.N = self.N
        other.HCOUNT = self.HCOUNT
        other.ECOUNT = self.ECOUNT
        other.VCOUNT = self.VCOUNT
        other.CCOUNT = self.CCOUNT

        other.vid = self.vid
        other.hidx = self.hidx
        other.vidx = self.vidx

        other.clues = self.clues
        other.edge_ends = self.edge_ends
        other.edge_cells = self.edge_cells
        other.vertex_edges = self.vertex_edges
        other.cell_edges = self.cell_edges
        other.cell_corners = self.cell_corners
        other.patterns = self.patterns

        other.val = self.val[:]
        other.cell_on = self.cell_on[:]
        other.cell_unk = self.cell_unk[:]
        other.vert_on = self.vert_on[:]
        other.vert_unk = self.vert_unk[:]
        other.on_edge_count = self.on_edge_count
        other.unknown_edge_count = self.unknown_edge_count

        other.queue = deque()
        return other

    def assign(self, e, x):
        cur = self.val[e]
        if cur != -1:
            return cur == x

        self.val[e] = x
        self.unknown_edge_count -= 1
        if x == 1:
            self.on_edge_count += 1

        for cid in self.edge_cells[e]:
            self.cell_unk[cid] -= 1
            if x == 1:
                self.cell_on[cid] += 1
            if self.clues[cid] is not None:
                self.queue.append(("c", cid))

        a, b = self.edge_ends[e]
        self.vert_unk[a] -= 1
        self.vert_unk[b] -= 1
        if x == 1:
            self.vert_on[a] += 1
            self.vert_on[b] += 1
        self.queue.append(("v", a))
        self.queue.append(("v", b))
        return True

    def _cell_pattern_feasible(self, cid, pat):
        edges = self.cell_edges[cid]

        # Current assignments must match the pattern.
        for i, e in enumerate(edges):
            cur = self.val[e]
            if cur != -1 and cur != pat[i]:
                return False

        # Each corner vertex must still be completable to degree 0 or 2,
        # accounting for outside edges at that vertex.
        for _, i, j, outside in self.cell_corners[cid]:
            local_on = pat[i] + pat[j]
            outside_on = 0
            outside_unk = 0
            for e in outside:
                cur = self.val[e]
                if cur == 1:
                    outside_on += 1
                elif cur == -1:
                    outside_unk += 1

            base = outside_on + local_on
            ok = False

            # Can total degree end at 0?
            if base == 0:
                ok = True

            # Can total degree end at 2?
            need = 2 - base
            if 0 <= need <= outside_unk:
                ok = True

            if not ok:
                return False

        return True

    def propagate_cell(self, cid):
        clue = self.clues[cid]
        if clue is None:
            return True

        # Fast count feasibility check
        if self.cell_on[cid] > clue:
            return False
        if self.cell_on[cid] + self.cell_unk[cid] < clue:
            return False

        feasible = []
        for pat in self.patterns[clue]:
            if self._cell_pattern_feasible(cid, pat):
                feasible.append(pat)

        if not feasible:
            return False

        edges = self.cell_edges[cid]
        for i, e in enumerate(edges):
            if self.val[e] != -1:
                continue
            forced = feasible[0][i]
            same = True
            for pat in feasible[1:]:
                if pat[i] != forced:
                    same = False
                    break
            if same and not self.assign(e, forced):
                return False

        return True

    def propagate_vertex(self, v):
        on = self.vert_on[v]
        unk = self.vert_unk[v]

        if on > 2:
            return False

        possible_unknown_ons = set()
        for target in (0, 2):
            need = target - on
            if 0 <= need <= unk:
                possible_unknown_ons.add(need)

        if not possible_unknown_ons:
            return False

        unknown_edges = [e for e in self.vertex_edges[v] if self.val[e] == -1]

        if possible_unknown_ons == {0}:
            for e in unknown_edges:
                if not self.assign(e, 0):
                    return False
        elif possible_unknown_ons == {unk}:
            for e in unknown_edges:
                if not self.assign(e, 1):
                    return False

        return True

    def global_checks(self):
        # All already-on edges must remain mutually connectable through edges
        # that are not yet forced off.
        on_vertices = [v for v in range(self.VCOUNT) if self.vert_on[v] > 0]
        if on_vertices:
            start = on_vertices[0]
            seen = {start}
            dq = deque([start])
            while dq:
                v = dq.popleft()
                for e in self.vertex_edges[v]:
                    if self.val[e] == 0:
                        continue
                    a, b = self.edge_ends[e]
                    w = b if a == v else a
                    if w not in seen:
                        seen.add(w)
                        dq.append(w)
            for v in on_vertices:
                if v not in seen:
                    return False

        # No detached closed loop is allowed before completion.
        if self.on_edge_count:
            visited_vertices = set()
            used_edges = set()
            cycle_components = 0

            for v in range(self.VCOUNT):
                if self.vert_on[v] == 0 or v in visited_vertices:
                    continue

                stack = [v]
                visited_vertices.add(v)
                verts = 0
                edges = 0

                while stack:
                    u = stack.pop()
                    verts += 1
                    for e in self.vertex_edges[u]:
                        if self.val[e] != 1:
                            continue
                        if e not in used_edges:
                            used_edges.add(e)
                            edges += 1
                        a, b = self.edge_ends[e]
                        w = b if a == u else a
                        if w not in visited_vertices:
                            visited_vertices.add(w)
                            stack.append(w)

                if edges == verts:
                    cycle_components += 1
                    if edges != self.on_edge_count:
                        return False

            if cycle_components > 1:
                return False

        return True

    def edge_score(self, e):
        score = 0

        # Clue pressure
        for cid in self.edge_cells[e]:
            clue = self.clues[cid]
            if clue is None:
                continue
            on = self.cell_on[cid]
            unk = self.cell_unk[cid]
            need = clue - on

            score += 8
            if 0 <= need <= unk:
                score += 4 - min(need, unk - need)
                if need == 0 or need == unk:
                    score += 10
            else:
                score += 20

        # Vertex pressure
        a, b = self.edge_ends[e]
        for v in (a, b):
            on = self.vert_on[v]
            unk = self.vert_unk[v]
            if on == 1:
                score += 12
            elif on == 2:
                score += 9
            if unk <= 2:
                score += 8
            elif unk == 3:
                score += 3

        return score

    def branch_order(self, e):
        bias = 0

        for cid in self.edge_cells[e]:
            clue = self.clues[cid]
            if clue is None:
                continue
            need = clue - self.cell_on[cid]
            unk = self.cell_unk[cid]
            bias += 2 * need - unk

        a, b = self.edge_ends[e]
        for v in (a, b):
            if self.vert_on[v] == 1:
                bias += 2
            elif self.vert_on[v] == 2:
                bias -= 3
            elif self.vert_on[v] == 0 and self.vert_unk[v] == 1:
                bias -= 2

        return (1, 0) if bias > 0 else (0, 1)

    def candidate_unknown_edges(self, limit=None):
        items = []
        for e, cur in enumerate(self.val):
            if cur == -1:
                items.append((self.edge_score(e), e))
        items.sort(reverse=True)
        if limit is not None:
            items = items[:limit]
        return [e for _, e in items]

    def failed_literal_pass(self):
        if self.unknown_edge_count == 0:
            return False

        # Use all candidates on small/medium states, capped on larger ones.
        limit = None if self.unknown_edge_count <= 40 else 24

        for e in self.candidate_unknown_edges(limit=limit):
            if self.val[e] != -1:
                continue

            ok0 = False
            ok1 = False

            child0 = self.clone()
            if child0.assign(e, 0) and child0.propagate(no_failed=True):
                ok0 = True

            child1 = self.clone()
            if child1.assign(e, 1) and child1.propagate(no_failed=True):
                ok1 = True

            if not ok0 and not ok1:
                return None
            if not ok0:
                if not self.assign(e, 1):
                    return None
                return True
            if not ok1:
                if not self.assign(e, 0):
                    return None
                return True

        return False

    def propagate(self, no_failed=False):
        while True:
            while self.queue:
                typ, idx = self.queue.popleft()
                if typ == "c":
                    if not self.propagate_cell(idx):
                        return False
                else:
                    if not self.propagate_vertex(idx):
                        return False

            if not self.global_checks():
                return False

            if no_failed:
                return True

            step = self.failed_literal_pass()
            if step is None:
                return False
            if not step:
                return True

    def choose_edge(self):
        best_e = None
        best_score = -1
        for e, cur in enumerate(self.val):
            if cur != -1:
                continue
            s = self.edge_score(e)
            if s > best_score:
                best_score = s
                best_e = e
        return best_e

    def is_complete_solution(self):
        if self.unknown_edge_count != 0:
            return False
        if self.on_edge_count == 0:
            return False

        for cid, clue in enumerate(self.clues):
            if clue is not None and self.cell_on[cid] != clue:
                return False

        on_vertices = []
        for v in range(self.VCOUNT):
            if self.vert_on[v] not in (0, 2):
                return False
            if self.vert_on[v] == 2:
                on_vertices.append(v)

        if not on_vertices:
            return False

        start = on_vertices[0]
        seen = {start}
        dq = deque([start])
        edge_visits = 0

        while dq:
            v = dq.popleft()
            for e in self.vertex_edges[v]:
                if self.val[e] != 1:
                    continue
                edge_visits += 1
                a, b = self.edge_ends[e]
                w = b if a == v else a
                if w not in seen:
                    seen.add(w)
                    dq.append(w)

        edges = edge_visits // 2
        return len(seen) == len(on_vertices) and edges == self.on_edge_count and edges == len(on_vertices)

    def vertex_coord(self, v):
        return (v // (self.N + 1), v % (self.N + 1))

    def extract_loop(self):
        adj = [[] for _ in range(self.VCOUNT)]
        for e, cur in enumerate(self.val):
            if cur == 1:
                a, b = self.edge_ends[e]
                adj[a].append(b)
                adj[b].append(a)

        start = None
        for v in range(self.VCOUNT):
            if len(adj[v]) == 2:
                start = v
                break
        if start is None:
            return None

        for nbrs in adj:
            if nbrs:
                if len(nbrs) != 2:
                    return None
                nbrs.sort()

        path = [self.vertex_coord(start)]
        prev = None
        cur = start

        while True:
            nbrs = adj[cur]
            if prev is None:
                nxt = nbrs[0]
            else:
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]

            path.append(self.vertex_coord(nxt))
            prev, cur = cur, nxt

            if cur == start:
                break
            if len(path) > self.on_edge_count + 1:
                return None

        if len(path) != self.on_edge_count + 1:
            return None

        return path

    def solve_state(self):
        if not self.propagate():
            return None

        if self.unknown_edge_count == 0:
            if self.is_complete_solution():
                return self.extract_loop()
            return None

        e = self.choose_edge()
        if e is None:
            return None

        for x in self.branch_order(e):
            child = self.clone()
            if child.assign(e, x):
                res = child.solve_state()
                if res is not None:
                    return res

        return None


def solve(observation):
    data = observation.get("data")
    if not data or any(len(row) != len(data) for row in data):
        return "No Solution"

    solver = SlitherlinkSolver(data)
    ans = solver.solve_state()
    return "No Solution" if ans is None else repr(ans)


