class SlitherlinkSolver:
    # Domain encoding per edge:
    #   1 -> definitely off
    #   2 -> definitely on
    #   3 -> unknown {off,on}
    OFF = 1
    ON = 2
    ANY = 3

    def __init__(self, data):
        self.data = data
        self.R = len(data)
        self.C = len(data[0]) if self.R else 0
        self.V = (self.R + 1) * (self.C + 1)

        self.edge_ends = []
        self.h = [[None] * self.C for _ in range(self.R + 1)]
        self.v = [[None] * (self.C + 1) for _ in range(self.R)]

        # Build edge indices.
        for r in range(self.R + 1):
            for c in range(self.C):
                eid = len(self.edge_ends)
                self.h[r][c] = eid
                self.edge_ends.append((self.vid(r, c), self.vid(r, c + 1)))
        for r in range(self.R):
            for c in range(self.C + 1):
                eid = len(self.edge_ends)
                self.v[r][c] = eid
                self.edge_ends.append((self.vid(r, c), self.vid(r + 1, c)))

        self.E = len(self.edge_ends)

        self.vertex_edges = [[] for _ in range(self.V)]
        for e, (u, v) in enumerate(self.edge_ends):
            self.vertex_edges[u].append(e)
            self.vertex_edges[v].append(e)

        # Precompute tiny local pattern tables.
        pop = [0] * 16
        for i in range(1, 16):
            pop[i] = pop[i >> 1] + (i & 1)

        self.cell_patterns = {k: [p for p in range(16) if pop[p] == k] for k in range(5)}
        self.vertex_patterns = {d: [p for p in range(1 << d) if pop[p] in (0, 2)] for d in range(5)}

        self.cons_edges = []
        self.cons_patterns = []
        self.cons_kind = []  # 0 = clue-cell, 1 = vertex
        self.edge_to_constraints = [[] for _ in range(self.E)]
        self.edge_adj_clues = [[] for _ in range(self.E)]

        self.clue_constraints = []
        self.vertex_constraints = []

        # Cell constraints: exact clue count.
        for r in range(self.R):
            for c in range(self.C):
                clue = data[r][c]
                if clue is None:
                    continue
                edges = (
