        best_score = None
        best_vals = None

        for e, dom in enumerate(domains):
            if dom != self.ANY:
                continue
            clue_touch = len(self.edge_adj_clues[e])
            clue_sum = sum(self.edge_adj_clues[e])
            deg_cons = len(self.edge_to_constraints[e])

            score = (-clue_touch, -clue_sum, -deg_cons, e)
            if best_e is None or score < best_score:
                best_e = e
                best_score = score
                best_vals = (self.ON, self.OFF) if clue_sum >= 4 else (self.OFF, self.ON)

