        prev = None
        cur = start

        while True:
            nxts = adj[cur]
            if prev is None:
                nxt = nxts[0]
            else:
                nxt = nxts[0] if nxts[0] != prev else nxts[1]

            a, b = (cur, nxt) if cur < nxt else (nxt, cur)
            if (a, b) in visited_edges:
                return nxt == start and len(visited_edges) == on_count
            visited_edges.add((a, b))
            prev, cur = cur, nxt

    def dfs(self, domains):
        if self.solved(domains):
            return domains if self.final_valid(domains) else None

        choice = self.select_branch(domains)
        if choice is None:
            return None

        branches = []
        seen = set()

        if choice[0] == "constraint":
            _, cid, edges, pats = choice
            for pat in pats:
                nd = domains.copy()
                changed = []
                if not self.apply_pattern(nd, edges, pat, changed):
                    continue
                if not changed:
                    continue
                if self.propagate(nd, changed):
                    key = tuple(nd)
                    if key not in seen:
                        seen.add(key)
                        branches.append(nd)
        else:
            _, e, vals = choice
            for need in vals:
                nd = domains.copy()
                changed = []
                if not self.apply_edge_value(nd, e, need, changed):
                    continue
                if self.propagate(nd, changed):
                    key = tuple(nd)
                    if key not in seen:
                        seen.add(key)
                        branches.append(nd)

        if not branches:
            return None

        branches.sort(key=lambda d: (sum(x == self.ANY for x in d), -sum(x == self.ON for x in d)))

        for nd in branches:
            out = self.dfs(nd)
            if out is not None:
                return out
        return None

    def canonicalize_cycle(self, coords):
        cyc = coords[:-1]
        n = len(cyc)
        start = min(range(n), key=lambda i: cyc[i])

        seq1 = [cyc[(start + i) % n] for i in range(n)]
        seq1.append(seq1[0])

        seq2 = [cyc[(start - i) % n] for i in range(n)]
        seq2.append(seq2[0])

        return seq1 if tuple(seq1) <= tuple(seq2) else seq2

    def extract_loop(self, domains):
        adj = [[] for _ in range(self.V)]
        for e, dom in enumerate(domains):
            if dom == self.ON:
                u, v = self.edge_ends[e]
                adj[u].append(v)
                adj[v].append(u)

        start = None
        for v in range(self.V):
            if adj[v]:
                start = v
                break

        if start is None:
            return []

        path = [start]
        prev = None
        cur = start

        while True:
            nxts = adj[cur]
            nxt = nxts[0] if prev is None or nxts[0] != prev else nxts[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break

        coords = [self.vrc(v) for v in path]
        return self.canonicalize_cycle(coords)

    def solve(self):
        domains = [self.ANY] * self.E
        if not self.propagate(domains):
            return None
        return self.dfs(domains)


def solve(observation):
    data = observation.get("data", [])
    if not data or not data[0]:
        return "No Solution"

    solver = SlitherlinkSolver(data)
    result = solver.solve()
    if result is None:
        return "No Solution"
    loop = solver.extract_loop(result)
    if not loop:
        return "No Solution"
    return repr(loop)


