        u, v = self.edge_ends[edge]
        for vid in (u, v):
            inc = self.vertex_edges[vid]
            on = 0
            unk = 0
            for e in inc:
                s = state[e]
                if s == 1:
                    on += 1
                elif s == -1:
                    unk += 1

