            sc = self._edge_score(state, e)
            if best_score is None or sc > best_score:
                best_score = sc
                best_edge = e
        return best_edge

    def _simulate_branch(self, state, edge, value):
        if state[edge] != -1:
            return None if state[edge] != value else state[:]
        trial = state[:]
        trial[edge] = value
        if not self.propagate(trial, self.var_to_constraints[edge], do_lookahead=True):
            return None
        return trial

    def _extract_path(self, state):
        # Full validation + ordered loop extraction
        if any(s == -1 for s in state):
            return None

        on_adj = [[] for _ in range(self.dot_count)]
        edge_on_count = 0
        for e, val in enumerate(state):
            if val == 1:
                edge_on_count += 1
                u, v = self.edge_ends[e]
                on_adj[u].append(v)
                on_adj[v].append(u)

        used = [u for u in range(self.dot_count) if on_adj[u]]
        if not used:
            return None
        for u in used:
            if len(on_adj[u]) != 2:
                return None

        # Single connected component
        vis = {used[0]}
        stack = [used[0]]
        while stack:
            u = stack.pop()
            for v in on_adj[u]:
                if v not in vis:
                    vis.add(v)
                    stack.append(v)
        if len(vis) != len(used):
            return None

        # Deterministic ordered traversal
        start = min(used, key=lambda x: self.dot_coords[x])
        path = [self.dot_coords[start]]
        prev = None
        cur = start

        for _ in range(edge_on_count):
            nbrs = on_adj[cur]
            if prev is None:
                a, b = nbrs
                nxt = a if self.dot_coords[a] < self.dot_coords[b] else b
            else:
                nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(self.dot_coords[nxt])
            prev, cur = cur, nxt

        if cur != start:
            return None
        if len(path) != edge_on_count + 1:
            return None
        if len(set(path[:-1])) != len(path) - 1:
            return None

        return path

    def _search(self, state):
        if -1 not in state:
            return self._extract_path(state)

        edge = self._choose_branch_edge(state)
        if edge is None:
            return None

        branches = []
        for value in (1, 0):
            trial = self._simulate_branch(state, edge, value)
            if trial is not None:
                branches.append((trial.count(-1), trial))

        branches.sort(key=lambda x: x[0])

        for _, trial in branches:
            ans = self._search(trial)
            if ans is not None:
                return ans
        return None

    def solve(self):
        state = [-1] * self.edge_count
        if not self.propagate(state, do_lookahead=True):
            return None
        return self._search(state)


