        branch_cells = choose_branch_cells(state)
        if not branch_cells:
            return None

        # Human-like contradiction testing:
        # try each candidate as a temporary star; eliminate those that instantly fail.
        reduced = list(state)
        viable = []
        for r, c in branch_cells:
            trial = list(state)
            trial[r] = 1 << c
            normalized_trial = normalize(tuple(trial))
            if normalized_trial is None:
                reduced[r] &= ~(1 << c)
            else:
                viable.append(((r, c), normalized_trial))

        reduced_state = tuple(reduced)
        if reduced_state != state:
            return search(reduced_state)

        if not viable:
            return None

        # Search the most constrained resulting states first.
        viable.sort(key=lambda item: sum(m.bit_count() for m in item[1]))
        for (_, _), next_state in viable:
            ans = search(next_state)
            if ans is not None:
                return ans
        return None

    initial_state = tuple(full_cols_mask for _ in range(n))
    solution = search(initial_state)
    if solution is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, mask in enumerate(solution):
        c = singleton_col(mask)
        answer[r][c] = 'S'
    return repr(answer)


