            m = state[r] & region_row_masks[g][r]
            while m:
                b = m & -m
                cells.append((r, b.bit_length() - 1))
                m ^= b
        return cells

    def collect_column_cells(state, c):
        bit = 1 << c
        return [(r, c) for r in range(n) if state[r] & bit]

    def collect_row_cells(state, r):
        return [(r, c) for c in iter_bits(state[r])]

    def choose_branch_cells(state):
        # Branch on the smallest unresolved unit, preferring region/column over row on ties.
        best_cells = None
        best_key = (n + 1, 9)

        # Regions.
        for g in range(n):
            cells = collect_region_cells(state, g)
            k = len(cells)
            if 1 < k < best_key[0] or (k == best_key[0] and 0 < best_key[1]):
                best_key = (k, 0)
                best_cells = cells

        # Columns.
        for c in range(n):
            cells = collect_column_cells(state, c)
            k = len(cells)
            if 1 < k < best_key[0] or (k == best_key[0] and 1 < best_key[1]):
                best_key = (k, 1)
                best_cells = cells

        # Rows.
        for r in range(n):
            k = state[r].bit_count()
            if 1 < k < best_key[0] or (k == best_key[0] and 2 < best_key[1]):
                best_key = (k, 2)
                best_cells = collect_row_cells(state, r)

        return best_cells

    @lru_cache(maxsize=None)
    def search(state):
        state = normalize(state)
        if state is None:
            return None

        if all(is_singleton(m) for m in state):
            return state if verify(state) else None

        branch_cells = choose_branch_cells(state)
        if not branch_cells:
            return None

        # Human-like contradiction testing:
        # try each candidate as a temporary star; eliminate those that instantly fail.
        reduced = list(state)
        viable = []
        for r, c in branch_cells:
            trial = list(state)
            trial[r] = 1 << c
            normalized_trial = normalize(tuple(trial))
            if normalized_trial is None:
                reduced[r] &= ~(1 << c)
            else:
                viable.append(((r, c), normalized_trial))

        reduced_state = tuple(reduced)
        if reduced_state != state:
            return search(reduced_state)

        if not viable:
            return None

        # Search the most constrained resulting states first.
        viable.sort(key=lambda item: sum(m.bit_count() for m in item[1]))
        for (_, _), next_state in viable:
            ans = search(next_state)
            if ans is not None:
                return ans
        return None

    initial_state = tuple(full_cols_mask for _ in range(n))
    solution = search(initial_state)
    if solution is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, mask in enumerate(solution):
        c = singleton_col(mask)
        answer[r][c] = 'S'
    return repr(answer)


