# General 1-star Star Battle solver:
# - exactly 1 star per row
# - exactly 1 star per column
# - exactly 1 star per region
# - stars cannot touch, including diagonally
#
# The solver uses:
# 1) bitset domains
# 2) singleton propagation on rows/cols/regions
# 3) human-like line/region interaction rules
# 4) local adjacency support checks
# 5) Hall-set pruning on row/col/region bipartite relations
# 6) lightweight failed-literal lookahead
# 7) tightly pruned backtracking only when needed


class _StarSolver:
    HALL_LIMIT = 12

    def __init__(self, region_grid):
        self.data = region_grid
        self.n = len(region_grid)
        self.rcount = len({v for row in region_grid for v in row})
        self.cell_count = self.n * self.n
        self.dead = set()

        self.idx = [[r * self.n + c for c in range(self.n)] for r in range(self.n)]
        self.row_of = [0] * self.cell_count
        self.col_of = [0] * self.cell_count
        self.reg_of = [0] * self.cell_count

        self.row_masks = [0] * self.n
        self.col_masks = [0] * self.n
        self.region_masks = [0] * self.rcount

        for r in range(self.n):
            for c in range(self.n):
                i = self.idx[r][c]
                g = region_grid[r][c]
                self.row_of[i] = r
                self.col_of[i] = c
                self.reg_of[i] = g
                self.row_masks[r] |= 1 << i
                self.col_masks[c] |= 1 << i
                self.region_masks[g] |= 1 << i

        self.touch_masks = [0] * self.cell_count
        self.conflict_masks = [0] * self.cell_count
        for r in range(self.n):
            for c in range(self.n):
                i = self.idx[r][c]
                touch = 0
                for dr in (-1, 0, 1):
                    rr = r + dr
                    if not (0 <= rr < self.n):
                        continue
                    for dc in (-1, 0, 1):
                        cc = c + dc
                        if not (0 <= cc < self.n):
                            continue
                        if dr == 0 and dc == 0:
                            continue
                        touch |= 1 << self.idx[rr][cc]
                self.touch_masks[i] = touch
                self.conflict_masks[i] = (
                    self.row_masks[r] | self.col_masks[c] | self.region_masks[self.reg_of[i]] | touch
                ) & ~(1 << i)

        self.full_alive = (1 << self.cell_count) - 1

        self.row_combo_cells = self._build_combo_cells(self.row_masks)
        self.col_combo_cells = self._build_combo_cells(self.col_masks)
        self.reg_combo_cells = self._build_combo_cells(self.region_masks)

    @staticmethod
    def _single_index(bits):
        return (bits & -bits).bit_length() - 1

    @staticmethod
    def _iter_bits(bits):
        while bits:
            lsb = bits & -bits
            yield lsb.bit_length() - 1
            bits ^= lsb

    @staticmethod
    def _build_combo_cells(unit_masks):
        size = 1 << len(unit_masks)
        combo = [0] * size
        for mask in range(1, size):
            lsb = mask & -mask
            idx = lsb.bit_length() - 1
            combo[mask] = combo[mask ^ lsb] | unit_masks[idx]
        return combo

    def _force_cell(self, alive, chosen, i):
        bit = 1 << i
        if not (alive & bit):
            return None
        if chosen & self.conflict_masks[i]:
            return None
        if chosen & bit:
            return alive, chosen
        chosen |= bit
        alive = (alive & ~self.conflict_masks[i]) | bit
        return alive, chosen

    def _has_perfect_matching(self, masks, right_count):
        order = sorted(range(len(masks)), key=lambda k: masks[k].bit_count())
        match = [-1] * right_count

        def dfs(li, seen):
            opts = masks[li]
            while opts:
                lsb = opts & -opts
                r = lsb.bit_length() - 1
                opts ^= lsb
                if seen[r]:
                    continue
                seen[r] = True
                if match[r] == -1 or dfs(match[r], seen):
                    match[r] = li
                    return True
            return False

        for li in order:
            seen = [False] * right_count
            if not dfs(li, seen):
                return False
        return True

    def _hall_prune(self, alive, chosen, left_ids, masks, right_count, remove_mask_fn):
        m = len(left_ids)
        if m == 0:
            return alive, False

        for mask in masks:
            if mask == 0:
                return None

        if m > self.HALL_LIMIT:
            if not self._has_perfect_matching(masks, right_count):
                return None
            return alive, False

        left_global_masks = [1 << u for u in left_ids]
        subset_left = [0] * (1 << m)
        subset_right = [0] * (1 << m)

        for s in range(1, 1 << m):
            lsb = s & -s
            j = lsb.bit_length() - 1
            prev = s ^ lsb
            subset_left[s] = subset_left[prev] | left_global_masks[j]
            subset_right[s] = subset_right[prev] | masks[j]
            size = s.bit_count()
            rights = subset_right[s]
            rc = rights.bit_count()
            if rc < size:
                return None
            if rc == size and size < m:
                rem = remove_mask_fn(subset_left[s], rights) & alive
                if rem:
                    if rem & chosen:
                        return None
                    return alive & ~rem, True
        return alive, False

    def _build_graphs(self, alive, chosen):
        active_rows = []
        row_to_cols = []
        row_to_regs = []

        active_cols = []
        col_to_rows = []
        col_to_regs = []

        active_regs = []
        reg_to_rows = []
        reg_to_cols = []

        for r in range(self.n):
            if chosen & self.row_masks[r]:
                continue
            bits = alive & self.row_masks[r]
            if bits == 0:
                return None
            cm = 0
            gm = 0
            for i in self._iter_bits(bits):
                cm |= 1 << self.col_of[i]
                gm |= 1 << self.reg_of[i]
            active_rows.append(r)
            row_to_cols.append(cm)
            row_to_regs.append(gm)

        for c in range(self.n):
            if chosen & self.col_masks[c]:
                continue
            bits = alive & self.col_masks[c]
            if bits == 0:
                return None
            rm = 0
            gm = 0
            for i in self._iter_bits(bits):
                rm |= 1 << self.row_of[i]
                gm |= 1 << self.reg_of[i]
            active_cols.append(c)
            col_to_rows.append(rm)
            col_to_regs.append(gm)

        for g in range(self.rcount):
            if chosen & self.region_masks[g]:
                continue
            bits = alive & self.region_masks[g]
            if bits == 0:
                return None
            rm = 0
            cm = 0
            for i in self._iter_bits(bits):
                rm |= 1 << self.row_of[i]
                cm |= 1 << self.col_of[i]
            active_regs.append(g)
            reg_to_rows.append(rm)
            reg_to_cols.append(cm)

        if not (len(active_rows) == len(active_cols) == len(active_regs)):
            return None

        return (
            active_rows, row_to_cols, row_to_regs,
            active_cols, col_to_rows, col_to_regs,
            active_regs, reg_to_rows, reg_to_cols,
        )

    def _apply_hall(self, alive, chosen):
        graphs = self._build_graphs(alive, chosen)
        if graphs is None:
            return None

        (
            active_rows, row_to_cols, row_to_regs,
            active_cols, col_to_rows, col_to_regs,
            active_regs, reg_to_rows, reg_to_cols,
        ) = graphs

        checks = [
            (
                active_rows,
                row_to_cols,
                self.n,
                lambda left, right: self.col_combo_cells[right] & ~self.row_combo_cells[left],
            ),
            (
                active_cols,
                col_to_rows,
                self.n,
                lambda left, right: self.row_combo_cells[right] & ~self.col_combo_cells[left],
            ),
            (
                active_rows,
                row_to_regs,
                self.rcount,
                lambda left, right: self.reg_combo_cells[right] & ~self.row_combo_cells[left],
            ),
            (
                active_regs,
                reg_to_rows,
                self.n,
                lambda left, right: self.row_combo_cells[right] & ~self.reg_combo_cells[left],
            ),
            (
                active_cols,
                col_to_regs,
                self.rcount,
                lambda left, right: self.reg_combo_cells[right] & ~self.col_combo_cells[left],
            ),
            (
                active_regs,
                reg_to_cols,
                self.n,
                lambda left, right: self.col_combo_cells[right] & ~self.reg_combo_cells[left],
            ),
        ]

        for left_ids, masks, right_count, remover in checks:
            res = self._hall_prune(alive, chosen, left_ids, masks, right_count, remover)
            if res is None:
                return None
            new_alive, changed = res
            if changed:
                return new_alive, True

        return alive, False

    def _failed_literal(self, alive, chosen):
        best_bits = 0
        best_count = 4

        for unit_masks in (self.row_masks, self.col_masks, self.region_masks):
            for mask in unit_masks:
                if chosen & mask:
                    continue
                bits = alive & mask
                cnt = bits.bit_count()
                if 2 <= cnt < best_count:
                    best_count = cnt
                    best_bits = bits
                    if cnt == 2:
                        break
            if best_count == 2:
                break

        if best_bits == 0:
            return alive, chosen, False

        impossible = 0
        for i in self._iter_bits(best_bits):
            nxt = self._force_cell(alive, chosen, i)
            if nxt is None or self._propagate(nxt[0], nxt[1], allow_failed_literal=False) is None:
                impossible |= 1 << i

        if impossible:
            if impossible & chosen:
                return None
            return alive & ~impossible, chosen, True

        return alive, chosen, False

    def _propagate(self, alive, chosen, allow_failed_literal=True):
        while True:
            changed = False

            # Unit singles and consistency.
            for unit_masks in (self.row_masks, self.col_masks, self.region_masks):
                for mask in unit_masks:
                    chosen_bits = chosen & mask
                    if chosen_bits.bit_count() > 1:
                        return None
                    bits = alive & mask
                    if chosen_bits:
                        rem = bits & ~chosen_bits
                        if rem:
                            if rem & chosen:
                                return None
                            alive &= ~rem
                            changed = True
                    else:
                        if bits == 0:
                            return None
                        if bits & (bits - 1) == 0:
                            i = self._single_index(bits)
                            nxt = self._force_cell(alive, chosen, i)
                            if nxt is None:
                                return None
                            alive, chosen = nxt
                            changed = True
            if changed:
                continue

            # Region -> single row/col, row/col -> single region.
            for g in range(self.rcount):
                if chosen & self.region_masks[g]:
                    continue
                bits = alive & self.region_masks[g]
                rows = 0
                cols = 0
                for i in self._iter_bits(bits):
                    rows |= 1 << self.row_of[i]
                    cols |= 1 << self.col_of[i]
                if rows.bit_count() == 1:
                    r = self._single_index(rows)
                    rem = (alive & self.row_masks[r]) & ~self.region_masks[g]
                    if rem:
                        if rem & chosen:
                            return None
                        alive &= ~rem
                        changed = True
                        break
                if cols.bit_count() == 1:
                    c = self._single_index(cols)
                    rem = (alive & self.col_masks[c]) & ~self.region_masks[g]
                    if rem:
                        if rem & chosen:
                            return None
                        alive &= ~rem
                        changed = True
                        break
            if changed:
                continue

            for r in range(self.n):
                if chosen & self.row_masks[r]:
                    continue
                bits = alive & self.row_masks[r]
                regs = 0
                for i in self._iter_bits(bits):
                    regs |= 1 << self.reg_of[i]
                if regs.bit_count() == 1:
                    g = self._single_index(regs)
                    rem = (alive & self.region_masks[g]) & ~self.row_masks[r]
                    if rem:
                        if rem & chosen:
                            return None
                        alive &= ~rem
                        changed = True
                        break
            if changed:
