                    continue
                bits = alive & self.col_masks[c]
                regs = 0
                for i in self._iter_bits(bits):
                    regs |= 1 << self.reg_of[i]
                if regs.bit_count() == 1:
                    g = self._single_index(regs)
                    rem = (alive & self.region_masks[g]) & ~self.col_masks[c]
                    if rem:
                        if rem & chosen:
                            return None
                        alive &= ~rem
                        changed = True
                        break
            if changed:
