from functools import lru_cache
import sys


# Fast specialized 2-star solver.
# Human-like structure:
# 1) Each row is represented by one legal 2-star placement (a non-adjacent pair of columns).
# 2) Adjacent-row compatibility enforces "stars do not touch".
# 3) Exact-2 filters on every column and every region prune row placements aggressively.
# 4) Only then, if needed, branch on the most constrained row.

def solve(observation):
    data = observation.get("data")
    if not isinstance(data, list) or not data:
        return "No Solution"
    n = len(data)
    if any(not isinstance(row, list) or len(row) != n for row in data):
        return "No Solution"

    # Normalize region ids to 0..R-1
    region_map = {}
    next_region = 0
    regions = []
    for row in data:
        out_row = []
        for x in row:
            if x not in region_map:
                region_map[x] = next_region
                next_region += 1
            out_row.append(region_map[x])
        regions.append(out_row)
    rcount = next_region

    # In a standard N x N 2-star battle, rows imply 2N stars total,
    # and regions imply 2 * (#regions) stars total, so #regions must be N.
    if rcount != n:
        return "No Solution"

    target = 2
    sys.setrecursionlimit(10000)

    # All legal row patterns: exactly 2 stars, not horizontally adjacent.
    pairs = []
    pair_col_masks = []
    for c1 in range(n):
        for c2 in range(c1 + 2, n):
            pairs.append((c1, c2))
            pair_col_masks.append((1 << c1) | (1 << c2))

    pcount = len(pairs)
    if pcount == 0:
        return "No Solution"

    all_patterns = (1 << pcount) - 1
    full_col_bits = (1 << n) - 1

    # Column -> patterns containing that column
    col_masks = [0] * n
    for p, (c1, c2) in enumerate(pairs):
        bit = 1 << p
        col_masks[c1] |= bit
        col_masks[c2] |= bit
    not_col_masks = [all_patterns ^ m for m in col_masks]

    # Pattern compatibility for adjacent rows: no same-column or diagonal touching.
    compat = [0] * pcount
    for i, m in enumerate(pair_col_masks):
        forbidden = m | ((m << 1) & full_col_bits) | (m >> 1)
        cm = 0
        for j, nm in enumerate(pair_col_masks):
            if (nm & forbidden) == 0:
                cm |= 1 << j
        compat[i] = cm

    # For each region g and row r:
    # region_masks[g][r][v] = patterns that contribute exactly v stars to region g on row r.
    region_masks = [[[all_patterns, 0, 0] for _ in range(n)] for _ in range(rcount)]
    for r in range(n):
        for p, (c1, c2) in enumerate(pairs):
            bit = 1 << p
            g1 = regions[r][c1]
            g2 = regions[r][c2]
            if g1 == g2:
                region_masks[g1][r][0] ^= bit
                region_masks[g1][r][2] |= bit
            else:
                region_masks[g1][r][0] ^= bit
                region_masks[g2][r][0] ^= bit
                region_masks[g1][r][1] |= bit
                region_masks[g2][r][1] |= bit

    # Small DP table on reachable counts 0..2, encoded as a 3-bit bitset.
    # Example: bitset 0b101 means counts {0, 2} reachable.
    add_reach = [[0] * 8 for _ in range(8)]
    for a in range(8):
        for b in range(8):
            out = 0
            for i in range(3):
                if (a >> i) & 1:
                    for j in range(3 - i):
                        if (b >> j) & 1:
                            out |= 1 << (i + j)
            add_reach[a][b] = out

    def supported_subset(domain_mask, other_domain_mask):
        out = 0
        x = domain_mask
        while x:
            bit = x & -x
            p = bit.bit_length() - 1
            if compat[p] & other_domain_mask:
                out |= bit
            x ^= bit
        return out

    def propagate(state):
        domains = list(state)

        while True:
            changed = False

            for d in domains:
                if d == 0:
                    return None

            # Adjacent-row arc consistency.
            for r in range(n - 1):
                left = domains[r]
                right = domains[r + 1]

                new_left = supported_subset(left, right)
                if new_left != left:
                    if new_left == 0:
                        return None
                    domains[r] = new_left
                    left = new_left
                    changed = True

                new_right = supported_subset(right, left)
                if new_right != right:
                    if new_right == 0:
                        return None
                    domains[r + 1] = new_right
