                    return None

                suffix = [0] * (n + 1)
                suffix[n] = 1
                for r in range(n - 1, -1, -1):
                    suffix[r] = add_reach[options[r]][suffix[r + 1]]

                for r in range(n):
                    others = add_reach[prefix[r]][suffix[r + 1]]
                    nd = domains[r]

                    # If this row contributes 0 to column c, others must contribute 2.
                    if ((others >> 2) & 1) == 0:
