            for g in range(rcount):
                options = [0] * n
                prefix = [0] * (n + 1)
                prefix[0] = 1

                for r in range(n):
                    d = domains[r]
                    masks = region_masks[g][r]
                    opt = 0
                    if d & masks[0]:
                        opt |= 1 << 0
                    if d & masks[1]:
                        opt |= 1 << 1
                    if d & masks[2]:
                        opt |= 1 << 2
                    if opt == 0:
                        return None
                    options[r] = opt
                    prefix[r + 1] = add_reach[prefix[r]][opt]

                if ((prefix[n] >> target) & 1) == 0:
                    return None

                suffix = [0] * (n + 1)
                suffix[n] = 1
                for r in range(n - 1, -1, -1):
                    suffix[r] = add_reach[options[r]][suffix[r + 1]]

                for r in range(n):
                    others = add_reach[prefix[r]][suffix[r + 1]]
                    nd = domains[r]
                    masks = region_masks[g][r]

                    for v in (0, 1, 2):
                        need = target - v
                        if ((others >> need) & 1) == 0:
                            nd &= all_patterns ^ masks[v]

                    if nd != domains[r]:
                        if nd == 0:
