        best_r = None
        best_size = 10**9
        best_score = -1

        for r, d in enumerate(domains):
            sz = d.bit_count()
            if sz <= 1:
                continue
            # Tie-break: rows with more interaction first.
            score = 0
            if r > 0:
                score += domains[r - 1].bit_count()
            if r + 1 < n:
                score += domains[r + 1].bit_count()
            if sz < best_size or (sz == best_size and score > best_score):
                best_size = sz
                best_score = score
                best_r = r
        return best_r

    def ordered_patterns(row, domains):
        d = domains[row]
        items = []
        left = domains[row - 1] if row > 0 else all_patterns
        right = domains[row + 1] if row + 1 < n else all_patterns

        x = d
        while x:
            bit = x & -x
            p = bit.bit_length() - 1
            # Fail-fast: try patterns with fewer neighbor supports first.
            score = 0
            if row > 0:
                score += (compat[p] & left).bit_count()
            if row + 1 < n:
                score += (compat[p] & right).bit_count()
            items.append((score, p))
            x ^= bit

        items.sort()
        return [p for _, p in items]

    @lru_cache(maxsize=None)
    def search(state):
        domains = propagate(state)
        if domains is None:
            return None

        solved = True
        for d in domains:
            if d.bit_count() != 1:
                solved = False
                break
        if solved:
            return domains

        row = choose_row(domains)
        if row is None:
            return None

        for p in ordered_patterns(row, domains):
            new_domains = list(domains)
            new_domains[row] = 1 << p
            result = search(tuple(new_domains))
            if result is not None:
                return result
        return None

    def build_answer(solution):
        answer = [[None for _ in range(n)] for _ in range(n)]
        col_count = [0] * n
        reg_count = [0] * rcount
        stars = []

        for r, d in enumerate(solution):
            if d == 0 or d.bit_count() != 1:
                return None
            p = d.bit_length() - 1
            c1, c2 = pairs[p]
            answer[r][c1] = 'S'
            answer[r][c2] = 'S'
            col_count[c1] += 1
            col_count[c2] += 1
            reg_count[regions[r][c1]] += 1
            reg_count[regions[r][c2]] += 1
            stars.append((r, c1))
            stars.append((r, c2))

        if any(x != 2 for x in col_count):
            return None
        if any(x != 2 for x in reg_count):
            return None

        star_set = set(stars)
        for r, c in stars:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    if (r + dr, c + dc) in star_set:
                        return None

        return answer

    initial_state = tuple([all_patterns] * n)
    solution = search(initial_state)
    if solution is None:
        return "No Solution"

    answer = build_answer(solution)
    if answer is None:
        return "No Solution"

    return repr(answer)


