ACTIVE = 0
CHOSEN = 1
MUST = 2
CANT = 3
SAT = 4


def _bit_iter(mask):
    while mask:
        b = mask & -mask
        yield b.bit_length() - 1
        mask ^= b


class StitchSolver:
    # Model:
    # - One stitch is chosen for each adjacent pair of regions.
    # - A candidate stitch is any orthogonally adjacent cell-pair crossing that region boundary.
    # - Chosen stitches form a matching on cells (no cell used twice).
    # - Row/column clues count used cells.

    def __init__(self, observation):
        self.region = observation["region"]
        self.row_clues = observation["row_stitch_counts"]
        self.col_clues = observation["col_stitch_counts"]
        self.n = len(self.region)
        self.cells = self.n * self.n
        self.total_used = sum(self.row_clues)

        if any(len(row) != self.n for row in self.region):
            raise ValueError("Region grid must be square")
        if len(self.row_clues) != self.n or len(self.col_clues) != self.n:
            raise ValueError("Clue lengths must match grid size")

        self.row_cells = [[r * self.n + c for c in range(self.n)] for r in range(self.n)]
        self.col_cells = [[r * self.n + c for r in range(self.n)] for c in range(self.n)]

        self._build_candidates()
        self.fail_cache = set()

    def _build_candidates(self):
        pair_to_edges = {}
        for r in range(self.n):
            for c in range(self.n):
                u = r * self.n + c
                if c + 1 < self.n and self.region[r][c] != self.region[r][c + 1]:
                    v = u + 1
                    pair = tuple(sorted((self.region[r][c], self.region[r][c + 1])))
                    pair_to_edges.setdefault(pair, []).append((u, v))
                if r + 1 < self.n and self.region[r][c] != self.region[r + 1][c]:
                    v = u + self.n
                    pair = tuple(sorted((self.region[r][c], self.region[r + 1][c])))
                    pair_to_edges.setdefault(pair, []).append((u, v))

        self.group_pairs = sorted(pair_to_edges)
        self.group_count = len(self.group_pairs)

        self.edges = []
        self.edge_u = []
        self.edge_v = []
        self.edge_group = []
        self.edge_cells_bits = []
        self.group_masks = []
        self.cell_masks = [0] * self.cells

        for gid, pair in enumerate(self.group_pairs):
            mask = 0
            for u, v in sorted(pair_to_edges[pair]):
                e = len(self.edges)
                self.edges.append((u, v, gid))
                self.edge_u.append(u)
                self.edge_v.append(v)
                self.edge_group.append(gid)
                cells_bits = (1 << u) | (1 << v)
                self.edge_cells_bits.append(cells_bits)
                mask |= 1 << e
                self.cell_masks[u] |= 1 << e
                self.cell_masks[v] |= 1 << e
            self.group_masks.append(mask)

        self.all_active = (1 << len(self.edges)) - 1

    def _clone_state(self, state):
        return [state[ACTIVE], state[CHOSEN][:], state[MUST], state[CANT], state[SAT]]

    def _force_unused(self, state, cell):
        bit = 1 << cell
        if state[CANT] & bit:
            return True, False
        if state[MUST] & bit:
            return False, False
        state[CANT] |= bit
        state[ACTIVE] &= ~self.cell_masks[cell]
        return True, True

    def _force_used(self, state, cell):
        bit = 1 << cell
        if state[MUST] & bit:
            return True, False
        if state[CANT] & bit:
            return False, False
        state[MUST] |= bit
        if not (state[SAT] & bit) and not (state[ACTIVE] & self.cell_masks[cell]):
            return False, False
        return True, True

    def _choose_edge(self, state, edge):
        gid = self.edge_group[edge]
        chosen = state[CHOSEN][gid]
        if chosen != -1:
            return (chosen == edge), False

        u = self.edge_u[edge]
        v = self.edge_v[edge]
        bu = 1 << u
        bv = 1 << v

        if state[CANT] & (bu | bv):
            return False, False
        if state[SAT] & (bu | bv):
            return False, False

        state[CHOSEN][gid] = edge
        state[MUST] |= bu | bv
        state[SAT] |= bu | bv
        state[ACTIVE] &= ~(self.group_masks[gid] | self.cell_masks[u] | self.cell_masks[v])
        return True, True

    def _restrict_group_to_cell(self, state, gid, cell):
        if state[CHOSEN][gid] != -1:
            edge = state[CHOSEN][gid]
            u = self.edge_u[edge]
            v = self.edge_v[edge]
            return (u == cell or v == cell), False

        current = state[ACTIVE] & self.group_masks[gid]
        keep = current & self.cell_masks[cell]
        if keep == 0:
            return False, False
        if keep == current:
            return True, False
        state[ACTIVE] = (state[ACTIVE] & ~self.group_masks[gid]) | keep
        return True, True

    def _single_support_group(self, mask):
        gid = -1
        for e in _bit_iter(mask):
            g = self.edge_group[e]
            if gid == -1:
                gid = g
            elif gid != g:
