            return None

        key = (
            tuple(group_masks),
            tuple(selected),
            tuple(cell_state),
            tuple(required),
            tuple(row_used),
            tuple(col_used),
        )
        if key in dead:
            return None

        if all(s != -1 for s in selected):
            if row_used == row_clues and col_used == col_clues:
                return selected[:]
            dead.add(key)
            return None

        _, active_incident = recompute_active_incident(group_masks, selected, cell_state)
        if active_incident is None:
            dead.add(key)
            return None

        # First branch on the most constrained required cell.
        best_mask = 0
        best_size = 10**9
        branch_is_cell = False

        for c in range(cell_count):
            if cell_state[c] == 0 and required[c]:
                mask = active_incident[c]
                bc = mask.bit_count()
                if 1 < bc < best_size:
                    best_size = bc
                    best_mask = mask
                    branch_is_cell = True

        # Otherwise branch on the smallest group domain.
        if not branch_is_cell:
            for g in range_g:
                if selected[g] == -1:
                    bc = group_masks[g].bit_count()
                    if 1 < bc < best_size:
                        best_size = bc
                        best_mask = group_masks[g]

        if best_mask == 0:
            dead.add(key)
            return None

        for e in candidate_order(best_mask, required, row_used, col_used):
            ngm = group_masks[:]
            nsel = selected[:]
            nstate = cell_state[:]
            nreq = required[:]
            nru = row_used[:]
            ncu = col_used[:]

            ok, _ = select_edge(e, ngm, nsel, nstate, nreq, nru, ncu)
            if not ok:
                continue

            res = search(ngm, nsel, nstate, nreq, nru, ncu)
            if res is not None:
                return res

        dead.add(key)
        return None

    group_masks = group_masks_init[:]
    selected = [-1] * gcount
    cell_state = [0] * cell_count   # 0 undecided, 1 used, -1 forbidden
    required = [False] * cell_count
    row_used = [0] * n
    col_used = [0] * n

    result = search(group_masks, selected, cell_state, required, row_used, col_used)
    if result is None:
        return "No Solution"

    answer = []
    for e in result:
        u, v = cand_uv[e]
        p1 = pos_of[u]
        p2 = pos_of[v]
        if p2 < p1:
            p1, p2 = p2, p1
        answer.append([p1, p2])
    return repr(answer)


