        if a == b:
            return
        g = get_group(a, b)
        u = r1 * n + c1
        v = r2 * n + c2
        e = len(edges)
        edges.append((u, v, g))
        edge_coords.append(((r1, c1), (r2, c2)))
        groups_edges[g].append(e)

    for r in range(n):
        for c in range(n - 1):
            add_candidate(r, c, r, c + 1)
    for r in range(n - 1):
        for c in range(n):
            add_candidate(r, c, r + 1, c)

    m = n * n
    inc_edges = [[] for _ in range(m)]
    for e, (u, v, _) in enumerate(edges):
        inc_edges[u].append(e)
        inc_edges[v].append(e)

    row_cells = [[r * n + c for c in range(n)] for r in range(n)]
    col_cells = [[r * n + c for r in range(n)] for c in range(n)]

    g_count = len(groups_edges)
    if sum(row_clues) != sum(col_clues):
        return None
    if sum(row_clues) != 2 * g_count:
        return None

    # Quick necessary line feasibility.
    for r in range(n):
        usable = sum(1 for cell in row_cells[r] if inc_edges[cell])
        if row_clues[r] > usable:
            return None
    for c in range(n):
        usable = sum(1 for cell in col_cells[c] if inc_edges[cell])
        if col_clues[c] > usable:
            return None

    return {
        "n": n,
        "m": m,
        "e_count": len(edges),
        "g_count": g_count,
        "edges": edges,
        "edge_coords": edge_coords,
        "groups_edges": groups_edges,
        "inc_edges": inc_edges,
        "row_cells": row_cells,
        "col_cells": col_cells,
        "row_clues": row_clues,
        "col_clues": col_clues,
    }


def add_force_edge(edge_state, forced, e, val):
    cur = edge_state[e]
    if cur != -1:
        return cur == val
    prev = forced.get(e)
    if prev is None:
        forced[e] = val
        return True
    return prev == val


def add_force_cell(y_state, forced, cell, val):
    cur = y_state[cell]
    if cur != -1:
        return cur == val
    prev = forced.get(cell)
    if prev is None:
        forced[cell] = val
        return True
    return prev == val


def propagate(model, edge_state, y_state):
    groups_edges = model["groups_edges"]
    inc_edges = model["inc_edges"]
    row_cells = model["row_cells"]
    col_cells = model["col_cells"]
    row_clues = model["row_clues"]
    col_clues = model["col_clues"]
    edges = model["edges"]
    g_count = model["g_count"]
    m = model["m"]

    while True:
        forced_edges = {}
        forced_cells = {}

        # Rule 1: each touching region-pair gets exactly one stitch.
        group_sel = [-1] * g_count
        for g, eids in enumerate(groups_edges):
            poss = []
            sel = -1
            for e in eids:
                st = edge_state[e]
                if st != 0:
                    poss.append(e)
                    if st == 1:
                        if sel != -1:
                            return None
                        sel = e
            if not poss:
                return None
            group_sel[g] = sel
            if sel != -1:
                for e in poss:
                    if e != sel:
                        if not add_force_edge(edge_state, forced_edges, e, 0):
                            return None
            elif len(poss) == 1:
                if not add_force_edge(edge_state, forced_edges, poss[0], 1):
                    return None

        # Current cell/hole support.
        cell_sel = [-1] * m
        cell_poss = [[] for _ in range(m)]
        for cell, eids in enumerate(inc_edges):
            sel = -1
            poss = []
            for e in eids:
                st = edge_state[e]
                if st != 0:
                    poss.append(e)
                    if st == 1:
                        if sel != -1:
                            return None
                        sel = e
            cell_sel[cell] = sel
            cell_poss[cell] = poss

        # Rule 2 + Rule 3: a used hole belongs to exactly one stitch; unused hole belongs to none.
        for cell in range(m):
            ys = y_state[cell]
            sel = cell_sel[cell]
            poss = cell_poss[cell]

            if ys == 0:
                if sel != -1:
                    return None
                for e in poss:
                    if not add_force_edge(edge_state, forced_edges, e, 0):
                        return None

            if sel != -1:
                if not add_force_cell(y_state, forced_cells, cell, 1):
                    return None
                for e in poss:
                    if e != sel:
                        if not add_force_edge(edge_state, forced_edges, e, 0):
                            return None
            elif not poss:
                if not add_force_cell(y_state, forced_cells, cell, 0):
                    return None
            elif ys == 1 and len(poss) == 1:
                if not add_force_edge(edge_state, forced_edges, poss[0], 1):
                    return None

        # Rule 2/3 immediate edge pruning from already fixed holes.
        for e, (u, v, g) in enumerate(edges):
            if edge_state[e] != -1:
                continue
            if y_state[u] == 0 or y_state[v] == 0:
                if not add_force_edge(edge_state, forced_edges, e, 0):
                    return None
            su = cell_sel[u]
            sv = cell_sel[v]
            if (su != -1 and su != e) or (sv != -1 and sv != e):
                if not add_force_edge(edge_state, forced_edges, e, 0):
                    return None
            sg = group_sel[g]
            if sg != -1 and sg != e:
                if not add_force_edge(edge_state, forced_edges, e, 0):
                    return None

        # Rule 4: row clues on used holes.
        for r, cells in enumerate(row_cells):
            ones = 0
            unknown = []
            for cell in cells:
                ys = y_state[cell]
                if ys == 1:
                    ones += 1
                elif ys == -1:
                    unknown.append(cell)
            clue = row_clues[r]
            if ones > clue or ones + len(unknown) < clue:
                return None
            if ones == clue:
                for cell in unknown:
                    if not add_force_cell(y_state, forced_cells, cell, 0):
                        return None
            elif ones + len(unknown) == clue:
                for cell in unknown:
                    if not add_force_cell(y_state, forced_cells, cell, 1):
                        return None

        # Rule 4: column clues on used holes.
        for c, cells in enumerate(col_cells):
            ones = 0
            unknown = []
            for cell in cells:
                ys = y_state[cell]
                if ys == 1:
                    ones += 1
                elif ys == -1:
                    unknown.append(cell)
            clue = col_clues[c]
            if ones > clue or ones + len(unknown) < clue:
                return None
            if ones == clue:
                for cell in unknown:
                    if not add_force_cell(y_state, forced_cells, cell, 0):
                        return None
            elif ones + len(unknown) == clue:
                for cell in unknown:
                    if not add_force_cell(y_state, forced_cells, cell, 1):
                        return None

        if not forced_edges and not forced_cells:
            break

        changed = False
        for e, val in forced_edges.items():
            if edge_state[e] == -1:
                edge_state[e] = val
                changed = True
            elif edge_state[e] != val:
                return None
        for cell, val in forced_cells.items():
            if y_state[cell] == -1:
                y_state[cell] = val
                changed = True
            elif y_state[cell] != val:
                return None

        if not changed:
            break

    return edge_state, y_state


def analyze(model, edge_state, y_state):
    groups_edges = model["groups_edges"]
    inc_edges = model["inc_edges"]
    row_cells = model["row_cells"]
    col_cells = model["col_cells"]
    row_clues = model["row_clues"]
    col_clues = model["col_clues"]

    group_sel = [-1] * model["g_count"]
    group_poss = [[] for _ in range(model["g_count"])]
    for g, eids in enumerate(groups_edges):
        sel = -1
        poss = []
        for e in eids:
            st = edge_state[e]
            if st != 0:
                poss.append(e)
                if st == 1:
                    sel = e
        group_sel[g] = sel
        group_poss[g] = poss

    cell_sel = [-1] * model["m"]
    cell_poss = [[] for _ in range(model["m"])]
    for cell, eids in enumerate(inc_edges):
        sel = -1
        poss = []
        for e in eids:
            st = edge_state[e]
            if st != 0:
                poss.append(e)
                if st == 1:
                    sel = e
        cell_sel[cell] = sel
        cell_poss[cell] = poss

    row_ones = []
    row_unknown = []
    row_slack = []
    for r, cells in enumerate(row_cells):
        ones = sum(1 for cell in cells if y_state[cell] == 1)
        unknown = sum(1 for cell in cells if y_state[cell] == -1)
        need = row_clues[r] - ones
        row_ones.append(ones)
        row_unknown.append(unknown)
        row_slack.append(unknown - need)

    col_ones = []
    col_unknown = []
    col_slack = []
    for c, cells in enumerate(col_cells):
        ones = sum(1 for cell in cells if y_state[cell] == 1)
        unknown = sum(1 for cell in cells if y_state[cell] == -1)
        need = col_clues[c] - ones
        col_ones.append(ones)
        col_unknown.append(unknown)
        col_slack.append(unknown - need)

    return {
        "group_sel": group_sel,
        "group_poss": group_poss,
        "cell_sel": cell_sel,
        "cell_poss": cell_poss,
        "row_slack": row_slack,
        "col_slack": col_slack,
    }


def validate_solution(model, edge_state):
    n = model["n"]
    g_count = model["g_count"]
    edges = model["edges"]
    row_clues = model["row_clues"]
    col_clues = model["col_clues"]

    selected = [e for e, st in enumerate(edge_state) if st == 1]
    if len(selected) != g_count:
        return None

    group_counts = [0] * g_count
    deg = [0] * model["m"]
    row_used = [0] * n
    col_used = [0] * n

    for e in selected:
        u, v, g = edges[e]
        group_counts[g] += 1
        if group_counts[g] > 1:
            return None

        deg[u] += 1
        deg[v] += 1
        if deg[u] > 1 or deg[v] > 1:
            return None

        ru, cu = divmod(u, n)
        rv, cv = divmod(v, n)
        row_used[ru] += 1
        row_used[rv] += 1
        col_used[cu] += 1
        col_used[cv] += 1

    if any(x != 1 for x in group_counts):
        return None
    if row_used != row_clues:
        return None
    if col_used != col_clues:
        return None

    return selected


def choose_branch(model, edge_state, y_state, info):
    n = model["n"]
    edges = model["edges"]
    group_sel = info["group_sel"]
    group_poss = info["group_poss"]
    cell_sel = info["cell_sel"]
    cell_poss = info["cell_poss"]
    row_slack = info["row_slack"]
    col_slack = info["col_slack"]

    def edge_priority(e):
        u, v, g = edges[e]
        ru, cu = divmod(u, n)
        rv, cv = divmod(v, n)
        return (
            row_slack[ru] + col_slack[cu] + row_slack[rv] + col_slack[cv],
            len(cell_poss[u]) + len(cell_poss[v]),
            len(group_poss[g]),
            e,
        )

    # Prefer a hole already forced to be used but not yet attached.
    best_cell = None
    best_cell_choices = None
    for cell in range(model["m"]):
        if y_state[cell] == 1 and cell_sel[cell] == -1:
            choices = cell_poss[cell]
            if len(choices) > 1:
                if best_cell is None or len(choices) < len(best_cell_choices):
                    best_cell = cell
                    best_cell_choices = choices

    # Otherwise branch on the tightest unsatisfied region-pair.
    best_group = None
    best_group_choices = None
    for g in range(model["g_count"]):
        if group_sel[g] == -1:
            choices = group_poss[g]
            if len(choices) > 1:
                if best_group is None or len(choices) < len(best_group_choices):
                    best_group = g
                    best_group_choices = choices

    if best_cell is not None and (best_group is None or len(best_cell_choices) <= len(best_group_choices)):
        return sorted(best_cell_choices, key=edge_priority)
    if best_group is not None:
        return sorted(best_group_choices, key=edge_priority)
    return []


def search(model, edge_state, y_state, fail_cache):
    state = propagate(model, edge_state, y_state)
    if state is None:
        return None
    edge_state, y_state = state

    key = (tuple(edge_state), tuple(y_state))
    if key in fail_cache:
        return None

    solution = validate_solution(model, edge_state)
    if solution is not None:
        return solution

    info = analyze(model, edge_state, y_state)
    choices = choose_branch(model, edge_state, y_state, info)
    if not choices:
        fail_cache.add(key)
        return None

    for e in choices:
        new_edge_state = edge_state[:]
        new_y_state = y_state[:]
        if new_edge_state[e] == 0:
            continue
        new_edge_state[e] = 1
        result = search(model, new_edge_state, new_y_state, fail_cache)
        if result is not None:
            return result

    fail_cache.add(key)
    return None


def solve(observation):
    model = build_model(observation)
    if model is None:
        return "No Solution"

    edge_state = [-1] * model["e_count"]
    y_state = [-1] * model["m"]

    # Holes with no incident candidate stitch are immediately unused.
    for cell, eids in enumerate(model["inc_edges"]):
        if not eids:
            y_state[cell] = 0

    result = search(model, edge_state, y_state, set())
    if result is None:
        return "No Solution"

    answer = []
    for e in result:
        p1, p2 = model["edge_coords"][e]
        if p2 < p1:
            p1, p2 = p2, p1
        answer.append([p1, p2])
    answer.sort()
    return repr(answer)


