import sys

sys.setrecursionlimit(10000)


def build_model(observation):
    region = observation["region"]
    row_clues = observation["row_stitch_counts"]
    col_clues = observation["col_stitch_counts"]

    n = len(region)
    if n == 0:
        return None
    if len(row_clues) != n or len(col_clues) != n:
        return None
    if any(len(row) != n for row in region):
        return None
    if any((not isinstance(x, int)) or x < 0 or x > n for x in row_clues + col_clues):
        return None

    total_used = sum(row_clues)
    if total_used != sum(col_clues):
        return None
    if total_used % 2 != 0:
        return None

    hole_count = n * n
    row_holes = [[r * n + c for c in range(n)] for r in range(n)]
    col_holes = [[r * n + c for r in range(n)] for c in range(n)]
    hole_row = [h // n for h in range(hole_count)]
    hole_col = [h % n for h in range(hole_count)]

    boundary_options = []
    hole_options = [[] for _ in range(hole_count)]
    option_ends = []
    option_coords = []
    option_boundary = []

    def canonical_edge(p, q):
        return (p, q) if p <= q else (q, p)

    def add_boundary(candidates):
        b = len(boundary_options)
        boundary_options.append([])
        seen = set()

        for p, q in candidates:
            if not (0 <= p[0] < n and 0 <= p[1] < n and 0 <= q[0] < n and 0 <= q[1] < n):
                continue
            p, q = canonical_edge(p, q)
            if p == q:
                continue
            key = (p, q)
            if key in seen:
                continue
            seen.add(key)

            u = p[0] * n + p[1]
            v = q[0] * n + q[1]
            oid = len(option_ends)

            option_ends.append((u, v))
            option_coords.append((p, q))
            option_boundary.append(b)
            boundary_options[b].append(oid)
            hole_options[u].append(oid)
            hole_options[v].append(oid)

        if not boundary_options[b]:
            return False
        return True

    # Model assumption:
    # - Each adjacency between different regions must choose exactly one stitch position.
    # - For left/right-adjacent cells, the stitch is chosen at the top or bottom endpoint.
    # - For up/down-adjacent cells, the stitch is chosen at the left or right endpoint.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                candidates = []
                if r > 0:
                    candidates.append(((r - 1, c), (r - 1, c + 1)))
                if r < n - 1:
                    candidates.append(((r, c), (r, c + 1)))
                if not add_boundary(candidates):
                    return None

    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                candidates = []
                if c > 0:
                    candidates.append(((r, c - 1), (r + 1, c - 1)))
                if c < n - 1:
                    candidates.append(((r, c), (r + 1, c)))
                if not add_boundary(candidates):
                    return None

    # Basic clue feasibility
    for r in range(n):
        possible = sum(1 for h in row_holes[r] if hole_options[h])
        if row_clues[r] > possible:
            return None
    for c in range(n):
        possible = sum(1 for h in col_holes[c] if hole_options[h])
        if col_clues[c] > possible:
            return None

    return {
        "n": n,
        "row_clues": row_clues,
        "col_clues": col_clues,
        "row_holes": row_holes,
        "col_holes": col_holes,
        "hole_row": hole_row,
        "hole_col": hole_col,
        "boundary_options": boundary_options,
        "hole_options": hole_options,
        "option_ends": option_ends,
        "option_coords": option_coords,
        "option_boundary": option_boundary,
    }


class StitchSolver:
    def __init__(self, model):
        self.n = model["n"]
        self.row_clues = model["row_clues"]
        self.col_clues = model["col_clues"]
        self.row_holes = model["row_holes"]
        self.col_holes = model["col_holes"]
        self.hole_row = model["hole_row"]
        self.hole_col = model["hole_col"]
        self.boundary_options = model["boundary_options"]
        self.hole_options = model["hole_options"]
        self.option_ends = model["option_ends"]
        self.option_coords = model["option_coords"]
        self.option_boundary = model["option_boundary"]

        self.hole_count = len(self.hole_options)
        self.option_count = len(self.option_ends)
        self.dead = set()

    def compute_hole_counts(self, opt_state):
        inc_true = [0] * self.hole_count
        inc_unknown = [0] * self.hole_count
        for oid, st in enumerate(opt_state):
            if st == -1 or st == 1:
                u, v = self.option_ends[oid]
                if st == 1:
                    inc_true[u] += 1
                    inc_true[v] += 1
                else:
                    inc_unknown[u] += 1
                    inc_unknown[v] += 1
        return inc_true, inc_unknown

    def hole_status(self, h, hole_force, inc_true, inc_unknown):
        if inc_true[h] > 0 or hole_force[h] == 1:
            return 1
        if hole_force[h] == 0 or (inc_true[h] == 0 and inc_unknown[h] == 0):
            return 0
        return -1

    def propagate(self, opt_state, hole_force):
        while True:
            progress = False

            def assign_option(oid, value):
                nonlocal progress
                cur = opt_state[oid]
                if cur == value:
                    return True
                if cur != -1:
                    return False
                opt_state[oid] = value
                progress = True
                return True

            def force_hole(h, value):
                nonlocal progress
                cur = hole_force[h]
                if cur == value:
                    return True
                if cur != -1:
                    return False
                hole_force[h] = value
                progress = True
                return True

            inc_true, inc_unknown = self.compute_hole_counts(opt_state)

            # Immediate option impossibilities from already-used / forbidden holes.
            for oid, st in enumerate(opt_state):
                if st != -1:
                    continue
                u, v = self.option_ends[oid]
                if hole_force[u] == 0 or hole_force[v] == 0 or inc_true[u] > 0 or inc_true[v] > 0:
                    if not assign_option(oid, 0):
                        return False

            # Exactly-one per boundary.
            for opts in self.boundary_options:
                t = 0
                rem = []
                for oid in opts:
                    st = opt_state[oid]
                    if st == 1:
                        t += 1
                    elif st == -1:
                        rem.append(oid)

                if t > 1:
                    return False
                if t + len(rem) < 1:
                    return False

                if t == 1:
                    for oid in rem:
                        if not assign_option(oid, 0):
                            return False
                elif len(rem) == 1:
                    if not assign_option(rem[0], 1):
                        return False
                elif rem:
                    # Human-style deduction:
                    # if every remaining stitch for this boundary touches the same hole,
                    # that hole must be used.
                    common = set(self.option_ends[rem[0]])
                    for oid in rem[1:]:
                        common &= set(self.option_ends[oid])
                    for h in common:
                        if not force_hole(h, 1):
                            return False

            inc_true, inc_unknown = self.compute_hole_counts(opt_state)

            # Hole constraints: at most one selected stitch per hole.
            for h in range(self.hole_count):
                t = inc_true[h]
                ucnt = inc_unknown[h]

                if t > 1:
                    return False

                if hole_force[h] == 0:
                    if t > 0:
                        return False
                    for oid in self.hole_options[h]:
                        if opt_state[oid] == -1 and not assign_option(oid, 0):
                            return False

                if t == 1:
                    if not force_hole(h, 1):
                        return False
                    for oid in self.hole_options[h]:
                        if opt_state[oid] == -1 and not assign_option(oid, 0):
                            return False
                elif t == 0:
                    if ucnt == 0:
                        if not force_hole(h, 0):
                            return False
                    elif hole_force[h] == 1:
                        rem = [oid for oid in self.hole_options[h] if opt_state[oid] == -1]
                        if not rem:
                            return False
                        if len(rem) == 1:
                            if not assign_option(rem[0], 1):
                                return False

            inc_true, inc_unknown = self.compute_hole_counts(opt_state)

            # Row clue deductions.
            for r in range(self.n):
                used = 0
                free = []
                for h in self.row_holes[r]:
                    st = self.hole_status(h, hole_force, inc_true, inc_unknown)
                    if st == 1:
                        used += 1
                    elif st == -1:
                        free.append(h)

                clue = self.row_clues[r]
                if used > clue or used + len(free) < clue:
                    return False
                if used == clue:
                    for h in free:
                        if not force_hole(h, 0):
                            return False
                elif used + len(free) == clue:
                    for h in free:
                        if not force_hole(h, 1):
                            return False

            # Column clue deductions.
            for c in range(self.n):
                used = 0
                free = []
                for h in self.col_holes[c]:
                    st = self.hole_status(h, hole_force, inc_true, inc_unknown)
                    if st == 1:
                        used += 1
                    elif st == -1:
                        free.append(h)

                clue = self.col_clues[c]
                if used > clue or used + len(free) < clue:
                    return False
                if used == clue:
                    for h in free:
                        if not force_hole(h, 0):
                            return False
                elif used + len(free) == clue:
                    for h in free:
                        if not force_hole(h, 1):
                            return False

            if not progress:
                return True

    def option_order_key(self, oid, opt_state):
        u, v = self.option_ends[oid]
        ru = sum(1 for x in self.hole_options[u] if opt_state[x] == -1)
        rv = sum(1 for x in self.hole_options[v] if opt_state[x] == -1)
        return (ru + rv, max(ru, rv), oid)

    def pick_branch(self, opt_state, hole_force):
        inc_true, inc_unknown = self.compute_hole_counts(opt_state)

        best_kind = None
        best_rank = None
        best_items = None

        # Prefer unresolved exact-one boundary choices.
        for opts in self.boundary_options:
            t = 0
            rem = []
            for oid in opts:
                if opt_state[oid] == 1:
                    t += 1
                elif opt_state[oid] == -1:
                    rem.append(oid)
            if t == 0 and len(rem) > 1:
                rank = (len(rem), 0, tuple(sorted(rem)))
                if best_rank is None or rank < best_rank:
                    best_kind = "boundary"
                    best_rank = rank
                    best_items = sorted(rem, key=lambda oid: self.option_order_key(oid, opt_state))

        # Then forced-used holes with multiple ways to satisfy them.
        for h in range(self.hole_count):
            if hole_force[h] == 1 and inc_true[h] == 0:
                rem = [oid for oid in self.hole_options[h] if opt_state[oid] == -1]
                if len(rem) > 1:
                    rank = (len(rem), 1, h)
                    if best_rank is None or rank < best_rank:
                        best_kind = "hole"
                        best_rank = rank
                        best_items = sorted(rem, key=lambda oid: self.option_order_key(oid, opt_state))

        if best_kind is not None:
            return best_kind, best_items

        # Fallback: branch on one remaining option.
        for oid, st in enumerate(opt_state):
            if st == -1:
                return "option", oid

        return None

    def is_complete_and_valid(self, opt_state, hole_force):
        if any(st == -1 for st in opt_state):
            return False

        inc_true, inc_unknown = self.compute_hole_counts(opt_state)
        if any(inc_unknown):
            return False
        if any(x > 1 for x in inc_true):
            return False

        for opts in self.boundary_options:
            if sum(1 for oid in opts if opt_state[oid] == 1) != 1:
                return False

        for h in range(self.hole_count):
            used = 1 if inc_true[h] == 1 else 0
            if hole_force[h] == 1 and not used:
                return False
            if hole_force[h] == 0 and used:
                return False

        for r in range(self.n):
            used = sum(1 for h in self.row_holes[r] if inc_true[h] == 1)
            if used != self.row_clues[r]:
                return False

        for c in range(self.n):
            used = sum(1 for h in self.col_holes[c] if inc_true[h] == 1)
            if used != self.col_clues[c]:
                return False

        return True

    def extract_answer(self, opt_state):
        ans = []
        seen = set()
        for oid, st in enumerate(opt_state):
            if st == 1:
                p, q = self.option_coords[oid]
                key = (p[0], p[1], q[0], q[1])
                if key not in seen:
                    seen.add(key)
                    ans.append([p, q])
        ans.sort(key=lambda seg: (seg[0][0], seg[0][1], seg[1][0], seg[1][1]))
        return ans

    def dfs(self, opt_state, hole_force):
        key_before = (tuple(opt_state), tuple(hole_force))
        if key_before in self.dead:
            return None

        if not self.propagate(opt_state, hole_force):
            self.dead.add(key_before)
            return None

        key_after = (tuple(opt_state), tuple(hole_force))
        if key_after in self.dead:
            return None

        if self.is_complete_and_valid(opt_state, hole_force):
            return self.extract_answer(opt_state)

        branch = self.pick_branch(opt_state, hole_force)
        if branch is None:
            self.dead.add(key_after)
            return None

        kind, payload = branch

        if kind in ("boundary", "hole"):
            for oid in payload:
                new_opt = opt_state.copy()
                new_hole = hole_force.copy()
                new_opt[oid] = 1
                res = self.dfs(new_opt, new_hole)
                if res is not None:
                    return res
        else:
            oid = payload
            for val in (1, 0):
                new_opt = opt_state.copy()
                new_hole = hole_force.copy()
                new_opt[oid] = val
                res = self.dfs(new_opt, new_hole)
                if res is not None:
                    return res

        self.dead.add(key_after)
        return None


