    model = build_model(observation)
    if model is None:
        return "No Solution"

    solver = StitchSolver(model)
    opt_state = [-1] * solver.option_count
    hole_force = [-1] * solver.hole_count

    result = solver.dfs(opt_state, hole_force)
    if result is None:
        return "No Solution"
    return repr(result)


