class StitchSolver:
    # Flexible model:
    # - region is an R x C cell grid
    # - clue rows/cols define the hole grid size HR x HC
    # - every inter-region cell adjacency must be linked by exactly one stitch
    # - for a horizontal cell-pair boundary, the stitch is chosen at one endpoint
    #   as a horizontal hole-edge, if that endpoint exists inside the hole grid
    # - for a vertical cell-pair boundary, the stitch is chosen at one endpoint
    #   as a vertical hole-edge, if that endpoint exists inside the hole grid
    # This handles both classical "+1 hole grid" instances and same-sized clue grids.

    def __init__(self, observation):
        self.region = [list(row) for row in observation["region"]]
        self.row_clues = list(observation["row_stitch_counts"])
        self.col_clues = list(observation["col_stitch_counts"])

        self.R = len(self.region)
        self.C = len(self.region[0]) if self.R else 0
        self.HR = len(self.row_clues)
        self.HC = len(self.col_clues)

        self.valid = True
        self.invalid_reason = ""

        if self.R == 0 or self.C == 0 or any(len(row) != self.C for row in self.region):
            self.valid = False
            self.invalid_reason = "Malformed region grid"
            return

        self.hole_count = self.HR * self.HC
        self.hole_pos = [(r, c) for r in range(self.HR) for c in range(self.HC)]
        self.row_holes = [[r * self.HC + c for c in range(self.HC)] for r in range(self.HR)]
        self.col_holes = [[r * self.HC + c for r in range(self.HR)] for c in range(self.HC)]

        self.edges = []
        self.edge_index = {}
        self.edge_bounds = []
        self.boundary_opts = []

        self._build_constraints()
        if not self.valid:
            return

        self.edge_count = len(self.edges)
        self.boundary_count = len(self.boundary_opts)

        self.hole_edges = [[] for _ in range(self.hole_count)]
        for eid, (h1, h2) in enumerate(self.edges):
            self.hole_edges[h1].append(eid)
            self.hole_edges[h2].append(eid)

        for clue in self.row_clues:
            if clue < 0 or clue > self.HC:
                self.valid = False
                self.invalid_reason = "Impossible row clue"
                return
        for clue in self.col_clues:
            if clue < 0 or clue > self.HR:
                self.valid = False
                self.invalid_reason = "Impossible column clue"
                return

    def _hole_id(self, r, c):
        return r * self.HC + c

    def _add_edge(self, h1, h2):
        if h1 > h2:
            h1, h2 = h2, h1
        key = (h1, h2)
        eid = self.edge_index.get(key)
        if eid is None:
            eid = len(self.edges)
            self.edge_index[key] = eid
            self.edges.append(key)
            self.edge_bounds.append([])
        return eid

    def _build_constraints(self):
        # Horizontal cell adjacencies
        for r in range(self.R):
            for c in range(self.C - 1):
                if self.region[r][c] == self.region[r][c + 1]:
                    continue
                opts = []
                # top endpoint stitch
                if 0 <= r < self.HR and 0 <= c < self.HC - 1:
                    h1 = self._hole_id(r, c)
                    h2 = self._hole_id(r, c + 1)
                    opts.append(self._add_edge(h1, h2))
                # bottom endpoint stitch
                if 0 <= r + 1 < self.HR and 0 <= c < self.HC - 1:
                    h1 = self._hole_id(r + 1, c)
                    h2 = self._hole_id(r + 1, c + 1)
                    opts.append(self._add_edge(h1, h2))
                opts = list(dict.fromkeys(opts))
                if not opts:
                    self.valid = False
                    self.invalid_reason = "A boundary has no possible stitch endpoints"
                    return
                bid = len(self.boundary_opts)
                self.boundary_opts.append(opts)
                for eid in opts:
                    self.edge_bounds[eid].append(bid)

        # Vertical cell adjacencies
        for r in range(self.R - 1):
            for c in range(self.C):
                if self.region[r][c] == self.region[r + 1][c]:
                    continue
                opts = []
                # left endpoint stitch
                if 0 <= c < self.HC and 0 <= r < self.HR - 1:
                    h1 = self._hole_id(r, c)
                    h2 = self._hole_id(r + 1, c)
                    opts.append(self._add_edge(h1, h2))
                # right endpoint stitch
                if 0 <= c + 1 < self.HC and 0 <= r < self.HR - 1:
                    h1 = self._hole_id(r, c + 1)
                    h2 = self._hole_id(r + 1, c + 1)
                    opts.append(self._add_edge(h1, h2))
                opts = list(dict.fromkeys(opts))
                if not opts:
                    self.valid = False
                    self.invalid_reason = "A boundary has no possible stitch endpoints"
                    return
                bid = len(self.boundary_opts)
                self.boundary_opts.append(opts)
                for eid in opts:
                    self.edge_bounds[eid].append(bid)

    def _new_state(self):
        s = State()
        s.edge_state = [-1] * self.edge_count          # -1 undecided, 0 off, 1 on
        s.hole_on = [-1] * self.hole_count            # chosen edge id, else -1
        s.hole_undec = [len(self.hole_edges[h]) for h in range(self.hole_count)]

        s.row_used = [0] * self.HR
        s.row_possible = [0] * self.HR
        s.col_used = [0] * self.HC
        s.col_possible = [0] * self.HC

        for h in range(self.hole_count):
            if s.hole_undec[h] > 0:
                r, c = self.hole_pos[h]
                s.row_possible[r] += 1
                s.col_possible[c] += 1

        s.b_on = [0] * self.boundary_count
        s.b_avail = [len(opts) for opts in self.boundary_opts]

        s.queue = deque()
        s.dirty_h = [False] * self.hole_count
        s.dirty_r = [False] * self.HR
        s.dirty_c = [False] * self.HC
        s.dirty_b = [False] * self.boundary_count

        for h in range(self.hole_count):
            self._mark_hole(s, h)
        for r in range(self.HR):
            self._mark_row(s, r)
        for c in range(self.HC):
            self._mark_col(s, c)
        for b in range(self.boundary_count):
            self._mark_boundary(s, b)
        return s

    def _copy_state(self, s):
        t = State()
        t.edge_state = s.edge_state[:]
        t.hole_on = s.hole_on[:]
        t.hole_undec = s.hole_undec[:]
        t.row_used = s.row_used[:]
        t.row_possible = s.row_possible[:]
        t.col_used = s.col_used[:]
        t.col_possible = s.col_possible[:]
        t.b_on = s.b_on[:]
        t.b_avail = s.b_avail[:]
        t.queue = deque()
        t.dirty_h = [False] * self.hole_count
        t.dirty_r = [False] * self.HR
        t.dirty_c = [False] * self.HC
        t.dirty_b = [False] * self.boundary_count
        return t

    def _mark_hole(self, s, h):
        if not s.dirty_h[h]:
            s.dirty_h[h] = True
            s.queue.append((0, h))

    def _mark_row(self, s, r):
        if not s.dirty_r[r]:
            s.dirty_r[r] = True
            s.queue.append((1, r))

    def _mark_col(self, s, c):
        if not s.dirty_c[c]:
            s.dirty_c[c] = True
            s.queue.append((2, c))

    def _mark_boundary(self, s, b):
        if not s.dirty_b[b]:
            s.dirty_b[b] = True
            s.queue.append((3, b))

    def _kill_hole(self, s, h):
        if s.hole_on[h] != -1:
            return True
        changed = False
        for eid in self.hole_edges[h]:
            if s.edge_state[eid] == -1:
                changed = True
                if not self._set_edge_off(s, eid):
                    return False
        if changed:
            self._mark_hole(s, h)
        return True

    def _set_edge_off(self, s, eid):
        st = s.edge_state[eid]
        if st == 0:
            return True
        if st == 1:
            return False

        s.edge_state[eid] = 0

        for bid in self.edge_bounds[eid]:
            s.b_avail[bid] -= 1
            self._mark_boundary(s, bid)

        h1, h2 = self.edges[eid]
        for h in (h1, h2):
            if s.hole_on[h] == -1:
                s.hole_undec[h] -= 1
                if s.hole_undec[h] == 0:
                    r, c = self.hole_pos[h]
                    s.row_possible[r] -= 1
                    s.col_possible[c] -= 1
                    self._mark_row(s, r)
                    self._mark_col(s, c)
                self._mark_hole(s, h)

        return True

    def _set_edge_on(self, s, eid):
        st = s.edge_state[eid]
        if st == 1:
            return True
        if st == 0:
            return False

        h1, h2 = self.edges[eid]
        for h in (h1, h2):
            if s.hole_on[h] not in (-1, eid):
                return False
            if s.hole_on[h] == -1:
                r, c = self.hole_pos[h]
                if s.row_used[r] >= self.row_clues[r]:
                    return False
                if s.col_used[c] >= self.col_clues[c]:
                    return False

        s.edge_state[eid] = 1

        for bid in self.edge_bounds[eid]:
            s.b_on[bid] += 1
            self._mark_boundary(s, bid)

        for h in (h1, h2):
            if s.hole_on[h] == -1:
                s.hole_on[h] = eid
                r, c = self.hole_pos[h]
                s.row_used[r] += 1
                s.col_used[c] += 1
                self._mark_row(s, r)
                self._mark_col(s, c)
            self._mark_hole(s, h)

            for oe in self.hole_edges[h]:
                if oe != eid and s.edge_state[oe] == -1:
                    if not self._set_edge_off(s, oe):
                        return False

        return True

    def _process_boundary(self, s, b):
        if s.b_on[b] > 1:
            return False
        if s.b_on[b] == 1:
            for eid in self.boundary_opts[b]:
                if s.edge_state[eid] == -1:
                    if not self._set_edge_off(s, eid):
                        return False
            return True
        if s.b_avail[b] == 0:
            return False
        if s.b_avail[b] == 1:
            for eid in self.boundary_opts[b]:
                if s.edge_state[eid] != 0:
                    return self._set_edge_on(s, eid)
        return True

    def _process_row(self, s, r):
        clue = self.row_clues[r]
        if s.row_used[r] > clue:
            return False
        if s.row_possible[r] < clue:
            return False

        if s.row_used[r] == clue:
            for h in self.row_holes[r]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    if not self._kill_hole(s, h):
                        return False
        elif s.row_possible[r] == clue:
            for h in self.row_holes[r]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    self._mark_hole(s, h)

        return True

    def _process_col(self, s, c):
        clue = self.col_clues[c]
        if s.col_used[c] > clue:
            return False
        if s.col_possible[c] < clue:
            return False

        if s.col_used[c] == clue:
            for h in self.col_holes[c]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    if not self._kill_hole(s, h):
                        return False
        elif s.col_possible[c] == clue:
            for h in self.col_holes[c]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    self._mark_hole(s, h)

        return True

    def _process_hole(self, s, h):
        if s.hole_on[h] != -1:
            return True
        if s.hole_undec[h] == 0:
            return True

        r, c = self.hole_pos[h]

        forbidden = (s.row_used[r] == self.row_clues[r]) or (s.col_used[c] == self.col_clues[c])
        if forbidden:
            return self._kill_hole(s, h)

        required = (s.row_possible[r] == self.row_clues[r]) or (s.col_possible[c] == self.col_clues[c])
        if required:
            rem = [eid for eid in self.hole_edges[h] if s.edge_state[eid] == -1]
            if not rem:
                return False
            if len(rem) == 1:
                return self._set_edge_on(s, rem[0])

        return True

    def _propagate(self, s):
        while s.queue:
            typ, idx = s.queue.popleft()
            if typ == 0:
                s.dirty_h[idx] = False
                if not self._process_hole(s, idx):
                    return False
            elif typ == 1:
                s.dirty_r[idx] = False
                if not self._process_row(s, idx):
                    return False
            elif typ == 2:
                s.dirty_c[idx] = False
                if not self._process_col(s, idx):
                    return False
            else:
                s.dirty_b[idx] = False
                if not self._process_boundary(s, idx):
                    return False
        return True

    def _is_solved(self, s):
        for b in range(self.boundary_count):
            if s.b_on[b] != 1:
                return False
        return s.row_used == self.row_clues and s.col_used == self.col_clues

    def _edge_branch_score(self, s, eid):
        # Higher = more constrained / more promising
        score = 0
        score += 3 * len(self.edge_bounds[eid])
        h1, h2 = self.edges[eid]
        for h in (h1, h2):
            r, c = self.hole_pos[h]
            if s.hole_on[h] != -1:
                score += 100
            if s.row_possible[r] == self.row_clues[r]:
                score += 10
            if s.col_possible[c] == self.col_clues[c]:
                score += 10
            score += max(0, 3 - (self.row_clues[r] - s.row_used[r]))
            score += max(0, 3 - (self.col_clues[c] - s.col_used[c]))
        return score

    def _choose_branch(self, s):
        best_kind = None
        best_item = None
        best_cands = None
        best_key = None

        # Human-like priority:
        # 1) a hole that must be used but still has multiple choices
        for h in range(self.hole_count):
            if s.hole_on[h] != -1 or s.hole_undec[h] <= 1:
                continue
            r, c = self.hole_pos[h]
            required = (s.row_possible[r] == self.row_clues[r]) or (s.col_possible[c] == self.col_clues[c])
            if not required:
                continue
            cands = [eid for eid in self.hole_edges[h] if s.edge_state[eid] == -1]
            key = (len(cands), -max(self._edge_branch_score(s, eid) for eid in cands))
            if best_key is None or key < best_key:
                best_key = key
                best_kind = "hole"
                best_item = h
                best_cands = cands

        if best_kind is not None:
            return best_kind, best_item, best_cands

        # 2) otherwise an unsatisfied boundary with the fewest remaining options
        for b in range(self.boundary_count):
            if s.b_on[b] != 0:
                continue
            cands = [eid for eid in self.boundary_opts[b] if s.edge_state[eid] != 0]
            if len(cands) <= 1:
                continue
            key = (len(cands), -max(self._edge_branch_score(s, eid) for eid in cands))
            if best_key is None or key < best_key:
                best_key = key
                best_kind = "boundary"
                best_item = b
                best_cands = cands

        return best_kind, best_item, best_cands

    def _search(self, s):
        if not self._propagate(s):
            return None
        if self._is_solved(s):
            return s

        kind, item, cands = self._choose_branch(s)
        if kind is None:
            return None

        ordered = sorted(cands, key=lambda eid: self._edge_branch_score(s, eid), reverse=True)
        for eid in ordered:
            t = self._copy_state(s)
            if self._set_edge_on(t, eid):
                ans = self._search(t)
                if ans is not None:
                    return ans
        return None

    def format_solution(self, s):
        ans = []
        for eid, st in enumerate(s.edge_state):
            if st == 1:
                h1, h2 = self.edges[eid]
                r1, c1 = self.hole_pos[h1]
                r2, c2 = self.hole_pos[h2]
                p1 = (r1, c1)
                p2 = (r2, c2)
                if p2 < p1:
                    p1, p2 = p2, p1
                ans.append([p1, p2])
        ans.sort(key=lambda x: (x[0][0], x[0][1], x[1][0], x[1][1]))
        return str(ans)

    def solve(self):
        if not self.valid:
            return "No Solution"
        s = self._new_state()
        res = self._search(s)
        if res is None:
            return "No Solution"
        return self.format_solution(res)


def solve(observation):
    return StitchSolver(observation).solve()


