        changed = False
        for eid in self.hole_edges[h]:
            if s.edge_state[eid] == -1:
                changed = True
                if not self._set_edge_off(s, eid):
                    return False
        if changed:
            self._mark_hole(s, h)
        return True

    def _set_edge_off(self, s, eid):
        st = s.edge_state[eid]
        if st == 0:
            return True
        if st == 1:
            return False

        s.edge_state[eid] = 0

        for bid in self.edge_bounds[eid]:
            s.b_avail[bid] -= 1
            self._mark_boundary(s, bid)

        h1, h2 = self.edges[eid]
        for h in (h1, h2):
            if s.hole_on[h] == -1:
                s.hole_undec[h] -= 1
                if s.hole_undec[h] == 0:
                    r, c = self.hole_pos[h]
                    s.row_possible[r] -= 1
                    s.col_possible[c] -= 1
                    self._mark_row(s, r)
                    self._mark_col(s, c)
                self._mark_hole(s, h)

        return True

    def _set_edge_on(self, s, eid):
        st = s.edge_state[eid]
        if st == 1:
            return True
        if st == 0:
            return False

        h1, h2 = self.edges[eid]
        for h in (h1, h2):
            if s.hole_on[h] not in (-1, eid):
                return False
            if s.hole_on[h] == -1:
                r, c = self.hole_pos[h]
                if s.row_used[r] >= self.row_clues[r]:
                    return False
                if s.col_used[c] >= self.col_clues[c]:
                    return False

        s.edge_state[eid] = 1

        for bid in self.edge_bounds[eid]:
            s.b_on[bid] += 1
            self._mark_boundary(s, bid)

        for h in (h1, h2):
            if s.hole_on[h] == -1:
                s.hole_on[h] = eid
                r, c = self.hole_pos[h]
                s.row_used[r] += 1
                s.col_used[c] += 1
                self._mark_row(s, r)
                self._mark_col(s, c)
            self._mark_hole(s, h)

            for oe in self.hole_edges[h]:
                if oe != eid and s.edge_state[oe] == -1:
                    if not self._set_edge_off(s, oe):
                        return False

        return True

    def _process_boundary(self, s, b):
        if s.b_on[b] > 1:
            return False
        if s.b_on[b] == 1:
            for eid in self.boundary_opts[b]:
                if s.edge_state[eid] == -1:
                    if not self._set_edge_off(s, eid):
                        return False
            return True
        if s.b_avail[b] == 0:
            return False
        if s.b_avail[b] == 1:
            for eid in self.boundary_opts[b]:
                if s.edge_state[eid] != 0:
                    return self._set_edge_on(s, eid)
        return True

    def _process_row(self, s, r):
        clue = self.row_clues[r]
        if s.row_used[r] > clue:
            return False
        if s.row_possible[r] < clue:
            return False

        if s.row_used[r] == clue:
            for h in self.row_holes[r]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    if not self._kill_hole(s, h):
                        return False
        elif s.row_possible[r] == clue:
            for h in self.row_holes[r]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    self._mark_hole(s, h)

        return True

    def _process_col(self, s, c):
        clue = self.col_clues[c]
        if s.col_used[c] > clue:
            return False
        if s.col_possible[c] < clue:
            return False

        if s.col_used[c] == clue:
            for h in self.col_holes[c]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    if not self._kill_hole(s, h):
                        return False
        elif s.col_possible[c] == clue:
            for h in self.col_holes[c]:
                if s.hole_on[h] == -1 and s.hole_undec[h] > 0:
                    self._mark_hole(s, h)

        return True

    def _process_hole(self, s, h):
        if s.hole_on[h] != -1:
            return True
        if s.hole_undec[h] == 0:
            return True

        r, c = self.hole_pos[h]

        forbidden = (s.row_used[r] == self.row_clues[r]) or (s.col_used[c] == self.col_clues[c])
        if forbidden:
            return self._kill_hole(s, h)

        required = (s.row_possible[r] == self.row_clues[r]) or (s.col_possible[c] == self.col_clues[c])
        if required:
            rem = [eid for eid in self.hole_edges[h] if s.edge_state[eid] == -1]
            if not rem:
                return False
            if len(rem) == 1:
                return self._set_edge_on(s, rem[0])

        return True

    def _propagate(self, s):
        while s.queue:
            typ, idx = s.queue.popleft()
            if typ == 0:
                s.dirty_h[idx] = False
                if not self._process_hole(s, idx):
                    return False
            elif typ == 1:
                s.dirty_r[idx] = False
                if not self._process_row(s, idx):
                    return False
            elif typ == 2:
                s.dirty_c[idx] = False
                if not self._process_col(s, idx):
                    return False
            else:
                s.dirty_b[idx] = False
                if not self._process_boundary(s, idx):
                    return False
        return True

    def _is_solved(self, s):
        for b in range(self.boundary_count):
            if s.b_on[b] != 1:
                return False
        return s.row_used == self.row_clues and s.col_used == self.col_clues

    def _edge_branch_score(self, s, eid):
        # Higher = more constrained / more promising
        score = 0
        score += 3 * len(self.edge_bounds[eid])
        h1, h2 = self.edges[eid]
        for h in (h1, h2):
            r, c = self.hole_pos[h]
            if s.hole_on[h] != -1:
                score += 100
            if s.row_possible[r] == self.row_clues[r]:
                score += 10
            if s.col_possible[c] == self.col_clues[c]:
                score += 10
            score += max(0, 3 - (self.row_clues[r] - s.row_used[r]))
            score += max(0, 3 - (self.col_clues[c] - s.col_used[c]))
        return score

    def _choose_branch(self, s):
        best_kind = None
        best_item = None
        best_cands = None
        best_key = None

        # Human-like priority:
        # 1) a hole that must be used but still has multiple choices
        for h in range(self.hole_count):
            if s.hole_on[h] != -1 or s.hole_undec[h] <= 1:
                continue
            r, c = self.hole_pos[h]
            required = (s.row_possible[r] == self.row_clues[r]) or (s.col_possible[c] == self.col_clues[c])
            if not required:
                continue
            cands = [eid for eid in self.hole_edges[h] if s.edge_state[eid] == -1]
            key = (len(cands), -max(self._edge_branch_score(s, eid) for eid in cands))
            if best_key is None or key < best_key:
                best_key = key
                best_kind = "hole"
                best_item = h
                best_cands = cands

        if best_kind is not None:
            return best_kind, best_item, best_cands

        # 2) otherwise an unsatisfied boundary with the fewest remaining options
        for b in range(self.boundary_count):
            if s.b_on[b] != 0:
                continue
            cands = [eid for eid in self.boundary_opts[b] if s.edge_state[eid] != 0]
            if len(cands) <= 1:
                continue
            key = (len(cands), -max(self._edge_branch_score(s, eid) for eid in cands))
            if best_key is None or key < best_key:
                best_key = key
                best_kind = "boundary"
                best_item = b
                best_cands = cands

        return best_kind, best_item, best_cands

    def _search(self, s):
        if not self._propagate(s):
            return None
        if self._is_solved(s):
            return s

        kind, item, cands = self._choose_branch(s)
        if kind is None:
            return None

        ordered = sorted(cands, key=lambda eid: self._edge_branch_score(s, eid), reverse=True)
        for eid in ordered:
            t = self._copy_state(s)
            if self._set_edge_on(t, eid):
                ans = self._search(t)
                if ans is not None:
                    return ans
        return None

    def format_solution(self, s):
        ans = []
        for eid, st in enumerate(s.edge_state):
            if st == 1:
                h1, h2 = self.edges[eid]
                r1, c1 = self.hole_pos[h1]
                r2, c2 = self.hole_pos[h2]
                p1 = (r1, c1)
                p2 = (r2, c2)
                if p2 < p1:
                    p1, p2 = p2, p1
                ans.append([p1, p2])
        ans.sort(key=lambda x: (x[0][0], x[0][1], x[1][0], x[1][1]))
        return str(ans)

    def solve(self):
        if not self.valid:
            return "No Solution"
        s = self._new_state()
        res = self._search(s)
        if res is None:
            return "No Solution"
        return self.format_solution(res)


def solve(observation):
    return StitchSolver(observation).solve()


