# Generalized solver for the stitch puzzle.
# The solver models:
# - a set of hole-to-hole candidate stitches (orthogonally adjacent holes),
# - region-boundary requirements: each boundary must be "covered" by exactly one candidate stitch,
# - hole matching constraint: a hole may be used by at most one stitch,
# - row/column clue counts: exact number of used holes.
#
# Because the public prompt's geometric wording is slightly ambiguous, the solver tries two
# closely related candidate-generation interpretations and returns the first valid solution.

from dataclasses import dataclass
import time


@dataclass
class Model:
    n: int
    row_clues: list
    col_clues: list
    pairs: list
    edge_holes: list
    edge_to_pairs: list
    incident: list
    hole_coords: list
    row_holes: list
    col_holes: list
    total_used_holes: int
    name: str


class State:
    __slots__ = ("edges", "holes")

    def __init__(self, edge_count, hole_count):
        self.edges = [0] * edge_count   # -1 rejected, 0 undecided, 1 selected
        self.holes = [0] * hole_count   # -1 forbidden, 0 unknown, 1 used

    def clone(self):
        s = State.__new__(State)
        s.edges = self.edges[:]
        s.holes = self.holes[:]
        return s


def build_model(observation, mode="across"):
    region = observation["region"]
    row_clues = observation["row_stitch_counts"]
    col_clues = observation["col_stitch_counts"]

    n = len(region)
    if n == 0 or any(len(row) != n for row in region):
        return None
    if len(row_clues) != n or len(col_clues) != n:
        return None
    if sum(row_clues) != sum(col_clues):
        return None
    if sum(row_clues) % 2 != 0:
        return None

    hole_count = n * n
    hole_coords = [(r, c) for r in range(n) for c in range(n)]
    row_holes = [[r * n + c for c in range(n)] for r in range(n)]
    col_holes = [[r * n + c for r in range(n)] for c in range(n)]

    edge_map = {}
    edge_holes = []

    def hole_id(r, c):
        if 0 <= r < n and 0 <= c < n:
            return r * n + c
        return None

    def add_edge(a, b):
        if a is None or b is None:
            return None
        if a > b:
            a, b = b, a
        if a == b:
            return None
        ra, ca = divmod(a, n)
        rb, cb = divmod(b, n)
        if abs(ra - rb) + abs(ca - cb) != 1:
            return None
        key = (a, b)
        if key not in edge_map:
            edge_map[key] = len(edge_holes)
            edge_holes.append(key)
        return edge_map[key]

    pairs = []

    def unique_keep_order(seq):
        seen = set()
        out = []
        for x in seq:
            if x is not None and x not in seen:
                seen.add(x)
                out.append(x)
        return out

    # mode == "across":
    #   left-right cell boundary -> horizontal candidates above/below
    #   up-down cell boundary   -> vertical candidates left/right
    #
    # mode == "along":
    #   left-right cell boundary -> vertical candidates left/right
    #   up-down cell boundary   -> horizontal candidates above/below
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                if mode == "across":
                    cands = [
                        add_edge(hole_id(r, c), hole_id(r, c + 1)),
                        add_edge(hole_id(r + 1, c), hole_id(r + 1, c + 1)),
                    ]
                else:
                    cands = [
                        add_edge(hole_id(r, c), hole_id(r + 1, c)),
                        add_edge(hole_id(r, c + 1), hole_id(r + 1, c + 1)),
                    ]
                cands = unique_keep_order(cands)
                if not cands:
                    return None
                pairs.append(tuple(cands))

    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                if mode == "across":
                    cands = [
                        add_edge(hole_id(r, c), hole_id(r + 1, c)),
                        add_edge(hole_id(r, c + 1), hole_id(r + 1, c + 1)),
                    ]
                else:
                    cands = [
                        add_edge(hole_id(r, c), hole_id(r, c + 1)),
                        add_edge(hole_id(r + 1, c), hole_id(r + 1, c + 1)),
                    ]
                cands = unique_keep_order(cands)
                if not cands:
                    return None
                pairs.append(tuple(cands))

    edge_to_pairs = [[] for _ in range(len(edge_holes))]
    for p, cands in enumerate(pairs):
        for e in cands:
            edge_to_pairs[e].append(p)

    incident = [[] for _ in range(hole_count)]
    for e, (a, b) in enumerate(edge_holes):
        incident[a].append(e)
        incident[b].append(e)

    # Quick capacity checks.
    row_cap = [sum(1 for h in row_holes[r] if incident[h]) for r in range(n)]
    col_cap = [sum(1 for h in col_holes[c] if incident[h]) for c in range(n)]
    for r in range(n):
        if row_clues[r] > row_cap[r]:
            return None
    for c in range(n):
        if col_clues[c] > col_cap[c]:
            return None

    return Model(
        n=n,
        row_clues=row_clues[:],
        col_clues=col_clues[:],
        pairs=pairs,
        edge_holes=edge_holes,
        edge_to_pairs=edge_to_pairs,
        incident=incident,
        hole_coords=hole_coords,
        row_holes=row_holes,
        col_holes=col_holes,
        total_used_holes=sum(row_clues),
        name=mode,
    )


def recompute(model, state):
    pair_sel = [0] * len(model.pairs)
    pair_pos = [0] * len(model.pairs)
    for p, cands in enumerate(model.pairs):
        sel = 0
        pos = 0
        for e in cands:
            st = state.edges[e]
            if st != -1:
                pos += 1
            if st == 1:
                sel += 1
        pair_sel[p] = sel
        pair_pos[p] = pos

    hole_sel = [0] * len(model.hole_coords)
    hole_pos = [0] * len(model.hole_coords)
    for h, inc in enumerate(model.incident):
        sel = 0
        pos = 0
        for e in inc:
            st = state.edges[e]
            if st != -1:
                pos += 1
            if st == 1:
                sel += 1
        hole_sel[h] = sel
        hole_pos[h] = pos

    row_used = [0] * model.n
    row_maybe = [0] * model.n
    col_used = [0] * model.n
    col_maybe = [0] * model.n
    for h, hs in enumerate(state.holes):
        r, c = model.hole_coords[h]
        if hs != -1:
            row_maybe[r] += 1
            col_maybe[c] += 1
        if hs == 1:
            row_used[r] += 1
            col_used[c] += 1

    return {
        "pair_sel": pair_sel,
        "pair_pos": pair_pos,
        "hole_sel": hole_sel,
        "hole_pos": hole_pos,
        "row_used": row_used,
        "row_maybe": row_maybe,
        "col_used": col_used,
        "col_maybe": col_maybe,
