    for c in range(n):
        if col_clues[c] > col_cap[c]:
            return None

    return Model(
        n=n,
        row_clues=row_clues[:],
        col_clues=col_clues[:],
        pairs=pairs,
        edge_holes=edge_holes,
        edge_to_pairs=edge_to_pairs,
        incident=incident,
        hole_coords=hole_coords,
        row_holes=row_holes,
        col_holes=col_holes,
        total_used_holes=sum(row_clues),
