                for c in range(c0, c0 + box_c):
                    idx = base + c
                    cells.append(idx)
                    box_of[idx] = bi
            boxes.append(tuple(cells))
            bi += 1

    row_of = [i // n for i in range(n * n)]
    col_of = [i % n for i in range(n * n)]

    peers = []
    for idx in range(n * n):
