class YinYangSolver:
    # Human-like solver:
    # 1) propagate local 2x2 deductions,
    # 2) propagate region-connectivity deductions,
    # 3) force bridge cells that are required to keep a color connected,
    # 4) do contradiction-based single-cell trials,
    # 5) only then branch on the most constrained cell.

    def __init__(self, data):
        if not isinstance(data, list) or not data or not all(isinstance(row, list) for row in data):
            raise ValueError("Invalid observation")
        self.n = len(data)
        if any(len(row) != self.n for row in data):
            raise ValueError("Grid must be square")

        self.m = self.n * self.n
        self.init = [U] * self.m

        for r in range(self.n):
            for c in range(self.n):
                v = data[r][c]
                if v is None:
                    continue
                if v not in CHAR_TO_VAL:
                    raise ValueError("Invalid clue")
                self.init[self.rc_to_i(r, c)] = CHAR_TO_VAL[v]

        self.nei = [[] for _ in range(self.m)]
        for r in range(self.n):
            for c in range(self.n):
                i = self.rc_to_i(r, c)
                if r > 0:
                    self.nei[i].append(self.rc_to_i(r - 1, c))
                if r + 1 < self.n:
                    self.nei[i].append(self.rc_to_i(r + 1, c))
                if c > 0:
                    self.nei[i].append(self.rc_to_i(r, c - 1))
                if c + 1 < self.n:
                    self.nei[i].append(self.rc_to_i(r, c + 1))

        self.blocks = []
        self.cell_blocks = [[] for _ in range(self.m)]
        for r in range(self.n - 1):
            for c in range(self.n - 1):
                block = (
                    self.rc_to_i(r, c),
                    self.rc_to_i(r, c + 1),
                    self.rc_to_i(r + 1, c),
                    self.rc_to_i(r + 1, c + 1),
