                if v == "B":
                    self.initial[i] = BLACK
                elif v == "W":
                    self.initial[i] = WHITE
                else:
                    raise ValueError("Invalid clue")

        self.failed = set()

    def assign(self, grid, i, val):
        cur = grid[i]
        if cur == val:
            return False
        if cur != UNKNOWN:
            return None
        grid[i] = val
        return True

    def propagate(self, grid):
        while True:
            changed = False

            # Local 2x2 deductions
            for a, b, c, d in self.windows:
                va, vb, vc, vd = grid[a], grid[b], grid[c], grid[d]
                vals = (va, vb, vc, vd)
                cnt_b = (va == BLACK) + (vb == BLACK) + (vc == BLACK) + (vd == BLACK)
                cnt_w = (va == WHITE) + (vb == WHITE) + (vc == WHITE) + (vd == WHITE)

