        return True, changed

    # Human-like connectivity rule:
    # If a fixed-color component has only one unknown frontier and there are multiple
    # fixed components of that color, that frontier cell must be that color.
    def rule_component_frontiers(g):
        changed = False

        for color in (B, W):
            fixed_cells = [i for i, v in enumerate(g) if v == color]
            if len(fixed_cells) <= 1:
                continue

            seen = [False] * m
            frontiers = []

            for start in fixed_cells:
                if seen[start]:
                    continue

                stack = [start]
                seen[start] = True
                frontier = set()

                while stack:
                    x = stack.pop()
                    for y in neighbors[x]:
                        vy = g[y]
                        if vy == color and not seen[y]:
                            seen[y] = True
                            stack.append(y)
                        elif vy == U:
                            frontier.add(y)

                frontiers.append(frontier)

            if len(frontiers) > 1:
                for frontier in frontiers:
                    if not frontier:
                        return False, changed
                    if len(frontier) == 1:
                        cell = next(iter(frontier))
                        res = force(g, cell, color)
                        if res < 0:
                            return False, changed
                        if res > 0:
                            changed = True

        return True, changed

    # Deterministic propagation without speculative recursion.
    def basic_propagate(g):
        while True:
            if not partial_valid(g):
                return False

            changed = False

            ok, ch = rule_no_2x2_forces(g)
            if not ok:
                return False
            changed = changed or ch

            ok, ch = rule_single_possible_cell(g)
            if not ok:
                return False
            changed = changed or ch

            ok, ch = rule_component_frontiers(g)
            if not ok:
                return False
            changed = changed or ch

            if not changed:
                return True

    # Stronger propagation by contradiction probing:
    # try each color for each unknown; if one fails under deterministic logic, force the other.
    def propagate(g, probing=True):
        while True:
            if not basic_propagate(g):
                return False

            if not probing:
                return True

            unknowns = [i for i, v in enumerate(g) if v == U]
            if not unknowns:
                return True

            forced = []
            for i in unknowns:
                possible = []
                for val in (B, W):
                    g2 = g.copy()
                    g2[i] = val
                    if basic_propagate(g2):
                        possible.append(val)

                if not possible:
                    return False
                if len(possible) == 1:
                    forced.append((i, possible[0]))

            if not forced:
                return True

            any_change = False
            for i, val in forced:
                res = force(g, i, val)
                if res < 0:
                    return False
                if res > 0:
                    any_change = True

            if not any_change:
                return True

    def local_score(g, i):
        score = 0

        for nb in neighbors[i]:
            if g[nb] != U:
                score += 3

        for block in cell_blocks[i]:
            cnt_u = 0
            for j in block:
                if g[j] == U:
                    cnt_u += 1
            fixed = 4 - cnt_u
            score += fixed
            if cnt_u == 1:
                score += 4
            elif cnt_u == 2:
                score += 2

        r, c = divmod(i, n)
        if r == 0 or r == n - 1:
            score += 1
        if c == 0 or c == n - 1:
            score += 1

        return score

    # Choose a branch cell by trying a small constrained shortlist and measuring
    # how much full propagation each choice achieves.
    def choose_branch(g):
        unknowns = [i for i, v in enumerate(g) if v == U]
        unknowns.sort(key=lambda i: (-local_score(g, i), i))
        shortlist = unknowns[:min(len(unknowns), 10)]

        best_cell = None
        best_branches = None
        best_key = None

        for i in shortlist:
            branches = []
            counts = []

            for val in (B, W):
                g2 = g.copy()
                g2[i] = val
                if propagate(g2, probing=True):
                    ucnt = g2.count(U)
                    branches.append((ucnt, val, g2))
                    counts.append(ucnt)

            if not branches:
                return i, []

            if len(branches) == 1:
                branches.sort()
                return i, [(branches[0][1], branches[0][2])]

            branches.sort()
            ordered = [(val, g2) for _, val, g2 in branches]
            key = (len(ordered), max(counts), sum(counts), -local_score(g, i), i)

            if best_key is None or key < best_key:
                best_key = key
                best_cell = i
                best_branches = ordered

        if best_branches is None:
            i = unknowns[0]
            fallback = []
            for val in (B, W):
                g2 = g.copy()
                g2[i] = val
                if propagate(g2, probing=True):
                    fallback.append((val, g2))
            return i, fallback

        return best_cell, best_branches

    dead = set()

    def search(g, already_propagated=False):
        if not already_propagated:
            if not propagate(g, probing=True):
                return None

        if U not in g:
            return g if partial_valid(g) else None

        key = tuple(g)
        if key in dead:
            return None

        _, branches = choose_branch(g)
        if not branches:
            dead.add(key)
            return None

        for _, g2 in branches:
            res = search(g2, already_propagated=True)
            if res is not None:
                return res

        dead.add(key)
        return None

    result = search(grid)
    if result is None:
        return "No Solution"

    answer = []
    for r in range(n):
        answer.append(['B' if result[idx(r, c)] == B else 'W' for c in range(n)])
    return answer

if __name__ == "__main__":
    print(solve(OBSERVATION))
